#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define SPI_CE 8
#define MCP3008_CHANNEL 0

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int read_adc(int channel) {
    uint8_t buf[3];
    buf[0] = 1; // Start bit
    buf[1] = (8 + channel) << 4; // Single-ended, channel
    buf[2] = 0; // Don't care

    if (gpio_spi_xfer(SPI_CHANNEL, buf, 3, buf, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Combine the three bytes into a 10-bit value
    return ((buf[1] & 3) << 8) | buf[2];
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SPI_CE, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set CE0 mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SPI_CE, PI_PUD_OFF) != 0) {
        fprintf(stderr, "Failed to set CE0 pull-up/down\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(10, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set MOSI mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(9, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set MISO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(11, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set SCLK mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(10, PI_PUD_OFF) != 0) {
        fprintf(stderr, "Failed to set MOSI pull-up/down\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(9, PI_PUD_OFF) != 0) {
        fprintf(stderr, "Failed to set MISO pull-up/down\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(11, PI_PUD_OFF) != 0) {
        fprintf(stderr, "Failed to set SCLK pull-up/down\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetSPIOptions(SPI_CHANNEL, SPI_SPEED, 0) != 0) {
        fprintf(stderr, "Failed to set SPI options\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

        int adc_value = read_adc(MCP3008_CHANNEL);
        if (adc_value >= 0) {
            printf("%s - ADC Value: %d\n", time_str, adc_value);
        }

        sleep(1);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

