#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define ADS1115_I2C_ADDRESS 0x48
#define ADS1115_I2C_BUS 1
#define ADS1115_CONVERSION_TIME 1000000 // 1 second
#define ADS1115_DATA_RATE 128
#define ADS1115_PGA 0x04 // PGA ±4.096V
#define ADS1115_MUX 0x01 // AIN0 single-ended
#define ADS1115_CONFIG_REG 0x01
#define ADS1115_CONVERSION_REG 0x00
#define ADS1115_SENSITIVITY 0.040 // 40mV/A
#define ADS1115_ZERO_CURRENT_OFFSET 2048 // Mid-supply for 16-bit

volatile int i2cHandle = -1;

void cleanup() {
    if (i2cHandle >= 0) {
        i2cClose(i2cHandle);
    }
    gpioTerminate();
    exit(0);
}

void signalHandler(int signum) {
    cleanup();
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if ((i2cHandle = i2cOpen(ADS1115_I2C_BUS, ADS1115_I2C_ADDRESS, 0)) < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signalHandler);

    while (1) {
        uint16_t config = (ADS1115_PGA << 11) | (ADS1115_MUX << 4) | 0x01; // Single-shot mode
        if (i2cWriteI2CBlockData(i2cHandle, ADS1115_CONFIG_REG, (uint8_t*)&config, 2) < 0) {
            fprintf(stderr, "Failed to write to ADS1115 config register\n");
            cleanup();
            return 1;
        }

        gpioDelay(ADS1115_CONVERSION_TIME);

        uint16_t data[2];
        if (i2cReadI2CBlockData(i2cHandle, ADS1115_CONVERSION_REG, (uint8_t*)data, 2) < 0) {
            fprintf(stderr, "Failed to read from ADS1115 conversion register\n");
            cleanup();
            return 1;
        }

        int16_t rawValue = (data[0] << 8) | data[1];
        double voltage = (rawValue - ADS1115_ZERO_CURRENT_OFFSET) * (ADS1115_SENSITIVITY / 32768.0);
        double current = voltage / ADS1115_SENSITIVITY;

        printf("Current: %.2f A\n", current);

        gpioDelay(500000); // 500ms
    }

    cleanup();
    return 0;
}

