#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define MIN_TEMP 10
#define MAX_TEMP 40
#define ADC_RANGE 1023

void cleanup() {
    gpioTerminate();
    printf("Cleanup complete.\n");
    exit(0);
}

void handle_sigint(int sig) {
    cleanup();
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as input.\n", GPIO_PIN);
        cleanup();
        return 1;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel %d.\n", SPI_CHANNEL);
        cleanup();
        return 1;
    }

    FILE *file = fopen("flame_data.csv", "a");
    if (!file) {
        fprintf(stderr, "Failed to open flame_data.csv for writing.\n");
        spiClose(spi_handle);
        cleanup();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        int flame_detected = gpioRead(GPIO_PIN);
        int adc_value = spiXfer2(spi_handle, 0x68 | (ADC_CHANNEL << 4), 3);
        int adc_result = ((adc_value & 0x3) << 8) | (adc_value >> 4);

        float temperature = MIN_TEMP + (adc_result * (MAX_TEMP - MIN_TEMP)) / ADC_RANGE;

        fprintf(file, "%s,%d,%.1f\n", timestamp, flame_detected, temperature);
        fflush(file);

        sleep(1);
    }

    fclose(file);
    spiClose(spi_handle);
    cleanup();

    return 0;
}

