#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 27
#define I2C_BUS 1
#define I2C_ADDR 0x48
#define ADC_CHANNEL 0
#define ADC_GAIN 4096
#define ADC_SPS 128
#define FLAME_DEBOUNCE_TIME 50
#define LOG_FILE "fire_log.txt"

volatile int running = 1;
volatile int last_flame_time = 0;

void flame_isr(int gpio, int level, uint32_t tick) {
    if (level == PI_LOW && tick - last_flame_time > FLAME_DEBOUNCE_TIME) {
        last_flame_time = tick;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set flame sensor pin mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set buzzer pin mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(FLAME_SENSOR_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set flame sensor pull-up\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetISRFunc(FLAME_SENSOR_PIN, FALLING_EDGE, 0, flame_isr) < 0) {
        fprintf(stderr, "Failed to set flame sensor ISR\n");
        gpioTerminate();
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        gpioTerminate();
        return 1;
    }

    uint16_t config = 0b1000000000000000 | (ADC_CHANNEL << 12) | (ADC_GAIN << 9) | (ADC_SPS << 5);
    if (i2cWriteWordData(i2c_handle, 0x01, config) < 0) {
        fprintf(stderr, "Failed to write ADC configuration\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (running) {
        if (gpioRead(FLAME_SENSOR_PIN) == PI_LOW) {
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            fprintf(log_file, "%sFlame detected!\n", asctime(tm_info));
            fflush(log_file);
        }

        int16_t adc_value = i2cReadWordData(i2c_handle, 0x00);
        if (adc_value >= 0) {
            float voltage = (adc_value * 3.3) / 32767.0;
            float temperature = 20.0 + (voltage - 0.5) * 40.0;
            if (temperature > 60.0) {
                time_t now = time(NULL);
                struct tm *tm_info = localtime(&now);
                fprintf(log_file, "%sTemperature above 60°C: %.1f°C\n", asctime(tm_info), temperature);
                fflush(log_file);
                gpioWrite(BUZZER_PIN, PI_HIGH);
                gpioDelay(2000000);
                gpioWrite(BUZZER_PIN, PI_LOW);
            }
        } else {
            fprintf(stderr, "Failed to read ADC value\n");
        }

        gpioDelay(100000);
    }

    gpioWrite(BUZZER_PIN, PI_LOW);
    gpioSetISRFunc(FLAME_SENSOR_PIN, FALLING_EDGE, 0, NULL);
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

