#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip4"
#define GPIO_FAN 18
#define DEFAULT_SENSITIVITY 100.0
#define DEFAULT_THRESHOLD 5.0
#define SAMPLE_INTERVAL 1

static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *fan_line = NULL;

void cleanup(int signum) {
    if (fan_line) {
        gpiod_line_set_value(fan_line, 0);
        gpiod_line_release(fan_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    exit(signum);
}

int read_adc() {
    uint8_t tx[] = {0x01, 0x80, 0x00};
    uint8_t rx[3];
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(tx),
        .speed_hz = 1000000,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI_IOC_MESSAGE");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

double adc_to_current(int adc_value, double sensitivity) {
    return (adc_value * 3.3 / 1023.0) / (sensitivity / 1000.0);
}

int main(int argc, char *argv[]) {
    double sensitivity = DEFAULT_SENSITIVITY;
    double threshold = DEFAULT_THRESHOLD;
    int opt;
    while ((opt = getopt(argc, argv, "s:t:")) != -1) {
        switch (opt) {
            case 's':
                sensitivity = atof(optarg);
                break;
            case 't':
                threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-s sensitivity] [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        return 1;
    }

    fan_line = gpiod_chip_get_line(gpio_chip, GPIO_FAN);
    if (!fan_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return 1;
    }

    if (gpiod_line_request_output(fan_line, "fan_control", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(fan_line);
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return 1;
    }

    FILE *log_file = fopen("current_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(fan_line);
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return 1;
    }

    while (1) {
        int adc_value = read_adc();
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue;
        }

        double current = adc_to_current(adc_value, sensitivity);
        if (current > threshold) {
            gpiod_line_set_value(fan_line, 1);
        } else {
            gpiod_line_set_value(fan_line, 0);
        }

        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        fprintf(log_file, "%04d-%02d-%02dT%02d:%02d:%02dZ %.2f A\n",
                tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
                tm->tm_hour, tm->tm_min, tm->tm_sec, current);
        fflush(log_file);

        sleep(SAMPLE_INTERVAL);
    }

    fclose(log_file);
    return 0;
}

