#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x28
#define ADS1115_ADDR 0x48
#define ADS1115_REG 0x00
#define ADS1115_CONFIG 0x4000
#define ADS1115_GAIN 0x0000
#define ADS1115_MODE 0x0000
#define ADS1115_DATA_READY 0x0000

#define CO_LOG_FILE "co_log.txt"

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

double ads1115_read(int i2c_handle) {
    uint16_t data;
    if (i2cReadDevice(i2c_handle, ADS1115_REG, (uint8_t*)&data, 2) != 2) {
        fprintf(stderr, "Failed to read from ADS1115\n");
        return -1;
    }
    return (data & 0x0FFF) * 0.1875; // Convert to voltage
}

double co_concentration(double resistance) {
    // Simulated calibration curve for CO concentration in PPM
    // Replace with actual calibration data
    return 1000.0 / (resistance * resistance);
}

void log_co_concentration(double ppm) {
    FILE *log_file = fopen(CO_LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }
    time_t now = time(NULL);
    fprintf(log_file, "%s, %.2f PPM\n", ctime(&now), ppm);
    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int ads1115_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (ads1115_handle < 0) {
        fprintf(stderr, "Failed to open ADS1115 I2C device\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        double voltage = ads1115_read(ads1115_handle);
        if (voltage >= 0) {
            double resistance = 10000.0 / (voltage / 0.0048828125); // Convert voltage to resistance
            double ppm = co_concentration(resistance);
            log_co_concentration(ppm);
        }
        gpioDelay(5000000); // Wait for 5 seconds
    }

    i2cClose(ads1115_handle);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

