#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define MCP3008_CHANNEL 0
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define CSV_FILE "flame_data.csv"

void cleanup(int signum) {
    gpioTerminate();
    printf("Cleanup complete.\n");
    exit(signum);
}

uint16_t read_adc(int channel) {
    uint8_t buf[3] = {1, (8 + channel) << 4, 0};
    uint8_t rbuf[3];
    if (gpioSPIDataRW(SPI_CHANNEL, buf, 3, rbuf) != 3) {
        fprintf(stderr, "SPI read error\n");
        return 0;
    }
    return ((rbuf[1] & 3) << 8) | rbuf[2];
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO4 as input\n");
        gpioTerminate();
        return 1;
    }

    FILE *csv_file = fopen(CSV_FILE, "a");
    if (!csv_file) {
        fprintf(stderr, "Failed to open CSV file for writing\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, cleanup);

    while (1) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        int flame_detected = gpioRead(FLAME_SENSOR_PIN);
        uint16_t adc_value = read_adc(MCP3008_CHANNEL);
        float temperature = 10.0 + (adc_value * 30.0 / 1023.0);

        fprintf(csv_file, "%s,%d,%.1f\n", timestamp, flame_detected, temperature);
        fflush(csv_file);

        sleep(1);
    }

    fclose(csv_file);
    gpioTerminate();
    return 0;
}

