    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *co_log = fopen("co_log.txt", "a");
    if (!co_log) {
        fprintf(stderr, "Failed to open co_log.txt for writing\n");
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *alert_log = fopen("alert_log.txt", "a");
    if (!alert_log) {
        fprintf(stderr, "Failed to open alert_log.txt for writing\n");
        fclose(co_log);
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        uint8_t buffer[4];
        int result = gpioI2CRead(i2c_handle, buffer, 4);
        if (result != 4) {
            fprintf(stderr, "Failed to read from I2C device\n");
            continue;
