        uint16_t ox = (buffer[0] << 8) | buffer[1];
        uint16_t red = (buffer[2] << 8) | buffer[3];

        // Assuming conversion formula for CO level in PPM
        // This is a placeholder and should be replaced with actual conversion
        float co_ppm = (float)ox * 0.001;

        fprintf(co_log, "CO Level: %.2f PPM\n", co_ppm);

        if (co_ppm > CO_ALERT_THRESHOLD) {
            fprintf(alert_log, "CO Alert: %.2f PPM exceeds threshold of %d PPM\n", co_ppm, CO_ALERT_THRESHOLD);
        }

        sleep(READ_INTERVAL);
    }

    fclose(co_log);
    fclose(alert_log);
    gpioI2CClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

