#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR_1 0x48
#define I2C_ADDR_2 0x49
#define SAMPLE_INTERVAL 100000  // 100ms in microseconds
#define MIC_SENSITIVITY -38.0  // dBV/Pa
#define REFERENCE_PRESSURE 20e-6  // Pa

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int read_mic(int i2c_handle, int addr) {
    char buf[2];
    if (i2cReadDevice(i2c_handle, addr, buf, 2) != 2) {
        return -1;
    }
    int16_t raw_data = (buf[0] << 8) | buf[1];
    return raw_data;
}

double convert_to_dB(int16_t raw_data, double sensitivity, double reference_pressure) {
    double voltage = (double)raw_data * 0.0000610352;  // 0.0000610352V per LSB
    double pressure = voltage / (10 * pow(10, sensitivity / 20));
    return 20 * log10(pressure / reference_pressure);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    int i2c_handle_1 = i2cOpen(I2C_BUS, I2C_ADDR_1, 0);
    int i2c_handle_2 = i2cOpen(I2C_BUS, I2C_ADDR_2, 0);

    if (i2c_handle_1 < 0 || i2c_handle_2 < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    FILE *log_file = fopen("audio_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle_1);
        i2cClose(i2c_handle_2);
        gpioTerminate();
        return 1;
    }

    while (running) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        int16_t raw_data_1 = read_mic(i2c_handle_1, I2C_ADDR_1);
        int16_t raw_data_2 = read_mic(i2c_handle_2, I2C_ADDR_2);

        double dB_1 = (raw_data_1 == -1) ? -999.0 : convert_to_dB(raw_data_1, MIC_SENSITIVITY, REFERENCE_PRESSURE);
        double dB_2 = (raw_data_2 == -1) ? -999.0 : convert_to_dB(raw_data_2, MIC_SENSITIVITY, REFERENCE_PRESSURE);

        fprintf(log_file, "%s, %.2f dB, %.2f dB\n", timestamp, dB_1, dB_2);
        fflush(log_file);

        gpioDelay(SAMPLE_INTERVAL);
    }

    fclose(log_file);
    i2cClose(i2c_handle_1);
    i2cClose(i2c_handle_2);
    gpioTerminate();

    return 0;
}

