unsigned int read_adc(int spi_channel, int adc_channel) {
    uint8_t tx[3] = {1, (8 + adc_channel) << 4, 0};
    uint8_t rx[3];
    if (gpioSPIDataRW(spi_channel, tx, rx, 3) != 3) {
