#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define ADC_CHANNEL 0
#define LED_PIN 17
#define SAMPLE_RATE 10
#define BUFFER_SIZE 100
#define THRESHOLD_CURRENT 50.0

volatile int running = 1;
volatile float buffer[BUFFER_SIZE];
volatile int buffer_index = 0;

void signal_handler(int sig) {
    running = 0;
}

float read_adc_value(int bus, int addr, int channel) {
    uint8_t config[3] = {0x01, (channel << 4) | 0x83, 0x00};
    i2cWriteDevice(bus, addr, config, 3);
    uint8_t data[2];
    i2cReadDevice(bus, addr, data, 2);
    return ((data[0] << 8) | data[1]) * 0.1875;
}

float convert_to_current(float adc_value) {
    return (adc_value - 0.5) * 100.0;
}

void log_current(float current) {
    buffer[buffer_index] = current;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

float calculate_average_current() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += buffer[i];
    }
    return sum / BUFFER_SIZE;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(LED_PIN, PI_PUD_OFF) < 0) {
        fprintf(stderr, "Failed to set GPIO%d pull-up/pull-down\n", LED_PIN);
        gpioTerminate();
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (running) {
        float adc_value = read_adc_value(i2c_handle, I2C_ADDR, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue;
        }

        float current = convert_to_current(adc_value);
        log_current(current);

        float average_current = calculate_average_current();
        if (average_current > THRESHOLD_CURRENT) {
            gpioWrite(LED_PIN, PI_HIGH);
        } else {
            gpioWrite(LED_PIN, PI_LOW);
        }

        time_sleep(1.0 / SAMPLE_RATE);
    }

    gpioWrite(LED_PIN, PI_LOW);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

