#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define ID_REG 0x12
#define ATIME_REG 0x01
#define CONTROL_REG 0x0F
#define ENABLE_REG 0x00
#define CLEAR_REG 0x14
#define RED_REG 0x16
#define GREEN_REG 0x18
#define BLUE_REG 0x1A
#define CSV_FILE "color_log.csv"

#define ID_EXPECTED 0x44
#define I2C_RETRIES 3
#define SLEEP_INTERVAL 1000000

volatile int i2c_handle = -1;
volatile FILE *csv_file = NULL;

void signal_handler(int signum) {
    if (i2c_handle != -1) {
        gpioI2CClose(i2c_handle);
    }
    if (csv_file != NULL) {
        fflush(csv_file);
        fclose(csv_file);
    }
    gpioTerminate();
    exit(signum == SIGINT ? 0 : 1);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    i2c_handle = gpioI2COpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return 1;
    }

    uint8_t id;
    int retries = 0;
    while (retries < I2C_RETRIES) {
        int rc = gpioI2CReadReg8(i2c_handle, ID_REG, &id);
        if (rc < 0) {
            fprintf(stderr, "Transient I2C read error, retrying...\n");
            retries++;
            continue;
        }
        if ((id & 0x0F) == ID_EXPECTED) {
            break;
        }
        fprintf(stderr, "Incorrect sensor ID: 0x%02X, retrying...\n", id);
        retries++;
    }
    if (retries == I2C_RETRIES) {
        fprintf(stderr, "Failed to verify sensor ID after %d retries\n", I2C_RETRIES);
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioI2CWriteReg8(i2c_handle, ATIME_REG, 0xFF);
    gpioI2CWriteReg8(i2c_handle, CONTROL_REG, 0x01);
    gpioI2CWriteReg8(i2c_handle, ENABLE_REG, 0x01 | 0x02);

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm *tm = localtime(&ts.tv_sec);
    char header[256];
    snprintf(header, sizeof(header), "%04d-%02d-%02d %02d:%02d:%02d,clear,red,green,blue\n",
             tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
             tm->tm_hour, tm->tm_min, tm->tm_sec);
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Failed to open CSV file\n");
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    fprintf(csv_file, "%s", header);
    fflush(csv_file);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        uint16_t clear, red, green, blue;
        retries = 0;
        while (retries < I2C_RETRIES) {
            int rc = gpioI2CReadReg16(i2c_handle, CLEAR_REG, &clear);
            if (rc < 0) {
                fprintf(stderr, "Transient I2C read error, retrying...\n");
                retries++;
                continue;
            }
            rc = gpioI2CReadReg16(i2c_handle, RED_REG, &red);
            if (rc < 0) {
                fprintf(stderr, "Transient I2C read error, retrying...\n");
                retries++;
                continue;
            }
            rc = gpioI2CReadReg16(i2c_handle, GREEN_REG, &green);
            if (rc < 0) {
                fprintf(stderr, "Transient I2C read error, retrying...\n");
                retries++;
                continue;
            }
            rc = gpioI2CReadReg16(i2c_handle, BLUE_REG, &blue);
            if (rc < 0) {
                fprintf(stderr, "Transient I2C read error, retrying...\n");
                retries++;
                continue;
            }
            break;
        }
        if (retries == I2C_RETRIES) {
            fprintf(stderr, "Failed to read sensor values after %d retries\n", I2C_RETRIES);
            continue;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        tm = localtime(&ts.tv_sec);
        char line[256];
        snprintf(line, sizeof(line), "%04d-%02d-%02d %02d:%02d:%02d,%u,%u,%u,%u\n",
                 tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
                 tm->tm_hour, tm->tm_min, tm->tm_sec,
                 clear, red, green, blue);
        fprintf(csv_file, "%s", line);
        fflush(csv_file);

        nanosleep((struct timespec){SLEEP_INTERVAL / 1000000, (SLEEP_INTERVAL % 1000000) * 1000}, NULL);
    }

    return 0;
}

