#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 500000
#define MCP3008_CHANNEL_0 0x80
#define MCP3008_CHANNEL_1 0xC0
#define ADC_RANGE 1023
#define MAX_MOISTURE 100
#define LOG_FILE "moisture_log.csv"

static int spi_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *cs_line;

void cleanup() {
    if (cs_line) {
        gpiod_line_release(cs_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (access(LOG_FILE, F_OK) == 0) {
        remove(LOG_FILE);
    }
}

void signal_handler(int signum) {
    cleanup();
    exit(signum);
}

int read_adc_channel(int channel) {
    uint8_t tx[3] = {channel, 0x00, 0x00};
    uint8_t rx[3];
    int ret;

    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD);
    if (ret < 0) {
        perror("SPI_IOC_WR_BITS_PER_WORD");
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        return -1;
    }

    ret = write(spi_fd, tx, sizeof(tx));
    if (ret < 0) {
        perror("write");
        return -1;
    }

    ret = read(spi_fd, rx, sizeof(rx));
    if (ret < 0) {
        perror("read");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

int main() {
    struct timespec ts;
    FILE *log_file;
    int moisture1, moisture2;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    cs_line = gpiod_chip_get_line(chip, 8);
    if (!cs_line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(cs_line, "moisture_cs", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("fopen");
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    fprintf(log_file, "Timestamp,Moisture1,Moisture2\n");

    while (1) {
        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld.%09ld,", ts.tv_sec, ts.tv_nsec);

        gpiod_line_set_value(cs_line, 0);
        moisture1 = read_adc_channel(MCP3008_CHANNEL_0);
        gpiod_line_set_value(cs_line, 1);
        moisture2 = read_adc_channel(MCP3008_CHANNEL_1);
        gpiod_line_set_value(cs_line, 0);

        if (moisture1 < 0 || moisture2 < 0) {
            fprintf(stderr, "Error reading ADC values\n");
            continue;
        }

        fprintf(log_file, "%d,%d\n", (moisture1 * MAX_MOISTURE) / ADC_RANGE, (moisture2 * MAX_MOISTURE) / ADC_RANGE);

        sleep(5);
    }

    fclose(log_file);
    cleanup();

    return EXIT_SUCCESS;
}

