    fprintf(log_file, "Timestamp,Moisture1,Moisture2\n");

    while (1) {
        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld.%09ld,", ts.tv_sec, ts.tv_nsec);

        gpiod_line_set_value(cs_line, 0);
        moisture1 = read_adc_channel(MCP3008_CHANNEL_0);
        gpiod_line_set_value(cs_line, 1);
        moisture2 = read_adc_channel(MCP3008_CHANNEL_1);
        gpiod_line_set_value(cs_line, 0);

        if (moisture1 < 0 || moisture2 < 0) {
            fprintf(stderr, "Error reading ADC values\n");
            continue;
        }

        fprintf(log_file, "%d,%d\n", (moisture1 * MAX_MOISTURE) / ADC_RANGE, (moisture2 * MAX_MOISTURE) / ADC_RANGE);

        sleep(5);
    }

    fclose(log_file);
    cleanup();

    return EXIT_SUCCESS;
}
