#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE_CURRENT_SHUTDOWN 17
#define ADC_CHANNEL 0
#define ADC_RESOLUTION 1024
#define VOLTAGE_REF 3.3
#define SENSITIVITY 0.1
#define OFFSET 0.05
#define MAX_SPI_RETRIES 3
#define LOG_FILE "current_log.csv"

static int spi_fd;
static struct gpiod_chip *gpio_chip;
static struct gpiod_line *gpio_line_current_shutdown;
static FILE *log_file;

void log_event(const char *message) {
    if (log_file) {
        fprintf(log_file, "%s,%s\n", message, "Event");
        fflush(log_file);
    }
}

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        if (gpio_line_current_shutdown) {
            gpiod_line_set_value(gpio_line_current_shutdown, 1);
        }
        if (log_file) {
            fclose(log_file);
        }
        if (gpio_chip) {
            gpiod_chip_close(gpio_chip);
        }
        if (spi_fd >= 0) {
            close(spi_fd);
        }
        exit(signum);
    }
}

int read_adc_value() {
    uint8_t tx[3] = {1, (8 + ADC_CHANNEL) << 4, 0};
    uint8_t rx[3];
    int retries = 0;

    while (retries < MAX_SPI_RETRIES) {
        if (write(spi_fd, tx, 3) != 3) {
            perror("Failed to write to SPI device");
            retries++;
            continue;
        }
        if (read(spi_fd, rx, 3) != 3) {
            perror("Failed to read from SPI device");
            retries++;
            continue;
        }
        return ((rx[1] & 3) << 8) | rx[2];
    }
    return -1;
}

double adc_to_current(int adc_value) {
    double voltage = (adc_value * VOLTAGE_REF) / ADC_RESOLUTION;
    return (voltage - OFFSET) / SENSITIVITY;
}

int main() {
    struct timespec ts;
    char timestamp[20];
    int adc_value;
    double current;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize SPI
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE_0) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return EXIT_FAILURE;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &8) < 0) {
        perror("Failed to set bits per word");
        close(spi_fd);
        return EXIT_FAILURE;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &1000000) < 0) {
        perror("Failed to set max speed hz");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        return EXIT_FAILURE;
    }
    gpio_line_current_shutdown = gpiod_chip_get_line(gpio_chip, GPIO_LINE_CURRENT_SHUTDOWN);
    if (!gpio_line_current_shutdown) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(gpio_line_current_shutdown, "current_shutdown", 1) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(gpio_line_current_shutdown);
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,current_in_Amperes\n");
    }

    while (1) {
        if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
            perror("Failed to get current time");
            continue;
        }
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        adc_value = read_adc_value();
        if (adc_value < 0) {
            perror("Failed to read ADC value");
            continue;
        }
        current = adc_to_current(adc_value);

        fprintf(log_file, "%s,%.2f\n", timestamp, current);
        fflush(log_file);

        if (current > 10.0) {
            gpiod_line_set_value(gpio_line_current_shutdown, 0);
            log_event("Overcurrent detected, motor shutdown");
            sleep(1);
            gpiod_line_set_value(gpio_line_current_shutdown, 1);
            log_event("Motor re-enabled");
        }

        sleep(1);
    }

    // Cleanup
    fclose(log_file);
    gpiod_line_release(gpio_line_current_shutdown);
    gpiod_chip_close(gpio_chip);
    close(spi_fd);

    return EXIT_SUCCESS;
}

