#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define REGISTER 0x00
#define FILENAME "pressure_log.csv"

void log_pressure(double pressure_kPa) {
    FILE *file = fopen(FILENAME, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = gmtime(&now);
    fprintf(file, "%04d-%02d-%02dT%02d:%02d:%02dZ,%.2f\n",
            tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
            tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec, pressure_kPa);
    fflush(file);
    fclose(file);
}

void handle_sigint(int sig) {
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    int i2c_handle = gpioI2COpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d, address 0x%02X: %s\n",
                I2C_BUS, I2C_ADDR, gpioStrerror(i2c_handle));
        gpioTerminate();
        return 1;
    }

    FILE *file = fopen(FILENAME, "a");
    if (!file) {
        perror("Failed to open log file");
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fprintf(file, "timestamp,pressure_kPa\n");
    fflush(file);

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    while (1) {
        uint16_t raw_value = gpioI2CReadReg16(i2c_handle, REGISTER);
        if (raw_value == 0xFFFF) {
            fprintf(stderr, "Failed to read register 0x%02X: %s\n",
                    REGISTER, gpioStrerror(raw_value));
            continue;
        }

        double pressure_kPa = (raw_value / 65535.0) * 500.0;
        log_pressure(pressure_kPa);
        sleep(1);
    }

    fclose(file);
    gpioI2CClose(i2c_handle);
    gpioTerminate();
    return 0;
}

