#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define ADS1115_ADDRESS 0x48
#define ADS1115_CONFIG_REG 0x01
#define ADS1115_CONVERSION_REG 0x00
#define ADS1115_GAIN 0x02 // 2/3 gain
#define ADS1115_SPS 0x00 // 128 SPS
#define ADS1115_CHANNEL_0 0x80 // AIN0
#define ADS1115_CHANNEL_1 0xC0 // AIN1
#define ADS1115_CONVERSION_TIME 1000 // 1 ms

#define GPIO_WARNING_LED 17
#define VOLTAGE_REF 6.144
#define VOLTAGE_TO_PRESSURE 80.0 // 400 kPa / 5V
#define VOLTAGE_TO_TEMP 100.0 // 100°C / 1V

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int read_ads1115(int channel) {
    int retries = 3;
    while (retries--) {
        uint16_t config = ADS1115_CHANNEL_0 | ADS1115_GAIN | ADS1115_SPS;
        if (channel == 1) {
            config = ADS1115_CHANNEL_1 | ADS1115_GAIN | ADS1115_SPS;
        }
        if (gpioWriteByte(ADS1115_ADDRESS, config) < 0) {
            perror("Failed to write to ADS1115 config register");
            continue;
        }
        gpioDelay(ADS1115_CONVERSION_TIME);
        uint16_t adc_value = gpioReadByte(ADS1115_ADDRESS);
        if (adc_value < 0) {
            perror("Failed to read from ADS1115 conversion register");
            continue;
        }
        return adc_value;
    }
    fprintf(stderr, "Failed to read from ADS1115 after %d retries\n", retries);
    return -1;
}

double adc_to_voltage(int adc_value) {
    return (double)adc_value * VOLTAGE_REF / 65536.0;
}

double adc_to_pressure(int adc_value) {
    return adc_to_voltage(adc_value) * VOLTAGE_TO_PRESSURE;
}

double adc_to_temperature(int adc_value) {
    return adc_to_voltage(adc_value) * VOLTAGE_TO_TEMP;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_WARNING_LED, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_WARNING_LED);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    while (running) {
        int pressure_adc = read_ads1115(0);
        if (pressure_adc < 0) {
            gpioWrite(GPIO_WARNING_LED, 0);
            continue;
        }

        int temperature_adc = read_ads1115(1);
        if (temperature_adc < 0) {
            gpioWrite(GPIO_WARNING_LED, 0);
            continue;
        }

        double pressure = adc_to_pressure(pressure_adc);
        double temperature = adc_to_temperature(temperature_adc);

        printf("Pressure: %.2f kPa, Temperature: %.2f°C\n", pressure, temperature);

        if (pressure > 105.0) {
            gpioWrite(GPIO_WARNING_LED, 1);
        } else {
            gpioWrite(GPIO_WARNING_LED, 0);
        }

        gpioDelay(1000000); // 1 second
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

