#include <string.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define MCP3008_CHANNEL 0
#define GPIO_SHUTDOWN 27
#define MAX_ADC_VALUE 1023
#define VCC 3.3
#define SENSITIVITY 0.066
#define OVERCURRENT_CURRENT 10.0
#define LOG_FILE "current_log.txt"

void log_event(const char *event) {
    FILE *log = fopen(LOG_FILE, "a");
    if (log == NULL) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    fprintf(log, "%s: %s\n", ctime(&now), event);
    fclose(log);
}

void handle_error(const char *message) {
    perror(message);
    gpioTerminate();
    exit(EXIT_FAILURE);
}

int main() {
    if (gpioInitialise() < 0) {
        handle_error("Failed to initialize pigpio");
    }

    if (gpioSetMode(GPIO_SHUTDOWN, PI_OUTPUT) < 0) {
        handle_error("Failed to set GPIO27 mode");
    }

    if (gpioSetPullUpDown(GPIO_SHUTDOWN, PI_PUD_DOWN) < 0) {
        handle_error("Failed to set GPIO27 pull-up/down");
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        handle_error("Failed to open SPI channel");
    }

    while (1) {
        uint8_t tx[3] = {0x01, 0b10000000 | (MCP3008_CHANNEL << 4), 0x00};
        uint8_t rx[3];
        int result = spiXfer(spi_handle, tx, rx, 3);
        if (result < 0) {
            handle_error("SPI transfer failed");
        }

        int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
        if (adc_value < 0 || adc_value > MAX_ADC_VALUE) {
            handle_error("Invalid ADC value");
        }

        double voltage = (double)adc_value * VCC / MAX_ADC_VALUE;
        double current = (voltage - VCC / 2) / SENSITIVITY;

        if (current > OVERCURRENT_CURRENT) {
            gpioWrite(GPIO_SHUTDOWN, PI_HIGH);
            log_event("OVERCURRENT");
            gpioTerminate();
            exit(EXIT_FAILURE);
        }

        FILE *log = fopen(LOG_FILE, "a");
        if (log == NULL) {
            handle_error("Failed to open log file");
        }
        time_t now = time(NULL);
        fprintf(log, "%s: Current: %.2f A\n", ctime(&now), current);
        fflush(log);
        fclose(log);

        gpioDelay(100000); // 100ms
    }

    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

