#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pigpio.h>
#include <signal.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define ADC_CHANNEL 0
#define ALARM_PIN 4
#define VOLTAGE_REF 3.3
#define ALARM_THRESHOLD 2.5
#define LOG_FILE "co_log.txt"

int spi_handle = -1;
FILE *log_file = NULL;

void log_reading(double voltage) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d,Voltage: %.2f V\n",
            tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
            tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec, voltage);
    fflush(log_file);
}

void handle_sigint(int sig) {
    if (spi_handle != -1) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(ALARM_PIN, PI_OFF);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio library\n");
        return 1;
    }

    if ((spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE)) < 0) {
        fprintf(stderr, "Failed to open SPI channel %d\n", SPI_CHANNEL);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(ALARM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", ALARM_PIN);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    while (1) {
        uint16_t adc_value;
        int result = spiXfer2(spi_handle, (char *)&adc_value, sizeof(adc_value), NULL, 0);
        if (result < 0) {
            fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
            gpioWrite(ALARM_PIN, PI_OFF);
            sleep(1);
            continue;
        }

        double voltage = (adc_value * VOLTAGE_REF) / 1023.0;
        log_reading(voltage);

        if (voltage > ALARM_THRESHOLD) {
            gpioWrite(ALARM_PIN, PI_ON);
        } else {
            gpioWrite(ALARM_PIN, PI_OFF);
        }

        sleep(1);
    }

    return 0;
}

