#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define MCP3008_CHANNEL 0
#define ADC_MIN 0
#define ADC_MAX 1023
#define PPM_MIN 0
#define PPM_MAX 5000
#define LOG_FILE "methane_log.txt"
#define LEAK_THRESHOLD 1000

volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    int spi_handle;
    FILE *log_file;
    struct timespec ts;
    struct tm tm;
    char timestamp[20];
    uint8_t tx[3] = {0x01, 0x80, 0x00};
    uint8_t rx[3];
    int adc_value;
    float ppm;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel %d\n", SPI_CHANNEL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        if (spiXfer(spi_handle, tx, rx, 3) != 3) {
            fprintf(stderr, "SPI transfer failed\n");
        } else {
            adc_value = ((rx[1] & 0x03) << 8) | rx[2];
            ppm = (float)adc_value * (PPM_MAX - PPM_MIN) / (ADC_MAX - ADC_MIN) + PPM_MIN;

            clock_gettime(CLOCK_REALTIME, &ts);
            localtime_r(&ts.tv_sec, &tm);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);

            fprintf(log_file, "%s,%d,%.2f\n", timestamp, adc_value, ppm);
            fflush(log_file);

            if (ppm > LEAK_THRESHOLD) {
                fprintf(stderr, "Methane leak detected! Concentration: %.2f PPM\n", ppm);
            }
        }

        sleep(1);
    }

    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

