#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_OS_SINGLE 0x8000
#define ADS1115_CONFIG_MUX_AIN0_GND 0x4000
#define ADS1115_CONFIG_PGA_4P096 0x0000
#define ADS1115_CONFIG_MODE_SINGLE 0x0000
#define ADS1115_CONFIG_DATA_RATE_8 0x0000
#define ADS1115_CONFIG_COMP_QUE_DISABLE 0x0000
#define ADS1115_CONFIG_COMP_POL_LOW 0x0000
#define ADS1115_CONFIG_COMP_LAT_NONLAT 0x0000
#define ADS1115_CONFIG_COMP_MODE_TRAD 0x0000

#define VOLTAGE_REF 4.096
#define VOLTAGE_OFFSET 0.5
#define VOLTAGE_SENSITIVITY 0.1

#define LOG_FILE "pressure_log.txt"

void log_pressure(double pressure) {
    FILE *log = fopen(LOG_FILE, "a");
    if (log == NULL) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
    fprintf(log, "%s, %.2f kPa\n", timestamp, pressure);
    fclose(log);
}

void handle_sigint(int sig) {
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(2, PI_INPUT) != 0 || gpioSetMode(3, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    int i2c_handle = gpioI2COpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        uint16_t adc_value = gpioI2CReadReg16(i2c_handle, ADS1115_REG_CONVERSION);
        if (adc_value == 0xFFFF) {
            fprintf(stderr, "I2C read error\n");
            continue;
        }

        int16_t adc_result = (adc_value & 0x0FFF) - 0x800;
        double voltage = (adc_result * VOLTAGE_REF) / 2048.0;
        double pressure = (voltage - VOLTAGE_OFFSET) / VOLTAGE_SENSITIVITY;

        if (pressure >= 0 && pressure <= 100) {
            log_pressure(pressure);
        }

        gpioDelay(1000000); // 1 second
    }

    gpioI2CClose(i2c_handle);
    gpioTerminate();
    return 0;
}

