#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000
#define MCP3208_CHANNEL 0
#define TMP36_REF_VOLTAGE 3.3
#define TMP36_MIN_TEMP -40.0
#define TMP36_MAX_TEMP 125.0

static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *cs_line = NULL;
static FILE *log_file = NULL;

void close_resources() {
    if (log_file) {
        fclose(log_file);
    }
    if (cs_line) {
        gpiod_line_release(cs_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
}

void handle_sigint(int sig) {
    close_resources();
    exit(0);
}

int read_adc_value() {
    uint8_t tx[3] = {0x01, (MCP3208_CHANNEL << 4) | 0x8, 0x00};
    uint8_t rx[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI_IOC_MESSAGE");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

double adc_to_voltage(int adc_value) {
    return (adc_value * TMP36_REF_VOLTAGE) / 4095.0;
}

double voltage_to_celsius(double voltage) {
    return (voltage - 0.5) / 0.01;
}

int main() {
    struct timespec ts;
    char timestamp[20];
    int adc_value;
    double voltage, temperature;

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    // Initialize SPI
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI max speed");
        close(spi_fd);
        return 1;
    }

    // Initialize GPIO
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        return 1;
    }

    cs_line = gpiod_chip_get_line(chip, 8);
    if (!cs_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    if (gpiod_line_request_output(cs_line, "MCP3208_CS", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("temperature_log.csv", "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,temperature_celsius\n");
    }

    while (1) {
        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        gpiod_line_set_value(cs_line, 0);
        adc_value = read_adc_value();
        gpiod_line_set_value(cs_line, 1);

        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue;
        }

        voltage = adc_to_voltage(adc_value);
        temperature = voltage_to_celsius(voltage);

        if (temperature < TMP36_MIN_TEMP || temperature > TMP36_MAX_TEMP) {
            fprintf(stderr, "Invalid temperature reading: %.2f°C\n", temperature);
            continue;
        }

        fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
        fflush(log_file);

        sleep(1);
    }

    close_resources();
    return 0;
}

