#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_CE 8
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define ADXL335_X_CHANNEL 0
#define ADXL335_Y_CHANNEL 1
#define ADXL335_Z_CHANNEL 2
#define LOG_FILE "impact_log.txt"
#define IMPACT_THRESHOLD 2.0
#define VOLTAGE_REF 3.3
#define VOLTAGE_0G 1.65
#define SENSITIVITY 0.300

void log_impact(double x, double y, double z) {
    FILE *log = fopen(LOG_FILE, "a");
    if (log == NULL) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    fprintf(log, "%s,%.2f,%.2f,%.2f\n", ctime(&now), x, y, z);
    fclose(log);
}

void log_impact_detected(double x, double y, double z) {
    FILE *log = fopen(LOG_FILE, "a");
    if (log == NULL) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    fprintf(log, "%s,IMPACT DETECTED,%.2f,%.2f,%.2f\n", ctime(&now), x, y, z);
    fclose(log);
}

void handle_sigint(int sig) {
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(SPI_CE, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set SPI_CE mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(SPI_CE, 1) < 0) {
        fprintf(stderr, "Failed to set SPI_CE high\n");
        gpioTerminate();
        return 1;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        uint8_t tx[3] = {1, (ADXL335_X_CHANNEL << 4) | 0x8, 0};
        uint8_t rx[3];
        if (spiXfer(spi_handle, tx, rx, 3) < 0) {
            fprintf(stderr, "Failed to perform SPI transfer\n");
            gpioTerminate();
            return 1;
        }

        uint16_t x_raw = ((rx[1] & 0x0F) << 8) | rx[2];
        uint16_t y_raw = ((rx[1] & 0xF0) << 4) | (rx[2] >> 4);
        uint16_t z_raw = ((rx[1] & 0xF0) << 4) | (rx[2] >> 4);

        double x_voltage = (double)x_raw * VOLTAGE_REF / 1023.0;
        double y_voltage = (double)y_raw * VOLTAGE_REF / 1023.0;
        double z_voltage = (double)z_raw * VOLTAGE_REF / 1023.0;

        double x_accel = (x_voltage - VOLTAGE_0G) / SENSITIVITY;
        double y_accel = (y_voltage - VOLTAGE_0G) / SENSITIVITY;
        double z_accel = (z_voltage - VOLTAGE_0G) / SENSITIVITY;

        double magnitude = sqrt(x_accel * x_accel + y_accel * y_accel + z_accel * z_accel);

        log_impact(x_raw, y_raw, z_raw);

        if (magnitude > IMPACT_THRESHOLD) {
            log_impact_detected(x_raw, y_raw, z_raw);
        }

        gpioDelay(10000); // 100 Hz
    }

    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

