#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_CE 8
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define ADC_MIN 0
#define ADC_MAX 1023
#define VOLTAGE_MIN 0.0
#define VOLTAGE_MAX 3.3
#define FLOW_MIN 0.0
#define FLOW_MAX 5.0
#define LOG_FILE "flow_log.csv"

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int read_adc(int channel) {
    uint16_t adc_value;
    if (gpioReadDevice(SPI_CHANNEL, &adc_value, 2) != 2) {
        fprintf(stderr, "SPI read error\n");
        return -1;
    }
    return (adc_value >> 6) & 0x3FF;
}

double adc_to_flow(int adc_value) {
    double voltage = (double)adc_value * (VOLTAGE_MAX / ADC_MAX);
    double flow_rate = (voltage - VOLTAGE_MIN) * (FLOW_MAX / (VOLTAGE_MAX - VOLTAGE_MIN));
    return flow_rate;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SPI_CE, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set SPI_CE mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SPI_CE, PI_PUD_OFF) != 0) {
        fprintf(stderr, "Failed to set SPI_CE pull-up/pull-down\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SPI_CHANNEL, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set SPI channel mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SPI_CHANNEL, PI_PUD_OFF) != 0) {
        fprintf(stderr, "Failed to set SPI channel pull-up/pull-down\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetSPIMode(SPI_CHANNEL, 0) != 0) {
        fprintf(stderr, "Failed to set SPI mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetSPISpeed(SPI_CHANNEL, SPI_SPEED) != 0) {
        fprintf(stderr, "Failed to set SPI speed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value == -1) {
            continue;
        }

        double flow_rate = adc_to_flow(adc_value);
        if (flow_rate < FLOW_MIN || flow_rate > FLOW_MAX) {
            fprintf(stderr, "Invalid flow rate: %.2f L/min\n", flow_rate);
            continue;
        }

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate);
        fflush(log_file);

        sleep(1);
    }

    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

