#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x67
#define MEASUREMENT_CMD 0x6845
#define DATA_SIZE 6
#define CSV_FILE "environmental_data.csv"

int i2c_fd = -1;
FILE *csv_fd = NULL;

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        if (i2c_fd >= 0) {
            close(i2c_fd);
        }
        if (csv_fd) {
            fclose(csv_fd);
        }
        printf("Shutting down...\n");
        exit(0);
    }
}

void log_error(const char *message) {
    perror(message);
    fprintf(stderr, "Error: %s\n", strerror(errno));
}

int i2c_write(int fd, uint16_t cmd) {
    uint8_t buf[2];
    buf[0] = (cmd >> 8) & 0xFF;
    buf[1] = cmd & 0xFF;
    if (write(fd, buf, 2) != 2) {
        log_error("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t *buf, size_t size) {
    if (read(fd, buf, size) != size) {
        log_error("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

void convert_and_log_data(uint8_t *data) {
    uint16_t pressure_raw = (data[0] << 8) | data[1];
    uint16_t temperature_raw = (data[2] << 8) | data[3];
    uint16_t crc = (data[4] << 8) | data[5];

    // Placeholder for actual calibration formulas
    float pressure = pressure_raw * 0.01; // Example conversion
    float temperature = temperature_raw * 0.01; // Example conversion

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    printf("Timestamp: %s, Pressure: %.2f Pa, Temperature: %.2f °C\n", timestamp, pressure, temperature);

    if (csv_fd) {
        fprintf(csv_fd, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
        fflush(csv_fd);
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        log_error("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    csv_fd = fopen(CSV_FILE, "a");
    if (!csv_fd) {
        log_error("Failed to open CSV file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    fprintf(csv_fd, "Timestamp,Pressure (Pa),Temperature (°C)\n");

    while (1) {
        if (i2c_write(i2c_fd, MEASUREMENT_CMD) < 0) {
            sleep(5);
            continue;
        }

        uint8_t data[DATA_SIZE];
        if (i2c_read(i2c_fd, data, DATA_SIZE) < 0) {
            sleep(5);
            continue;
        }

        convert_and_log_data(data);

        sleep(5);
    }

    if (csv_fd) {
        fclose(csv_fd);
    }
    close(i2c_fd);

    return EXIT_SUCCESS;
}

