#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define SPI_BITS 8
#define SPI_MODE 0
#define MCP3008_ADDRESS 0x40
#define MIC_CHANNEL 0

volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
}

int read_mic(int channel) {
    uint8_t tx[3] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    int result = spi_xfer(SPI_CHANNEL, tx, rx, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }
    return ((rx[1] & 3) << 8) | rx[2];
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <gain>\n", argv[0]);
        return 1;
    }

    int gain = atoi(argv[1]);
    if (gain < 1 || gain > 100) {
        fprintf(stderr, "Gain must be between 1 and 100\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE) < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (running) {
        int mic1 = read_mic(MIC_CHANNEL);
        int mic2 = read_mic(MIC_CHANNEL);

        if (mic1 == -1 || mic2 == -1) {
            continue;
        }

        int noise_cancelled = mic1 - mic2;
        noise_cancelled = noise_cancelled * gain / 100;

        printf("%d\n", noise_cancelled);
        fflush(stdout);
    }

    spiClose(SPI_CHANNEL);
    gpioTerminate();

    return 0;
}

