void log_moisture_reading(int adc_value) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    char *iso_time = ctime(&now);
    iso_time[strlen(iso_time) - 1] = '\0'; // Remove newline character

    fprintf(log_file, "%s,%d\n", iso_time, adc_value);
    fclose(log_file);
}

int read_adc_value(int channel) {
    uint8_t tx[3] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];

    if (gpioSPIDataRW(SPI_CHANNEL, tx, rx, 3) != 3) {
        perror("SPI data read/write failed");
        return -1;
    }

    int adc_value = ((rx[1] & 3) << 8) | rx[2];
    return adc_value;
}

void cleanup() {
    gpioTerminate();
    printf("Cleanup complete\n");
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SPI_CHANNEL, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set SPI channel mode\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetSPISpeed(SPI_CHANNEL, SPI_SPEED) < 0) {
        fprintf(stderr, "Failed to set SPI speed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetSPIBitMode(SPI_CHANNEL, SPI_BITS) < 0) {
        fprintf(stderr, "Failed to set SPI bit mode\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetSPIMode(SPI_CHANNEL, SPI_MODE) < 0) {
        fprintf(stderr, "Failed to set SPI mode\n");
        cleanup();
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        int adc_value = read_adc_value(ADC_CHANNEL);
        if (adc_value >= 0) {
            log_moisture_reading(adc_value);
        }

        sleep(SAMPLE_INTERVAL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

