#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <libgpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define Buzzer_PIN 18
#define LOG_FILE "flame_log.txt"
#define TEMP_FILE "ambient_temp.txt"
#define SAMPLE_INTERVAL 500000
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define SPI_BITS_PER_WORD 8
#define ADC_CHANNEL 0
#define ADC_MAX_VALUE 1023
#define FLAME_THRESHOLD 1.0

struct gpiod_chip *chip;
struct gpiod_line *buzzer_line;
int spi_fd;

void log_error(const char *message) {
    fprintf(stderr, "%s\n", message);
    FILE *log = fopen(LOG_FILE, "a");
    if (log) {
        fprintf(log, "%s\n", message);
        fclose(log);
    }
}

void log_reading(time_t now, int adc_value, double voltage, double compensated_voltage, double temperature, int flame_detected) {
    FILE *log = fopen(LOG_FILE, "a");
    if (log) {
        fprintf(log, "%s,%d,%.3f,%.3f,%.1f,%d\n", ctime(&now), adc_value, voltage, compensated_voltage, temperature, flame_detected);
        fclose(log);
    }
}

int read_adc_value() {
    uint8_t tx[3] = {0x01, (ADC_CHANNEL << 4) | 0x8, 0x00};
    uint8_t rx[3];
    int ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tx);
    if (ret < 0) {
        log_error("SPI transfer failed");
        return -1;
    }
    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

double read_temperature() {
    FILE *temp_file = fopen(TEMP_FILE, "r");
    if (temp_file) {
        double temperature;
        if (fscanf(temp_file, "%lf", &temperature) == 1) {
            fclose(temp_file);
            return temperature;
        }
        fclose(temp_file);
    }
    return 25.0;
}

void handle_sigint(int sig) {
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    exit(0);
}

int main() {
    signal(SIGINT, handle_sigint);

    // Initialize SPI
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        log_error("Failed to open SPI device");
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        log_error("Failed to set SPI mode");
        close(spi_fd);
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        log_error("Failed to set SPI bits per word");
        close(spi_fd);
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        log_error("Failed to set SPI speed");
        close(spi_fd);
        return 1;
    }

    // Initialize GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        log_error("Failed to open GPIO chip");
        close(spi_fd);
        return 1;
    }
    buzzer_line = gpiod_chip_get_line(chip, Buzzer_PIN);
    if (!buzzer_line) {
        log_error("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }
    if (gpiod_line_request_output(buzzer_line, "flame_sensor_buzzer", 0) < 0) {
        log_error("Failed to request GPIO line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    while (1) {
        time_t now = time(NULL);
        int adc_value = read_adc_value();
        if (adc_value < 0) {
            gpiod_line_set_value(buzzer_line, 0);
            continue;
        }
        double voltage = (double)adc_value * 3.3 / ADC_MAX_VALUE;
        double temperature = read_temperature();
        double compensated_voltage = voltage + (temperature - 25.0) * 0.001;
        int flame_detected = compensated_voltage > FLAME_THRESHOLD;

        log_reading(now, adc_value, voltage, compensated_voltage, temperature, flame_detected);
        gpiod_line_set_value(buzzer_line, flame_detected);

        usleep(SAMPLE_INTERVAL);
    }

    return 0;
}

