#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define MCP3008_CHANNEL 0
#define LED_PIN 17
#define WATER_LEVEL_HIGH 75
#define WATER_LEVEL_LOW 70
#define JSON_FILE "water_levels.json"

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        gpioTerminate();
        return 1;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel %d\n", SPI_CHANNEL);
        gpioTerminate();
        return 1;
    }

    FILE *json_file = fopen(JSON_FILE, "a");
    if (!json_file) {
        fprintf(stderr, "Failed to open JSON file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    if (fseek(json_file, 0, SEEK_END) != 0) {
        fprintf(stderr, "Failed to seek to end of JSON file\n");
        fclose(json_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    if (ftell(json_file) == 0) {
        fprintf(json_file, "[\n");
    } else {
        fseek(json_file, -1, SEEK_END);
        fprintf(json_file, ",\n");
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        uint8_t tx[3] = {0x01, 0x80 | (MCP3008_CHANNEL << 4), 0x00};
        uint8_t rx[3];
        int result = spiXfer(spi_handle, tx, rx, 3);
        if (result < 0) {
            fprintf(stderr, "SPI transfer error: %s\n", pigpio_error(result));
            gpioDelay(100000); // 100ms
            continue;
        }

        int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
        int water_level = (adc_value * 100) / 1023;

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.%03ldZ", tm_info);

        fprintf(json_file, "{\"timestamp\": \"%s\", \"water_level\": %d}\n", timestamp, water_level);
        fflush(json_file);

        if (water_level > WATER_LEVEL_HIGH) {
            gpioWrite(LED_PIN, PI_HIGH);
        } else if (water_level < WATER_LEVEL_LOW) {
            gpioWrite(LED_PIN, PI_LOW);
        }

        gpioDelay(5000000); // 5 seconds
    }

    if (fseek(json_file, -1, SEEK_END) != 0) {
        fprintf(stderr, "Failed to seek to end of JSON file\n");
    } else {
        fprintf(json_file, "\n]");
    }

    fclose(json_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

