#define MOISTURE_THRESHOLD 30
#define LOG_INTERVAL 60

#define EMAIL_RECIPIENT "recipient@example.com"
#define MSMTP_CONFIG "/etc/msmtprc"

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int read_adc(int spi_channel, int adc_channel) {
    uint8_t buf[3] = {1, (8 + adc_channel) << 4, 0};
    uint8_t rbuf[3];
    int rc = spiXfer2(spi_channel, buf, rbuf, 3);
    if (rc < 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", rc);
        return -1;
    }
    return ((rbuf[1] & 3) << 8) + rbuf[2];
}

void log_moisture(int moisture_percent) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    FILE *log_file = fopen("plant_data.txt", "a");
    if (log_file) {
        fprintf(log_file, "%s, %d\n", timestamp, moisture_percent);
        fclose(log_file);
    } else {
        fprintf(stderr, "Failed to open log file\n");
    }
}

void send_email(int moisture_percent) {
    char email_body[100];
    snprintf(email_body, sizeof(email_body), "Moisture level is critically low: %d%%", moisture_percent);
    FILE *email_pipe = popen("msmtp -C /etc/msmtprc recipient@example.com", "w");
    if (email_pipe) {
        fprintf(email_pipe, "To: %s\n", EMAIL_RECIPIENT);
        fprintf(email_pipe, "Subject: Plant Moisture Alert\n\n");
        fprintf(email_pipe, "%s\n", email_body);
        pclose(email_pipe);
    } else {
        fprintf(stderr, "Failed to open email pipe\n");
    }
}

