#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define ADC_CHANNEL 0
#define LOG_FILE "soil_moisture.log"

volatile int running = 1;

void signal_handler(int signum) {
    running = 0;
}

int read_adc(int channel) {
    uint16_t adc_value;
    if (gpioReadDevice(SPI_CHANNEL, &adc_value, sizeof(adc_value)) != sizeof(adc_value)) {
        fprintf(stderr, "SPI read error\n");
        return -1;
    }
    return (adc_value >> 6) & 0x3FF; // 10-bit value
}

void log_moisture(int adc_value) {
    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    int moisture_percentage = (adc_value * 100) / 1023;
    fprintf(log, "%s, %d, %d\n", timestamp, adc_value, moisture_percentage);
    fclose(log);
}

