#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000
#define SPI_CHANNEL 0
#define SPI_TRANSFER_SIZE 3
#define DRY_ADC 700
#define WET_ADC 300

static struct gpiod_chip *chip;
static int spi_fd;

void close_spi() {
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

void close_chip() {
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

void handle_sigint(int sig) {
    close_spi();
    close_chip();
    exit(0);
}

uint16_t read_adc() {
    uint8_t tx[SPI_TRANSFER_SIZE] = {1, (SPI_CHANNEL << 4) | 8, 0};
    uint8_t rx[SPI_TRANSFER_SIZE];
    ssize_t bytes_read;

    bytes_read = read(spi_fd, rx, SPI_TRANSFER_SIZE);
    if (bytes_read != SPI_TRANSFER_SIZE) {
        perror("Failed to read from SPI device");
        return 0;
    }

    return ((rx[1] & 3) << 8) | rx[2];
}

int main() {
    struct gpiod_line_request req;
    struct sigaction sa;

    // Set up signal handler for graceful exit
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    // Set SPI mode, bits per word, and speed
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close_spi();
        return EXIT_FAILURE;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set bits per word");
        close_spi();
        return EXIT_FAILURE;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close_spi();
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close_spi();
        return EXIT_FAILURE;
    }

    while (1) {
        uint16_t adc_value = read_adc();
        if (adc_value == 0) {
            fprintf(stderr, "Failed to read valid ADC value\n");
            continue;
        }

        int moisture_percentage = (adc_value - DRY_ADC) * 100 / (WET_ADC - DRY_ADC);
        if (moisture_percentage < 0) moisture_percentage = 0;
        if (moisture_percentage > 100) moisture_percentage = 100;

        printf("ADC Value: %u, Moisture: %d%%\n", adc_value, moisture_percentage);

        sleep(5);
    }

    close_spi();
    close_chip();
    return EXIT_SUCCESS;
}

