#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define SPI_CE 8
#define ADC_MIN 0
#define ADC_MAX 1023
#define VOLTAGE_MIN 0.5
#define VOLTAGE_MAX 4.5
#define PRESSURE_MIN 10
#define PRESSURE_MAX 150

void log_reading(double voltage, double pressure) {
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
    printf("%s: Voltage: %.2fV, Pressure: %.2fkPa\n", timestamp, voltage, pressure);
}

double adc_to_voltage(int adc_value) {
    return (double)adc_value * (VOLTAGE_MAX - VOLTAGE_MIN) / ADC_MAX + VOLTAGE_MIN;
}

double voltage_to_pressure(double voltage) {
    return (voltage - VOLTAGE_MIN) * (PRESSURE_MAX - PRESSURE_MIN) / (VOLTAGE_MAX - VOLTAGE_MIN) + PRESSURE_MIN;
}

void cleanup() {
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

void handle_signal(int sig) {
    cleanup();
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (gpioSetMode(SPI_CE, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set SPI_CE mode\n");
        cleanup();
    }

    if (gpioSetPullUpDown(SPI_CE, PI_PUD_OFF) < 0) {
        fprintf(stderr, "Failed to set SPI_CE pull-up/down\n");
        cleanup();
    }

    if (gpioSetMode(8, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO8 mode\n");
        cleanup();
    }

    if (gpioSetPullUpDown(8, PI_PUD_OFF) < 0) {
        fprintf(stderr, "Failed to set GPIO8 pull-up/down\n");
        cleanup();
    }

    if (gpioSetMode(9, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO9 mode\n");
        cleanup();
    }

    if (gpioSetMode(10, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO10 mode\n");
        cleanup();
    }

    if (gpioSetPullUpDown(10, PI_PUD_OFF) < 0) {
        fprintf(stderr, "Failed to set GPIO10 pull-up/down\n");
        cleanup();
    }

    if (gpioSetMode(11, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO11 mode\n");
        cleanup();
    }

    if (gpioSetPullUpDown(11, PI_PUD_OFF) < 0) {
        fprintf(stderr, "Failed to set GPIO11 pull-up/down\n");
        cleanup();
    }

    while (1) {
        gpioWrite(SPI_CE, 0);
        gpioDelay(1);
        gpioWrite(SPI_CE, 1);
        gpioDelay(1);

        int adc_value = gpioRead(9);
        if (adc_value < ADC_MIN || adc_value > ADC_MAX) {
            fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
            cleanup();
        }

        double voltage = adc_to_voltage(adc_value);
        if (voltage < VOLTAGE_MIN || voltage > VOLTAGE_MAX) {
            fprintf(stderr, "Invalid voltage: %.2fV\n", voltage);
            cleanup();
        }

        double pressure = voltage_to_pressure(voltage);
        log_reading(voltage, pressure);

        gpioDelay(1000000); // 1 second
    }

    cleanup();
    return EXIT_SUCCESS;
}

