#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define CS_LINE "gpiochip0::line8"
#define VREF 3.3
#define SAMPLE_INTERVAL 1

static int spi_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *cs_line;

void close_resources() {
    if (cs_line) {
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
}

void handle_signal(int signum) {
    close_resources();
    exit(signum);
}

uint16_t read_adc_channel(int channel) {
    uint8_t tx[3] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = 1000000,
        .delay_usecs = 0,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI_IOC_MESSAGE");
        return 0;
    }

    return ((rx[1] & 3) << 8) | rx[2];
}

int main() {
    struct timespec ts;
    FILE *csv_file;

    // Open SPI device
    if ((spi_fd = open(SPI_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    // Initialize GPIO chip and line for chip select
    if (!(chip = gpiod_chip_open_by_name("gpiochip0"))) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        return EXIT_FAILURE;
    }
    if (!(cs_line = gpiod_chip_get_line(chip, 8))) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(cs_line, "ADC_CS", 0) < 0) {
        perror("Failed to request GPIO line for output");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Open CSV file
    if ((csv_file = fopen("environmental_data.csv", "w")) == NULL) {
        perror("Failed to open CSV file");
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }
    fprintf(csv_file, "Timestamp,Channel0,Channel1,Channel2,Channel3\n");

    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(csv_file, "%ld.%09ld,", ts.tv_sec, ts.tv_nsec);

        for (int channel = 0; channel < 4; channel++) {
            gpiod_line_set_value(cs_line, 0);
            uint16_t adc_value = read_adc_channel(channel);
            gpiod_line_set_value(cs_line, 1);
            fprintf(csv_file, "%d,", adc_value);
        }

        fprintf(csv_file, "\n");
        fflush(csv_file);
        sleep(SAMPLE_INTERVAL);
    }

    // Clean up
    fclose(csv_file);
    close_resources();
    return EXIT_SUCCESS;
}

