This C program for a Raspberry Pi 5 uses the libgpiod library for GPIO control and the standard Linux spidev for SPI communication to continuously sample voltage readings from four analog sensors connected to an MCP3008 ADC via the SPI0 interface. The program configures SPI0 (CE0 on GPIO8) at 1 MHz, Mode 0, and reads channels 0 through 3 in single-ended mode using a VREF of 3.3V. It samples once per second and logs timestamped voltage values to a CSV file named `environmental_data.csv`. The program includes robust error handling for SPI communication failures and ensures clean resource release, closing the file, the SPI device, and the libgpiod lines, on all exit paths via SIGINT/SIGTERM signal handling.

code:
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_CE0 0
#define SPI_MOSI 10
#define SPI_MISO 9
#define SPI_SCLK 11
#define PUMP_PIN 17
#define LOW_THRESHOLD 300
#define HIGH_THRESHOLD 600
#define BUFFER_SIZE 20

typedef struct {
    time_t timestamp;
    int moisture_level;
    int pump_state;
} LogEntry;

LogEntry logBuffer[BUFFER_SIZE];
int logIndex = 0;

void logEntry(int moisture_level, int pump_state) {
    logBuffer[logIndex].timestamp = time(NULL);
    logBuffer[logIndex].moisture_level = moisture_level;
    logBuffer[logIndex].pump_state = pump_state;
    logIndex = (logIndex + 1) % BUFFER_SIZE;
}

void printLogBuffer() {
    for (int i = 0; i < BUFFER_SIZE; i++) {
        printf("Timestamp: %s, Moisture: %d, Pump: %s\n",
               ctime(&logBuffer[i].timestamp), logBuffer[i].moisture_level,
               logBuffer[i].pump_state ? "ON" : "OFF");
    }
}

void spiTransfer(int *data) {
    int status = spiXfer(SPI_CHANNEL, data, 3);
    if (status != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", status);
        exit(EXIT_FAILURE);
    }
}

int readMoistureLevel() {
    int data[3] = {0x68, 0x00, 0x00}; // Start bit, single-ended, channel 0
    spiTransfer(data);
    return ((data[1] & 0x03) << 8) | data[2];
}

void controlPump(int state) {
    gpioWrite(PUMP_PIN, state);
    logEntry(readMoistureLevel(), state);
}

void timerHandler(int timer) {
    static int lastPumpState = 0;
    int moistureLevel = readMoistureLevel();
    int currentPumpState = (moistureLevel < LOW_THRESHOLD) ? 1 : (moistureLevel > HIGH_THRESHOLD) ? 0 : lastPumpState;
    if (currentPumpState != lastPumpState) {
        controlPump(currentPumpState);
        lastPumpState = currentPumpState;
    }
    printLogBuffer();
}

void cleanup() {
    gpioTerminate();
    spiClose(SPI_CHANNEL);
}

void signalHandler(int sig) {
    cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PUMP_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set pump pin mode\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(PUMP_PIN, PI_PUD_OFF) < 0) {
        fprintf(stderr, "Failed to set pump pin pull-up/pull-down\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE) < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        cleanup();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    int timer = gpioSetTimerFunc(5000, timerHandler, 0);
    if (timer < 0) {
        fprintf(stderr, "Failed to set timer\n");
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        // Main loop does nothing, timer handles the sampling
    }

    return EXIT_SUCCESS;
}

