#define MODE_CONFIG_REG 0x06
#define SPO2_CONFIG_REG 0x08
#define LED1_PA_REG 0x09
#define LED2_PA_REG 0x0A
#define FIFO_DATA_REG 0x07
#define FIFO_SIZE 16

#define PART_ID_EXPECTED 0x15
#define SPO2_MODE 0x40
#define SPO2_CONFIG 0x27
#define LED_PA 0x24

#define MIN_SPO2 95
#define MAX_HR 100

void log_event(const char *event) {
    FILE *log = fopen("health_log.txt", "a");
    if (log) {
        time_t now = time(NULL);
        fprintf(log, "%s: %s\n", ctime(&now), event);
        fclose(log);
    }
}

void cleanup(int sig) {
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
