    int i2c_handle = gpioI2COpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return 1;
    }

    uint8_t part_id;
    if (gpioI2CReadReg8(i2c_handle, PART_ID_REG, &part_id) < 0) {
        fprintf(stderr, "Failed to read Part ID register\n");
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (part_id != PART_ID_EXPECTED) {
        fprintf(stderr, "Sensor not found, expected Part ID 0x%02X, got 0x%02X\n", PART_ID_EXPECTED, part_id);
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t mode_config = SPO2_MODE;
    if (gpioI2CWriteReg8(i2c_handle, MODE_CONFIG_REG, mode_config) < 0) {
        fprintf(stderr, "Failed to reset sensor\n");
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t spo2_config = SPO2_CONFIG;
    if (gpioI2CWriteReg8(i2c_handle, SPO2_CONFIG_REG, spo2_config) < 0) {
        fprintf(stderr, "Failed to configure SpO2 mode\n");
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t led1_pa = LED_PA;
    if (gpioI2CWriteReg8(i2c_handle, LED1_PA_REG, led1_pa) < 0) {
        fprintf(stderr, "Failed to set LED1 pulse amplitude\n");
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t led2_pa = LED_PA;
    if (gpioI2CWriteReg8(i2c_handle, LED2_PA_REG, led2_pa) < 0) {
        fprintf(stderr, "Failed to set LED2 pulse amplitude\n");
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        uint8_t fifo_data[FIFO_SIZE];
        int bytes_read = gpioI2CRead(i2c_handle, fifo_data, FIFO_SIZE);
        if (bytes_read < 0) {
            fprintf(stderr, "Failed to read FIFO data\n");
            continue;
        }

        // Process FIFO data and compute SpO2 and HR
        // ...

        // Log events if necessary
        // ...

        sleep(1);
    }

    gpioI2CClose(i2c_handle);
    gpioTerminate();
    return 0;
}

