#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_CE 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define VREF 3.3
#define ADC_CHANNELS 3
#define LOG_INTERVAL 500

void log_voltage(int channel, float voltage) {
    time_t now = time(NULL);
    struct tm *tm_info = gmtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

    FILE *log_file = fopen("analog_log.csv", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    if (channel == 0) {
        fprintf(log_file, "Timestamp,Channel,Voltage\n");
    }

    fprintf(log_file, "%s,%d,%.2f\n", timestamp, channel, voltage);
    fclose(log_file);
}

int read_adc_channel(int channel) {
    uint8_t tx_buf[3] = {0x01, (channel << 4) | 0x08, 0x00};
    uint8_t rx_buf[3];

    int retries = 3;
    while (retries--) {
        int rc = spi_xfer(SPI_CHANNEL, tx_buf, rx_buf, 3);
        if (rc == 3) {
            return ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
        }
        printf("SPI transfer failed, retrying...\n");
    }

    fprintf(stderr, "Failed to read ADC channel %d after %d retries\n", channel, retries);
    return -1;
}

void signal_handler(int sig) {
    gpioTerminate();
    exit(0);
}

