    if (channel == 0) {
        fprintf(log_file, "Timestamp,Channel,Voltage\n");
    }

    fprintf(log_file, "%s,%d,%.2f\n", timestamp, channel, voltage);
    fclose(log_file);
}

int read_adc_channel(int channel) {
    uint8_t tx_buf[3] = {0x01, (channel << 4) | 0x08, 0x00};
    uint8_t rx_buf[3];

    int retries = 3;
    while (retries--) {
        int rc = spi_xfer(SPI_CHANNEL, tx_buf, rx_buf, 3);
        if (rc == 3) {
            return ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
        }
        printf("SPI transfer failed, retrying...\n");
    }

    fprintf(stderr, "Failed to read ADC channel %d after %d retries\n", channel, retries);
    return -1;
}

void signal_handler(int sig) {
    gpioTerminate();
    exit(0);
}

