#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>
#include <time.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x48
#define RELAY_PIN 17
#define DOOR_SENSOR_PIN 27
#define ADS1115_CONVERSION_TIME 1
#define ADS1115_CONVERSION_REG 0x00
#define ADS1115_CONFIG_REG 0x01
#define ADS1115_CONFIG_SINGLE_SHOT 0x8000
#define ADS1115_CONFIG_CHANNEL_0 0x4000
#define ADS1115_CONFIG_GAIN_1 0x0000
#define ADS1115_CONFIG_MODE_CONTINUOUS 0x0000
#define ADS1115_CONFIG_DATA_RATE_8 0x0000
#define ADS1115_CONFIG_COMP_QUE_DISABLE 0x0000
#define ADS1115_CONFIG_COMP_POL_LOW 0x0000
#define ADS1115_CONFIG_COMP_LAT_NONLATCH 0x0000
#define ADS1115_CONFIG_COMP_MODE_WINDOW 0x0000
#define ADS1115_CONFIG_COMP_VALUE 0x0000
#define ADS1115_CONFIG_COMP_HIGH 0x0000
#define ADS1115_CONFIG_COMP_LOW 0x0000
#define ADS1115_CONVERSION_MASK 0x0FFF
#define ADS1115_CONVERSION_SCALE 0.1875
#define BASELINE_SAMPLES 10
#define TRIGGER_THRESHOLD 0.8
#define RELAY_HOLD_TIME 3000
#define LOG_FILE "/var/log/door_events.log"

int i2c_fd;
struct gpiod_chip *chip;
struct gpiod_line *relay_line, *door_sensor_line;
time_t start_time;

void log_event(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        time_t now = time(NULL);
        fprintf(log_file, "%ld.%03ld: %s\n", now - start_time, (long)clock() / CLOCKS_PER_SEC % 1000, message);
        fclose(log_file);
    }
}

void handle_sigint(int sig) {
    gpiod_line_set_value(relay_line, 0);
    gpiod_chip_close(chip);
    close(i2c_fd);
    exit(0);
}

int read_ads1115_conversion() {
    uint16_t config = ADS1115_CONFIG_SINGLE_SHOT | ADS1115_CONFIG_CHANNEL_0 | ADS1115_CONFIG_GAIN_1 | ADS1115_CONFIG_MODE_CONTINUOUS | ADS1115_CONFIG_DATA_RATE_8 | ADS1115_CONFIG_COMP_QUE_DISABLE | ADS1115_CONFIG_COMP_POL_LOW | ADS1115_CONFIG_COMP_LAT_NONLATCH | ADS1115_CONFIG_COMP_MODE_WINDOW | ADS1115_CONFIG_COMP_VALUE | ADS1115_CONFIG_COMP_HIGH | ADS1115_CONFIG_COMP_LOW;
    if (write(i2c_fd, &config, 2) != 2) {
        log_event("I2C write failed");
        return -1;
    }
    usleep(ADS1115_CONVERSION_TIME * 1000);
    uint16_t conversion;
    if (read(i2c_fd, &conversion, 2) != 2) {
        log_event("I2C read failed");
        return -1;
    }
    return (conversion & ADS1115_CONVERSION_MASK) * ADS1115_CONVERSION_SCALE;
}

int main() {
    start_time = time(NULL);
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return 1;
    }

    // Initialize GPIO lines
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }
    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        perror("Failed to get relay line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }
    if (gpiod_line_request_output(relay_line, "door_lock", 0) < 0) {
        perror("Failed to request relay line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }
    door_sensor_line = gpiod_chip_get_line(chip, DOOR_SENSOR_PIN);
    if (!door_sensor_line) {
        perror("Failed to get door sensor line");
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }
    if (gpiod_line_request_input(door_sensor_line, "door_sensor") < 0) {
        perror("Failed to request door sensor line");
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    // Take baseline samples
    int baseline_sum = 0;
    for (int i = 0; i < BASELINE_SAMPLES; i++) {
        int distance = read_ads1115_conversion();
        if (distance >= 0) {
            baseline_sum += distance;
        }
        usleep(50 * 1000);
    }
    int baseline_avg = baseline_sum / BASELINE_SAMPLES;
    int trigger_threshold = baseline_avg * TRIGGER_THRESHOLD;

    // Main loop
    while (1) {
        int distance = read_ads1115_conversion();
        if (distance >= 0 && distance < trigger_threshold) {
            gpiod_line_set_value(relay_line, 1);
            usleep(RELAY_HOLD_TIME * 1000);
            gpiod_line_set_value(relay_line, 0);
            int door_open = gpiod_line_get_value(door_sensor_line);
            if (door_open == 0) {
                log_event("door opened");
            } else {
                log_event("door not opened");
            }
        }
        usleep(200 * 1000);
    }

    // Cleanup
    gpiod_line_release(relay_line);
    gpiod_line_release(door_sensor_line);
    gpiod_chip_close(chip);
    close(i2c_fd);
    return 0;
}

