#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define CS_LINES {8, 7, 25}
#define NUM_SENSORS 3
#define LOG_INTERVAL 5
#define CSV_HEADER "timestamp,sensor1,sensor2,sensor3\n"

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int read_adc(int fd, int cs, int channel) {
    uint8_t tx[3] = {0x01, (0x08 | channel) << 4, 0x00};
    uint8_t rx[3];
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = 1000000,
        .delay_usecs = 0,
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI_IOC_MESSAGE");
        return -1;
    }

    int value = (rx[1] & 0x03) << 8 | rx[2];
    return value;
}

int main() {
    int spi_fd;
    struct gpiod_chip *chip;
    struct gpiod_line *lines[NUM_SENSORS];
    FILE *log_file;
    time_t now;
    char timestamp[20];

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open SPI device
    if ((spi_fd = open(SPI_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    if ((chip = gpiod_chip_open_by_name("gpiochip0")) == NULL) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Request CS lines
    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, CS_LINES[i]);
        if (gpiod_line_request_output(lines[i], "soil_moisture_cs", 1) < 0) {
            perror("Failed to request CS line");
            for (int j = 0; j < i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            close(spi_fd);
            return EXIT_FAILURE;
        }
    }

    // Open log file
    if ((log_file = fopen("soil_moisture_log.csv", "a")) == NULL) {
        perror("Failed to open log file");
        for (int i = 0; i < NUM_SENSORS; i++) {
            gpiod_line_release(lines[i]);
        }
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Write CSV header if file is newly created
    if (ftell(log_file) == 0) {
        fputs(CSV_HEADER, log_file);
    }

    while (running) {
        now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        for (int i = 0; i < NUM_SENSORS; i++) {
            gpiod_line_set_value(lines[i], 0);
            int value = read_adc(spi_fd, CS_LINES[i], 0);
            gpiod_line_set_value(lines[i], 1);

            if (value < 0) {
                fprintf(log_file, "%s,-1,", timestamp);
            } else {
                fprintf(log_file, "%s,%d,", timestamp, value);
            }
        }

        fprintf(log_file, "\n");
        fflush(log_file);
        sleep(LOG_INTERVAL);
    }

    // Cleanup
    fclose(log_file);
    for (int i = 0; i < NUM_SENSORS; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);
    close(spi_fd);

    return EXIT_SUCCESS;
}
