This code provides a complete solution for logging soil moisture sensor readings from three MCP3008 chips on a Raspberry Pi 5 using libgpiod for GPIO control and standard Linux spidev for SPI communication. It handles errors, logs sensor readings every 5 seconds, and ensures proper resource cleanup on exit.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_CE 8
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define PUMP_PIN 18
#define DRY_RAW 200
#define WET_RAW 800
#define LOG_FILE "irrigation.log"

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

int read_adc(int channel) {
    int retries = 3;
    while (retries--) {
        int adc_value = spiRead(SPI_CHANNEL, (channel << 4) | 0x18, 1);
        if (adc_value >= 0) {
            return adc_value & 0x3FF;
        }
        printf("SPI read error, retrying...\n");
    }
    return -1;
}

int main(int argc, char *argv[]) {
    int threshold = 30;
    int duration_seconds = 10;
    int sleep_interval = 60;
    int opt;
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atoi(optarg);
                break;
            case 'd':
                duration_seconds = atoi(optarg);
                break;
            case 's':
                sleep_interval = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d duration_seconds] [-s sleep_interval]\n", argv[0]);
                return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(PUMP_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set pump pin mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(PUMP_PIN, PI_PUD_OFF) < 0) {
        fprintf(stderr, "Failed to set pump pin pull-up/pull-down\n");
        gpioTerminate();
        return 1;
    }

    if (spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE) < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(SPI_CHANNEL);
        gpioTerminate();
        return 1;
    }

    while (!stop_flag) {
        int adc_value = read_adc(0);
        if (adc_value < 0) {
            fprintf(log_file, "Failed to read ADC value\n");
            fflush(log_file);
            sleep(sleep_interval);
            continue;
        }

        int moisture_percentage = (adc_value - DRY_RAW) * 100 / (WET_RAW - DRY_RAW);
        if (moisture_percentage < 0) moisture_percentage = 0;
        if (moisture_percentage > 100) moisture_percentage = 100;

        time_t now = time(NULL);
        fprintf(log_file, "%s: Moisture: %d%%\n", ctime(&now), moisture_percentage);
        fflush(log_file);

        if (moisture_percentage < threshold) {
            gpioWrite(PUMP_PIN, 1);
            fprintf(log_file, "%s: Pump activated for %d seconds\n", ctime(&now), duration_seconds);
            fflush(log_file);
            sleep(duration_seconds);
            gpioWrite(PUMP_PIN, 0);
            fprintf(log_file, "%s: Pump deactivated\n", ctime(&now));
            fflush(log_file);
        }

        sleep(sleep_interval);
    }

    fclose(log_file);
    spiClose(SPI_CHANNEL);
    gpioTerminate();

    return 0;
}

