#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x48
#define CONTROL_BYTE 0x40 // Single-ended mode, channel 0, analog output disabled

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    int i2c_fd;
    struct i2c_msg msgs[2];
    struct i2c_rdwr_ioctl_data msgset;
    uint8_t control_byte = CONTROL_BYTE;
    uint8_t dummy_read[1];
    uint8_t sample[1];

    // Open I2C bus
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Register SIGINT handler
    signal(SIGINT, sigint_handler);

    while (running) {
        // Perform dummy read
        msgs[0].addr = I2C_ADDR;
        msgs[0].flags = 0;
        msgs[0].len = 1;
        msgs[0].buf = dummy_read;

        msgset.nmsgs = 1;
        msgset.msgs = msgs;

        if (ioctl(i2c_fd, I2C_RDWR, &msgset) < 0) {
            perror("Failed to perform dummy read");
            close(i2c_fd);
            return EXIT_FAILURE;
        }

        // Perform actual read
        msgs[0].addr = I2C_ADDR;
        msgs[0].flags = 0;
        msgs[0].len = 1;
        msgs[0].buf = sample;

        msgset.nmsgs = 1;
        msgset.msgs = msgs;

        if (ioctl(i2c_fd, I2C_RDWR, &msgset) < 0) {
            perror("Failed to perform actual read");
            close(i2c_fd);
            return EXIT_FAILURE;
        }

        // Print sample value
        printf("Sample: %d\n", sample[0]);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Close I2C bus
    close(i2c_fd);

    return EXIT_SUCCESS;
}

