#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <ads1115.h>

#define I2C_ADDRESS 0x48
#define I2C_CHANNEL 1
#define GPIO_PIN 27
#define BUFFER_SIZE 10
#define THRESHOLD 500.0

volatile int running = 1;
volatile float buffer[BUFFER_SIZE];
volatile int buffer_index = 0;
volatile float sum = 0.0;

void signal_handler(int signum) {
    running = 0;
}

float voltage_to_gauss(float voltage) {
    return (voltage - 2.5) / 0.0014;
}

void log_event(const char *message) {
    syslog(LOG_INFO, "%s", message);
}

void log_error(const char *message) {
    syslog(LOG_ERR, "%s", message);
}

int main() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    if (ads1115Initialise(I2C_CHANNEL, I2C_ADDRESS) < 0) {
        log_error("Failed to initialize ADS1115");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        log_error("Failed to set GPIO27 mode");
        ads1115Terminate();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    openlog("ss49e_monitor", LOG_PID, LOG_USER);

    while (running) {
        float voltage = ads1115ReadVoltage(0);
        if (voltage < 0 || voltage > 3.3) {
            log_error("Invalid voltage reading");
            continue;
        }

        float gauss = voltage_to_gauss(voltage);
        sum -= buffer[buffer_index];
        buffer[buffer_index] = gauss;
        sum += buffer[buffer_index];
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        float average = sum / BUFFER_SIZE;
        if (average > THRESHOLD) {
            gpioWrite(GPIO_PIN, PI_HIGH);
            log_event("Threshold exceeded, motor shutdown");
        } else {
            gpioWrite(GPIO_PIN, PI_LOW);
        }

        log_event("Voltage: %.2f V, Gauss: %.2f G, Average: %.2f G", voltage, gauss, average);

        gpioDelay(1000000); // 1 Hz
    }

    gpioWrite(GPIO_PIN, PI_LOW);
    ads1115Terminate();
    gpioTerminate();
    closelog();

    return EXIT_SUCCESS;
}

