#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define ADC_CHANNEL 0
#define PUMP_PIN 18
#define WATERING_DURATION 10
#define CHECK_INTERVAL 60
#define THRESHOLD 300
#define LOG_FILE "watering_events.txt"

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int read_adc(int channel) {
    uint16_t adc_value;
    int ret = spiXfer(SPI_CHANNEL, (uint8_t[]){1, (8 + channel) << 4, 0}, (uint8_t[]){0, 0}, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }
    adc_value = ((uint16_t)ret[1] << 8) | ret[2];
    return adc_value;
}

void log_event(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }
    time_t now = time(NULL);
    fprintf(log_file, "%s: %s\n", ctime(&now), message);
    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PUMP_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for pump\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            log_event("ADC read failed");
            gpioWrite(PUMP_PIN, PI_OFF);
            continue;
        }

        if (adc_value < THRESHOLD) {
            gpioWrite(PUMP_PIN, PI_ON);
            log_event("Watering started");
            sleep(WATERING_DURATION);
            gpioWrite(PUMP_PIN, PI_OFF);
            log_event("Watering ended");
        } else {
            log_event("No watering needed");
        }

        sleep(CHECK_INTERVAL);
    }

    gpioWrite(PUMP_PIN, PI_OFF);
    gpioTerminate();
    return EXIT_SUCCESS;
}

