#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define MCP3008_ADDRESS 0x40
#define ADC_CHANNEL 0
#define ADC_FULL_SCALE 1023
#define INTENSITY_SCALE 10

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int read_adc_value(int spi_handle, int channel) {
    uint8_t tx[3] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    int status = spiXfer(spi_handle, tx, rx, 3);
    if (status < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", pigpio_error(status));
        return -1;
    }
    return ((rx[1] & 3) << 8) | rx[2];
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %s\n", pigpio_error(spi_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    while (running) {
        int adc_value = read_adc_value(spi_handle, ADC_CHANNEL);
        if (adc_value >= 0) {
            int intensity = (adc_value * INTENSITY_SCALE) / ADC_FULL_SCALE;
            time_t now = time(NULL);
            printf("%s, ADC: %d, Intensity: %d\n", ctime(&now), adc_value, intensity);
        }
        sleep(1);
    }

    spiClose(spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

