#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_ADDRESS 0x48
#define I2C_CHANNEL 1
#define ADC_CHANNEL 0
#define LED_PIN 17
#define DEFAULT_THRESHOLD 100.0
#define BLINK_DURATION 1000
#define BLINK_INTERVAL 50
#define READ_INTERVAL 100

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int read_adc_value(int i2c_handle) {
    uint16_t adc_value;
    if (i2cReadReg16(i2c_handle, 0x00) != PI_OK) {
        fprintf(stderr, "Failed to read ADC value\n");
        return -1;
    }
    adc_value = (i2cReadReg16(i2c_handle, 0x01) << 8) | i2cReadReg16(i2c_handle, 0x02);
    return adc_value;
}

double adc_to_gauss(int adc_value) {
    return (adc_value * 0.001 * 4.096) / 3.3;
}

void blink_led(int gpio_pin, int duration, int interval) {
    gpioWrite(gpio_pin, PI_ON);
    gpioDelay(interval);
    gpioWrite(gpio_pin, PI_OFF);
    gpioDelay(interval);
    gpioDelay(duration - 2 * interval);
}

int main(int argc, char *argv[]) {
    double threshold = DEFAULT_THRESHOLD;
    if (argc > 1) {
        threshold = atof(argv[1]);
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != PI_OK) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        gpioTerminate();
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_CHANNEL, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C channel\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        int adc_value = read_adc_value(i2c_handle);
        if (adc_value >= 0) {
            double gauss = adc_to_gauss(adc_value);
            printf("Magnetic field: %.2f Gauss\n", gauss);
            if (gauss > threshold) {
                blink_led(LED_PIN, BLINK_DURATION, BLINK_INTERVAL);
            }
        }
        gpioDelay(READ_INTERVAL * 1000);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

