This C program uses the pigpio library to monitor a Honeywell SS49E linear Hall-effect sensor connected to an ADS1115 ADC via I2C on a Raspberry Pi 4 Model B. It reads the sensor value every 100 ms, converts it to Gauss, and prints the result to the console. If the magnetic field exceeds a user-configurable threshold (default 100.0 Gauss), it blinks an LED on GPIO17 rapidly for 1 second. The program handles initialization, I2C communication, and resource cleanup gracefully, including on exit via SIGINT/SIGTERM signals.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <paho-mqtt.h>

#define SPI_CHANNEL 0
#define SPI_CE 8
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define RELAY_PIN 17
#define MOISTURE_MIN 30
#define MOISTURE_MAX 35
#define MQTT_BROKER "mqtt.eclipse.org"
#define MQTT_PORT 1883
#define MQTT_TOPIC "soil_moisture"
#define MQTT_CONTROL_TOPIC "pump_control"
#define MQTT_INTERVAL 60

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int read_adc(int channel) {
    int value = spiXfer2(SPI_CHANNEL, SPI_CE, 0b11000000 | (channel << 4) | 0b00000111, 3);
    return ((value >> 4) & 0x3FF);
}

void control_relay(int state) {
    gpioWrite(RELAY_PIN, state);
}

void publish_moisture(int moisture) {
    char payload[10];
    snprintf(payload, sizeof(payload), "%d", moisture);
    MQTTAsync_publishMessage(client, MQTT_TOPIC, MQTTAsync_message_initializer);
}

void on_message_arrived(void *context, char *topicName, int topicLen, MQTTAsync_message *message) {
    char payload[message->payloadlen + 1];
    memcpy(payload, message->payload, message->payloadlen);
    payload[message->payloadlen] = '\0';
    if (strcmp(topicName, MQTT_CONTROL_TOPIC) == 0) {
        if (strcmp(payload, "pump_on") == 0) {
            control_relay(1);
        } else if (strcmp(payload, "pump_off") == 0) {
            control_relay(0);
        }
    }
    MQTTAsync_freeMessage(&message);
    MQTTAsync_free(topicName);
}

int main() {
    int moisture, adc_value;
    MQTTAsync client;
    MQTTAsync_connectOptions conn_opts = MQTTAsync_connectOptions_initializer;
    MQTTAsync_message pubmsg = MQTTAsync_message_initializer;
    MQTTAsync_responseOptions opts = MQTTAsync_responseOptions_initializer;

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d as output", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (spiOpen(SPI_CHANNEL, SPI_SPEED, 0) < 0) {
        syslog(LOG_ERR, "Failed to open SPI channel %d", SPI_CHANNEL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    MQTTAsync_create(&client, MQTT_BROKER, "soil_moisture_client", MQTTCLIENT_PERSISTENCE_NONE, NULL);
    MQTTAsync_setCallbacks(client, NULL, NULL, on_message_arrived, NULL);

    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;
    MQTTAsync_connect(client, &conn_opts, &opts);

    while (running) {
        adc_value = read_adc(ADC_CHANNEL);
        moisture = (adc_value * 100) / 1023;
        if (moisture < 0 || moisture > 100) {
            syslog(LOG_WARNING, "Sensor out of range: %d", moisture);
        } else {
            publish_moisture(moisture);
            if (moisture < MOISTURE_MIN) {
                control_relay(1);
            } else if (moisture > MOISTURE_MAX) {
                control_relay(0);
            }
        }
        sleep(MQTT_INTERVAL);
    }

    MQTTAsync_disconnect(client, &opts);
    spiClose(SPI_CHANNEL);
    gpioTerminate();
    MQTTAsync_destroy(&client);

    return EXIT_SUCCESS;
}

