            if (moisture < MOISTURE_MIN) {
                control_relay(1);
            } else if (moisture > MOISTURE_MAX) {
                control_relay(0);
            }
        }
        sleep(MQTT_INTERVAL);
    }

    MQTTAsync_disconnect(client, &opts);
    spiClose(SPI_CHANNEL);
    gpioTerminate();
    MQTTAsync_destroy(&client);

    return EXIT_SUCCESS;
}
