#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define VREF 3.3

int spi_fd;

void close_spi() {
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

void handle_sigint(int sig) {
    close_spi();
    exit(0);
}

int main() {
    struct spi_ioc_transfer tr;
    uint8_t tx[3] = {0x01, 0b10000000, 0x00};
    uint8_t rx[3];
    uint16_t adc_value;
    double voltage;

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    // Set SPI mode
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close_spi();
        exit(EXIT_FAILURE);
    }

    // Set SPI bits per word
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set SPI bits per word");
        close_spi();
        exit(EXIT_FAILURE);
    }

    // Set SPI speed
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close_spi();
        exit(EXIT_FAILURE);
    }

    // Register signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    while (1) {
        // Transfer data
        memset(&tr, 0, sizeof(tr));
        tr.tx_buf = (unsigned long)tx;
        tr.rx_buf = (unsigned long)rx;
        tr.len = 3;
        tr.delay_usecs = 0;
        tr.speed_hz = SPI_SPEED;
        tr.bits_per_word = SPI_BITS_PER_WORD;

        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
            perror("Failed to transfer data");
            close_spi();
            exit(EXIT_FAILURE);
        }

        // Extract ADC value
        adc_value = ((rx[1] & 0x03) << 8) | rx[2];

        // Calculate voltage
        voltage = (double)adc_value * VREF / 1024.0;

        // Print results
        printf("ADC Value: %d, Voltage: %.2f V\n", adc_value, voltage);

        // Sleep for 500 ms
        usleep(500000);
    }

    close_spi();
    return 0;
}

