This C program reads channel 0 from an MCP3008 10-bit ADC over SPI on a Raspberry Pi using the Linux spidev interface. It initializes the SPI device, sets the appropriate parameters, and continuously reads the ADC value, converting it to a voltage and printing both the raw value and the voltage every 500 ms. The program handles SIGINT to cleanly close the SPI device and exit, and it reports errors to stderr, exiting non-zero on any initialization failure.

code:
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_CE 0
#define SPI_SPEED 500000
#define VREF 3.3
#define NUM_CHANNELS 3
#define SAMPLE_INTERVAL 5

void cleanup(int signum) {
    gpioTerminate();
    exit(signum);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    int spiHandle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_CE);
    if (spiHandle < 0) {
        fprintf(stderr, "Failed to open SPI channel %d\n", SPI_CHANNEL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *file = fopen("sensor_data.csv", "w");
    if (!file) {
        fprintf(stderr, "Failed to open sensor_data.csv for writing\n");
        spiClose(spiHandle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        for (int i = 0; i < NUM_CHANNELS; i++) {
            uint8_t tx[3] = {1, (8 + i) << 4, 0};
            uint8_t rx[3];
            int result = spiXfer(spiHandle, tx, rx, 3);
            if (result < 0) {
                fprintf(stderr, "SPI transfer failed for channel %d\n", i);
                fclose(file);
                spiClose(spiHandle);
                gpioTerminate();
                return EXIT_FAILURE;
            }

            int adcValue = ((rx[1] & 3) << 8) | rx[2];
            double voltage = (double)adcValue * VREF / 1024.0;

            fprintf(file, "%s,Channel%d,%.4f\n", timestamp, i, voltage);
        }

        fflush(file);
        sleep(SAMPLE_INTERVAL);
    }

    fclose(file);
    spiClose(spiHandle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

