#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 500000
#define PWM_FREQ 100
#define PWM_RANGE 1024
#define NOISE_THRESHOLD 500
#define LOG_FILE "vibration_log.txt"

int spi_fd;
int pwm_channel1 = 17;
int pwm_channel2 = 27;
FILE *log_file;

void log_event(int adc_value) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(log_file, "%s, ADC: %d\n", asctime(tm_info), adc_value);
    fflush(log_file);
}

void close_resources() {
    if (log_file) fclose(log_file);
    if (spi_fd >= 0) close(spi_fd);
    gpioTerminate();
}

void handle_signal(int sig) {
    close_resources();
    exit(0);
}

int read_adc(int channel) {
    uint8_t tx[3] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    int ret;

    ret = write(spi_fd, tx, 3);
    if (ret != 3) {
        perror("Failed to write to SPI device");
        return -1;
    }

    ret = read(spi_fd, rx, 3);
    if (ret != 3) {
        perror("Failed to read from SPI device");
        return -1;
    }

    return ((rx[1] & 3) << 8) | rx[2];
}

int main() {
    int adc_value, pwm_duty;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(pwm_channel1, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", pwm_channel1);
        close_resources();
        return 1;
    }

    if (gpioSetMode(pwm_channel2, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", pwm_channel2);
        close_resources();
        return 1;
    }

    if (gpioSetPWMfrequency(pwm_channel1, PWM_FREQ) != 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO%d\n", pwm_channel1);
        close_resources();
        return 1;
    }

    if (gpioSetPWMfrequency(pwm_channel2, PWM_FREQ) != 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO%d\n", pwm_channel2);
        close_resources();
        return 1;
    }

    if (gpioSetPWMrange(pwm_channel1, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range for GPIO%d\n", pwm_channel1);
        close_resources();
        return 1;
    }

    if (gpioSetPWMrange(pwm_channel2, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range for GPIO%d\n", pwm_channel2);
        close_resources();
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        close_resources();
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        close_resources();
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        close_resources();
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        close_resources();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(spi_fd);
        close_resources();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        adc_value = read_adc(0);
        if (adc_value < 0) {
            continue;
        }

        if (adc_value > NOISE_THRESHOLD) {
            pwm_duty = (adc_value - NOISE_THRESHOLD) * (PWM_RANGE - NOISE_THRESHOLD) / (1023 - NOISE_THRESHOLD) + NOISE_THRESHOLD;
            gpioSetPWMrange(pwm_channel1, pwm_duty);
            gpioSetPWMrange(pwm_channel2, pwm_duty);
            log_event(adc_value);
        } else {
            gpioSetPWMrange(pwm_channel1, 0);
            gpioSetPWMrange(pwm_channel2, 0);
        }

        usleep(10000); // 10 ms
    }

    close_resources();
    return 0;
}

