#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define I2C_DEVICE "/dev/i2c-1"
#define BH1750_ADDRESS 0x23
#define BH1750_COMMAND 0x11
#define MAX9814_CHANNEL 0
#define LOG_FILE "tamper_log.csv"
#define LOG_INTERVAL 5
#define SPI_SPEED 500000
#define SPI_BITS_PER_WORD 8

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int read_bh1750(int fd) {
    uint8_t data[2];
    if (write(fd, &BH1750_COMMAND, 1) != 1) {
        perror("BH1750 write");
        return -1;
    }
    usleep(180000);
    if (read(fd, data, 2) != 2) {
        perror("BH1750 read");
        return -1;
    }
    return (data[0] << 8) | data[1];
}

int read_max9814(int fd) {
    uint8_t tx[3] = {0x80 | (MAX9814_CHANNEL << 2), 0x00, 0x00};
    uint8_t rx[3];
    if (write(fd, tx, 3) != 3) {
        perror("MAX9814 write");
        return -1;
    }
    if (read(fd, rx, 3) != 3) {
        perror("MAX9814 read");
        return -1;
    }
    int16_t value = (rx[1] << 8) | rx[2];
    return value;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int i2c_fd, spi_fd, log_fd;
    FILE *log_file;
    time_t now;
    struct tm *tm_info;
    int sound_level, light_level, error_code;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if ((i2c_fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("I2C open");
        return EXIT_FAILURE;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDRESS) < 0) {
        perror("I2C slave");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize SPI
    if ((spi_fd = open(SPI_DEVICE, O_RDWR)) < 0) {
        perror("SPI open");
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE_0) < 0) {
        perror("SPI mode");
        close(spi_fd);
        close(i2c_fd);
