#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define MCP3008_CHANNEL 0
#define FAN_PIN 18
#define CO2_THRESHOLD 700
#define CALIBRATION_SLOPE 0.5
#define CALIBRATION_INTERCEPT -50
#define LOG_FILE "air_quality.log"

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int read_adc(int channel) {
    int handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (handle < 0) {
        fprintf(stderr, "Failed to open SPI channel %d\n", SPI_CHANNEL);
        return -1;
    }

    uint8_t tx[3] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    int result = spiXfer(handle, tx, rx, 3);
    spiClose(handle);

    if (result < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 3) << 8) | rx[2];
}

double adc_to_co2(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
        return -1;
    }
    return CALIBRATION_SLOPE * adc_value + CALIBRATION_INTERCEPT;
}

void log_reading(double co2_ppm, int fan_state) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

    fprintf(log_file, "%s,%.2f,%d\n", timestamp, co2_ppm, fan_state);
    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(FAN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", FAN_PIN);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        int adc_value = read_adc(MCP3008_CHANNEL);
        if (adc_value >= 0) {
            double co2_ppm = adc_to_co2(adc_value);
            if (co2_ppm >= 0) {
                int fan_state = co2_ppm > CO2_THRESHOLD;
                gpioWrite(FAN_PIN, fan_state);
                log_reading(co2_ppm, fan_state);
            }
        }

        sleep(5);
    }

    gpioWrite(FAN_PIN, 0);
    gpioTerminate();
    return 0;
}

