#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_CE 0
#define SPI_CHANNEL_NUM 0
#define RELAY_PIN 17
#define PROXIMITY_THRESHOLD 20
#define POLL_INTERVAL 100
#define DEBOUNCE_DELAY 1000

static struct gpiod_chip *chip;
static struct gpiod_line *relay_line;
static int spi_fd;

void log_event(const char *event) {
    FILE *log_file = fopen("door_events.log", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    fprintf(log_file, "%s: %s\n", ctime(&now), event);
    fclose(log_file);
}

void handle_sigint(int sig) {
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (relay_line) {
        gpiod_line_release(relay_line);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    exit(0);
}

int main() {
    signal(SIGINT, handle_sigint);

    // Initialize GPIO
    if (gpiod_library_init() < 0) {
        perror("Failed to initialize libgpiod library");
        return EXIT_FAILURE;
    }
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }
    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        perror("Failed to get relay line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(relay_line, "relay_control", 0) < 0) {
        perror("Failed to request relay line as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initialize SPI
    if ((spi_fd = spiOpen(SPI_CHANNEL, SPI_SPEED, 0)) < 0) {
        perror("Failed to open SPI device");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int last_state = 0;
    while (1) {
        // Read from MCP3008
        uint16_t adc_value = spiXfer2(spi_fd, 0x68, 3);
        uint16_t voltage = (adc_value & 0x3FF) * 3300 / 1024;
        int proximity = 20 * voltage / 3300; // Assuming linear relationship

        // Check for proximity
        if (proximity < PROXIMITY_THRESHOLD && last_state == 0) {
            // Debounce
            usleep(DEBOUNCE_DELAY * 1000);
            adc_value = spiXfer2(spi_fd, 0x68, 3);
            voltage = (adc_value & 0x3FF) * 3300 / 1024;
            proximity = 20 * voltage / 3300;

            if (proximity < PROXIMITY_THRESHOLD) {
                // Trigger relay
                gpiod_line_set_value(relay_line, 1);
                log_event("Door opened");
                last_state = 1;
            }
        } else if (proximity >= PROXIMITY_THRESHOLD && last_state == 1) {
            // Debounce
            usleep(DEBOUNCE_DELAY * 1000);
            adc_value = spiXfer2(spi_fd, 0x68, 3);
            voltage = (adc_value & 0x3FF) * 3300 / 1024;
            proximity = 20 * voltage / 3300;

            if (proximity >= PROXIMITY_THRESHOLD) {
                // Deactivate relay
                gpiod_line_set_value(relay_line, 0);
                log_event("Door closed");
                last_state = 0;
            }
        }

        // Poll
        usleep(POLL_INTERVAL * 1000);
    }

    // Clean up
    gpiod_chip_close(chip);
    gpiod_line_release(relay_line);
    close(spi_fd);

    return EXIT_SUCCESS;
}

