uint16_t read_adc(uint8_t channel) {
    uint8_t cmd[3] = {0x18 | (channel & 0x07), 0x00, 0x00};
    uint8_t response[3];
    int retries = 0;

    while (retries < SPI_RETRY_MAX) {
        if (gpio_spi_xfer(SPI_CHANNEL, cmd, response, 3) == 3) {
            return ((response[1] & 0x03) << 8) | response[2];
        }
        retries++;
        gpioDelay(SPI_RETRY_DELAY * (1 << retries));
    }

    fprintf(stderr, "SPI communication failed after %d retries\n", SPI_RETRY_MAX);
    return 0;
}

void log_moisture(uint16_t adc_value) {
    FILE *file = fopen("soil_data.txt", "a");
