#include <fcntl.h>
#include <sys/mman.h>
#include <linux/spi/spidev.h>

#define GPIO_CHIP "gpiochip0"
#define TRIG_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18
#define LDR_PIN 0
#define SPI_DEVICE "/dev/spidev0.0"
#define CONFIG_FILE "theremin_config.txt"

#define PWM_FREQ 1000000
#define PWM_RANGE 1000
#define MIN_FREQ 220
#define MAX_FREQ 880
#define MIN_DUTY 100
#define MAX_DUTY 900

static struct gpiod_chip *chip;
static struct gpiod_line *trig_line, *echo_line, *ldr_line;
static int pwm_fd;
static int spi_fd;
static uint16_t last_valid_distance = 0;
static uint16_t last_valid_duty = 500;

static void handle_sigint(int sig) {
    gpiod_line_release(trig_line);
    gpiod_line_release(echo_line);
    gpiod_line_release(ldr_line);
    close(pwm_fd);
    close(spi_fd);
    exit(0);
}

static uint16_t read_distance() {
    uint16_t distance = 0;
    uint8_t buf[4] = {0x02, 0x00, 0x00, 0x00};
    uint8_t status;

    if (write(spi_fd, buf, 4) != 4) {
        perror("SPI write failed");
        return last_valid_distance;
    }

    if (read(spi_fd, buf, 4) != 4) {
        perror("SPI read failed");
        return last_valid_distance;
    }

    status = buf[0];
    if (status & 0x80) {
        distance = (buf[2] << 8) | buf[3];
    }

    return distance;
}

static uint16_t read_ldr() {
    uint8_t buf[3] = {1, (8 | (LDR_PIN & 7)) << 4, 0};
    uint8_t read_buf[3];
    uint16_t adc_value = 0;

    if (write(spi_fd, buf, 3) != 3) {
        perror("SPI write failed");
        return last_valid_duty;
    }

    if (read(spi_fd, read_buf, 3) != 3) {
        perror("SPI read failed");
        return last_valid_duty;
    }

    adc_value = (read_buf[1] & 3) << 8 | read_buf[2];
    return adc_value;
}

static void set_pwm_duty(uint16_t duty) {
    uint32_t value = (duty * PWM_RANGE) / 1000;
    lseek(pwm_fd, 0, SEEK_SET);
    write(pwm_fd, &value, sizeof(value));
}

static void load_config() {
    FILE *file = fopen(CONFIG_FILE, "r");
    if (file) {
        fscanf(file, "%hu %hu", &last_valid_distance, &last_valid_duty);
        fclose(file);
    }
}

static void save_config() {
    FILE *file = fopen(CONFIG_FILE, "w");
    if (file) {
        fprintf(file, "%hu %hu", last_valid_distance, last_valid_duty);
        fclose(file);
    }
}

