    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Failed to get ECHO line");
        gpiod_line_release(trig_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request(echo_line, &echo_config)) {
        perror("Failed to request ECHO line");
        gpiod_line_release(trig_line);
        gpiod_chip_close(chip);
        return 1;
    }

    ldr_line = gpiod_chip_get_line(chip, LDR_PIN);
    if (!ldr_line) {
        perror("Failed to get LDR line");
