        uint16_t frequency = MIN_FREQ + (distance * (MAX_FREQ - MIN_FREQ)) / 255;
        uint16_t duty = MIN_DUTY + (ldr_value * (MAX_DUTY - MIN_DUTY)) / 1023;

        if (distance != last_valid_distance) {
