#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 8
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define ADC_CHANNEL 0
#define ADC_START 0x01
#define ADC_SINGLE_ENDED 0x80
#define ADC_READ_RETRIES 3
#define ADC_READ_DELAY 100000

volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int fd;
    uint8_t tx[3] = {ADC_START, (ADC_CHANNEL << 4) | ADC_SINGLE_ENDED, 0};
    uint8_t rx[3];
    int adc_value, ppm;
    FILE *log_file;
    struct timespec ts;
    char timestamp[20];

    // Initialize GPIO
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "gpio_output", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initialize SPI
    fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set SPI bits per word");
        close(fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("alcohol_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up signal handler
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    while (running) {
        for (int i = 0; i < ADC_READ_RETRIES; i++) {
            if (write(fd, tx, sizeof(tx)) != sizeof(tx)) {
                perror("Failed to write to SPI device");
                continue;
            }

            if (read(fd, rx, sizeof(rx)) != sizeof(rx)) {
                perror("Failed to read from SPI device");
                continue;
            }

            adc_value = ((rx[1] & 0x03) << 8) | rx[2];
            ppm = (adc_value * 0.5) - 10.0;

            if (ppm < 0 || ppm > 1023) {
                fprintf(log_file, "Sensor absent or error, ADC value: %d\n", adc_value);
                fflush(log_file);
                break;
            }

            if (i == ADC_READ_RETRIES - 1) {
                fprintf(log_file, "Failed to read valid ADC value after %d retries\n", ADC_READ_RETRIES);
                fflush(log_file);
                break;
            }

            break;
        }

        if (running) {
            clock_gettime(CLOCK_REALTIME, &ts);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", &ts);
            fprintf(log_file, "%s: ADC value: %d, PPM: %.2f\n", timestamp, adc_value, ppm);

            if (ppm > 50) {
                fprintf(log_file, "Alcohol detected! Limit exceeded.\n");
            } else if (ppm < 20) {
                fprintf(log_file, "Sobriety confirmed.\n");
            } else {
                fprintf(log_file, "Alcohol level within acceptable range.\n");
            }

            fflush(log_file);
            sleep(1);
        }
    }

    // Clean up
    fclose(log_file);
    close(fd);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

