#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define SPI_BITS 10
#define LED_PIN 17
#define MIC_CHANNEL 0
#define CALIBRATION_TIME 5
#define THRESHOLD_PERCENTAGE 10
#define DEBOUNCE_TIME 10

volatile int running = 1;
volatile int last_led_state = 0;

void signal_handler(int sig) {
    running = 0;
}

int read_mic_level(int spi_handle, int channel) {
    uint8_t tx[3] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }
    return ((rx[1] & 3) << 8) | rx[2];
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        gpioTerminate();
        return 1;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_BITS);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI handle\n");
        gpioTerminate();
        return 1;
    }

    int total = 0;
    for (int i = 0; i < CALIBRATION_TIME * 1000 / DEBOUNCE_TIME; i++) {
        int level = read_mic_level(spi_handle, MIC_CHANNEL);
        if (level >= 0) {
            total += level;
        }
        gpioDelay(DEBOUNCE_TIME * 1000);
    }
    int average = total / (CALIBRATION_TIME * 1000 / DEBOUNCE_TIME);

    signal(SIGINT, signal_handler);

    while (running) {
        int level = read_mic_level(spi_handle, MIC_CHANNEL);
        if (level >= 0) {
            int threshold = average * (100 + THRESHOLD_PERCENTAGE) / 100;
            if (level > threshold && level > average) {
                if (last_led_state == 0) {
                    gpioWrite(LED_PIN, 1);
                    last_led_state = 1;
                }
            } else {
                if (last_led_state == 1) {
                    gpioWrite(LED_PIN, 0);
                    last_led_state = 0;
                }
            }
        }
        gpioDelay(DEBOUNCE_TIME * 1000);
    }

    gpioWrite(LED_PIN, 0);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

