#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define SAMPLE_INTERVAL 100  // 100 ms
#define LOG_FILE "airflow_log.txt"

void log_with_timestamp(const char *message) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char buffer[80];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(stderr, "%s: %s\n", buffer, message);
}

int read_adc(int channel) {
    int value = spiRead(SPI_CHANNEL, (channel << 4) | (1 << 3), 1);
    if (value < 0) {
        log_with_timestamp("ERROR: ADC read failed");
        return -1;
    }
    return value;
}

void log_airflow(float airflow) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char buffer[80];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(stderr, "%s: Airflow: %.2f SLPM\n", buffer, airflow);
    fprintf(stderr, "%s: Airflow: %.2f SLPM\n", buffer, airflow, LOG_FILE);
}

void cleanup() {
    spiClose(SPI_CHANNEL);
    gpioTerminate();
    fclose(log_file);
    exit(0);
}

int main() {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        log_with_timestamp("ERROR: Failed to open log file");
        return 1;
    }

    if (gpioInitialise() < 0) {
        log_with_timestamp("ERROR: Failed to initialize pigpio");
        fclose(log_file);
        return 1;
    }

    if (spiOpen(SPI_CHANNEL, SPI_SPEED, 0) < 0) {
        log_with_timestamp("ERROR: Failed to open SPI channel");
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    signal(SIGINT, cleanup);

    while (1) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value >= 0) {
            float voltage = (adc_value * 3.3) / 1024.0;
            float airflow = (voltage - 0.5) / (4.5 - 0.5) * 200;
            log_airflow(airflow);
        }
        gpioDelay(SAMPLE_INTERVAL * 1000);
    }

    return 0;
}

