    clock_gettime(CLOCK_MONOTONIC_RAW, &ts_next);
    ts_next.tv_nsec += SAMPLE_PERIOD_NS;
    if (ts_next.tv_nsec >= 1000000000) {
        ts_next.tv_sec++;
        ts_next.tv_nsec -= 1000000000;
    }

    while (1) {
        // Wait until next sample time
        clock_gettime(CLOCK_MONOTONIC_RAW, &ts);
        if (ts.tv_sec < ts_next.tv_sec || (ts.tv_sec == ts_next.tv_sec && ts.tv_nsec < ts_next.tv_nsec)) {
            struct timespec ts_diff = {ts_next.tv_sec - ts.tv_sec, ts_next.tv_nsec - ts.tv_nsec};
            if (nanosleep(&ts_diff, NULL) < 0) {
                perror("Failed to sleep");
                goto cleanup;
            }
        }

        // Sample audio
        if (gpiod_line_set_value(gpio_line, 0) < 0) {
            perror("Failed to set GPIO line low");
            goto cleanup;
        }
