            goto cleanup;
        }
        if (read(spi_fd, rx_buf, sizeof(rx_buf)) != sizeof(rx_buf)) {
            perror("Failed to read from SPI device");
            goto cleanup;
        }
        if (gpiod_line_set_value(gpio_line, 1) < 0) {
            perror("Failed to set GPIO line high");
            goto cleanup;
        }

        // Parse ADC value
        adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];

        // Log sample
        clock_gettime(CLOCK_MONOTONIC_RAW, &now);
        fprintf(log_file, "%ld%09ld|%u\n", now.tv_sec, now.tv_nsec, adc_value);
        fflush(log_file);

        // Update next sample time
        ts_next.tv_nsec += SAMPLE_PERIOD_NS;
        if (ts_next.tv_nsec >= 1000000000) {
            ts_next.tv_sec++;
            ts_next.tv_nsec -= 1000000000;
        }
    }

