int read_adc_channel(int channel) {
    uint8_t buf[3];
    buf[0] = (1 << 1) | (channel << 4) | 0x08;
    buf[1] = 0;
    buf[2] = 0;

    if (gpio_spi_xfer(SPI_CHANNEL, buf, 3, buf, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((buf[1] & 0x03) << 8) | buf[2];
}

double adc_to_voltage(int adc_value) {
    return (double)adc_value * VREF / 1023.0;
}

double voltage_to_acceleration(double voltage) {
    return (voltage - ZERO_G_BIAS) / SENSITIVITY;
}

double kalman_filter(double measurement, double *state, double *error) {
    double predicted_state = *state;
    double predicted_error = *error + 0.01; // Process noise

    double kalman_gain = predicted_error / (predicted_error + 0.01); // Measurement noise
    *state = predicted_state + kalman_gain * (measurement - predicted_state);
    *error = (1 - kalman_gain) * predicted_error;

    return *state;
}

