#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define VCC 3.3
#define V_QUIESCENT 1.65
#define SENSITIVITY 0.025
#define SAMPLE_INTERVAL 100
#define LOG_FILE "magnetic_log.txt"

static struct gpiod_chip *chip;
static struct gpiod_line *lines[3];
static FILE *log_file;

void cleanup() {
    for (int i = 0; i < 3; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

void handle_sigint(int sig) {
    cleanup();
    exit(0);
}

int main() {
    struct gpiod_line_request_config config = {
        .consumer = "DRV5055VA",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
    };

    signal(SIGINT, handle_sigint);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 3; i++) {
        lines[i] = gpiod_chip_get_line(chip, i + 4);
        if (!lines[i]) {
            perror("Failed to get GPIO line");
            cleanup();
            return EXIT_FAILURE;
        }

        if (gpiod_line_request(lines[i], &config)) {
            perror("Failed to request GPIO line");
            cleanup();
            return EXIT_FAILURE;
        }
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        double values[3];
        for (int i = 0; i < 3; i++) {
            int value = gpiod_line_get_value(lines[i]);
            if (value < 0) {
                fprintf(stderr, "Failed to read GPIO line %d\n", i + 4);
                continue;
            }
            values[i] = (value == 1) ? VCC : 0.0;
        }

        double magnetic_fields[3];
        for (int i = 0; i < 3; i++) {
            magnetic_fields[i] = (values[i] - V_QUIESCENT) / SENSITIVITY;
            if (magnetic_fields[i] < -100 || magnetic_fields[i] > 100) {
                fprintf(stderr, "Warning: Magnetic field value out of range: %f mT\n", magnetic_fields[i]);
            }
        }

        fprintf(log_file, "%f,%f,%f\n", magnetic_fields[0], magnetic_fields[1], magnetic_fields[2]);
        fflush(log_file);

        usleep(SAMPLE_INTERVAL * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

