#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000
#define ADC_CHANNEL_COUNT 3
#define LOG_INTERVAL 1

static int spi_fd;
static FILE *log_file;
static struct gpiod_chip *chip;
static struct gpiod_line *ce0_line;

void close_resources() {
    if (log_file) {
        fclose(log_file);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (ce0_line) {
        gpiod_line_release(ce0_line);
    }
}

void handle_sigint(int sig) {
    close_resources();
    exit(0);
}

uint16_t read_adc_channel(int channel) {
    uint8_t tx[3] = {0x01, 0x80 | (channel << 4), 0x00};
    uint8_t rx[3];
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI_IOC_MESSAGE");
        exit(EXIT_FAILURE);
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open");
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("SPI_IOC_WR_MODE");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("SPI_IOC_WR_BITS_PER_WORD");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    ce0_line = gpiod_chip_get_line(chip, 8); // Assuming CE0 is GPIO8
    if (!ce0_line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(ce0_line, "adc_ce0", 0) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen("sensor_data.csv", "w");
    if (!log_file) {
        perror("fopen");
        gpiod_line_release(ce0_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    fprintf(log_file, "Time,Channel0,Channel1,Channel2\n");

    while (1) {
        time_t now = time(NULL);
        fprintf(log_file, "%ld,", now);

        for (int i = 0; i < ADC_CHANNEL_COUNT; i++) {
            gpiod_line_set_value(ce0_line, 1);
            uint16_t adc_value = read_adc_channel(i);
            gpiod_line_set_value(ce0_line, 0);
            fprintf(log_file, "%d,", adc_value);
        }

        fprintf(log_file, "\n");
        fflush(log_file);
        sleep(LOG_INTERVAL);
    }

    close_resources();
    return EXIT_SUCCESS;
}

