    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("SPI_IOC_WR_MODE");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("SPI_IOC_WR_BITS_PER_WORD");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    ce0_line = gpiod_chip_get_line(chip, 8); // Assuming CE0 is GPIO8
    if (!ce0_line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(ce0_line, "adc_ce0", 0) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen("sensor_data.csv", "w");
    if (!log_file) {
        perror("fopen");
        gpiod_line_release(ce0_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    fprintf(log_file, "Time,Channel0,Channel1,Channel2\n");

    while (1) {
        time_t now = time(NULL);
        fprintf(log_file, "%ld,", now);

        for (int i = 0; i < ADC_CHANNEL_COUNT; i++) {
            gpiod_line_set_value(ce0_line, 1);
            uint16_t adc_value = read_adc_channel(i);
            gpiod_line_set_value(ce0_line, 0);
            fprintf(log_file, "%d,", adc_value);
        }

        fprintf(log_file, "\n");
        fflush(log_file);
        sleep(LOG_INTERVAL);
    }

    close_resources();
    return EXIT_SUCCESS;
}
