#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <mosquitto.h>
#include <cJSON.h>

#define LED_PIN 17
#define MQTT_BROKER "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/led_control"
#define MQTT_CLIENT_ID "rpi_led_control"
#define MAX_RECONNECT_DELAY 60

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

void on_connect(struct mosquitto *mosq, void *obj, int rc) {
    if (rc == 0) {
        printf("Connected to MQTT broker\n");
    } else {
        fprintf(stderr, "Connection failed with error code %d\n", rc);
    }
}

void on_message(struct mosquitto *mosq, void *obj, const struct mosquitto_message *msg) {
    if (msg->topic && !strcmp(msg->topic, MQTT_TOPIC) && msg->payloadlen > 0) {
        char *payload = (char *)msg->payload;
        cJSON *root = cJSON_Parse(payload);
        if (root != NULL) {
            cJSON *led_state = cJSON_GetObjectItemCaseSensitive(root, "led_state");
            if (cJSON_IsBool(led_state)) {
                gpioWrite(LED_PIN, cJSON_IsTrue(led_state));
            } else {
                fprintf(stderr, "Invalid JSON payload: missing or invalid 'led_state'\n");
            }
            cJSON_Delete(root);
        } else {
            fprintf(stderr, "Invalid JSON payload\n");
        }
    }
}

void on_disconnect(struct mosquitto *mosq, void *obj, int rc) {
    if (rc != 0) {
        fprintf(stderr, "Unexpected disconnect from MQTT broker\n");
    }
}

int main() {
    struct mosquitto *mosq = NULL;
    int rc, reconnect_delay = 1;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, PI_LOW);

    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (mosq == NULL) {
        fprintf(stderr, "Failed to create mosquitto instance\n");
        gpioTerminate();
        mosquitto_lib_cleanup();
        return EXIT_FAILURE;
    }

    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_message_callback_set(mosq, on_message);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
        if (rc != MOSQ_ERR_SUCCESS) {
            fprintf(stderr, "Failed to connect to MQTT broker: %s\n", mosquitto_strerror(rc));
            sleep(reconnect_delay);
            reconnect_delay = reconnect_delay * 2;
            if (reconnect_delay > MAX_RECONNECT_DELAY) {
                reconnect_delay = MAX_RECONNECT_DELAY;
            }
        } else {
            rc = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
            if (rc != MOSQ_ERR_SUCCESS) {
                fprintf(stderr, "Failed to subscribe to topic: %s\n", mosquitto_strerror(rc));
                mosquitto_disconnect(mosq);
            } else {
                mosquitto_loop_start(mosq);
                while (running) {
                    sleep(1);
                }
                mosquitto_loop_stop(mosq, true);
            }
        }
    }

    gpioWrite(LED_PIN, PI_LOW);
    gpioTerminate();
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();

    return EXIT_SUCCESS;
}

