#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_DO 17
#define GPIO_LED 18
#define DELAY_MS 100
#define BLINK_DURATION_MS 1000

static struct gpiod_chip *chip;
static struct gpiod_line *do_line;
static struct gpiod_line *led_line;

void cleanup(int signum) {
    if (do_line) {
        gpiod_line_release(do_line);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(signum);
}

int main() {
    int ret;

    // Register signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request GPIO lines
    do_line = gpiod_chip_get_line(chip, GPIO_DO);
    if (!do_line) {
        perror("Failed to get DO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(do_line, "sound_sensor");
    if (ret < 0) {
        perror("Failed to request DO line as input");
        gpiod_line_release(do_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, GPIO_LED);
    if (!led_line) {
        perror("Failed to get LED line");
        gpiod_line_release(do_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(led_line, "alarm_led", 0);
    if (ret < 0) {
        perror("Failed to request LED line as output");
        gpiod_line_release(do_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        int sound_level = gpiod_line_get_value(do_line);
        if (sound_level < 0) {
            perror("Failed to read sound level");
            cleanup(EXIT_FAILURE);
        }

        printf("Sound level: %d\n", sound_level);

        if (sound_level == 0) {
            // Blink LED for 1 second
            gpiod_line_set_value(led_line, 1);
            usleep(BLINK_DURATION_MS * 1000);
            gpiod_line_set_value(led_line, 0);
            usleep(BLINK_DURATION_MS * 1000);
        }

        usleep(DELAY_MS * 1000);
    }

    // This line should never be reached
    cleanup(EXIT_SUCCESS);
    return EXIT_SUCCESS;
}

