#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define LOG_FILE "/var/log/vibration_shutdown.log"

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_event event;
    FILE *log_file;
    char timestamp[20];
    time_t now;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request line for falling-edge event detection
    if (gpiod_line_request_falling_edge_events(line, "vibration-monitor")) {
        perror("Failed to request line for falling-edge events");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!stop_flag) {
        if (gpiod_line_event_wait(line, NULL)) {
            perror("Failed to wait for line event");
            continue;
        }

        if (gpiod_line_event_read(line, &event)) {
            perror("Failed to read line event");
            continue;
        }

        // Get current timestamp
        time(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        // Log and print the event
        fprintf(log_file, "%s: Vibration detected\n", timestamp);
        printf("%s: Vibration detected\n", timestamp);

        // Shutdown the system
        if (system("sudo shutdown -h now")) {
            perror("Failed to shutdown system");
        }
    }

    // Cleanup
    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

