#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define BMP280_I2C_ADDR 0x76
#define BMP280_CHIP_ID_REG 0xD0
#define BMP280_CALIB_START_REG 0x88
#define BMP280_CALIB_END_REG 0xA1
#define BMP280_CTRL_MEAS_REG 0xF4
#define BMP280_PRESSURE_REG 0xF7
#define BMP280_TEMP_REG 0xFA
#define BMP280_SEA_LEVEL_PRESSURE 101325.0

#define I2C_BUS 1
#define I2C_SDA_PIN 2
#define I2C_SCL_PIN 3

void log_altitude(double altitude) {
    FILE *log_file = fopen("altitude_log.txt", "a");
    if (!log_file) {
        perror("Failed to open altitude_log.txt");
        return;
    }

    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

    fprintf(log_file, "%s: Altitude = %.2f meters\n", timestamp, altitude);
    fflush(log_file);
    fclose(log_file);
}

void handle_error(int status, const char *message) {
    if (status < 0) {
        fprintf(stderr, "Error: %s\n", message);
        exit(EXIT_FAILURE);
    }
}

void cleanup(int i2c_handle, FILE *log_file) {
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_SDA_PIN, I2C_SCL_PIN);
    handle_error(i2c_handle, "Failed to open I2C bus");

    uint8_t chip_id;
    handle_error(i2cReadByteData(i2c_handle, BMP280_I2C_ADDR, BMP280_CHIP_ID_REG, &chip_id),
                 "Failed to read chip ID");
    if (chip_id != 0x58) {
        fprintf(stderr, "BMP280 chip ID mismatch: 0x%02X\n", chip_id);
        cleanup(i2c_handle, NULL);
        return EXIT_FAILURE;
    }

    uint8_t calib_data[24];
    handle_error(i2cReadBlockData(i2c_handle, BMP280_I2C_ADDR, BMP280_CALIB_START_REG, calib_data, 24),
                 "Failed to read calibration data");

    // Bosch compensation formulas (omitted for brevity)

    uint8_t ctrl_meas = 0x27; // Normal mode, temp oversample x1, pressure oversample x1
    handle_error(i2cWriteByteData(i2c_handle, BMP280_I2C_ADDR, BMP280_CTRL_MEAS_REG, ctrl_meas),
