#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define BUFFER_SIZE 120
#define FILENAME "temp_log.dat"

volatile int running = 1;
float buffer[BUFFER_SIZE];
int buffer_index = 0;

void signal_handler(int sig) {
    running = 0;
}

float read_temperature() {
    uint8_t tx[] = {0x01, 0x80, 0x00};
    uint8_t rx[3];
    int rc = spi_xfer(SPI_CHANNEL, tx, rx, 3);
    if (rc < 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", rc);
        return -1.0;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

void log_temperature(float temperature) {
    FILE *file = fopen(FILENAME, "wb+");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for logging: %s\n", FILENAME);
        return;
    }
    fseek(file, 0, SEEK_SET);
    fwrite(buffer, sizeof(float), BUFFER_SIZE, file);
    fclose(file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (spiOpen(SPI_CHANNEL, SPI_SPEED, 0) < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        float temperature = read_temperature();
        if (temperature >= 0.0) {
            buffer[buffer_index] = temperature;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;
            printf("Temperature: %.2f °C\n", temperature);
            log_temperature(temperature);
        }
        sleep(5);
    }

    spiClose(SPI_CHANNEL);
    gpioTerminate();
    return 0;
}

