#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define LOG_FILE "flame_events.log"
#define PULL_DOWN gpiod_line_request_bias_PULL_DOWN

volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

void log_event(int pin, int state) {
    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    fprintf(log, "%ld,%d,%d\n", now, pin, state);
    fclose(log);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    // Register signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request line for input with pull-down
    ret = gpiod_line_request_input(line, "flame_sensor", PULL_DOWN);
    if (ret < 0) {
        perror("Failed to request GPIO line for input");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open log file
    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        perror("Failed to open log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (running) {
        int state = gpiod_line_get_value(line);
        if (state < 0) {
            perror("Failed to read GPIO line");
            break;
        }

        if (state) {
            printf("Flame detected!\n");
            log_event(GPIO_LINE, state);
        } else {
            log_event(GPIO_LINE, state);
        }

        sleep(1);
    }

    // Clean up
    fclose(log);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

