#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define SPI_MODE 0
#define MCP3008_ADDRESS 0x48
#define MCP4725_ADDRESS 0x62
#define MCP4725_COMMAND 0x40
#define TEMP_RANGE_MIN 0
#define TEMP_RANGE_MAX 50
#define DAC_RANGE_MIN 0
#define DAC_RANGE_MAX 3.3
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL 500000

void log_temperature(double temperature, double voltage) {
    FILE *log = fopen(LOG_FILE, "a");
    if (log == NULL) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    fprintf(log, "%s, %.2f°C, %.2fV\n", ctime(&now), temperature, voltage);
    fclose(log);
}

void write_dac(double voltage) {
    int fd = i2cOpen(1, MCP4725_ADDRESS, 0);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        return;
    }
    uint16_t value = (uint16_t)((voltage / DAC_RANGE_MAX) * 4095);
    uint8_t data[2] = {MCP4725_COMMAND | (value >> 8), value & 0xFF};
    if (i2cWriteDevice(fd, data, 2) < 0) {
        fprintf(stderr, "Failed to write to MCP4725\n");
    }
    i2cClose(fd);
}

double read_temperature() {
    int fd = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (fd < 0) {
        fprintf(stderr, "Failed to open SPI channel %d\n", SPI_CHANNEL);
        return -1;
    }
    uint8_t data[3] = {1, (8 << 4) | 0, 0};
    if (spiXfer(fd, data, 3) < 0) {
        fprintf(stderr, "Failed to read from MCP3008\n");
        spiClose(fd);
        return -1;
    }
    spiClose(fd);
    uint16_t adc_value = ((data[1] & 3) << 8) | data[2];
