    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d Sensor %d: %d\n",
            tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
            tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec, sensor, adc_value);
    fclose(log_file);
}

int read_adc(int channel) {
    char tx[3] = {1, (8 + channel) << 4, 0};
    char rx[3];
    int result = spiXfer(SPI_CHANNEL, tx, rx, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }
    return ((rx[1] & 3) << 8) | rx[2];
}

void handle_sigint(int sig) {
    spiClose(SPI_CHANNEL);
    gpioTerminate();
    printf("Goodbye!\n");
    exit(0);
}

