    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int adc_value = read_adc(i);
            if (adc_value >= 0) {
                int moisture = (1.0 - (adc_value / (float)ADC_MAX)) * 100.0;
                log_moisture(i, adc_value);
                printf("Sensor %d: %d (Moisture: %.2f%%)\n", i, adc_value, moisture);
            } else {
                fprintf(stderr, "Invalid ADC value from sensor %d\n", i);
            }
        }
        gpioDelay(SLEEP_INTERVAL);
    }

    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

