#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define RELAY_COUNT 4
#define RELAY_PINS[17, 22, 23, 24]

static struct gpiod_chip *chip;
static struct gpiod_line *lines[RELAY_COUNT];

void cleanup(int signum) {
    for (int i = 0; i < RELAY_COUNT; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 0); // Ensure all relays are off
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(signum);
}

int main() {
    // Register signal handlers for graceful exit
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request control of the relay lines
    for (int i = 0; i < RELAY_COUNT; i++) {
        lines[i] = gpiod_chip_get_line(chip, RELAY_PINS[i]);
        if (!lines[i]) {
            perror("Failed to get GPIO line");
            cleanup(EXIT_FAILURE);
        }

        if (gpiod_line_request_output(lines[i], "relay_seq", 0)) {
            perror("Failed to request output on GPIO line");
            cleanup(EXIT_FAILURE);
        }
    }

    // Main loop
    while (1) {
        for (int i = 0; i < RELAY_COUNT; i++) {
            if (gpiod_line_set_value(lines[i], 1)) {
                perror("Failed to set relay line high");
                cleanup(EXIT_FAILURE);
            }
            sleep(1); // Activate relay for 1 second

            if (gpiod_line_set_value(lines[i], 0)) {
                perror("Failed to set relay line low");
                cleanup(EXIT_FAILURE);
            }
            sleep(1); // Deactivate relay for 1 second
        }
    }

    // This line should never be reached
    return EXIT_SUCCESS;
}

