        log_timestamp("Failed to set LED pin mode");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SPI_CE, PI_OUTPUT) < 0) {
        log_timestamp("Failed to set SPI CE pin mode");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(SPI_CE, 0) < 0) {
        log_timestamp("Failed to set SPI CE pin low");
        gpioTerminate();
        return EXIT_FAILURE;
