#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <signal.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define MOTOR_IN1 17
#define MOTOR_IN2 18
#define MOTOR_ENA 27
#define PWM_RANGE 255
#define PWM_SPEED 150
#define RAIN_SENSOR_CHANNEL 0
#define RAIN_LOG_FILE "rain_log.txt"
#define RAIN_THRESHOLD 5

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

int read_rain_sensor(int spi_handle) {
    uint8_t tx[3] = {0x01, (0x08 | RAIN_SENSOR_CHANNEL) << 4, 0x00};
    uint8_t rx[3];
    int result;

    if ((result = spiXfer(spi_handle, tx, rx, 3)) != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    int rain_level = (1023 - adc_value) * 10 / 1023;
    return rain_level;
}

void control_motor(int gpio_in1, int gpio_in2, int gpio_ena, int direction, int speed) {
    gpioWrite(gpio_in1, direction);
    gpioWrite(gpio_in2, !direction);
    gpioPWM(gpio_ena, speed);
}

int main() {
    int spi_handle, log_fd;
    FILE *log_file = NULL;
    time_t now;
    struct tm *tm_info;
    int rain_level;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if ((spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE)) < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if ((log_fd = open(RAIN_LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644)) < 0) {
        fprintf(stderr, "Log file open failed: %d\n", log_fd);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fdopen(log_fd, "a");
    if (log_file == NULL) {
        fprintf(stderr, "fdopen failed\n");
        close(log_fd);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(MOTOR_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR_ENA, PI_OUTPUT);
    gpioSetPWMrange(MOTOR_ENA, PWM_RANGE);
    gpioSetPWMfrequency(MOTOR_ENA, 1000);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    control_motor(MOTOR_IN1, MOTOR_IN2, MOTOR_ENA, 0, 0); // Start with the window open

    while (!stop_flag) {
        rain_level = read_rain_sensor(spi_handle);
        if (rain_level >= 0) {
            time(&now);
            tm_info = localtime(&now);
            fprintf(log_file, "%s Rain level: %d\n", asctime(tm_info), rain_level);
            fflush(log_file);

            if (rain_level >= RAIN_THRESHOLD) {
                control_motor(MOTOR_IN1, MOTOR_IN2, MOTOR_ENA, 1, PWM_SPEED);
                sleep(3);
                control_motor(MOTOR_IN1, MOTOR_IN2, MOTOR_ENA, 0, 0);
            } else {
                control_motor(MOTOR_IN1, MOTOR_IN2, MOTOR_ENA, 0, PWM_SPEED);
                sleep(3);
                control_motor(MOTOR_IN1, MOTOR_IN2, MOTOR_ENA, 1, PWM_SPEED);
            }
        } else {
            sleep(1);
        }
    }

    control_motor(MOTOR_IN1, MOTOR_IN2, MOTOR_ENA, 0, 0);
    close(log_fd);
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

