#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define MIC_PIN 26
#define LED_PIN 16
#define THRESHOLD 700
#define DEBOUNCE_TIME 50
#define LED_ON_TIME 500

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MIC_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", MIC_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetPullUpDown(MIC_PIN, PI_PUD_DOWN);

    signal(SIGINT, sigint_handler);

    while (running) {
        int adc_value = gpioRead(MIC_PIN);
        if (adc_value > THRESHOLD) {
            time_t now = time(NULL);
            printf("Clap detected at %s", ctime(&now));
            gpioWrite(LED_PIN, 1);
            gpioDelay(LED_ON_TIME * 1000);
            gpioWrite(LED_PIN, 0);
            gpioDelay(DEBOUNCE_TIME * 1000);
        }
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

