#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>

#define GPIO_PIN 17
#define GPIO_PATH "/sys/class/gpio/gpio%d/value"
#define LOG_FILE "distance_log.txt"
#define A 26.0
#define B -6.0
#define PROXIMITY_THRESHOLD 200.0

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_distance(double distance) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline character
    fprintf(log_file, "%s, Distance: %.2f mm\n", timestamp, distance);
    fclose(log_file);
}

double read_distance() {
    char gpio_path[256];
    snprintf(gpio_path, sizeof(gpio_path), GPIO_PATH, GPIO_PIN);

    int fd = open(gpio_path, O_RDONLY);
    if (fd == -1) {
        perror("Failed to open GPIO value file");
        return -1;
    }

    char value_str[2];
    if (read(fd, value_str, sizeof(value_str) - 1) != 1) {
        perror("Failed to read GPIO value");
        close(fd);
        return -1;
    }
    close(fd);

    int value = atoi(value_str);
    double voltage = (double)value * 3.3;
    double distance = A / voltage + B;
    return distance;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    char export_path[256];
    snprintf(export_path, sizeof(export_path), "/sys/class/gpio/export");
    int export_fd = open(export_path, O_WRONLY);
    if (export_fd == -1) {
        perror("Failed to open GPIO export file");
        return EXIT_FAILURE;
    }
    write(export_fd, &GPIO_PIN, sizeof(GPIO_PIN));
    close(export_fd);

    char direction_path[256];
    snprintf(direction_path, sizeof(direction_path), "/sys/class/gpio/gpio%d/direction", GPIO_PIN);
    int direction_fd = open(direction_path, O_WRONLY);
    if (direction_fd == -1) {
        perror("Failed to open GPIO direction file");
        close(export_fd);
        return EXIT_FAILURE;
    }
    write(direction_fd, "in", 2);
    close(direction_fd);

    while (running) {
        double distance = read_distance();
        if (distance != -1) {
            log_distance(distance);
            if (distance < PROXIMITY_THRESHOLD) {
                printf("Feeder Activated\n");
            } else {
                printf("Feeder Idle\n");
            }
        }
        sleep(1);
    }

    char unexport_path[256];
    snprintf(unexport_path, sizeof(unexport_path), "/sys/class/gpio/unexport");
    int unexport_fd = open(unexport_path, O_WRONLY);
    if (unexport_fd == -1) {
        perror("Failed to open GPIO unexport file");
        return EXIT_FAILURE;
    }
    write(unexport_fd, &GPIO_PIN, sizeof(GPIO_PIN));
    close(unexport_fd);

    return EXIT_SUCCESS;
}

