#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 500000
#define DRY_ADC 800
#define WET_ADC 300
#define THRESHOLD 30
#define SAMPLE_INTERVAL 60

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static int spidev_fd;
static FILE *log_file;

void handle_sigint(int sig) {
    if (line) {
        gpiod_line_set_value(line, 0);
    }
    if (log_file) {
        fclose(log_file);
    }
    if (spidev_fd >= 0) {
        close(spidev_fd);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

int read_adc(int channel) {
    uint8_t tx[3] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spidev_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI_IOC_MESSAGE");
        return -1;
    }

    return ((rx[1] & 3) << 8) | rx[2];
}

int main() {
    struct timespec ts;
    int adc_value, moisture_percentage, pump_status = 0;

    signal(SIGINT, handle_sigint);

    // Initialize GPIO
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(line, "pump", 0) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return 1;
    }

    // Initialize SPI
    spidev_fd = open(SPI_DEVICE, O_RDWR);
    if (spidev_fd < 0) {
        perror("open");
        gpiod_chip_close(chip);
        return 1;
    }

    if (ioctl(spidev_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("SPI_IOC_WR_MODE");
        close(spidev_fd);
        gpiod_chip_close(chip);
        return 1;
    }

    if (ioctl(spidev_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("SPI_IOC_WR_BITS_PER_WORD");
        close(spidev_fd);
        gpiod_chip_close(chip);
        return 1;
    }

    if (ioctl(spidev_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        close(spidev_fd);
        gpiod_chip_close(chip);
        return 1;
    }

    // Initialize log file
    log_file = fopen("soil_moisture.log", "a");
    if (!log_file) {
        perror("fopen");
        close(spidev_fd);
        gpiod_chip_close(chip);
        return 1;
    }

    while (1) {
        adc_value = read_adc(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue;
        }

        moisture_percentage = (100 * (DRY_ADC - adc_value)) / (DRY_ADC - WET_ADC);
        if (moisture_percentage < THRESHOLD) {
            pump_status = 1;
            gpiod_line_set_value(line, 1);
        } else {
            pump_status = 0;
            gpiod_line_set_value(line, 0);
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld.%09ld, %d%%, %s\n", ts.tv_sec, ts.tv_nsec, moisture_percentage, pump_status ? "ON" : "OFF");
        fflush(log_file);

        sleep(SAMPLE_INTERVAL);
    }

    return 0;
}

