#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <time.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 8
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define ADC_CHANNEL 0
#define VREF_MV 3300
#define VCC_MV 3300
#define SENSITIVITY_MV_MT 100
#define QUIESCENT_MV 1650
#define SAMPLE_INTERVAL_MS 500
#define LOG_FILE "magnetic_log.txt"

static int spi_fd;
static struct gpiod_chip *gpio_chip;
static struct gpiod_line *gpio_line;

static int open_spi_device(const char *device) {
    spi_fd = open(device, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }
    return 0;
}

static int setup_spi() {
    uint8_t mode = SPI_MODE;
    uint8_t bits_per_word = SPI_BITS_PER_WORD;
    uint32_t speed = SPI_SPEED;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        return -1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits_per_word) < 0) {
        perror("Failed to set SPI bits per word");
        return -1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        return -1;
    }
    return 0;
}

static int open_gpio_chip(const char *chip) {
    gpio_chip = gpiod_chip_open_by_name(chip);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }
    return 0;
}

static int request_gpio_line(int line) {
    gpio_line = gpiod_chip_get_line(gpio_chip, line);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        return -1;
    }
    if (gpiod_line_request_output(gpio_line, "drv5055_cs", 0) < 0) {
        perror("Failed to request GPIO line as output");
        return -1;
    }
    return 0;
}

static int read_adc_value() {
    uint8_t tx[3] = {1, (ADC_CHANNEL + 8) << 4, 0};
    uint8_t rx[3];
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Failed to perform SPI transfer");
        return -1;
    }
    return ((rx[1] & 3) << 8) | rx[2];
}

static void log_magnetic_field(double B_mt) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    fprintf(log_file, "%ld,%.2f\n", now, B_mt);
    fclose(log_file);
}

static void handle_signal(int signum) {
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    exit(signum);
}

int main() {
    if (open_spi_device(SPI_DEVICE) < 0) {
        return EXIT_FAILURE;
    }
    if (setup_spi() < 0) {
        close(spi_fd);
        return EXIT_FAILURE;
    }
    if (open_gpio_chip(GPIO_CHIP) < 0) {
        close(spi_fd);
        return EXIT_FAILURE;
    }
    if (request_gpio_line(GPIO_LINE) < 0) {
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        if (gpiod_line_set_value(gpio_line, 0) < 0) {
            perror("Failed to set GPIO line low");
            continue;
        }

        int adc_value = read_adc_value();
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            gpiod_line_set_value(gpio_line, 1);
            continue;
        }

        double Vout_mV = (double)adc_value * VREF_MV / 1023;
        double B_mt = (Vout_mV - QUIESCENT_MV) / SENSITIVITY_MV_MT;

        log_magnetic_field(B_mt);

        if (gpiod_line_set_value(gpio_line, 1) < 0) {
            perror("Failed to set GPIO line high");
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    return EXIT_SUCCESS;
}

