#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define MCP3008_CHANNEL 0
#define LOG_FILE "moisture_log.txt"

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

int read_adc(int channel) {
    uint8_t tx_buf[3] = {0x01, 0x80 | (channel << 4), 0x00};
    uint8_t rx_buf[3] = {0};

    if (gpio_spi_xfer(SPI_CHANNEL, tx_buf, rx_buf, 3) != 3) {
        return -1;
    }

    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

void log_moisture(int adc_value) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, ADC Value: %d\n",
            tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
            tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec, adc_value);

    fclose(log_file);
}

void log_error() {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, Error: ADC read failed\n",
            tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
            tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec);

    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SPI_CE0, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set SPI_CE0 mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SPI_CE0, PI_PUD_OFF) != 0) {
        fprintf(stderr, "Failed to set SPI_CE0 pull-up/pull-down\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SPI_MOSI, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set SPI_MOSI mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SPI_MISO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set SPI_MISO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SPI_SCLK, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set SPI_SCLK mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SPI_SCLK, PI_PUD_OFF) != 0) {
        fprintf(stderr, "Failed to set SPI_SCLK pull-up/pull-down\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SPI_CE0, PI_ALT0) != 0) {
        fprintf(stderr, "Failed to set SPI_CE0 alternate function\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SPI_MOSI, PI_ALT0) != 0) {
        fprintf(stderr, "Failed to set SPI_MOSI alternate function\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SPI_MISO, PI_ALT0) != 0) {
        fprintf(stderr, "Failed to set SPI_MISO alternate function\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SPI_SCLK, PI_ALT0) != 0) {
        fprintf(stderr, "Failed to set SPI_SCLK alternate function\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetSPIOptions(SPI_CHANNEL, SPI_SPEED, SPI_MODE) != 0) {
        fprintf(stderr, "Failed to set SPI options\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    while (!stop_flag) {
        int adc_value = read_adc(MCP3008_CHANNEL);
        if (adc_value == -1) {
            log_error();
        } else {
            log_moisture(adc_value);
        }

        sleep(60);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

