    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        close(spi_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initialize log file
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("fopen");
        close(spi_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    fprintf(log_file, "Timestamp,Current_A\n");

    while (1) {
        uint16_t adc_value;
        read_adc_value(&adc_value);
        double current_A = adc_to_current(adc_value);
        log_current(current_A);
        sleep(1);
    }

    // Clean up
    fclose(log_file);
    close(spi_fd);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}
