#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define MCP3008_CHANNEL 0
#define VDD 5.0
#define VREF 2.5
#define MAX_CURRENT 50.0
#define LOG_FILE "current_log.txt"

volatile sig_atomic_t stop_flag = 0;

void sigint_handler(int signum) {
    stop_flag = 1;
}

int main() {
    int spi_handle;
    FILE *log_file = NULL;
    struct tm *timeinfo;
    char timestamp[20];
    uint8_t tx[3] = {0x01, 0x80 | (MCP3008_CHANNEL << 4), 0x00};
    uint8_t rx[3];
    int raw_value;
    float voltage, current;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel %d\n", SPI_CHANNEL);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (!stop_flag) {
        if (spiXfer(spi_handle, tx, rx, 3) != 3) {
            fprintf(stderr, "SPI transfer error\n");
            continue;
        }

        raw_value = ((rx[1] & 0x03) << 8) | rx[2];
        voltage = (float)raw_value * (VDD / 1023.0);
        current = (voltage - VREF) * (MAX_CURRENT / VREF);

        if (voltage < 0.0 || voltage > VDD) {
            fprintf(stderr, "Voltage out of range: %.2fV\n", voltage);
            continue;
        }

        timeinfo = localtime(&time(NULL));
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
        fprintf(log_file, "%s %.2f A\n", timestamp, current);
        fflush(log_file);
        gpioDelay(100000);
    }

    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

