#define SENSOR1_CHIP 0
#define SENSOR1_LINE 4
#define SENSOR2_CHIP 0
#define SENSOR2_LINE 17
#define DEBOUNCE_SAMPLES 5
#define DEBOUNCE_INTERVAL 2000000 // 2 ms in microseconds

volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

int read_sensor(int chip_num, int line_num) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int value = 0, count = 0;

    chip = gpiod_chip_open_by_number(chip_num);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, line_num);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    for (int i = 0; i < DEBOUNCE_SAMPLES; i++) {
        int ret = gpiod_line_get_value(line);
        if (ret < 0) {
            perror("Failed to read GPIO line");
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            return -1;
        }
        if (ret == 0) {
            value++;
        }
        usleep(DEBOUNCE_INTERVAL);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return (value >= DEBOUNCE_SAMPLES / 2);
}

