#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define READ_DELAY 60
#define MIN_ADC 300
#define MAX_ADC 800
#define LOG_FILE "soil_moisture_log.csv"

volatile sig_atomic_t terminate = 0;

void signal_handler(int signal) {
    terminate = 1;
}

int read_mcp3008(int channel) {
    uint8_t tx_buf[3] = {0x01, 0x80 | (channel << 4), 0x00};
    uint8_t rx_buf[3];
    int status = spi_xfer(SPI_CHANNEL, tx_buf, rx_buf, 3);
    if (status < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(status));
        return -1;
    }
    return ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
}

double calculate_moisture_level(int adc_value) {
    if (adc_value < MIN_ADC) adc_value = MIN_ADC;
    if (adc_value > MAX_ADC) adc_value = MAX_ADC;
    return 100.0 - ((adc_value - MIN_ADC) / (double)(MAX_ADC - MIN_ADC)) * 100.0;
}

void log_data(double moisture_level) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, moisture_level);
    fclose(log_file);

    printf("%s,%.2f\n", timestamp, moisture_level);
}

int spi_setup(spi_config_t config) {
    int status = spi_open(SPI_CHANNEL, SPI_BAUD, 0);
    if (status < 0) {
        fprintf(stderr, "Failed to open SPI channel: %s\n", strerror(status));
        return -1;
    }
    return status;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    spi_config_t config = {SPI_CHANNEL, SPI_BAUD, 0};
    if (spi_setup(config) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value >= 0) {
            double moisture_level = calculate_moisture_level(adc_value);
            log_data(moisture_level);
        }
        sleep(READ_DELAY);
    }

    spi_close(SPI_CHANNEL);
    gpioTerminate();
    return EXIT_SUCCESS;
}

