#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <sys/stat.h>
#include <libgpiod.h>
#include <syslog.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define DEBOUNCE_TIME 200
#define POLL_INTERVAL 50
#define IMAGE_DIR "/home/pi/security_cam/"
#define IMAGE_FORMAT "%s/security_cam_%Y%m%d%H%M%S.jpg"

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int line_value = 0, last_line_value = 0;
    pid_t pid;
    char timestamp[20];
    char image_path[256];
    struct stat dir_stat;

    // Initialize syslog
    openlog("motion_detector", LOG_PID, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        closelog();
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        syslog(LOG_ERR, "Failed to get GPIO line");
        gpiod_chip_close(chip);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    // Request GPIO line as input with pull-down resistor
    if (gpiod_line_request_input(line, "motion_detector") < 0) {
        syslog(LOG_ERR, "Failed to request GPIO line as input");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create image directory if it doesn't exist
    if (stat(IMAGE_DIR, &dir_stat) != 0) {
        if (mkdir(IMAGE_DIR, 0755) != 0) {
            syslog(LOG_ERR, "Failed to create image directory");
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            gpioTerminate();
            closelog();
            return EXIT_FAILURE;
        }
    }

    // Main loop
    while (!stop_flag) {
        // Read GPIO line value
        line_value = gpiod_line_get_value(line);
        if (line_value < 0) {
            syslog(LOG_ERR, "Failed to read GPIO line value");
            continue;
        }

        // Check for state change
        if (line_value != last_line_value) {
            // Apply debounce delay
            usleep(DEBOUNCE_TIME * 1000);

            // Re-read GPIO line value
            line_value = gpiod_line_get_value(line);
            if (line_value < 0) {
                syslog(LOG_ERR, "Failed to read GPIO line value after debounce");
                continue;
            }

            // Check for state change after debounce
            if (line_value != last_line_value) {
                // Motion detected
                syslog(LOG_INFO, "Motion detected");

                // Capture image
                time_t now = time(NULL);
                strftime(timestamp, sizeof(timestamp), IMAGE_FORMAT, localtime(&now));
                snprintf(image_path, sizeof(image_path), "%s", timestamp);

                pid = fork();
                if (pid == 0) {
                    // Child process
                    char *args[] = {"libcamera-still", "-o", image_path, "-t", "0", "-r", "-ISO", "8601", NULL};
                    execvp("libcamera-still", args);
                    syslog(LOG_ERR, "Failed to execute libcamera-still");
                    exit(EXIT_FAILURE);
                } else if (pid > 0) {
                    // Parent process
                    int status;
                    if (waitpid(pid, &status, 0) < 0) {
                        syslog(LOG_ERR, "Failed to wait for libcamera-still");
                    } else if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
                        syslog(LOG_ERR, "libcamera-still capture failed with status %d", WEXITSTATUS(status));
                    } else {
                        syslog(LOG_INFO, "Image captured successfully: %s", image_path);
                    }
                } else {
                    syslog(LOG_ERR, "Failed to fork");
                }
            }
        }

        last_line_value = line_value;
        usleep(POLL_INTERVAL * 1000);
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    gpioTerminate();
    closelog();

    return EXIT_SUCCESS;
}

