static int open_device(const char *device_name) {
    int fd = open(device_name, O_RDWR);
    if (fd == -1) {
        perror("Failed to open device");
    }
    return fd;
}

static int init_device(int fd) {
    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("Failed to query device capabilities");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device is not a video capture device\n");
        return -1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_GREY;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("Failed to set format");
        return -1;
    }

    return 0;
}

static int request_buffers(int fd, struct buffer *buffers, unsigned int count) {
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = count;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("Failed to request buffers");
        return -1;
    }

    for (unsigned int i = 0; i < count; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            perror("Failed to query buffer");
            return -1;
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffers[i].start == MAP_FAILED) {
            perror("Failed to mmap buffer");
            return -1;
        }
    }

    return 0;
}

static int queue_buffers(int fd, struct buffer *buffers, unsigned int count) {
    for (unsigned int i = 0; i < count; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            perror("Failed to queue buffer");
            return -1;
        }
    }

    return 0;
}

static int start_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("Failed to start streaming");
        return -1;
    }

    return 0;
}

static int stop_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        perror("Failed to stop streaming");
        return -1;
    }

    return 0;
}

static int dequeue_buffer(int fd, struct buffer *buffers, unsigned int count) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    fd_set fds;
    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    struct timeval timeout;
    timeout.tv_sec = 2;
    timeout.tv_usec = 0;

    int ret = select(fd + 1, &fds, NULL, NULL, &timeout);
    if (ret == -1) {
        perror("Failed to select");
        return -1;
    } else if (ret == 0) {
        fprintf(stderr, "Timeout waiting for buffer\n");
        return -1;
    }

    if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("Failed to dequeue buffer");
        return -1;
    }

    if (buf.index >= count) {
        fprintf(stderr, "Invalid buffer index\n");
        return -1;
    }

    return buf.index;
}

static int enqueue_buffer(int fd, struct buffer *buffers, unsigned int index) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = index;

    if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        perror("Failed to enqueue buffer");
        return -1;
    }

    return 0;
}

static void unmap_buffers(int fd, struct buffer *buffers, unsigned int count) {
    for (unsigned int i = 0; i < count; i++) {
        if (munmap(buffers[i].start, buffers[i].length) == -1) {
            perror("Failed to unmap buffer");
        }
    }
}

static void close_device(int fd) {
    if (fd != -1) {
        close(fd);
    }
}

static void signal_handler(int signum) {
    printf("Received signal %d, stopping...\n", signum);
    exit(0);
}

int main(int argc, char *argv[]) {
    const char *device_name = argc > 1 ? argv[1] : "/dev/video0";
    int fd = open_device(device_name);
    if (fd == -1) {
        return EXIT_FAILURE;
    }

    if (init_device(fd) == -1) {
        close_device(fd);
        return EXIT_FAILURE;
    }

    struct buffer buffers[BUFFER_COUNT];
    if (request_buffers(fd, buffers, BUFFER_COUNT) == -1) {
        close_device(fd);
        return EXIT_FAILURE;
    }

    if (queue_buffers(fd, buffers, BUFFER_COUNT) == -1) {
        unmap_buffers(fd, buffers, BUFFER_COUNT);
        close_device(fd);
        return EXIT_FAILURE;
    }

    if (start_streaming(fd) == -1) {
        unmap_buffers(fd, buffers, BUFFER_COUNT);
        close_device(fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    unsigned int frame_count = 0;
    while (1) {
        int index = dequeue_buffer(fd, buffers, BUFFER_COUNT);
        if (index == -1) {
            break;
        }

        char filename[256];
        snprintf(filename, sizeof(filename), "%s%04u.pgm", FILENAME_PREFIX, frame_count + 1);
        FILE *file = fopen(filename, "wb");
        if (file == NULL) {
            perror("Failed to open file");
            break;
        }

        fprintf(file, "P5\n%d %d\n255\n", WIDTH, HEIGHT);
        fwrite(buffers[index].start, 1, buffers[index].length, file);
        fclose(file);

        enqueue_buffer(fd, buffers, index);
        frame_count++;
    }

    stop_streaming(fd);
    unmap_buffers(fd, buffers, BUFFER_COUNT);
    close_device(fd);

    return EXIT_SUCCESS;
}

