#include <signal.h>
#include <time.h>

#define DEVICE "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define BUFFER_COUNT 4

static int fd;
static struct v4l2_buffer buf[BUFFER_COUNT];
static void *buffers[BUFFER_COUNT];
static FILE *log_file;
static volatile sig_atomic_t running = 1;

static void signal_handler(int signum) {
    running = 0;
}

static void init_v4l2() {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf_req;

    fd = open(DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Failed to query device capabilities");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(fd);
        exit(EXIT_FAILURE);
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Failed to set video format");
        close(fd);
        exit(EXIT_FAILURE);
    }

    memset(&req, 0, sizeof(req));
    req.count = BUFFER_COUNT;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Failed to request buffers");
        close(fd);
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < BUFFER_COUNT; i++) {
        memset(&buf_req, 0, sizeof(buf_req));
        buf_req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf_req.memory = V4L2_MEMORY_MMAP;
        buf_req.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf_req) < 0) {
            perror("Failed to query buffer");
            close(fd);
            exit(EXIT_FAILURE);
        }

        buffers[i] = mmap(NULL, buf_req.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf_req.m.offset);
        if (buffers[i] == MAP_FAILED) {
            perror("Failed to map buffer");
            close(fd);
            exit(EXIT_FAILURE);
        }

        memset(&buf[i], 0, sizeof(buf[i]));
        buf[i].type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf[i].memory = V4L2_MEMORY_MMAP;
        buf[i].index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf[i]) < 0) {
            perror("Failed to queue buffer");
            close(fd);
            exit(EXIT_FAILURE);
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Failed to start streaming");
        close(fd);
        exit(EXIT_FAILURE);
    }
}

static void capture_frames() {
    fd_set read_fds;
    struct timeval timeout;
    struct v4l2_buffer buf_req;
    struct timespec ts;

    while (running) {
        FD_ZERO(&read_fds);
        FD_SET(fd, &read_fds);
        timeout.tv_sec = 1;
        timeout.tv_usec = 0;

        if (select(fd + 1, &read_fds, NULL, NULL, &timeout) < 0) {
            perror("Select failed");
            continue;
        }

        if (FD_ISSET(fd, &read_fds)) {
            memset(&buf_req, 0, sizeof(buf_req));
            buf_req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
            buf_req.memory = V4L2_MEMORY_MMAP;

            if (ioctl(fd, VIDIOC_DQBUF, &buf_req) < 0) {
                perror("Failed to dequeue buffer");
                continue;
            }

            clock_gettime(CLOCK_MONOTONIC, &ts);
            fprintf(log_file, "%ld.%06ld\n", ts.tv_sec, ts.tv_nsec / 1000);

            if (ioctl(fd, VIDIOC_QBUF, &buf_req) < 0) {
                perror("Failed to queue buffer");
            }
        }
    }
}

static void cleanup() {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Failed to stop streaming");
    }

    for (int i = 0; i < BUFFER_COUNT; i++) {
        if (munmap(buffers[i], buf[i].length) < 0) {
            perror("Failed to unmap buffer");
        }
    }

    close(fd);
    fclose(log_file);
}

int main() {
    signal(SIGINT, signal_handler);

    log_file = fopen("frame_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    init_v4l2();
    capture_frames();

    cleanup();
    return EXIT_SUCCESS;
}
