        perror("Invalid server IP address");
        close(sock);
        close(fd);
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int frame_index = 0;
    while (1) {
        for (int i = 0; i < NUM_BUFFERS; i++) {
            if (ioctl(fd, VIDIOC_DQBUF, &buf[i]) < 0) {
                perror("Failed to dequeue buffer");
                close(sock);
                close(fd);
                return 1;
            }

            int payload_size = buf[i].bytesused;
            int fragment_count = (payload_size + MAX_DATAGRAM_SIZE - 1) / MAX_DATAGRAM_SIZE;
            for (int fragment_index = 0; fragment_index < fragment_count; fragment_index++) {
                Header header = {
                    .frame_index = frame_index,
                    .fragment_index = fragment_index,
                    .total_fragments = fragment_count,
                    .payload_size = payload_size
                };

                int datagram_size = sizeof(header) + payload_size;
                if (datagram_size > MAX_DATAGRAM_SIZE) {
                    datagram_size = MAX_DATAGRAM_SIZE;
                    payload_size = MAX_DATAGRAM_SIZE - sizeof(header);
                }

                if (sendto(sock, &header, sizeof(header), 0, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
                    perror("Failed to send header");
                    close(sock);
                    close(fd);
                    return 1;
                }

                if (sendto(sock, buf[i].m.userptr + fragment_index * MAX_DATAGRAM_SIZE, payload_size, 0, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
                    perror("Failed to send payload");
                    close(sock);
                    close(fd);
                    return 1;
                }
            }

            if (ioctl(fd, VIDIOC_QBUF, &buf[i]) < 0) {
                perror("Failed to queue buffer");
                close(sock);
                close(fd);
                return 1;
            }
        }

        frame_index++;
    }

    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Failed to stop streaming");
    }

    for (int i = 0; i < NUM_BUFFERS; i++) {
        if (munmap(buf[i].m.userptr, buf[i].length) < 0) {
            perror("Failed to unmap buffer");
        }
    }

    close(sock);
    close(fd);

    return 0;
}

