        gpiod_line_release(tilt_up_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(tilt_down_line, &tilt_down_config) < 0) {
        perror("Failed to request tilt down line");
        gpiod_line_release(pan_line);
        gpiod_line_release(tilt_line);
        gpiod_line_release(pan_left_line);
        gpiod_line_release(pan_right_line);
        gpiod_line_release(tilt_up_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);

    while (1) {
        if (read_button(pan_left_line) == 0) {
            pan_position = (pan_position - 5 + 125) % 125;
            set_servo_duty(pan_line, pan_position);
            usleep(BUTTON_DEBOUNCE_MS * 1000);
        }
        if (read_button(pan_right_line) == 0) {
            pan_position = (pan_position + 5) % 125;
            set_servo_duty(pan_line, pan_position);
            usleep(BUTTON_DEBOUNCE_MS * 1000);
        }
        if (read_button(tilt_up_line) == 0) {
            tilt_position = (tilt_position + 5) % 125;
            set_servo_duty(tilt_line, tilt_position);
            usleep(BUTTON_DEBOUNCE_MS * 1000);
        }
        if (read_button(tilt_down_line) == 0) {
            tilt_position = (tilt_position - 5 + 125) % 125;
            set_servo_duty(tilt_line, tilt_position);
            usleep(BUTTON_DEBOUNCE_MS * 1000);
        }
        usleep(50 * 1000);
    }

    return EXIT_SUCCESS;
}
