#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/time.h>
#include <signal.h>
#include <linux/videodev2.h>
#include <jpeglib.h>

#define WIDTH 640
#define HEIGHT 480
#define BUFFER_COUNT 4
#define KERNEL_RADIUS 2

struct buffer {
    void *start;
    size_t length;
};

static int fd = -1;
static struct buffer *buffers = NULL;
static int buffer_count = 0;
static struct v4l2_format fmt;
static struct v4l2_requestbuffers req;
static struct v4l2_buffer buf;
static struct timeval timeout;
static sig_atomic_t stop = 0;

static void signal_handler(int signum) {
    stop = 1;
}

static void init_camera() {
    fd = open("/dev/video0", O_RDWR);
    if (fd < 0) {
        perror("Failed to open /dev/video0");
        exit(EXIT_FAILURE);
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Failed to set format");
        close(fd);
        exit(EXIT_FAILURE);
    }

    memset(&req, 0, sizeof(req));
    req.count = BUFFER_COUNT;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Failed to request buffers");
        close(fd);
        exit(EXIT_FAILURE);
    }

    buffers = calloc(req.count, sizeof(*buffers));
    if (!buffers) {
        perror("Failed to allocate buffer array");
        close(fd);
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < req.count; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("Failed to query buffer");
            free(buffers);
            close(fd);
            exit(EXIT_FAILURE);
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffers[i].start == MAP_FAILED) {
            perror("Failed to mmap buffer");
            for (int j = 0; j < i; j++) {
                munmap(buffers[j].start, buffers[j].length);
            }
            free(buffers);
            close(fd);
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < req.count; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Failed to queue buffer");
            for (int j = 0; j <= i; j++) {
                munmap(buffers[j].start, buffers[j].length);
            }
            free(buffers);
            close(fd);
            exit(EXIT_FAILURE);
        }
    }

    if (ioctl(fd, VIDIOC_STREAMON, &buf.type) < 0) {
        perror("Failed to start streaming");
        for (int i = 0; i < req.count; i++) {
            munmap(buffers[i].start, buffers[i].length);
        }
        free(buffers);
        close(fd);
        exit(EXIT_FAILURE);
    }
}

static void capture_frame() {
    fd_set fds;
    int ret;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    timeout.tv_sec = 2;
    timeout.tv_usec = 0;

    ret = select(fd + 1, &fds, NULL, NULL, &timeout);
    if (ret < 0) {
        perror("Failed to select");
        return;
    } else if (ret == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        return;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Failed to dequeue buffer");
        return;
    }

    // Process the frame here
    // ...

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Failed to queue buffer");
    }
}

static void save_jpeg(const unsigned char *data, int width, int height, const char *filename) {
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;
    FILE *outfile;
    JSAMPROW row_pointer[1];

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);

    if ((outfile = fopen(filename, "wb")) == NULL) {
        fprintf(stderr, "Can't open %s\n", filename);
        jpeg_destroy_compress(&cinfo);
        return;
    }

    jpeg_stdio_dest(&cinfo, outfile);

    cinfo.image_width = width;
    cinfo.image_height = height;
    cinfo.input_components = 3;
    cinfo.in_color_space = JCS_RGB;

    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, 75, TRUE);

    jpeg_start_compress(&cinfo, TRUE);

    while (cinfo.next_scanline < cinfo.image_height) {
        row_pointer[0] = (JSAMPROW)data + cinfo.next_scanline * width * 3;
        jpeg_write_scanlines(&cinfo, row_pointer, 1);
    }

    jpeg_finish_compress(&cinfo);
    fclose(outfile);
    jpeg_destroy_compress(&cinfo);
}

static void cleanup() {
    if (fd >= 0) {
        if (ioctl(fd, VIDIOC_STREAMOFF, &buf.type) < 0) {
            perror("Failed to stop streaming");
        }
        for (int i = 0; i < buffer_count; i++) {
            munmap(buffers[i].start, buffers[i].length);
        }
        free(buffers);
        close(fd);
    }
}

int main() {
    signal(SIGINT, signal_handler);

    init_camera();

    while (!stop) {
        capture_frame();
    }

    cleanup();

    return 0;
}

