#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

void print_error(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

void print_resolutions(int fd) {
    struct v4l2_frmsizeenum fsize = {0};
    fsize.index = 0;
    fsize.type = V4L2_FRMSIZE_TYPE_DISCRETE;

    printf("Supported resolutions:\n");
    while (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &fsize) == 0) {
        printf("  %ux%u\n", fsize.discrete.width, fsize.discrete.height);
        fsize.index++;
    }
}

void print_frame_rates(int fd, unsigned int width, unsigned int height) {
    struct v4l2_frmivalenum fival = {0};
    fival.index = 0;
    fival.type = V4L2_FRMSIZE_TYPE_DISCRETE;
    fival.pixel_format = V4L2_PIX_FMT_YUYV;
    fival.width = width;
    fival.height = height;

    printf("  Frame rates for %ux%u:\n", width, height);
    while (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &fival) == 0) {
        printf("    %u/%u\n", fival.discrete.numerator, fival.discrete.denominator);
        fival.index++;
    }
}

int main() {
    int fd = open("/dev/video0", O_RDWR);
    if (fd == -1) {
        print_error("Failed to open /dev/video0");
    }

    struct v4l2_capability cap = {0};
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        print_error("Failed to query device capabilities");
    }

    printf("Device: %s\n", cap.card);
    printf("Driver: %s\n", cap.driver);
    printf("Bus info: %s\n", cap.bus_info);

    print_resolutions(fd);

    // Example resolution to check frame rates
    unsigned int width = 640;
    unsigned int height = 480;
    print_frame_rates(fd, width, height);

    struct v4l2_queryctrl qctrl = {0};
    qctrl.id = V4L2_CID_FOCUS_AUTO;
    if (ioctl(fd, VIDIOC_QUERYCTRL, &qctrl) == 0) {
        printf("Autofocus supported: %s\n", qctrl.flags & V4L2_CTRL_FLAG_READ_ONLY ? "No" : "Yes");
    } else {
        printf("Autofocus control not supported\n");
    }

    close(fd);
    return 0;
}

