#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define SERVO_PAN_PIN 4
#define SERVO_TILT_PIN 5
#define BUTTON_UP_PIN 6
#define BUTTON_DOWN_PIN 7
#define BUTTON_LEFT_PIN 8
#define BUTTON_RIGHT_PIN 9
#define SERVO_CENTER 1500
#define SERVO_MIN 1000
#define SERVO_MAX 2000
#define LOOP_DELAY 50000  // 50 ms

volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(SERVO_PAN_PIN, PI_OUTPUT);
    gpioSetMode(SERVO_TILT_PIN, PI_OUTPUT);
    gpioSetMode(BUTTON_UP_PIN, PI_INPUT);
    gpioSetMode(BUTTON_DOWN_PIN, PI_INPUT);
    gpioSetMode(BUTTON_LEFT_PIN, PI_INPUT);
    gpioSetMode(BUTTON_RIGHT_PIN, PI_INPUT);

    gpioSetPullUpDown(BUTTON_UP_PIN, PI_PUD_UP);
    gpioSetPullUpDown(BUTTON_DOWN_PIN, PI_PUD_UP);
    gpioSetPullUpDown(BUTTON_LEFT_PIN, PI_PUD_UP);
    gpioSetPullUpDown(BUTTON_RIGHT_PIN, PI_PUD_UP);

    gpioServo(SERVO_PAN_PIN, SERVO_CENTER);
    gpioServo(SERVO_TILT_PIN, SERVO_CENTER);

    printf("Camera Pan-Tilt Control\n");
    printf("Pan Servo: GPIO%d\n", SERVO_PAN_PIN);
    printf("Tilt Servo: GPIO%d\n", SERVO_TILT_PIN);
    printf("Up Button: GPIO%d\n", BUTTON_UP_PIN);
    printf("Down Button: GPIO%d\n", BUTTON_DOWN_PIN);
    printf("Left Button: GPIO%d\n", BUTTON_LEFT_PIN);
    printf("Right Button: GPIO%d\n", BUTTON_RIGHT_PIN);
    printf("Servo Center Position: %d us\n", SERVO_CENTER);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        if (gpioRead(BUTTON_UP_PIN) == 0) {
            int current = gpioServo(SERVO_TILT_PIN);
            if (current > SERVO_MIN) {
                gpioServo(SERVO_TILT_PIN, current - 10);
            }
            gpioDelay(LOOP_DELAY);
        }

        if (gpioRead(BUTTON_DOWN_PIN) == 0) {
            int current = gpioServo(SERVO_TILT_PIN);
            if (current < SERVO_MAX) {
                gpioServo(SERVO_TILT_PIN, current + 10);
            }
            gpioDelay(LOOP_DELAY);
        }

        if (gpioRead(BUTTON_LEFT_PIN) == 0) {
            int current = gpioServo(SERVO_PAN_PIN);
            if (current > SERVO_MIN) {
                gpioServo(SERVO_PAN_PIN, current - 10);
            }
            gpioDelay(LOOP_DELAY);
        }

        if (gpioRead(BUTTON_RIGHT_PIN) == 0) {
            int current = gpioServo(SERVO_PAN_PIN);
            if (current < SERVO_MAX) {
                gpioServo(SERVO_PAN_PIN, current + 10);
            }
            gpioDelay(LOOP_DELAY);
        }
    }

    gpioServo(SERVO_PAN_PIN, 0);
    gpioServo(SERVO_TILT_PIN, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

