#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>
#include <libcamera-still.h>
#include <curl/curl.h>

#define GPIO_PIN 17
#define DEBOUNCE_TIME 2000
#define CAMERA_COMMAND "libcamera-still -t 1000 -o motion_captures/%s.jpg -q 85 --width 640 --height 480"
#define UPLOAD_URL "http://<server_ip>:<server_port>/upload"
#define TIMESTAMP_FORMAT "%Y-%m-%dT%H:%M:%S.%06fZ"

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

void create_directory(const char *path) {
    if (mkdir(path, 0755) == -1 && errno != EEXIST) {
        perror("mkdir");
        exit(EXIT_FAILURE);
    }
}

void capture_image(const char *filename) {
    char command[256];
    snprintf(command, sizeof(command), CAMERA_COMMAND, filename);
    if (system(command) != 0) {
        perror("libcamera-still");
        exit(EXIT_FAILURE);
    }
}

void send_upload(const char *filename, const char *timestamp, int motion_status, int gpio_pin) {
    CURL *curl;
    CURLcode res;
    struct curl_slist *headers = NULL;
    char json_payload[512];
    time_t now = time(NULL);
    struct tm *tm_info = gmtime(&now);
    char iso_timestamp[20];
    snprintf(iso_timestamp, sizeof(iso_timestamp), TIMESTAMP_FORMAT, tm_info, (double)now - (double)tm_info->tm_sec);

    snprintf(json_payload, sizeof(json_payload), "{\"filename\":\"%s\",\"timestamp\":\"%s\",\"motion_status\":%d,\"gpio_pin\":%d}",
             filename, iso_timestamp, motion_status, gpio_pin);

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if(curl) {
        headers = curl_slist_append(headers, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_URL, UPLOAD_URL);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_payload);
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
        res = curl_easy_perform(curl);
        if(res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }
        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int motion_detected = 0;
    time_t last_motion_time = 0;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    create_directory("motion_captures");

    if ((chip = gpiod_chip_open_by_name("gpiochip0")) == NULL) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    if ((line = gpiod_chip_get_line(chip, GPIO_PIN)) == NULL) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line, "motion_sensor") != 0) {
        perror("gpiod_line_request_input");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (!stop_flag) {
        int value = gpiod_line_get_value(line);
        if (value == 1 && !motion_detected) {
            motion_detected = 1;
            last_motion_time = time(NULL);
        } else if (value == 0 && motion_detected) {
            if (time(NULL) - last_motion_time > DEBOUNCE_TIME / 1000) {
                motion_detected = 0;
                char filename[256];
                time_t now = time(NULL);
                struct tm *tm_info = localtime(&now);
                strftime(filename, sizeof(filename), "motion_%Y%m%d_%H%M%S.jpg", tm_info);
                capture_image(filename);
                send_upload(filename, timestamp, 1, GPIO_PIN);
            }
        }
        usleep(100000);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

