#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define IMAGE_DIR "/home/pi/images"
#define LOG_FILE "/home/pi/motion_capture.log"
#define DEBOUNCE_TIME 50
#define CAMERA_CMD "libcamera-still -o %s --width 640 --height 480 -q 85 --timeout 2000 --nopreview"

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static FILE *log_file;

void log_event(const char *event) {
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
    fprintf(log_file, "[%s] %s\n", timestamp, event);
    fflush(log_file);
}

void capture_image() {
    char filename[256];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(filename, sizeof(filename), "%Y%m%d_%H%M%S_%3ld.jpg", tm_info, (long)now % 1000);

    char cmd[512];
    snprintf(cmd, sizeof(cmd), CAMERA_CMD, filename);

    int ret = system(cmd);
    if (ret != 0) {
        log_event("Failed to capture image");
    } else {
        log_event("Image captured: ");
        fprintf(log_file, "%s\n", filename);
    }
}

void handle_signal(int signum) {
    log_event("Received signal, cleaning up...");
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(log_file);
    exit(signum);
}

int main() {
    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Claim GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Request line as input with edge-rising detection
    struct gpiod_line_request_config config = {
        .consumer = "motion_sensor",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
        .default_val = 0,
        .flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP,
    };
    int ret = gpiod_line_request(line, &config);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    log_event("Motion sensor started");

    while (1) {
        int value = gpiod_line_get_value(line);
        if (value == 1) {
            // Wait for falling edge with timeout
            struct timespec timeout = { .tv_sec = 0, .tv_nsec = DEBOUNCE_TIME * 1000 * 1000 };
            ret = gpiod_line_event_wait(line, &timeout);
            if (ret > 0) {
                struct gpiod_line_event event;
                ret = gpiod_line_event_read(line, &event);
                if (ret > 0 && event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
                    capture_image();
                }
            }
        }
        sleep(1);
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(log_file);

    return EXIT_SUCCESS;
}

