#include <sys/mman.h>
#include <sys/select.h>
#include <errno.h>
#include <signal.h>
#include <linux/videodev2.h>

#define WIDTH 640
#define HEIGHT 480
#define CROP_WIDTH 200
#define CROP_HEIGHT 150
#define CROP_OFFSET (100 * 2 + 50 * 2 * WIDTH)
#define BUFFER_COUNT 1

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    int fd = open("/dev/video0", O_RDWR);
    if (fd < 0) {
        perror("Failed to open /dev/video0");
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Failed to query device capabilities");
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device is not a video capture device\n");
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Failed to set format");
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = BUFFER_COUNT;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Failed to request buffers");
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("Failed to query buffer");
        close(fd);
        return EXIT_FAILURE;
    }

    void *buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        perror("Failed to mmap buffer");
        close(fd);
        return EXIT_FAILURE;
    }

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Failed to queue buffer");
        munmap(buffer, buf.length);
        close(fd);
        return EXIT_FAILURE;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Failed to start streaming");
        munmap(buffer, buf.length);
        close(fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fd_set fds;
    struct timeval tv;
    int ret;

    while (!stop) {
        FD_ZERO(&fds);
        FD_SET(fd, &fds);
        tv.tv_sec = 2;
        tv.tv_usec = 0;

        ret = select(fd + 1, &fds, NULL, NULL, &tv);
        if (ret < 0) {
            if (errno == EINTR) {
                continue;
            }
            perror("Failed to select");
            break;
        } else if (ret == 0) {
            fprintf(stderr, "Timeout waiting for frame\n");
            break;
        }

        if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
            perror("Failed to dequeue buffer");
            break;
        }

        if (buf.type != V4L2_BUF_TYPE_VIDEO_CAPTURE || buf.memory != V4L2_MEMORY_MMAP) {
            fprintf(stderr, "Invalid buffer type or memory\n");
            break;
        }

        if (buf.bytesused != WIDTH * HEIGHT * 2) {
            fprintf(stderr, "Invalid buffer size\n");
            break;
        }

        if (buf.field != V4L2_FIELD_NONE) {
            fprintf(stderr, "Invalid field type\n");
            break;
        }

        uint8_t *src = buffer + CROP_OFFSET;
        uint8_t *dst = malloc(CROP_WIDTH * CROP_HEIGHT * 2);
        if (!dst) {
            perror("Failed to allocate memory for cropped frame");
            break;
        }

        for (int y = 0; y < CROP_HEIGHT; y++) {
            for (int x = 0; x < CROP_WIDTH; x++) {
                int src_idx = (y * WIDTH + x) * 2;
                int dst_idx = (y * CROP_WIDTH + x) * 2;
                dst[dst_idx] = src[src_idx];
                dst[dst_idx + 1] = src[src_idx + 1];
                dst[dst_idx + 2] = src[src_idx + 2];
                dst[dst_idx + 3] = src[src_idx + 3];
            }
        }

        FILE *file = fopen("cropped.yuv", "wb");
        if (!file) {
            perror("Failed to open cropped.yuv for writing");
            free(dst);
            break;
        }

        if (fwrite(dst, 1, CROP_WIDTH * CROP_HEIGHT * 2, file) != CROP_WIDTH * CROP_HEIGHT * 2) {
