#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define SERVO_FREQ 50
#define SERVO_MIN 500
#define SERVO_MAX 2500
#define SERVO_RANGE 180
#define STEP 5
#define DELAY 100

volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
}

int set_servo_angle(int gpio, int angle) {
    if (angle < 0 || angle > SERVO_RANGE) {
        fprintf(stderr, "Angle out of range: %d\n", angle);
        return -1;
    }
    int pulse_width = SERVO_MIN + (angle * (SERVO_MAX - SERVO_MIN) / SERVO_RANGE);
    if (gpioSetPulsewidth(gpio, pulse_width) != 0) {
        fprintf(stderr, "Failed to set pulse width for GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    int pan_gpio = 17;
    int tilt_gpio = 18;
    int pan_angle = 90;
    int tilt_angle = 90;

    if (gpioSetMode(pan_gpio, PI_OUTPUT) != 0 || gpioSetMode(tilt_gpio, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(pan_gpio, SERVO_FREQ) != 0 || gpioSetPWMfrequency(tilt_gpio, SERVO_FREQ) != 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (running) {
        printf("Pan: %d, Tilt: %d\n", pan_angle, tilt_angle);
        printf("Use arrow keys to move, 'q' to quit: ");
        fflush(stdout);

        int ch = getchar();
        if (ch == '\n') {
            continue;
        }

        switch (ch) {
            case 'w':
                if (tilt_angle < SERVO_RANGE) {
                    tilt_angle += STEP;
                }
                break;
            case 's':
                if (tilt_angle > 0) {
                    tilt_angle -= STEP;
                }
                break;
            case 'a':
                if (pan_angle > 0) {
                    pan_angle -= STEP;
                }
                break;
            case 'd':
                if (pan_angle < SERVO_RANGE) {
                    pan_angle += STEP;
                }
                break;
            case 'q':
                running = 0;
                break;
            default:
                printf("Invalid input\n");
                break;
        }

        if (set_servo_angle(pan_gpio, pan_angle) != 0 || set_servo_angle(tilt_gpio, tilt_angle) != 0) {
            running = 0;
        }

        usleep(DELAY * 1000);
    }

    set_servo_angle(pan_gpio, 90);
    set_servo_angle(tilt_gpio, 90);

    gpioTerminate();
    return 0;
}

