#define FONT_HEIGHT 8

typedef struct {
    uint8_t data[OLED_WIDTH * OLED_HEIGHT / 8];
} OledBuffer;

void oled_init(OledBuffer *buffer) {
    memset(buffer->data, 0, sizeof(buffer->data));
}

void oled_clear(OledBuffer *buffer) {
    memset(buffer->data, 0, sizeof(buffer->data));
}

void oled_set_pixel(OledBuffer *buffer, int x, int y) {
    if (x >= 0 && x < OLED_WIDTH && y >= 0 && y < OLED_HEIGHT) {
        buffer->data[(y / 8) * OLED_WIDTH + x] |= 1 << (y % 8);
    }
}

void oled_draw_char(OledBuffer *buffer, int x, int y, char c) {
    for (int i = 0; i < FONT_WIDTH; i++) {
        for (int j = 0; j < FONT_HEIGHT; j++) {
            if (font[c * FONT_WIDTH + i] & (1 << (FONT_HEIGHT - 1 - j))) {
                oled_set_pixel(buffer, x + i, y + j);
            }
        }
    }
}

void oled_update(OledBuffer *buffer) {
    if (gpioI2CWrite(I2C_BUS, buffer->data, sizeof(buffer->data)) < 0) {
        fprintf(stderr, "I2C write error\n");
        exit(EXIT_FAILURE);
    }
}

