    oled_init(&buffer);

    int fd = gpioI2COpen(I2C_BUS, I2C_ADDR, 0);
    if (fd < 0) {
        fprintf(stderr, "I2C open error\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

