            snprintf(temp_str, sizeof(temp_str), "Temp: %dC", temp / 1000);
            for (int i = 0; i < strlen(temp_str); i++) {
                oled_draw_char(&buffer, i * FONT_WIDTH, 0, temp_str[i]);
            }
        } else {
            oled_draw_char(&buffer, 0, 0, 'E');
            oled_draw_char(&buffer, 1 * FONT_WIDTH, 0, 'R');
            oled_draw_char(&buffer, 2 * FONT_WIDTH, 0, 'R');
            oled_draw_char(&buffer, 3 * FONT_WIDTH, 0, 'O');
            oled_draw_char(&buffer, 4 * FONT_WIDTH, 0, 'R');
        }

