        if (stat_file) {
            char line[256];
            if (fgets(line, sizeof(line), stat_file)) {
                char *fields[10];
                int count = 0;
                char *token = strtok(line, " ");
                while (token && count < 10) {
                    fields[count++] = token;
                    token = strtok(NULL, " ");
                }
                if (count >= 5) {
                    unsigned long user = strtoul(fields[1], NULL, 10);
                    unsigned long nice = strtoul(fields[2], NULL, 10);
                    unsigned long system = strtoul(fields[3], NULL, 10);
                    unsigned long idle = strtoul(fields[4], NULL, 10);
                    unsigned long total = user + nice + system + idle;
                    unsigned long prev_total = prev_user + prev_nice + prev_system + prev_idle;
                    unsigned long prev_user_total = prev_user + prev_nice;
                    unsigned long user_total = user + nice;
                    unsigned long usage = ((user_total - prev_user_total) * 100) / (total - prev_total);
                    char usage_str[10];
                    snprintf(usage_str, sizeof(usage_str), "Usage: %lu%%", usage);
                    for (int i = 0; i < strlen(usage_str); i++) {
                        oled_draw_char(&buffer, i * FONT_WIDTH, FONT_HEIGHT, usage_str[i]);
                    }
                }
            }
            fclose(stat_file);
        } else {
            oled_draw_char(&buffer, 0, FONT_HEIGHT, 'E');
            oled_draw_char(&buffer, 1 * FONT_WIDTH, FONT_HEIGHT, 'R');
            oled_draw_char(&buffer, 2 * FONT_WIDTH, FONT_HEIGHT, 'R');
            oled_draw_char(&buffer, 3 * FONT_WIDTH, FONT_HEIGHT, 'O');
            oled_draw_char(&buffer, 4 * FONT_WIDTH, FONT_HEIGHT, 'R');
        }

        oled_update(&buffer);
        sleep(1);
    }

    gpioI2CClose(fd);
    gpioTerminate();
    return EXIT_SUCCESS;
}

