#define LCD_I2C_BUS 1
#define PULSES_PER_LITER 450
#define UPDATE_INTERVAL 1
#define LCD_UPDATE_INTERVAL 10

volatile int pulse_count = 0;
volatile int last_pulse_count = 0;
volatile int64_t total_volume = 0;
volatile int running = 1;

void gpio_callback(int gpio, int level, uint32_t tick) {
    if (level == PI_TIMEOUT) {
        pulse_count++;
    }
}

void update_lcd() {
    char buffer[16];
    int flow_rate = (pulse_count - last_pulse_count) * 60 / PULSES_PER_LITER;
    total_volume += (pulse_count - last_pulse_count) / PULSES_PER_LITER;
    last_pulse_count = pulse_count;

    snprintf(buffer, sizeof(buffer), "Flow: %d L/min\nTotal: %lld L", flow_rate, total_volume);
    gpioI2CWrite(LCD_I2C_BUS, LCD_I2C_ADDRESS, (uint8_t *)buffer, strlen(buffer));
}

void signal_handler(int sig) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", FLOW_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(FLOW_SENSOR_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", FLOW_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetWatchdog(FLOW_SENSOR_PIN, UPDATE_INTERVAL * 1000) < 0) {
        fprintf(stderr, "Failed to set watchdog on GPIO%d\n", FLOW_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioI2COpen(LCD_I2C_BUS, LCD_I2C_ADDRESS, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus %d for address 0x%02X\n", LCD_I2C_BUS, LCD_I2C_ADDRESS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        update_lcd();
        sleep(UPDATE_INTERVAL);
    }

    gpioSetWatchdog(FLOW_SENSOR_PIN, 0);
    gpioTerminate();
    gpioI2CClose(LCD_I2C_BUS, LCD_I2C_ADDRESS);

    return EXIT_SUCCESS;
}

