This C program uses the pigpio library to read pulses from a YF-S201 water flow sensor connected to GPIO17 and calculates the flow rate in liters per minute. It logs the current flow rate and the running total volume to the console every second. Every 10 seconds, it updates an HD44780 LCD screen connected via I2C (bus 1, address 0x27) to display the current flow rate and accumulated volume. The program handles GPIO initialization failures, I2C communication errors, and graceful shutdown on SIGINT and SIGTERM signals.

code:
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define I2C_ADDRESS 0x27
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define GPIO_PIN 17
#define SAMPLE_INTERVAL 500

volatile int wind_speed = 0;
volatile int wind_direction = 0;
volatile int adc_value = 0;
volatile int adc_last_value = 0;
volatile int adc_stuck_count = 0;
volatile int i2c_handle = -1;
volatile int spi_handle = -1;
volatile int running = 1;

void signal_handler(int signum) {
    running = 0;
}

void init_i2c() {
    i2c_handle = i2cOpen(1, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        exit(EXIT_FAILURE);
    }
}

void init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        exit(EXIT_FAILURE);
    }
}

void init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);
    gpioSetAlertFunc(GPIO_PIN, [](unsigned gpio, unsigned level, uint32_t tick) {
        if (level == PI_TIMEOUT) {
            wind_speed++;
        }
    });
}

void read_wind_vane() {
    uint8_t tx[2] = {1, 0}; // MCP3008 channel 0
    uint8_t rx[3];
    int result = spiXfer(spi_handle, tx, rx, 3);
    if (result < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return;
    }
    adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    if (adc_value == 0 || adc_value == 1023) {
        adc_stuck_count++;
        if (adc_stuck_count > 10) {
            fprintf(stderr, "Wind vane sensor stuck at %d\n", adc_value);
            adc_stuck_count = 0;
        }
    } else {
        adc_stuck_count = 0;
    }
    wind_direction = (int)((adc_value * 359.0) / 1023.0);
}

void display_on_lcd() {
    char buffer[17];
    snprintf(buffer, sizeof(buffer), "Wind Speed: %dm/s\nWind Dir: %ddeg", wind_speed, wind_direction);
    i2cWriteQuick(i2c_handle, 0x01); // Clear display
    i2cWriteBlockData(i2c_handle, 0x40, (uint8_t *)buffer, 16);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    init_i2c();
    init_spi();
    init_gpio();

    while (running) {
        read_wind_vane();
        display_on_lcd();
        usleep(SAMPLE_INTERVAL * 1000);
    }

    i2cClose(i2c_handle);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

