#include <gpiod.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>

#define ROWS 8
#define COLS 8
#define ROW_PINS {17, 18, 27, 22, 23, 24, 25, 4}
#define COL_PINS {5, 6, 12, 13, 19, 16, 26, 20}
#define SCAN_DELAY_US 800

static struct gpiod_chip *chip;
static struct gpiod_line *row_lines[ROWS];
static struct gpiod_line *col_lines[COLS];

void cleanup(int signum) {
    for (int i = 0; i < ROWS; i++) {
        gpiod_line_release(row_lines[i]);
    }
    for (int i = 0; i < COLS; i++) {
        gpiod_line_release(col_lines[i]);
    }
    gpiod_chip_close(chip);
    exit(signum);
}

void init_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < ROWS; i++) {
        row_lines[i] = gpiod_chip_get_line(chip, ROW_PINS[i]);
        if (!row_lines[i]) {
            perror("Failed to get row line");
            cleanup(EXIT_FAILURE);
        }
        if (gpiod_line_request_output(row_lines[i], "led_matrix_row", 0)) {
            perror("Failed to request row line output");
            cleanup(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < COLS; i++) {
        col_lines[i] = gpiod_chip_get_line(chip, COL_PINS[i]);
        if (!col_lines[i]) {
            perror("Failed to get column line");
            cleanup(EXIT_FAILURE);
        }
        if (gpiod_line_request_output(col_lines[i], "led_matrix_col", 1)) {
            perror("Failed to request column line output");
            cleanup(EXIT_FAILURE);
        }
    }

    signal(SIGINT, cleanup);
}

void display_wave(int direction) {
    for (int i = 0; i < ROWS; i++) {
        gpiod_line_set_value(row_lines[i], 1);
        for (int j = 0; j < COLS; j++) {
            gpiod_line_set_value(col_lines[j], (direction == 0) ? (j >= i) : (j < i));
            usleep(SCAN_DELAY_US);
        }
        gpiod_line_set_value(row_lines[i], 0);
    }
}

int main() {
    init_gpio();

    while (1) {
        display_wave(0); // Left-to-right wave
        display_wave(1); // Right-to-left wave
    }

    return 0;
}

