This C program uses the libgpiod library to control an 8x8 common-anode LED matrix on a Raspberry Pi. It initializes the GPIO lines for the rows and columns, sets up a signal handler for graceful shutdown, and implements a function to display a wave pattern on the matrix. The wave pattern shifts left-to-right and right-to-left, and the display updates every 800 microseconds. The program handles errors and cleans up resources on exit.

code:
#include <gpiod.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

#define ROWS 8
#define COLS 8
#define ROW_PINS {2, 3, 4, 17, 27, 22, 10, 9}
#define COL_PINS {14, 15, 18, 23, 24, 25, 8, 7}
#define DELAY 150

static struct gpiod_chip *chip;
static struct gpiod_line *row_lines[ROWS];
static struct gpiod_line *col_lines[COLS];

void cleanup(int signum) {
    for (int i = 0; i < ROWS; i++) {
        gpiod_line_release(row_lines[i]);
    }
    for (int i = 0; i < COLS; i++) {
        gpiod_line_release(col_lines[i]);
    }
    gpiod_chip_close(chip);
    exit(signum);
}

int main() {
    struct gpiod_line_request_config row_config = {
        .consumer = "LED Matrix Row",
        .request_type = GPIOD_LINE_REQUEST_OUTPUT,
        .default_val = 1,
    };
    struct gpiod_line_request_config col_config = {
        .consumer = "LED Matrix Column",
        .request_type = GPIOD_LINE_REQUEST_OUTPUT,
        .default_val = 1,
    };

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request row lines
    for (int i = 0; i < ROWS; i++) {
        row_lines[i] = gpiod_chip_get_line(chip, ROW_PINS[i]);
        if (!row_lines[i]) {
            perror("Failed to get row line");
            cleanup(EXIT_FAILURE);
        }
        if (gpiod_line_request(row_lines[i], &row_config)) {
            perror("Failed to request row line");
            cleanup(EXIT_FAILURE);
        }
    }

    // Request column lines
    for (int i = 0; i < COLS; i++) {
