#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x4C
#define DISTANCE_REG 0x0D
#define SAMPLE_INTERVAL 100  // 100 milliseconds
#define LOG_FILE "depth_log.csv"

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int sig) {
    stop_flag = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = gpioI2COpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Distance\n");
    }

    signal(SIGINT, signal_handler);

    while (!stop_flag) {
        uint8_t reg_addr = DISTANCE_REG;
        if (gpioI2CWriteByte(i2c_handle, reg_addr) < 0) {
            fprintf(stderr, "Failed to write register address\n");
            gpioI2CClose(i2c_handle);
            fclose(log_file);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        uint8_t data[2];
        if (gpioI2CRead(i2c_handle, data, 2) < 0) {
            fprintf(stderr, "Failed to read distance data\n");
            fprintf(log_file, "%ld,-1\n", time(NULL));
            fflush(log_file);
            gpioI2CClose(i2c_handle);
            fclose(log_file);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        uint16_t distance = (data[0] << 8) | data[1];
        fprintf(log_file, "%ld,%d\n", time(NULL), distance);
        fflush(log_file);

        gpioDelay(SAMPLE_INTERVAL * 1000);
    }

    gpioI2CClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return EXIT_SUCCESS;
}

