#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SI1145_I2C_BUS 1
#define SI1145_I2C_ADDR 0x60
#define SI1145_PART_ID_REG 0x00
#define SI1145_COMMAND_REG 0x18
#define SI1145_IRQ_REG 0x12
#define SI1145_ALS_DATA_REG 0x2C
#define SI1145_PS_DATA_REG 0x2E

volatile int running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    int i2c_handle = gpioI2COpen(SI1145_I2C_BUS, SI1145_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", SI1145_I2C_BUS);
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen("biometric_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);

    uint8_t part_id;
    if (gpioI2CReadReg8(i2c_handle, SI1145_PART_ID_REG, &part_id) != 1) {
        fprintf(stderr, "Failed to read PART ID register\n");
        fclose(log_file);
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (part_id != 0x45) {
        fprintf(stderr, "Invalid PART ID: 0x%02X\n", part_id);
        fclose(log_file);
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t command = 0x07; // Set measurement rates and clear IRQ
    if (gpioI2CWriteReg8(i2c_handle, SI1145_COMMAND_REG, command) != 1) {
        fprintf(stderr, "Failed to write to COMMAND register\n");
        fclose(log_file);
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (running) {
        uint8_t als_data[2];
        if (gpioI2CReadReg16(i2c_handle, SI1145_ALS_DATA_REG, als_data) != 2) {
            fprintf(stderr, "Failed to read ALS data\n");
        } else {
            uint16_t als_value = (als_data[0] << 8) | als_data[1];
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d ALS: %u\n",
                    tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
                    tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec, als_value);
            fflush(log_file);
        }

        uint8_t ps_data[2];
        if (gpioI2CReadReg16(i2c_handle, SI1145_PS_DATA_REG, ps_data) != 2) {
            fprintf(stderr, "Failed to read PS data\n");
        } else {
            uint16_t ps_value = (ps_data[0] << 8) | ps_data[1];
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d PS: %u\n",
                    tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
                    tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec, ps_value);
            fflush(log_file);
        }

        gpioDelay(500 * 1000); // 500 ms
    }

    fclose(log_file);
    gpioI2CClose(i2c_handle);
    gpioTerminate();

    return 0;
}

