#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI1145_I2C_ADDR 0x60
#define PART_ID 0x00
#define HW_KEY 0x07
#define CH_LIST 0x4F
#define COMMAND 0x30
#define ALS_FORCE 0x06
#define PS_FORCE 0x07
#define PS1_DATA 0x18
#define ALS_VIS_DATA 0x22

volatile int running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    int i2c_handle = gpioI2COpen(I2C_BUS, SI1145_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen("biometric_data.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Verify PART_ID
    uint8_t part_id;
    if (gpioI2CReadReg8(i2c_handle, PART_ID, &part_id) != 1) {
        fprintf(stderr, "Failed to read PART_ID\n");
        fclose(log_file);
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Invalid PART_ID: 0x%02X\n", part_id);
        fclose(log_file);
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write HW_KEY
    if (gpioI2CWriteReg8(i2c_handle, HW_KEY, 0x17) != 1) {
        fprintf(stderr, "Failed to write HW_KEY\n");
        fclose(log_file);
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set CH_LIST
    if (gpioI2CWriteReg8(i2c_handle, CH_LIST, 0x18) != 1) {
        fprintf(stderr, "Failed to write CH_LIST\n");
        fclose(log_file);
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure measurement rates (example: 100ms)
    if (gpioI2CWriteReg8(i2c_handle, 0x10, 0x0A) != 1) {
        fprintf(stderr, "Failed to write ALS_MEAS_RATE\n");
        fclose(log_file);
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (gpioI2CWriteReg8(i2c_handle, 0x11, 0x0A) != 1) {
        fprintf(stderr, "Failed to write PS_MEAS_RATE\n");
        fclose(log_file);
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Trigger measurements
    if (gpioI2CWriteReg8(i2c_handle, COMMAND, ALS_FORCE) != 1) {
        fprintf(stderr, "Failed to trigger ALS measurement\n");
        fclose(log_file);
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (gpioI2CWriteReg8(i2c_handle, COMMAND, PS_FORCE) != 1) {
        fprintf(stderr, "Failed to trigger PS measurement\n");
        fclose(log_file);
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (running) {
        uint8_t ps1_data[2];
        if (gpioI2CReadReg16(i2c_handle, PS1_DATA, ps1_data) != 2) {
            fprintf(stderr, "Failed to read PS1 data\n");
            continue;
        }

        uint8_t als_vis_data[2];
        if (gpioI2CReadReg16(i2c_handle, ALS_VIS_DATA, als_vis_data) != 2) {
            fprintf(stderr, "Failed to read ALS_VIS data\n");
            continue;
        }

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

        fprintf(log_file, "%s,%d,%d\n", timestamp, (ps1_data[1] << 8) | ps1_data[0], (als_vis_data[1] << 8) | als_vis_data[0]);
        fflush(log_file);

        sleep(1);
    }

    fclose(log_file);
    gpioI2CClose(i2c_handle);
    gpioTerminate();

    return 0;
}

