#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define TRIGGER_LINE "gpiochip0:line17"
#define ECHO_LINE "gpiochip0:line27"
#define LOG_FILE "distance_log.txt"
#define TIMEOUT_US 30000
#define MIN_DISTANCE 2
#define MAX_DISTANCE 400
#define WATERING_THRESHOLD 15

static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line, *echo_line;
static FILE *log_file;

void log_event(const char *message) {
    time_t now = time(NULL);
    char *iso_time = ctime(&now);
    iso_time[strlen(iso_time) - 1] = '\0'; // Remove newline
    fprintf(log_file, "%s: %s\n", iso_time, message);
    fflush(log_file);
}

void handle_signal(int sig) {
    log_event("Shutting down gracefully...");
    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);
    fclose(log_file);
    exit(0);
}

int main() {
    struct timespec start, end;
    long long duration_ns;
    double distance_cm;

    // Initialize libgpiod
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    trigger_line = gpiod_chip_get_line(chip, 17);
    if (!trigger_line) {
        perror("Failed to get trigger line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    echo_line = gpiod_chip_get_line(chip, 27);
    if (!echo_line) {
        perror("Failed to get echo line");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(trigger_line, "trigger", 0) < 0) {
        perror("Failed to request trigger line as output");
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(echo_line, "echo") < 0) {
        perror("Failed to request echo line as input");
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        // Trigger pulse
        if (gpiod_line_set_value(trigger_line, 1) < 0) {
            perror("Failed to set trigger line high");
            continue;
        }
        if (nanosleep((struct timespec){0, 10000}, NULL) < 0) {
            perror("Failed to sleep for 10us");
            continue;
        }
        if (gpiod_line_set_value(trigger_line, 0) < 0) {
            perror("Failed to set trigger line low");
            continue;
        }

        // Wait for echo to rise
        if (gpiod_line_event_wait(echo_line, &start, TIMEOUT_US / 1000) < 0) {
            log_event("Timeout waiting for echo to rise");
            continue;
        }

        // Wait for echo to fall
        if (gpiod_line_event_wait(echo_line, &end, TIMEOUT_US / 1000) < 0) {
            log_event("Timeout waiting for echo to fall");
            continue;
        }

        // Calculate duration
        duration_ns = (end.tv_sec - start.tv_sec) * 1000000000LL + (end.tv_nsec - start.tv_nsec);
        distance_cm = (duration_ns * 34300) / 2 / 10000000.0;

        // Log measurement
        if (distance_cm < MIN_DISTANCE || distance_cm > MAX_DISTANCE) {
            log_event("Invalid distance measurement");
        } else {
            log_event(f"Distance: %.2f cm", distance_cm);
            if (distance_cm < WATERING_THRESHOLD) {
                log_event("Time to water the plant!");
            }
        }

        // Sleep for 60 seconds
        if (sleep(60) != 0) {
            perror("Failed to sleep for 60 seconds");
        }
    }

    return EXIT_SUCCESS;
}

