#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x39
#define SENSOR_ID_REG 0x92
#define ENABLE_REG 0x80
#define ATIME_REG 0x81
#define WTIME_REG 0x83
#define PPULSE_REG 0x8E
#define CONTROL_REG 0xF1
#define CONFIG2_REG 0x90
#define RGB_REG_START 0x96
#define PROXIMITY_REG 0x9C
#define PROXIMITY_THRESHOLD 200

FILE *log_file = NULL;
int i2c_handle = -1;

void log_data(uint16_t r, uint16_t g, uint16_t b, uint16_t proximity) {
    if (log_file) {
        time_t now = time(NULL);
        fprintf(log_file, "%ld,%u,%u,%u,%u\n", now, r, g, b, proximity);
        fflush(log_file);
    }
}

void handle_sigint(int sig) {
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    pigpioTerminate();
    exit(0);
}

void init_sensor() {
    uint8_t data[2];
    if (i2cReadDevice(i2c_handle, SENSOR_ID_REG, data, 1) != 1) {
        i2cClose(i2c_handle);
        i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
        if (i2c_handle < 0) {
            fprintf(stderr, "Failed to re-open I2C bus\n");
            exit(1);
        }
        init_sensor();
        return;
    }
    if (data[0] != 0xAB) {
        fprintf(stderr, "Sensor ID mismatch\n");
        exit(1);
    }

    data[0] = 0x03;
    if (i2cWriteDevice(i2c_handle, ENABLE_REG, data, 1) != 1) {
        init_sensor();
        return;
    }

    data[0] = 0xDB;
    if (i2cWriteDevice(i2c_handle, ATIME_REG, data, 1) != 1) {
        init_sensor();
        return;
    }

    data[0] = 0xF6;
    if (i2cWriteDevice(i2c_handle, WTIME_REG, data, 1) != 1) {
        init_sensor();
        return;
    }

    data[0] = 0x87;
    if (i2cWriteDevice(i2c_handle, PPULSE_REG, data, 1) != 1) {
        init_sensor();
        return;
    }

    data[0] = 0x03;
    if (i2cWriteDevice(i2c_handle, CONTROL_REG, data, 1) != 1) {
        init_sensor();
        return;
    }

    data[0] = 0x01;
    if (i2cWriteDevice(i2c_handle, CONFIG2_REG, data, 1) != 1) {
        init_sensor();
        return;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        pigpioTerminate();
        return 1;
    }

    log_file = fopen("color_proximity_log.csv", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        pigpioTerminate();
        return 1;
    }
    fprintf(log_file, "Timestamp,Red,Green,Blue,Proximity\n");

    init_sensor();

    while (1) {
        uint8_t data[6];
        if (i2cReadDevice(i2c_handle, RGB_REG_START, data, 6) != 6) {
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to re-open I2C bus\n");
                continue;
            }
            init_sensor();
            continue;
        }

        uint16_t r = (data[1] << 8) | data[0];
        uint16_t g = (data[3] << 8) | data[2];
        uint16_t b = (data[5] << 8) | data[4];
        uint8_t proximity = data[6];

        if (proximity > PROXIMITY_THRESHOLD) {
            log_data(r, g, b, proximity);
        }

        gpioDelay(100000); // 100 ms
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    pigpioTerminate();
    return 0;
}

