#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SI1182_ADDRESS 0x5A
#define PART_ID 0x00
#define MEAS_RATE0 0x08
#define COMMAND 0x47
#define PS_DATA0 0x24
#define PS_DATA1 0x25

volatile sig_atomic_t running = true;

void signal_handler(int signum) {
    running = false;
}

int main() {
    int fd;
    if ((fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SI1182_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return EXIT_FAILURE;
    }

    uint8_t part_id;
    if (i2c_smbus_read_byte_data(fd, PART_ID) < 0) {
        perror("Failed to read PART_ID register");
        close(fd);
        return EXIT_FAILURE;
    }

    if (part_id != 0x42) {
        fprintf(stderr, "Invalid Si1182 part ID: 0x%02X\n", part_id);
        close(fd);
        return EXIT_FAILURE;
    }

    if (i2c_smbus_write_byte_data(fd, MEAS_RATE0, 0x01) < 0) {
        perror("Failed to set MEAS_RATE0 register");
        close(fd);
        return EXIT_FAILURE;
    }

    if (i2c_smbus_write_byte_data(fd, COMMAND, 0x03) < 0) {
        perror("Failed to issue reset/start command");
        close(fd);
        return EXIT_FAILURE;
    }

    FILE *csv = fopen("heartrate.csv", "w");
    if (!csv) {
        perror("Failed to open CSV file");
        close(fd);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        uint8_t data[2];
        if (i2c_smbus_read_i2c_block_data(fd, PS_DATA0, 2, data) < 0) {
            fprintf(stderr, "Failed to read proximity data\n");
            continue;
        }

        uint16_t proximity = (data[1] << 8) | data[0];
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);

        fprintf(csv, "%s,%d\n", timestamp, proximity);
        fflush(csv);
        usleep(100000); // 100 ms
    }

    fclose(csv);
    close(fd);
    return 0;
}

