    FILE *log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    fprintf(log_file, "%ld,%d\n", now, distance_mm);
    fclose(log_file);
}

void handle_sigint(int sig) {
    gpioTerminate();
    exit(0);
}

