#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x45
#define I2C_REG 0x00
#define SAMPLE_INTERVAL 200
#define LOG_INTERVAL 50
#define LOG_FILE "distance_log.txt"

volatile sig_atomic_t stop_flag = 0;

void sigint_handler(int sig) {
    stop_flag = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);

    char timestamp[20];
    uint16_t distance;

    while (!stop_flag) {
        // Trigger measurement
        if (i2cWriteByte(i2c_handle, I2C_REG | 0x01) < 0) {
            fprintf(stderr, "I2C write failed\n");
        }

        // Wait for measurement to complete
        gpioDelay(LOG_INTERVAL * 1000);

        // Read distance
        if (i2cReadWordData(i2c_handle, I2C_REG) < 0) {
            fprintf(stderr, "I2C read failed\n");
            continue;
        }

        // Log and print distance
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
        distance = i2cReadWordData(i2c_handle, I2C_REG);
        fprintf(log_file, "%s, %d\n", timestamp, distance);
        printf("%s, %d\n", timestamp, distance);

        // Sample every 200 ms
        gpioDelay(SAMPLE_INTERVAL * 1000);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

