#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <signal.h>

#define I2C_BUS 1
#define I2C_ADDR 0x6A
#define LED_PIN 17
#define MIN_DISTANCE 20.0
#define LOG_FILE "distance_log.txt"
#define SAMPLE_INTERVAL 100

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

int main() {
    int i2c_handle;
    FILE *log_file;
    struct timespec ts;
    double distance;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    if ((i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0)) < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_PIN);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!stop_flag) {
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            fprintf(stderr, "Failed to get current time\n");
            break;
        }

        if (i2cReadDevice(i2c_handle, 0x02, (unsigned char *)&distance, 2) != 2) {
            fprintf(stderr, "Failed to read distance from sensor\n");
            break;
        }

        distance = (double)((distance & 0xFF) | ((distance >> 8) & 0xFF)) / 100.0;

        if (distance < MIN_DISTANCE) {
            gpioWrite(LED_PIN, PI_HIGH);
        } else {
            gpioWrite(LED_PIN, PI_LOW);
        }

        fprintf(log_file, "%ld.%09ld,%f\n", ts.tv_sec, ts.tv_nsec, distance);
        fflush(log_file);

        usleep(SAMPLE_INTERVAL * 1000);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

