This C program uses the pigpio library to interface with a Silicon Labs Si1182-GMR Optical Proximity and Ambient Light Sensor over I2C bus 1 at address 0x60. It reads the 16-bit proximity data from register 0x18 and the 16-bit ambient light data from register 0x16 every 500 ms, logging the timestamped readings to a file named 'biometric_log.txt'. It handles sensor-absent or bus-error paths gracefully, retries failed reads up to 3 times, and handles SIGINT (Ctrl+C) for clean resource release by closing the I2C handle and the log file and terminating pigpio cleanly before exiting.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x6A
#define WHO_AM_I_REG 0x0F
#define DEFAULT_THRESHOLD 100
#define GPIO_LED 17
#define LOG_FILE "tof_log.txt"
#define READ_INTERVAL 50

volatile sig_atomic_t stop = 0;

void sigint_handler(int sig) {
    stop = 1;
}

int main(int argc, char *argv[]) {
    int threshold = DEFAULT_THRESHOLD;
    if (argc > 1) {
        threshold = atoi(argv[1]);
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return 1;
    }

    uint8_t who_am_i;
    if (i2cReadByteData(i2c_handle, WHO_AM_I_REG, &who_am_i) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (who_am_i != 0x20) {
        fprintf(stderr, "Sensor not found or wrong address\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d mode\n", GPIO_LED);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (!stop) {
        uint8_t distance_high, distance_low;
        if (i2cReadByteData(i2c_handle, 0x02, &distance_high) < 0 ||
            i2cReadByteData(i2c_handle, 0x03, &distance_low) < 0) {
            fprintf(stderr, "Failed to read distance data\n");
            continue;
        }

        uint16_t distance = (distance_high << 8) | distance_low;
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        fprintf(log_file, "%s, Distance: %d mm\n", asctime(tm_info), distance);

        if (distance < threshold) {
            gpioWrite(GPIO_LED, PI_HIGH);
        } else {
            gpioWrite(GPIO_LED, PI_LOW);
        }

        fflush(log_file);
        gpioDelay(READ_INTERVAL * 1000);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

