#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SENSOR_ADDRESS 0x50
#define COMMAND_FRAME {0x50, 0x0A, 0x00, 0x01}
#define RESPONSE_SIZE 15
#define SAMPLES_PER_CYCLE 10
#define MIN_DISTANCE 1000
#define LOG_FILE "intrusion_log.txt"
#define DELAY_MS 100
#define CYCLE_DELAY_MS 1000

void log_event(time_t timestamp, uint16_t average_distance) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }
    fprintf(log_file, "Intrusion detected at %s, average distance: %u mm\n", ctime(&timestamp), average_distance);
    fclose(log_file);
}

void handle_sigint(int sig) {
    printf("Received SIGINT, exiting...\n");
    exit(0);
}

int main() {
    int i2c_fd;
    uint8_t command_frame[] = COMMAND_FRAME;
    uint8_t response_frame[RESPONSE_SIZE];
    uint16_t distances[SAMPLES_PER_CYCLE];
    uint16_t total_distance = 0;
    time_t timestamp;
    struct sigaction sa;

    // Set up signal handler for SIGINT
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to set up signal handler");
        return EXIT_FAILURE;
    }

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        // Request distance measurement
        if (write(i2c_fd, command_frame, sizeof(command_frame)) != sizeof(command_frame)) {
            perror("Failed to write command frame");
            close(i2c_fd);
            return EXIT_FAILURE;
        }

        // Wait for sensor to process the command
        usleep(10 * 1000);

        // Read response frame
        if (read(i2c_fd, response_frame, RESPONSE_SIZE) != RESPONSE_SIZE) {
            perror("Failed to read response frame");
            close(i2c_fd);
            return EXIT_FAILURE;
        }

        // Validate response header
        if (response_frame[0] != 0x50) {
            fprintf(stderr, "Invalid response header\n");
            continue;
        }

        // Calculate average distance
        total_distance = 0;
        for (int i = 0; i < SAMPLES_PER_CYCLE; i++) {
            uint16_t distance = (response_frame[11 + i * 2] << 8) | response_frame[12 + i * 2];
            distances[i] = distance;
            total_distance += distance;
        }
        uint16_t average_distance = total_distance / SAMPLES_PER_CYCLE;

        // Check for intrusion
        if (average_distance < MIN_DISTANCE) {
            time(&timestamp);
            log_event(timestamp, average_distance);
        }

        // Delay between cycles
        usleep(CYCLE_DELAY_MS * 1000);
    }

    close(i2c_fd);
    return EXIT_SUCCESS;
}

