This C program interfaces with an Omron B5L-LD50-07050 3D TOF sensor using the Linux i2c-dev kernel interface on a Raspberry Pi Zero W. It requests distance measurements, calculates the average distance, and logs any intrusion events to 'intrusion_log.txt' if the average distance is less than 1000 mm. The program handles I2C errors, sensor-absent conditions, and gracefully handles SIGINT (Ctrl+C) to close resources.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define MODEL_ID_REG 0xC0
#define SYSRANGE_START_REG 0x00
#define RESULT_INTERRUPT_STATUS_REG 0x13
#define RESULT_RANGE_STATUS_REG 0x14
#define SYSTEM_INTERRUPT_CLEAR_REG 0x0B

volatile sig_atomic_t stop_flag = 0;

void sig_handler(int signum) {
    stop_flag = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int i2c_handle = gpioI2COpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t model_id;
    if (gpioI2CReadReg8(i2c_handle, MODEL_ID_REG, &model_id) != 1) {
        fprintf(stderr, "Failed to read model ID: %s\n", strerror(errno));
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (model_id != 0xEE) {
        fprintf(stderr, "Incorrect model ID: 0x%02X\n", model_id);
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (!stop_flag) {
        uint8_t start_cmd = 0x01;
        if (gpioI2CWriteReg8(i2c_handle, SYSRANGE_START_REG, start_cmd) != 1) {
            fprintf(stderr, "Failed to start ranging: %s\n", strerror(errno));
        } else {
            uint8_t status;
            int timeout = 100000; // 100 ms in microseconds
            while (timeout > 0) {
                if (gpioI2CReadReg8(i2c_handle, RESULT_INTERRUPT_STATUS_REG, &status) != 1) {
                    fprintf(stderr, "Failed to read interrupt status: %s\n", strerror(errno));
                    break;
                }
                if (status & 0x01) {
                    uint16_t distance;
                    if (gpioI2CReadReg16(i2c_handle, RESULT_RANGE_STATUS_REG, &distance) != 2) {
                        fprintf(stderr, "Failed to read distance: %s\n", strerror(errno));
                        break;
                    }
                    time_t now = time(NULL);
                    struct tm *tm_info = localtime(&now);
                    printf("%04d-%02d-%02d %02d:%02d:%02d Distance: %d mm\n",
                           tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
                           tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec, distance);
                    uint8_t clear_cmd = 0x01;
                    if (gpioI2CWriteReg8(i2c_handle, SYSTEM_INTERRUPT_CLEAR_REG, clear_cmd) != 1) {
                        fprintf(stderr, "Failed to clear interrupt: %s\n", strerror(errno));
                    }
                    break;
                }
                gpioDelay(100); // 100 us
                timeout -= 100;
            }
        }
        gpioDelay(500000); // 500 ms
    }

    gpioI2CClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

