#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x4C
#define I2C_REG 0x00
#define I2C_READ_LEN 2
#define DISTANCE_FACTOR 0.125

int i2c_fd = -1;
volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set signal handler");
        return 1;
    }

    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    uint8_t reg = I2C_REG;
    uint8_t buf[I2C_READ_LEN];
    while (running) {
        if (write(i2c_fd, &reg, 1) != 1) {
            perror("Failed to write to I2C device");
            continue;
        }

        if (read(i2c_fd, buf, I2C_READ_LEN) != I2C_READ_LEN) {
            perror("Failed to read from I2C device");
            continue;
        }

        uint16_t distance_raw = (buf[1] << 8) | buf[0];
        float distance_mm = distance_raw * DISTANCE_FACTOR;

        printf("Distance: %.2f mm\n", distance_mm);

        struct timespec ts = {0, 500 * 1000 * 1000};
        if (nanosleep(&ts, NULL) == -1 && errno != EINTR) {
            perror("Failed to sleep");
            break;
        }
    }

    close(i2c_fd);
    return 0;
}

