This C program for a Raspberry Pi 4 Model B uses the Linux I2C userland API to read distance data from a Melexis MLX75030 Time-of-Flight sensor over I2C bus 1. It opens `/dev/i2c-1`, sets the slave address to 0x4C, and verifies the device responds. It reads the 16-bit distance register at offset 0x00, converts the raw value to millimetres using the factor 0.125 mm per count, and logs the distance to stdout every 500 ms. The program handles SIGINT and SIGTERM signals to cleanly close the I2C file descriptor and exit.

code:
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x44
#define READ_INTERVAL 500

volatile sig_atomic_t stop_flag = 0;

void sigint_handler(int signum) {
    stop_flag = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = gpioI2COpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    while (!stop_flag) {
        uint8_t buffer[6];
        int result = gpioI2CRead(i2c_handle, buffer, sizeof(buffer));
        if (result < 0) {
            fprintf(stderr, "I2C read error: %d\n", result);
        } else {
            uint16_t distance = (buffer[0] << 8) | buffer[1];
            uint16_t ambient = (buffer[2] << 8) | buffer[3];
            uint8_t flags = buffer[4];
            uint8_t status = buffer[5];

            printf("Distance: %d mm, Ambient: %d lux, Flags: 0x%02X, Status: 0x%02X\n",
                   distance, ambient, flags, status);
        }

        gpioDelay(READ_INTERVAL * 1000);
    }

    gpioI2CClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

