#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define MAX_PULSE_DURATION 38000 // 38 ms in microseconds
#define TIMEOUT_US 200000 // 200 ms in microseconds

volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        gpioWrite(TRIGGER_PIN, 0);
        gpioDelay(10); // 10 microseconds trigger pulse
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(10);
        gpioWrite(TRIGGER_PIN, 0);

        uint32_t start = gpioTick();
        uint32_t end = start;

        while (gpioRead(ECHO_PIN) == 0 && (gpioTick() - start) < TIMEOUT_US) {
            end = gpioTick();
        }

        if (gpioRead(ECHO_PIN) == 0) {
            fprintf(stderr, "Echo rising-edge timeout\n");
            continue;
        }

        uint32_t pulse_start = end;

        while (gpioRead(ECHO_PIN) == 1 && (gpioTick() - pulse_start) < TIMEOUT_US) {
            end = gpioTick();
        }

        if (gpioRead(ECHO_PIN) == 1) {
            fprintf(stderr, "Echo falling-edge timeout\n");
            continue;
        }

        uint32_t pulse_duration = end - pulse_start;

        if (pulse_duration <= 0 || pulse_duration > MAX_PULSE_DURATION) {
            fprintf(stderr, "Invalid pulse duration\n");
            continue;
        }

        double distance = (pulse_duration * 0.0343) / 2;

        printf("Timestamp: %lu, Distance: %.2f cm\n", gpioTick(), distance);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

