### Explanation:
1. **Initialization**:
   - The `gpioInitialise()` function initializes the pigpio library. If it fails, the program prints an error message and exits.
   - The trigger pin (GPIO 17) is set to output mode, and the echo pin (GPIO 18) is set to input mode.

2. **Signal Handling**:
   - The `signal()` function is used to set up signal handlers for `SIGINT` and `SIGTERM` to gracefully shut down the program.

3. **Main Loop**:
   - The program enters a loop that runs until a shutdown signal is received.
   - A 10 microsecond trigger pulse is sent to the HC-SR04 sensor.
   - The program waits for the echo pin to go high and then low, measuring the pulse duration.
   - If the echo pin does not go high or low within the timeout period, an error message is printed.
   - If the pulse duration is invalid (<= 0 or > 38 ms), an error message is printed.
   - The distance is calculated using the formula `(pulse_us * 0.0343) / 2` and printed along with a timestamp.

4. **Cleanup**:
   - The `gpioTerminate()` function is called to clean up the pigpio library resources when the program exits.

### Notes:
- The HC-SR04 operates at 5V, while the Raspberry Pi GPIO is 3.3V tolerant. A 1kOhm resistor in series on the echo line is used for protection.
- The `gpioTick()` function returns a monotonically increasing microsecond counter, which is used to measure the time between the trigger and echo pulses.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <termios.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/serial0"
#define GPIO_PIN 17
#define RANGE_BINS 64
#define RANGE_RESOLUTION 0.0486
#define DISTANCE_THRESHOLD 1.0
#define MAGIC_WORD "\x02\x01\x04\x03\x06\x05\x08\x07"
#define LOG_FILE "intrusion_log.csv"

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    int uart_fd;
    struct termios options;
    FILE *log_file;
    uint16_t range_profile[RANGE_BINS];
    uint8_t buffer[128];
    time_t now;
    struct tm *tm_info;
    char timestamp[20];

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if ((uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY)) == -1) {
        perror("Failed to open UART device");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (tcgetattr(uart_fd, &options) < 0) {
        perror("Failed to get UART attributes");
        close(uart_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    cfsetispeed(&options, B921600);
    cfsetospeed(&options, B921600);
    options.c_cflag |= (CLOCAL | CREAD);
    options.c_cflag &= ~PARENB;
    options.c_cflag &= ~CSTOPB;
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8;
    options.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    options.c_oflag &= ~OPOST;

    if (tcsetattr(uart_fd, TCSANOW, &options) < 0) {
        perror("Failed to set UART attributes");
        close(uart_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        perror("Failed to open log file");
        close(uart_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, PI_OFF);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        if (read(uart_fd, buffer, 128) != 128) {
            fprintf(stderr, "Failed to read from UART\n");
            continue;
        }

        if (memcmp(buffer, MAGIC_WORD, 8) != 0) {
            fprintf(stderr, "Invalid magic word received\n");
            continue;
        }

        memcpy(range_profile, buffer + 8, 128);

        double min_distance = 0.0;
        for (int i = 0; i < RANGE_BINS; i++) {
            double distance = i * RANGE_RESOLUTION;
            if (range_profile[i] > 0 && distance < min_distance) {
                min_distance = distance;
            }
        }

        if (min_distance < DISTANCE_THRESHOLD) {
            gpioWrite(GPIO_PIN, PI_ON);
            sleep(2);
            gpioWrite(GPIO_PIN, PI_OFF);

            time(&now);
            tm_info = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", tm_info);

