#include <libgpiod.h>

#define SENSOR_CHIP "gpiochip0"
#define SENSOR_LINE 17
#define BUZZER_LINE 18
#define POLL_INTERVAL 100000  // 100 ms in microseconds

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *sensor_line = NULL;
static struct gpiod_line *buzzer_line = NULL;
static int obstacle_detected = 0;

void log_state_change(int new_state) {
    FILE *log_file = fopen("obstacle_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", tm_info);

    fprintf(log_file, "%s: Obstacle detected: %d\n", timestamp, new_state);
    fclose(log_file);
}

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        if (sensor_line) {
            gpiod_line_release(sensor_line);
        }
        if (buzzer_line) {
            gpiod_line_release(buzzer_line);
        }
        if (chip) {
            gpiod_chip_close(chip);
        }
        exit(signum);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open_by_name(SENSOR_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_LINE);
    if (!sensor_line) {
        perror("Failed to get sensor line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_LINE);
    if (!buzzer_line) {
        perror("Failed to get buzzer line");
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(sensor_line, "obstacle_sensor") < 0) {
        perror("Failed to request input for sensor line");
        gpiod_line_release(sensor_line);
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(buzzer_line, "obstacle_buzzer", 0) < 0) {
        perror("Failed to request output for buzzer line");
        gpiod_line_release(sensor_line);
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        int current_state = gpiod_line_get_value(sensor_line);
        if (current_state < 0) {
            perror("Failed to read sensor line");
            break;
        }

        if (current_state != obstacle_detected) {
            obstacle_detected = current_state;
            log_state_change(obstacle_detected);
            if (obstacle_detected) {
                gpiod_line_set_value(buzzer_line, 1);
            } else {
                gpiod_line_set_value(buzzer_line, 0);
            }
        }

        usleep(POLL_INTERVAL);
    }

    gpiod_line_release(sensor_line);
    gpiod_line_release(buzzer_line);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

