#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x69
#define GPIO_PIN 17
#define SAMPLE_INTERVAL 100
#define MIN_DISTANCE 10.0
#define LOG_FILE "distance_log.txt"

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d mode\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t distance;
    uint8_t buffer[2];
    time_t now;
    struct tm *tm_info;
    char timestamp[20];

    while (!stop_flag) {
        if (i2cReadDevice(i2c_handle, 0x31, buffer, 2) != 2) {
            fprintf(stderr, "Failed to read distance from sensor\n");
            continue;
        }

        distance = (buffer[0] << 8) | buffer[1];

        if (distance < MIN_DISTANCE) {
            gpioWrite(GPIO_PIN, PI_HIGH);
        } else {
            gpioWrite(GPIO_PIN, PI_LOW);
        }

        time(&now);
        tm_info = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", tm_info);

        fprintf(log_file, "%s, Distance: %.2f cm\n", timestamp, distance / 10.0);
        fflush(log_file);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

