#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define MODEL_ID_REG 0x010F
#define RESET_REG 0x0000
#define SYSTEM_MODE_REG 0x007
#define SYSRANGE_START_REG 0x000
#define RESULT_INTERRUPT_STATUS_REG 0x013
#define RESULT_RANGE_STATUS_REG 0x078
#define SYSTEM_INTERRUPT_CLEAR_REG 0x014
#define LOG_FILE "distance_log.csv"

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (fseek(log_file, 0, SEEK_END) != 0 || ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,distance_mm\n");
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint8_t model_id;
    if (i2cReadByteData(i2c_handle, MODEL_ID_REG, &model_id) < 0) {
        fprintf(stderr, "Failed to read model ID\n");
        goto cleanup;
    }

    if (model_id != 0xEA) {
        fprintf(stderr, "Invalid model ID: 0x%02X\n", model_id);
        goto cleanup;
    }

    if (i2cWriteByteData(i2c_handle, RESET_REG, 0x00) < 0) {
        fprintf(stderr, "Failed to perform software reset\n");
        goto cleanup;
    }

    gpioDelay(2000);

    if (i2cWriteByteData(i2c_handle, SYSTEM_MODE_REG, 0x01) < 0) {
        fprintf(stderr, "Failed to start continuous back-to-back ranging\n");
        goto cleanup;
    }

    while (!stop_flag) {
        uint8_t sysrange_start;
        if (i2cReadByteData(i2c_handle, SYSRANGE_START_REG, &sysrange_start) < 0) {
            fprintf(stderr, "Failed to read SYSRANGE_START register\n");
            goto cleanup;
        }

        if (sysrange_start & 0x01) {
            fprintf(stderr, "SYSRANGE_START register not cleared\n");
            goto cleanup;
        }

        uint8_t result_interrupt_status;
        if (i2cReadByteData(i2c_handle, RESULT_INTERRUPT_STATUS_REG, &result_interrupt_status) < 0) {
            fprintf(stderr, "Failed to read RESULT_INTERRUPT_STATUS register\n");
            goto cleanup;
        }

        if (!(result_interrupt_status & 0x01)) {
            gpioDelay(100000);
            continue;
        }

        uint16_t distance;
        if (i2cReadWordData(i2c_handle, RESULT_RANGE_STATUS_REG + 10, &distance) < 0) {
            fprintf(stderr, "Failed to read distance\n");
            goto cleanup;
        }

        if (i2cWriteByteData(i2c_handle, SYSTEM_INTERRUPT_CLEAR_REG, 0x01) < 0) {
            fprintf(stderr, "Failed to clear interrupt\n");
            goto cleanup;
        }

        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        fprintf(log_file, "%s,%d\n", timestamp, distance);
        fflush(log_file);

        if (distance < 300) {
            printf("STOP\n");
        } else if (distance < 600) {
            printf("APPROACH\n");
        } else if (distance < 1200) {
            printf("SLOW\n");
        } else {
            printf("CLEAR\n");
        }

        gpioDelay(100000);
    }

cleanup:
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

