            gpioDelay(100000);
            continue;
        }

        uint16_t distance;
        if (i2cReadWordData(i2c_handle, RESULT_RANGE_STATUS_REG + 10, &distance) < 0) {
            fprintf(stderr, "Failed to read distance\n");
            goto cleanup;
        }

        if (i2cWriteByteData(i2c_handle, SYSTEM_INTERRUPT_CLEAR_REG, 0x01) < 0) {
            fprintf(stderr, "Failed to clear interrupt\n");
            goto cleanup;
        }

        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        fprintf(log_file, "%s,%d\n", timestamp, distance);
        fflush(log_file);

        if (distance < 300) {
            printf("STOP\n");
        } else if (distance < 600) {
            printf("APPROACH\n");
        } else if (distance < 1200) {
            printf("SLOW\n");
        } else {
            printf("CLEAR\n");
        }

        gpioDelay(100000);
    }

cleanup:
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}
```

This C program for a Raspberry Pi 3 Model B+ implements a parking-assistance system using an STMicroelectronics VL53L1X Time-of-Flight sensor over I2C bus 1 at its default address 0x29. It verifies the sensor is present by reading the model ID register 0x010F and checking it equals 0xEA. It performs a software reset by writing 0x00 to register 0x0000 and waiting 2 ms. It writes 0x01 to the SYSTEM__MODE_START register 0x007 to begin continuous back-to-back ranging, then polls the SYSRANGE__START register 0x000 bit 0 until it self-clears, with a timeout of 100 ms. In a loop every 100 ms, it polls bit 0 of the RESULT__INTERRUPT_STATUS register 0x013 for data-ready, reads the 16-bit distance from RESULT__RANGE_STATUS + 10 (register 0x078, big-endian), clears the interrupt by writing 0x01 to the SYSTEM__INTERRUPT_CLEAR register 0x014, and appends each reading as 'timestamp,distance_mm' to distance_log.csv, writing the header row 'timestamp,distance_mm' only when creating a new file. It prints a parking guidance message to stdout based on thresholds: below 300 mm print 'STOP', 300-600 mm 'APPROACH', 600-1200 mm 'SLOW', and above 1200 mm 'CLEAR'. It checks every pigpio, I2C, and file return code, and handles SIGINT/SIGTERM for graceful shutdown, releasing all resources -- I2C handle, log file, pigpio -- on every exit path.

