#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x45
#define LED_PIN 18
#define MIN_DISTANCE 50
#define MAX_DISTANCE 500
#define MIN_FREQ 10
#define MAX_FREQ 1
#define I2C_RETRIES 3
#define I2C_RETRY_DELAY 10

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int i2c_retry(int fd, int func, int retries) {
    int result;
    for (int i = 0; i <= retries; i++) {
        result = func();
        if (result != -1) {
            return result;
        }
        if (i < retries) {
            gpioDelay(1000 * I2C_RETRY_DELAY);
        }
    }
    return -1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        gpioTerminate();
        return 1;
    }

    int i2c_handle = i2c_open(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        uint8_t buffer[2];
        int retries = I2C_RETRIES;
        while (retries > 0) {
            int result = i2c_read_device(i2c_handle, buffer, 2);
            if (result == 2) {
                break;
            }
            retries--;
            gpioDelay(1000 * I2C_RETRY_DELAY);
        }

        if (retries == 0) {
            fprintf(stderr, "I2C read failed\n");
            continue;
        }

        uint16_t distance = (buffer[0] << 8) | buffer[1];
        if (distance < MIN_DISTANCE) {
            distance = MIN_DISTANCE;
        } else if (distance > MAX_DISTANCE) {
            distance = MAX_DISTANCE;
        }

        float freq = MIN_FREQ + (distance - MIN_DISTANCE) * (MAX_FREQ - MIN_FREQ) / (MAX_DISTANCE - MIN_DISTANCE);
        int on_time = (int)(500000 / (2 * freq));

        gpioDelay(on_time);
        gpioWrite(LED_PIN, 1);
        gpioDelay(on_time);
        gpioWrite(LED_PIN, 0);

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        printf("%s, Distance: %d mm, Frequency: %.2f Hz\n", asctime(tm_info), distance, freq);
    }

    i2c_close(i2c_handle);
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    return 0;
}

