#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x50
#define MEASURE_CMD 0x01
#define DISTANCE_REG 0x00
#define MAX_RETRIES 5
#define RETRY_DELAY 100

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = gpioI2COpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("distance_log.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        for (int retry = 0; retry < MAX_RETRIES; retry++) {
            if (gpioI2CWriteByte(i2c_handle, MEASURE_CMD) < 0) {
                fprintf(stderr, "I2C write error, retrying...\n");
                gpioDelay(RETRY_DELAY * 1000);
                continue;
            }

            gpioDelay(100 * 1000); // 100 ms delay

            uint8_t distance_bytes[2];
            if (gpioI2CRead(i2c_handle, distance_bytes, 2) != 2) {
                fprintf(stderr, "I2C read error, retrying...\n");
                gpioDelay(RETRY_DELAY * 1000);
                continue;
            }

            uint16_t distance = (distance_bytes[0] << 8) | distance_bytes[1];
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

            fprintf(log_file, "%s,%d\n", timestamp, distance);
            fflush(log_file);

            break;
        }

        if (retry == MAX_RETRIES) {
            fprintf(stderr, "Max retries reached, exiting...\n");
            break;
        }

        gpioDelay(100 * 1000); // 100 ms delay
    }

    fclose(log_file);
    gpioI2CClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

