This C program uses the pigpio library to interface with a Melexis MLX75030 Time-of-Flight sensor over I2C bus 1. It continuously reads distance data, formats it with a timestamp, and appends it to a 'distance_log.csv' file. The program handles I2C communication errors with retry logic and logs errors to stderr. It ensures clean resource release on all exit paths, including graceful termination via SIGINT/SIGTERM.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SENSOR1_PIN 17
#define SENSOR2_PIN 27
#define DEBOUNCE_TIME 50
#define POLL_INTERVAL 10

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

void log_event(int sensor_id, const char* event_type) {
    FILE* log_file = fopen("proximity_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm* tm_info = gmtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

    fprintf(log_file, "%s, Sensor %d, %s\n", timestamp, sensor_id, event_type);
    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio library\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int sensor1_state = gpioRead(SENSOR1_PIN);
    int sensor2_state = gpioRead(SENSOR2_PIN);

    while (running) {
        int new_sensor1_state = gpioRead(SENSOR1_PIN);
        int new_sensor2_state = gpioRead(SENSOR2_PIN);

        if (new_sensor1_state != sensor1_state) {
            if (new_sensor1_state == 0) {
                log_event(1, "DETECTED");
            } else {
                log_event(1, "CLEARED");
            }
            sensor1_state = new_sensor1_state;
        }

        if (new_sensor2_state != sensor2_state) {
            if (new_sensor2_state == 0) {
                log_event(2, "DETECTED");
            } else {
                log_event(2, "CLEARED");
            }
            sensor2_state = new_sensor2_state;
        }

        gpioDelay(POLL_INTERVAL * 1000);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

