This C program uses the pigpio library to interface with two TCRT5000 IR obstacle avoidance sensors connected to GPIO 17 and GPIO 27 on a Raspberry Pi 4 Model B. It polls the sensors every 10 ms with a 50 ms software debounce per sensor. When a state transition is detected, it logs the event with an ISO 8601 UTC timestamp, the sensor ID, and the event type to 'proximity_log.txt'. The program handles graceful shutdown on SIGINT or SIGTERM and ensures clean resource release by closing the log file and calling gpioTerminate() on all exit paths.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x49
#define MEAS_TRIGGER 0x04
#define MEAS_STATUS 0x06
#define DIST_HIGH 0x08
#define DIST_LOW 0x09
#define TIMEOUT_MS 50
#define SAMPLE_INTERVAL_MS 500

int i2c_fd;
FILE *log_file;

void close_resources() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }
}

void log_error(const char *message) {
    fprintf(stderr, "Error: %s (errno=%d)\n", message, errno);
}

int i2c_write_then_read(uint8_t reg, uint8_t *data, size_t data_len) {
    uint8_t buffer[data_len + 1];
    buffer[0] = reg;
    if (write(i2c_fd, buffer, 1) != 1) {
        log_error("Failed to write to I2C device");
        return -1;
    }
    if (read(i2c_fd, data, data_len) != data_len) {
        log_error("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

int read_distance_mm() {
    uint8_t status;
    if (i2c_write_then_read(MEAS_STATUS, &status, 1) != 0) {
        return -1;
    }
    if (!(status & 0x01)) {
        return -1;
    }

    uint8_t dist_high, dist_low;
    if (i2c_write_then_read(DIST_HIGH, &dist_high, 1) != 0) {
        return -1;
    }
    if (i2c_write_then_read(DIST_LOW, &dist_low, 1) != 0) {
        return -1;
    }

    return (dist_high << 8) | dist_low;
}

void log_distance() {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    int distance = read_distance_mm();
    if (distance >= 0) {
        fprintf(log_file, "%s,%d\n", timestamp, distance);
    }
}

void signal_handler(int sig) {
    close_resources();
    exit(0);
}

int main() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        log_error("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen("distance_log.csv", "a");
    if (!log_file) {
        log_error("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        log_distance();
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    close_resources();
    return EXIT_SUCCESS;
}

