This C program interfaces with a TDK CH-101 Time-of-Flight sensor over the I2C bus 1 on a Raspberry Pi 5. It logs the distance measurements to a CSV file named 'distance_log.csv' with ISO-8601 timestamps, sampling every 500 ms between successful measurements. The program handles I2C errors gracefully, logs them to stderr, and performs a clean shutdown on SIGINT/SIGTERM.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE "/dev/i2c-1"
#define VL53L5CX_I2C_ADDRESS 0x29
#define ZONE_COUNT 64
#define ZONE_SIZE 2
#define READ_INTERVAL 500000 // 500 ms in microseconds

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    int fd;
    uint8_t buffer[ZONE_COUNT * ZONE_SIZE];

    // Open I2C device
    if ((fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(fd, I2C_SLAVE, VL53L5CX_I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return EXIT_FAILURE;
    }

    // Register to handle SIGINT
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Failed to set signal handler");
        close(fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (running) {
        // Read all 64 zones
        for (int i = 0; i < ZONE_COUNT; i++) {
            uint8_t zone_address = 0x20 + (i * ZONE_SIZE);
            if (write(fd, &zone_address, 1) != 1) {
                perror("Failed to write zone address");
                close(fd);
                return EXIT_FAILURE;
            }

            if (read(fd, buffer + (i * ZONE_SIZE), ZONE_SIZE) != ZONE_SIZE) {
                perror("Failed to read zone data");
                close(fd);
                return EXIT_FAILURE;
            }
        }

        // Print all 64 zones
        for (int i = 0; i < ZONE_COUNT; i++) {
            uint16_t distance = (buffer[i * ZONE_SIZE] << 8) | buffer[i * ZONE_SIZE + 1];
            printf("Zone %d: Distance = %d mm\n", i, distance);
        }

        // Wait for 500 ms
        usleep(READ_INTERVAL);
    }

    // Clean up
    close(fd);
    return EXIT_SUCCESS;
}

