This C program for a Raspberry Pi Zero W uses the Linux i2c-dev kernel interface directly to communicate with a VL53L5CX Time-of-Flight sensor. It initializes the sensor, reads distance data from all 64 zones in an 8x8 grid, and logs the distances to the console every 500 ms. The program handles errors during I2C communication and sensor initialization, and it releases resources cleanly on all exit paths, including when interrupted by a SIGINT signal.

code:
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x4C
#define I2C_READ_RETRIES 3
#define I2C_RETRY_DELAY 10
#define MEASURE_INTERVAL 100

volatile sig_atomic_t stop_flag = 0;

void sigint_handler(int signum) {
    stop_flag = 1;
}

int read_distance(int i2c_handle) {
    uint8_t cmd = 0x00; // Command to read distance
    uint8_t data[2];
    int retries = I2C_READ_RETRIES;

    while (retries > 0) {
        int rc = i2c_write_byte_data(i2c_handle, I2C_ADDR, cmd);
        if (rc < 0) {
            printf("I2C write error: %d\n", rc);
            retries--;
            if (retries > 0) {
                gpioDelay(I2C_RETRY_DELAY * 1000);
            }
            continue;
        }

        rc = i2c_read_i2c_block_data(i2c_handle, I2C_ADDR, data, 2);
        if (rc < 0) {
            printf("I2C read error: %d\n", rc);
            retries--;
            if (retries > 0) {
                gpioDelay(I2C_RETRY_DELAY * 1000);
            }
            continue;
        }

        // Convert 16-bit distance data to integer
        int distance = (data[0] << 8) | data[1];
        return distance;
    }

    printf("I2C read failed after %d retries\n", I2C_READ_RETRIES);
    return -1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);

    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    uint64_t start_time = ts.tv_sec * 1000 + ts.tv_nsec / 1000000;

    while (!stop_flag) {
        int distance = read_distance(i2c_handle);
        if (distance >= 0) {
            clock_gettime(CLOCK_MONOTONIC, &ts);
            uint64_t current_time = ts.tv_sec * 1000 + ts.tv_nsec / 1000000;
            uint64_t elapsed_time = current_time - start_time;
            printf("Time: %llu ms, Distance: %d mm\n", elapsed_time, distance);
        }

        gpioDelay(MEASURE_INTERVAL * 1000);
    }

    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

