#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 17
#define MIN_DISTANCE 2
#define MAX_DISTANCE 400
#define MIN_ANGLE -90
#define MAX_ANGLE 90
#define TIMEOUT_US 50000
#define LOG_INTERVAL_MS 200

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

void log_distance(double distance) {
    FILE *log_file = fopen("sensor_data.log", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    fprintf(log_file, "%s, Distance: %.2f cm\n", ctime(&now), distance);
    fclose(log_file);
}

double measure_distance() {
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);

    int start_time = gpioTick();
    int end_time = start_time;

    while (gpioRead(ECHO_PIN) == 0 && (gpioTick() - start_time) < TIMEOUT_US) {
        start_time = gpioTick();
    }

    if (gpioRead(ECHO_PIN) == 0) {
        return -1; // Timeout
    }

    while (gpioRead(ECHO_PIN) == 1 && (gpioTick() - end_time) < TIMEOUT_US) {
        end_time = gpioTick();
    }

    if (gpioRead(ECHO_PIN) == 1) {
        return -1; // Timeout
    }

    int pulse_width = end_time - start_time;
    double distance = (double)pulse_width * 0.0343 / 2; // Speed of sound is 343 m/s
    return distance;
}

int map_angle(double distance) {
    if (distance < MIN_DISTANCE) {
        return MIN_ANGLE;
    } else if (distance > MAX_DISTANCE) {
        return MAX_ANGLE;
    } else {
        return (int)((distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE) * (MAX_ANGLE - MIN_ANGLE) + MIN_ANGLE);
    }
}

void set_servo_angle(int angle) {
    gpioServo(SERVO_PIN, (angle + 90) * 2000 / 180);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    gpioSetPullUpDown(TRIGGER_PIN, PI_PUD_OFF);
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_OFF);

    gpioSetServoRange(SERVO_PIN, 2000);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        double distance = measure_distance();
        if (distance >= 0) {
            int angle = map_angle(distance);
            set_servo_angle(angle);
            log_distance(distance);
        }
        gpioDelay(LOG_INTERVAL_MS * 1000);
    }

    set_servo_angle(0);
    gpioTerminate();

    return 0;
}

