#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <mqueue.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define MODEL_ID_REG 0x010F
#define SOFTWARE_RESET_REG 0x0000
#define TIMING_BUDGET_REG 0x0081
#define DATA_READY_REG 0x0089
#define DISTANCE_HIGH_REG 0x0096
#define DISTANCE_LOW_REG 0x0097
#define BUZZER_PIN 23
#define MQ_NAME "/distance_queue"
#define MQ_MAX_SIZE 1024
#define MQ_MSG_SIZE 16

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

int read_i2c(int handle, uint16_t reg, uint8_t *data, size_t len) {
    if (i2c_write_byte_data(handle, reg >> 8, reg & 0xFF) < 0) {
        perror("i2c_write_byte_data");
        return -1;
    }
    if (i2c_read_i2c_block_data(handle, reg >> 8, reg & 0xFF, data, len) < 0) {
        perror("i2c_read_i2c_block_data");
        return -1;
    }
    return 0;
}

int write_i2c(int handle, uint16_t reg, uint8_t *data, size_t len) {
    if (i2c_write_byte_data(handle, reg >> 8, reg & 0xFF) < 0) {
        perror("i2c_write_byte_data");
        return -1;
    }
    if (i2c_write_i2c_block_data(handle, reg >> 8, reg & 0xFF, data, len) < 0) {
        perror("i2c_write_i2c_block_data");
        return -1;
    }
    return 0;
}

int main() {
    int i2c_handle, gpio_handle;
    uint8_t model_id, reset_data[2] = {0x00, 0x01}, timing_budget[2] = {0x00, 0x32}, data_ready, distance[2];
    mqd_t mq;
    struct mq_attr attr;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if ((gpio_handle = gpioSetMode(BUZZER_PIN, PI_OUTPUT)) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if ((i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0)) < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (read_i2c(i2c_handle, MODEL_ID_REG, &model_id, 1) < 0) {
        fprintf(stderr, "Failed to read model ID\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (model_id != 0xEA) {
        fprintf(stderr, "Incorrect model ID: 0x%02X\n", model_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (write_i2c(i2c_handle, SOFTWARE_RESET_REG, reset_data, 2) < 0) {
        fprintf(stderr, "Failed to perform software reset\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (write_i2c(i2c_handle, TIMING_BUDGET_REG, timing_budget, 2) < 0) {
        fprintf(stderr, "Failed to set timing budget\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (write_i2c(i2c_handle, 0x0080, (uint8_t[]){0x01}, 1) < 0) {
        fprintf(stderr, "Failed to start ranging\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    attr.mq_flags = 0;
    attr.mq_maxmsg = MQ_MAX_SIZE;
    attr.mq_msgsize = MQ_MSG_SIZE;
    attr.mq_curmsgs = 0;

    if ((mq = mq_open(MQ_NAME, O_CREAT | O_WRONLY, 0644, &attr)) == (mqd_t)-1) {
        perror("mq_open");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    while (!stop_flag) {
        if (read_i2c(i2c_handle, DATA_READY_REG, &data_ready, 1) < 0) {
            fprintf(stderr, "Failed to read data ready bit\n");
            break;
        }

        if (data_ready & 0x01) {
            if (read_i2c(i2c_handle, DISTANCE_HIGH_REG, distance, 2) < 0) {
                fprintf(stderr, "Failed to read distance\n");
                break;
            }

            uint16_t distance_mm = (distance[0] << 8) | distance[1];
            printf("Distance: %d mm\n", distance_mm);

            if (distance_mm < 100) {
                gpioWrite(BUZZER_PIN, PI_HIGH);
            } else {
                gpioWrite(BUZZER_PIN, PI_LOW);
            }

            char msg[MQ_MSG_SIZE];
            snprintf(msg, MQ_MSG_SIZE, "Distance: %d mm", distance_mm);
            if (mq_send(mq, msg, MQ_MSG_SIZE, 0) == -1) {
                perror("mq_send");
                break;
            }
        }

        usleep(50000);
    }

    mq_close(mq);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

