    if (write_i2c(i2c_handle, 0x0080, (uint8_t[]){0x01}, 1) < 0) {
        fprintf(stderr, "Failed to start ranging\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    attr.mq_flags = 0;
    attr.mq_maxmsg = MQ_MAX_SIZE;
    attr.mq_msgsize = MQ_MSG_SIZE;
    attr.mq_curmsgs = 0;

    if ((mq = mq_open(MQ_NAME, O_CREAT | O_WRONLY, 0644, &attr)) == (mqd_t)-1) {
        perror("mq_open");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    while (!stop_flag) {
        if (read_i2c(i2c_handle, DATA_READY_REG, &data_ready, 1) < 0) {
            fprintf(stderr, "Failed to read data ready bit\n");
            break;
        }

        if (data_ready & 0x01) {
            if (read_i2c(i2c_handle, DISTANCE_HIGH_REG, distance, 2) < 0) {
                fprintf(stderr, "Failed to read distance\n");
                break;
            }

            uint16_t distance_mm = (distance[0] << 8) | distance[1];
            printf("Distance: %d mm\n", distance_mm);

            if (distance_mm < 100) {
                gpioWrite(BUZZER_PIN, PI_HIGH);
            } else {
                gpioWrite(BUZZER_PIN, PI_LOW);
            }

            char msg[MQ_MSG_SIZE];
            snprintf(msg, MQ_MSG_SIZE, "Distance: %d mm", distance_mm);
            if (mq_send(mq, msg, MQ_MSG_SIZE, 0) == -1) {
                perror("mq_send");
                break;
            }
        }

        usleep(50000);
    }

    mq_close(mq);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}
