                buzzer_active = 1;
            } else if (buzzer_active) {
                gpioWrite(BUZZER_PIN, 0);
                buzzer_active = 0;
            }
        }

        gpioDelay(DISTANCE_UPDATE_INTERVAL * 1000);
    }

    return 0;
}

