#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <paho-mqtt.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define SERVO_PIN 18
#define DISTANCE_THRESHOLD 20
#define I2C_RETRIES 5
#define MQTT_BROKER "tcp://localhost:1883"
#define MQTT_TOPIC "gate_control"

typedef enum {
    GATE_CLOSED,
    GATE_OPENING,
    GATE_OPEN,
    GATE_CLOSING
} GateState;

typedef struct {
    FILE *log_file;
    GateState state;
    int distance;
} GateControl;

void log_event(GateControl *gc, const char *event) {
    time_t now = time(NULL);
    fprintf(gc->log_file, "%s: %s\n", ctime(&now), event);
    fflush(gc->log_file);
}

void handle_mqtt_message(void *context, char *topicName, int topicLen, MQTTMessage *message) {
    GateControl *gc = (GateControl *)context;
    char *payload = (char *)malloc(message->payloadlen + 1);
    memcpy(payload, message->payload, message->payloadlen);
    payload[message->payloadlen] = '\0';

    if (strcmp(payload, "force_open") == 0) {
        log_event(gc, "Force open command received");
        gpioServo(SERVO_PIN, 2000); // Open position
        gc->state = GATE_OPENING;
    } else if (strcmp(payload, "force_close") == 0) {
        log_event(gc, "Force close command received");
        gpioServo(SERVO_PIN, 500); // Close position
        gc->state = GATE_CLOSING;
    } else if (strcmp(payload, "status_request") == 0) {
        char status[50];
        switch (gc->state) {
            case GATE_CLOSED: strcpy(status, "Closed"); break;
            case GATE_OPENING: strcpy(status, "Opening"); break;
            case GATE_OPEN: strcpy(status, "Open"); break;
            case GATE_CLOSING: strcpy(status, "Closing"); break;
        }
        log_event(gc, "Status request received");
        printf("Gate status: %s\n", status);
    }

    free(payload);
}

void init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for servo\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    gpioSetPWMfrequency(SERVO_PIN, 50); // 50 Hz PWM frequency
}

void init_mqtt(GateControl *gc) {
    MQTTClient client;
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    MQTTClient_create(&client, MQTT_BROKER, "gate_control_client", MQTTCLIENT_PERSISTENCE_NONE, NULL);
    if (MQTTClient_connect(client, &conn_opts) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker\n");
        MQTTClient_destroy(&client);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    MQTTClient_subscribe(client, MQTT_TOPIC, 0);
    MQTTClient_setCallbacks(client, gc, NULL, handle_mqtt_message, NULL);

    gc->log_file = fopen("gate_log.txt", "a");
    if (!gc->log_file) {
        fprintf(stderr, "Failed to open log file\n");
        MQTTClient_destroy(&client);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void read_distance(GateControl *gc) {
    int retries = I2C_RETRIES;
    while (retries--) {
        uint8_t cmd = 0x00;
        if (gpioI2CWrite(gc->i2c_handle, &cmd, 1) != 1) {
            fprintf(stderr, "I2C write failed\n");
            continue;
        }

        uint8_t data[2];
        if (gpioI2CRead(gc->i2c_handle, data, 2) != 2) {
            fprintf(stderr, "I2C read failed\n");
            continue;
        }

        gc->distance = (data[0] << 8) | data[1];
        break;
    }
}

void control_gate(GateControl *gc) {
    if (gc->distance < DISTANCE_THRESHOLD) {
        if (gc->state != GATE_OPENING && gc->state != GATE_OPEN) {
            log_event(gc, "Object detected, opening gate");
            gpioServo(SERVO_PIN, 2000); // Open position
            gc->state = GATE_OPENING;
        }
    } else {
        if (gc->state != GATE_CLOSING && gc->state != GATE_CLOSED) {
            log_event(gc, "Path clear, closing gate");
            gpioServo(SERVO_PIN, 500); // Close position
            gc->state = GATE_CLOSING;
        }
    }
}

void cleanup(GateControl *gc) {
    if (gc->log_file) {
        fclose(gc->log_file);
    }
    MQTTClient_destroy(&gc->mqtt_client);
    gpioTerminate();
}

int main() {
    GateControl gc = {0};
    gc.i2c_handle = gpioI2COpen(I2C_BUS, I2C_ADDR, 0);
    if (gc.i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        exit(EXIT_FAILURE);
    }

    init_i2c();
    init_mqtt(&gc);

    signal(SIGINT, (void (*)(int))cleanup);
    signal(SIGTERM, (void (*)(int))cleanup);

    while (1) {
        read_distance(&gc);
        control_gate(&gc);
        sleep(1);
    }

    return 0;
}

