#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pigpio.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define TRIGGER_PULSE_WIDTH 10
#define MIN_PULSE_WIDTH 100
#define MAX_PULSE_WIDTH 30000
#define MEASUREMENT_INTERVAL 200000
#define TIMEOUT_INTERVAL 60000

FILE *log_file = NULL;

void log_distance(double distance) {
    time_t now = time(NULL);
    char *iso_time = ctime(&now);
    iso_time[strlen(iso_time) - 1] = '\0'; // Remove newline character

    printf("%s: Distance: %.2f cm\n", iso_time, distance);
    fprintf(log_file, "%s: Distance: %.2f cm\n", iso_time, distance);
    fflush(log_file);
}

void alert_callback(int gpio, int level, uint32_t tick) {
    static uint32_t last_tick = 0;
    static int state = 0; // 0: waiting for rising edge, 1: waiting for falling edge

    if (gpio == ECHO_PIN) {
        if (level == PI_TIMEOUT) {
            printf("Timeout warning: No echo received within 60 ms.\n");
            return;
        }

        if (state == 0 && level == 1) {
            last_tick = tick;
            state = 1;
        } else if (state == 1 && level == 0) {
            uint32_t pulse_width = tick - last_tick;
            if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
                printf("Warning: Invalid pulse width: %u us\n", pulse_width);
            } else {
                double distance = (pulse_width * 0.0343) / 2;
                log_distance(distance);
            }
            state = 0;
        }
    }
}

void cleanup() {
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

