    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return 1;
    }

    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set TRIG_PIN as output.\n");
        cleanup();
        return 1;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set ECHO_PIN as input.\n");
        cleanup();
        return 1;
    }

    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set pull-down resistor on ECHO_PIN.\n");
        cleanup();
        return 1;
    }

    if (gpioSetAlertFunc(ECHO_PIN, alert_callback) < 0) {
        fprintf(stderr, "Failed to set alert callback for ECHO_PIN.\n");
        cleanup();
        return 1;
    }

    log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file.\n");
        cleanup();
        return 1;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        gpioWrite(TRIG_PIN, 1);
        gpioDelay(TRIGGER_PULSE_WIDTH);
        gpioWrite(TRIG_PIN, 0);

        gpioDelay(MEASUREMENT_INTERVAL);
    }

    cleanup();
    return 0;
