        fprintf(stderr, "Failed to set GPIO alert function\n");
        cleanup();
        return 1;
    }

    if (i2cWriteByte(I2C_BUS, I2C_ADDR, 0x01) != 1) {
        fprintf(stderr, "Failed to verify sensor model ID\n");
        cleanup();
        return 1;
