#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <signal.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define GPIO_OPEN 18
#define GPIO_CLOSE 19
#define DISTANCE_REG 0x14
#define SOFT_RESET_REG 0x0000
#define SOFT_RESET_VAL 0x0001
#define TIMING_BUDGET 20000

FILE *log_file;
int i2c_handle;

void log_event(const char *event) {
    time_t now = time(NULL);
    char *iso_time = ctime(&now);
    iso_time[strlen(iso_time) - 1] = '\0'; // Remove newline
    fprintf(log_file, "%s: %s\n", iso_time, event);
    fflush(log_file);
}

void handle_signal(int sig) {
    log_event("Program terminated by signal");
    gpioTerminate();
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if ((i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0)) < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return 1;
    }

    // Soft reset VL53L1X
    uint8_t reset_data[2] = {SOFT_RESET_REG >> 8, SOFT_RESET_REG & 0xFF};
    if (i2cWriteI2CBlockData(i2c_handle, SOFT_RESET_REG, reset_data, 2) < 0) {
        fprintf(stderr, "Failed to soft reset VL53L1X\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure timing budget
    uint8_t budget_data[2] = {TIMING_BUDGET >> 8, TIMING_BUDGET & 0xFF};
    if (i2cWriteI2CBlockData(i2c_handle, 0x0081, budget_data, 2) < 0) {
        fprintf(stderr, "Failed to set timing budget\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Start ranging
    if (i2cWriteI2CBlockData(i2c_handle, 0x0087, (uint8_t[]){0x00}, 1) < 0) {
        fprintf(stderr, "Failed to start ranging\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    if ((log_file = fopen("gate_events.log", "a")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up GPIO pins
    if (gpioSetMode(GPIO_OPEN, PI_OUTPUT) < 0 || gpioSetMode(GPIO_CLOSE, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        uint8_t distance_data[2];
        if (i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, distance_data, 2) < 0) {
            fprintf(stderr, "Failed to read distance\n");
            log_event("Sensor absent or bus error");
            gpioWrite(GPIO_OPEN, 0);
            gpioWrite(GPIO_CLOSE, 1);
        } else {
            uint16_t distance = (distance_data[0] << 8) | distance_data[1];
            if (distance < 200) {
                gpioWrite(GPIO_OPEN, 1);
                gpioWrite(GPIO_CLOSE, 0);
                log_event("Gate opened");
            } else {
                gpioWrite(GPIO_OPEN, 0);
                gpioWrite(GPIO_CLOSE, 1);
                log_event("Gate closed");
            }
        }

        gpioDelay(500000); // 500 ms
    }

    return 0;
}

