#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define GPIO_TRIGGER 24
#define GPIO_MOTOR_FORWARD 17
#define GPIO_MOTOR_BACKWARD 18
#define SOFT_RESET_REG 0x0000
#define START_MEASUREMENT_REG 0x0000
#define DATA_READY_REG 0x0089
#define DISTANCE_HIGH_REG 0x0096
#define DISTANCE_LOW_REG 0x0097
#define MIN_DISTANCE 100
#define MAX_DISTANCE 300

volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
}

int i2c_retry(int fd, uint8_t reg, uint8_t *data, size_t len, int retries) {
    for (int i = 0; i < retries; i++) {
        if (i2cWriteByteData(fd, reg, *data) == PI_OK) {
            return 0;
        }
        usleep(1000 * (1 << i));
    }
    return -1;
}

int i2c_read_retry(int fd, uint8_t reg, uint8_t *data, size_t len, int retries) {
    for (int i = 0; i < retries; i++) {
        if (i2cReadByteData(fd, reg) == PI_OK) {
            *data = i2cReadByteData(fd, reg);
            return 0;
        }
        usleep(1000 * (1 << i));
    }
    return -1;
}

void motor_control(int distance) {
    if (distance < MIN_DISTANCE) {
        gpioWrite(GPIO_MOTOR_FORWARD, 1);
        gpioWrite(GPIO_MOTOR_BACKWARD, 0);
    } else if (distance > MAX_DISTANCE) {
        gpioWrite(GPIO_MOTOR_FORWARD, 0);
        gpioWrite(GPIO_MOTOR_BACKWARD, 1);
    } else {
        gpioWrite(GPIO_MOTOR_FORWARD, 0);
        gpioWrite(GPIO_MOTOR_BACKWARD, 0);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(GPIO_TRIGGER, PI_INPUT) != PI_OK) {
        fprintf(stderr, "Failed to set GPIO24 as input\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(GPIO_MOTOR_FORWARD, PI_OUTPUT) != PI_OK) {
        fprintf(stderr, "Failed to set GPIO17 as output\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(GPIO_MOTOR_BACKWARD, PI_OUTPUT) != PI_OK) {
        fprintf(stderr, "Failed to set GPIO18 as output\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(GPIO_TRIGGER, PI_PUD_UP) != PI_OK) {
        fprintf(stderr, "Failed to set pull-up on GPIO24\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetISRFunc(GPIO_TRIGGER, RISING_EDGE, 0, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR on GPIO24\n");
        gpioTerminate();
        return 1;
    }

    int i2c_fd = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        uint8_t reset_data = 0x00;
        if (i2c_retry(i2c_fd, SOFT_RESET_REG, &reset_data, 1, 5) != 0) {
            fprintf(stderr, "Failed to soft reset VL53L1X\n");
            break;
        }
        usleep(1000);

        reset_data = 0x01;
        if (i2c_retry(i2c_fd, START_MEASUREMENT_REG, &reset_data, 1, 5) != 0) {
            fprintf(stderr, "Failed to start measurement\n");
            break;
        }

        uint8_t data_ready = 0;
        while (1) {
            if (i2c_read_retry(i2c_fd, DATA_READY_REG, &data_ready, 1, 5) != 0) {
                fprintf(stderr, "Failed to read data ready status\n");
                break;
            }
            if (data_ready & 0x01) {
                break;
            }
            usleep(100);
        }

        uint8_t distance_high = 0, distance_low = 0;
        if (i2c_read_retry(i2c_fd, DISTANCE_HIGH_REG, &distance_high, 1, 5) != 0) {
            fprintf(stderr, "Failed to read distance high\n");
            break;
        }
        if (i2c_read_retry(i2c_fd, DISTANCE_LOW_REG, &distance_low, 1, 5) != 0) {
            fprintf(stderr, "Failed to read distance low\n");
            break;
        }

        uint16_t distance = (distance_high << 8) | distance_low;
        printf("Distance: %d mm\n", distance);

        motor_control(distance);
    }

    gpioWrite(GPIO_MOTOR_FORWARD, 0);
    gpioWrite(GPIO_MOTOR_BACKWARD, 0);
    i2cClose(i2c_fd);
    gpioTerminate();

    return 0;
}

