    if (write(i2c_fd, init_values, sizeof(init_values)) != sizeof(init_values)) {
        perror("Failed to initialize sensor");
        for (int i = 0; i < GPIO_COUNT; i++) {
            gpiod_line_release(gpio_lines[i]);
        }
        gpiod_chip_close(chip);
        close(i2c_fd);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Read touch status
        if (read(i2c_fd, touch_status, sizeof(touch_status)) != sizeof(touch_status)) {
            perror("Failed to read touch status");
            for (int i = 0; i < GPIO_COUNT; i++) {
                gpiod_line_release(gpio_lines[i]);
            }
            gpiod_chip_close(chip);
            close(i2c_fd);
            fclose(log_file);
            return EXIT_FAILURE;
        }

        // Determine active electrode
        int new_active_led = -1;
        for (int i = 0; i < 12; i++) {
            if (touch_status[i / 8] & (1 << (i % 8))) {
                new_active_led = i;
                break;
            }
        }

        // Update LED pattern
        if (new_active_led != active_led) {
            if (active_led != -1) {
                gpiod_line_set_value(gpio_lines[active_led], 0);
            }
            if (new_active_led != -1) {
                gpiod_line_set_value(gpio_lines[new_active_led], 1);
                active_led = new_active_led;
            }
        }

        // Log event
        if (new_active_led == -1) {
            log_event("No electrode active");
        } else {
            log_event("Electrode active: ELE0 + new_active_led");
        }

        // Sleep for poll interval
        usleep(POLL_INTERVAL * 1000);
    }

    // Clean up
    for (int i = 0; i < GPIO_COUNT; i++) {
        gpiod_line_release(gpio_lines[i]);
    }
    gpiod_chip_close(chip);
    close(i2c_fd);
    fclose(log_file);

    return EXIT_SUCCESS;
}
