    trigger_line = gpiod_chip_get_line(chip, 17);
    if (!trigger_line) {
        perror("Failed to get trigger line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(trigger_line, "distance_sensor_trigger", 0)) {
        perror("Failed to request trigger line as output");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request the echo line as input
    echo_line = gpiod_chip_get_line(chip, 18);
    if (!echo_line) {
        perror("Failed to get echo line");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_input(echo_line, "distance_sensor_echo")) {
        perror("Failed to request echo line as input");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up the SIGINT handler
    signal(SIGINT, sigint_handler);

    while (!stop_flag) {
        // Trigger the sensor
        if (gpiod_line_set_value(trigger_line, 0) < 0) {
            perror("Failed to set trigger line low");
            continue;
        }
        usleep(5);
        if (gpiod_line_set_value(trigger_line, 1) < 0) {
            perror("Failed to set trigger line high");
            continue;
        }
        usleep(10);
        if (gpiod_line_set_value(trigger_line, 0) < 0) {
            perror("Failed to set trigger line low");
            continue;
        }

        // Wait for the echo rising edge
        if (gpiod_line_event_wait(echo_line, &start, TIMEOUT_US) < 0) {
            perror("Failed to wait for echo rising edge");
            continue;
        }
        if (gpiod_line_event_read(echo_line, &start) < 0) {
            perror("Failed to read echo rising edge");
            continue;
        }

        // Wait for the echo falling edge
        if (gpiod_line_event_wait(echo_line, &end, TIMEOUT_US) < 0) {
            perror("Failed to wait for echo falling edge");
            continue;
        }
        if (gpiod_line_event_read(echo_line, &end) < 0) {
            perror("Failed to read echo falling edge");
            continue;
        }

        // Calculate the pulse width
        pulse_us = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;

        // Calculate the distance
        double distance = (pulse_us * 0.0343) / 2.0;

        // Check the distance range
        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            fprintf(log_file, "Distance out of range: %.2f cm\n", distance);
            fflush(log_file);
            continue;
        }

        // Log the distance with an ISO 8601 UTC timestamp
        time_t now = time(NULL);
        struct tm *utc_time = gmtime(&now);
        fprintf(log_file, "%04d-%02d-%02dT%02d:%02d:%02dZ: %.2f cm\n",
                utc_time->tm_year + 1900, utc_time->tm_mon + 1, utc_time->tm_mday,
                utc_time->tm_hour, utc_time->tm_min, utc_time->tm_sec, distance);
        fflush(log_file);

        // Sleep for one second
        sleep(1);
    }

    // Release the lines and close the log file
    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);
    fclose(log_file);

    return EXIT_SUCCESS;
}
