#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TRIG_PIN 17
#define ECHO_PIN 18
#define TRIGGER_US 10
#define MIN_PULSE_US 58
#define MAX_PULSE_US 25000

volatile int echo_width = 0;
volatile int echo_start = 0;
volatile int log_fd = -1;
volatile int running = 1;

void gpio_callback(int gpio, int level, uint32_t tick) {
    if (gpio == ECHO_PIN) {
        if (level == PIGPIO_BOTH_EDGES) {
            if (echo_width == 0) {
                echo_start = tick;
            } else {
                echo_width = tick - echo_start;
            }
        }
    }
}

void signal_handler(int sig) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set TRIG_PIN mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set ECHO_PIN mode\n");
        gpioTerminate();
        return 1;
    }

    if ((log_fd = open("distance_log.txt", O_WRONLY | O_CREAT | O_APPEND, 0644)) < 0) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    gpioSetISRFuncEx(ECHO_PIN, PIGPIO_BOTH_EDGES, 0, gpio_callback, NULL);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        gpioWrite(TRIG_PIN, PI_HIGH);
        gpioDelay(TRIGGER_US * 1000);
        gpioWrite(TRIG_PIN, PI_LOW);

        if (echo_width > 0 && echo_width >= MIN_PULSE_US && echo_width <= MAX_PULSE_US) {
            double distance = echo_width * 343 / 2e6;
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

            char log_entry[100];
            snprintf(log_entry, sizeof(log_entry), "%s: Distance = %.2f m\n", timestamp, distance);
            write(log_fd, log_entry, strlen(log_entry));
        }

        gpioDelay(1000000); // 1 second
    }

    gpioSetISRFuncEx(ECHO_PIN, PIGPIO_BOTH_EDGES, 0, NULL, NULL);
    close(log_fd);
    gpioTerminate();

    return 0;
}

