This C program for a Raspberry Pi Zero W uses the pigpio library to measure distance with an HC-SR04 ultrasonic sensor. It initializes the GPIO pins, sets up an interrupt-driven callback to measure the echo pulse width, and logs each valid distance reading with a timestamp to a file. The program handles signal interrupts for clean shutdown and ensures proper resource cleanup.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pigpio.h>
#include <syslog.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define XSHUT_PIN 27
#define DISTANCE_REG 0x0014
#define STATUS_REG 0x0016
#define MODE_REG 0x0018
#define TIMEOUT_REG 0x0019
#define START_REG 0x0020

void log_message(int level, const char *format, ...) {
    va_list args;
    va_start(args, format);
    vsyslog(level, format, args);
    va_end(args);
}

void signal_handler(int signum) {
    log_message(LOG_INFO, "Received signal %d, exiting...", signum);
    gpioTerminate();
    exit(signum);
}

int main() {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "Failed to initialise pigpio");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(XSHUT_PIN, PI_OUTPUT) < 0) {
        log_message(LOG_ERR, "Failed to set GPIO%d as output", XSHUT_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(XSHUT_PIN, PI_HIGH);
    usleep(10000); // 10 ms delay

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        log_message(LOG_ERR, "Failed to open I2C device at address 0x%02X", I2C_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t mode_data[] = {0x00};
    if (i2cWriteDevice(i2c_handle, MODE_REG, mode_data, sizeof(mode_data)) < 0) {
        log_message(LOG_ERR, "Failed to write to mode register");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t timeout_data[] = {0x00};
    if (i2cWriteDevice(i2c_handle, TIMEOUT_REG, timeout_data, sizeof(timeout_data)) < 0) {
        log_message(LOG_ERR, "Failed to write to timeout register");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t start_data[] = {0x01};
    if (i2cWriteDevice(i2c_handle, START_REG, start_data, sizeof(start_data)) < 0) {
        log_message(LOG_ERR, "Failed to start ranging");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        uint8_t distance_data[2];
        if (i2cReadDevice(i2c_handle, DISTANCE_REG, distance_data, sizeof(distance_data)) < 0) {
            log_message(LOG_ERR, "Failed to read distance data");
        } else {
            uint16_t distance = (distance_data[1] << 8) | distance_data[0];
            uint8_t status_data;
            if (i2cReadDevice(i2c_handle, STATUS_REG, &status_data, sizeof(status_data)) < 0) {
                log_message(LOG_ERR, "Failed to read status data");
            } else {
                log_message(LOG_INFO, "Timestamp: %lu, Distance: %u mm, Status: 0x%02X", time(NULL), distance, status_data);
            }
        }

        usleep(100000); // 100 ms delay
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

