This program will continuously read the distance and status from the VL53L1X sensor and log the information to the systemd journal. It handles errors gracefully and ensures that resources are properly released on exit.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define GPIO_GATE 24
#define MODEL_ID_REG 0x010F
#define RANGE_MODE_REG 0x0021
#define START_RANGING_REG 0x0015
#define DISTANCE_HIGH_REG 0x0089
#define DISTANCE_LOW_REG 0x008A
#define LOG_FILE "gate_log.txt"

void log_event(const char *event) {
    FILE *log = fopen(LOG_FILE, "a");
    if (log == NULL) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    fprintf(log, "%s: %s\n", ctime(&now), event);
    fclose(log);
}

void handle_sigint(int sig) {
    gpioTerminate();
    log_event("Graceful shutdown initiated");
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    if (gpioSetMode(GPIO_GATE, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(GPIO_GATE, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set GPIO pull-up/down\n");
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(GPIO_GATE, 0) < 0) {
        fprintf(stderr, "Failed to set GPIO state\n");
        gpioTerminate();
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    uint8_t model_id[1];
    if (i2cReadDevice(i2c_handle, MODEL_ID_REG, model_id, 1) != 1) {
        fprintf(stderr, "Failed to read model ID\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (model_id[0] != 0xEA) {
        fprintf(stderr, "Incorrect model ID\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t range_mode[1] = {0x00};
    if (i2cWriteDevice(i2c_handle, RANGE_MODE_REG, range_mode, 1) != 1) {
        fprintf(stderr, "Failed to set ranging mode\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t start_ranging[1] = {0x01};
    if (i2cWriteDevice(i2c_handle, START_RANGING_REG, start_ranging, 1) != 1) {
        fprintf(stderr, "Failed to start ranging\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    int gate_state = 0;
    while (1) {
        uint8_t distance_high[1], distance_low[1];
        if (i2cReadDevice(i2c_handle, DISTANCE_HIGH_REG, distance_high, 1) != 1 ||
            i2cReadDevice(i2c_handle, DISTANCE_LOW_REG, distance_low, 1) != 1) {
            fprintf(stderr, "Failed to read distance\n");
            continue;
        }

        uint16_t distance_mm = (distance_high[0] << 8) | distance_low[0];
        float distance_cm = distance_mm / 10.0;

        if (distance_cm < 20.0) {
            if (!gate_state) {
                gpioWrite(GPIO_GATE, 1);
                gate_state = 1;
                log_event("Gate opened");
            }
        } else {
            if (gate_state) {
                gpioWrite(GPIO_GATE, 0);
                gate_state = 0;
                log_event("Gate closed");
            }
        }

        log_event(fprintf(log, "Distance: %.1f cm\n", distance_cm) < 0 ? "Failed to log distance" : "");

        gpioDelay(100000); // 100 ms
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

