#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18
#define SAMPLES 5
#define TIMEOUT 30000
#define MIN_DISTANCE 2
#define MAX_DISTANCE 400
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define MIN_PULSE 500
#define MAX_PULSE 2500
#define LOG_FILE "distance_log.csv"

volatile sig_atomic_t stop_flag = 0;
volatile int pulse_widths[SAMPLES] = {0};
volatile int index = 0;
volatile int valid_samples = 0;
FILE *log_file = NULL;

void gpio_alert(int gpio, int level, uint32_t tick) {
    static uint32_t last_tick = 0;
    uint32_t duration;

    if (level == PI_TIMEOUT) {
        pulse_widths[index] = -1;
        valid_samples++;
        index = (index + 1) % SAMPLES;
        return;
    }

    if (level == PI_RISING_EDGE) {
        last_tick = tick;
    } else if (level == PI_FALLING_EDGE) {
        duration = tick - last_tick;
        if (duration > 0) {
            pulse_widths[index] = duration;
            valid_samples++;
            index = (index + 1) % SAMPLES;
        }
    }
}

void handle_sigint(int sig) {
    stop_flag = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set trigger pin mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set echo pin mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set servo pin mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFunc(ECHO_PIN, gpio_alert) < 0) {
        fprintf(stderr, "Failed to set alert function\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(SERVO_PIN, 50) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return 1;
    }

    if ((log_file = fopen(LOG_FILE, "w")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    fprintf(log_file, "Timestamp,Distance (cm),Servo Angle (degrees)\n");

    signal(SIGINT, handle_sigint);

    while (!stop_flag) {
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(10);
        gpioWrite(TRIGGER_PIN, 0);

        if (valid_samples > 0) {
            int sum = 0;
            for (int i = 0; i < valid_samples; i++) {
                sum += pulse_widths[i];
            }
            int average_pulse_width = sum / valid_samples;

            double distance = (double)average_pulse_width * 34300 / 2 / 1000000;
            if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
                distance = -1.0;
            }

            int angle = (int)(MIN_ANGLE + (MAX_ANGLE - MIN_ANGLE) * log(distance / MIN_DISTANCE) / log(MAX_DISTANCE / MIN_DISTANCE));
            if (angle < MIN_ANGLE) {
                angle = MIN_ANGLE;
            } else if (angle > MAX_ANGLE) {
                angle = MAX_ANGLE;
            }

            int pulse_width = MIN_PULSE + (MAX_PULSE - MIN_PULSE) * (angle - MIN_ANGLE) / (MAX_ANGLE - MIN_ANGLE);
            gpioServo(SERVO_PIN, pulse_width);

            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

            fprintf(log_file, "%s,%.2f,%d\n", timestamp, distance, angle);
            fflush(log_file);

            valid_samples = 0;
        }

        gpioDelay(100000);
    }

    gpioServo(SERVO_PIN, 0);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

