#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SI1102_I2C_ADDRESS 0x60
#define SI1102_PROXIMITY_REG 0x08
#define SI1102_PROXIMITY_HIGH_REG 0x09
#define SI1102_PROXIMITY_LOW_REG 0x0A
#define GPIO_PIN 27
#define DEFAULT_THRESHOLD 1000

volatile int running = 1;
volatile uint16_t proximity_value = 0;
volatile int threshold = DEFAULT_THRESHOLD;

void log_proximity(int threshold, uint16_t value) {
    FILE *log_file = fopen("proximity.log", "a");
    if (!log_file) {
        perror("Failed to open proximity.log");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d - Proximity: %d, Status: %s\n",
            tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
            tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec,
            value, value > threshold ? "ALERT" : "SAFE");

    fclose(log_file);
}

void gpio_interrupt_callback(int gpio, int level, uint32_t tick) {
    if (level == PI_TIMEOUT) {
        return;
    }

    uint8_t high_byte, low_byte;
    if (i2cReadByteData(pi, SI1102_I2C_ADDRESS, SI1102_PROXIMITY_HIGH_REG, &high_byte) < 0) {
        fprintf(stderr, "Failed to read high byte from Si1102\n");
        return;
    }
    if (i2cReadByteData(pi, SI1102_I2C_ADDRESS, SI1102_PROXIMITY_LOW_REG, &low_byte) < 0) {
        fprintf(stderr, "Failed to read low byte from Si1102\n");
        return;
    }

    proximity_value = (high_byte << 8) | low_byte;
}

void signal_handler(int sig) {
    running = 0;
}

int main(int argc, char *argv[]) {
    int i2c_address = SI1102_I2C_ADDRESS;
    threshold = DEFAULT_THRESHOLD;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-a") == 0 && i + 1 < argc) {
            i2c_address = strtol(argv[i + 1], NULL, 0);
            i++;
        } else if (strcmp(argv[i], "-t") == 0 && i + 1 < argc) {
            threshold = strtol(argv[i + 1], NULL, 0);
            i++;
        } else {
            fprintf(stderr, "Usage: %s [-a <i2c_address>] [-t <threshold>]\n", argv[0]);
            return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    if (i2cOpen(1, i2c_address, 0) < 0) {
