void log_proximity(int threshold, uint16_t value) {
    FILE *log_file = fopen("proximity.log", "a");
    if (!log_file) {
        perror("Failed to open proximity.log");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d - Proximity: %d, Status: %s\n",
            tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
            tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec,
            value, value > threshold ? "ALERT" : "SAFE");

    fclose(log_file);
}

