#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define SPEAKER_PIN 18
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define MIN_DISTANCE 2
#define MAX_DISTANCE 200
#define MIN_FREQ 200
#define MAX_FREQ 2000
#define TIMEOUT 200000

volatile int running = 1;
volatile int prev_freq = 0;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    gpioSetMode(SPEAKER_PIN, PI_OUTPUT);
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        gpioWrite(TRIGGER_PIN, 0);
        gpioDelay(10);
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(10);
        gpioWrite(TRIGGER_PIN, 0);

        int start_time = gpioTick();
        int echo_time = gpioWaitEvent(0, ECHO_PIN, 1, TIMEOUT);

        if (echo_time == 0) {
            if (prev_freq != 0) {
                gpioSetPWMfrequency(SPEAKER_PIN, prev_freq);
            }
            continue;
        }

        int end_time = gpioTick();
        int duration = end_time - start_time;

        if (duration < 0) {
            duration += 0x100000000L;
        }

        int distance = (duration * 0.034 / 2) * 100;

        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            if (prev_freq != 0) {
                gpioSetPWMfrequency(SPEAKER_PIN, prev_freq);
            }
            continue;
        }

        double freq = 200 * exp(distance / 50);

        if (freq < MIN_FREQ) {
            freq = MIN_FREQ;
        } else if (freq > MAX_FREQ) {
            freq = MAX_FREQ;
        }

        gpioSetPWMfrequency(SPEAKER_PIN, (int)freq);
        prev_freq = (int)freq;
    }

    gpioSetPWMfrequency(SPEAKER_PIN, 0);
    gpioTerminate();

    return 0;
}

