This C program for a Raspberry Pi Zero W uses the pigpio library to create a theremin-like instrument. It controls an 8-ohm speaker on GPIO18 with hardware-timed PWM to produce a tone whose pitch is adjusted based on the distance measured by an HC-SR04 ultrasonic sensor. The distance is mapped logarithmically to a frequency range of 200 Hz to 2000 Hz. The program includes robust error checking, signal handlers for graceful termination, and proper resource cleanup.

code:
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18
#define MIN_FREQ 200
#define MAX_FREQ 2000
#define MIN_DIST 5
#define MAX_DIST 50
#define TIMEOUT_US 100000

volatile int running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    signal(SIGINT, sigint_handler);

    int last_distance = 0;
    int last_frequency = 0;

    while (running) {
        gpioWrite(TRIGGER_PIN, 0);
        gpioDelay(10);
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(10);
        gpioWrite(TRIGGER_PIN, 0);

        int start_time = gpioTick();
        int echo_time = start_time;

        while (gpioRead(ECHO_PIN) == 0 && echo_time - start_time < TIMEOUT_US) {
            echo_time = gpioTick();
        }

        if (echo_time - start_time >= TIMEOUT_US) {
            printf("Timeout: No echo received\n");
            last_distance = 0;
        } else {
            while (gpioRead(ECHO_PIN) == 1 && echo_time - start_time < TIMEOUT_US) {
                echo_time = gpioTick();
            }

            int pulse_width = echo_time - start_time;
            int distance = pulse_width * 0.034 / 2;

            if (distance < MIN_DIST || distance > MAX_DIST) {
                printf("Invalid distance: %d cm\n", distance);
                distance = last_distance;
            } else {
                last_distance = distance;
            }

            int frequency = MIN_FREQ + (MAX_FREQ - MIN_FREQ) * (MAX_DIST - distance) / (MAX_DIST - MIN_DIST);
            frequency = frequency < MIN_FREQ ? MIN_FREQ : (frequency > MAX_FREQ ? MAX_FREQ : frequency);

            if (frequency != last_frequency) {
                gpioHardwarePWM(PWM_PIN, frequency, 500000);
                last_frequency = frequency;
            }

            printf("Distance: %d cm, Frequency: %d Hz\n", distance, frequency);
        }

        gpioDelay(10000);
    }

    gpioHardwarePWM(PWM_PIN, 0, 0);
    gpioTerminate();

    return 0;
}

