This C program uses the pigpio library to synthesize a theremin-like instrument on a piezo buzzer connected to GPIO18 (PWM0), with pitch controlled by distance read from an HC-SR04 ultrasonic sensor (trigger on GPIO23, echo on GPIO24). The program initializes the GPIO pins, sets up a signal handler for graceful termination, and enters a loop where it reads the distance from the sensor, calculates the corresponding frequency, and drives the piezo buzzer with that frequency. The program handles sensor read failures gracefully and reports errors. It also prints the distance and frequency to the console each loop iteration, with a 10 ms delay between readings.

code:
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define TIMEOUT 50000
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 400.0
#define TRIGGER_PULSE_WIDTH 10

volatile sig_atomic_t exit_flag = 0;

void sigint_handler(int sig) {
    exit_flag = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    signal(SIGINT, sigint_handler);

    while (!exit_flag) {
        gpioWrite(TRIGGER_PIN, 0);
        gpioDelay(10);
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(TRIGGER_PULSE_WIDTH);
        gpioWrite(TRIGGER_PIN, 0);

        int pulse_width = gpioWaveGetHigh(TRIGGER_PIN, ECHO_PIN, TIMEOUT);
        if (pulse_width == -1) {
            printf("Timeout\n");
        } else {
            double distance = pulse_width / 2.0 / 29.1;
            if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
                printf("Invalid reading\n");
            } else {
                printf("Distance: %.2f cm", distance);
                if (distance < 10.0) {
                    printf(" Too close!\n");
                } else {
                    printf("\n");
                }
            }
        }

        gpioDelay(500000);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

