#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_CE 8
#define SENSOR_INIT_REGISTERS {{0x01, 0x01}, {0x02, 0x00}, {0x00, 0x01}}
#define SENSOR_DATA_REGISTERS {0x0C, 0x0D}
#define LOG_FILE "distance_log.csv"

volatile int running = 1;

void signal_handler(int signum) {
    running = 0;
}

uint16_t read_distance(pigpio_handle spi_handle) {
    uint8_t tx_data[2] = {0x00, 0x00};
    uint8_t rx_data[2];
    if (spiXfer(spi_handle, tx_data, rx_data, 2) != 2) {
        fprintf(stderr, "SPI transfer failed\n");
        return 0;
    }
    return (rx_data[1] << 8) | rx_data[0];
}

int main() {
    pigpio_handle spi_handle;
    FILE *log_file;
    struct timespec ts;
    uint16_t distance;

    if ((spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0)) < 0) {
        fprintf(stderr, "Failed to open SPI channel %d\n", SPI_CHANNEL);
        return EXIT_FAILURE;
    }

    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        spiClose(spi_handle);
        return EXIT_FAILURE;
    }

    for (int i = 0; i < sizeof(SENSOR_INIT_REGISTERS) / sizeof(SENSOR_INIT_REGISTERS[0]); i++) {
        if (gpioWrite(spiCePin(spi_handle, SPI_CE), PI_LOW) != 0) {
            fprintf(stderr, "Failed to set chip select low\n");
            goto cleanup;
        }
        if (spiWrite(spi_handle, SENSOR_INIT_REGISTERS[i].reg, SENSOR_INIT_REGISTERS[i].value) != 1) {
            fprintf(stderr, "Failed to write to register 0x%02X\n", SENSOR_INIT_REGISTERS[i].reg);
            goto cleanup;
        }
        if (gpioWrite(spiCePin(spi_handle, SPI_CE), PI_HIGH) != 0) {
            fprintf(stderr, "Failed to set chip select high\n");
            goto cleanup;
        }
        gpioDelay(1000); // Delay to allow register to update
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        if (gpioWrite(spiCePin(spi_handle, SPI_CE), PI_LOW) != 0) {
            fprintf(stderr, "Failed to set chip select low\n");
            continue;
        }
        if (spiWrite(spi_handle, SENSOR_DATA_REGISTERS[0], 0x00) != 1) {
            fprintf(stderr, "Failed to trigger measurement\n");
            gpioWrite(spiCePin(spi_handle, SPI_CE), PI_HIGH);
            continue;
        }
        gpioDelay(1000); // Delay to allow measurement to complete
        gpioWrite(spiCePin(spi_handle, SPI_CE), PI_HIGH);

        distance = read_distance(spi_handle);
        if (distance == 0) {
            fprintf(stderr, "Sensor read failed\n");
            continue;
        }

        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            fprintf(stderr, "Failed to get timestamp\n");
            continue;
        }

        fprintf(log_file, "%ld.%09ld,%u\n", ts.tv_sec, ts.tv_nsec, distance);
        fflush(log_file);
        gpioDelay(100000); // 100 ms delay
    }

cleanup:
    fclose(log_file);
    spiClose(spi_handle);
    return EXIT_SUCCESS;
}

