        if (gpioWrite(spiCePin(spi_handle, SPI_CE), PI_LOW) != 0) {
            fprintf(stderr, "Failed to set chip select low\n");
            goto cleanup;
        }
        if (spiWrite(spi_handle, SENSOR_INIT_REGISTERS[i].reg, SENSOR_INIT_REGISTERS[i].value) != 1) {
            fprintf(stderr, "Failed to write to register 0x%02X\n", SENSOR_INIT_REGISTERS[i].reg);
            goto cleanup;
        }
        if (gpioWrite(spiCePin(spi_handle, SPI_CE), PI_HIGH) != 0) {
            fprintf(stderr, "Failed to set chip select high\n");
            goto cleanup;
        }
        gpioDelay(1000); // Delay to allow register to update
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        if (gpioWrite(spiCePin(spi_handle, SPI_CE), PI_LOW) != 0) {
            fprintf(stderr, "Failed to set chip select low\n");
            continue;
        }
        if (spiWrite(spi_handle, SENSOR_DATA_REGISTERS[0], 0x00) != 1) {
            fprintf(stderr, "Failed to trigger measurement\n");
            gpioWrite(spiCePin(spi_handle, SPI_CE), PI_HIGH);
            continue;
        }
        gpioDelay(1000); // Delay to allow measurement to complete
        gpioWrite(spiCePin(spi_handle, SPI_CE), PI_HIGH);

        distance = read_distance(spi_handle);
        if (distance == 0) {
            fprintf(stderr, "Sensor read failed\n");
            continue;
        }

        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            fprintf(stderr, "Failed to get timestamp\n");
            continue;
        }

        fprintf(log_file, "%ld.%09ld,%u\n", ts.tv_sec, ts.tv_nsec, distance);
        fflush(log_file);
        gpioDelay(100000); // 100 ms delay
    }

cleanup:
    fclose(log_file);
    spiClose(spi_handle);
    return EXIT_SUCCESS;
}
