#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x60
#define SI1120_PART_ID 0x41
#define SI1120_RESET_REG 0x30
#define SI1120_ALS_LOW_REG 0x22
#define SI1120_ALS_HIGH_REG 0x23
#define SI1120_PS1_LOW_REG 0x18
#define SI1120_PS1_HIGH_REG 0x19
#define RETRY_COUNT 3
#define RETRY_DELAY 10

void log_reading(int als, int ps1) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    FILE *log_file = fopen("si1120_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "%s ALS: %d PS1: %d\n", timestamp, als, ps1);
    fclose(log_file);
}

int read_sensor_data(int i2c_handle) {
    uint8_t data[4];
    int retries = RETRY_COUNT;

    while (retries > 0) {
        if (i2cReadDevice(i2c_handle, SI1120_ALS_LOW_REG, data, 4) == 4) {
            int als = (data[1] << 8) | data[0];
            int ps1 = (data[3] << 8) | data[2];
            log_reading(als, ps1);
            return 0;
        }
        retries--;
        gpioDelay(RETRY_DELAY * 1000);
    }

    fprintf(stderr, "Failed to read sensor data after %d retries\n", RETRY_COUNT);
    return -1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t reset_data = 0x01;
    if (i2cWriteDevice(i2c_handle, SI1120_RESET_REG, &reset_data, 1) != 1) {
        fprintf(stderr, "Failed to reset sensor\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t part_id;
    if (i2cReadDevice(i2c_handle, 0x00, &part_id, 1) != 1) {
        fprintf(stderr, "Failed to read part ID\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (part_id != SI1120_PART_ID) {
        fprintf(stderr, "Incorrect part ID: 0x%02X, expected 0x%02X\n", part_id, SI1120_PART_ID);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, SIG_IGN);
    while (1) {
        if (read_sensor_data(i2c_handle) != 0) {
            break;
        }
        gpioDelay(500 * 1000);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

