#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SI1182_I2C_ADDRESS 0x39
#define SI1182_PART_ID_REG 0x00
#define SI1182_MEAS_RATE_REG 0x08
#define SI1182_ALS_DATA_REG 0x22
#define SI1182_PROX_DATA_REG 0x24
#define SI1182_ALS_CONV_FACTOR 0.1

int i2c_fd;
FILE *log_file;

void close_resources() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
}

void signal_handler(int signum) {
    fprintf(stderr, "Received signal %d, exiting...\n", signum);
    close_resources();
    exit(signum);
}

int main() {
    struct timespec ts;
    char buffer[4];
    uint16_t part_id, als_data, prox_data;
    double lux;

    // Open I2C device
    if ((i2c_fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SI1182_I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Open log file
    if ((log_file = fopen("biometric_log.txt", "a")) == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize sensor
    if (read(i2c_fd, &part_id, sizeof(part_id)) != sizeof(part_id)) {
        perror("Failed to read part ID");
        close_resources();
        exit(EXIT_FAILURE);
    }
    if (part_id != 0x42) {
        fprintf(stderr, "Sensor not found, part ID: 0x%04X\n", part_id);
        close_resources();
        exit(EXIT_FAILURE);
    }

    if (write(i2c_fd, &SI1182_MEAS_RATE_REG, sizeof(SI1182_MEAS_RATE_REG)) != sizeof(SI1182_MEAS_RATE_REG)) {
        perror("Failed to write measurement rate register address");
        close_resources();
        exit(EXIT_FAILURE);
    }

    uint8_t meas_rate = 0x07;
    if (write(i2c_fd, &meas_rate, sizeof(meas_rate)) != sizeof(meas_rate)) {
        perror("Failed to write measurement rate");
        close_resources();
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        // Read ambient light data
        if (write(i2c_fd, &SI1182_ALS_DATA_REG, sizeof(SI1182_ALS_DATA_REG)) != sizeof(SI1182_ALS_DATA_REG)) {
            perror("Failed to write ALS data register address");
            close_resources();
            exit(EXIT_FAILURE);
        }

        if (read(i2c_fd, buffer, sizeof(buffer)) != sizeof(buffer)) {
            perror("Failed to read ALS data");
            close_resources();
            exit(EXIT_FAILURE);
        }
        als_data = (buffer[1] << 8) | buffer[0];

        // Read proximity data
        if (write(i2c_fd, &SI1182_PROX_DATA_REG, sizeof(SI1182_PROX_DATA_REG)) != sizeof(SI1182_PROX_DATA_REG)) {
            perror("Failed to write proximity data register address");
            close_resources();
            exit(EXIT_FAILURE);
        }

        if (read(i2c_fd, buffer, sizeof(buffer)) != sizeof(buffer)) {
            perror("Failed to read proximity data");
            close_resources();
            exit(EXIT_FAILURE);
        }
        prox_data = (buffer[1] << 8) | buffer[0];

        // Convert ambient light to lux
        lux = als_data * SI1182_ALS_CONV_FACTOR;

        // Get current timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("Failed to get current time");
            close_resources();
            exit(EXIT_FAILURE);
        }

        // Log and print reading
        fprintf(log_file, "%ld,%ld,%d,%d\n", ts.tv_sec, ts.tv_nsec / 1000000, (int)lux, prox_data);
        fprintf(stdout, "%ld,%ld,%d,%d\n", ts.tv_sec, ts.tv_nsec / 1000000, (int)lux, prox_data);

        // Sleep for 100 ms
        usleep(100000);
    }

    close_resources();
    return 0;
}

