#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SI1145_I2C_ADDRESS 0x60
#define SI1145_HW_KEY 0x03
#define SI1145_MEAS_RATE 0x02
#define SI1145_NO_INTERRUPT 0x00
#define SI1145_ALS_VIS_IR_ADC_COUNTER 0x0B
#define SI1145_ALS_VIS_ADC_GAIN 0x00
#define SI1145_PS_ADC_COUNTER 0x49
#define SI1145_PS_LED21 0x03
#define SI1145_PS_LED3 0x0F
#define SI1145_PS_ADC_MISC 0x03
#define SI1145_PS_ADC_GAIN 0x07
#define SI1145_COMMAND_PS_FORCE 0x03
#define SI1145_PS1_DATA0 0x16
#define SI1145_PS1_DATA1 0x17

#define MAX_RETRIES 3

volatile int running = 1;

void log_error(const char *message) {
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
    fprintf(stderr, "[%s] Error: %s\n", timestamp, message);
}

void log_proximity(unsigned int proximity) {
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
    fprintf(stdout, "[%s] Proximity: %u\n", timestamp, proximity);
}

void log_to_file(unsigned int proximity) {
    FILE *log_file = fopen("proximity_log.txt", "a");
    if (log_file == NULL) {
        log_error("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
    fprintf(log_file, "[%s] Proximity: %u\n", timestamp, proximity);
    fclose(log_file);
}

void signal_handler(int sig) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(1, SI1145_I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C handle");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    unsigned char init_sequence[] = {
        SI1145_HW_KEY, SI1145_MEAS_RATE, SI1145_NO_INTERRUPT,
        SI1145_ALS_VIS_IR_ADC_COUNTER, SI1145_ALS_VIS_ADC_GAIN,
        SI1145_PS_ADC_COUNTER, SI1145_PS_LED21, SI1145_PS_LED3,
        SI1145_PS_ADC_MISC, SI1145_PS_ADC_GAIN, SI1145_COMMAND_PS_FORCE
    };

    for (int i = 0; i < sizeof(init_sequence) / sizeof(init_sequence[0]); i++) {
        for (int retry = 0; retry < MAX_RETRIES; retry++) {
            int result = i2cWriteByteData(i2c_handle, i, init_sequence[i]);
            if (result >= 0) {
                break;
            }
            log_error("I2C write failed, retrying...");
            if (retry == MAX_RETRIES - 1) {
                log_error("Failed to initialise sensor after multiple retries");
                i2cClose(i2c_handle);
                gpioTerminate();
                return EXIT_FAILURE;
            }
        }
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        unsigned char data[2];
        for (int retry = 0; retry < MAX_RETRIES; retry++) {
            int result = i2cReadByteData(i2c_handle, SI1145_PS1_DATA0, &data[0]);
            if (result >= 0) {
                result = i2cReadByteData(i2c_handle, SI1145_PS1_DATA1, &data[1]);
                if (result >= 0) {
                    unsigned int proximity = (data[1] << 8) | data[0];
                    log_proximity(proximity);
                    log_to_file(proximity);
                    break;
                }
            }
            log_error("I2C read failed, retrying...");
            if (retry == MAX_RETRIES - 1) {
                log_error("Failed to read proximity data after multiple retries");
                break;
            }
        }
        gpioDelay(1000000); // 1 second delay
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

