#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define BUZZER_PIN 27
#define MIN_DISTANCE 20.0

volatile uint32_t echo_start = 0;
volatile uint32_t echo_end = 0;
volatile int distance = 0;
volatile int buzzer_state = 0;

void gpioAlert(int gpio, int level, uint32_t tick) {
    if (gpio == ECHO_PIN) {
        if (level == PI_EVENT_RISING_EDGE) {
            echo_start = tick;
        } else if (level == PI_EVENT_FALLING_EDGE) {
            echo_end = tick;
            uint32_t duration = echo_end - echo_start;
            distance = (int)(duration * 0.0343 / 2);
            if (distance < MIN_DISTANCE) {
                gpioWrite(BUZZER_PIN, 1);
                buzzer_state = 1;
            } else {
                gpioWrite(BUZZER_PIN, 0);
                buzzer_state = 0;
            }
        }
    }
}

void cleanup() {
    gpioTerminate();
    printf("Program terminated.\n");
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    gpioSetAlertFuncEx(ECHO_PIN, gpioAlert, 0);

    signal(SIGINT, cleanup);

    while (1) {
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(10); // 10 us trigger pulse
        gpioWrite(TRIGGER_PIN, 0);

        printf("Distance: %d cm\n", distance);

        if (buzzer_state) {
            printf("Buzzer activated.\n");
        } else {
            printf("Buzzer deactivated.\n");
        }

        sleep(1);
    }

    cleanup();

    return 0;
}

