This C program uses the pigpio library to measure distance with an HC-SR04 ultrasonic sensor and control a buzzer based on the distance. It initializes the GPIO pins, sets up an interrupt-driven edge detection on the echo pin, and handles the SIGINT signal to clean up resources properly. The program measures the distance every second and activates the buzzer if the distance is below 20 cm.

code:
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18
#define MIN_DISTANCE 20
#define MAX_DISTANCE 200
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define SERVO_RANGE 180

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

double measure_distance() {
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);

    int start_time = gpioTick();
    int end_time = start_time;

    while (gpioRead(ECHO_PIN) == 0 && end_time - start_time < 1000000) {
        end_time = gpioTick();
    }

    if (end_time - start_time >= 1000000) {
        return -1.0; // Timeout
    }

    int pulse_width = gpioTick() - end_time;
    double distance = (pulse_width * 0.034 / 2) * 100;

    return distance;
}

void set_servo_angle(int angle) {
    int pulse_width = MIN_PULSE_WIDTH + (angle * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) / SERVO_RANGE);
    gpioServo(SERVO_PIN, pulse_width);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    signal(SIGINT, signal_handler);

    while (running) {
        double distance = measure_distance();
        if (distance >= 0) {
            printf("Distance: %.2f cm\n", distance);
            int angle = (distance - MIN_DISTANCE) * (SERVO_RANGE / (MAX_DISTANCE - MIN_DISTANCE));
            if (angle < 0) angle = 0;
            if (angle > SERVO_RANGE) angle = SERVO_RANGE;
            set_servo_angle(angle);
        } else {
            printf("Echo timeout\n");
        }

        gpioDelay(100000); // 100 ms
    }

    gpioServo(SERVO_PIN, 0);
    gpioTerminate();

    return 0;
}

