This C program for a Raspberry Pi Zero W uses the pigpio library to implement a parking assist system with an HC-SR04 ultrasonic sensor and an SG90 servo motor. It measures distance, displays it in centimeters on the console, and rotates the servo proportionally to the distance. The program handles sensor errors, echo timeouts, and graceful cleanup on SIGINT.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define VL53L1X_MODEL_ID 0xEA
#define VL53L1X_TIMING_BUDGET 20000
#define VL53L1X_DISTANCE_REG 0x1E
#define SERVO_PIN 18
#define SERVO_CLOSED 1000
#define SERVO_OPEN 2000
#define Hysteresis 50

volatile int running = 1;
FILE *log_file;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return 1;
    }

    uint8_t model_id;
    if (i2cReadByteData(i2c_handle, 0x010F, &model_id) < 0) {
        fprintf(stderr, "Failed to read model ID from VL53L1X\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (model_id != VL53L1X_MODEL_ID) {
        fprintf(stderr, "Incorrect model ID: 0x%02X\n", model_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteWordData(i2c_handle, 0x0086, VL53L1X_TIMING_BUDGET) < 0) {
        fprintf(stderr, "Failed to set timing budget\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByteData(i2c_handle, 0x0087, 0x00) < 0) {
        fprintf(stderr, "Failed to start ranging\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SERVO_PIN);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(SERVO_PIN, 50) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("gate_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    uint16_t last_distance = 0;
    while (running) {
        uint16_t distance;
        if (i2cReadWordData(i2c_handle, VL53L1X_DISTANCE_REG, &distance) < 0) {
            fprintf(stderr, "Failed to read distance from VL53L1X\n");
            continue;
        }

        if (distance < 200) {
            if (last_distance >= 200) {
                time_t now = time(NULL);
                fprintf(log_file, "Gate opened at %s", ctime(&now));
                fflush(log_file);
                gpioSetPWMrange(SERVO_PIN, 2000);
                gpioSetPWMfrequency(SERVO_PIN, 50);
                gpioSetPWMrange(SERVO_PIN, 2000);
                gpioSetPWMDutyCycle(SERVO_PIN, SERVO_OPEN);
            }
        } else if (distance > 250) {
            if (last_distance <= 250) {
                time_t now = time(NULL);
                fprintf(log_file, "Gate closed at %s", ctime(&now));
                fflush(log_file);
                gpioSetPWMDutyCycle(SERVO_PIN, SERVO_CLOSED);
            }
        }

        last_distance = distance;
        gpioDelay(100000); // 100 ms
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

