        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("gate_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    uint16_t last_distance = 0;
    while (running) {
        uint16_t distance;
        if (i2cReadWordData(i2c_handle, VL53L1X_DISTANCE_REG, &distance) < 0) {
            fprintf(stderr, "Failed to read distance from VL53L1X\n");
            continue;
        }

        if (distance < 200) {
            if (last_distance >= 200) {
                time_t now = time(NULL);
                fprintf(log_file, "Gate opened at %s", ctime(&now));
                fflush(log_file);
                gpioSetPWMrange(SERVO_PIN, 2000);
                gpioSetPWMfrequency(SERVO_PIN, 50);
                gpioSetPWMrange(SERVO_PIN, 2000);
                gpioSetPWMDutyCycle(SERVO_PIN, SERVO_OPEN);
            }
        } else if (distance > 250) {
            if (last_distance <= 250) {
                time_t now = time(NULL);
                fprintf(log_file, "Gate closed at %s", ctime(&now));
                fflush(log_file);
                gpioSetPWMDutyCycle(SERVO_PIN, SERVO_CLOSED);
            }
        }

        last_distance = distance;
        gpioDelay(100000); // 100 ms
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}
```

This code initializes the pigpio library, opens the I2C bus, verifies the VL53L1X sensor model ID, sets the timing budget, starts ranging, and configures the servo pin. It then enters a loop to poll the distance from the sensor, opens the gate when an object is detected closer than 200 mm, and closes it when the object moves beyond 250 mm with hysteresis. It logs every open/close event with a timestamp to 'gate_log.txt'. The program handles I2C read/write errors gracefully and ensures clean release of the I2C handle, pigpio, and log file on SIGINT.

