#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18
#define MIN_DISTANCE 20
#define MAX_DISTANCE 200
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define TIMEOUT_US 50000
#define DELAY_MS 100

volatile int running = 1;

void sigint_handler(int sig) {
    running = 0;
}

double measure_distance() {
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);

    uint32_t start = gpioTick();
    uint32_t end = start;

    while (gpioRead(ECHO_PIN) == 0 && gpioTick() - start < TIMEOUT_US) {
        start = gpioTick();
    }

    if (gpioTick() - start >= TIMEOUT_US) {
        return -1.0;
    }

    while (gpioRead(ECHO_PIN) == 1 && gpioTick() - start < TIMEOUT_US) {
        end = gpioTick();
    }

    if (gpioTick() - start >= TIMEOUT_US) {
        return -1.0;
    }

    uint32_t pulse_duration_us = end - start;
    return (pulse_duration_us * 0.0343) / 2;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    gpioSetPullUpDown(TRIGGER_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    signal(SIGINT, sigint_handler);

    while (running) {
        double distance = measure_distance();
        if (distance < 0) {
            printf("Sensor timeout\n");
        } else {
            int angle;
            if (distance <= MIN_DISTANCE) {
                angle = MIN_ANGLE;
            } else if (distance >= MAX_DISTANCE) {
                angle = MAX_ANGLE;
            } else {
                angle = MIN_ANGLE + (int)((distance - MIN_DISTANCE) * (MAX_ANGLE - MIN_ANGLE) / (MAX_DISTANCE - MIN_DISTANCE));
            }
            gpioServo(SERVO_PIN, MIN_PULSE_WIDTH + (angle * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) / (MAX_ANGLE - MIN_ANGLE)));
            printf("Distance: %.2f cm, Angle: %d degrees\n", distance, angle);
        }
        gpioDelay(DELAY_MS * 1000);
    }

    gpioServo(SERVO_PIN, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

