#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI7005_ADDRESS 0x40
#define CONFIG_REG 0x03
#define TEMP_REG 0x01
#define HUMIDITY_REG 0x02
#define CONVERSION_TIME 10

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = gpioI2COpen(I2C_BUS, SI7005_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    while (!stop) {
        // Write to CONFIG register
        if (gpioI2CWriteByteData(i2c_handle, CONFIG_REG, 0x00) < 0) {
            fprintf(stderr, "Failed to write to CONFIG register\n");
            gpioI2CClose(i2c_handle);
            i2c_handle = gpioI2COpen(I2C_BUS, SI7005_ADDRESS, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to re-open I2C bus %d\n", I2C_BUS);
                gpioTerminate();
                return EXIT_FAILURE;
            }
        }
        gpioDelay(10000); // 10 ms delay

        // Read temperature register
        uint16_t temp_raw = gpioI2CReadWordData(i2c_handle, TEMP_REG);
        if (temp_raw < 0) {
            fprintf(stderr, "Failed to read temperature register\n");
            gpioI2CClose(i2c_handle);
            i2c_handle = gpioI2COpen(I2C_BUS, SI7005_ADDRESS, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to re-open I2C bus %d\n", I2C_BUS);
                gpioTerminate();
                return EXIT_FAILURE;
            }
        }

        // Read humidity register
        uint16_t humidity_raw = gpioI2CReadWordData(i2c_handle, HUMIDITY_REG);
        if (humidity_raw < 0) {
            fprintf(stderr, "Failed to read humidity register\n");
            gpioI2CClose(i2c_handle);
            i2c_handle = gpioI2COpen(I2C_BUS, SI7005_ADDRESS, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to re-open I2C bus %d\n", I2C_BUS);
                gpioTerminate();
                return EXIT_FAILURE;
            }
        }

        // Convert readings
        double temperature = (175.72 * temp_raw) / 65536.0 - 46.85;
        double humidity = (125.0 * humidity_raw) / 65536.0 - 6.0;

        // Print readings
        printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);

        gpioDelay(2000000); // 2 seconds delay
    }

    gpioI2CClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

