#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define SHT40_I2C_ADDR 0x44
#define SHT40_MEAS_CMD 0xFD
#define SHT40_CRC_POLY 0x31
#define SHT40_CRC_INIT 0xFF
#define SHT40_TEMP_SCALE 175.0 / 65535.0
#define SHT40_HUM_SCALE 125.0 / 65535.0
#define SHT40_TEMP_OFFSET -45.0
#define SHT40_HUM_OFFSET -6.0
#define SHT40_TEMP_MIN 0.0
#define SHT40_TEMP_MAX 100.0
#define SHT40_HUM_MIN 0.0
#define SHT40_HUM_MAX 100.0
#define SHT40_READ_INTERVAL 5000

volatile sig_atomic_t running = 1;

void sig_handler(int signum) {
    running = 0;
}

uint8_t crc8(const uint8_t *data, size_t length, uint8_t polynomial, uint8_t initial) {
    uint8_t crc = initial;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ polynomial;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = gpioI2COpen(1, SHT40_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (running) {
        if (gpioI2CWriteByte(i2c_handle, SHT40_MEAS_CMD) < 0) {
            fprintf(stderr, "Failed to send measurement command\n");
            gpioI2CClose(i2c_handle);
            i2c_handle = gpioI2COpen(1, SHT40_I2C_ADDR, 0);
            if (i2c_handle < 0) {
