#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SENSOR_ADDRESS 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define LOG_FILE "temperature_log.csv"

int i2c_fd;
FILE *log_file;

void init_i2c() {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void log_temperature(float ambient, float object) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
            tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec, ambient, object);
    fflush(log_file);
}

float read_temperature(int reg) {
    uint8_t data[2];
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1.0f;
    }

    if (read(i2c_fd, data, 2) != 2) {
        perror("Failed to read temperature data");
        return -1.0f;
    }

    int16_t raw_temp = (data[0] << 8) | data[1];
    return (float)raw_temp * 0.02f - 273.15f;
}

void cleanup() {
    if (log_file) fclose(log_file);
    if (i2c_fd) close(i2c_fd);
}

void signal_handler(int sig) {
    cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    init_i2c();
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, signal_handler);

    while (1) {
        float ambient = read_temperature(AMBIENT_TEMP_REG);
        float object = read_temperature(OBJECT_TEMP_REG);

        if (ambient != -1.0f && object != -1.0f) {
            log_temperature(ambient, object);
        }

        sleep(5);
    }

    cleanup();
    return 0;
}

