#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x4A
#define SAMPLE_INTERVAL 5000000 // 5 seconds in microseconds
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG "error_log.txt"

void log_error(const char *message) {
    FILE *error_log = fopen(ERROR_LOG, "a");
    if (error_log) {
        time_t now = time(NULL);
        fprintf(error_log, "%s: %s\n", ctime(&now), message);
        fclose(error_log);
    }
}

void log_temperature(double temperature) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        time_t now = time(NULL);
        fprintf(log_file, "%s: %.2f°C\n", ctime(&now), temperature);
        fclose(log_file);
    }
}

void cleanup() {
    pigpioTerminate();
    log_error("Program terminated.");
}

int main() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio library.");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus.");
        cleanup();
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);

    while (1) {
        uint8_t cmd[3] = {0x03, 0x00, 0x00}; // Command to start temperature measurement
        if (i2cWriteDevice(i2c_handle, cmd, sizeof(cmd)) < 0) {
            log_error("Failed to send measurement command to STS30-DIS.");
            cleanup();
            return EXIT_FAILURE;
        }

        // Wait for measurement to complete (500ms)
        gpioDelay(500000);

        uint8_t data[6];
        if (i2cReadDevice(i2c_handle, data, sizeof(data)) < 0) {
            log_error("Failed to read temperature data from STS30-DIS.");
            cleanup();
            return EXIT_FAILURE;
        }

        // Calculate temperature from data
        double temperature = (data[0] << 16) | (data[1] << 8) | data[2];
        temperature = -45 + 175 * (temperature / 65536.0);

        log_temperature(temperature);

        gpioDelay(SAMPLE_INTERVAL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

