#define CMD_READ 0x08
#define CRC_POLY 0x31
#define CRC_INIT 0xFF
#define LOG_FILE "pressure_log.csv"

void log_data(const char *timestamp, int16_t pressure, int16_t temperature) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }
    if (ftell(file) == 0) {
        fprintf(file, "Timestamp,Pressure (Pa),Temperature (°C)\n");
    }
    fprintf(file, "%s,%d,%d\n", timestamp, pressure, temperature);
    fclose(file);
}

uint8_t calculate_crc(const uint8_t *data, size_t length) {
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

void handle_sigint(int sig) {
    gpioTerminate();
    exit(0);
}

