#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define SHT40_ADDRESS 0x44
#define SHT40_MEAS_CMD 0xFD
#define SHT40_CRC_POLY 0x31
#define SHT40_CRC_INIT 0xFF
#define SHT40_LOG_FILE "sht40_log.txt"
#define MEAS_INTERVAL 5

uint8_t crc8(const uint8_t *data, size_t length, uint8_t crc) {
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SHT40_CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    int i2c_fd, log_fd;
    uint8_t buf[6];
    uint16_t temp_raw, humidity_raw;
    float temp, humidity;
    struct timespec ts;
    struct sigaction sa;

    // Open I2C bus
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SHT40_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    if ((log_fd = open(SHT40_LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644)) < 0) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Set up signal handler for SIGINT and SIGTERM
    sa.sa_handler = SIG_IGN;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set signal handler");
        close(i2c_fd);
        close(log_fd);
        return EXIT_FAILURE;
    }

    sa.sa_handler = &cleanup;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set signal handler");
        close(i2c_fd);
        close(log_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        // Send measurement command
        if (write(i2c_fd, &SHT40_MEAS_CMD, 1) != 1) {
            perror("Failed to send measurement command");
            continue;
        }

        // Wait for measurement to complete
        nanosleep(&ts, NULL);

        // Read 6 bytes from sensor
        if (read(i2c_fd, buf, 6) != 6) {
            perror("Failed to read from sensor");
            continue;
        }

        // Validate CRC
        if (crc8(buf, 2, SHT40_CRC_INIT) != buf[2] || crc8(buf + 3, 2, SHT40_CRC_INIT) != buf[5]) {
            fprintf(stderr, "CRC validation failed\n");
            continue;
        }

        // Convert raw data to temperature and humidity
        temp_raw = (buf[0] << 8) | buf[1];
        humidity_raw = (buf[3] << 8) | buf[4];
        temp = -45 + 175 * temp_raw / 65535;
        humidity = 100 * humidity_raw / 65535;

        // Log temperature and humidity with timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
            fprintf(log_fd, "%ld.%09ld %f %f\n", ts.tv_sec, ts.tv_nsec, temp, humidity);
        } else {
            perror("Failed to get timestamp");
        }

        // Wait for next measurement
        sleep(MEAS_INTERVAL);
    }

    return EXIT_SUCCESS;

cleanup:
    close(i2c_fd);
    close(log_fd);
    exit(EXIT_SUCCESS);
}

