code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x28
#define TRIGGER_CMD 0x2196
#define MEASUREMENT_DELAY 1000
#define SAMPLE_INTERVAL 100
#define RETRY_COUNT 3
#define BACKOFF_FACTOR 2

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("airflow.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!stop_flag) {
        for (int attempt = 0; attempt < RETRY_COUNT; ++attempt) {
            if (i2cWriteDevice(i2c_handle, &TRIGGER_CMD, 2) >= 0) {
                gpioDelay(MEASUREMENT_DELAY);
                uint8_t buffer[6];
                if (i2cReadDevice(i2c_handle, buffer, 6) >= 0) {
                    uint16_t raw_pressure = (buffer[0] << 8) | buffer[1];
                    uint16_t raw_temperature = (buffer[3] << 8) | buffer[4];
                    double pressure_pa = raw_pressure / 60.0;
                    double temperature_c = raw_temperature / 200.0;

                    time_t now = time(NULL);
                    struct tm *tm_info = localtime(&now);
                    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d,%f,%f\n",
                            tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
                            tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec,
                            pressure_pa, temperature_c);
                    fflush(log_file);
                    break;
                }
            }
            gpioDelay(SAMPLE_INTERVAL * BACKOFF_FACTOR);
        }
        gpioDelay(SAMPLE_INTERVAL);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

