#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define TEMP_CMD 0xF3
#define HUM_CMD 0xF5
#define MEAS_TIME 20
#define SAMPLE_INTERVAL 5

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

int main() {
    int i2c_handle;
    FILE *log_file;
    time_t now;
    struct tm *tm_info;
    uint16_t raw_temp, raw_hum;
    double temperature, humidity;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", pigpio_error(gpioInitialise()));
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("sensor_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    while (!stop_flag) {
        // Read temperature
        if (i2cWriteByte(i2c_handle, TEMP_CMD) < 0) {
            fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
            goto cleanup;
        }
        gpioDelay(MEAS_TIME * 1000);
        if (i2cReadDevice(i2c_handle, (char *)&raw_temp, 2) != 2) {
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
            goto cleanup;
        }
        temperature = (175.72 * raw_temp / 65536.0) - 46.85;

        // Read humidity
        if (i2cWriteByte(i2c_handle, HUM_CMD) < 0) {
            fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
            goto cleanup;
        }
        gpioDelay(MEAS_TIME * 1000);
        if (i2cReadDevice(i2c_handle, (char *)&raw_hum, 2) != 2) {
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
            goto cleanup;
        }
        humidity = (125.0 * raw_hum / 65536.0) - 6.0;
        if (humidity < 0) humidity = 0;
        if (humidity > 100) humidity = 100;

        // Log and print the data
        time(&now);
        tm_info = localtime(&now);
        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, Temp: %.2f°C, Humidity: %.2f%%\n",
                tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
                tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec,
                temperature, humidity);
        printf("Temp: %.2f°C, Humidity: %.2f%%\n", temperature, humidity);

        gpioDelay(SAMPLE_INTERVAL * 1000 * 1000);
    }

cleanup:
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

