        }
        gpioDelay(MEAS_TIME * 1000);
        if (i2cReadDevice(i2c_handle, (char *)&raw_temp, 2) != 2) {
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
            goto cleanup;
        }
        temperature = (175.72 * raw_temp / 65536.0) - 46.85;

        // Read humidity
        if (i2cWriteByte(i2c_handle, HUM_CMD) < 0) {
            fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
            goto cleanup;
        }
        gpioDelay(MEAS_TIME * 1000);
        if (i2cReadDevice(i2c_handle, (char *)&raw_hum, 2) != 2) {
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
            goto cleanup;
        }
        humidity = (125.0 * raw_hum / 65536.0) - 6.0;
        if (humidity < 0) humidity = 0;
        if (humidity > 100) humidity = 100;

        // Log and print the data
        time(&now);
        tm_info = localtime(&now);
        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, Temp: %.2f°C, Humidity: %.2f%%\n",
                tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
                tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec,
                temperature, humidity);
        printf("Temp: %.2f°C, Humidity: %.2f%%\n", temperature, humidity);

        gpioDelay(SAMPLE_INTERVAL * 1000 * 1000);
    }

cleanup:
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}
