This program initializes the pigpio library, opens the I2C bus, and reads temperature and humidity from the Si7015 sensor. It logs each reading with a timestamp to 'sensor_data.txt' and prints it to the console. The program handles SIGINT (Ctrl+C) to clean up resources before exiting. It retries on transient I2C failures and exits cleanly on sensor-absent or bus-error conditions.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x25
#define MEASURE_CMD 0x362F
#define CRC8_POLYNOMIAL 0x31
#define LOG_FILE "airflow_data.txt"

int i2c_fd = -1;
FILE *log_file = NULL;

void handle_signal(int sig) {
    if (log_file) fclose(log_file);
    if (i2c_fd >= 0) close(i2c_fd);
    exit(0);
}

unsigned char calculate_crc8(unsigned char *data, size_t length) {
    unsigned char crc = 0;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            else crc <<= 1;
        }
    }
    return crc;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    fprintf(log_file, "Timestamp,Pressure (Pa),Temperature (°C)\n");

    while (1) {
        if (write(i2c_fd, &MEASURE_CMD, 2) != 2) {
            perror("Failed to send measurement command");
            break;
        }

        usleep(45000);

        unsigned char buffer[9];
        if (read(i2c_fd, buffer, 9) != 9) {
            perror("Failed to read data from sensor");
            break;
        }

        unsigned char pressure_crc = calculate_crc8(buffer, 3);
        unsigned char temperature_crc = calculate_crc8(buffer + 3, 3);
        unsigned char scale_factor_crc = calculate_crc8(buffer + 6, 3);

        if (pressure_crc != buffer[3] || temperature_crc != buffer[6] || scale_factor_crc != buffer[9]) {
            fprintf(stderr, "CRC error in sensor data\n");
            continue;
        }

        uint32_t pressure_raw = (buffer[0] << 16) | (buffer[1] << 8) | buffer[2];
        uint32_t temperature_raw = (buffer[4] << 16) | (buffer[5] << 8) | buffer[6];
        uint32_t scale_factor_raw = (buffer[7] << 16) | (buffer[8] << 8) | buffer[9];

        double pressure_pa = pressure_raw / (double)scale_factor_raw;
        double temperature_c = (temperature_raw / 200.0) - 45.0;

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure_pa, temperature_c);
        fflush(log_file);

        usleep(100000);
    }

    fclose(log_file);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

