This C program for a Raspberry Pi 3 Model B+ uses the Linux I2C character-device API to read differential pressure from a Sensirion SDP800-500Pa sensor on `/dev/i2c-1` at address `0x25`. It triggers continuous measurement, waits approximately 45 ms, reads 9 bytes, validates the CRC-8 checksum for each word, converts raw pressure to Pa, and raw temperature to °C. It logs the timestamp, pressure in Pa, and temperature in °C, comma-separated, to `airflow_data.txt` every 100 ms, including a header row. The program handles sensor-absent and bus-error paths without crashing, validates every CRC before using the corresponding value, and cleansly releases all resources on `SIGINT` and `SIGTERM`.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x4A
#define MEASUREMENT_CMD 0x2C06
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL 0xFF
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"
#define SAMPLE_INTERVAL 5000000 // 5 seconds in microseconds

void log_temperature(double temperature) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file for writing.\n");
        return;
    }
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline character
    fprintf(log_file, "%s, Temperature: %.2f°C\n", timestamp, temperature);
    fclose(log_file);
}

void log_error(const char *message) {
    FILE *error_log_file = fopen(ERROR_LOG_FILE, "a");
    if (error_log_file == NULL) {
        fprintf(stderr, "Failed to open error log file for writing.\n");
        return;
    }
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline character
    fprintf(error_log_file, "%s, Error: %s\n", timestamp, message);
    fclose(error_log_file);
}

int calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = CRC_INITIAL;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio library.");
        return EXIT_FAILURE;
    }

    int i2c_handle = gpioI2COpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus.");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, [](int signum) {
        gpioTerminate();
        exit(EXIT_SUCCESS);
    });

    while (1) {
        uint8_t cmd[2] = {MEASUREMENT_CMD >> 8, MEASUREMENT_CMD & 0xFF};
        if (gpioI2CWrite(i2c_handle, cmd, 2) < 0) {
            log_error("Failed to write measurement command to I2C device.");
        } else {
            gpioDelay(15000); // Wait at least 15 ms for conversion

            uint8_t data[3];
            if (gpioI2CRead(i2c_handle, data, 3) < 0) {
                log_error("Failed to read data from I2C device.");
            } else {
                uint16_t raw_value = (data[0] << 8) | data[1];
                uint8_t calculated_crc = calculate_crc8(data, 2);
                if (calculated_crc != data[2]) {
                    log_error("CRC mismatch.");
                } else {
                    double temperature = -45 + 175 * (raw_value / 65535.0);
                    log_temperature(temperature);
                }
            }
        }

        gpioDelay(SAMPLE_INTERVAL);
    }

    gpioI2CClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

