code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SHT40_ADDRESS 0x44
#define SHT40_MEAS_CMD 0xFD
#define SHT40_CRC_POLY 0x31
#define SHT40_CRC_INIT 0xFF
#define LOG_FILE "sht40_log.txt"
#define MEAS_INTERVAL 5

uint8_t crc8(const uint8_t *data, size_t length, uint8_t crc) {
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SHT40_CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    int i2c_fd, log_fd;
    uint8_t buf[6];
    time_t now;
    struct tm *tm_info;
    char log_entry[128];

    if ((i2c_fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SHT40_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if ((log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644)) < 0) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, [](int sig) {
        close(i2c_fd);
        close(log_fd);
        exit(EXIT_SUCCESS);
    });

    while (1) {
        if (write(i2c_fd, &SHT40_MEAS_CMD, 1) != 1) {
            perror("Failed to send measurement command");
        } else {
            usleep(8500); // Wait at least 8.5 ms

            if (read(i2c_fd, buf, 6) != 6) {
                perror("Failed to read measurement data");
            } else {
                uint16_t temp_raw = (buf[0] << 8) | buf[1];
                uint16_t hum_raw = (buf[3] << 8) | buf[4];

                if (buf[2] != crc8(buf, 2, SHT40_CRC_INIT) || buf[5] != crc8(buf + 3, 2, SHT40_CRC_INIT)) {
                    fprintf(stderr, "CRC error in measurement data\n");
                } else {
                    float temp = -45 + 175 * temp_raw / 65535.0;
                    float hum = 100 * hum_raw / 65535.0;

                    time(&now);
                    tm_info = localtime(&now);
                    strftime(log_entry, sizeof(log_entry), "%Y-%m-%d %H:%M:%S", tm_info);
                    snprintf(log_entry + strlen(log_entry), sizeof(log_entry) - strlen(log_entry), " Temp: %.2f°C, Hum: %.2f%%\n", temp, hum);
                    if (write(log_fd, log_entry, strlen(log_entry)) != strlen(log_entry)) {
                        perror("Failed to write to log file");
                    }
                }
            }
        }

        sleep(MEAS_INTERVAL);
    }

    close(i2c_fd);
    close(log_fd);
    return EXIT_SUCCESS;
}

