#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SENSOR_ADDRESS 0x25
#define MEASUREMENT_COMMAND 0x362F
#define RESPONSE_SIZE 6
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF
#define PRESSURE_SCALE 240
#define TEMPERATURE_SCALE 200
#define TEMPERATURE_OFFSET -45

void log_data(const char *filename, double pressure, double temperature) {
    FILE *file = fopen(filename, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    fprintf(file, "%ld,%.2f,%.2f\n", now, pressure, temperature);
    fclose(file);
}

uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    int fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return EXIT_FAILURE;
    }

    uint8_t command[2] = {MEASUREMENT_COMMAND >> 8, MEASUREMENT_COMMAND & 0xFF};
    if (write(fd, command, sizeof(command)) != sizeof(command)) {
        perror("Failed to send measurement command");
        close(fd);
        return EXIT_FAILURE;
    }

    usleep(1000); // Wait at least 1 ms

    uint8_t response[RESPONSE_SIZE];
    if (read(fd, response, sizeof(response)) != sizeof(response)) {
        perror("Failed to read sensor response");
        close(fd);
        return EXIT_FAILURE;
    }

    uint8_t pressure_crc = calculate_crc8(response, 3);
    uint8_t temperature_crc = calculate_crc8(response + 3, 3);

    if (pressure_crc != response[3] || temperature_crc != response[6]) {
        fprintf(stderr, "CRC error in sensor response\n");
        close(fd);
        return EXIT_FAILURE;
    }

    double pressure = (response[0] << 16 | response[1] << 8 | response[2]) * PRESSURE_SCALE;
    double temperature = ((response[3] << 16 | response[4] << 8 | response[5]) * TEMPERATURE_SCALE) / TEMPERATURE_SCALE + TEMPERATURE_OFFSET;

    log_data("airflow_data.txt", pressure, temperature);

    close(fd);
    return EXIT_SUCCESS;
}

