#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define FAN_PIN 18
#define BUFFER_SIZE 60
#define RETRY_COUNT 3
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0
#define HUMIDITY_THRESHOLD 40.0

typedef struct {
    time_t timestamp;
    float temperature;
    float humidity;
} Reading;

Reading buffer[BUFFER_SIZE];
int buffer_index = 0;

void log_reading(float temperature, float humidity) {
    time_t now = time(NULL);
    buffer[buffer_index].timestamp = now;
    buffer[buffer_index].temperature = temperature;
    buffer[buffer_index].humidity = humidity;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

void print_buffer() {
    for (int i = 0; i < BUFFER_SIZE; i++) {
        printf("%s: Temp %.2f°C, Humidity %.2f%%\n", ctime(&buffer[i].timestamp), buffer[i].temperature, buffer[i].humidity);
    }
}

void handle_sigint(int sig) {
    gpioWrite(FAN_PIN, PI_OFF);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(FAN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", FAN_PIN);
        gpioTerminate();
        return 1;
    }

    gpioSetPullUpDown(FAN_PIN, PI_PUD_OFF);

    signal(SIGINT, handle_sigint);

    int i2c_handle = gpioI2COpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return 1;
    }

    while (1) {
        for (int i = 0; i < RETRY_COUNT; i++) {
            int status = gpioI2CWriteByte(i2c_handle, 0xE3);
            if (status >= 0) {
                gpioDelay(10000); // 10 ms delay
                uint16_t temp_raw = gpioI2CRead(i2c_handle, 2);
                if (temp_raw >= 0) {
                    float temperature = 175.72 * temp_raw / 65536.0 - 46.85;
                    status = gpioI2CWriteByte(i2c_handle, 0xE5);
                    if (status >= 0) {
                        gpioDelay(10000); // 10 ms delay
                        uint16_t humidity_raw = gpioI2CRead(i2c_handle, 2);
                        if (humidity_raw >= 0) {
                            float humidity = 125.0 * humidity_raw / 65536.0 - 6.0;
                            log_reading(temperature, humidity);
                            if (temperature > TEMP_THRESHOLD_HIGH) {
                                gpioWrite(FAN_PIN, PI_ON);
                            } else if (temperature < TEMP_THRESHOLD_LOW) {
                                gpioWrite(FAN_PIN, PI_OFF);
                            }
                            print_buffer();
                            goto next_reading;
                        }
                    }
                }
            }
        }
        fprintf(stderr, "Failed to read from sensor after %d retries\n", RETRY_COUNT);
        gpioWrite(FAN_PIN, PI_OFF);
        sleep(2);
    next_reading:;
    }

    gpioI2CClose(i2c_handle);
    gpioTerminate();
    return 0;
}

