#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define SCD40_I2C_ADDRESS 0x62
#define SCD40_I2C_BUS 1
#define SCD40_START_MEASUREMENT 0x21B1
#define SCD40_STOP_MEASUREMENT 0x3F86
#define SCD40_DATA_READY 0xE4B8
#define SCD40_READ_MEASUREMENT 0xEC05
#define SCD40_CRC_POLYNOMIAL 0x31
#define SCD40_CRC_INIT 0xFF
#define SCD40_LOG_FILE "air_quality.log"

void log_data(double co2, double temperature, double humidity) {
    FILE *log = fopen(SCD40_LOG_FILE, "a");
    if (log == NULL) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    fprintf(log, "%s,%.2f,%.2f,%.2f\n", ctime(&now), co2, temperature, humidity);
    fflush(log);
    fclose(log);
}

int calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = SCD40_CRC_INIT;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SCD40_CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = gpioI2COpen(SCD40_I2C_BUS, SCD40_I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t start_measurement[2] = {0x21, 0xB1};
    if (gpioI2CWrite(i2c_handle, start_measurement, 2) != 2) {
        fprintf(stderr, "Failed to send start measurement command\n");
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, [](int sig) {
        uint8_t stop_measurement[2] = {0x3F, 0x86};
        gpioI2CWrite(i2c_handle, stop_measurement, 2);
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        exit(EXIT_SUCCESS);
    });

    while (1) {
        uint8_t data_ready[2] = {0xE4, 0xB8};
        uint8_t data[9];
        int result;

        result = gpioI2CWriteRead(i2c_handle, data_ready, 2, data, 2);
        if (result != 2) {
            fprintf(stderr, "Failed to read data ready flag\n");
            continue;
        }

        if (data[0] == 0x01 && data[1] == 0x00) {
            result = gpioI2CWriteRead(i2c_handle, data_ready, 2, data, 9);
            if (result != 9) {
                fprintf(stderr, "Failed to read measurement data\n");
                continue;
            }

            uint16_t co2_raw = (data[0] << 8) | data[1];
            uint16_t temperature_raw = (data[3] << 8) | data[4];
            uint16_t humidity_raw = (data[6] << 8) | data[7];

            uint8_t crc_co2 = calculate_crc8(data, 2);
            uint8_t crc_temperature = calculate_crc8(data + 2, 2);
            uint8_t crc_humidity = calculate_crc8(data + 4, 2);

            if (crc_co2 != data[2] || crc_temperature != data[5] || crc_humidity != data[8]) {
                fprintf(stderr, "CRC check failed\n");
                continue;
            }

            double co2 = co2_raw;
            double temperature = -45 + 175 * temperature_raw / 65535.0;
            double humidity = 100 * humidity_raw / 65535.0;

            log_data(co2, temperature, humidity);
        }

        sleep(5);
    }

    gpioI2CClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

