#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pigpio.h>
#include <signal.h>

#define GPIO_PIN 4
#define SAMPLE_INTERVAL 5000000  // 5 seconds in microseconds
#define TIMEOUT 50000  // 50 ms in microseconds
#define MIN_TEMP -40.0
#define MAX_TEMP 150.0
#define CONSEC_FAILURES 3

volatile int consecutive_failures = 0;
FILE *log_file = NULL;

void log_temperature(double temperature) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(log_file, "%s,%.2f\n", asctime(tm_info), temperature);
    fflush(log_file);
}

void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(log_file, "%s,%s\n", asctime(tm_info), message);
    fflush(log_file);
}

void handle_signal(int sig) {
    if (log_file) fclose(log_file);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    if ((log_file = fopen("temperature_log.txt", "a")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    gpioSetMode(GPIO_PIN, PI_INPUT);

    while (1) {
        uint32_t start_time = gpioTick();
        uint32_t high_time = 0;

        // Wait for the first edge
        if (gpioWaitEvent(GPIO_PIN, TIMEOUT) == 0) {
            log_error("Sensor absent or stuck line");
            consecutive_failures++;
            if (consecutive_failures >= CONSEC_FAILURES) {
                log_error("SENSOR MALFUNCTION");
            }
            continue;
        }

        // Measure high pulse width
        while (gpioRead(GPIO_PIN) == 1) {
            if (gpioWaitEvent(GPIO_PIN, TIMEOUT) == 0) {
                log_error("Sensor absent or stuck line");
                consecutive_failures++;
                if (consecutive_failures >= CONSEC_FAILURES) {
                    log_error("SENSOR MALFUNCTION");
                }
                continue;
            }
            high_time = gpioTick() - start_time;
        }

        // Wait for the next edge
        if (gpioWaitEvent(GPIO_PIN, TIMEOUT) == 0) {
            log_error("Sensor absent or stuck line");
            consecutive_failures++;
            if (consecutive_failures >= CONSEC_FAILURES) {
                log_error("SENSOR MALFUNCTION");
            }
            continue;
        }

        uint32_t total_time = gpioTick() - start_time;

        if (total_time == 0) {
            log_error("Division by zero");
            consecutive_failures++;
            if (consecutive_failures >= CONSEC_FAILURES) {
                log_error("SENSOR MALFUNCTION");
            }
            continue;
        }

        double temperature = 4215 - (2143.0 * high_time / total_time);

        if (temperature < MIN_TEMP || temperature > MAX_TEMP) {
            log_error("Invalid temperature reading");
            consecutive_failures++;
            if (consecutive_failures >= CONSEC_FAILURES) {
                log_error("SENSOR MALFUNCTION");
            }
            continue;
        }

        log_temperature(temperature);
        consecutive_failures = 0;
        gpioDelay(SAMPLE_INTERVAL);
    }

    fclose(log_file);
    gpioTerminate();
    return 0;
}

