            crc = crc << 1;
        }
        if (data & 0x8000) {
            crc ^= 0x01;
        }
        data <<= 1;
    }
    return crc;
}

int read_sht35_temperature_humidity(int i2c_handle, float *temperature, float *humidity) {
    uint8_t cmd[2] = {SHT35_MEAS_CMD >> 8, SHT35_MEAS_CMD & 0xFF};
    uint8_t data[6];
    int retries = SHT35_RETRY_COUNT;

    while (retries--) {
        if (gpioI2CWrite(i2c_handle, cmd, 2) < 0) {
            continue;
        }
        gpioDelay(15000);
        if (gpioI2CRead(i2c_handle, data, 6) < 0) {
            continue;
        }

        uint16_t temp_raw = (data[0] << 8) | data[1];
        uint16_t hum_raw = (data[3] << 8) | data[4];

        uint8_t temp_crc = calculate_crc(temp_raw);
        uint8_t hum_crc = calculate_crc(hum_raw);

        if (temp_crc == data[2] && hum_crc == data[5]) {
            *temperature = -45.0 + 175.0 * (temp_raw / 65535.0);
            *humidity = -6.0 + 125.0 * (hum_raw / 65535.0);
            return 0;
        }
    }

    *temperature = NAN;
    *humidity = NAN;
    return -1;
}

void log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *utc_time = gmtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc_time);

    FILE *log_file = fopen("environmental_data.txt", "a");
    if (log_file) {
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
        fclose(log_file);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = gpioI2COpen(1, SHT35_I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float temperature, humidity;
    while (running) {
        if (read_sht35_temperature_humidity(i2c_handle, &temperature, &humidity) == 0) {
            temperature += SINUSOIDAL_OFFSET_TEMP * sin(now() / SINUSOIDAL_PERIOD * 2 * M_PI);
            humidity += SINUSOIDAL_OFFSET_HUM * sin(now() / SINUSOIDAL_PERIOD * 2 * M_PI);
            log_data(temperature, humidity);
        }
        gpioDelay(LOG_INTERVAL * 1000000);
    }

    gpioI2CClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}
