#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x25
#define SDP810_CMD_CONT_MEAS 0x362F
#define SDP810_DATA_LEN 9
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL 0xFF

int i2c_fd;
FILE *csv_fd;

void calculate_crc8(uint8_t *data, size_t len, uint8_t *crc) {
    *crc = CRC8_INITIAL;
    for (size_t i = 0; i < len; i++) {
        *crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (*crc & 0x80) {
                *crc = (*crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                *crc = *crc << 1;
            }
        }
    }
}

int read_sensor_data(uint8_t *data) {
    if (write(i2c_fd, &SDP810_CMD_CONT_MEAS, 2) != 2) {
        perror("Failed to send measurement command");
        return -1;
    }
    usleep(45000); // Wait for conversion time
    if (read(i2c_fd, data, SDP810_DATA_LEN) != SDP810_DATA_LEN) {
        perror("Failed to read sensor data");
        return -1;
    }
    return 0;
}

void log_data() {
    uint8_t data[SDP810_DATA_LEN];
    if (read_sensor_data(data) != 0) {
        return;
    }

    uint8_t crc;
    calculate_crc8(data, 8, &crc);
    if (crc != data[8]) {
        fprintf(stderr, "CRC error\n");
        return;
    }

    float pressure = (data[0] << 16) | (data[1] << 8) | data[2];
    float temperature = (data[3] << 8) | data[4];
    float scale_factor = (data[5] << 8) | data[6];

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(csv_fd, "%s,%.2f,%.2f\n", timestamp, pressure * scale_factor, temperature);
}

void cleanup() {
    if (csv_fd) {
        fclose(csv_fd);
    }
    if (i2c_fd) {
        close(i2c_fd);
    }
}

void signal_handler(int sig) {
    cleanup();
    exit(0);
}

int main() {
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if ((csv_fd = fopen("airflow.csv", "w")) == NULL) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    fprintf(csv_fd, "Timestamp,Pressure (Pa),Temperature (°C)\n");

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        log_data();
        sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

