#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define SI7021_ADDRESS 0x40
#define SI7021_MEASURE_HUMIDITY 0xF5
#define SI7021_MEASURE_TEMP 0xF3
#define SI7021_RESET 0xFE
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL 0x00
#define TIMEOUT_US 100000
#define LOG_INTERVAL 5

void log_error(const char *message) {
    fprintf(stderr, "ERROR: %s\n", message);
}

void log_data(const char *filename, double temperature, double humidity) {
    FILE *file = fopen(filename, "a");
    if (!file) {
        log_error("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
    fprintf(file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(file);
}

uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = CRC8_INITIAL;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        log_error("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SI7021_ADDRESS) < 0) {
        log_error("Failed to set I2C address");
        close(fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, SIG_IGN);
    signal(SIGTERM, SIG_IGN);

    FILE *log_file = fopen("environment.log", "a");
    if (!log_file) {
        log_error("Failed to open log file");
        close(fd);
        return EXIT_FAILURE;
    }

    fprintf(log_file, "timestamp,temperature_C,humidity_percent\n");
    fclose(log_file);

    while (1) {
        uint8_t buffer[3];
        struct timespec start, end;
        clock_gettime(CLOCK_MONOTONIC, &start);

        if (write(fd, &SI7021_MEASURE_HUMIDITY, 1) != 1) {
            log_error("Failed to send humidity measurement command");
            close(fd);
            return EXIT_FAILURE;
        }

        while (1) {
            clock_gettime(CLOCK_MONOTONIC, &end);
            if (timespec_diff(&end, &start) > TIMEOUT_US) {
                log_error("Humidity measurement timed out");
                break;
            }
            if (read(fd, buffer, 3) == 3) {
                if (buffer[2] == calculate_crc8(buffer, 2)) {
                    double humidity = 125.0 * (buffer[0] * 256 + buffer[1]) / 65536.0 - 6.0;
                    if (write(fd, &SI7021_MEASURE_TEMP, 1) != 1) {
                        log_error("Failed to send temperature measurement command");
                        close(fd);
                        return EXIT_FAILURE;
                    }

                    while (1) {
                        clock_gettime(CLOCK_MONOTONIC, &end);
                        if (timespec_diff(&end, &start) > TIMEOUT_US) {
                            log_error("Temperature measurement timed out");
                            break;
                        }
                        if (read(fd, buffer, 3) == 3) {
                            if (buffer[2] == calculate_crc8(buffer, 2)) {
                                double temperature = 175.72 * (buffer[0] * 256 + buffer[1]) / 65536.0 - 46.85;
                                log_data("environment.log", temperature, humidity);
                                break;
                            }
                        }
                    }
                    break;
                }
            }
        }

        sleep(LOG_INTERVAL);
    }

    close(fd);
    return EXIT_SUCCESS;
}

int timespec_diff(struct timespec *end, struct timespec *start) {
    return (end->tv_sec - start->tv_sec) * 1000000 + (end->tv_nsec - start->tv_nsec) / 1000;
}

