#define CONV_TIME 45
#define LOG_FILE "pressure_log.txt"
#define SCALE_FACTOR 60.0

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

