    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!stop_flag) {
        uint8_t cmd[2] = {MEAS_CMD >> 8, MEAS_CMD & 0xFF};
        if (gpioI2CWrite(i2c_handle, cmd, 2) != 2) {
            fprintf(stderr, "I2C write error\n");
            break;
        }

        gpioDelay(CONV_TIME * 1000);

        uint8_t data[9];
        if (gpioI2CRead(i2c_handle, data, 9) != 9) {
