        uint16_t crc1 = (data[2] << 8) | data[3];
        uint16_t crc2 = (data[4] << 8) | data[5];
        uint16_t crc3 = (data[6] << 8) | data[7];

        uint8_t crc_data[6] = {data[0], data[1], data[2], data[3], data[4], data[5]};
        uint8_t calculated_crc = 0;
        for (int i = 0; i < 6; i++) {
            calculated_crc ^= crc_data[i];
            calculated_crc = (calculated_crc << 1) ^ (calculated_crc & 0x80 ? 0x31 : 0);
        }

