#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x28
#define FAN_PIN 18
#define PWM_FREQ 25000
#define SAMPLE_INTERVAL 100
#define LOG_FILE "flow_log.txt"

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", FAN_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(FAN_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO%d\n", FAN_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        uint16_t raw_reading = i2cReadWordData(i2c_handle, 0x00);
        if (raw_reading < 0) {
            fprintf(stderr, "I2C read error\n");
            continue;
        }

        uint16_t flow_reading = (raw_reading & 0x3FFF) >> 2;
        float flow_rate = (float)flow_reading * 10.0 / 14745.0;

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s,%f\n", timestamp, flow_rate);
        fflush(log_file);

        int pwm_duty_cycle = (int)(flow_rate / 10.0 * 100.0);
        gpioSetPWMrange(FAN_PIN, 100);
        gpioSetPWMduty(FAN_PIN, pwm_duty_cycle);

        gpioDelay(SAMPLE_INTERVAL * 1000);
    }

    gpioSetPWMduty(FAN_PIN, 0);
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return EXIT_SUCCESS;
}

