#define PRESS_OUT_L 0x29
#define PRESS_OUT_H 0x2A
#define TEMP_OUT_L 0x2B
#define TEMP_OUT_H 0x2C

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    int i2c_handle = gpioI2COpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen("environmental_data.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (!stop_flag) {
        uint8_t who_am_i[1];
        if (gpioI2CRead(i2c_handle, WHO_AM_I, who_am_i, 1) != 1) {
            fprintf(stderr, "Failed to read WHO_AM_I register\n");
            continue;
        }

        if (who_am_i[0] != 0xB1) {
            fprintf(stderr, "Incorrect WHO_AM_I value: 0x%02X\n", who_am_i[0]);
            continue;
        }

        uint8_t ctrl_reg1[1] = {0xB0};
        if (gpioI2CWrite(i2c_handle, CTRL_REG1, ctrl_reg1, 1) != 1) {
            fprintf(stderr, "Failed to write CTRL_REG1 register\n");
            continue;
        }

        uint8_t press_data[3];
        if (gpioI2CRead(i2c_handle, PRESS_OUT_XL, press_data, 3) != 3) {
            fprintf(stderr, "Failed to read pressure data\n");
            continue;
        }

        int32_t pressure = (int32_t)press_data[2] << 16 | (int32_t)press_data[1] << 8 | press_data[0];
        float pressure_hpa = pressure / 4096.0;

        uint8_t temp_data[2];
        if (gpioI2CRead(i2c_handle, TEMP_OUT_L, temp_data, 2) != 2) {
            fprintf(stderr, "Failed to read temperature data\n");
            continue;
        }

        int16_t temperature = (int16_t)temp_data[1] << 8 | temp_data[0];
        float temperature_c = 42.5 + temperature / 480.0;

        time_t now = time(NULL);
        struct tm tm;
        localtime_r(&now, &tm);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

        fprintf(log_file, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n", timestamp, pressure_hpa, temperature_c);
        fflush(log_file);

        gpioDelay(1000000); // 1 second
    }

    fclose(log_file);
    gpioI2CClose(i2c_handle);
    gpioTerminate();

    return 0;
}
```

This code initializes the pigpio library, opens the I2C bus, and opens the log file. It sets up a signal handler for SIGINT to allow graceful termination. The main loop reads the WHO_AM_I register to ensure the sensor is present, configures the sensor, reads the pressure and temperature, and logs the data. If any I2C operation fails, it logs an error and continues. On exit, it closes the log file, the I2C handle, and terminates the pigpio library.

