#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define TEMP_REG 0x00
#define LED_PIN 17
#define BUFFER_SIZE 10

volatile int running = 1;
volatile float buffer[BUFFER_SIZE];
volatile int buffer_index = 0;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_PIN);
        gpioTerminate();
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        uint16_t raw_temp = i2cReadWordData(i2c_handle, TEMP_REG);
        if (raw_temp == PI_I2C_READ_FAILED) {
            fprintf(stderr, "I2C read failed\n");
            continue;
        }

        // Swap bytes and right-shift by 7
        uint16_t swapped_temp = ((raw_temp & 0xFF) << 8) | ((raw_temp & 0xFF00) >> 8);
        float temperature = (swapped_temp >> 7) / 2.0;

        // Update circular buffer
        buffer[buffer_index] = temperature;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        // Calculate running average
        float sum = 0;
        for (int i = 0; i < BUFFER_SIZE; i++) {
            sum += buffer[i];
        }
        float average = sum / BUFFER_SIZE;

        // Control LED
        if (average > 28.0) {
            gpioWrite(LED_PIN, PI_HIGH);
        } else {
            gpioWrite(LED_PIN, PI_LOW);
        }

        // Sleep for 1 second
        gpioDelay(1000000);
    }

    // Cleanup
    gpioWrite(LED_PIN, PI_LOW);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

