#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SCD30_I2C_ADDRESS 0x61
#define SCD30_I2C_BUS 1
#define SCD30_MEASUREMENT_INTERVAL 2000000 // 2 seconds in microseconds
#define SCD30_DATA_READY_FLAG 0x0202
#define SCD30_MEASUREMENT_COMMAND 0x0300
#define SCD30_CRC_POLYNOMIAL 0x31
#define SCD30_CRC_INITIAL 0xFF
#define SENSIRION_CO2_MIN 800
#define SENSIRION_CO2_LOW 1199
#define SENSIRION_CO2_HIGH 1200

volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

int calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = SCD30_CRC_INITIAL;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SCD30_CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    int i2c_handle = i2cOpen(SCD30_I2C_BUS, SCD30_I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", SCD30_I2C_BUS);
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen("air_quality.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_sigint;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint8_t measurement_command[2] = {0x00, 0x00};
    if (i2cWriteDevice(i2c_handle, measurement_command, 2) < 0) {
        fprintf(stderr, "Failed to send measurement command\n");
        goto cleanup;
    }

    while (running) {
        uint8_t data_ready_flag[2];
        if (i2cReadDevice(i2c_handle, data_ready_flag, 2) < 0) {
            fprintf(stderr, "Failed to read data ready flag\n");
            goto cleanup;
        }

        if (data_ready_flag[0] == 0x00 && data_ready_flag[1] == 0x01) {
            uint8_t measurement[18];
            if (i2cReadDevice(i2c_handle, measurement, 18) < 0) {
                fprintf(stderr, "Failed to read measurement data\n");
                goto cleanup;
            }

            uint8_t co2_crc = calculate_crc8(measurement, 4);
            uint8_t temp_crc = calculate_crc8(measurement + 4, 4);
            uint8_t humidity_crc = calculate_crc8(measurement + 8, 4);

            if (co2_crc != measurement[4] || temp_crc != measurement[8] || humidity_crc != measurement[12]) {
                fprintf(stderr, "CRC mismatch in measurement data\n");
                goto cleanup;
            }

            uint16_t co2 = (measurement[3] << 8) | measurement[2];
            int16_t temp_raw = (measurement[7] << 8) | measurement[6];
            float temp = temp_raw * 0.00152587890625;
            uint16_t humidity_raw = (measurement[11] << 8) | measurement[10];
            float humidity = humidity_raw * 0.00152587890625;

            time_t now = time(NULL);
            struct tm *utc_time = gmtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc_time);

            fprintf(log_file, "%s,%d,%.2f,%.2f\n", timestamp, co2, temp, humidity);
            fflush(log_file);

            if (co2 < SENSIRION_CO2_MIN) {
                printf("Ventilation: OFF\n");
            } else if (co2 <= SENSIRION_CO2_LOW) {
                printf("Ventilation: LOW\n");
            } else {
                printf("Ventilation: HIGH\n");
            }
        }

        usleep(SCD30_MEASUREMENT_INTERVAL);
    }

cleanup:
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

