This code initializes the pigpio library, opens the I2C bus, and starts continuous measurement with the SCD30 CO2 sensor. It polls the data-ready flag, reads the measurement data, verifies the CRC, and logs the CO2, temperature, and humidity with timestamps. It also controls a simulated ventilation system based on the CO2 level. The program handles errors gracefully and can be stopped with SIGINT or SIGTERM.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x21
#define MEASUREMENT_CMD 0x362F
#define CRC8_POLYNOMIAL 0x31
#define SAMPLE_INTERVAL 1000

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = 0;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main(int argc, char *argv[]) {
    if (argc > 2) {
        fprintf(stderr, "Usage: %s [sample_interval]\n", argv[0]);
        return 1;
    }

    int interval = SAMPLE_INTERVAL;
    if (argc == 2) {
        interval = atoi(argv[1]);
        if (interval <= 0) {
            fprintf(stderr, "Invalid sample interval\n");
            return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    int i2c_handle = gpioI2COpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return 1;
    }

    gpioSetSignalFunc(SIGINT, signal_handler);
    gpioSetSignalFunc(SIGTERM, signal_handler);

    uint8_t cmd[2] = {MEASUREMENT_CMD >> 8, MEASUREMENT_CMD & 0xFF};
    if (gpioI2CWrite(i2c_handle, cmd, 2) != 2) {
        fprintf(stderr, "Failed to send measurement command\n");
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (running) {
        uint8_t buffer[9];
        int bytes_read = gpioI2CRead(i2c_handle, buffer, 9);
        if (bytes_read != 9) {
            fprintf(stderr, "Failed to read from sensor\n");
            gpioI2CClose(i2c_handle);
            gpioTerminate();
            return 1;
        }

        uint16_t raw_pressure = (buffer[0] << 8) | buffer[1];
        uint8_t pressure_crc = buffer[2];
        uint16_t raw_temperature = (buffer[3] << 8) | buffer[4];
        uint8_t temperature_crc = buffer[5];
        uint16_t scale_factor = (buffer[6] << 8) | buffer[7];
        uint8_t scale_factor_crc = buffer[8];

        uint8_t calculated_pressure_crc = calculate_crc8(buffer, 3);
        uint8_t calculated_temperature_crc = calculate_crc8(buffer + 3, 3);
        uint8_t calculated_scale_factor_crc = calculate_crc8(buffer + 6, 3);

        if (pressure_crc != calculated_pressure_crc ||
            temperature_crc != calculated_temperature_crc ||
            scale_factor_crc != calculated_scale_factor_crc) {
            fprintf(stderr, "CRC error in sensor data\n");
            continue;
        }

        double pressure_pa = (double)raw_pressure / scale_factor;
        printf("Timestamp: %ld, Pressure: %.2f Pa, Temperature: %.2f C\n", time(NULL), pressure_pa, raw_temperature / 100.0);
        usleep(interval * 1000);
    }

    gpioI2CClose(i2c_handle);
    gpioTerminate();
    return 0;
}

