code:
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x25
#define CONTINUOUS_MEAS_CMD 0x3615
#define CRC_POLY 0x31
#define CRC_INIT 0xFF
#define DATA_SIZE 9
#define DELAY_MS 45
#define LOG_INTERVAL 1000

volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

int calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = gpioI2COpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    uint8_t cmd[2] = {CONTINUOUS_MEAS_CMD >> 8, CONTINUOUS_MEAS_CMD & 0xFF};
    if (gpioI2CWrite(i2c_handle, cmd, 2) < 0) {
        fprintf(stderr, "Failed to send continuous measurement command\n");
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        uint8_t data[DATA_SIZE];
        int bytes_read = gpioI2CRead(i2c_handle, data, DATA_SIZE);
        if (bytes_read != DATA_SIZE) {
            fprintf(stderr, "Failed to read data from sensor\n");
            continue;
        }

        uint8_t crc8 = calculate_crc8(data, 8);
        if (crc8 != data[8]) {
            fprintf(stderr, "CRC mismatch\n");
            continue;
        }

        int32_t raw_pressure = (data[0] << 16) | (data[1] << 8) | data[2];
        int16_t raw_temperature = (data[3] << 8) | data[4];
        int16_t scale_factor_pressure = (data[5] << 8) | data[6];
        int16_t scale_factor_temperature = (data[7] << 8) | data[8];

        double pressure = (double)raw_pressure / scale_factor_pressure;
        double temperature = (double)raw_temperature / 200.0;

        printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);

        gpioDelay(DELAY_MS * 1000);
    }

    gpioI2CClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

