code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE "/dev/i2c-1"
#define HDC1000_ADDRESS 0x40
#define CONFIG_REG 0x02
#define TEMP_REG 0x00
#define HDC1000_CONFIG_ENABLE_CONTINUOUS 0x1000
#define HDC1000_CONFIG_TEMP_HUMIDITY_14BIT 0x0000
#define HDC1000_CONFIG 0x1000
#define HDC1000_READ_DELAY 20000 // 20 ms in microseconds

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    int fd;
    uint8_t config[2] = {CONFIG_REG, HDC1000_CONFIG};
    uint8_t temp_humidity[4];
    uint16_t temperature_raw, humidity_raw;
    double temperature, humidity;

    // Open I2C device
    if ((fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(fd, I2C_SLAVE, HDC1000_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return EXIT_FAILURE;
    }

    // Write configuration to sensor
    if (write(fd, config, sizeof(config)) != sizeof(config)) {
        perror("Failed to write configuration to sensor");
        close(fd);
        return EXIT_FAILURE;
    }

    // Set up signal handler
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set signal handler");
        close(fd);
        return EXIT_FAILURE;
    }

    while (running) {
        // Write temperature register pointer to sensor
        if (write(fd, &TEMP_REG, sizeof(TEMP_REG)) != sizeof(TEMP_REG)) {
            perror("Failed to write temperature register pointer to sensor");
            continue;
        }

        // Wait for conversion to complete
        usleep(HDC1000_READ_DELAY);

        // Read 4 bytes (2 temperature + 2 humidity)
        if (read(fd, temp_humidity, sizeof(temp_humidity)) != sizeof(temp_humidity)) {
            perror("Failed to read temperature and humidity from sensor");
            continue;
        }

        // Convert raw values to temperature and humidity
        temperature_raw = (temp_humidity[0] << 8) | temp_humidity[1];
        humidity_raw = (temp_humidity[2] << 8) | temp_humidity[3];
        temperature = (temperature_raw / 65536.0) * 165.0 - 40.0;
        humidity = (humidity_raw / 65536.0) * 100.0;

        // Print readings to console
        printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Close I2C device
    close(fd);

    return EXIT_SUCCESS;
}

