#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x60
#define I2C_REG_TEMP 0x00
#define SAMPLE_INTERVAL 500000 // 500 ms in microseconds

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = gpioI2COpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!stop_flag) {
        uint8_t data[2];
        int result = gpioI2CReadDevice(i2c_handle, I2C_REG_TEMP, data, 2);
        if (result < 0) {
            fprintf(stderr, "I2C read error: %d\n", result);
        } else {
            uint16_t raw_temp = (data[0] << 8) | data[1];
            double temperature = (raw_temp * 0.02) - 45.0;
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            printf("%04d-%02d-%02d %02d:%02d:%02d - Temperature: %.2f°C\n",
                   tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
                   tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec, temperature);
        }

        gpioDelay(SAMPLE_INTERVAL);
    }

    gpioI2CClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

