#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x60
#define MEASURE_REG 0x00
#define PRESSURE_MSB_REG 0xAA
#define PRESSURE_LSB_REG 0xAB
#define SCALE_FACTOR 0.1

int i2c_fd = -1;
volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    struct timespec ts;
    uint8_t measure_cmd = 0;
    uint8_t pressure_data[2];
    int16_t raw_pressure;
    double pressure_kpa;

    // Open I2C bus
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        // Trigger measurement
        if (write(i2c_fd, &measure_cmd, 1) != 1) {
            perror("Failed to trigger measurement");
        } else {
            // Wait for measurement to complete (approx 100ms)
            nanosleep(&ts, NULL);

            // Read pressure data
            if (read(i2c_fd, pressure_data, 2) != 2) {
                perror("Failed to read pressure data");
            } else {
                // Convert raw data to 16-bit integer
                raw_pressure = (pressure_data[0] << 8) | pressure_data[1];

                // Convert to kPa
                pressure_kpa = raw_pressure * SCALE_FACTOR;

                // Log reading with timestamp
                clock_gettime(CLOCK_REALTIME, &ts);
                printf("%ld.%09ld: Pressure: %.2f kPa\n", ts.tv_sec, ts.tv_nsec, pressure_kpa);
            }
        }

        // Sleep for 1 second
        nanosleep(&ts, NULL);
    }

    // Close I2C bus
    close(i2c_fd);

    return EXIT_SUCCESS;
}

