#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x25
#define CMD_CONT_MEAS 0x362F
#define CRC8_POLY 0x31
#define CRC8_INIT 0xFF
#define LOG_FILE "pressure_log.txt"

void log_data(time_t timestamp, float pressure, float temperature) {
    FILE *log = fopen(LOG_FILE, "a");
    if (log == NULL) {
        perror("Failed to open log file");
        return;
    }
    fprintf(log, "%ld,%f,%f\n", timestamp, pressure, temperature);
    fclose(log);
}

uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

void handle_sigint(int sig) {
    printf("Received signal %d, exiting...\n", sig);
    exit(0);
}

int main() {
    int fd;
    uint8_t buf[10];
    uint16_t pressure_raw, temperature_raw;
    uint8_t crc8_pressure, crc8_temperature;
    float pressure, temperature;
    time_t timestamp;

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(fd);
        return EXIT_FAILURE;
    }

    while (1) {
        buf[0] = CMD_CONT_MEAS;
        if (write(fd, buf, 1) != 1) {
            perror("Failed to send measurement command");
            close(fd);
            return EXIT_FAILURE;
        }

        usleep(45000);

        if (read(fd, buf, 9) != 9) {
            perror("Failed to read data from sensor");
            close(fd);
            return EXIT_FAILURE;
        }

        pressure_raw = (buf[1] << 8) | buf[2];
        temperature_raw = (buf[4] << 8) | buf[5];
        crc8_pressure = buf[3];
        crc8_temperature = buf[6];

        if (calculate_crc8(buf, 3) != crc8_pressure) {
            fprintf(stderr, "CRC error in pressure data\n");
            continue;
        }

        if (calculate_crc8(buf + 3, 3) != crc8_temperature) {
            fprintf(stderr, "CRC error in temperature data\n");
            continue;
        }

        pressure = pressure_raw / 60.0;
        temperature = temperature_raw / 200.0;

        timestamp = time(NULL);
        log_data(timestamp, pressure, temperature);

        sleep(1);
    }

    close(fd);
    return EXIT_SUCCESS;
}

