#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x25
#define MEASURE_CMD 0x362F
#define CRC_POLY 0x31
#define CRC_INIT 0xFF
#define DATA_LEN 3
#define LOG_FILE "airflow_log.csv"

void log_pressure(double pressure) {
    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        perror("Failed to open log file");
        return;
    }
    if (access(LOG_FILE, F_OK) == -1) {
        fprintf(log, "Timestamp,Pressure (Pa)\n");
    }
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
    fprintf(log, "%s,%.2f\n", timestamp, pressure);
    fclose(log);
}

uint8_t calculate_crc(uint8_t *data, size_t len) {
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = gpioI2COpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, gpioTerminate);
    signal(SIGTERM, gpioTerminate);

    uint8_t cmd[2] = {MEASURE_CMD >> 8, MEASURE_CMD & 0xFF};
    if (gpioI2CWrite(i2c_handle, cmd, 2) < 0) {
        fprintf(stderr, "Failed to send measurement command\n");
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (1) {
        uint8_t data[DATA_LEN];
        if (gpioI2CRead(i2c_handle, data, DATA_LEN) != DATA_LEN) {
            fprintf(stderr, "Failed to read data from sensor\n");
            gpioI2CClose(i2c_handle);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        uint8_t crc = calculate_crc(data, 2);
        if (crc != data[2]) {
            fprintf(stderr, "CRC check failed\n");
            continue;
        }

        int16_t raw_pressure = (data[0] << 8) | data[1];
        double pressure = raw_pressure / 60.0;

        log_pressure(pressure);

        sleep(1);
    }

    gpioI2CClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

