#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x27
#define SENSOR_DATA_SIZE 4
#define LOG_FILE "environmental_data.log"
#define MAX_LOG_SIZE (1 * 1024 * 1024)

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = gpioI2COpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    while (!stop_flag) {
        // Trigger measurement
        if (gpioI2CWriteByte(i2c_handle, 0x00) < 0) {
            fprintf(stderr, "Failed to trigger measurement\n");
            break;
        }

        // Wait for measurement to complete
        gpioDelay(40 * 1000);

        // Read sensor data
        uint8_t data[SENSOR_DATA_SIZE];
        int bytes_read = gpioI2CRead(i2c_handle, data, SENSOR_DATA_SIZE);
        if (bytes_read != SENSOR_DATA_SIZE) {
            fprintf(stderr, "Failed to read sensor data\n");
            break;
        }

        // Validate sensor status bits
        if ((data[0] & 0x80) != 0x80) {
            fprintf(stderr, "Sensor status error\n");
            continue;
        }

        // Convert raw values to temperature and humidity
        int raw_T = (data[0] & 0x3F) << 8 | data[1];
        int raw_H = data[2] << 8 | data[3];
        float temperature = raw_T * 165.0 / 16383.0 - 40.0;
        float humidity = raw_H * 100.0 / 16383.0;

        // Log the reading with an ISO-8601 timestamp
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
        fprintf(log_file, "%s, Temperature: %.2f°C, Humidity: %.2f%%\n", timestamp, temperature, humidity);
        fflush(log_file);

        // Check log file size and truncate if necessary
        if (ftell(log_file) > MAX_LOG_SIZE) {
            fclose(log_file);
            if (rename(LOG_FILE, "environmental_data.old") != 0) {
                perror("Failed to rename log file");
            }
            log_file = fopen(LOG_FILE, "a");
            if (!log_file) {
                fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
                gpioI2CClose(i2c_handle);
                gpioTerminate();
                return EXIT_FAILURE;
            }
        }

        // Sample every 5 seconds
        gpioDelay(5 * 1000 * 1000);
    }

    fclose(log_file);
    gpioI2CClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

