#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <signal.h>

#define GPIO_PIN 4
#define TICK_TIME 3
#define SYNC_PULSE 56
#define NIBBLE_COUNT 8
#define CHECKSUM_INDEX 7
#define MIN_PULSE_WIDTH 36
#define MAX_PULSE_WIDTH 813
#define SCALE 0.01
#define OFFSET 0.0

volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
}

int read_nibble(int gpio, int tick_time) {
    int start_tick = gpioTick();
    while (gpioRead(gpio) == 0) {
        if (gpioTick() - start_tick > MAX_PULSE_WIDTH / tick_time) {
            fprintf(stderr, "Bus error: Pulse width too long\n");
            return -1;
        }
    }
    int end_tick = gpioTick();
    int pulse_width = end_tick - start_tick;
    if (pulse_width < MIN_PULSE_WIDTH / tick_time) {
        fprintf(stderr, "Bus error: Pulse width too short\n");
        return -1;
    }
    return pulse_width;
}

int read_sent_data(int gpio, int tick_time) {
    int sync_pulses = 0;
    while (sync_pulses < SYNC_PULSE) {
        if (read_nibble(gpio, tick_time) == -1) {
            return -1;
        }
        sync_pulses++;
    }
    int data[NIBBLE_COUNT];
    for (int i = 0; i < NIBBLE_COUNT; i++) {
        data[i] = read_nibble(gpio, tick_time);
        if (data[i] == -1) {
            return -1;
        }
    }
    int checksum = 0;
    for (int i = 0; i < CHECKSUM_INDEX; i++) {
        checksum += data[i];
    }
    if (checksum % 16 != data[CHECKSUM_INDEX]) {
        fprintf(stderr, "Bus error: Invalid checksum\n");
        return -1;
    }
    int raw_value = (data[1] << 8) | data[2];
    return raw_value;
}

void log_pressure(double pressure) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(stderr, "%s, Pressure: %.2f Pa\n", timestamp, pressure);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    FILE *log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    while (running) {
        int raw_value = read_sent_data(GPIO_PIN, TICK_TIME);
        if (raw_value != -1) {
            double pressure = raw_value * SCALE + OFFSET;
            log_pressure(pressure);
        }
        sleep(1);
    }

    fclose(log_file);
    gpioTerminate();
    return 0;
}

