#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define DEVICE_ID_REG 0x0F
#define TEMP_REG 0x00
#define FILENAME "greenhouse_temps.dat"

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    int i2c_handle;
    FILE *file;
    uint16_t device_id;
    uint16_t temp_raw;
    float temp_c;
    char buffer[4];

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Verify device ID
    device_id = i2cReadWordData(i2c_handle, DEVICE_ID_REG);
    if (device_id != 0x0117) {
        fprintf(stderr, "Invalid device ID: 0x%04X\n", device_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Open file for appending
    file = fopen(FILENAME, "ab");
    if (!file) {
        fprintf(stderr, "Failed to open file %s\n", FILENAME);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        // Read temperature register
        temp_raw = i2cReadWordData(i2c_handle, TEMP_REG);
        if (temp_raw == 0xFFFF) {
            fprintf(stderr, "I2C read error\n");
            continue;
        }

        // Convert to Celsius
        temp_c = (temp_raw * 0.0078125);

        // Write temperature as 4-byte little-endian float to file
        *(float *)buffer = temp_c;
        if (fwrite(buffer, sizeof(buffer), 1, file) != 1) {
            fprintf(stderr, "Failed to write to file\n");
            break;
        }

        // Flush file buffer
        fflush(file);

        // Sleep for 60 seconds
        sleep(60);
    }

    // Clean up
    fclose(file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

