        *(float *)buffer = temp_c;
        if (fwrite(buffer, sizeof(buffer), 1, file) != 1) {
            fprintf(stderr, "Failed to write to file\n");
            break;
        }

        // Flush file buffer
        fflush(file);

        // Sleep for 60 seconds
        sleep(60);
    }

    // Clean up
    fclose(file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}
