#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SHT40_I2C_ADDRESS 0x44
#define SHT40_MEAS_HIGH_PRECISION 0xFD
#define SHT40_CRC_POLYNOMIAL 0x31
#define SHT40_CRC_INITIAL 0xFF
#define SHT40_LOG_FILE "environmental_data.txt"

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

uint8_t calculate_crc8(const uint8_t *data, size_t length, uint8_t initial) {
    uint8_t crc = initial;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SHT40_CRC_POLYNOMIAL;
            } else {
                crc = crc << 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = gpioI2COpen(1, SHT40_I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(SHT40_LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    while (!stop_flag) {
        gpioI2CWriteByte(i2c_handle, SHT40_MEAS_HIGH_PRECISION);
        gpioDelay(8500); // Wait at least 8.5 ms

        uint8_t buffer[6];
        int bytes_read = gpioI2CRead(i2c_handle, buffer, sizeof(buffer));
        if (bytes_read != sizeof(buffer)) {
            fprintf(stderr, "Failed to read from I2C sensor\n");
            continue;
        }

        uint16_t raw_temp = (buffer[0] << 8) | buffer[1];
        uint16_t raw_hum = (buffer[3] << 8) | buffer[4];

        uint8_t crc_temp = calculate_crc8(buffer, 2, SHT40_CRC_INITIAL);
        uint8_t crc_hum = calculate_crc8(buffer + 3, 2, SHT40_CRC_INITIAL);

        if (crc_temp != buffer[2] || crc_hum != buffer[5]) {
            fprintf(stderr, "CRC check failed\n");
            continue;
        }

        double temperature = -45 + 175 * (raw_temp / 65535.0);
        double humidity = -6 + 125 * (raw_hum / 65535.0);

        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        fprintf(log_file, "%s, Temperature: %.2f°C, Humidity: %.2f%%RH\n", timestamp, temperature, humidity);
        fflush(log_file);

        gpioDelay(5000000); // Wait 5 seconds
    }

    fclose(log_file);
    gpioI2CClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

