#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define TEMP_REG 0x00
#define BUFFER_SIZE 100
#define FILENAME "temperature_log.dat"

typedef struct {
    float temperatures[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

CircularBuffer buffer;

void init_buffer() {
    buffer.head = 0;
    buffer.count = 0;
}

void add_to_buffer(float temp) {
    buffer.temperatures[buffer.head] = temp;
    buffer.head = (buffer.head + 1) % BUFFER_SIZE;
    if (buffer.count < BUFFER_SIZE) {
        buffer.count++;
    }
}

void save_buffer_to_file() {
    FILE *file = fopen(FILENAME, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }
    fwrite(buffer.temperatures, sizeof(float), buffer.count, file);
    fclose(file);
}

void handle_sigint(int sig) {
    save_buffer_to_file();
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    int i2c_handle = gpioI2COpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        gpioTerminate();
        return 1;
    }

    init_buffer();

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    while (1) {
        uint8_t data[2];
        int result = gpioI2CReadDevice(i2c_handle, TEMP_REG, data, 2);
        if (result == 2) {
            float temp = (data[0] << 8) | data[1];
            temp *= 0.0078125;
            add_to_buffer(temp);
            save_buffer_to_file();
        } else {
            fprintf(stderr, "Failed to read temperature\n");
        }
        sleep(5);
    }

    gpioI2CClose(i2c_handle);
    gpioTerminate();
    return 0;
}

