#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x49
#define I2C_READ_LEN 4
#define LOG_FILE "flow_log.txt"

volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    int i2c_handle;
    FILE *log_file;
    uint8_t buffer[I2C_READ_LEN];
    double raw_flow, raw_temp, slpm, celsius;
    struct timespec ts;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        if (i2cReadDevice(i2c_handle, buffer, I2C_READ_LEN) != I2C_READ_LEN) {
            fprintf(stderr, "I2C read failed\n");
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to re-open I2C handle\n");
                fclose(log_file);
                gpioTerminate();
                return EXIT_FAILURE;
            }
            continue;
        }

        raw_flow = (buffer[0] << 8) | buffer[1];
        raw_temp = (buffer[2] << 8) | buffer[3];

        slpm = ((raw_flow / 16384.0) - 0.1) / 0.8 * 25.0;
        celsius = ((raw_temp / 4096.0) - 0.1) / 0.8 * 80.0 - 40.0;

        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld.%09ld, %.2f SLPM, %.2f °C\n", ts.tv_sec, ts.tv_nsec, slpm, celsius);
        fflush(log_file);

        sleep(1);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

