#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define SAMPLE_INTERVAL 2000000
#define RESPONSE_TIMEOUT 10000
#define BIT_TIMEOUT 1000
#define CHECKSUM_TIMEOUT 1000

volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
}

int read_dht11() {
    int humidity = 0, temperature = 0, checksum = 0;
    int bits[40] = {0};
    int i, j, bit_count = 0;
    uint32_t start_time, current_time, bit_start_time, bit_duration;

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioWrite(GPIO_PIN, PI_LOW);
    gpioDelay(18000);
    gpioWrite(GPIO_PIN, PI_HIGH);
    gpioSetMode(GPIO_PIN, PI_INPUT);

    start_time = gpioTick();
    while (gpioRead(GPIO_PIN) == PI_HIGH) {
        if (gpioTick() - start_time > RESPONSE_TIMEOUT) {
            fprintf(stderr, "Timeout waiting for sensor response\n");
            return -1;
        }
    }

    for (i = 0; i < 40; i++) {
        bit_start_time = gpioTick();
        while (gpioRead(GPIO_PIN) == PI_LOW) {
            if (gpioTick() - bit_start_time > BIT_TIMEOUT) {
                fprintf(stderr, "Timeout waiting for bit %d start\n", i);
                return -1;
            }
        }
        bit_start_time = gpioTick();
        while (gpioRead(GPIO_PIN) == PI_HIGH) {
            if (gpioTick() - bit_start_time > BIT_TIMEOUT) {
                fprintf(stderr, "Timeout waiting for bit %d end\n", i);
                return -1;
            }
        }
        bit_duration = gpioTick() - bit_start_time;
        bits[i] = (bit_duration > 50000) ? 1 : 0;
        bit_count++;
    }

    if (bit_count != 40) {
        fprintf(stderr, "Incorrect number of bits received\n");
        return -1;
    }

    for (i = 0; i < 8; i++) {
        humidity = (humidity << 1) | bits[i];
    }
    for (i = 8; i < 16; i++) {
        temperature = (temperature << 1) | bits[i];
    }
    for (i = 16; i < 24; i++) {
        checksum = (checksum << 1) | bits[i];
    }

    if ((humidity + temperature) % 256 != bits[24]) {
        fprintf(stderr, "Checksum error\n");
        return -1;
    }

    return humidity * 10 + temperature;
}

int main() {
    FILE *log_file;
    time_t now;
    struct tm *tm_info;
    char timestamp[20];

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_file = fopen("dht11_readings.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    while (running) {
        int reading = read_dht11();
        if (reading >= 0) {
            time(&now);
            tm_info = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
            fprintf(log_file, "%s, Temperature: %d.%d°C, Humidity: %d.%d%%\n", timestamp, reading / 10, reading % 10, reading / 10, reading % 10);
        }
        gpioDelay(SAMPLE_INTERVAL);
    }

    fclose(log_file);
    gpioTerminate();
    return 0;
}

