This C program uses the pigpio library to bit-bang the DHT11 temperature/humidity sensor protocol on a Raspberry Pi Zero W. It logs temperature and humidity readings with ISO-8601 timestamps to `dht11_readings.txt`. The program handles timeouts, checksum errors, and sensor-absent conditions, logging all errors with timestamps and status codes. It releases GPIO resources and closes the log file on SIGINT/SIGTERM signals.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SHT31_I2C_ADDRESS 0x44
#define SHT31_MEASUREMENT_CMD 0x2C06
#define SHT31_CRC_POLYNOMIAL 0x31
#define SHT31_CRC_INITIAL 0xFF
#define SHT31_DATA_LENGTH 6
#define SHT31_LOG_FILE "sht31d_data.log"
#define SHT31_RETRY_COUNT 3
#define SHT31_LOG_INTERVAL 5

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = SHT31_CRC_INITIAL;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SHT31_CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = gpioI2COpen(1, SHT31_I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(SHT31_LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        uint8_t data[SHT31_DATA_LENGTH];
        int retries = 0;
        while (retries < SHT31_RETRY_COUNT) {
            if (gpioI2CWriteReadDevice(i2c_handle, SHT31_MEASUREMENT_CMD, data, SHT31_DATA_LENGTH) == SHT31_DATA_LENGTH) {
                break;
            }
            retries++;
            if (retries == SHT31_RETRY_COUNT) {
                fprintf(stderr, "Failed to read from SHT31 after %d retries\n", SHT31_RETRY_COUNT);
                break;
            }
            gpioDelay(100000); // 100ms delay
        }

        if (retries < SHT31_RETRY_COUNT) {
            uint16_t temperature_raw = (data[0] << 8) | data[1];
            uint16_t humidity_raw = (data[3] << 8) | data[4];
            uint8_t temperature_crc = data[2];
            uint8_t humidity_crc = data[5];

            if (temperature_crc != calculate_crc8(data, 2) || humidity_crc != calculate_crc8(data + 3, 2)) {
                fprintf(stderr, "CRC check failed\n");
                continue;
            }

            double temperature = -45 + 175 * temperature_raw / 65535;
            double humidity = 100 * humidity_raw / 65535;

            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

            fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
            fflush(log_file);
        }

        gpioDelay(SHT31_LOG_INTERVAL * 1000000); // 5 seconds
    }

    fclose(log_file);
    gpioI2CClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

