#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ADPD105_ADDR1 0x64
#define ADPD105_ADDR2 0x65
#define DEVICE_ID_REG 0x00
#define RED_REG 0x64
#define GREEN_REG 0x66
#define BLUE_REG 0x68
#define CCT_LOG_FILE "cct_log.csv"

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

uint16_t read_16bit_le(int i2c_handle, uint8_t reg) {
    uint8_t data[2];
    if (i2cReadI2CBlockData(i2c_handle, reg, data, 2) != 2) {
        fprintf(stderr, "Failed to read 16-bit value from register 0x%02X\n", reg);
        return 0;
    }
    return (data[1] << 8) | data[0];
}

double calculate_cct(uint16_t red, uint16_t green, uint16_t blue) {
    double r, g, b;
    r = red / 65535.0;
    g = green / 65535.0;
    b = blue / 65535.0;

    if (r > 0.04045) r = pow((r + 0.055) / 1.055, 2.4);
    else r = r / 12.92;
    if (g > 0.04045) g = pow((g + 0.055) / 1.055, 2.4);
    else g = g / 12.92;
    if (b > 0.04045) b = pow((b + 0.055) / 1.055, 2.4);
    else b = b / 12.92;

    double x = r * 0.649926 + g * 0.103455 + b * 0.197109;
    double y = r * 0.234327 + g * 0.743075 + b * 0.022598;
    double z = r * 0.000000 + g * 0.072910 + b * 0.927090;

    double n = (x + y + z) / 3.0;
    double u = (4.0 * x) / (x + 15.0 * y + 3.0 * z);
    double v = (9.0 * y) / (x + 15.0 * y + 3.0 * z);

    double CCT = 449.0 * pow(u - 0.3320, -1.4302) + 3525.0 * pow(v - 0.17697, -1.4052);

    return CCT;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    int i2c_handle1 = i2cOpen(I2C_BUS, ADPD105_ADDR1, 0);
    int i2c_handle2 = i2cOpen(I2C_BUS, ADPD105_ADDR2, 0);

    if (i2c_handle1 < 0 || i2c_handle2 < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(CCT_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Average_CCT\n");
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        uint8_t device_id1 = i2cReadByteData(i2c_handle1, DEVICE_ID_REG);
        uint8_t device_id2 = i2cReadByteData(i2c_handle2, DEVICE_ID_REG);

        if (device_id1 != 0x2A || device_id2 != 0x2A) {
            fprintf(stderr, "Device ID mismatch\n");
            continue;
        }

        uint16_t red1 = read_16bit_le(i2c_handle1, RED_REG);
        uint16_t green1 = read_16bit_le(i2c_handle1, GREEN_REG);
        uint16_t blue1 = read_16bit_le(i2c_handle1, BLUE_REG);

        uint16_t red2 = read_16bit_le(i2c_handle2, RED_REG);
        uint16_t green2 = read_16bit_le(i2c_handle2, GREEN_REG);
        uint16_t blue2 = read_16bit_le(i2c_handle2, BLUE_REG);

        double cct1 = calculate_cct(red1, green1, blue1);
        double cct2 = calculate_cct(red2, green2, blue2);

        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        fprintf(log_file, "%s,%.2f\n", timestamp, (cct1 + cct2) / 2.0);
        fflush(log_file);

        sleep(1);
    }

    fclose(log_file);
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    gpioTerminate();

    return EXIT_SUCCESS;
}

