#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x60
#define RAW_PRESSURE_REG 0x0A2C
#define RAW_TEMP_REG 0x0A2E
#define OUTPUT_MIN 0
#define OUTPUT_MAX 32768
#define P_MIN_KPA 0
#define P_MAX_KPA 800

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    int i2c_handle;
    FILE *log_file;
    time_t now;
    struct tm *tm_info;
    uint16_t raw_pressure, raw_temp;
    float pressure_kPa, temp_C;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("pressure_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        if (i2cReadWordData(i2c_handle, RAW_PRESSURE_REG, &raw_pressure) < 0) {
            fprintf(stderr, "Failed to read raw pressure\n");
        } else {
            pressure_kPa = (raw_pressure - OUTPUT_MIN) * (P_MAX_KPA - P_MIN_KPA) / (OUTPUT_MAX - OUTPUT_MIN);
            fprintf(log_file, "%s, Pressure: %.2f kPa\n", asctime(localtime(&now)), pressure_kPa);
        }

        if (i2cReadWordData(i2c_handle, RAW_TEMP_REG, &raw_temp) < 0) {
            fprintf(stderr, "Failed to read raw temperature\n");
        } else {
            temp_C = raw_temp * 0.01 - 40;
            fprintf(log_file, "%s, Temperature: %.2f C\n", asctime(localtime(&now)), temp_C);
        }

        fflush(log_file);
        sleep(2);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

