#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define GPIO_FAN 18
#define BUFFER_SIZE 60
#define AVG_TEMP_ON 28.0
#define AVG_TEMP_OFF 26.0
#define TEMP_RESOLUTION 0.5

volatile int running = 1;
volatile float buffer[BUFFER_SIZE];
volatile int buffer_index = 0;
volatile float running_avg = 0.0;

void signal_handler(int sig) {
    running = 0;
}

float read_temperature(int i2c_handle) {
    uint8_t data[2];
    if (i2cReadDevice(i2c_handle, 0x00, data, 2) != 2) {
        fprintf(stderr, "Failed to read temperature from LM75B\n");
        return -1.0;
    }
    int16_t temp_raw = (data[0] << 8) | data[1];
    return (temp_raw >> 7) * TEMP_RESOLUTION;
}

void update_running_avg(float new_temp) {
    running_avg = (running_avg * (BUFFER_SIZE - 1) + new_temp) / BUFFER_SIZE;
}

void control_fan(float avg_temp) {
    static int fan_state = 0;
    if (avg_temp > AVG_TEMP_ON && !fan_state) {
        if (gpioWrite(GPIO_FAN, PI_HIGH) != 0) {
            fprintf(stderr, "Failed to turn on fan\n");
        } else {
            fan_state = 1;
        }
    } else if (avg_temp < AVG_TEMP_OFF && fan_state) {
        if (gpioWrite(GPIO_FAN, PI_LOW) != 0) {
            fprintf(stderr, "Failed to turn off fan\n");
        } else {
            fan_state = 0;
        }
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_FAN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_FAN);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        float temp = read_temperature(i2c_handle);
        if (temp >= 0.0) {
            buffer[buffer_index] = temp;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;
            update_running_avg(temp);
            control_fan(running_avg);
        }
        sleep(1);
    }

    gpioWrite(GPIO_FAN, PI_LOW);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

