#define I2C_BUS 1
#define I2C_ADDR 0x25
#define CMD_CONT_MEAS 0x362F
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL 0xFF
#define LOG_FILE "airflow.log"

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = CRC8_INITIAL;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = gpioI2COpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        uint8_t cmd[2] = {CMD_CONT_MEAS >> 8, CMD_CONT_MEAS & 0xFF};
        if (gpioI2CWrite(i2c_handle, cmd, 2) != 2) {
            fprintf(stderr, "Failed to send measurement command\n");
            break;
        }

        gpioDelay(45000); // 45 ms delay

        uint8_t buffer[12];
        if (gpioI2CRead(i2c_handle, buffer, 12) != 12) {
            fprintf(stderr, "Failed to read measurement data\n");
            break;
        }

        uint16_t pressure_raw = (buffer[0] << 8) | buffer[1];
        uint16_t temperature_raw = (buffer[2] << 8) | buffer[3];
        uint8_t status = buffer[4];
        uint8_t crc8 = buffer[5];

        uint8_t calculated_crc8 = calculate_crc8(buffer, 5);
        if (crc8 != calculated_crc8) {
            fprintf(stderr, "CRC mismatch\n");
            continue;
        }

        double pressure = pressure_raw * 60.0;
        double temperature = temperature_raw * 200.0;

        if (pressure > 5.0) {
            fprintf(stderr, "Warning: Pressure exceeds 5.0 Pa\n");
        }

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
                tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
                tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec,
                pressure, temperature);
        fflush(log_file);

        gpioDelay(1000000); // 1 second delay
    }

    fclose(log_file);
    gpioI2CClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}
