#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <libgpiod.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x4A
#define LED_PIN 17
#define HYS_TEMP_HIGH 28.0
#define HYS_TEMP_LOW 27.0

static int i2c_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *led_line;

void cleanup_and_exit(int status) {
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(status);
}

void handle_signal(int signum) {
    cleanup_and_exit(EXIT_SUCCESS);
}

int main() {
    uint16_t temperature;
    int16_t msb, lsb;
    double temp_celsius;
    int ret;

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Request LED line
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get LED line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Configure LED line as output
    ret = gpiod_line_request_output(led_line, "temperature_led", 0);
    if (ret < 0) {
        perror("Failed to request LED line as output");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        // Read MSB and LSB from temperature sensor
        ret = read(i2c_fd, &msb, 1);
        if (ret != 1) {
            perror("Failed to read MSB from temperature sensor");
            cleanup_and_exit(EXIT_FAILURE);
        }
        ret = read(i2c_fd, &lsb, 1);
        if (ret != 1) {
            perror("Failed to read LSB from temperature sensor");
            cleanup_and_exit(EXIT_FAILURE);
        }

        // Combine MSB and LSB, right-shift by 4 bits, and convert to Celsius
        temperature = (msb << 8) | lsb;
        temp_celsius = (temperature >> 4) * 0.0625;

        // Log temperature to stdout
        printf("Temperature: %.2f °C\n", temp_celsius);

        // Drive LED based on temperature
        if (temp_celsius > HYS_TEMP_HIGH) {
            gpiod_line_set_value(led_line, 1);
        } else if (temp_celsius < HYS_TEMP_LOW) {
            gpiod_line_set_value(led_line, 0);
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Should never reach here
    cleanup_and_exit(EXIT_SUCCESS);
}

