#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define SI7021_MEASURE_RH 0xF5
#define SI7021_MEASURE_TEMP 0xF3
#define SI7021_READ_TEMP_FROM_RH 0xE0
#define SI7021_RETRY_COUNT 3
#define SAMPLE_INTERVAL 60
#define LOG_FILE "environment.log"

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int read_i2c_device(int handle, uint8_t reg, uint8_t *data, size_t len) {
    for (int i = 0; i < SI7021_RETRY_COUNT; i++) {
        if (i2cReadDevice(handle, reg, data, len) == len) {
            return 0;
        }
        gpioDelay(10000); // 10 ms delay
    }
    return -1;
}

int write_i2c_device(int handle, uint8_t reg, uint8_t *data, size_t len) {
    for (int i = 0; i < SI7021_RETRY_COUNT; i++) {
        if (i2cWriteDevice(handle, reg, data, len) == len) {
            return 0;
        }
        gpioDelay(10000); // 10 ms delay
    }
    return -1;
}

float convert_temperature(uint16_t raw) {
    return 175.72 * raw / 65536 - 46.85;
}

float convert_humidity(uint16_t raw) {
    float humidity = 125 * raw / 65536 - 6;
    return humidity < 0 ? 0 : (humidity > 100 ? 100 : humidity);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    int handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    uint8_t id[2];
    if (read_i2c_device(handle, 0xFA, id, sizeof(id)) < 0) {
        fprintf(stderr, "Failed to read sensor ID\n");
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        uint8_t data[2];
        if (write_i2c_device(handle, SI7021_MEASURE_RH, NULL, 0) < 0) {
            fprintf(stderr, "Failed to start RH measurement\n");
        } else {
            gpioDelay(20000); // 20 ms delay
            if (read_i2c_device(handle, 0, data, sizeof(data)) < 0) {
                fprintf(stderr, "Failed to read RH data\n");
            } else {
                float humidity = convert_humidity((data[0] << 8) | data[1]);
                if (write_i2c_device(handle, SI7021_READ_TEMP_FROM_RH, NULL, 0) < 0) {
                    fprintf(stderr, "Failed to start temp measurement\n");
                } else {
                    gpioDelay(20000); // 20 ms delay
                    if (read_i2c_device(handle, 0, data, sizeof(data)) < 0) {
                        fprintf(stderr, "Failed to read temp data\n");
                    } else {
                        float temperature = convert_temperature((data[0] << 8) | data[1]);
                        time_t now = time(NULL);
                        struct tm *tm = localtime(&now);
                        char timestamp[20];
                        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);
                        fprintf(stdout, "%s,%f,%f\n", timestamp, temperature, humidity);
                        fprintf(log_file, "%s,%f,%f\n", timestamp, temperature, humidity);
                        fflush(log_file);
                    }
                }
            }
        }
        sleep(SAMPLE_INTERVAL);
    }

    fclose(log_file);
    i2cClose(handle);
    gpioTerminate();
    return 0;
}

