#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define CONFIG_REG 0x02
#define MEASUREMENT_REG 0x00
#define TEMP_HUMIDITY_REG 0x00
#define CONVERSION_TIME 20
#define LOG_FILE "enviro_log.txt"

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    int i2c_handle = gpioI2COpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return 1;
    }

    if (gpioI2CWriteByteData(i2c_handle, CONFIG_REG, 0x03) < 0) {
        fprintf(stderr, "Failed to configure HDC1080\n");
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (!stop_flag) {
        if (gpioI2CWriteByteData(i2c_handle, MEASUREMENT_REG, 0x00) < 0) {
            fprintf(stderr, "Failed to start measurement\n");
            continue;
        }

        gpioDelay(CONVERSION_TIME * 1000);

        uint8_t data[4];
        if (gpioI2CRead(i2c_handle, data, 4) < 0) {
            fprintf(stderr, "Failed to read data from HDC1080\n");
            continue;
        }

        uint16_t raw_temp = (data[0] << 8) | data[1];
        uint16_t raw_humidity = (data[2] << 8) | data[3];

        double temperature = (raw_temp / 65536.0) * 165.0 - 40.0;
        double humidity = (raw_humidity / 65536.0) * 100.0;

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
        fflush(log_file);

        gpioDelay(5000 * 1000);
    }

    fclose(log_file);
    gpioI2CClose(i2c_handle);
    gpioTerminate();

    return 0;
}

