#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define I2C_DEVICE "/dev/i2c-1"
#define STS40_ADDRESS 0x44
#define MEASUREMENT_COMMAND 0x2CE0
#define CRC8_POLYNOMIAL 0x31
#define LOG_FILE "temperature_log.txt"
#define MEASUREMENT_INTERVAL 5

void log_temperature(double temperature) {
    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(log, "%04d-%02d-%02d %02d:%02d:%02d - %.2f°C\n",
            tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
            tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec, temperature);
    fclose(log);
}

unsigned char calculate_crc8(const unsigned char *data, size_t length) {
    unsigned char crc = 0xFF;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

void handle_sigint(int sig) {
    exit(0);
}

int main() {
    int fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, STS40_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    while (1) {
        unsigned char command[2] = {MEASUREMENT_COMMAND >> 8, MEASUREMENT_COMMAND & 0xFF};
        if (write(fd, command, sizeof(command)) != sizeof(command)) {
            fprintf(stderr, "Failed to send measurement command: %s\n", strerror(errno));
            continue;
        }

        usleep(10 * 1000); // Wait 10 ms for conversion

        unsigned char data[3];
        if (read(fd, data, sizeof(data)) != sizeof(data)) {
            fprintf(stderr, "Failed to read measurement data: %s\n", strerror(errno));
            continue;
        }

        unsigned char crc = calculate_crc8(data, 2);
        if (crc != data[2]) {
            fprintf(stderr, "CRC mismatch: expected 0x%02X, got 0x%02X\n", crc, data[2]);
            continue;
        }

        double temperature = -45 + 175 * (data[0] * 256 + data[1]) / 65535.0;
        log_temperature(temperature);

        sleep(MEASUREMENT_INTERVAL);
    }

    close(fd);
    return EXIT_SUCCESS;
}

