#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pigpio.h>
#include <signal.h>

#define I2C_BUS 1
#define I2C_ADDR 0x25
#define I2C_CMD 0x3615
#define I2C_READ_LEN 9
#define CRC8_POLY 0x31
#define CRC8_INIT 0xFF

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("hvac_pressure_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    while (!stop_flag) {
        if (i2cWriteWordData(i2c_handle, I2C_CMD, 0) < 0) {
            fprintf(stderr, "Failed to send command to I2C device\n");
        } else {
            uint8_t buffer[I2C_READ_LEN];
            if (i2cReadDevice(i2c_handle, buffer, I2C_READ_LEN) != I2C_READ_LEN) {
                fprintf(stderr, "Failed to read from I2C device\n");
            } else {
                uint8_t pressure_crc = calculate_crc8(buffer, 2);
                uint8_t temperature_crc = calculate_crc8(buffer + 3, 2);
                uint8_t scale_factor_crc = calculate_crc8(buffer + 6, 3);

                if (pressure_crc != buffer[2] || temperature_crc != buffer[5] || scale_factor_crc != buffer[8]) {
                    fprintf(log_file, "%ld,%s\n", time(NULL), "CRC error");
                } else {
                    uint16_t pressure_raw = (buffer[0] << 8) | buffer[1];
                    uint16_t temperature_raw = (buffer[3] << 8) | buffer[4];
                    uint32_t scale_factor_raw = (buffer[6] << 16) | (buffer[7] << 8) | buffer[8];
                    double pressure = pressure_raw / (double)scale_factor_raw;
                    double temperature = temperature_raw / 200.0;

                    fprintf(log_file, "%ld,%.2f,%.2f\n", time(NULL), pressure, temperature);
                }
            }
        }

        sleep(1);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

