This C program uses the pigpio library to monitor air duct pressure in a simulated HVAC system. It reads data from a Sensirion SDP810-500Pa differential pressure sensor over I2C bus 1 at address 0x25, validates the data, and logs valid readings to `hvac_pressure_log.txt`. It handles errors, including I2C communication errors and CRC mismatches, and exits gracefully on SIGINT (Ctrl+C).

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

#define SCD40_I2C_ADDRESS 0x62
#define SCD40_I2C_BUS 1
#define SCD40_START_MEASUREMENT 0x21B1
#define SCD40_READ_MEASUREMENT 0xE000
#define SCD40_STOP_MEASUREMENT 0x3F86
#define SCD40_BUFFER_SIZE 100
#define SCD40_LOG_DIR "/var/log/scd40_data/"
#define SCD40_LOG_FILE "/var/log/scd40_error.log"

typedef struct {
    time_t timestamp;
    uint16_t co2;
    float temperature;
    float humidity;
} Reading;

volatile sig_atomic_t running = 1;

void log_error(const char *message) {
    FILE *log_file = fopen(SCD40_LOG_FILE, "a");
    if (log_file) {
        time_t now = time(NULL);
        fprintf(log_file, "%s: %s\n", ctime(&now), message);
        fclose(log_file);
    }
}

int calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_scd40(uint16_t *co2, float *temperature, float *humidity) {
    uint8_t buffer[9];
    if (i2cReadDevice(pi, SCD40_I2C_ADDRESS, buffer, 9) != 9) {
        log_error("Failed to read from SCD40 sensor");
        return -1;
    }

    uint16_t co2_raw = (buffer[0] << 8) | buffer[1];
    uint16_t temperature_raw = (buffer[3] << 8) | buffer[4];
    uint16_t humidity_raw = (buffer[6] << 8) | buffer[7];

    uint8_t co2_crc = buffer[2];
    uint8_t temperature_crc = buffer[5];
    uint8_t humidity_crc = buffer[8];

    if (calculate_crc8(buffer, 2) != co2_crc ||
        calculate_crc8(buffer + 3, 2) != temperature_crc ||
        calculate_crc8(buffer + 6, 2) != humidity_crc) {
        log_error("CRC check failed for SCD40 sensor");
        return -1;
    }

    *co2 = co2_raw;
    *temperature = -45.0 + 175.0 * temperature_raw / 65535.0;
    *humidity = 100.0 * humidity_raw / 65535.0;

    return 0;
}

void *log_thread_func(void *arg) {
    Reading *buffer = (Reading *)arg;
    FILE *log_file = fopen(SCD40_LOG_DIR "scd40_data.csv", "a");
    if (!log_file) {
        log_error("Failed to open log file");
        return NULL;
    }

    if (mkdir(SCD40_LOG_DIR, 0755) == -1 && errno != EEXIST) {
        log_error("Failed to create log directory");
        fclose(log_file);
        return NULL;
    }

    time_t now = time(NULL);
    fprintf(log_file, "Timestamp,CO2,Temperature,Humidity\n");
    for (int i = 0; i < SCD40_BUFFER_SIZE; i++) {
        if (buffer[i].timestamp != 0) {
            fprintf(log_file, "%s,%d,%.2f,%.2f\n", ctime(&buffer[i].timestamp), buffer[i].co2, buffer[i].temperature, buffer[i].humidity);
        }
    }
    fclose(log_file);
    return NULL;
}

int main() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio");
        return 1;
    }

    if (i2cOpen(pi, SCD40_I2C_BUS, SCD40_I2C_ADDRESS) < 0) {
        log_error("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    if (i2cWriteWordData(pi, SCD40_I2C_ADDRESS, SCD40_START_MEASUREMENT) < 0) {
        log_error("Failed to start periodic measurement");
        i2cClose(pi);
        gpioTerminate();
        return 1;
    }

    Reading buffer[SCD40_BUFFER_SIZE];
    memset(buffer, 0, sizeof(buffer));
    int buffer_index = 0;

    pthread_t log_thread;
    if (pthread_create(&log_thread, NULL, log_thread_func, buffer) != 0) {
        log_error("Failed to create log thread");
        i2cClose(pi);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, [](int sig) {
        running = 0;
    });

    while (running) {
        sleep(5);

        uint16_t co2;
        float temperature, humidity;
        if (read_scd40(&co2, &temperature, &humidity) == 0) {
            buffer[buffer_index].timestamp = time(NULL);
            buffer[buffer_index].co2 = co2;
            buffer[buffer_index].temperature = temperature;
            buffer[buffer_index].humidity = humidity;
            buffer_index = (buffer_index + 1) % SCD40_BUFFER_SIZE;
        }
    }

    if (i2cWriteWordData(pi, SCD40_I2C_ADDRESS, SCD40_STOP_MEASUREMENT) < 0) {
        log_error("Failed to stop periodic measurement");
    }

    pthread_join(log_thread, NULL);

    for (int i = 0; i < SCD40_BUFFER_SIZE; i++) {
        if (buffer[i].timestamp != 0) {
            log_error("Writing final buffer data to log file");
            break;
        }
    }

    i2cClose(pi);
    gpioTerminate();

    return 0;
}

