#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x63
#define WHO_AM_I 0x08
#define CALIBRATION_START 0x05
#define MEASUREMENT_REG 0x00
#define DATA_SIZE 6
#define SAMPLE_INTERVAL 5000000
#define LOG_FILE "environmental_data.txt"

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int sig) {
    stop_flag = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return 1;
    }

    uint8_t who_am_i;
    if (i2cReadByteData(i2c_handle, WHO_AM_I, &who_am_i) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (who_am_i != 0x08) {
        fprintf(stderr, "Incorrect sensor identity\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t calibration[4];
    if (i2cReadI2CBlockData(i2c_handle, CALIBRATION_START, 4, calibration) < 0) {
        fprintf(stderr, "Failed to read calibration coefficients\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (!stop_flag) {
        if (i2cWriteByteData(i2c_handle, MEASUREMENT_REG, 0x00) < 0) {
            fprintf(stderr, "Failed to trigger measurement\n");
        } else {
            gpioDelay(10000); // 10 ms delay

            uint8_t data[DATA_SIZE];
            if (i2cReadI2CBlockData(i2c_handle, MEASUREMENT_REG, DATA_SIZE, data) < 0) {
                fprintf(stderr, "Failed to read measurement data\n");
            } else {
                int32_t pressure_raw = (data[0] << 16) | (data[1] << 8) | data[2];
                int32_t temperature_raw = (data[3] << 16) | (data[4] << 8) | data[5];

                // Convert to hPa and Celsius using ICP-10110 formulas
                float pressure = pressure_raw * 0.01;
                float temperature = temperature_raw * 0.01;

                time_t now = time(NULL);
                char timestamp[20];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));

                fprintf(log_file, "%s, Pressure: %.2f hPa, Temperature: %.2f C\n", timestamp, pressure, temperature);
                fprintf(stdout, "%s, Pressure: %.2f hPa, Temperature: %.2f C\n", timestamp, pressure, temperature);

                fflush(log_file);
            }
        }

        gpioDelay(SAMPLE_INTERVAL);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

