#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x5A
#define AMBIENT_REG 0x06
#define OBJECT_REG 0x07
#define FAN_PIN 18
#define Hysteresis 2
#define RetryCount 3
#define RetryDelay 10

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

int read_i2c(int handle, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    int retries = RetryCount;
    while (retries--) {
        if (i2cReadDevice(handle, reg, buf, 2) == 2) {
            *value = (buf[0] << 8) | buf[1];
            return 0;
        }
        gpioDelay(RetryDelay * 1000);
    }
    return -1;
}

void log_temperature(uint16_t ambient, uint16_t object) {
    FILE *log_file = fopen("temperature_log.txt", "a");
    if (log_file) {
        time_t now = time(NULL);
        fprintf(log_file, "%s, Ambient: %.2f°C, Object: %.2f°C\n", ctime(&now), ambient * 0.02 - 273.15, object * 0.02 - 273.15);
        fclose(log_file);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(FAN_PIN, PI_OUTPUT);
    gpioWrite(FAN_PIN, 0);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t ambient, object;
    while (!stop_flag) {
        if (read_i2c(i2c_handle, AMBIENT_REG, &ambient) == 0 && read_i2c(i2c_handle, OBJECT_REG, &object) == 0) {
            float ambient_c = ambient * 0.02 - 273.15;
            float object_c = object * 0.02 - 273.15;
            if (ambient_c >= -40 && ambient_c <= 125 && object_c >= -40 && object_c <= 125) {
                log_temperature(ambient, object);
                if (object_c > 30) {
                    gpioWrite(FAN_PIN, 1);
                } else if (object_c < 28) {
                    gpioWrite(FAN_PIN, 0);
                }
            }
        }
        gpioDelay(2000000);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

