#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define HDC2010_ADDR 0x40
#define MEASUREMENT_CONFIG 0x0E
#define CONFIG 0x0F
#define TEMP_HUMIDITY 0x00
#define MAX_RETRIES 5
#define TIMEOUT_MS 500

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    int i2c_handle = gpioI2COpen(I2C_BUS, HDC2010_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (!stop_flag) {
        uint8_t config[1] = {CONFIG};
        if (gpioI2CWrite(i2c_handle, config, 1) < 0) {
            fprintf(stderr, "Failed to write to CONFIG register\n");
            goto cleanup;
        }

        uint8_t measurement_config[1] = {0x01};
        if (gpioI2CWrite(i2c_handle, measurement_config, 1) < 0) {
            fprintf(stderr, "Failed to start measurement\n");
            goto cleanup;
        }

        uint8_t status[1];
        int retries = 0;
        while (retries < MAX_RETRIES) {
            if (gpioI2CRead(i2c_handle, status, 1) < 0) {
                fprintf(stderr, "Failed to read status register\n");
                goto cleanup;
            }

            if (!(status[0] & 0x01)) {
                break;
            }

            retries++;
            usleep(1000);
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Measurement timed out\n");
            goto cleanup;
        }

        uint8_t data[4];
        if (gpioI2CRead(i2c_handle, data, 4) < 0) {
            fprintf(stderr, "Failed to read temperature and humidity\n");
            goto cleanup;
        }

        uint16_t temp_raw = (data[0] << 8) | data[1];
        uint16_t humid_raw = (data[2] << 8) | data[3];

        double temperature = (temp_raw / 65536.0) * 165.0 - 40.0;
        double humidity = (humid_raw / 65536.0) * 100.0;

        printf("Temperature: %.2f°C, Humidity: %.2f%%\n", temperature, humidity);

        sleep(5);
    }

cleanup:
    gpioI2CClose(i2c_handle);
    gpioTerminate();

    return 0;
}

