#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x25
#define MEASUREMENT_CMD 0x362F
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL 0xFF
#define MEASUREMENT_TIME 45
#define LOG_INTERVAL 500

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = CRC_INITIAL;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc = crc << 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = gpioI2COpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    while (running) {
        if (gpioI2CWriteByte(i2c_handle, MEASUREMENT_CMD) < 0) {
            fprintf(stderr, "Failed to send measurement command\n");
            break;
        }

        gpioDelay(MEASUREMENT_TIME * 1000);

        uint8_t buffer[6];
        if (gpioI2CRead(i2c_handle, buffer, 6) != 6) {
            fprintf(stderr, "Failed to read 6 bytes from sensor\n");
            break;
        }

        uint16_t pressure_raw = (buffer[0] << 8) | buffer[1];
        uint16_t temperature_raw = (buffer[4] << 8) | buffer[5];

        uint8_t pressure_crc = calculate_crc8(buffer, 2);
        uint8_t temperature_crc = calculate_crc8(buffer + 4, 2);

        if (pressure_crc != buffer[2] || temperature_crc != buffer[5]) {
            fprintf(stderr, "CRC error in sensor data\n");
            break;
        }

        printf("Pressure: 0x%04X, Temperature: 0x%04X\n", pressure_raw, temperature_raw);

        gpioDelay(LOG_INTERVAL * 1000);
    }

    gpioI2CClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

