#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define RELAY_PIN 17
#define TARGET_PROFILE "profile.txt"
#define LOG_FILE "reflow_log.csv"

struct pid_controller {
    double Kp, Ki, Kd;
    double setpoint, integral, last_error;
};

struct thermocouple {
    int fd;
    struct gpiod_chip *chip;
    struct gpiod_line *relay;
};

void signal_handler(int signum) {
    printf("Signal %d received, exiting...\n", signum);
    exit(signum);
}

int read_thermocouple(struct thermocouple *tc) {
    uint8_t tx[2] = {0x00, 0x00};
    uint8_t rx[2];
    int ret;

    ret = ioctl(tc->fd, SPI_IOC_MESSAGE(1), &tx);
    if (ret < 0) {
        perror("SPI_IOC_MESSAGE");
        return -1;
    }

    ret = read(tc->fd, rx, 2);
    if (ret < 0) {
        perror("read");
        return -1;
    }

    if (rx[0] & 0x04) {
        fprintf(stderr, "Thermocouple open-circuit detected\n");
        return -1;
    }

    int temp = ((rx[0] & 0x3F) << 8) | rx[1];
    return temp >> 4;
}

double pid_compute(struct pid_controller *pid, double measured) {
    double error = pid->setpoint - measured;
    pid->integral += error;
    double derivative = error - pid->last_error;
    pid->last_error = error;

    return pid->Kp * error + pid->Ki * pid->integral + pid->Kd * derivative;
}

void control_relay(struct thermocouple *tc, double output) {
    if (output > 1.0) output = 1.0;
    if (output < 0.0) output = 0.0;

    int duty_cycle = (int)(output * 100);
    gpiod_line_set_value(tc->relay, duty_cycle);
}

int main() {
    struct pid_controller pid = {Kp: 1.0, Ki: 0.1, Kd: 0.01, setpoint: 0.0, integral: 0.0, last_error: 0.0};
    struct thermocouple tc;
    FILE *profile_file, *log_file;
    char line[256];
    double time_seconds, target_temp_celsius;
    int temp, log_fd;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    tc.fd = open(SPI_DEVICE, O_RDWR);
    if (tc.fd < 0) {
        perror("open");
        return EXIT_FAILURE;
    }

    if (ioctl(tc.fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("SPI_IOC_WR_MODE");
        close(tc.fd);
        return EXIT_FAILURE;
    }

    if (ioctl(tc.fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("SPI_IOC_WR_BITS_PER_WORD");
        close(tc.fd);
        return EXIT_FAILURE;
    }

    if (ioctl(tc.fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        close(tc.fd);
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    tc.chip = gpiod_chip_open("/dev/gpiochip0");
    if (!tc.chip) {
        perror("gpiod_chip_open");
        close(tc.fd);
        return EXIT_FAILURE;
    }

    tc.relay = gpiod_chip_get_line(tc.chip, RELAY_PIN);
    if (!tc.relay) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(tc.chip);
        close(tc.fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(tc.relay, "reflow_oven_relay", 0) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(tc.chip);
        close(tc.fd);
        return EXIT_FAILURE;
    }

    // Open profile and log files
    profile_file = fopen(TARGET_PROFILE, "r");
    if (!profile_file) {
        perror("fopen");
        gpiod_line_release(tc.relay);
        gpiod_chip_close(tc.chip);
        close(tc.fd);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("fopen");
        fclose(profile_file);
        gpiod_line_release(tc.relay);
        gpiod_chip_close(tc.chip);
        close(tc.fd);
        return EXIT_FAILURE;
    }

    // Read and process profile
    while (fgets(line, sizeof(line), profile_file)) {
        if (sscanf(line, "%lf,%lf", &time_seconds, &target_temp_celsius) != 2) {
            fprintf(stderr, "Invalid line in profile.txt\n");
            continue;
        }

        pid.setpoint = target_temp_celsius;

        for (double elapsed = 0.0; elapsed < time_seconds; elapsed += 1.0) {
            temp = read_thermocouple(&tc);
            if (temp < 0) {
                fprintf(stderr, "Failed to read thermocouple\n");
                continue;
            }

            double output = pid_compute(&pid, temp);
            control_relay(&tc, output);

            fprintf(log_file, "%.1f,%.1f,%.1f\n", elapsed, temp, output);
            fflush(log_file);

            sleep(1);
        }
    }

    // Cleanup
    fclose(profile_file);
    fclose(log_file);
    gpiod_line_release(tc.relay);
    gpiod_chip_close(tc.chip);
    close(tc.fd);

    return EXIT_SUCCESS;
}

