#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define DS18B20_PATH "/sys/bus/w1/devices/28-000000000000/w1_slave"
#define RELAY_PIN 17
#define PWM_PIN 18
#define LOG_FILE "greenhouse.log"

static struct gpiod_chip *chip;
static struct gpiod_line *relay_line, *pwm_line;
static FILE *log_file;

static void cleanup() {
    if (relay_line) gpiod_line_release(relay_line);
    if (pwm_line) gpiod_line_release(pwm_line);
    if (chip) gpiod_chip_close(chip);
    if (log_file) fclose(log_file);
}

static void signal_handler(int signum) {
    cleanup();
    exit(signum);
}

static int read_temperature() {
    FILE *file = fopen(DS18B20_PATH, "r");
    if (!file) return -1;

    char buffer[256];
    if (!fgets(buffer, sizeof(buffer), file)) {
        fclose(file);
        return -1;
    }

    if (strncmp(buffer, "t=", 2) != 0) {
        fclose(file);
        return -1;
    }

    char *end;
    long temp = strtol(buffer + 2, &end, 10);
    if (*end != '\n') {
        fclose(file);
        return -1;
    }

    fclose(file);
    return temp / 1000;
}

static void control_heater(int temperature, double setpoint, double Kp, double Ki, double Kd) {
    static double integral = 0.0, last_error = 0.0;
    double error = setpoint - temperature;
    integral += error;
    double derivative = error - last_error;
    last_error = error;

    double output = Kp * error + Ki * integral + Kd * derivative;
    if (output > 100) output = 100;
    if (output < 0) output = 0;

    int duty_cycle = (int)(output * 1023 / 100);
    gpiod_line_set_value(pwm_line, duty_cycle);

    if (output > 0) {
        gpiod_line_set_value(relay_line, 1);
    } else {
        gpiod_line_set_value(relay_line, 0);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <setpoint> <Kp> <Ki> <Kd>\n", argv[0]);
        return 1;
    }

    double setpoint = atof(argv[1]);
    double Kp = atof(argv[2]);
    double Ki = atof(argv[3]);
    double Kd = atof(argv[4]);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        perror("Failed to get relay line");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(relay_line, "heater_relay", 0) < 0) {
        perror("Failed to request relay line");
        cleanup();
        return 1;
    }

    pwm_line = gpiod_chip_get_line(chip, PWM_PIN);
    if (!pwm_line) {
        perror("Failed to get PWM line");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(pwm_line, "heater_pwm", 0) < 0) {
        perror("Failed to request PWM line");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    while (1) {
        int temperature = read_temperature();
        if (temperature == -1) {
            fprintf(stderr, "Failed to read temperature\n");
            sleep(5);
            continue;
        }

        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, %d, %.1f, %.1f, %.1f, %d\n",
                tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
                tm->tm_hour, tm->tm_min, tm->tm_sec,
                temperature, setpoint, Kp, Ki, Kd, temperature);

        control_heater(temperature, setpoint, Kp, Ki, Kd);

        sleep(5);
    }

    cleanup();
    return 0;
}

