#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x38
#define RELAY_PIN 17
#define AHT20_INIT_CMD "\xBE\x08\x00"
#define AHT20_MEAS_CMD "\xAC\x33\x00"
#define AHT20_DATA_LEN 6
#define AHT20_STATUS_MASK 0x03
#define AHT20_STATUS_BUSY 0x01
#define AHT20_STATUS_CALIBRATED 0x02
#define RETRY_COUNT 3
#define RETRY_DELAY 10
#define POLL_INTERVAL 5000

static struct gpiod_chip *chip;
static struct gpiod_line *relay_line;
static int i2c_fd;

void handle_sigint(int sig) {
    gpiod_line_release(relay_line);
    close(i2c_fd);
    exit(0);
}

int i2c_write_retry(int fd, const char *buf, size_t len) {
    int retries = RETRY_COUNT;
    while (retries--) {
        if (write(fd, buf, len) == len) {
            return 0;
        }
        usleep(RETRY_DELAY * 1000);
    }
    return -1;
}

int i2c_read_retry(int fd, char *buf, size_t len) {
    int retries = RETRY_COUNT;
    while (retries--) {
        if (read(fd, buf, len) == len) {
            return 0;
        }
        usleep(RETRY_DELAY * 1000);
    }
    return -1;
}

int aht20_init(int fd) {
    char init_cmd[] = AHT20_INIT_CMD;
    if (i2c_write_retry(fd, init_cmd, sizeof(init_cmd)) != 0) {
        fprintf(stderr, "Failed to initialize AHT20 sensor\n");
        return -1;
    }
    usleep(100000); // Wait for 100ms
    return 0;
}

int aht20_read_humidity(int fd, float *humidity) {
    char meas_cmd[] = AHT20_MEAS_CMD;
    char data[AHT20_DATA_LEN];
    if (i2c_write_retry(fd, meas_cmd, sizeof(meas_cmd)) != 0) {
        fprintf(stderr, "Failed to trigger AHT20 measurement\n");
        return -1;
    }
    usleep(80000); // Wait for 80ms

    if (i2c_read_retry(fd, data, sizeof(data)) != 0) {
        fprintf(stderr, "Failed to read AHT20 data\n");
        return -1;
    }

    if ((data[0] & AHT20_STATUS_MASK) != AHT20_STATUS_CALIBRATED) {
        fprintf(stderr, "AHT20 not calibrated\n");
        return -1;
    }

    if (data[0] & AHT20_STATUS_BUSY) {
        fprintf(stderr, "AHT20 still busy\n");
        return -1;
    }

    uint32_t humidity_raw = (data[1] << 16) | (data[2] << 8) | data[3];
    *humidity = (humidity_raw * 100.0) / 0x000FFFFF;
    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if ((chip = gpiod_chip_open("/dev/gpiochip0")) == NULL) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    if ((relay_line = gpiod_chip_get_line(chip, RELAY_PIN)) == NULL) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(relay_line, "dehumidifier", 0) != 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        return 1;
    }

    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (aht20_init(i2c_fd) != 0) {
        close(i2c_fd);
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        return 1;
    }

    while (1) {
        float humidity;
        if (aht20_read_humidity(i2c_fd, &humidity) == 0) {
            time_t now = time(NULL);
            printf("%s: Humidity: %.2f%%\n", ctime(&now), humidity);
            if (humidity > 60.0) {
                gpiod_line_set_value(relay_line, 1);
            } else if (humidity < 55.0) {
                gpiod_line_set_value(relay_line, 0);
            }
        } else {
            fprintf(stderr, "Failed to read humidity, retrying...\n");
        }
        sleep(POLL_INTERVAL / 1000);
    }

    close(i2c_fd);
    gpiod_line_release(relay_line);
    gpiod_chip_close(chip);
    return 0;
}

