#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <syslog.h>
#include <signal.h>

#define I2C_DEVICE "/dev/i2c-1"
#define HTU21D_ADDRESS 0x40
#define HTU21D_HUMIDITY_REG 0xF5
#define HTTP_HOST "api.example.com"
#define HTTP_PORT 80
#define HTTP_PATH "/humidity"
#define BUFFER_SIZE 256

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t *data, size_t len) {
    uint8_t buf[1] = {reg};
    if (write(fd, buf, 1) != 1) {
        syslog(LOG_ERR, "I2C write failed");
        return -1;
    }
    if (read(fd, data, len) != len) {
        syslog(LOG_ERR, "I2C read failed");
        return -1;
    }
    return 0;
}

int http_post(int sockfd, const char *data) {
    char request[BUFFER_SIZE];
    snprintf(request, BUFFER_SIZE, "POST %s HTTP/1.1\r\nHost: %s\r\nContent-Type: application/json\r\nContent-Length: %zu\r\n\r\n%s",
             HTTP_PATH, HTTP_HOST, strlen(data), data);
    if (send(sockfd, request, strlen(request), 0) != strlen(request)) {
        syslog(LOG_ERR, "HTTP POST failed");
        return -1;
    }
    return 0;
}

int main() {
    int i2c_fd, http_fd;
    struct sockaddr_in server_addr;
    uint8_t humidity_data[2];
    double humidity;
    char json_data[BUFFER_SIZE];

    openlog("humidity_sensor", LOG_PID | LOG_CONS, LOG_USER);

    // Open I2C device
    if ((i2c_fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        syslog(LOG_ERR, "Failed to open I2C device");
        closelog();
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, HTU21D_ADDRESS) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address");
        close(i2c_fd);
        closelog();
        return EXIT_FAILURE;
    }

    // Open HTTP socket
    if ((http_fd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        syslog(LOG_ERR, "Failed to create HTTP socket");
        close(i2c_fd);
        closelog();
        return EXIT_FAILURE;
    }

    // Set up server address
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(HTTP_PORT);
    if (inet_pton(AF_INET, HTTP_HOST, &server_addr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid HTTP host address");
        close(http_fd);
        close(i2c_fd);
        closelog();
        return EXIT_FAILURE;
