            fprintf(log_file, "%s: Pressure threshold breached: %.2f hPa\n", ctime(&now), pressure);
            fflush(log_file);
        }
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

