#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>

#define I2C_DEVICE "/dev/i2c-1"
#define TMP117_ADDRESS 0x48
#define AHT20_ADDRESS 0x38
#define PIR_PIN 17
#define GPIO_CHIP "gpiochip4"
#define CSV_HEADER "Timestamp,Temperature(C),Humidity(%),MotionDetected\n"

int i2c_fd;
struct gpiod_chip *chip;
struct gpiod_line *pir_line;
time_t last_log_time;

void init_i2c() {
    if ((i2c_fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, TMP117_ADDRESS) < 0) {
        perror("Failed to set I2C address for TMP117");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDRESS) < 0) {
        perror("Failed to set I2C address for AHT20");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void init_gpio() {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }
    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_input(pir_line, "pir_sensor") < 0) {
        perror("Failed to request GPIO line as input");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
}

void log_data() {
    time_t now = time(NULL);
    if (difftime(now, last_log_time) < 86400) {
        return;
    }
    last_log_time = now;

    FILE *log_file = fopen("log.csv", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    char timestamp[20];
    struct tm *tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    // TMP117 temperature
    uint16_t temp_raw;
    if (read(i2c_fd, &temp_raw, 2) != 2) {
        fprintf(stderr, "Failed to read TMP117 temperature\n");
        fclose(log_file);
        return;
    }
    float temperature = (temp_raw >> 4) * 0.0078125;

    // AHT20 humidity and temperature
    uint8_t aht20_cmd[] = {0xAC, 0x33, 0x00};
    if (write(i2c_fd, aht20_cmd, sizeof(aht20_cmd)) != sizeof(aht20_cmd)) {
        fprintf(stderr, "Failed to send AHT20 measure command\n");
        fclose(log_file);
        return;
    }
    usleep(100000); // Wait for measurement to complete

    uint8_t aht20_data[7];
    int retries = 3;
    while (retries--) {
        if (read(i2c_fd, aht20_data, sizeof(aht20_data)) == sizeof(aht20_data)) {
            if (!(aht20_data[0] & 0x80)) {
                uint32_t humidity_raw = (aht20_data[1] << 12) | (aht20_data[2] << 4) | (aht20_data[3] >> 4);
                uint32_t temperature_raw = ((aht20_data[3] & 0x0F) << 16) | (aht20_data[4] << 8) | aht20_data[5];
                float humidity = humidity_raw * 0.0000625;
                float temp_c = temperature_raw * 0.0001875 - 40;
                fprintf(log_file, "%s,%.2f,%.2f,%d\n", timestamp, temperature, humidity, gpiod_line_get_value(pir_line));
                fclose(log_file);
                return;
            }
        }
        usleep(10000); // 10 ms backoff
    }
    fprintf(stderr, "Failed to read AHT20 data after retries\n");
    fclose(log_file);
}

void cleanup() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

void signal_handler(int sig) {
    cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    init_i2c();
    init_gpio();

    FILE *log_file = fopen("log.csv", "a");
    if (log_file) {
        fprintf(log_file, "%s", CSV_HEADER);
        fclose(log_file);
    }

    last_log_time = time(NULL);
    while (1) {
        log_data();
        sleep(1);
    }

    cleanup();
    return 0;
}

