#include <string.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define RAIN_SENSOR_CHIP "gpiochip0"
#define RAIN_SENSOR_LINE 17
#define MOTOR_ENA_LINE 22
#define MOTOR_IN1_LINE 23
#define MOTOR_IN2_LINE 24
#define MOTOR_RUN_TIME 5

static struct gpiod_chip *chip;
static struct gpiod_line *rain_sensor_line;
static struct gpiod_line *motor_ena_line;
static struct gpiod_line *motor_in1_line;
static struct gpiod_line *motor_in2_line;

void log_event(const char *event) {
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
    printf("[%s] %s\n", timestamp, event);
}

void close_motor() {
    gpiod_line_set_value(motor_ena_line, 0);
    gpiod_line_set_value(motor_in1_line, 0);
    gpiod_line_set_value(motor_in2_line, 0);
    log_event("Motor stopped");
}

void handle_signal(int sig) {
    log_event("Signal received, shutting down");
    close_motor();
    gpiod_line_release(rain_sensor_line);
    gpiod_line_release(motor_ena_line);
    gpiod_line_release(motor_in1_line);
    gpiod_line_release(motor_in2_line);
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open_by_name(RAIN_SENSOR_CHIP);
    if (!chip) {
        log_event("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    rain_sensor_line = gpiod_chip_get_line(chip, RAIN_SENSOR_LINE);
    if (!rain_sensor_line) {
        log_event("Failed to get rain sensor line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    motor_ena_line = gpiod_chip_get_line(chip, MOTOR_ENA_LINE);
    if (!motor_ena_line) {
        log_event("Failed to get motor ENA line");
        gpiod_line_release(rain_sensor_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    motor_in1_line = gpiod_chip_get_line(chip, MOTOR_IN1_LINE);
    if (!motor_in1_line) {
        log_event("Failed to get motor IN1 line");
        gpiod_line_release(motor_ena_line);
        gpiod_line_release(rain_sensor_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    motor_in2_line = gpiod_chip_get_line(chip, MOTOR_IN2_LINE);
    if (!motor_in2_line) {
        log_event("Failed to get motor IN2 line");
        gpiod_line_release(motor_in1_line);
        gpiod_line_release(motor_ena_line);
        gpiod_line_release(rain_sensor_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(rain_sensor_line, "rain_sensor") < 0) {
        log_event("Failed to request input for rain sensor line");
        gpiod_line_release(motor_in2_line);
        gpiod_line_release(motor_in1_line);
        gpiod_line_release(motor_ena_line);
        gpiod_line_release(rain_sensor_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(motor_ena_line, "motor_ena", 0) < 0) {
        log_event("Failed to request output for motor ENA line");
        gpiod_line_release(motor_in2_line);
        gpiod_line_release(motor_in1_line);
        gpiod_line_release(motor_ena_line);
        gpiod_line_release(rain_sensor_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(motor_in1_line, "motor_in1", 0) < 0) {
        log_event("Failed to request output for motor IN1 line");
        gpiod_line_release(motor_in2_line);
        gpiod_line_release(motor_in1_line);
        gpiod_line_release(motor_ena_line);
        gpiod_line_release(rain_sensor_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(motor_in2_line, "motor_in2", 0) < 0) {
        log_event("Failed to request output for motor IN2 line");
        gpiod_line_release(motor_in2_line);
        gpiod_line_release(motor_in1_line);
        gpiod_line_release(motor_ena_line);
        gpiod_line_release(rain_sensor_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_event("Program started");

    while (1) {
        int rain_detected = gpiod_line_get_value(rain_sensor_line);
        if (rain_detected == 0) {
            log_event("Rain detected, closing window");
            gpiod_line_set_value(motor_ena_line, 1);
            gpiod_line_set_value(motor_in1_line, 1);
            gpiod_line_set_value(motor_in2_line, 0);
            sleep(MOTOR_RUN_TIME);
            close_motor();
        }
        sleep(2);
    }

    return EXIT_SUCCESS;
}

