#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_RED 17
#define GPIO_GREEN 22
#define GPIO_BLUE 27
#define PWM_FREQ 1000
#define SAMPLE_INTERVAL 500000

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

void set_led_color(int red, int green, int blue) {
    gpioSetPWMRange(GPIO_RED, 255);
    gpioSetPWMRange(GPIO_GREEN, 255);
    gpioSetPWMRange(GPIO_BLUE, 255);
    gpioSetPWMFrequency(GPIO_RED, PWM_FREQ);
    gpioSetPWMFrequency(GPIO_GREEN, PWM_FREQ);
    gpioSetPWMFrequency(GPIO_BLUE, PWM_FREQ);
    gpioSetPWMdutycycle(GPIO_RED, red);
    gpioSetPWMdutycycle(GPIO_GREEN, green);
    gpioSetPWMdutycycle(GPIO_BLUE, blue);
}

int get_cpu_load() {
    FILE *fp;
    char buffer[1024];
    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    unsigned long long prev_user, prev_nice, prev_system, prev_idle, prev_iowait, prev_irq, prev_softirq, prev_steal, prev_guest, prev_guest_nice;
    static unsigned long long prev_total = 0;
    unsigned long long total, total_diff, idle_diff;
    int load;

    fp = fopen("/proc/stat", "r");
    if (!fp) {
        perror("Failed to open /proc/stat");
        return -1;
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        fclose(fp);
        perror("Failed to read /proc/stat");
        return -1;
    }

    sscanf(buffer, "cpu %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
           &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice);

    fclose(fp);

    total = user + nice + system + idle + iowait + irq + softirq + steal + guest + guest_nice;
    total_diff = total - prev_total;
    idle_diff = idle - prev_idle;

    prev_user = user;
    prev_nice = nice;
    prev_system = system;
    prev_idle = idle;
    prev_iowait = iowait;
    prev_irq = irq;
    prev_softirq = softirq;
    prev_steal = steal;
    prev_guest = guest;
    prev_guest_nice = guest_nice;
    prev_total = total;

    if (total_diff == 0) {
        return 0;
    }

    load = (int)((100 * (total_diff - idle_diff)) / total_diff);
    return load;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    gpioSetMode(GPIO_RED, PI_OUTPUT);
    gpioSetMode(GPIO_GREEN, PI_OUTPUT);
    gpioSetMode(GPIO_BLUE, PI_OUTPUT);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!stop) {
        int load = get_cpu_load();
        if (load == -1) {
            continue;
        }

        int red, green, blue;
        if (load < 50) {
            red = 0;
            green = 255;
            blue = 0;
        } else if (load < 100) {
            red = (load - 50) * 5;
            green = 255 - red;
            blue = 0;
        } else {
            red = 255;
            green = 0;
            blue = 0;
        }

        set_led_color(red, green, blue);
        usleep(SAMPLE_INTERVAL);
    }

    set_led_color(0, 0, 0);
    gpioTerminate();
    return 0;
}

