#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define BMP280_I2C_ADDRESS 0x76
#define BMP280_CHIP_ID 0x58
#define BMP280_CALIBRATION_BLOCK_SIZE 24
#define BMP280_MEASUREMENT_REG 0xF7
#define BMP280_CONTROL_REG 0xF4
#define BMP280_MODE_NORMAL 0x03
#define BMP280_MODE_FORCED 0x01
#define BMP280_TEMP_PRESSURE_REG 0xFA
#define BMP280_TEMP_PRESSURE_SIZE 6

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

int main() {
    int i2c_handle, udp_socket;
    struct sockaddr_in server_addr;
    uint8_t chip_id, calibration_block[BMP280_CALIBRATION_BLOCK_SIZE];
    uint8_t measurement[BMP280_TEMP_PRESSURE_SIZE];
    int16_t t_fine;
    double temperature, pressure;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, 0x76, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2cReadByteData(i2c_handle, 0xD0) != BMP280_CHIP_ID) {
        fprintf(stderr, "BMP280 chip ID mismatch\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2cReadBulk(i2c_handle, 0x88, calibration_block, BMP280_CALIBRATION_BLOCK_SIZE) != BMP280_CALIBRATION_BLOCK_SIZE) {
        fprintf(stderr, "Failed to read calibration block\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if ((udp_socket = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        fprintf(stderr, "Failed to create UDP socket\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(5000);
    if (inet_pton(AF_INET, "192.168.1.100", &server_addr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid address/ Address not supported\n");
        close(udp_socket);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!stop_flag) {
        if (i2cWriteByteData(i2c_handle, 0xF4, BMP280_MODE_FORCED) < 0) {
            fprintf(stderr, "Failed to set forced mode\n");
            break;
        }

        while (1) {
            uint8_t status = i2cReadByteData(i2c_handle, 0xF3);
            if (status & 0x08) {
                break;
            }
            usleep(1000);
        }

        if (i2cReadBulk(i2c_handle, 0xFA, measurement, BMP280_TEMP_PRESSURE_SIZE) != BMP280_TEMP_PRESSURE_SIZE) {
            fprintf(stderr, "Failed to read temperature and pressure data\n");
            break;
        }

        // Bosch compensation formulas here
        // ...

        // Convert to JSON and send over UDP
        char json[128];
        snprintf(json, sizeof(json), "{\"temperature\":%.2f,\"pressure\":%.2f}\n", temperature, pressure);
        if (sendto(udp_socket, json, strlen(json), 0, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
            fprintf(stderr, "Failed to send UDP packet\n");
            break;
        }

        sleep(5);
    }

    close(udp_socket);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

