#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define BMP180_I2C_ADDR 0x77
#define BMP180_OVERSAMPLING 3
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_RESULT 0xF6
#define BMP180_REG_CALIB 0xAA

volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
}

int read_i2c(int i2c_handle, uint8_t reg, uint8_t *data, size_t len) {
    if (i2c_read_device(i2c_handle, reg, data, len) != len) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

int write_i2c(int i2c_handle, uint8_t reg, uint8_t data) {
    if (i2c_write_byte_data(i2c_handle, reg, data) < 0) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

int main() {
    int i2c_handle, gpio_handle;
    FILE *log_file;
    uint8_t calib_data[22];
    uint16_t ac1, ac2, ac3, ac4, ac5, ac6, b1, b2, mb, mc, md;
    uint8_t oss = BMP180_OVERSAMPLING;
    uint8_t control_reg = (oss << 6) | 0x2E;
    uint16_t ut, up;
    int32_t x1, x2, x3, b5, b6, b7, p, t;
    time_t now;
    struct tm *tm_info;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if ((gpio_handle = gpioGetFd(2)) < 0) {
        fprintf(stderr, "Failed to get GPIO2 file descriptor\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(gpio_handle, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO2 as input\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(gpio_handle, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set GPIO2 pull-up\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if ((i2c_handle = i2cOpen(1, BMP180_I2C_ADDR, 0)) < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (read_i2c(i2c_handle, BMP180_REG_CALIB, calib_data, sizeof(calib_data)) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ac1 = (calib_data[0] << 8) | calib_data[1];
    ac2 = (calib_data[2] << 8) | calib_data[3];
    ac3 = (calib_data[4] << 8) | calib_data[5];
    ac4 = (calib_data[6] << 8) | calib_data[7];
    ac5 = (calib_data[8] << 8) | calib_data[9];
    ac6 = (calib_data[10] << 8) | calib_data[11];
    b1 = (calib_data[12] << 8) | calib_data[13];
    b2 = (calib_data[14] << 8) | calib_data[15];
    mb = (calib_data[16] << 8) | calib_data[17];
    mc = (calib_data[18] << 8) | calib_data[19];
    md = (calib_data[20] << 8) | calib_data[21];

    if ((log_file = fopen("altitude_log.txt", "w")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    while (running) {
        if (read_i2c(i2c_handle, BMP180_REG_CONTROL, &control_reg, 1) < 0) {
            break;
        }

        if (read_i2c(i2c_handle, BMP180_REG_RESULT, (uint8_t *)&ut, 2) < 0) {
            break;
        }

        if (read_i2c(i2c_handle, BMP180_REG_RESULT, (uint8_t *)&up, 2) < 0) {
            break;
        }

        x1 = ((int32_t)ut - (int32_t)ac6) * ((int32_t)ac5) >> 15;
        x2 = ((int32_t)mc << 11) / (x1 + md);
        b5 = x1 + x2;
        t = (b5 + 8) >> 4;

        x1 = ((int32_t)t) * ((int32_t)t);
        x1 = (x1 * 3038) >> 16;
        x2 = (-7357) * t;
        x2 = (x2 >> 17);
        p = ((int32_t)up - x1 - x2) * 256;

        if (oss == 0) {
            p >>= 4;
        } else if (oss == 1) {
            p >>= 2;
        } else if (oss == 2) {
            p >>= 1;
        }

        time(&now);
        tm_info = localtime(&now);
        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d,%f,%d\n",
                tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
                tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec,
                t / 100.0, p);

        fflush(log_file);
        sleep(1);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

