#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define CS_LINE "gpiochip0::line8"
#define RTD_LOG "rtd_log.csv"
#define SPI_SPEED 1000000
#define SPI_BITS_PER_WORD 8
#define SPI_MODE SPI_MODE_0
#define RTD_MODE 0x00
#define BIAS_ENABLE 0x01
#define FAULT_STATUS 0x02
#define RTD_DATA 0x04
#define MAX31865_ADDRESS 0x00
#define MAX31865_READ_SIZE 4

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    int spidev_fd, log_fd;
    struct gpiod_chip *chip;
    struct gpiod_line *cs_line;
    uint8_t tx_buffer[MAX31865_READ_SIZE] = {MAX31865_ADDRESS | RTD_DATA, 0, 0, 0};
    uint8_t rx_buffer[MAX31865_READ_SIZE];
    uint32_t rtd_value;
    double temperature;
    time_t now;
    struct tm *tm_info;
    char timestamp[20];

    // Open SPI device
    if ((spidev_fd = open(SPI_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    // Set SPI parameters
    if (ioctl(spidev_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spidev_fd);
        return EXIT_FAILURE;
    }
    if (ioctl(spidev_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set bits per word");
        close(spidev_fd);
        return EXIT_FAILURE;
    }
    if (ioctl(spidev_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set max speed HZ");
        close(spidev_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    if ((log_fd = open(RTD_LOG, O_WRONLY | O_CREAT | O_APPEND, 0644)) < 0) {
        perror("Failed to open log file");
        close(spidev_fd);
        return EXIT_FAILURE;
    }

    // Initialize GPIO chip and line
    if ((chip = gpiod_chip_open_by_name("gpiochip0")) == NULL) {
        perror("Failed to open GPIO chip");
        close(spidev_fd);
        close(log_fd);
        return EXIT_FAILURE;
    }
    if ((cs_line = gpiod_chip_get_line(chip, 8)) == NULL) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(spidev_fd);
        close(log_fd);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(cs_line, "RTD_CS", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        close(spidev_fd);
        close(log_fd);
        return EXIT_FAILURE;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize MAX31865
    tx_buffer[0] = MAX31865_ADDRESS | RTD_MODE | BIAS_ENABLE;
    if (write(spidev_fd, tx_buffer, 1) != 1) {
        perror("Failed to write to SPI device");
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        close(spidev_fd);
        close(log_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        // Set CS line low
        if (gpiod_line_set_value(cs_line, 0) < 0) {
            perror("Failed to set CS line low");
            continue;
        }

        // Read RTD data
        if (write(spidev_fd, tx_buffer, 1) != 1) {
            perror("Failed to write to SPI device");
            gpiod_line_set_value(cs_line, 1);
            continue;
        }
        if (read(spidev_fd, rx_buffer, MAX31865_READ_SIZE) != MAX31865_READ_SIZE) {
            perror("Failed to read from SPI device");
            gpiod_line_set_value(cs_line, 1);
            continue;
        }

        // Set CS line high
        if (gpiod_line_set_value(cs_line, 1) < 0) {
            perror("Failed to set CS line high");
            continue;
        }

        // Check fault status
        if (rx_buffer[0] & 0x01) {
