#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>

#define BME280_I2C_ADDR 0x76
#define BME280_CHIP_ID 0x60
#define BME280_REG_CHIP_ID 0xD0
#define BME280_REG_TEMP_MSB 0xFA
#define BME280_REG_HUM_MSB 0xF7
#define BME280_REG_PRESS_MSB 0xF5

#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "bme280_log.csv"

int i2c_fd;
FILE *log_fp;

void signal_handler(int signum) {
    if (log_fp) fclose(log_fp);
    if (i2c_fd) close(i2c_fd);
    exit(signum);
}

int read_bme280_reg(int reg, uint8_t *data, size_t len) {
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Failed to write to BME280 register");
        return -1;
    }
    if (read(i2c_fd, data, len) != len) {
        perror("Failed to read from BME280 register");
        return -1;
    }
    return 0;
}

int read_bme280_data(float *temperature, float *humidity, float *pressure) {
    uint8_t data[8];
    if (read_bme280_reg(BME280_REG_TEMP_MSB, data, 3) != 0) return -1;
    if (read_bme280_reg(BME280_REG_HUM_MSB, data + 3, 1) != 0) return -1;
    if (read_bme280_reg(BME280_REG_PRESS_MSB, data + 4, 3) != 0) return -1;

    int32_t temp_raw = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    int32_t hum_raw = (data[3] << 8) | data[4];
    int32_t press_raw = (data[5] << 12) | (data[6] << 4) | (data[7] >> 4);

    *temperature = (temp_raw / 16384.0) * 100.0;
    *humidity = (hum_raw / 1024.0) * 100.0;
    *pressure = (press_raw / 16384.0) * 100.0;

    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BME280_I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t chip_id;
    if (read_bme280_reg(BME280_REG_CHIP_ID, &chip_id, 1) != 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (chip_id != BME280_CHIP_ID) {
        fprintf(stderr, "BME280 chip ID mismatch: 0x%02X\n", chip_id);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if ((log_fp = fopen(LOG_FILE, "w")) == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    fprintf(log_fp, "timestamp,temperature_C,humidity_percent,pressure_hPa\n");

    while (1) {
        float temperature, humidity, pressure;
        if (read_bme280_data(&temperature, &humidity, &pressure) == 0) {
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            fprintf(log_fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f,%.2f\n",
                    tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
                    tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec,
                    temperature, humidity, pressure);
        }
        fflush(log_fp);
        sleep(5);
    }

    fclose(log_fp);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

