code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x77
#define BMP180_REG_CALIB 0xAA
#define BMP180_REG_CONTROL 0xF4
#define BMP180_CMD_PRESSURE_ULTRA_LOW_POWER 0x34
#define BMP180_CONVERSION_TIME 5
#define BUFFER_SIZE 120
#define SAMPLE_INTERVAL 50
#define ALERT_THRESHOLD 5.0

typedef struct {
    uint16_t AC1, AC2, AC3, AC4, AC5, AC6;
    int16_t B1, B2, MB, MC, MD;
} CalibrationData;

typedef struct {
    uint32_t timestamp;
    float pressure;
} DataPoint;

volatile int running = 1;
volatile DataPoint buffer[BUFFER_SIZE];
volatile int buffer_head = 0;
volatile int buffer_tail = 0;
volatile int buffer_count = 0;
volatile int alert_pin = 24;
volatile int i2c_handle = -1;

void signal_handler(int sig) {
    running = 0;
}

void log_error(const char *message) {
    fprintf(stderr, "ERROR: %s\n", message);
}

void log_alert(const char *message) {
    fprintf(stderr, "ALERT: %s\n", message);
}

void init_pigpio() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio");
        exit(EXIT_FAILURE);
    }
}

void init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }
}

void init_gpio() {
    if (gpioSetMode(alert_pin, PI_OUTPUT) < 0) {
        log_error("Failed to set GPIO mode");
        exit(EXIT_FAILURE);
    }
    gpioWrite(alert_pin, 0);
}

void read_calibration(CalibrationData *calibration) {
    uint8_t data[22];
    if (i2cReadBlockData(i2c_handle, BMP180_REG_CALIB, data, 22) != 22) {
        log_error("Failed to read calibration data");
        exit(EXIT_FAILURE);
    }
    calibration->AC1 = (data[0] << 8) | data[1];
    calibration->AC2 = (data[2] << 8) | data[3];
    calibration->AC3 = (data[4] << 8) | data[5];
    calibration->AC4 = (data[6] << 8) | data[7];
    calibration->AC5 = (data[8] << 8) | data[9];
    calibration->AC6 = (data[10] << 8) | data[11];
    calibration->B1 = (data[12] << 8) | data[13];
    calibration->B2 = (data[14] << 8) | data[15];
    calibration->MB = (data[16] << 8) | data[17];
    calibration->MC = (data[18] << 8) | data[19];
    calibration->MD = (data[20] << 8) | data[21];
}

float read_pressure(CalibrationData *calibration) {
    uint8_t data[3];
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, BMP180_CMD_PRESSURE_ULTRA_LOW_POWER) < 0) {
        log_error("Failed to start pressure conversion");
        return -1.0;
    }
    gpioDelay(5000);
    if (i2cReadBlockData(i2c_handle, 0xF6, data, 3) != 3) {
        log_error("Failed to read pressure data");
        return -1.0;
    }
    uint32_t adc = (data[0] << 16) | (data[1] << 8) | data[2];
    int32_t UT = adc;
    int32_t X1 = ((UT - calibration->AC6) * calibration->AC5) >> 15;
    int32_t X2 = (calibration->MC << 11) / (X1 + calibration->MD);
    int32_t B5 = X1 + X2;
    int32_t B6 = B5 - 4000;
    int32_t X3 = ((calibration->B2 * (B6 * B6) >> 12) >> 11);
    int32_t X4 = ((calibration->AC2 * B6) >> 11);
    int32_t X5 = ((X3 + X4) << 1) + 2;
    int32_t B3 = (((calibration->AC1 * 4 + X5) << 1) / 8);
    X1 = ((calibration->AC3 * B6) >> 13);
    X2 = ((calibration->B1 * (B6 * B6) >> 12)) >> 16;
    int32_t X4 = ((X1 + X2) + 2) >> 2;
    int32_t B4 = (B3 + X4) / 4096;
    int32_t B7 = (adc - B3) * 4096 / B4;
    X1 = ((calibration->B2 * (B7 * B7) >> 12) >> 11);
    X2 = ((calibration->AC2 * B7) >> 11);
    X3 = ((X1 + X2) + 2) >> 2;
    int32_t P = (B7 + X3) / 16;
    return P / 100.0;
}

void log_data(DataPoint *data) {
    printf("Timestamp: %ld, Pressure: %.2f hPa\n", data->timestamp, data->pressure);
}

void alert_if_needed(DataPoint *data) {
    if (buffer_count >= BUFFER_SIZE) {
        float sum = 0.0;
        for (int i = 0; i < BUFFER_SIZE; i++) {
            sum += buffer[(buffer_head + i) % BUFFER_SIZE].pressure;
        }
        float average = sum / BUFFER_SIZE;
        if (fabs(data->pressure - average) > ALERT_THRESHOLD) {
            gpioWrite(alert_pin, 1);
            log_alert("Pressure deviation detected");
        } else {
            gpioWrite(alert_pin, 0);
        }
    }
}

void timer_callback(void *userdata) {
    if (!running) return;
    DataPoint data;
    data.timestamp = time(NULL);
    data.pressure = read_pressure(&calibration);
    if (data.pressure >= 0.0) {
        buffer[buffer_head] = data;
        buffer_head = (buffer_head + 1) % BUFFER_SIZE;
        buffer_count = (buffer_count < BUFFER_SIZE) ? buffer_count + 1 : BUFFER_SIZE;
        log_data(&data);
        alert_if_needed(&data);
    }
}

int main() {
    CalibrationData calibration;
    signal(SIGINT, signal_handler);
    init_pigpio();
    init_i2c();
    init_gpio();
    read_calibration(&calibration);
    gpioSetTimerFuncEx(0, SAMPLE_INTERVAL, timer_callback, NULL);
    while (running) {
        gpioDelay(100000);
    }
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

