    calibration->B1 = (data[12] << 8) | data[13];
    calibration->B2 = (data[14] << 8) | data[15];
    calibration->MB = (data[16] << 8) | data[17];
    calibration->MC = (data[18] << 8) | data[19];
    calibration->MD = (data[20] << 8) | data[21];
}

float read_pressure(CalibrationData *calibration) {
    uint8_t data[3];
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, BMP180_CMD_PRESSURE_ULTRA_LOW_POWER) < 0) {
        log_error("Failed to start pressure conversion");
        return -1.0;
    }
    gpioDelay(5000);
    if (i2cReadBlockData(i2c_handle, 0xF6, data, 3) != 3) {
        log_error("Failed to read pressure data");
        return -1.0;
    }
    uint32_t adc = (data[0] << 16) | (data[1] << 8) | data[2];
    int32_t UT = adc;
    int32_t X1 = ((UT - calibration->AC6) * calibration->AC5) >> 15;
    int32_t X2 = (calibration->MC << 11) / (X1 + calibration->MD);
    int32_t B5 = X1 + X2;
    int32_t B6 = B5 - 4000;
    int32_t X3 = ((calibration->B2 * (B6 * B6) >> 12) >> 11);
    int32_t X4 = ((calibration->AC2 * B6) >> 11);
    int32_t X5 = ((X3 + X4) << 1) + 2;
    int32_t B3 = (((calibration->AC1 * 4 + X5) << 1) / 8);
    X1 = ((calibration->AC3 * B6) >> 13);
    X2 = ((calibration->B1 * (B6 * B6) >> 12)) >> 16;
    int32_t X4 = ((X1 + X2) + 2) >> 2;
    int32_t B4 = (B3 + X4) / 4096;
    int32_t B7 = (adc - B3) * 4096 / B4;
    X1 = ((calibration->B2 * (B7 * B7) >> 12) >> 11);
    X2 = ((calibration->AC2 * B7) >> 11);
    X3 = ((X1 + X2) + 2) >> 2;
    int32_t P = (B7 + X3) / 16;
    return P / 100.0;
}

void log_data(DataPoint *data) {
    printf("Timestamp: %ld, Pressure: %.2f hPa\n", data->timestamp, data->pressure);
}

void alert_if_needed(DataPoint *data) {
    if (buffer_count >= BUFFER_SIZE) {
        float sum = 0.0;
        for (int i = 0; i < BUFFER_SIZE; i++) {
            sum += buffer[(buffer_head + i) % BUFFER_SIZE].pressure;
        }
        float average = sum / BUFFER_SIZE;
        if (fabs(data->pressure - average) > ALERT_THRESHOLD) {
            gpioWrite(alert_pin, 1);
            log_alert("Pressure deviation detected");
        } else {
            gpioWrite(alert_pin, 0);
        }
    }
}

void timer_callback(void *userdata) {
    if (!running) return;
    DataPoint data;
    data.timestamp = time(NULL);
    data.pressure = read_pressure(&calibration);
    if (data.pressure >= 0.0) {
        buffer[buffer_head] = data;
        buffer_head = (buffer_head + 1) % BUFFER_SIZE;
        buffer_count = (buffer_count < BUFFER_SIZE) ? buffer_count + 1 : BUFFER_SIZE;
        log_data(&data);
        alert_if_needed(&data);
    }
}

int main() {
    CalibrationData calibration;
    signal(SIGINT, signal_handler);
    init_pigpio();
    init_i2c();
    init_gpio();
    read_calibration(&calibration);
    gpioSetTimerFuncEx(0, SAMPLE_INTERVAL, timer_callback, NULL);
    while (running) {
        gpioDelay(100000);
    }
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}
```

This code provides a complete solution for sampling a BMP180 pressure sensor over I2C bus 1 at address 0x77 every 50 ms using a pigpio hardware timer. It logs timestamped pressure readings to a circular buffer and triggers an alert on GPIO24 if the current pressure deviates by more than 5 hPa from the rolling average of the last 60 seconds. The code includes robust error handling for I2C failures and sensor absence, and logs alerts and errors to stderr. It ensures clean resource release on SIGINT by closing the I2C handle, resetting GPIO, and terminating pigpio.

