#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define FAN_PIN 18
#define PWM_FREQ 25000
#define MIN_TEMP 40000
#define MAX_TEMP 70000
#define DUTY_RANGE 255
#define LOG_INTERVAL 5

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

int read_cpu_temp() {
    FILE *fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (!fp) {
        perror("Failed to open temperature file");
        return -1;
    }
    int temp;
    if (fscanf(fp, "%d", &temp) != 1) {
        perror("Failed to read temperature");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return temp;
}

void log_data(int temp, int duty) {
    FILE *log = fopen("fan_log.txt", "a");
    if (!log) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(log, "%s, Temp: %d°C, Duty: %d\n", asctime(tm_info), temp / 1000, duty);
    fclose(log);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(FAN_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(FAN_PIN, PWM_FREQ);
    gpioSetPWMrange(FAN_PIN, DUTY_RANGE);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int last_temp = 0;
    int last_duty = 0;

    while (!stop_flag) {
        int temp = read_cpu_temp();
        if (temp == -1) {
            sleep(LOG_INTERVAL);
            continue;
        }

        int duty = 0;
        if (temp < MIN_TEMP) {
            duty = 0;
        } else if (temp > MAX_TEMP) {
            duty = DUTY_RANGE;
        } else {
            duty = (temp - MIN_TEMP) * DUTY_RANGE / (MAX_TEMP - MIN_TEMP);
        }

        if (duty != last_duty) {
            gpioSetPWMdutycycle(FAN_PIN, duty);
            last_duty = duty;
        }

        if (temp != last_temp) {
            log_data(temp, duty);
            last_temp = temp;
        }

        sleep(LOG_INTERVAL);
    }

    gpioSetPWMdutycycle(FAN_PIN, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

