#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define BMP280_I2C_ADDR1 0x76
#define BMP280_I2C_ADDR2 0x77
#define BMP280_CHIP_ID 0x58
#define BMP280_CALIB_START 0x88
#define BMP280_CTRL_MEAS 0xF4
#define BMP280_STATUS 0xF3
#define BMP280_PRESS_MSB 0xF7
#define BMP280_MEAS_INTERVAL 5

volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

int main() {
    int fd;
    char *bus = I2C_BUS;
    uint8_t addr = BMP280_I2C_ADDR1;
    uint8_t chip_id;
    uint8_t calib[24];
    uint8_t ctrl_meas = 0x27; // Forced mode, x1 oversampling
    uint8_t status;
    uint8_t data[6];
    int32_t dig_T1, dig_T2, dig_T3, dig_P1, dig_P2, dig_P3, dig_P4, dig_P5, dig_P6, dig_P7, dig_P8, dig_P9;
    int32_t t_fine;
    int32_t adc_T, adc_P;
    float temperature, pressure;
    FILE *log_file;
    struct tm *tm_info;
    char timestamp[20];

    // Open I2C bus
    if ((fd = open(bus, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return EXIT_FAILURE;
    }

    // Read chip ID
    if (read(fd, &chip_id, 1) != 1) {
        perror("Failed to read chip ID");
        close(fd);
        return EXIT_FAILURE;
    }

    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "Invalid chip ID: 0x%02X\n", chip_id);
        close(fd);
        return EXIT_FAILURE;
    }

    // Read calibration data
    if (read(fd, calib, sizeof(calib)) != sizeof(calib)) {
        perror("Failed to read calibration data");
        close(fd);
        return EXIT_FAILURE;
    }

    // Extract calibration values
    dig_T1 = (calib[1] << 8) | calib[0];
    dig_T2 = (calib[3] << 8) | calib[2];
    dig_T3 = (calib[5] << 8) | calib[4];
    dig_P1 = (calib[7] << 8) | calib[6];
    dig_P2 = (calib[9] << 8) | calib[8];
    dig_P3 = (calib[11] << 8) | calib[10];
    dig_P4 = (calib[13] << 8) | calib[12];
    dig_P5 = (calib[15] << 8) | calib[14];
    dig_P6 = (calib[17] << 8) | calib[16];
    dig_P7 = (calib[19] << 8) | calib[18];
    dig_P8 = (calib[21] << 8) | calib[20];
    dig_P9 = (calib[23] << 8) | calib[22];

    // Set up signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    // Open log file
    if ((log_file = fopen("weather_data.txt", "a")) == NULL) {
        perror("Failed to open log file");
        close(fd);
        return EXIT_FAILURE;
    }

    while (running) {
        // Write control measurement register
        if (write(fd, &ctrl_meas, 1) != 1) {
            perror("Failed to write control measurement register");
            running = 0;
        }

        // Wait for measurement to complete
        int timeout = 100;
        while (timeout--) {
            if (read(fd, &status, 1) != 1) {
                perror("Failed to read status register");
                running = 0;
                break;
            }
            if (!(status & 0x08)) {
                break;
            }
            usleep(1000);
        }

        if (timeout == 0) {
            fprintf(stderr, "Measurement timeout\n");
            running = 0;
            continue;
        }

        // Read raw data
        if (read(fd, data, sizeof(data)) != sizeof(data)) {
            perror("Failed to read raw data");
            running = 0;
            continue;
        }

        // Convert raw data to 20-bit values
        adc_T = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | (data[5] >> 4);
        adc_P = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | (data[2] >> 4);

        // Compensate temperature
        int32_t var1, var2, var3;
        var1 = ((adc_T >> 3) - ((int32_t)dig_T1 << 1)) * ((int32_t)dig_T2 >> 11);
        var2 = (((adc_T >> 4) - ((int32_t)dig_T1)) * ((adc_T >> 4) - ((int32_t)dig_T1))) >> 12;
        var2 = ((var2 * (int32_t)dig_T3) >> 14);
        t_fine = var1 + var2;
        temperature = (t_fine * 5 + 128) >> 8;

        // Compensate pressure
        var1 = ((t_fine >> 1) - 64000);
        var2 = var1 * var1 * ((int32_t)dig_P6) >> 19;
        var2 = var2 + var1 * ((int32_t)dig_P5) << 7;
        var2 = (var2 >> 4) + ((int32_t)dig_P4) * 65536;
        var3 = ((dig_P3 * var1 * var1) >> 15) + ((dig_P2 * var1) >> 17);
        var3 = ((32768 + var3) << 15) / (var3 + dig_P1);
        pressure = 1048576 - adc_P;
        pressure = ((pressure - (var3 >> 12)) * 3125) / var3;
        var1 = ((int32_t)dig_P9 * (pressure >> 13) * (pressure >> 13)) >> 25;
        var2 = ((int32_t)dig_P8 * pressure) >> 19;
        pressure = ((pressure + var1 + var2) >> 8) + ((int32_t)dig_P7 << 4);

        // Log data
        time_t now = time(NULL);
        tm_info = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
        fprintf(log_file, "%s, Temperature: %.2f °C, Pressure: %.2f hPa\n", timestamp, temperature / 100.0, pressure / 100.0);
        fflush(log_file);

        // Sleep for 5 seconds
        sleep(BMP280_MEAS_INTERVAL);
    }

    // Clean up
    fclose(log_file);
    close(fd);
    return EXIT_SUCCESS;
}

