#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <gpiod.h>
#include <sys/time.h>

#define I2C_BUS "1"
#define I2C_ADDR 0x48
#define LED_PIN 18
#define BUFFER_SIZE 60
#define REINIT_DELAY 5

struct circular_buffer {
    int16_t data[BUFFER_SIZE];
    int head;
    int count;
    pthread_mutex_t mutex;
};

struct circular_buffer cb;

void init_circular_buffer() {
    memset(&cb, 0, sizeof(cb));
    pthread_mutex_init(&cb.mutex, NULL);
}

void add_to_buffer(int16_t value) {
    pthread_mutex_lock(&cb.mutex);
    cb.data[cb.head] = value;
    cb.head = (cb.head + 1) % BUFFER_SIZE;
    if (cb.count < BUFFER_SIZE) {
        cb.count++;
    }
    pthread_mutex_unlock(&cb.mutex);
}

int16_t get_average() {
    pthread_mutex_lock(&cb.mutex);
    int16_t sum = 0;
    for (int i = 0; i < cb.count; i++) {
        sum += cb.data[i];
    }
    int16_t average = cb.count > 0 ? sum / cb.count : 0;
    pthread_mutex_unlock(&cb.mutex);
    return average;
}

void* read_temperature(void* arg) {
    struct gpiod_chip* chip = NULL;
    struct gpiod_line* led_line = NULL;
    int fd = -1;
    int16_t temperature = 0;
    int16_t last_average = 0;

    while (1) {
        if (fd == -1) {
            fd = open("/dev/i2c-1", O_RDWR);
            if (fd == -1) {
                perror("Failed to open I2C bus");
                sleep(REINIT_DELAY);
                continue;
            }

            if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
                perror("Failed to set I2C address");
                close(fd);
                fd = -1;
                sleep(REINIT_DELAY);
                continue;
            }

            chip = gpiod_chip_open_by_name("gpiochip0");
            if (!chip) {
                fprintf(stderr, "Failed to open GPIO chip\n");
                close(fd);
                fd = -1;
                sleep(REINIT_DELAY);
                continue;
            }

            led_line = gpiod_chip_get_line(chip, LED_PIN);
            if (!led_line) {
                fprintf(stderr, "Failed to get GPIO line\n");
                gpiod_chip_close(chip);
                close(fd);
                fd = -1;
                sleep(REINIT_DELAY);
                continue;
            }

            if (gpiod_line_request_output(led_line, "temperature_led", 0) < 0) {
                fprintf(stderr, "Failed to request GPIO line\n");
                gpiod_line_release(led_line);
                gpiod_chip_close(chip);
                close(fd);
                fd = -1;
                sleep(REINIT_DELAY);
                continue;
            }
        }

        uint8_t buffer[2];
        if (read(fd, buffer, 2) != 2) {
            fprintf(stderr, "Failed to read from I2C device\n");
            gpiod_line_release(led_line);
            gpiod_chip_close(chip);
            close(fd);
            fd = -1;
            sleep(REINIT_DELAY);
            continue;
        }

        temperature = (buffer[0] << 8) | buffer[1];
        temperature >>= 5;

        add_to_buffer(temperature);
        int16_t average = get_average();

        if (average > 2800) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }

        if (average != last_average) {
            printf("Average temperature: %.2f°C\n", average / 256.0);
            last_average = average;
        }

        sleep(1);
    }

    return NULL;
}

