#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <json-c/json.h>

#define GPIO_PWM 18
#define SPI_CHANNEL 0
#define SPI_CE 0
#define SPI_SPEED 500000
#define PWM_FREQ 1000
#define PWM_RANGE 1000
#define MAX_TEMP 80.0
#define RTD_REF 430.0
#define RTD_NOMINAL 100.0
#define RTD_A 3.9083e-3
#define RTD_B -5.775e-7
#define RTD_C 2.1792e-12
#define CONFIG_FILE "config.json"

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

double read_temperature(int spi_fd) {
    uint8_t tx[2] = {0x01, 0x02};
    uint8_t rx[2];
    if (pigpio_spi_xfer(spi_fd, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI read failed\n");
        exit(EXIT_FAILURE);
    }
    uint16_t rtd_code = (rx[0] << 8) | rx[1];
    if (rtd_code & 0x01) {
        fprintf(stderr, "RTD fault detected\n");
        exit(EXIT_FAILURE);
    }
    double rtd_resistance = (rtd_code / 32768.0) * RTD_REF;
    double temperature = 0.0;
    if (rtd_resistance > RTD_NOMINAL) {
        double delta = rtd_resistance - RTD_NOMINAL;
        temperature = RTD_A * delta + RTD_B * delta * delta + RTD_C * delta * delta * delta;
    }
    return temperature;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int spi_fd = pigpio_spi_open(SPI_CHANNEL, SPI_SPEED, SPI_CE);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (pigpio_spi_write(spi_fd, 0x80, 0xC1) != 1) {
        fprintf(stderr, "SPI write failed\n");
        pigpio_spi_close(spi_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    json_object *config = json_object_from_file(CONFIG_FILE);
    double target_temp = 25.0, Kp = 1.0, Ki = 0.1, Kd = 0.01;
    if (config) {
        json_object_object_get_ex(config, "target_temp", &json_target_temp);
        json_object_object_get_ex(config, "Kp", &json_Kp);
        json_object_object_get_ex(config, "Ki", &json_Ki);
        json_object_object_get_ex(config, "Kd", &json_Kd);
        target_temp = json_object_get_double(json_target_temp);
        Kp = json_object_get_double(json_Kp);
        Ki = json_object_get_double(json_Ki);
        Kd = json_object_get_double(json_Kd);
        json_object_put(config);
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gpioSetMode(GPIO_PWM, PI_OUTPUT);
    gpioSetPWMfrequency(GPIO_PWM, PWM_FREQ);
    gpioSetPWMrange(GPIO_PWM, PWM_RANGE);

    double integral = 0.0, last_error = 0.0;
    while (running) {
        double current_temp = read_temperature(spi_fd);
        if (current_temp > MAX_TEMP) {
            gpioSetPWMduty(GPIO_PWM, 0);
            fprintf(stderr, "Temperature exceeded %f°C, shutting down\n", MAX_TEMP);
            break;
        }
        double error = target_temp - current_temp;
        integral += error;
        double derivative = error - last_error;
        last_error = error;
        double duty_cycle = Kp * error + Ki * integral + Kd * derivative;
        duty_cycle = fmax(0.0, fmin(100.0, duty_cycle));
        gpioSetPWMduty(GPIO_PWM, (int)(duty_cycle * PWM_RANGE / 100.0));
        usleep(100000);
    }

    gpioSetPWMduty(GPIO_PWM, 0);
    pigpio_spi_close(spi_fd);
    gpioTerminate();
    return EXIT_SUCCESS;
}

