int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO mode for fan\n");
        gpioTerminate();
        return 1;
    }

    int i2c_handle = i2cOpen(1, BMP180_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        gpioTerminate();
        return 1;
    }

    i2c_read_calib(i2c_handle);
    if (calib.ac1 == 0 || calib.ac2 == 0 || calib.ac3 == 0 || calib.ac4 == 0 || calib.ac5 == 0 || calib.ac6 == 0 ||
        calib.b1 == 0 || calib.b2 == 0 || calib.mb == 0 || calib.mc == 0 || calib.md == 0) {
        fprintf(stderr, "Failed to read valid BMP180 calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gpioSetTimerFunc(0, SAMPLE_INTERVAL, timer_callback, NULL);

    while (running) {
        gpioDelay(100000);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}
