#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_ADDRESS 0x77
#define GPIO_PIN 27
#define DEBOUNCE_TIME 200
#define LOG_INTERVAL 2

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set GPIO%d pull-up\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(GPIO_PIN, [](unsigned gpio, unsigned level, uint32_t tick, void *userdata) {
        static uint32_t last_tick = 0;
        uint32_t current_tick = gpioTick();

        if (level == 0 && (current_tick - last_tick) > DEBOUNCE_TIME) {
            last_tick = current_tick;
            FILE *log_file = fopen("pressure_log.txt", "a");
            if (log_file == NULL) {
                fprintf(stderr, "Failed to open log file\n");
                return;
            }

            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

            int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
            uint16_t ac4, ac5, ac6;
            uint8_t data[22];

            if (i2cReadDevice(1, I2C_ADDRESS, data, 22) != 22) {
                fprintf(stderr, "Failed to read BMP180 calibration data\n");
                fclose(log_file);
                return;
            }

            ac1 = (data[0] << 8) | data[1];
            ac2 = (data[2] << 8) | data[3];
            ac3 = (data[4] << 8) | data[5];
            ac4 = (data[6] << 8) | data[7];
            ac5 = (data[8] << 8) | data[9];
            ac6 = (data[10] << 8) | data[11];
            b1 = (data[12] << 8) | data[13];
            b2 = (data[14] << 8) | data[15];
            mb = (data[16] << 8) | data[17];
            mc = (data[18] << 8) | data[19];
            md = (data[20] << 8) | data[21];

            uint8_t msb, lsb, xlsb;
            if (i2cReadDevice(1, I2C_ADDRESS, &msb, 1) != 1 ||
                i2cReadDevice(1, I2C_ADDRESS, &lsb, 1) != 1 ||
                i2cReadDevice(1, I2C_ADDRESS, &xlsb, 1) != 1) {
                fprintf(stderr, "Failed to read BMP180 pressure data\n");
                fclose(log_file);
                return;
            }

            int32_t ut = ((msb << 16) | (lsb << 8) | xlsb) >> 4;
            int32_t x1 = ((ut - ac6) * ac5) >> 15;
            int32_t x2 = (mc << 11) / (x1 + md);
            int32_t b5 = x1 + x2;
            int32_t b6 = b5 - 4000;
            int32_t x3 = ((b2 * (b6 * b6) >> 12) >> 11);
            int32_t x4 = ((ac2 * b6) >> 11);
            int32_t x5 = ((x3 + x4) * 2) >> 1;
            int32_t b3 = (((ac1 * 4 + x5) << 2) + 2) >> 2;
            int32_t x6 = b2 * (b6 * b6) >> 12;
            int32_t x7 = (x6 + 2) >> 2;
            int32_t p = ((b3 + x7) >> 4);

            fprintf(log_file, "%s: %d Pa\n", timestamp, p);
            fclose(log_file);
        }
    }, NULL) < 0) {
        fprintf(stderr, "Failed to set GPIO%d alert function\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        sleep(LOG_INTERVAL);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

