int read_max31855() {
    uint8_t tx[4] = {0x00, 0x00, 0x00, 0x00};
    uint8_t rx[4];
    int status = spi_xfer(SPI_CHANNEL, tx, rx, 4);
    if (status < 0) {
        fprintf(stderr, "SPI read failed: %s\n", strerror(status));
        return -1;
    }
    uint32_t thermocouple_data = ((uint32_t)rx[0] << 16) | ((uint32_t)rx[1] << 8) | (uint32_t)rx[2];
    uint32_t fault = thermocouple_data & 0x00000008;
    if (fault) {
        fprintf(stderr, "MAX31855 fault detected\n");
        return -1;
    }
    uint32_t thermocouple_temp = (thermocouple_data >> 4) & 0x3FFF;
