int read_max31855() {
    uint8_t tx[4] = {0x00, 0x00, 0x00, 0x00};
    uint8_t rx[4];
    int status = spi_xfer(SPI_CHANNEL, tx, rx, 4);
    if (status < 0) {
        fprintf(stderr, "SPI read failed: %s\n", strerror(status));
        return -1;
    }
    uint32_t thermocouple_data = ((uint32_t)rx[0] << 16) | ((uint32_t)rx[1] << 8) | (uint32_t)rx[2];
    uint32_t fault = thermocouple_data & 0x00000008;
    if (fault) {
        fprintf(stderr, "MAX31855 fault detected\n");
        return -1;
    }
    uint32_t thermocouple_temp = (thermocouple_data >> 4) & 0x3FFF;
    return thermocouple_temp;
}

double calculate_pi_control(double current_temp, double setpoint, double prev_error, double *integral, double dt) {
    double error = setpoint - current_temp;
    *integral += error * dt;
    double derivative = (error - prev_error) / dt;
    double output = 0.5 * (error + derivative); // Simplified PI controller
    if (output > MAX_DUTY_CYCLE) {
        output = MAX_DUTY_CYCLE;
    } else if (output < 0) {
        output = 0;
    }
    return output;
}

