#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <curl/curl.h>

#define DHT22_PIN 4
#define MAX_RETRIES 3
#define SERVER_URL "http://yourserver.com/api/humidity"

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

size_t write_callback(void *ptr, size_t size, size_t nmemb, void *userdata) {
    return size * nmemb;
}

int read_dht22(int pin) {
    int data[5] = {0};
    int i, j, sum = 0;
    int bit = 0;
    int state = 0;
    int last_state = 0;
    int count = 0;
    int last_time = 0;
    int current_time = 0;

    gpioSetMode(pin, PI_INPUT);
    gpioSetPullUpDown(pin, PI_PUD_UP);
    gpioDelay(500000); // 500ms
    gpioSetMode(pin, PI_OUTPUT);
    gpioWrite(pin, 0);
    gpioDelay(1000); // 1ms
    gpioSetMode(pin, PI_INPUT);
    gpioSetPullUpDown(pin, PI_PUD_UP);

    for (i = 0; i < 40; i++) {
        while (gpioRead(pin) == last_state) {
            gpioDelay(1);
        }
        last_state = gpioRead(pin);
        current_time = gpioTick();
        if (current_time - last_time > 10000) {
            bit = 1;
        } else {
            bit = 0;
        }
        data[i / 8] <<= 1;
        data[i / 8] |= bit;
        last_time = current_time;
    }

    for (i = 0; i < 4; i++) {
        sum += data[i];
    }

    if (data[4] != sum) {
        return -1;
    }

    return data[0];
}

int send_data(int humidity, int temperature) {
    CURL *curl;
    CURLcode res;
    char post_data[256];

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if(curl) {
        snprintf(post_data, sizeof(post_data), "{\"humidity\":%d,\"temperature\":%d}", humidity, temperature);
        curl_easy_setopt(curl, CURLOPT_URL, SERVER_URL);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, post_data);
        res = curl_easy_perform(curl);
        if(res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
            return -1;
        }
        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();
    return 0;
}

int main() {
    int humidity, temperature;
    int retries = 0;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    while (!stop_flag) {
        humidity = read_dht22(DHT22_PIN);
        if (humidity < 0) {
            retries++;
            if (retries >= MAX_RETRIES) {
                fprintf(stderr, "Failed to read DHT22 sensor after %d retries\n", MAX_RETRIES);
                break;
            }
            gpioDelay(2000000); // 2s
            continue;
        }
        retries = 0;

        temperature = humidity; // Assuming temperature is the same as humidity for simplicity

        if (send_data(humidity, temperature) < 0) {
            retries++;
            if (retries >= MAX_RETRIES) {
                fprintf(stderr, "Failed to send data to server after %d retries\n", MAX_RETRIES);
                break;
            }
            gpioDelay(2000000); // 2s
            continue;
        }
        retries = 0;

        gpioDelay(2000000); // 2s
    }

    gpioTerminate();
    return 0;
}

