#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define BMP180_I2C_ADDR 0x77
#define BMP180_I2C_BUS 1
#define BMP180_REG_CALIB 0xAA
#define BMP180_REG_CTRL_MEAS 0xF4
#define BMP180_REG_DATA 0xF6
#define BMP180_OSS 3
#define BMP180_CONVERSION_DELAY 26000
#define DEBOUNCE_US 200000
#define LOG_INTERVAL 2000000

volatile int logging = 0;
volatile uint32_t last_interrupt_time = 0;

void gpio_callback(int gpio, int level, uint32_t tick) {
    if (level == PI_TIMEOUT) {
        return;
    }

    uint32_t current_time = gpioTick();
    if (current_time - last_interrupt_time < DEBOUNCE_US) {
        return;
    }

    last_interrupt_time = current_time;

    if (logging) {
        printf("Logging disabled\n");
    } else {
        printf("Logging enabled\n");
    }

    logging = !logging;
}

int read_bmp180_calib(int i2c_handle, int16_t *calib) {
    uint8_t buf[22];
    if (i2cReadDevice(i2c_handle, BMP180_I2C_ADDR, buf, 22) != 22) {
        fprintf(stderr, "Failed to read BMP180 calibration data\n");
        return -1;
    }

    for (int i = 0; i < 11; i++) {
        calib[i] = (int16_t)((buf[i * 2] << 8) | buf[i * 2 + 1]);
    }

    return 0;
}

int read_bmp180_pressure(int i2c_handle, int16_t *calib, uint32_t *pressure) {
    uint8_t cmd = 0xF4 | (BMP180_OSS << 6);
    if (i2cWriteDevice(i2c_handle, BMP180_I2C_ADDR, &cmd, 1) != 1) {
        fprintf(stderr, "Failed to send BMP180 measurement command\n");
        return -1;
    }

    gpioDelay(BMP180_CONVERSION_DELAY);

    uint8_t buf[3];
    if (i2cReadDevice(i2c_handle, BMP180_I2C_ADDR, buf, 3) != 3) {
        fprintf(stderr, "Failed to read BMP180 pressure data\n");
        return -1;
    }

    uint32_t up = ((uint32_t)buf[0] << 16) | ((uint32_t)buf[1] << 8) | buf[2];

    int32_t ut = (int32_t)up;
    int32_t x1, x2, b5, b6, x3, b3, p;

    x1 = ((ut - calib[0]) * calib[1]) >> 15;
    x2 = (calib[2] << 11) / (x1 + calib[3]);
    b5 = x1 + x2;

    b6 = b5 - 4000;
    x1 = (calib[4] * ((b6 * b6) >> 12)) >> 11;
    x2 = calib[5] * (b6 >> 11);
    x3 = x1 + x2;
    b3 = (((calib[6] << 7) + x3) << 1) / (b5 + 32768);

    p = (b3 + 5) >> 1;

    *pressure = p;
    return 0;
}

void signal_handler(int sig) {
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    int i2c_handle = i2cOpen(BMP180_I2C_BUS, BMP180_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    int16_t calib[11];
    if (read_bmp180_calib(i2c_handle, calib) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(4, PI_INPUT);
    gpioSetPullUpDown(4, PI_PUD_UP);
    gpioSetAlertFunc(4, gpio_callback);

    uint32_t last_log_time = 0;

    while (1) {
        if (logging) {
            uint32_t pressure;
            if (read_bmp180_pressure(i2c_handle, calib, &pressure) == 0) {
                time_t now = time(NULL);
                struct tm *tm = localtime(&now);
                printf("%04d-%02d-%02d %02d:%02d:%02d.%03d: Pressure: %u hPa\n",
                       tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
                       tm->tm_hour, tm->tm_min, tm->tm_sec, (int)(now * 1000) % 1000,
                       pressure);
            }
        }

        if (gpioTick() - last_log_time >= LOG_INTERVAL) {
            last_log_time = gpioTick();
        }

        gpioDelay(10000);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

