#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <curl/curl.h>

#define DHT22_PIN 4
#define DHT22_START_SIGNAL_US 1000
#define DHT22_RESPONSE_SIGNAL_US 20
#define DHT22_TIMEOUT_US 100000
#define MAX_RETRIES 3
#define RETRY_DELAY_S 2
#define DEFAULT_SERVER_URL "http://your-server.com/api/humidity"
#define JSON_TEMPLATE "{\"humidity\":%.1f}"

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

size_t write_callback(void *ptr, size_t size, size_t nmemb, void *userdata) {
    return size * nmemb;
}

int read_dht22(float *humidity) {
    int status = gpioWrite(DHT22_PIN, PI_LOW);
    if (status != 0) {
        syslog(LOG_ERR, "Failed to pull DHT22 pin low: %d", status);
        return -1;
    }

    gpioDelay(DHT22_START_SIGNAL_US);

    status = gpioWrite(DHT22_PIN, PI_HIGH);
    if (status != 0) {
        syslog(LOG_ERR, "Failed to pull DHT22 pin high: %d", status);
        return -1;
    }

    gpioDelay(DHT22_RESPONSE_SIGNAL_US);

    int data[40] = {0};
    int index = 0;
    int bit = 0;
    int last_state = gpioRead(DHT22_PIN);
    int start_time = gpioTick();

    while (index < 40) {
        int current_state = gpioRead(DHT22_PIN);
        int current_time = gpioTick();
        int duration = current_time - start_time;

        if (duration > DHT22_TIMEOUT_US) {
            syslog(LOG_ERR, "DHT22 read timed out");
            return -1;
        }

        if (current_state != last_state) {
            if (duration > 2 * DHT22_RESPONSE_SIGNAL_US) {
                data[index] |= (1 << bit);
            }
            bit++;
            if (bit == 8) {
                index++;
                bit = 0;
            }
            last_state = current_state;
            start_time = current_time;
        }
    }

    int checksum = 0;
    for (int i = 0; i < 32; i++) {
        checksum += data[i];
    }

    if (checksum != data[32]) {
        syslog(LOG_ERR, "DHT22 checksum failed");
        return -1;
    }

    *humidity = (data[0] * 256 + data[1]) / 10.0;
    return 0;
}

int post_humidity(float humidity, const char *server_url) {
    CURL *curl;
    CURLcode res;
    char json[64];
    snprintf(json, sizeof(json), JSON_TEMPLATE, humidity);

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, server_url);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, (long)strlen(json));
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, curl_slist_append(NULL, "Content-Type: application/json"));

        int retries = 0;
        while (retries < MAX_RETRIES) {
            res = curl_easy_perform(curl);
            if (res != CURLE_OK) {
                syslog(LOG_ERR, "curl_easy_perform() failed: %s", curl_easy_strerror(res));
                retries++;
                if (retries < MAX_RETRIES) {
                    sleep(RETRY_DELAY_S);
                }
            } else {
                break;
            }
        }

        curl_easy_cleanup(curl);
    }

    curl_global_cleanup();
    return (res == CURLE_OK);
}

int main(int argc, char *argv[]) {
    const char *server_url = DEFAULT_SERVER_URL;
    int opt;

    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                server_url = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-s <url>]\n", argv[0]);
                return 1;
        }
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        float humidity;
        int retries = 0;
        while (retries < MAX_RETRIES) {
            int status = read_dht22(&humidity);
            if (status == 0) {
                if (post_humidity(humidity, server_url)) {
                    break;
                }
            }
            retries++;
            if (retries < MAX_RETRIES) {
                sleep(RETRY_DELAY_S);
            }
        }

        if (retries == MAX_RETRIES) {
            syslog(LOG_ERR, "Failed to read humidity after %d retries", MAX_RETRIES);
        }

        sleep(10);
    }

    gpioTerminate();
    return 0;
}

