#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <errno.h>

#define TEMP_PATH "/sys/class/thermal/thermal_zone0/temp"
#define COOLING_DEVICE_PATH "/sys/class/thermal/cooling_device0/cur_state"
#define MAX_STATE_PATH "/sys/class/thermal/cooling_device0/max_state"
#define LOG_PATH "/var/log/fan_control.log"

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

int read_temperature(const char *path) {
    int fd = open(path, O_RDONLY);
    if (fd == -1) {
        perror("Failed to open temperature file");
        return -1;
    }

    char buffer[16];
    ssize_t bytes_read = read(fd, buffer, sizeof(buffer) - 1);
    close(fd);

    if (bytes_read == -1) {
        perror("Failed to read temperature file");
        return -1;
    }

    buffer[bytes_read] = '\0';
    long temp = strtol(buffer, NULL, 10);
    if (temp == LONG_MAX || temp == LONG_MIN) {
        perror("Failed to parse temperature");
        return -1;
    }

    return temp / 1000; // Convert to millidegrees Celsius
}

int read_max_state(const char *path) {
    int fd = open(path, O_RDONLY);
    if (fd == -1) {
        perror("Failed to open max state file");
        return -1;
    }

    char buffer[16];
    ssize_t bytes_read = read(fd, buffer, sizeof(buffer) - 1);
    close(fd);

    if (bytes_read == -1) {
        perror("Failed to read max state file");
        return -1;
    }

    buffer[bytes_read] = '\0';
    long max_state = strtol(buffer, NULL, 10);
    if (max_state == LONG_MAX || max_state == LONG_MIN) {
        perror("Failed to parse max state");
        return -1;
    }

    return max_state;
}

void write_fan_state(int state) {
    int fd = open(COOLING_DEVICE_PATH, O_WRONLY);
    if (fd == -1) {
        perror("Failed to open cooling device file");
        return;
    }

    char buffer[16];
    snprintf(buffer, sizeof(buffer), "%d", state);
    ssize_t bytes_written = write(fd, buffer, strlen(buffer));
    close(fd);

    if (bytes_written == -1) {
        perror("Failed to write cooling device state");
    }
}

void log_fan_state_change(int old_state, int new_state) {
    if (old_state == new_state) {
        return;
    }

    FILE *log_file = fopen(LOG_PATH, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(log_file, "%s: Fan state changed from %d to %d\n", asctime(tm_info), old_state, new_state);
    fclose(log_file);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int old_state = -1;

    while (!stop_flag) {
        int temperature = read_temperature(TEMP_PATH);
        if (temperature == -1) {
            sleep(5);
            continue;
        }

        int max_state = read_max_state(MAX_STATE_PATH);
        if (max_state == -1) {
            sleep(5);
            continue;
        }

        int new_state;
        if (temperature < 45000) {
            new_state = 0;
        } else if (temperature < 55000) {
            new_state = 1;
        } else if (temperature < 65000) {
            new_state = 2;
        } else {
            new_state = 3;
        }

        if (new_state > max_state) {
            new_state = max_state;
        }

        if (new_state != old_state) {
            write_fan_state(new_state);
            log_fan_state_change(old_state, new_state);
            old_state = new_state;
        }

        sleep(5);
    }

    write_fan_state(0);
    log_fan_state_change(old_state, 0);

    return 0;
}

