#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define HEATER_PIN 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define SAMPLE_SIZE 4
#define TARGET_TEMP 50.0
#define Kp 1.0
#define Ki 0.1
#define Kd 0.01
#define MAX_TEMP 100.0
#define MIN_TEMP 0.0

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

double read_temperature() {
    uint8_t tx[4] = {0x00, 0x00, 0x00, 0x00};
    uint8_t rx[4];
    int status = spi_xfer(SPI_CHANNEL, tx, rx, SAMPLE_SIZE);
    if (status != SAMPLE_SIZE) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1.0;
    }

    uint32_t thermocouple_data = (rx[0] << 18) | (rx[1] << 10) | (rx[2] << 2);
    uint8_t fault_bits = rx[3] & 0x07;

    if (fault_bits != 0) {
        fprintf(stderr, "Thermocouple fault: %d\n", fault_bits);
        return -1.0;
    }

    double temperature = (thermocouple_data >> 4) * 0.25;
    return temperature;
}

void log_data(double temperature, int duty_cycle, double pid_output) {
    FILE *log_file = fopen("heater_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    time_t now = time(NULL);
    fprintf(log_file, "%s, Temperature: %.2f°C, Duty Cycle: %d%%, PID Output: %.2f\n", ctime(&now), temperature, duty_cycle, pid_output);
    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(HEATER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set heater pin mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(HEATER_PIN, 1000) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(HEATER_PIN, 100) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return 1;
    }

    if (spiOpen(SPI_CHANNEL, SPI_SPEED, 0) < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    double integral = 0.0;
    double prev_error = 0.0;

    while (running) {
        double temperature = read_temperature();
        if (temperature < 0.0) {
            continue;
        }

        if (temperature > MAX_TEMP || temperature < MIN_TEMP) {
            fprintf(stderr, "Temperature out of range: %.2f°C\n", temperature);
            gpioWrite(HEATER_PIN, 0);
            integral = 0.0;
            prev_error = 0.0;
            continue;
        }

        double error = TARGET_TEMP - temperature;
        integral += error;
        double derivative = error - prev_error;
        double pid_output = Kp * error + Ki * integral + Kd * derivative;

        int duty_cycle = (int)(pid_output * 100.0);
        if (duty_cycle < 0) {
            duty_cycle = 0;
        } else if (duty_cycle > 100) {
            duty_cycle = 100;
        }

        gpioSetPWMrange(HEATER_PIN, 100);
        gpioSetPWMDutyCycle(HEATER_PIN, duty_cycle);

        log_data(temperature, duty_cycle, pid_output);

        prev_error = error;
        sleep(1);
    }

    gpioWrite(HEATER_PIN, 0);
    spiClose(SPI_CHANNEL);
    gpioTerminate();

    return 0;
}

