        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(HEATER_PIN, 100) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return 1;
    }

    if (spiOpen(SPI_CHANNEL, SPI_SPEED, 0) < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    double integral = 0.0;
    double prev_error = 0.0;

    while (running) {
        double temperature = read_temperature();
        if (temperature < 0.0) {
            continue;
        }

        if (temperature > MAX_TEMP || temperature < MIN_TEMP) {
            fprintf(stderr, "Temperature out of range: %.2f°C\n", temperature);
            gpioWrite(HEATER_PIN, 0);
            integral = 0.0;
            prev_error = 0.0;
            continue;
        }

        double error = TARGET_TEMP - temperature;
        integral += error;
        double derivative = error - prev_error;
        double pid_output = Kp * error + Ki * integral + Kd * derivative;

        int duty_cycle = (int)(pid_output * 100.0);
        if (duty_cycle < 0) {
            duty_cycle = 0;
        } else if (duty_cycle > 100) {
            duty_cycle = 100;
        }

        gpioSetPWMrange(HEATER_PIN, 100);
        gpioSetPWMDutyCycle(HEATER_PIN, duty_cycle);

        log_data(temperature, duty_cycle, pid_output);

        prev_error = error;
        sleep(1);
    }

    gpioWrite(HEATER_PIN, 0);
    spiClose(SPI_CHANNEL);
    gpioTerminate();

    return 0;
}
