#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SLF3S_ADDRESS_1 0x08
#define SLF3S_ADDRESS_2 0x09
#define SLF3S_MEASUREMENT_CMD 0x3608
#define SLF3S_DATA_LEN 3
#define CRC8_POLYNOMIAL 0x31
#define RETRY_COUNT 3

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = 0;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_sensor(int i2c_handle, uint8_t address, float *flow_rate) {
    uint8_t buffer[SLF3S_DATA_LEN];
    int retries = RETRY_COUNT;
    while (retries--) {
        if (i2cWriteDevice(i2c_handle, address, &SLF3S_MEASUREMENT_CMD, 2) < 0) {
            continue;
        }
        if (i2cReadDevice(i2c_handle, address, buffer, SLF3S_DATA_LEN) < 0) {
            continue;
        }
        uint8_t crc = calculate_crc8(buffer, SLF3S_DATA_LEN - 1);
        if (crc == buffer[SLF3S_DATA_LEN - 1]) {
            *flow_rate = (buffer[0] << 8 | buffer[1]) * 0.01;
            return 0;
        }
    }
    return -1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    int i2c_handle_1 = i2cOpen(I2C_BUS, SLF3S_ADDRESS_1, 0);
    int i2c_handle_2 = i2cOpen(I2C_BUS, SLF3S_ADDRESS_2, 0);

    if (i2c_handle_1 < 0 || i2c_handle_2 < 0) {
        fprintf(stderr, "Failed to open I2C handles\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    FILE *log_file = fopen("flow_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle_1);
        i2cClose(i2c_handle_2);
        gpioTerminate();
        return 1;
    }

    while (!stop_flag) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        float flow_rate_1, flow_rate_2;
        if (read_sensor(i2c_handle_1, SLF3S_ADDRESS_1, &flow_rate_1) == 0) {
            if (read_sensor(i2c_handle_2, SLF3S_ADDRESS_2, &flow_rate_2) == 0) {
                fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, flow_rate_1, flow_rate_2);
                fflush(log_file);
            }
        }

        sleep(1);
    }

    fclose(log_file);
    i2cClose(i2c_handle_1);
    i2cClose(i2c_handle_2);
    gpioTerminate();

    return 0;
}

