#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_A 17
#define GPIO_B 18
#define PULSES_PER_REV 360.0

volatile int state = 0;
volatile int last_state = 0;
volatile int pulse_count = 0;
volatile int direction = 0;

void signal_handler(int signum) {
    gpioTerminate();
    exit(signum);
}

void quadrature_state_machine(int gpio, int level, uint32_t tick) {
    int new_state = (gpio == GPIO_A) ? (level << 1) : level;
    int delta = new_state - last_state;

    if (delta == 3) {
        state = 0;
    } else if (delta == -3) {
        state = 3;
    } else {
        state = (state + delta) & 3;
    }

    last_state = new_state;

    if (state == 0 || state == 3) {
        pulse_count += direction;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_A, PI_INPUT);
    gpioSetMode(GPIO_B, PI_INPUT);
    gpioSetPullUpDown(GPIO_A, PI_PUD_UP);
    gpioSetPullUpDown(GPIO_B, PI_PUD_UP);

    gpioSetAlertFunc(GPIO_A, quadrature_state_machine);
    gpioSetAlertFunc(GPIO_B, quadrature_state_machine);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    FILE *log_file = fopen("encoder_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (1) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        double angular_position = (pulse_count / PULSES_PER_REV) * 360.0;

        fprintf(log_file, "%s, %.2f\n", timestamp, angular_position);
        fflush(log_file);

        sleep(1);
    }

    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

