#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <sys/ioctl.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x39
#define FIFO_REG 0x60
#define LED_PIN 17
#define THRESHOLD 2000
#define SAMPLE_INTERVAL 100000  // 100 ms in microseconds

static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;
static FILE *log_file = NULL;

void cleanup() {
    if (log_file) fclose(log_file);
    if (led_line) gpiod_line_release(led_line);
    if (chip) gpiod_chip_close(chip);
    if (i2c_fd >= 0) close(i2c_fd);
}

void signal_handler(int signum) {
    cleanup();
    exit(signum);
}

int read_sensor_data(uint16_t *red, uint16_t *ir) {
    uint8_t buffer[2];
    if (read(i2c_fd, buffer, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }
    *red = (buffer[0] << 8) | buffer[1];
    return 0;
}

int main() {
    struct timespec ts;
    uint16_t red, ir;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Request LED GPIO line
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get LED GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Configure LED GPIO line as output
    if (gpiod_line_request_output(led_line, "adpd144ri_led", 0) < 0) {
        perror("Failed to request LED GPIO line as output");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("adpd144ri_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        if (read_sensor_data(&red, &ir) < 0) {
            continue;
        }

        // Check if IR reading exceeds threshold
        if (ir > THRESHOLD) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }

        // Log timestamped readings
        if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
            fprintf(log_file, "%ld.%09ld,%u,%u\n", ts.tv_sec, ts.tv_nsec, red, ir);
            fflush(log_file);
        }
    }

    // Cleanup on exit
    cleanup();
    return EXIT_SUCCESS;
}

