#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <pthread.h>
#include <signal.h>

#define SENSOR_PIN 18
#define SAMPLE_INTERVAL 1000000 // 1 second in microseconds
#define LOG_FILE "rpm_log.txt"

volatile int pulse_count = 0;
pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
FILE *log_file = NULL;

void *pulse_counter(void *arg) {
    while (1) {
        int level = gpioRead(SENSOR_PIN);
        if (level == PI_HIGH) {
            pthread_mutex_lock(&pulse_mutex);
            pulse_count++;
            pthread_mutex_unlock(&pulse_mutex);
        }
        gpioDelay(10); // 10 microseconds delay
    }
    return NULL;
}

void log_rpm() {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    pthread_mutex_lock(&pulse_mutex);
    int count = pulse_count;
    pulse_count = 0;
    pthread_mutex_unlock(&pulse_mutex);

    double rpm = count * 60.0 / SAMPLE_INTERVAL * 1000000.0;
    fprintf(log_file, "%s,%.2f\n", timestamp, rpm);
    fflush(log_file);
}

void signal_handler(int sig) {
    gpioTerminate();
    if (log_file) {
        fclose(log_file);
    }
    pthread_mutex_destroy(&pulse_mutex);
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(SENSOR_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set GPIO pull-down\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    pthread_t counter_thread;
    if (pthread_create(&counter_thread, NULL, pulse_counter, NULL) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        log_rpm();
        gpioDelay(SAMPLE_INTERVAL);
    }

    pthread_join(counter_thread, NULL);
    gpioTerminate();
    fclose(log_file);
    pthread_mutex_destroy(&pulse_mutex);
    return 0;
}

