#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <sys/ioctl.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x39
#define PART_ID_REG 0x00
#define FIFO_DATA_REG 0x01
#define LED_PIN 17
#define THRESHOLD 2000
#define SAMPLE_INTERVAL 100

static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;
static FILE *log_file = NULL;

void cleanup() {
    if (log_file) {
        fclose(log_file);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

void signal_handler(int signum) {
    cleanup();
    exit(signum);
}

int main() {
    struct timespec ts;
    uint8_t part_id;
    uint16_t red, ir;
    int ret;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Request LED GPIO line
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get LED GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Request exclusive access to the LED GPIO line
    ret = gpiod_line_request_output(led_line, "adpd144ri_led", 0);
    if (ret < 0) {
        perror("Failed to request LED GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("adpd144ri_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Read PART_ID register to verify sensor presence
    ret = read(i2c_fd, &part_id, 1);
    if (ret != 1) {
        perror("Failed to read PART_ID register");
        goto cleanup;
    }

    if (part_id != 0x14) {
        fprintf(stderr, "Sensor not found or incorrect part ID\n");
        goto cleanup;
    }

    // Main loop
    while (1) {
        // Read FIFO data registers
        ret = read(i2c_fd, &red, 2);
        if (ret != 2) {
            perror("Failed to read red channel data");
            goto cleanup;
        }

        ret = read(i2c_fd, &ir, 2);
        if (ret != 2) {
            perror("Failed to read IR channel data");
            goto cleanup;
        }

        // Log timestamped readings
        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld.%09ld,%u,%u\n", ts.tv_sec, ts.tv_nsec, red, ir);
        fflush(log_file);

        // Trigger LED if IR reading exceeds threshold
        if (ir > THRESHOLD) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }

        // Sleep for 100 ms
        usleep(SAMPLE_INTERVAL * 1000);
    }

cleanup:
    cleanup();
    return EXIT_FAILURE;
}

