This C program interfaces with an ADPD144RI sensor using the Raspberry Pi 3 Model B+ and libgpiod. It reads the PART_ID register to verify the sensor's presence, reads the red and IR channel data from the FIFO data registers, and logs timestamped readings to a file. The program also triggers an LED if the IR reading exceeds a specified threshold. It handles I2C errors, sensor-absent paths, and resource cleanup on all exit paths, including signal handling for SIGINT and SIGTERM.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_INPUT_LINE "17"
#define GPIO_OUTPUT_LINE "18"
#define GAIN_LOW 0
#define GAIN_HIGH 1
#define SAMPLE_INTERVAL 10  // in milliseconds

static struct gpiod_chip *chip;
static struct gpiod_line *input_line;
static struct gpiod_line *output_line;

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Interrupted, cleaning up...\n");
        if (input_line) {
            gpiod_line_release(input_line);
        }
        if (output_line) {
            gpiod_line_release(output_line);
        }
        if (chip) {
            gpiod_chip_close(chip);
        }
        exit(EXIT_SUCCESS);
    }
}

int main() {
    struct timespec ts;
    struct tm *tm_info;
    char timestamp[20];
    int last_state = 0;
    int current_state;

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request input line
    input_line = gpiod_chip_get_line(chip, atoi(GPIO_INPUT_LINE));
    if (!input_line) {
        perror("Failed to get input line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request output line
    output_line = gpiod_chip_get_line(chip, atoi(GPIO_OUTPUT_LINE));
    if (!output_line) {
        perror("Failed to get output line");
        gpiod_line_release(input_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set output line to LOW (60dB gain)
    if (gpiod_line_set_value(output_line, GAIN_LOW) < 0) {
        perror("Failed to set output line value");
        gpiod_line_release(input_line);
        gpiod_line_release(output_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set input line to input mode
    if (gpiod_line_request_input(input_line, "audio_input") < 0) {
        perror("Failed to request input line");
        gpiod_line_release(input_line);
        gpiod_line_release(output_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Audio peak detector started. Press Ctrl+C to stop.\n");

    while (1) {
        // Read current state of input line
        current_state = gpiod_line_get_value(input_line);
        if (current_state < 0) {
            perror("Failed to read input line value");
            handle_signal(SIGINT);  // Clean up and exit
        }

        // Check for rising edge
        if (current_state && !last_state) {
            // Get current time
            if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
                tm_info = localtime(&ts);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
                // Log peak to file
                FILE *log_file = fopen("audio_log.txt", "a");
                if (log_file) {
                    fprintf(log_file, "%s 1\n", timestamp);
                    fclose(log_file);
                } else {
                    perror("Failed to open log file");
                }
            }
        }

        last_state = current_state;

        // Sleep for the specified interval
        usleep(SAMPLE_INTERVAL * 1000);
    }

    return EXIT_SUCCESS;
}

