#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x36
#define CMD_START_MEAS 0x3608
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL 0xFF
#define LOG_FILE "flow_log.csv"

void log_error(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
}

void log_flow_rate(double flow_rate) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    FILE *log = fopen(LOG_FILE, "a");
    if (log == NULL) {
        log_error("Failed to open log file");
        return;
    }
    fprintf(log, "%s,%.2f\n", timestamp, flow_rate);
    fflush(log);
    fclose(log);
}

uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = CRC_INITIAL;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    int i2c_handle = gpioI2COpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioI2CWriteWordData(i2c_handle, CMD_START_MEAS) < 0) {
        log_error("Failed to start measurement");
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log = fopen(LOG_FILE, "a");
    if (log == NULL) {
        log_error("Failed to open log file");
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, [](int sig) {
        gpioI2CClose(i2c_handle);
        fclose(log);
        gpioTerminate();
        exit(EXIT_SUCCESS);
    });

    while (1) {
        uint8_t buffer[3];
        if (gpioI2CRead(i2c_handle, buffer, sizeof(buffer)) != sizeof(buffer)) {
            log_error("Failed to read from I2C sensor");
            continue;
        }

        uint16_t raw_flow = (buffer[0] << 8) | buffer[1];
        uint8_t crc_received = buffer[2];
        uint8_t crc_calculated = calculate_crc8(buffer, 2);

        if (crc_received != crc_calculated) {
            log_error("CRC check failed");
            continue;
        }

        double flow_rate = (double)raw_flow / 1000.0;
        log_flow_rate(flow_rate);

        gpioDelay(1000 * 1000); // 1000 ms
    }

    fclose(log);
    gpioI2CClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

