#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x70
#define SENSOR_REG 0x00
#define SENSOR_LEN 7

void log_air_quality(int iaq, int tvoc, int eco2) {
    FILE *log_file = fopen("air_quality_log.csv", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    fprintf(log_file, "%ld,%d,%d,%d\n", now, iaq, tvoc, eco2);
    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = gpioI2COpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, [](int sig) {
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        exit(EXIT_SUCCESS);
    });

    while (1) {
        uint8_t buffer[SENSOR_LEN];
        int result = gpioI2CRead(i2c_handle, buffer, SENSOR_LEN);
        if (result != SENSOR_LEN) {
            fprintf(stderr, "Failed to read from sensor\n");
            gpioI2CClose(i2c_handle);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        int tvoc = (buffer[1] << 8) | buffer[2];
        int eco2 = (buffer[5] << 8) | buffer[6];
        int iaq = 100 - (tvoc / 10.0) - ((eco2 - 400) / 50.0);
        iaq = (iaq < 0) ? 0 : ((iaq > 100) ? 100 : iaq);

        log_air_quality(iaq, tvoc, eco2);

        sleep(5);
    }

    gpioI2CClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

