#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define POLL_INTERVAL_MS 100
#define INTRUSION_TIMEOUT_S 5

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static int intrusion_timer = 0;

static void handle_signal(int signum) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(EXIT_SUCCESS);
}

static void check_error(int ret, const char *msg) {
    if (ret < 0) {
        fprintf(stderr, "%s: %s\n", msg, strerror(errno));
        exit(EXIT_FAILURE);
    }
}

int main(void) {
    struct gpiod_line_request_config config = {
        .consumer = "ttp223_tamper",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
    };

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open gpiochip0
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    check_error(chip == NULL, "Failed to open gpiochip0");

    // Request line 17 as input
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    check_error(line == NULL, "Failed to get GPIO line 17");
    check_error(gpiod_line_request(line, &config) < 0, "Failed to request GPIO line 17");

    while (1) {
        int value = gpiod_line_get_value(line);
        check_error(value < 0, "Failed to read GPIO line 17");

        if (value == 1) {
            intrusion_timer++;
            if (intrusion_timer >= INTRUSION_TIMEOUT_S) {
                printf("Intrusion alert!\n");
                intrusion_timer = 0;
            }
        } else {
            intrusion_timer = 0;
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    // Cleanup on exit
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

