#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <alsa/asoundlib.h>

#define I2S_DEVICE "/dev/snd/pcmC0D0c"
#define MIC_L_R_SELECT_PIN 17
#define PCM_FILE "audio_capture.pcm"
#define BUFFER_SIZE 1024

static int running = 1;
static struct gpiod_chip *chip;
static struct gpiod_line *line;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    int err;
    snd_pcm_t *handle;
    snd_pcm_hw_params_t *params;
    FILE *pcm_file;
    uint32_t buffer[BUFFER_SIZE];
    uint16_t pcm_samples[BUFFER_SIZE * 2];
    size_t frames_read, frames_written;

    // Initialize GPIO
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, MIC_L_R_SELECT_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    err = gpiod_line_request_output(line, "mic_select", 0);
    if (err < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initialize ALSA
    err = snd_pcm_open(&handle, I2S_DEVICE, SND_PCM_STREAM_CAPTURE, 0);
    if (err < 0) {
        fprintf(stderr, "Failed to open ALSA device: %s\n", snd_strerror(err));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    snd_pcm_hw_params_alloca(&params);
    snd_pcm_hw_params_any(handle, params);
    snd_pcm_hw_params_set_access(handle, params, SND_PCM_ACCESS_RW_INTERLEAVED);
    snd_pcm_hw_params_set_format(handle, params, SND_PCM_FORMAT_S32_LE);
    snd_pcm_hw_params_set_rate_near(handle, params, 48000, 0);
    snd_pcm_hw_params_set_channels(handle, params, 2);
    snd_pcm_hw_params(handle, params);

    // Open PCM file
    pcm_file = fopen(PCM_FILE, "wb");
    if (!pcm_file) {
        perror("Failed to open PCM file");
        snd_pcm_close(handle);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    while (running) {
        // Select left channel
        err = gpiod_line_set_value(line, 0);
        if (err < 0) {
            perror("Failed to set GPIO line value");
            break;
        }

        // Read I2S data
        frames_read = snd_pcm_readi(handle, buffer, BUFFER_SIZE);
        if (frames_read < 0) {
            fprintf(stderr, "Failed to read I2S data: %s\n", snd_strerror(frames_read));
            break;
        }

        // Extract 24-bit data and right-shift to 16-bit PCM
        for (size_t i = 0; i < frames_read; i++) {
            pcm_samples[i * 2] = (buffer[i] >> 8) & 0xFFFF;
            pcm_samples[i * 2 + 1] = (buffer[i] >> 8) & 0xFFFF;
        }

        // Write PCM samples to file
        frames_written = fwrite(pcm_samples, sizeof(uint16_t), frames_read * 2, pcm_file);
        if (frames_written != frames_read * 2) {
            perror("Failed to write PCM data to file");
            break;
        }
    }

    // Clean up
    fclose(pcm_file);
    snd_pcm_close(handle);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

