#define FAN_DUTY_MIN 0
#define FAN_DUTY_MAX 80
#define POLL_INTERVAL 50
#define DEBOUNCE_INTERVAL 50
#define TIMEOUT 1000

volatile int running = 1;
volatile int flame_detected = 0;
volatile int flame_start_time = 0;
volatile int flame_duration = 0;

void log_event(const char *event) {
    time_t now = time(NULL);
    char *iso_time = ctime(&now);
    iso_time[strlen(iso_time) - 1] = '\0'; // Remove newline
    printf("%s: %s\n", iso_time, event);
    FILE *log_file = fopen("flame_log.txt", "a");
    if (log_file) {
        fprintf(log_file, "%s: %s\n", iso_time, event);
        fclose(log_file);
    }
}

void gpio_callback(int gpio, int level, uint32_t tick) {
    static int last_level = 0;
    static int last_tick = 0;

    if (gpio == SENSOR_PIN) {
        if (level != last_level) {
            int time_diff = tick - last_tick;
            if (time_diff > DEBOUNCE_INTERVAL) {
                if (level == 0) {
                    flame_detected = 1;
                    flame_start_time = tick;
                } else {
                    flame_detected = 0;
                    flame_duration = tick - flame_start_time;
                }
            }
        }
        last_level = level;
        last_tick = tick;
    }
}

void signal_handler(int sig) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetMode(FAN_PIN, PI_OUTPUT);

    gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP);

    gpioSetAlertFunc(SENSOR_PIN, gpio_callback);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("System start");

    while (running) {
        if (flame_detected) {
            int duty_cycle = FAN_DUTY_MIN + (FAN_DUTY_MAX - FAN_DUTY_MIN) * (1 - exp(-flame_duration / 1000.0));
            gpioSetPWMFrequency(FAN_PIN, FAN_FREQ);
            gpioSetPWMRange(FAN_PIN, 100);
            gpioSetPWM dutyCycle(FAN_PIN, duty_cycle);
        } else {
            gpioSetPWMFrequency(FAN_PIN, 0);
            gpioSetPWMRange(FAN_PIN, 0);
        }

        gpioDelay(POLL_INTERVAL * 1000);
    }

    log_event("System shutdown");

    gpioSetPWMFrequency(FAN_PIN, 0);
    gpioSetPWMRange(FAN_PIN, 0);
    gpioTerminate();

    return 0;
}

