#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define TRIGGER_PIN 23
#define READY_PIN 24
#define LOG_FILE "heatmap.log"
#define MAGIC_NUMBER 0x52444144
#define HEADER_SIZE 24
#define FRAME_SIZE 32768
#define NUM_FRAMES 10000

typedef struct {
    uint32_t magic_number;
    uint64_t timestamp;
    float start_freq;
    float end_freq;
    uint16_t chirps;
    uint16_t samples;
    float frame_period;
} LogHeader;

typedef struct {
    uint64_t timestamp;
    uint32_t frame_number;
} FrameHeader;

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

int main() {
    int spi_handle;
    FILE *log_file;
    LogHeader header;
    FrameHeader frame_header;
    uint8_t *buffer = NULL;
    uint32_t frame_number = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if ((spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE)) < 0) {
        fprintf(stderr, "Failed to open SPI channel %d\n", SPI_CHANNEL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", TRIGGER_PIN);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(READY_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", READY_PIN);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if ((log_file = fopen(LOG_FILE, "wb")) == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    header.magic_number = MAGIC_NUMBER;
    header.timestamp = time(NULL);
    header.start_freq = 77.0;
    header.end_freq = 79.0;
    header.chirps = 64;
    header.samples = 256;
    header.frame_period = 0.1;

    if (fwrite(&header, 1, HEADER_SIZE, log_file) != HEADER_SIZE) {
        fprintf(stderr, "Failed to write log header\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    buffer = (uint8_t *)malloc(FRAME_SIZE);
    if (buffer == NULL) {
        fprintf(stderr, "Failed to allocate memory for buffer\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!stop_flag) {
        gpioWrite(TRIGGER_PIN, 1);
        while (gpioRead(READY_PIN) == 0) {
            if (stop_flag) break;
        }
        gpioWrite(TRIGGER_PIN, 0);

        frame_header.timestamp = time(NULL);
        frame_header.frame_number = frame_number++;

        if (fwrite(&frame_header, 1, sizeof(FrameHeader), log_file) != sizeof(FrameHeader)) {
            fprintf(stderr, "Failed to write frame header\n");
            break;
        }

        if (spiXfer(spi_handle, buffer, buffer, FRAME_SIZE) != FRAME_SIZE) {
            fprintf(stderr, "Failed to read frame data\n");
            break;
        }

        if (fwrite(buffer, 1, FRAME_SIZE, log_file) != FRAME_SIZE) {
            fprintf(stderr, "Failed to write frame data\n");
            break;
        }
    }

    free(buffer);
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

