#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x44
#define OPT3001_CONFIG_REG 0x01
#define OPT3001_RESULT_REG 0x00
#define OPT3001_CONV_TIME 100
#define OPT3001_FULL_SCALE 0x0000

volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    int i2c_handle;
    FILE *log_file;
    struct timespec ts;
    uint16_t config_reg, result_reg;
    uint8_t exponent, mantissa;
    double lux;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    config_reg = (OPT3001_CONV_TIME << 10) | OPT3001_FULL_SCALE;
    if (i2cWriteWordData(i2c_handle, OPT3001_CONFIG_REG, config_reg) < 0) {
        fprintf(stderr, "Failed to write configuration register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("light_data.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        if (i2cReadWordData(i2c_handle, OPT3001_RESULT_REG, &result_reg) < 0) {
            fprintf(stderr, "Failed to read result register\n");
            continue;
        }

        exponent = (result_reg >> 12) & 0x0F;
        mantissa = result_reg & 0x0FFF;
        lux = 0.01 * pow(2, exponent) * mantissa;

        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld.%09ld, %.2f lux\n", ts.tv_sec, ts.tv_nsec, lux);
        fflush(log_file);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

