        exponent = (result_reg >> 12) & 0x0F;
        mantissa = result_reg & 0x0FFF;
        lux = 0.01 * pow(2, exponent) * mantissa;

        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld.%09ld, %.2f lux\n", ts.tv_sec, ts.tv_nsec, lux);
        fflush(log_file);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}
