#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define POLL_INTERVAL 1

volatile sig_atomic_t exit_flag = 0;

void signal_handler(int signum) {
    if (signum == SIGINT) {
        exit_flag = 1;
    }
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_request_config config;
    struct gpiod_line_settings settings;
    int ret;
    time_t now;
    struct tm *tm_info;
    char timestamp[20];

    // Register signal handler for SIGINT
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Failed to register signal handler");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Configure line request
    memset(&config, 0, sizeof(config));
    config.consumer = "flame_detect";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    config.flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP;

    // Request line
    line = gpiod_chip_request_lines(chip, &config, 1, &GPIO_LINE);
    if (!line) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!exit_flag) {
        // Get line value
        int value = gpiod_line_request_get_value(line);
        if (value < 0) {
            perror("Failed to get line value");
            break;
        }

        // Get current time
        now = time(NULL);
        tm_info = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        // Print status
        if (value == 0) {
            printf("%s: Flame Detected: YES\n", timestamp);
        } else {
            printf("%s: Flame Detected: NO\n", timestamp);
        }

        // Sleep for the specified interval
        sleep(POLL_INTERVAL);
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

