#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_LEFT 17
#define GPIO_CENTER 18
#define GPIO_RIGHT 27

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    gpioSetMode(GPIO_LEFT, PI_INPUT);
    gpioSetMode(GPIO_CENTER, PI_INPUT);
    gpioSetMode(GPIO_RIGHT, PI_INPUT);

