        fprintf(stderr, "Invalid GPIO pin\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        int left = gpioRead(GPIO_LEFT);
        int center = gpioRead(GPIO_CENTER);
        int right = gpioRead(GPIO_RIGHT);

        printf("Left: %d, Center: %d, Right: %d\n", left, center, right);

        usleep(50000);
    }

    gpioTerminate();
    return 0;
}

