#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PINS {2, 3, 4, 5, 6, 7, 8, 9}
#define NUM_PINS 8
#define DELAY_MS 100

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[NUM_PINS];
    struct gpiod_line_request req = {
        .consumer = "TTP226",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
    };

    // Register signal handler for graceful shutdown
    signal(SIGINT, sigint_handler);

    // Open GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request lines for each GPIO pin
    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_PINS[i]);
        if (!lines[i]) {
            perror("Failed to get GPIO line");
            goto cleanup;
        }

        if (gpiod_line_request(lines[i], &req)) {
            perror("Failed to request GPIO line");
            goto cleanup;
        }
    }

    // Main loop
    while (running) {
        for (int i = 0; i < NUM_PINS; i++) {
            int value = gpiod_line_get_value(lines[i]);
            if (value < 0) {
                perror("Failed to read GPIO line value");
                goto cleanup;
            }
            printf("Channel %d: %d\n", GPIO_PINS[i], value);
        }
        usleep(DELAY_MS * 1000);
    }

cleanup:
    // Release lines
    for (int i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

