This C program uses the libgpiod library to read the state of an 8-channel TTP226 digital touch sensor connected to a Raspberry Pi Zero W. It opens the GPIO chip, requests lines for each of the specified GPIO pins, and enters a loop where it reads and logs the state of each channel every 100 ms. The program handles SIGINT (Ctrl+C) for graceful shutdown and ensures all resources are properly released on all exit paths.

code:
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_PINS {2, 3, 4, 5, 6, 12, 13, 16}
#define NUM_PINS 8
#define DELAY_US 100000

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_PINS; i++) {
        if (gpioSetMode(GPIO_PINS[i], PI_INPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_PINS[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPullUpDown(GPIO_PINS[i], PI_PUD_DOWN) < 0) {
            fprintf(stderr, "Failed to set GPIO %d pull-down resistor\n", GPIO_PINS[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);

    while (running) {
        for (int i = 0; i < NUM_PINS; i++) {
            int state = gpioRead(GPIO_PINS[i]);
            if (state < 0) {
                fprintf(stderr, "Failed to read GPIO %d\n", GPIO_PINS[i]);
                gpioTerminate();
                return EXIT_FAILURE;
            }
            printf("CH%d=%d ", i + 1, state);
        }
        printf("\n");

        clock_gettime(CLOCK_MONOTONIC, &end);
        long elapsed_ms = (end.tv_sec - start.tv_sec) * 1000 + (end.tv_nsec - start.tv_nsec) / 1000000;
        printf("[%+ld ms] ", elapsed_ms);

        gpioDelay(DELAY_US);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

