#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINES "2,3,4,17,27,22,10,9"
#define POLL_INTERVAL_MS 50

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[8];
    struct gpiod_line_request req;
    struct timespec ts;
    char timestamp[20];
    int i, ret;

    // Install SIGINT handler
    signal(SIGINT, sigint_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request the GPIO lines
    ret = gpiod_chip_get_lines(chip, GPIO_LINES, 8, &lines);
    if (ret != 8) {
        perror("Failed to request GPIO lines");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure lines as input with bias disabled
    for (i = 0; i < 8; i++) {
        ret = gpiod_line_request_input(lines[i], "touch_sensor");
        if (ret < 0) {
            perror("Failed to request input for line");
            for (int j = 0; j < i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    // Main loop
    while (running) {
        // Get current time
        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", localtime(&ts.tv_sec));

        // Read and print the state of each line
        for (i = 0; i < 8; i++) {
            int value = gpiod_line_get_value(lines[i]);
            if (value < 0) {
                perror("Failed to read line value");
                running = 0;
                break;
            }
            printf("%s,%d\n", timestamp, value);
        }

        // Sleep for the specified interval
        usleep(POLL_INTERVAL_MS * 1000);
    }

    // Release resources
    for (i = 0; i < 8; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

