#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define POLL_INTERVAL 100

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio library\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    signal(SIGINT, sigint_handler);

    printf("Tilt Sensor Monitor - Press Ctrl+C to exit\n");

    while (running) {
        int tilt_state = gpioRead(GPIO_PIN);
        if (tilt_state == PI_TIMEOUT) {
            fprintf(stderr, "GPIO read timed out\n");
            break;
        } else if (tilt_state == PI_BAD_GPIO) {
            fprintf(stderr, "Invalid GPIO pin\n");
            break;
        } else if (tilt_state == PI_BAD_LEVEL) {
            fprintf(stderr, "Invalid GPIO level\n");
            break;
        }

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

        if (tilt_state == 0) {
            printf("%s - Tilted\n", time_str);
        } else {
            printf("%s - Not Tilted\n", time_str);
        }

        fflush(stdout);
        gpioDelay(POLL_INTERVAL * 1000);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

