#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI1145_I2C_ADDR 0x60
#define SI1145_PART_ID 0x45
#define SI1145_HW_KEY 0x17
#define SI1145_CHLIST 0x01
#define SI1145_ALS_FORCE 0x06
#define SI1145_ALS_VIS_DATA 0x10
#define SI1145_UV_INDEX_DATA 0x20

void log_data(const char *filename, time_t timestamp, float uv_index, float als_visible) {
    FILE *file = fopen(filename, "a");
    if (file == NULL) {
        perror("Failed to open log file");
        return;
    }
    fprintf(file, "%ld,%f,%f\n", timestamp, uv_index, als_visible);
    fclose(file);
}

void cleanup(int sig) {
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    int i2c_handle = gpioI2COpen(I2C_BUS, SI1145_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    uint8_t part_id;
    if (gpioI2CReadReg8(i2c_handle, SI1145_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Failed to read PART ID\n");
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (part_id != SI1145_PART_ID) {
        fprintf(stderr, "Incorrect PART ID: 0x%02X\n", part_id);
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t hw_key = SI1145_HW_KEY;
    if (gpioI2CWriteReg8(i2c_handle, SI1145_HW_KEY, hw_key) < 0) {
        fprintf(stderr, "Failed to write HW_KEY\n");
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t chlist = SI1145_CHLIST;
    if (gpioI2CWriteReg8(i2c_handle, SI1145_CHLIST, chlist) < 0) {
        fprintf(stderr, "Failed to write CHLIST\n");
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t als_force = SI1145_ALS_FORCE;
    if (gpioI2CWriteReg8(i2c_handle, SI1145_ALS_FORCE, als_force) < 0) {
        fprintf(stderr, "Failed to write ALS_FORCE\n");
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    FILE *log_file = fopen("uv_als_log.csv", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fprintf(log_file, "timestamp,uv_index,als_visible\n");
    fclose(log_file);

    while (1) {
        uint8_t als_vis_data[2];
        if (gpioI2CReadReg16(i2c_handle, SI1145_ALS_VIS_DATA, als_vis_data) < 0) {
            fprintf(stderr, "Failed to read ALS_VIS_DATA\n");
            continue;
        }

        uint8_t uv_index_data[2];
        if (gpioI2CReadReg16(i2c_handle, SI1145_UV_INDEX_DATA, uv_index_data) < 0) {
            fprintf(stderr, "Failed to read UV_INDEX_DATA\n");
            continue;
        }

        float als_visible = (als_vis_data[0] << 8) | als_vis_data[1];
        float uv_index = (uv_index_data[0] << 8) | uv_index_data[1];

        time_t timestamp = time(NULL);
        printf("Timestamp: %ld, UV Index: %.2f, Visible ALS: %.2f\n", timestamp, uv_index, als_visible);

        log_file = fopen("uv_als_log.csv", "a");
        if (log_file == NULL) {
            perror("Failed to open log file");
            continue;
        }
        fprintf(log_file, "%ld,%.2f,%.2f\n", timestamp, uv_index, als_visible);
        fclose(log_file);

        sleep(1);
    }

    gpioI2CClose(i2c_handle);
    gpioTerminate();
    return 0;
}

