#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SENSOR1_ADDR 0x36
#define SENSOR2_ADDR 0x37
#define MEASUREMENT_CMD 0x3608
#define MEASUREMENT_REG 0x00
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL 0xFF
#define SCALE_FACTOR 0.036
#define ALARM_PIN "gpiochip0:17"
#define LOG_FILE "flow_log.txt"

static int i2c_fd1 = -1, i2c_fd2 = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *alarm_line = NULL;

static void cleanup() {
    if (alarm_line) {
        gpiod_line_release(alarm_line);
        alarm_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_fd1 != -1) {
        close(i2c_fd1);
        i2c_fd1 = -1;
    }
    if (i2c_fd2 != -1) {
        close(i2c_fd2);
        i2c_fd2 = -1;
    }
}

static int read_sensor(int fd, uint8_t *buffer, size_t len) {
    if (write(fd, &MEASUREMENT_CMD, 2) != 2) {
        perror("Failed to send measurement command");
        return -1;
    }
    usleep(100 * 1000);
    if (read(fd, buffer, len) != len) {
        perror("Failed to read from sensor");
        return -1;
    }
    return 0;
}

static int calculate_crc(uint8_t *data, size_t len) {
    uint8_t crc = CRC_INITIAL;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int validate_flow(uint8_t *data) {
    uint8_t crc = calculate_crc(data, 6);
    return crc == data[6];
}

static float convert_flow(int16_t raw_flow) {
    return raw_flow * SCALE_FACTOR;
}

static void log_flow(float flow1, float flow2) {
    if (log_file) {
        fprintf(log_file, "Flow1: %.2f ml/min, Flow2: %.2f ml/min\n", flow1, flow2);
        fflush(log_file);
    }
}

static void handle_signal(int signum) {
    cleanup();
    exit(signum);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd1 = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd1 == -1) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }
    if (ioctl(i2c_fd1, I2C_SLAVE, SENSOR1_ADDR) == -1) {
        perror("Failed to set I2C address for sensor 1");
        close(i2c_fd1);
        return EXIT_FAILURE;
    }

    i2c_fd2 = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd2 == -1) {
        perror("Failed to open I2C device");
        close(i2c_fd1);
        return EXIT_FAILURE;
    }
    if (ioctl(i2c_fd2, I2C_SLAVE, SENSOR2_ADDR) == -1) {
        perror("Failed to set I2C address for sensor 2");
        close(i2c_fd1);
        close(i2c_fd2);
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd1);
        close(i2c_fd2);
        return EXIT_FAILURE;
    }

    alarm_line = gpiod_chip_get_line(chip, 17);
    if (!alarm_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd1);
        close(i2c_fd2);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(alarm_line, "flow_alarm", 0) == -1) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(alarm_line);
        alarm_line = NULL;
        gpiod_chip_close(chip);
        close(i2c_fd1);
        close(i2c_fd2);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(alarm_line);
        alarm_line = NULL;
        gpiod_chip_close(chip);
        close(i2c_fd1);
        close(i2c_fd2);
        return EXIT_FAILURE;
    }

    uint8_t buffer1[9], buffer2[9];
    float total_flow = 0.0;

    while (1) {
        if (read_sensor(i2c_fd1, buffer1, 9) == 0 && validate_flow(buffer1)) {
            int16_t raw_flow1 = (buffer1[0] << 8) | buffer1[1];
            float flow1 = convert_flow(raw_flow1);
            total_flow += flow1;
        } else {
            fprintf(stderr, "Failed to read or validate flow from sensor 1\n");
        }

        if (read_sensor(i2c_fd2, buffer2, 9) == 0 && validate_flow(buffer2)) {
            int16_t raw_flow2 = (buffer2[0] << 8) | buffer2[1];
            float flow2 = convert_flow(raw_flow2);
            total_flow += flow2;
        } else {
            fprintf(stderr, "Failed to read or validate flow from sensor 2\n");
        }

        log_flow(flow1, flow2);

        if (total_flow / 2.0 < 0.5) {
            gpiod_line_set_value(alarm_line, 1);
        } else {
            gpiod_line_set_value(alarm_line, 0);
        }

        total_flow = 0.0;
        sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

