    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(alarm_line);
        alarm_line = NULL;
        gpiod_chip_close(chip);
        close(i2c_fd1);
        close(i2c_fd2);
        return EXIT_FAILURE;
    }

    uint8_t buffer1[9], buffer2[9];
    float total_flow = 0.0;

    while (1) {
        if (read_sensor(i2c_fd1, buffer1, 9) == 0 && validate_flow(buffer1)) {
            int16_t raw_flow1 = (buffer1[0] << 8) | buffer1[1];
            float flow1 = convert_flow(raw_flow1);
            total_flow += flow1;
        } else {
            fprintf(stderr, "Failed to read or validate flow from sensor 1\n");
        }

        if (read_sensor(i2c_fd2, buffer2, 9) == 0 && validate_flow(buffer2)) {
            int16_t raw_flow2 = (buffer2[0] << 8) | buffer2[1];
            float flow2 = convert_flow(raw_flow2);
            total_flow += flow2;
        } else {
            fprintf(stderr, "Failed to read or validate flow from sensor 2\n");
        }

        log_flow(flow1, flow2);

        if (total_flow / 2.0 < 0.5) {
            gpiod_line_set_value(alarm_line, 1);
        } else {
            gpiod_line_set_value(alarm_line, 0);
        }

        total_flow = 0.0;
        sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}
```

This code provides a complete solution for reading flow rates from two Sensirion SLF3S-0600F Liquid Flow Sensors on a Raspberry Pi 5 using the Linux I2C character-device API and the libgpiod library. It includes error handling, resource management, and clean shutdown on SIGINT/SIGTERM. The program logs the average flow rate to a file and controls an alarm GPIO based on the flow rate.

