#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define BUFFER_SIZE 100
#define GPIO_PIN 4
#define POLL_INTERVAL 50

typedef struct {
    time_t timestamp;
    int reading;
} Entry;

Entry buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_full = 0;

void handle_sigint(int sig) {
    printf("Buffer contents:\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index - i + BUFFER_SIZE) % BUFFER_SIZE;
        printf("%s: %d\n", ctime(&buffer[index].timestamp), buffer[index].reading);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up resistor on GPIO %d\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        int reading = gpioRead(GPIO_PIN);
        if (reading == 0) {
            time_t now = time(NULL);
            buffer[buffer_index].timestamp = now;
            buffer[buffer_index].reading = reading;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;
            buffer_full = buffer_index == 0;
            printf("Obstacle detected at %s\n", ctime(&now));
        }
        gpioDelay(POLL_INTERVAL * 1000);
    }

    gpioTerminate();
    return 0;
}

