#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x55
#define MODE_CONTROL 0x1D
#define OPERATING_STATUS 0x1B
#define X_ACCEL 0x2A
#define Y_ACCEL 0x2C
#define Z_ACCEL 0x2E
#define ACCEL_SCALE 0.0009765625
#define SAMPLE_INTERVAL 500000
#define CSV_HEADER "Timestamp,X,Y,Z\n"

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    int i2c_fd, csv_fd;
    char i2c_buffer[3];
    char csv_buffer[64];
    struct timespec ts;
    FILE *csv_file;

    // Open I2C device
    if ((i2c_fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open CSV file
    if ((csv_fd = open("fan_health.csv", O_WRONLY | O_CREAT | O_APPEND, 0644)) < 0) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Check if CSV file is newly created
    if (lseek(csv_fd, 0, SEEK_END) == 0) {
        if (write(csv_fd, CSV_HEADER, strlen(CSV_HEADER)) < 0) {
            perror("Failed to write CSV header");
            close(i2c_fd);
            close(csv_fd);
            return EXIT_FAILURE;
        }
    }

    // Initialize sensor
    i2c_buffer[0] = MODE_CONTROL;
    i2c_buffer[1] = 0x10;
    if (write(i2c_fd, i2c_buffer, 2) != 2) {
        perror("Failed to write to I2C device");
        close(i2c_fd);
        close(csv_fd);
        return EXIT_FAILURE;
    }

    // Wait for sensor to become active
    clock_gettime(CLOCK_MONOTONIC, &ts);
    while (1) {
        i2c_buffer[0] = OPERATING_STATUS;
        if (write(i2c_fd, i2c_buffer, 1) != 1) {
            perror("Failed to write to I2C device");
            close(i2c_fd);
            close(csv_fd);
            return EXIT_FAILURE;
        }
        if (read(i2c_fd, i2c_buffer, 1) != 1) {
            perror("Failed to read from I2C device");
            close(i2c_fd);
            close(csv_fd);
            return EXIT_FAILURE;
        }
        if (i2c_buffer[0] & 0x01) {
            break;
        }
        if (clock_gettime(CLOCK_MONOTONIC, &ts) < 0) {
            perror("Failed to get current time");
            close(i2c_fd);
            close(csv_fd);
            return EXIT_FAILURE;
        }
        if (ts.tv_sec - ts_start.tv_sec > 1) {
            fprintf(stderr, "Sensor did not become active within 1 second\n");
            close(i2c_fd);
            close(csv_fd);
            return EXIT_FAILURE;
        }
        usleep(10000);
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Read acceleration data
        i2c_buffer[0] = X_ACCEL;
        if (write(i2c_fd, i2c_buffer, 1) != 1) {
            perror("Failed to write to I2C device");
            continue;
        }
        if (read(i2c_fd, i2c_buffer, 2) != 2) {
            perror("Failed to read from I2C device");
            continue;
        }
        int16_t x_accel = (i2c_buffer[1] << 8) | i2c_buffer[0];
        i2c_buffer[0] = Y_ACCEL;
        if (write(i2c_fd, i2c_buffer, 1) != 1) {
            perror("Failed to write to I2C device");
            continue;
        }
        if (read(i2c_fd, i2c_buffer, 2) != 2) {
            perror("Failed to read from I2C device");
            continue;
        }
        int16_t y_accel = (i2c_buffer[1] << 8) | i2c_buffer[0];
        i2c_buffer[0] = Z_ACCEL;
        if (write(i2c_fd, i2c_buffer, 1) != 1) {
            perror("Failed to write to I2C device");
            continue;
        }
        if (read(i2c_fd, i2c_buffer, 2) != 2) {
            perror("Failed to read from I2C device");
            continue;
        }
        int16_t z_accel = (i2c_buffer[1] << 8) | i2c_buffer[0];

        // Convert to g
        float x_g = x_accel * ACCEL_SCALE;
        float y_g = y_accel * ACCEL_SCALE;
        float z_g = z_accel * ACCEL_SCALE;

        // Get current time
        if (clock_gettime(CLOCK_MONOTONIC, &ts) < 0) {
            perror("Failed to get current time");
            continue;
        }

        // Format CSV row
        strftime(csv_buffer, sizeof(csv_buffer), "%Y-%m-%dT%H:%M:%S.%09ldZ", gmtime(&ts.tv_sec));
        snprintf(csv_buffer + strlen(csv_buffer), sizeof(csv_buffer) - strlen(csv_buffer), ",%.6f,%.6f,%.6f\n", x_g, y_g, z_g);

        // Write to CSV file
        if (write(csv_fd, csv_buffer, strlen(csv_buffer)) != strlen(csv_buffer)) {
            perror("Failed to write to CSV file");
        }

        // Sleep for 500 ms
        usleep(SAMPLE_INTERVAL);
    }

    // Clean up
    close(i2c_fd);
    close(csv_fd);
    return EXIT_SUCCESS;
}

