#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SENSOR1 17
#define SENSOR2 18
#define STALL_TIME 2000000 // 2 seconds in microseconds
#define LOG_FILE "stall_log.txt"

volatile int running = 1;
FILE *log_fp = NULL;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(SENSOR1, PI_INPUT);
    gpioSetMode(SENSOR2, PI_INPUT);

    if ((log_fp = fopen(LOG_FILE, "a")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int last_sensor1 = 1, last_sensor2 = 1;
    struct timespec start_time, current_time;
    int stall_count = 0;

    while (running) {
        int sensor1 = gpioRead(SENSOR1);
        int sensor2 = gpioRead(SENSOR2);

        if (sensor1 == 0 && sensor2 == 0) {
            if (stall_count == 0) {
                clock_gettime(CLOCK_MONOTONIC, &start_time);
            }
            stall_count++;
        } else {
            stall_count = 0;
        }

        if (stall_count >= 2) {
            clock_gettime(CLOCK_MONOTONIC, &current_time);
            if (current_time.tv_sec - start_time.tv_sec >= 2) {
                char timestamp[20];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&start_time.tv_sec));
                fprintf(log_fp, "%s - Stall detected\n", timestamp);
                fflush(log_fp);
                stall_count = 0;
            }
        }

        last_sensor1 = sensor1;
        last_sensor2 = sensor2;

        gpioDelay(10000); // 10 ms delay
    }

    fclose(log_fp);
    gpioTerminate();
    return EXIT_SUCCESS;
}

