#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SENSOR_PIN 23
#define LOG_FILE "flood_log.txt"
#define REINIT_DELAY 60

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_event(const char *message) {
    FILE *log = fopen(LOG_FILE, "a");
    if (log == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        return;
    }
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
    fprintf(log, "%s ALERT: %s\n", timestamp, message);
    fclose(log);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_PIN, PI_PUD_DOWN);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        int water_detected = gpioRead(SENSOR_PIN);
        if (water_detected == PI_TIMEOUT) {
            log_event("GPIO read timeout");
            gpioTerminate();
            sleep(REINIT_DELAY);
            if (gpioInitialise() < 0) {
                fprintf(stderr, "Failed to reinitialize pigpio library\n");
                return EXIT_FAILURE;
            }
            gpioSetMode(SENSOR_PIN, PI_INPUT);
            gpioSetPullUpDown(SENSOR_PIN, PI_PUD_DOWN);
        } else if (water_detected == 1) {
            printf("Water detected\n");
            log_event("Water detected");
        }
        sleep(2);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

