#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define SAMPLE_INTERVAL 1000000 // 1 second in microseconds
#define PULSES_PER_REVOLUTION 1

volatile int pulse_count = 0;
FILE *log_file = NULL;

void gpio_callback(int gpio, int level, uint32_t tick) {
    if (level == PI_TIMEOUT) {
        return;
    }
    __atomic_add_fetch(&pulse_count, 1, __ATOMIC_SEQ_CST);
}

void log_rpm() {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

    int rpm = pulse_count * PULSES_PER_REVOLUTION * 60;
    fprintf(log_file, "%s %d\n", time_str, rpm);
    fflush(log_file);
    printf("%s %d\n", time_str, rpm);
}

void cleanup() {
    if (log_file) {
        fclose(log_file);
    }
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioTerminate();
    exit(0);
}

void signal_handler(int signum) {
    cleanup();
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up resistor on GPIO %d\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(GPIO_PIN, gpio_callback) < 0) {
        fprintf(stderr, "Failed to set GPIO %d alert function\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if ((log_file = fopen("rpm_log.txt", "a")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        gpioDelay(SAMPLE_INTERVAL);
        log_rpm();
        pulse_count = 0;
    }

    return EXIT_SUCCESS;
}

