#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <pthread.h>

#define SENSOR_A 17
#define SENSOR_B 27
#define LOG_FILE "rotation_log.txt"

volatile int sensor_a_state = 0;
volatile int sensor_b_state = 0;
volatile int direction = 0;
volatile int running = 1;

pthread_mutex_t state_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t state_cond = PTHREAD_COND_INITIALIZER;

void log_rotation(int direction) {
    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(log, "%04d-%02d-%02d %02d:%02d:%02d.%03d %s\n",
            tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
            tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec,
            (int)(now * 1000) % 1000,
            direction == 1 ? "CW" : "CCW");

    fclose(log);
}

void gpio_alert(int gpio, int level, uint32_t tick) {
    pthread_mutex_lock(&state_mutex);
    if (gpio == SENSOR_A) {
        sensor_a_state = level;
    } else if (gpio == SENSOR_B) {
        sensor_b_state = level;
    }

    if (sensor_a_state == 1 && sensor_b_state == 0) {
        direction = 1; // CW
    } else if (sensor_a_state == 0 && sensor_b_state == 1) {
        direction = -1; // CCW
    }

    pthread_cond_signal(&state_cond);
    pthread_mutex_unlock(&state_mutex);
}

void signal_handler(int sig) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(SENSOR_A, PI_INPUT);
    gpioSetMode(SENSOR_B, PI_INPUT);
    gpioSetPullUpDown(SENSOR_A, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR_B, PI_PUD_UP);

    gpioSetAlertFunc(SENSOR_A, gpio_alert);
    gpioSetAlertFunc(SENSOR_B, gpio_alert);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        pthread_mutex_lock(&state_mutex);
        while (direction == 0) {
            pthread_cond_wait(&state_cond, &state_mutex);
        }
        int detected_direction = direction;
        direction = 0;
        pthread_mutex_unlock(&state_mutex);

        log_rotation(detected_direction);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

