#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <libgpiod.h>
#include <unistd.h>

#define TOUCH_SENSOR_CHIP "gpiochip0"
#define TOUCH_SENSOR_LINE 17
#define LED_CHIP "gpiochip0"
#define LED_LINE 18
#define DEBOUNCE_TIME 50

static struct gpiod_chip *touch_chip = NULL;
static struct gpiod_line *touch_line = NULL;
static struct gpiod_chip *led_chip = NULL;
static struct gpiod_line *led_line = NULL;

static void cleanup_and_exit(int status) {
    if (touch_line) {
        gpiod_line_release(touch_line);
    }
    if (touch_chip) {
        gpiod_chip_close(touch_chip);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (led_chip) {
        gpiod_chip_close(led_chip);
    }
    exit(status);
}

static void signal_handler(int signum) {
    fprintf(stderr, "Received signal %d, cleaning up...\n", signum);
    cleanup_and_exit(EXIT_SUCCESS);
}

int main() {
    struct gpiod_line_request_config config;
    struct gpiod_line_event event;
    int ret;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip for touch sensor
    touch_chip = gpiod_chip_open_by_name(TOUCH_SENSOR_CHIP);
    if (!touch_chip) {
        perror("Failed to open GPIO chip for touch sensor");
        cleanup_and_exit(EXIT_FAILURE);
    }

    // Request line for touch sensor
    gpiod_line_request_config_init(&config);
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    config.consumer = "touch_sensor";
    touch_line = gpiod_chip_get_line(touch_chip, TOUCH_SENSOR_LINE);
    if (!touch_line) {
        perror("Failed to get line for touch sensor");
        cleanup_and_exit(EXIT_FAILURE);
    }
    ret = gpiod_line_request(touch_line, &config);
    if (ret < 0) {
        perror("Failed to request line for touch sensor");
        cleanup_and_exit(EXIT_FAILURE);
    }

    // Open GPIO chip for LED
    led_chip = gpiod_chip_open_by_name(LED_CHIP);
    if (!led_chip) {
        perror("Failed to open GPIO chip for LED");
        cleanup_and_exit(EXIT_FAILURE);
    }

    // Request line for LED
    gpiod_line_request_config_init(&config);
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    config.consumer = "led";
    config.default_val = 0; // Start with LED off
    led_line = gpiod_chip_get_line(led_chip, LED_LINE);
    if (!led_line) {
        perror("Failed to get line for LED");
        cleanup_and_exit(EXIT_FAILURE);
    }
    ret = gpiod_line_request(led_line, &config);
    if (ret < 0) {
        perror("Failed to request line for LED");
        cleanup_and_exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        // Wait for an event on the touch sensor line
        ret = gpiod_line_event_wait(touch_line, NULL);
        if (ret < 0) {
            perror("Failed to wait for line event");
            cleanup_and_exit(EXIT_FAILURE);
        }

        // Read the event
        ret = gpiod_line_event_read(touch_line, &event);
        if (ret < 0) {
            perror("Failed to read line event");
            cleanup_and_exit(EXIT_FAILURE);
        }

        // Check if it's a rising edge
        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            // Debounce
            usleep(DEBOUNCE_TIME * 1000);

            // Read the line state
            int value = gpiod_line_get_value(touch_line);
            if (value < 0) {
                perror("Failed to read line value");
                cleanup_and_exit(EXIT_FAILURE);
            }

            // Toggle LED if touched
            if (value == 1) {
                int current_value = gpiod_line_get_value(led_line);
                if (current_value < 0) {
                    perror("Failed to read LED line value");
                    cleanup_and_exit(EXIT_FAILURE);
                }
                gpiod_line_set_value(led_line, !current_value);
            }
        }
    }

    // This should never be reached
    cleanup_and_exit(EXIT_SUCCESS);
}

