#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define BUFFER_SIZE 100
#define DEBOUNCE_TIME 50

typedef struct {
    time_t timestamp;
    int sensor;
    int state;
} Event;

Event logBuffer[BUFFER_SIZE];
int logIndex = 0;
int logOverflow = 0;

void logEvent(int sensor, int state) {
    if (logIndex >= BUFFER_SIZE) {
        logOverflow++;
        logIndex = 0;
    }
    logBuffer[logIndex].timestamp = time(NULL);
    logBuffer[logIndex].sensor = sensor;
    logBuffer[logIndex].state = state;
    logIndex++;
}

void printLog() {
    for (int i = 0; i < BUFFER_SIZE; i++) {
        printf("%ld, %d, %d\n", logBuffer[i].timestamp, logBuffer[i].sensor, logBuffer[i].state);
    }
    printf("Overflow count: %d\n", logOverflow);
}

void cleanup() {
    gpioTerminate();
    printLog();
    exit(0);
}

void handleSignal(int sig) {
    cleanup();
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio library\n");
        return 1;
    }

    gpioSetMode(4, PI_INPUT);
    gpioSetMode(17, PI_INPUT);
    gpioSetMode(27, PI_OUTPUT);
    gpioSetMode(22, PI_OUTPUT);

    if (gpioRead(4) < 0 || gpioRead(17) < 0) {
        fprintf(stderr, "Failed to read GPIO pins\n");
        gpioTerminate();
        return 1;
    }

    gpioSetPullUpDown(4, PI_PUD_UP);
    gpioSetPullUpDown(17, PI_PUD_UP);

    signal(SIGINT, handleSignal);
    signal(SIGTERM, handleSignal);

    int lastState4 = gpioRead(4);
    int lastState17 = gpioRead(17);

    while (1) {
        int currentState4 = gpioRead(4);
        int currentState17 = gpioRead(17);

        if (currentState4 != lastState4) {
            if (currentState4 == 0) {
                gpioWrite(27, 1);
                logEvent(4, 1);
            } else {
                gpioWrite(27, 0);
                logEvent(4, 0);
            }
            lastState4 = currentState4;
        }

        if (currentState17 != lastState17) {
            if (currentState17 == 0) {
                gpioWrite(22, 1);
                logEvent(17, 1);
            } else {
                gpioWrite(22, 0);
                logEvent(17, 0);
            }
            lastState17 = currentState17;
        }

        gpioDelay(DEBOUNCE_TIME * 1000);
    }

    return 0;
}

