This code initializes the pigpio library, sets up the GPIO pins for the touch sensors and LEDs, and enters a loop to read the sensor states. It uses a 50 ms debounce time to filter out noise. When a touch is detected, it logs the event to a circular buffer and turns on the corresponding LED. The program handles SIGINT and SIGTERM signals to perform a graceful shutdown, turning off the LEDs and printing the log buffer contents.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define LOG_FILE "/var/log/rain_events.log"

volatile sig_atomic_t running = 1;

void log_event(const char *message) {
    FILE *log = fopen(LOG_FILE, "a");
    if (log == NULL) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    fprintf(log, "%s: %s\n", ctime(&now), message);
    fclose(log);
}

void signal_handler(int sig) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up resistor\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int last_state = gpioRead(GPIO_PIN);
    log_event(last_state ? "No Rain" : "Rain Detected");

    while (running) {
        int current_state = gpioRead(GPIO_PIN);
        if (current_state != last_state) {
            log_event(current_state ? "No Rain" : "Rain Detected");
            last_state = current_state;
        }
        gpioDelay(500 * 1000); // 500 ms
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

