#include <time.h>
#include <pigpio.h>

#define GPIO_SENSOR1 17
#define GPIO_SENSOR2 18
#define PULSE_PER_REV 2
#define DEBOUNCE_TIME 5  // in milliseconds

FILE *log_file = NULL;

void log_state(int sensor1, int sensor2) {
    if (log_file == NULL) {
        log_file = fopen("shaft_log.txt", "a");
        if (log_file == NULL) {
            perror("Failed to open log file");
            return;
        }
    }
    time_t now = time(NULL);
    fprintf(log_file, "%ld,%d,%d\n", now, sensor1, sensor2);
    fflush(log_file);
}

void signal_handler(int sig) {
