        int sensor2 = gpioRead(GPIO_SENSOR2);

        if (sensor1 != last_sensor1) {
            last_sensor1 = sensor1;
            pulse_count++;
        }

        if (sensor2 != last_sensor2) {
            last_sensor2 = sensor2;
            pulse_count++;
        }

        if (pulse_count >= PULSE_PER_REV) {
            time_t current_time = time(NULL);
