                int rpm = (pulse_count * 60) / PULSE_PER_REV;
                printf("RPM: %d\n", rpm);
                log_state(last_sensor1, last_sensor2);
                pulse_count = 0;
                last_time = current_time;
            }
        }

        gpioDelay(DEBOUNCE_TIME * 1000);
    }

