#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x28
#define PART_ID_REG 0x00
#define CONFIG_REG 0x30
#define HEART_RATE_REG 0x02
#define SPO2_REG 0x04
#define LOG_FILE "biometric_log.txt"

void log_data(int heart_rate, int spo2) {
    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(log, "%04d-%02d-%02d %02d:%02d:%02d, Heart Rate: %d BPM, SpO2: %d%%\n",
            tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
            tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec,
            heart_rate, spo2);
    fclose(log);
}

void handle_sigint(int sig) {
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    int i2c_handle = gpioI2COpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    uint8_t part_id;
    int rc = gpioI2CReadByte(i2c_handle, PART_ID_REG, &part_id);
    if (rc < 0) {
        fprintf(stderr, "Failed to read PART_ID register\n");
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (part_id != 0x42) {
        fprintf(stderr, "Invalid PART_ID: 0x%02X\n", part_id);
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t config = 0x01; // Continuous measurement mode
    rc = gpioI2CWriteByte(i2c_handle, CONFIG_REG, config);
    if (rc < 0) {
        fprintf(stderr, "Failed to write CONFIG register\n");
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        uint8_t heart_rate_data[2];
        rc = gpioI2CRead(i2c_handle, HEART_RATE_REG, heart_rate_data, 2);
        if (rc < 0) {
            fprintf(stderr, "Failed to read heart rate data\n");
        } else {
            int heart_rate = (heart_rate_data[0] << 8) | heart_rate_data[1];
            log_data(heart_rate, 0); // SpO2 data not available in this example
        }

        uint8_t spo2_data[2];
        rc = gpioI2CRead(i2c_handle, SPO2_REG, spo2_data, 2);
        if (rc < 0) {
            fprintf(stderr, "Failed to read SpO2 data\n");
        } else {
            int spo2 = (spo2_data[0] << 8) | spo2_data[1];
            log_data(0, spo2); // Heart rate data not available in this example
        }

        sleep(1);
    }

    gpioI2CClose(i2c_handle);
    gpioTerminate();
    return 0;
}

