volatile sig_atomic_t running = 1;

void log_event(const char *event) {
    FILE *log_file = fopen("bridge_integrity.log", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    char *iso_time = ctime(&now);
    iso_time[strlen(iso_time) - 1] = '\0'; // Remove newline
    fprintf(log_file, "%s: %s\n", iso_time, event);
    fclose(log_file);
}

void handle_signal(int sig) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(SENSOR1, PI_INPUT);
    gpioSetMode(SENSOR2, PI_INPUT);
    gpioSetPullUpDown(SENSOR1, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR2, PI_PUD_DOWN);
    gpioSetMode(ALARM, PI_OUTPUT);
    gpioWrite(ALARM, 0);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int sensor1_state = 0;
    int sensor2_state = 0;
    int alarm_active = 0;
    time_t last_alarm_time = 0;

    while (running) {
        int current_sensor1 = gpioRead(SENSOR1);
        int current_sensor2 = gpioRead(SENSOR2);

        if (current_sensor1 != sensor1_state) {
            sensor1_state = current_sensor1;
            if (sensor1_state) {
                log_event("Sensor 1 tilted");
            } else {
                log_event("Sensor 1 returned to normal");
            }
        }

        if (current_sensor2 != sensor2_state) {
            sensor2_state = current_sensor2;
            if (sensor2_state) {
                log_event("Sensor 2 tilted");
            } else {
                log_event("Sensor 2 returned to normal");
            }
        }

        if (current_sensor1 || current_sensor2) {
            if (!alarm_active) {
                alarm_active = 1;
                gpioWrite(ALARM, 1);
                log_event("Alarm activated");
            }
        } else {
            if (alarm_active) {
                alarm_active = 0;
                gpioWrite(ALARM, 0);
                log_event("Alarm deactivated");
            }
        }

        gpioDelay(POLL_INTERVAL);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

