This C program uses the pigpio library to monitor two tilt sensors connected to GPIO 17 and GPIO 18. It logs events to a file named `bridge_integrity.log` and activates an alarm (connected to GPIO 27) when either sensor is tilted beyond its threshold for more than 2 seconds. The program handles SIGINT and SIGTERM signals to ensure a clean shutdown, deactivating the alarm and closing the log file.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <signal.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1D
#define CTRL1_REG 0x1F
#define ACCEL_START_REG 0x28
#define ACCEL_SIZE 6
#define LED_PIN 17
#define THRESHOLD 500
#define RETRY_COUNT 3
#define LOG_FILE "seismic_events.log"

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int sig) {
    stop_flag = 1;
}

int read_sensor(int i2c_handle, uint8_t reg, uint8_t *data, size_t size) {
    int retries = RETRY_COUNT;
    while (retries--) {
        if (i2cReadDevice(i2c_handle, reg, data, size) == size) {
            return 0;
        }
        gpioDelay(10000); // 10 ms delay
    }
    return -1;
}

double calculate_magnitude(uint8_t *data) {
    int16_t x = (data[1] << 8) | data[0];
    int16_t y = (data[3] << 8) | data[2];
    int16_t z = (data[5] << 8) | data[4];
    return sqrt(x * x + y * y + z * z);
}

void log_event(double magnitude) {
    FILE *log = fopen(LOG_FILE, "a");
    if (log) {
        time_t now = time(NULL);
        char *iso_time = ctime(&now);
        iso_time[strlen(iso_time) - 1] = '\0'; // Remove newline
        fprintf(log, "%s, Peak Vibration: %.2f\n", iso_time, magnitude);
        fclose(log);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return 1;
    }

    uint8_t ctrl1_data = 0x00; // Clear power-down bit
    if (i2cWriteByteData(i2c_handle, CTRL1_REG, ctrl1_data) < 0) {
        fprintf(stderr, "Failed to write to CTRL1 register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioSetPullUpDown(LED_PIN, PI_PUD_OFF);

    signal(SIGINT, signal_handler);

    uint8_t accel_data[ACCEL_SIZE];
    double magnitude;

    while (!stop_flag) {
        if (read_sensor(i2c_handle, ACCEL_START_REG, accel_data, ACCEL_SIZE) == 0) {
            magnitude = calculate_magnitude(accel_data);
            if (magnitude > THRESHOLD) {
                gpioWrite(LED_PIN, 1);
                gpioDelay(1000000); // 1 second
                gpioWrite(LED_PIN, 0);
                log_event(magnitude);
            }
        }
        gpioDelay(100000); // 100 ms
    }

    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

