                gpioDelay(1000000); // 1 second
                gpioWrite(LED_PIN, 0);
                log_event(magnitude);
            }
        }
        gpioDelay(100000); // 100 ms
    }

    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}
