    out_line = gpiod_chip_get_line(chip, GPIO_OUT);
    if (!out_line) {
        perror("Failed to get output line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request(out_line, &out_config)) {
        perror("Failed to request output line");
        gpiod_line_release(out_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request input lines for sensors
    for (int i = 0; i < 4; i++) {
        in_lines[i] = gpiod_chip_get_line(chip, GPIO_IN1 + i);
