            perror("Failed to get input line");
            for (int j = 0; j < i; j++) {
                gpiod_line_release(in_lines[j]);
            }
            gpiod_line_release(out_line);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
        if (gpiod_line_request(in_lines[i], &in_config)) {
            perror("Failed to request input line");
            for (int j = 0; j <= i; j++) {
                gpiod_line_release(in_lines[j]);
            }
            gpiod_line_release(out_line);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    while (1) {
        int any_detected = 0;
        for (int i = 0; i < 4; i++) {
            int value = gpiod_line_get_value(in_lines[i]);
            if (value == 0) {
                any_detected = 1;
                break;
            }
        }
        gpiod_line_set_value(out_line, any_detected);
        usleep(POLL_INTERVAL * 1000);
    }

    // This line should never be reached
    return EXIT_SUCCESS;
