#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <libgpiod.h>

#define NUM_SENSORS 5
#define GPIO_PINS {2, 3, 4, 17, 27}
#define DEBOUNCE_TIME 50
#define LOG_FILE "/var/log/flame_events.log"

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

void log_event(const char *sensor_id, int pin) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        return;
    }

    if (flock(fileno(log_file), LOCK_EX) != 0) {
        syslog(LOG_ERR, "Failed to lock log file: %s", strerror(errno));
        fclose(log_file);
        return;
    }

    time_t now = time(NULL);
    char *iso_time = ctime(&now);
    iso_time[strlen(iso_time) - 1] = '\0'; // Remove newline

    fprintf(log_file, "%s - Sensor ID: %s (GPIO %d) - Flame Detected\n", iso_time, sensor_id, pin);
    fflush(log_file);
    flock(fileno(log_file), LOCK_UN);
    fclose(log_file);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[NUM_SENSORS];
    char sensor_ids[NUM_SENSORS][10] = {"S1", "S2", "S3", "S4", "S5"};
    int gpio_pins[NUM_SENSORS] = GPIO_PINS;
    int ret;

    openlog("flame_monitor", LOG_PID, LOG_USER);
    syslog(LOG_INFO, "Flame monitor started");

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpio_pins[i]);
        if (!lines[i]) {
            syslog(LOG_ERR, "Failed to get line %d: %s", gpio_pins[i], strerror(errno));
            gpiod_chip_close(chip);
            closelog();
            return EXIT_FAILURE;
        }

        ret = gpiod_line_request_input(lines[i], "flame_monitor");
        if (ret < 0) {
            syslog(LOG_ERR, "Failed to request input for line %d: %s", gpio_pins[i], strerror(errno));
            gpiod_chip_close(chip);
            closelog();
            return EXIT_FAILURE;
        }
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!stop_flag) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int value = gpiod_line_get_value(lines[i]);
            if (value < 0) {
                syslog(LOG_ERR, "Failed to read line %d: %s", gpio_pins[i], strerror(errno));
                continue;
            }

            if (value == 0) {
                log_event(sensor_ids[i], gpio_pins[i]);
            }
        }

        sleep(1);
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        gpiod_line_release(lines[i]);
    }

    gpiod_chip_close(chip);
    closelog();

    return EXIT_SUCCESS;
}

