#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PINS {5, 6, 13, 19, 26, 12, 16, 20}
#define NUM_PINS 8
#define POLL_INTERVAL 50

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[NUM_PINS];
    int ret;
    int old_states[NUM_PINS] = {0};
    struct timespec ts;

    // Register signal handler for graceful shutdown
    signal(SIGINT, sigint_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request lines
    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_PINS[i]);
        if (!lines[i]) {
            perror("Failed to get line");
            goto cleanup;
        }

        ret = gpiod_line_request_input(lines[i], "touch_sensor");
        if (ret < 0) {
            perror("Failed to request input line");
            goto cleanup;
        }
    }

    // Main loop
    while (running) {
        for (int i = 0; i < NUM_PINS; i++) {
            ret = gpiod_line_get_value(lines[i]);
            if (ret < 0) {
                perror("Failed to read line");
                goto cleanup;
            }

            if (ret != old_states[i]) {
                old_states[i] = ret;
                clock_gettime(CLOCK_REALTIME, &ts);
                printf("%ld-%02ld-%02ldT%02ld:%02ld:%02ld.%09ld+00:00, GPIO%d: %s\n",
                       ts.tv_sec / 86400, (ts.tv_sec % 86400) / 3600, (ts.tv_sec % 3600) / 60,
                       ts.tv_sec % 60, ts.tv_nsec / 1000000, ts.tv_nsec % 1000000,
                       ret ? "TOUCHED" : "RELEASED", GPIO_PINS[i], ret ? "TOUCHED" : "RELEASED");
            }
        }

        usleep(POLL_INTERVAL * 1000);
    }

cleanup:
    for (int i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

