#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x10
#define CONFIG_REG 0x00
#define ALS_REG 0x04
#define LED_PIN 18
#define PWM_FREQ 1000
#define PWM_RANGE 100

void log_sample(int lux, int brightness, int error) {
    FILE *log_file = fopen("grow_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

    fprintf(log_file, "%s, %d lux, %d%% brightness, %d\n", timestamp, lux, brightness, error);
    fflush(log_file);
    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    uint16_t config_value = 0x0000; // ALS gain 1/8, ALS integration time 100 ms
    if (i2cWriteWordData(i2c_handle, CONFIG_REG, config_value) < 0) {
        fprintf(stderr, "Failed to write to config register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(LED_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, gpioTerminate);
    signal(SIGTERM, gpioTerminate);

    while (1) {
        uint16_t lux_raw = i2cReadWordData(i2c_handle, ALS_REG);
        if (lux_raw < 0) {
            fprintf(stderr, "Failed to read ALS register\n");
            log_sample(-1, -1, -1);
        } else {
            int lux = lux_raw * 0.0576;
            int brightness;
            if (lux < 100) {
                brightness = PWM_RANGE;
            } else if (lux < 500) {
                brightness = PWM_RANGE * 3 / 4;
            } else if (lux < 1000) {
                brightness = PWM_RANGE / 2;
            } else {
                brightness = PWM_RANGE / 4;
            }

            gpioSetPWMrange(LED_PIN, PWM_RANGE);
            gpioSetPWMdutycycle(LED_PIN, brightness);

            log_sample(lux, brightness, 0);
        }

        sleep(1);
    }

    return 0;
}

