        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(LED_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, gpioTerminate);
    signal(SIGTERM, gpioTerminate);

    while (1) {
        uint16_t lux_raw = i2cReadWordData(i2c_handle, ALS_REG);
        if (lux_raw < 0) {
            fprintf(stderr, "Failed to read ALS register\n");
            log_sample(-1, -1, -1);
        } else {
            int lux = lux_raw * 0.0576;
            int brightness;
            if (lux < 100) {
                brightness = PWM_RANGE;
            } else if (lux < 500) {
                brightness = PWM_RANGE * 3 / 4;
            } else if (lux < 1000) {
                brightness = PWM_RANGE / 2;
            } else {
                brightness = PWM_RANGE / 4;
            }

            gpioSetPWMrange(LED_PIN, PWM_RANGE);
            gpioSetPWMdutycycle(LED_PIN, brightness);

            log_sample(lux, brightness, 0);
        }

        sleep(1);
    }

    return 0;
}
```

This code initializes the pigpio library, opens the I2C bus, configures the VEML7700 sensor, sets up the LED pin for PWM control, and enters a loop to read the ambient light, calculate the lux value, determine the appropriate brightness, and log the data. It handles errors and cleans up resources on exit.

