#include <signal.h>

#define LED_PIN 17
#define TOUCH_PINS 8
#define TOUCH_GPIO_START 2
#define TOUCH_GPIO_END 9
#define DEBOUNCE_TIME 50
#define LOG_FILE "touch_log.txt"

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    for (int i = TOUCH_GPIO_START; i <= TOUCH_GPIO_END; i++) {
        gpioSetMode(i, PI_INPUT);
        gpioSetPullUpDown(i, PI_PUD_DOWN);
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int last_state[TOUCH_PINS] = {0};
    time_t now;
    struct tm *tm_info;

    while (running) {
        for (int i = 0; i < TOUCH_PINS; i++) {
            int current_state = gpioRead(TOUCH_GPIO_START + i);
            if (current_state != last_state[i]) {
                if (current_state == 1) {
                    time(&now);
                    tm_info = localtime(&now);
                    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d - Channel %d Touched\n",
                            tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
                            tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec, i + 1);
                    fflush(log_file);
                    gpioWrite(LED_PIN, 1);
                } else {
                    gpioWrite(LED_PIN, 0);
                }
                last_state[i] = current_state;
            }
        }
        gpioDelay(DEBOUNCE_TIME * 1000);
    }

    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

