#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define CONFIG_WORD 0xC810
#define CONVERSION_TIME 100
#define LOG_FILE "light_data.txt"

void log_light_data(double lux) {
    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
    fprintf(log, "%s, %.2f\n", timestamp, lux);
    fclose(log);
}

void handle_sigint(int sig) {
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    uint16_t config_word = htons(CONFIG_WORD);
    if (i2cWriteWordData(i2c_handle, CONFIG_REG, config_word) < 0) {
        fprintf(stderr, "Failed to write configuration to OPT3001\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        sleep(1);

        uint16_t result = i2cReadWordData(i2c_handle, RESULT_REG);
        if (result < 0) {
            fprintf(stderr, "Failed to read result from OPT3001\n");
            continue;
        }

        uint8_t exponent = (result >> 12) & 0x0F;
        uint16_t mantissa = result & 0x0FFF;
        double lux = mantissa * 0.01 * (1 << exponent);

        printf("Light: %.2f lux\n", lux);
        log_light_data(lux);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

