#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define ALERT_PIN 17
#define POLL_INTERVAL 500
#define LOG_FILE "fire_events.log"

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set mode for flame sensor pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ALERT_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for alert pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set signal handler for SIGINT\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int flame_detected = gpioRead(FLAME_SENSOR_PIN);
        if (flame_detected < 0) {
            fprintf(stderr, "Failed to read flame sensor pin\n");
        } else {
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            fprintf(log_file, "%s, Flame detected: %d\n", asctime(tm_info), flame_detected);
            fflush(log_file);

            if (flame_detected == 0) {
                gpioWrite(ALERT_PIN, 1);
                gpioDelay(1000000); // 1 second
                gpioWrite(ALERT_PIN, 0);
            }
        }

        gpioDelay(POLL_INTERVAL * 1000);
    }

    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

