#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 4
#define DEBOUNCE_INTERVAL 50
#define LOG_FILE "touch_log.txt"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;

void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file);
}

void handle_signal(int sig) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(sig == SIGINT ? 0 : 1);
}

int main() {
    struct gpiod_line_request req = {
        .consumer = "touch_sensor",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
        .default_val = 0,
        .flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN,
    };

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request(line, &req)) {
        fprintf(stderr, "Failed to request GPIO line\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int last_state = 0;
    while (1) {
        int current_state = gpiod_line_get_value(line);
        if (current_state != last_state) {
            if (current_state) {
                log_event("Touch Detected");
            } else {
                log_event("Touch Released");
            }
            last_state = current_state;
        }
        usleep(DEBOUNCE_INTERVAL * 1000);
    }

    return 0;
}

