This C program uses the libgpiod library to read capacitive touch events from a TTP223 touch sensor connected to GPIO4 on a Raspberry Pi 5. It configures the GPIO line as an input with a pull-down bias, polls the line with a debounce interval of 50 ms, and logs touch events to a text file in the specified format. The program handles SIGINT and SIGTERM for graceful shutdown and releases all resources before exiting.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x08
#define I2C_CMD 0x3608
#define I2C_READ_LEN 3
#define CRC_POLY 0x31
#define CRC_INIT 0xFF
#define MIN_FLOW 0.0
#define MAX_FLOW 100.0

volatile sig_atomic_t stop_flag = 0;

void sigint_handler(int signum) {
    stop_flag = 1;
}

uint8_t calculate_crc(uint8_t *data, size_t len) {
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("cooling_log.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (fseek(log_file, 0, SEEK_END) != 0 || ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Flow Rate (ml/min),Status\n");
    }

    signal(SIGINT, sigint_handler);

    while (!stop_flag) {
        if (i2cWriteWordData(i2c_handle, I2C_CMD >> 8, I2C_CMD & 0xFF) < 0) {
            fprintf(stderr, "Failed to send I2C command\n");
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to re-open I2C bus %d\n", I2C_BUS);
                fclose(log_file);
                gpioTerminate();
                return EXIT_FAILURE;
            }
            continue;
        }

        uint8_t data[I2C_READ_LEN];
        if (i2cReadDevice(i2c_handle, data, I2C_READ_LEN) != I2C_READ_LEN) {
            fprintf(stderr, "Failed to read I2C data\n");
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to re-open I2C bus %d\n", I2C_BUS);
                fclose(log_file);
                gpioTerminate();
                return EXIT_FAILURE;
