#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <stdbool.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINES "17,27,22"
#define LOG_FILE "path_log.csv"

static struct gpiod_chip *chip;
static struct gpiod_line *lines[3];
static FILE *log_file;

static void cleanup(int sig) {
    for (int i = 0; i < 3; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    struct timespec ts;
    char timestamp[20];
    char line_state[4];

    // Register signal handler for SIGINT
    signal(SIGINT, cleanup);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request the GPIO lines
    for (int i = 0; i < 3; i++) {
        lines[i] = gpiod_chip_get_line(chip, i + 1);
        if (!lines[i]) {
            perror("Failed to get GPIO line");
            cleanup(EXIT_FAILURE);
        }
        if (gpiod_line_request_input(lines[i], "obstacle_sensor")) {
            perror("Failed to request GPIO line as input");
            cleanup(EXIT_FAILURE);
        }
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup(EXIT_FAILURE);
    }

    // Write header to log file
    fprintf(log_file, "timestamp,left,middle,right\n");

    // Main loop
    while (true) {
        // Get current time
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("Failed to get current time");
            cleanup(EXIT_FAILURE);
        }

        // Format timestamp
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", localtime(&ts.tv_sec));

        // Read line states
        for (int i = 0; i < 3; i++) {
            int state = gpiod_line_get_value(lines[i]);
            if (state == -1) {
                perror("Failed to read GPIO line state");
                cleanup(EXIT_FAILURE);
            }
            line_state[i] = state + '0';
        }
        line_state[3] = '\0';

        // Write to log file
        fprintf(log_file, "%s,%s,%s,%s\n", timestamp, line_state, line_state + 1, line_state + 2);
        fflush(log_file);

        // Sleep for 50 ms
        usleep(50000);
    }

    // This should never be reached
    cleanup(EXIT_FAILURE);
    return EXIT_SUCCESS;
}

