#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 4
#define LOG_FILE "flame_events.txt"

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static FILE *log_fp;

void log_event(const char *message) {
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

    fprintf(log_fp, "%s: %s\n", timestamp, message);
    fflush(log_fp);
}

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, exiting...\n", signum);
        if (line) {
            gpiod_line_release(line);
        }
        if (chip) {
            gpiod_chip_close(chip);
        }
        if (log_fp) {
            fclose(log_fp);
        }
        exit(signum);
    }
}

int main() {
    struct gpiod_line_request_config config = {
        .consumer = "flame_sensor",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
        .default_val = 1,
        .flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP,
    };

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open log file
    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        fclose(log_fp);
        return EXIT_FAILURE;
    }

    // Request GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        fclose(log_fp);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(line, &config) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        fclose(log_fp);
        return EXIT_FAILURE;
    }

    printf("Flame sensor monitoring started on GPIO%d...\n", GPIO_LINE);

    while (1) {
        int value = gpiod_line_get_value(line);
        if (value == 0) {
            printf("Flame detected at %s\n", ctime(NULL));
            log_event("Flame detected");
        }
        sleep(1); // Poll every second
    }

    // This point should never be reached
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(log_fp);
    return EXIT_SUCCESS;
}

