int main() {
    struct gpiod_line_request_config config = {
        .consumer = "touch_sensor",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
        .default_val = 0,
    };

    // Open GPIO chip
    chip = gpiod_chip_open_by_path(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request touch line
    touch_line = gpiod_chip_get_line(chip, GPIO_TOUCH_LINE);
    if (!touch_line) {
        perror("Failed to get touch line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(touch_line, &config) < 0) {
        perror("Failed to request touch line");
        gpiod_line_release(touch_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request LED line
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    config.default_val = 0;
    led_line = gpiod_chip_get_line(chip, GPIO_LED_LINE);
    if (!led_line) {
        perror("Failed to get LED line");
        gpiod_line_release(touch_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(led_line, &config) < 0) {
        perror("Failed to request LED line");
        gpiod_line_release(touch_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(led_line);
        gpiod_line_release(touch_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int touch_state = 0;
    while (1) {
        int ret = gpiod_line_event_wait(touch_line, 1000);
        if (ret < 0) {
            perror("Failed to wait for line event");
            break;
        }

        struct gpiod_line_event event;
        if (gpiod_line_event_read(touch_line, &event) < 0) {
            perror("Failed to read line event");
            break;
        }

        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            touch_state = !touch_state;
            gpiod_line_set_value(led_line, touch_state);
            log_event(touch_state);
        }
    }

    // Clean up
    fclose(log_file);
    gpiod_line_release(led_line);
    gpiod_line_release(touch_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

