        fclose(log_file);
        return 1;
    }

    flame_sensor_line = gpiod_chip_get_line(chip, FLAME_SENSOR_LINE);
    if (!flame_sensor_line) {
        perror("Failed to get flame sensor line");
        gpiod_chip_close(chip);
        fclose(log_file);
        return 1;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_LINE);
    if (!buzzer_line) {
        perror("Failed to get buzzer line");
        gpiod_line_release(flame_sensor_line);
        gpiod_chip_close(chip);
        fclose(log_file);
        return 1;
    }

    if (gpiod_line_request_input(flame_sensor_line, "flame_sensor") < 0) {
        perror("Failed to request input for flame sensor line");
        gpiod_line_release(flame_sensor_line);
        gpiod_chip_close(chip);
        fclose(log_file);
        return 1;
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        perror("Failed to request output for buzzer line");
        gpiod_line_release(flame_sensor_line);
        gpiod_chip_close(chip);
        fclose(log_file);
        return 1;
    }

    int last_value = gpiod_line_get_value(flame_sensor_line);
    while (1) {
        for (int i = 0; i < POLL_INTERVAL / SLICE_DURATION; i++) {
            usleep(SLICE_DURATION);
            if (gpiod_line_get_value(flame_sensor_line) != last_value) {
                if (last_value == 0 && gpiod_line_get_value(flame_sensor_line) == 1) {
                    log_event("Flame detected");
                    buzzer_on();
                    for (int j = 0; j < BUZZER_DURATION / SLICE_DURATION; j++) {
                        usleep(SLICE_DURATION);
                    }
                    buzzer_off();
                }
                last_value = gpiod_line_get_value(flame_sensor_line);
            }
        }
    }

    log_event("System stopped");
    gpiod_line_release(flame_sensor_line);
    gpiod_line_release(buzzer_line);
    gpiod_chip_close(chip);
    fclose(log_file);
    return 0;
}

