#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_INPUT 4
#define GPIO_OUTPUT 17
#define DEBOUNCE_TIME 200
#define POLL_INTERVAL 10

volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    if (gpioSetMode(GPIO_INPUT, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", GPIO_INPUT);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(GPIO_OUTPUT, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", GPIO_OUTPUT);
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen("touch_log.txt", "a");
    if (!log_file) {
        perror("Failed to open touch_log.txt");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int last_state = gpioRead(GPIO_INPUT);
    int last_time = gpioTick();

    while (running) {
        int current_state = gpioRead(GPIO_INPUT);
        int current_time = gpioTick();

        if (current_state != last_state) {
            int time_since_last = current_time - last_time;
            if (time_since_last > DEBOUNCE_TIME) {
                if (current_state == 1) {
                    gpioWrite(GPIO_OUTPUT, !gpioRead(GPIO_OUTPUT));
                    time_t now = time(NULL);
                    char buffer[20];
                    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S%z", gmtime(&now));
                    fprintf(log_file, "%s - LED toggled\n", buffer);
                    fflush(log_file);
                }
            }
            last_state = current_state;
            last_time = current_time;
        }

        gpioDelay(POLL_INTERVAL * 1000);
    }

    fclose(log_file);
    gpioTerminate();
    return 0;
}

