#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_PINS {4, 17, 27}
#define DELAY_US 100000
#define LOG_FILE "magnet_log.txt"

void log_state_change(int sensor, int state) {
    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }
    time_t now = time(NULL);
    char *iso_time = ctime(&now);
    iso_time[strlen(iso_time) - 1] = '\0'; // Remove newline
    fprintf(log, "%s, Sensor %d: %s\n", iso_time, sensor, state ? "Magnet Removed" : "Magnet Present");
    fclose(log);
}

void signal_handler(int sig) {
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    for (int i = 0; i < sizeof(GPIO_PINS) / sizeof(GPIO_PINS[0]); i++) {
        int gpio = GPIO_PINS[i];
        if (gpioSetMode(gpio, PI_INPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d to input mode\n", gpio);
            gpioTerminate();
            return 1;
        }
        if (gpioSetPullUpDown(gpio, PI_PUD_UP) != 0) {
            fprintf(stderr, "Failed to set GPIO %d pull-up\n", gpio);
            gpioTerminate();
            return 1;
        }
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int initial_states[3] = {0};
    for (int i = 0; i < sizeof(GPIO_PINS) / sizeof(GPIO_PINS[0]); i++) {
        initial_states[i] = gpioRead(GPIO_PINS[i]);
    }

    while (1) {
        for (int i = 0; i < sizeof(GPIO_PINS) / sizeof(GPIO_PINS[0]); i++) {
            int state = gpioRead(GPIO_PINS[i]);
            if (state != initial_states[i]) {
                log_state_change(GPIO_PINS[i], state);
                initial_states[i] = state;
            }
        }
        gpioDelay(DELAY_US);
    }

    gpioTerminate();
    return 0;
}

