#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x4A
#define PART_ID 0x00
#define HW_REV 0x01
#define LED_CURRENT 0x3F
#define AVERAGING 0x04
#define ENABLE 0x01
#define BPM_REG 0x2A
#define SAMPLES 5

void log_bpm(int bpm) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char buffer[20];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(stderr, "%s,%d\n", buffer, bpm);
    fflush(stderr);
}

void log_error(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
    exit(EXIT_FAILURE);
}

int main() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio");
    }

    int i2c_handle = gpioI2COpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
    }

    uint8_t part_id = gpioI2CReadByteData(i2c_handle, PART_ID);
    uint8_t hw_rev = gpioI2CReadByteData(i2c_handle, HW_REV);
    if (part_id != 0x02 || hw_rev != 0x01) {
        log_error("Sensor not found or wrong version");
    }

    gpioI2CWriteByteData(i2c_handle, LED_CURRENT, 0x10);
    gpioI2CWriteByteData(i2c_handle, AVERAGING, 0x01);
    gpioI2CWriteByteData(i2c_handle, ENABLE, 0x01);

    int bpm_values[SAMPLES] = {0};
    int index = 0;

    signal(SIGINT, [](int sig) {
        gpioTerminate();
        exit(EXIT_SUCCESS);
    });

    while (1) {
        int bpm_raw = gpioI2CReadWordData(i2c_handle, BPM_REG);
        if (bpm_raw < 0) {
            log_error("I2C read error");
            continue;
        }

        int bpm = bpm_raw * 0.5;
        bpm_values[index] = bpm;
        index = (index + 1) % SAMPLES;

        int sum = 0;
        for (int i = 0; i < SAMPLES; i++) {
            sum += bpm_values[i];
        }

        int avg_bpm = sum / SAMPLES;
        if (avg_bpm >= 30 && avg_bpm <= 220) {
            log_bpm(avg_bpm);
        }
    }

    gpioI2CClose(i2c_handle);
    gpioTerminate();
    return 0;
}

