#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINES "5,6,7,8,9,10,11,12"
#define GPIO_OUTPUT "17,18,19,20,21,22,23,24"
#define LOG_FILE "touch_log.txt"
#define STABILIZATION_DELAY 200
#define POLL_INTERVAL 10

struct gpio_state {
    struct gpiod_chip *chip;
    struct gpiod_line_bulk lines;
    struct gpiod_line_bulk outputs;
    int prev_states[8];
    int counter;
    FILE *log_file;
};

void log_event(const char *channel, int counter) {
    time_t now = time(NULL);
    struct tm *tm = gmtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(stdout, "Touch on channel %s | Counter: %d\n", channel, counter);
    if (log_file) {
        fprintf(log_file, "%s, Channel: %s, Counter: %d\n", timestamp, channel, counter);
        fflush(log_file);
    }
}

void handle_signal(int sig) {
    struct gpio_state *state = (struct gpio_state *)sig;
    for (int i = 0; i < 8; i++) {
        gpiod_line_set_value(state->outputs.lines[i], 0);
    }
    gpiod_line_bulk_release(&state->outputs);
    gpiod_chip_close(state->chip);
    if (log_file) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    struct gpio_state state = {0};
    struct gpiod_line_request_config config = {
        .consumer = "touch_counter",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
    };
    struct gpiod_line_request_config output_config = {
        .consumer = "touch_counter",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT,
    };

    state.chip = gpiod_chip_open(GPIO_CHIP);
    if (!state.chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    if (gpiod_chip_get_lines_bulk(state.chip, GPIO_LINES, &state.lines) < 0) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        gpiod_chip_close(state.chip);
        return 1;
    }

    if (gpiod_chip_get_lines_bulk(state.chip, GPIO_OUTPUT, &state.outputs) < 0) {
        fprintf(stderr, "Failed to get GPIO output lines: %s\n", strerror(errno));
        gpiod_line_bulk_release(&state.lines);
        gpiod_chip_close(state.chip);
        return 1;
    }

    for (int i = 0; i < 8; i++) {
        state.prev_states[i] = 0;
    }
    state.counter = 0;

    state.log_file = fopen(LOG_FILE, "a");
    if (!state.log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
    }

    signal(SIGINT, (void (*)(int))handle_signal);
    signal(SIGTERM, (void (*)(int))handle_signal);

    usleep(STABILIZATION_DELAY * 1000);

    while (1) {
        for (int i = 0; i < 8; i++) {
            int value = gpiod_line_get_value(state.lines.lines[i]);
            if (value == -1) {
                fprintf(stderr, "Failed to read GPIO line %d: %s\n", i, strerror(errno));
                continue;
            }

            if (value && !state.prev_states[i]) {
                state.counter = (state.counter + 1) % 256;
                log_event(strdup_printf("Channel %d", i + 1), state.counter);
                for (int j = 0; j < 8; j++) {
                    gpiod_line_set_value(state.outputs.lines[j], (state.counter >> j) & 1);
                }
            }
            state.prev_states[i] = value;
        }
        usleep(POLL_INTERVAL * 1000);
    }

    return 0;
}

