#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINES "17,18,27,22"
#define CSV_FILE "tracking_log.csv"

static struct gpiod_chip *chip;
static struct gpiod_line *lines[4];
static FILE *csv_file;

static void handle_sigint(int sig) {
    for (int i = 0; i < 4; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);
    fclose(csv_file);
    exit(0);
}

int main() {
    struct timespec ts;
    char timestamp[20];
    char line_state[5];

    // Initialize signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request GPIO lines
    for (int i = 0; i < 4; i++) {
        lines[i] = gpiod_chip_get_line(chip, i + 17);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d\n", i + 17);
            goto cleanup;
        }
        if (gpiod_line_request_input(lines[i], "tracking_module")) {
            fprintf(stderr, "Failed to request GPIO line %d as input\n", i + 17);
            goto cleanup;
        }
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (!csv_file) {
        fprintf(stderr, "Failed to open CSV file\n");
        goto cleanup;
    }

    // Write header if file is empty
    if (fseek(csv_file, 0, SEEK_END) == 0 && ftell(csv_file) == 0) {
        fprintf(csv_file, "timestamp,sensor1,sensor2,sensor3,sensor4\n");
    }

    // Main loop
    while (1) {
        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        for (int i = 0; i < 4; i++) {
            int value = gpiod_line_get_value(lines[i]);
            if (value < 0) {
                fprintf(stderr, "Failed to read GPIO line %d\n", i + 17);
                continue;
            }
            snprintf(line_state + i * 2, 3, "%d", value);
        }

        fprintf(csv_file, "%s,%s,%s,%s,%s\n", timestamp, line_state, line_state + 2, line_state + 4, line_state + 6);
        fflush(csv_file);

        usleep(100000); // 100 ms
    }

cleanup:
    for (int i = 0; i < 4; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    gpiod_chip_close(chip);
    if (csv_file) {
        fclose(csv_file);
    }
    return EXIT_FAILURE;
}

