#define GPIO_LINES "17,18"
#define DEBOUNCE_TIME 50
#define POLL_INTERVAL 100

static struct gpiod_chip *chip;
static struct gpiod_line *lines[2];
static FILE *log_file;

void log_event(int sensor, int state) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, Sensor %d tilted\n",
            tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
            tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec, sensor);
    fflush(log_file);
}

void handle_signal(int sig) {
    for (int i = 0; i < 2; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    struct gpiod_line_request_config config = {
        .consumer = "tilt_sensor_monitor",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
        .default_val = 1,
        .flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP,
    };

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 2; i++) {
        lines[i] = gpiod_chip_get_line(chip, i + 17);
        if (!lines[i]) {
            perror("Failed to get GPIO line");
            for (int j = 0; j < i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            fclose(log_file);
            return EXIT_FAILURE;
        }

        if (gpiod_line_request(lines[i], &config)) {
            perror("Failed to request GPIO line");
            for (int j = 0; j <= i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            fclose(log_file);
            return EXIT_FAILURE;
        }
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int last_state[2] = {1, 1};
    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);

    while (1) {
        for (int i = 0; i < 2; i++) {
            int state = gpiod_line_get_value(lines[i]);
            if (state == -1) {
                perror("Failed to read GPIO line");
                handle_signal(0);
            }

            if (state != last_state[i]) {
                clock_gettime(CLOCK_MONOTONIC, &end);
                if (end.tv_sec - start.tv_sec > DEBOUNCE_TIME / 1000.0) {
                    log_event(i + 1, state);
                    last_state[i] = state;
                    start = end;
                }
            }
        }

        usleep(POLL_INTERVAL * 1000);
    }

    return EXIT_SUCCESS;
}
