        gpiod_line_release(sensor1_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set the LED line as output
    if (gpiod_line_request_output(led_line, "obstacle_led", 0) < 0) {
        perror("Failed to request LED line as output");
        gpiod_line_release(sensor2_line);
        gpiod_line_release(sensor1_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set the sensor lines as input
    if (gpiod_line_request_input(sensor1_line, "obstacle_sensor1") < 0) {
        perror("Failed to request Sensor1 line as input");
        gpiod_line_release(sensor2_line);
        gpiod_line_release(sensor1_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(sensor2_line, "obstacle_sensor2") < 0) {
        perror("Failed to request Sensor2 line as input");
        gpiod_line_release(sensor2_line);
        gpiod_line_release(sensor1_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(sensor2_line);
        gpiod_line_release(sensor1_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Write the header to the log file
    fprintf(log_file, "timestamp,sensor1,sensor2,led_state\n");

    while (1) {
        // Read the sensor states
        sensor1_state = gpiod_line_get_value(sensor1_line);
        sensor2_state = gpiod_line_get_value(sensor2_line);

        // Determine the LED state
        led_state = (sensor1_state == 0 && sensor2_state == 0) ? 1 : 0;

        // Set the LED state
        gpiod_line_set_value(led_line, led_state);

        // Get the current timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
        } else {
            strcpy(timestamp, "N/A");
        }

        // Write the sample to the log file
        fprintf(log_file, "%s,%d,%d,%d\n", timestamp, sensor1_state, sensor2_state, led_state);
        fflush(log_file);

        // Sleep for 100 ms
        usleep(100000);
    }

    // This point should never be reached
    return EXIT_SUCCESS;
}

