#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define MIC_PIN 4
#define LED_PIN 17
#define SAMPLE_PERIOD_US 125
#define LED_DURATION_MS 100

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio library\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MIC_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", MIC_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(LED_PIN, 0); // Ensure LED is off initially

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set signal handler for SIGINT\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);

    while (!stop_flag) {
        int mic_value = gpioRead(MIC_PIN);
        if (mic_value < 0) {
            fprintf(stderr, "Failed to read GPIO%d\n", MIC_PIN);
            break;
        }

        if (mic_value == 1) {
            clock_gettime(CLOCK_MONOTONIC, &end);
            long ms = (end.tv_sec - start.tv_sec) * 1000 + (end.tv_nsec - start.tv_nsec) / 1000000;
            printf("Sound peak detected at %ld ms\n", ms);

            gpioWrite(LED_PIN, 1);
            gpioDelay(100000 * LED_DURATION_MS); // 100 ms
            gpioWrite(LED_PIN, 0);
        }

        gpioDelay(1000 * SAMPLE_PERIOD_US); // 125 us
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

