    struct gpiod_line_request_config config = {
        .consumer = "sensor_reader",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
        .flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP,
    };

    // Register signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request lines
    left_line = gpiod_chip_get_line(chip, GPIO_LEFT);
    if (!left_line) {
        perror("Failed to get left line");
        cleanup();
        return EXIT_FAILURE;
    }

    center_line = gpiod_chip_get_line(chip, GPIO_CENTER);
    if (!center_line) {
        perror("Failed to get center line");
        cleanup();
        return EXIT_FAILURE;
    }

    right_line = gpiod_chip_get_line(chip, GPIO_RIGHT);
    if (!right_line) {
        perror("Failed to get right line");
        cleanup();
        return EXIT_FAILURE;
    }

    // Request lines with configuration
    if (gpiod_line_request(left_line, &config) < 0) {
        perror("Failed to request left line");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(center_line, &config) < 0) {
        perror("Failed to request center line");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(right_line, &config) < 0) {
        perror("Failed to request right line");
        cleanup();
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        int left_state = gpiod_line_get_value(left_line);
        int center_state = gpiod_line_get_value(center_line);
        int right_state = gpiod_line_get_value(right_line);

        if (left_state < 0 || center_state < 0 || right_state < 0) {
            perror("Failed to read sensor states");
            cleanup();
            return EXIT_FAILURE;
        }

        printf("Left: %d, Center: %d, Right: %d\n", left_state, center_state, right_state);

        usleep(DELAY_MS * 1000);
    }

    return EXIT_SUCCESS;
