code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define SI1175_ADDR 0x49
#define ALS_LSB 0x24
#define ALS_MSB 0x25
#define READ_INTERVAL 100  // 100 ms

void handle_error(const char *message) {
    perror(message);
    exit(EXIT_FAILURE);
}

void close_i2c(int fd) {
    if (fd >= 0) {
        close(fd);
    }
}

void signal_handler(int signum) {
    printf("Caught signal %d, exiting...\n", signum);
    exit(EXIT_SUCCESS);
}

int main() {
    int fd;
    uint8_t buffer[2];
    uint16_t als_value;
    struct sigaction sa;

    // Set up signal handler for Ctrl+C
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        handle_error("Failed to set signal handler");
    }

    // Open I2C bus
    if ((fd = open(I2C_BUS, O_RDWR)) < 0) {
        handle_error("Failed to open I2C bus");
    }

    // Set I2C slave address
    if (ioctl(fd, I2C_SLAVE, SI1175_ADDR) < 0) {
        close_i2c(fd);
        handle_error("Failed to set I2C slave address");
    }

    while (1) {
        // Read ALS LSB
        if (read(fd, buffer, 1) != 1) {
            close_i2c(fd);
            handle_error("Failed to read ALS LSB");
        }

        // Read ALS MSB
        if (read(fd, buffer + 1, 1) != 1) {
            close_i2c(fd);
            handle_error("Failed to read ALS MSB");
        }

        // Combine LSB and MSB into a 16-bit value
        als_value = (buffer[1] << 8) | buffer[0];

        // Log the raw sensor value
        printf("ALS Value: 0x%04X\n", als_value);

        // Wait for 100 ms
        usleep(READ_INTERVAL * 1000);
    }

    close_i2c(fd);
    return 0;
}

