#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINES {2, 3, 4}
#define POLL_INTERVAL 100

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[3];
    int ret;

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Get the lines
    for (int i = 0; i < 3; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_LINES[i]);
        if (!lines[i]) {
            perror("Failed to get GPIO line");
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    // Request the lines as input
    for (int i = 0; i < 3; i++) {
        ret = gpiod_line_request_input(lines[i], "keywish_sensor");
        if (ret < 0) {
            perror("Failed to request GPIO line as input");
            for (int j = 0; j <= i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    // Poll and log sensor values
    while (running) {
        for (int i = 0; i < 3; i++) {
            int value = gpiod_line_get_value(lines[i]);
            if (value < 0) {
                perror("Failed to read GPIO line value");
                running = 0;
                break;
            }
            printf("L:%d M:%d R:%d\n", value, value, value);
        }
        usleep(POLL_INTERVAL * 1000);
    }

    // Release resources
    for (int i = 0; i < 3; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

