#include <gpiod.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINES "5,6,13,19,26,12,16,20"
#define POLL_INTERVAL_MS 200

static struct gpiod_chip *chip;
static struct gpiod_line *lines[8];
static int running = 1;

void handle_sigint(int sig) {
    running = 0;
}

void log_state(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    printf("[%ld.%03ld] ", ts.tv_sec, ts.tv_nsec / 1000000);
    for (int i = 0; i < 8; i++) {
        int value = gpiod_line_get_value(lines[i]);
        if (value < 0) {
            fprintf(stderr, "Failed to read line %d: %s\n", i, strerror(-value));
            exit(EXIT_FAILURE);
        }
        printf("CH%d=%d ", i + 1, value);
    }
    printf("\n");
}

int main(void) {
    struct gpiod_line_request_config config = {
        .consumer = "TTP226",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
    };

    // Open gpiochip0
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    // Request all 8 lines as inputs
    char *line_names[8] = {"5", "6", "13", "19", "26", "12", "16", "20"};
    for (int i = 0; i < 8; i++) {
        lines[i] = gpiod_chip_get_line(chip, atoi(line_names[i]));
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %s: %s\n", line_names[i], strerror(errno));
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        if (gpiod_line_request(lines[i], &config) < 0) {
            fprintf(stderr, "Failed to request line %s: %s\n", line_names[i], strerror(errno));
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    // Install signal handler for graceful shutdown
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        for (int i = 0; i < 8; i++) {
            gpiod_line_release(lines[i]);
        }
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        for (int i = 0; i < 8; i++) {
            gpiod_line_release(lines[i]);
        }
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Poll and log state
    while (running) {
        log_state();
        usleep(POLL_INTERVAL_MS * 1000);
    }

    // Release resources
    for (int i = 0; i < 8; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

