#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

#define RED_PIN 17
#define GREEN_PIN 18
#define BLUE_PIN 27
#define PWM_FREQ 1000
#define FADE_STEPS 50
#define FADE_INTERVAL 5

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

void hsv_to_rgb(float h, float s, float v, unsigned char *r, unsigned char *g, unsigned char *b) {
    if (s == 0) {
        *r = *g = *b = v * 255;
    } else {
        h = h * 6;
        int i = (int)h;
        float f = h - i;
        float p = v * (1 - s);
        float q = v * (1 - s * f);
        float t = v * (1 - s * (1 - f));
        switch (i % 6) {
            case 0: *r = v * 255; *g = t * 255; *b = p * 255; break;
            case 1: *r = q * 255; *g = v * 255; *b = p * 255; break;
            case 2: *r = p * 255; *g = v * 255; *b = t * 255; break;
            case 3: *r = p * 255; *g = q * 255; *b = v * 255; break;
            case 4: *r = t * 255; *g = p * 255; *b = v * 255; break;
            case 5: *r = v * 255; *g = p * 255; *b = q * 255; break;
        }
    }
}

int main() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        return 1;
    }

    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    gpioSetPWMfrequency(RED_PIN, PWM_FREQ);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ);
    gpioSetPWMfrequency(BLUE_PIN, PWM_FREQ);

    srand(time(NULL));
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        float h = (float)rand() / RAND_MAX;
        unsigned char r, g, b;
        hsv_to_rgb(h, 1.0, 1.0, &r, &g, &b);

        for (int i = 0; i <= FADE_STEPS; i++) {
            int red = 255 - (int)((float)i / FADE_STEPS * r);
            int green = 255 - (int)((float)i / FADE_STEPS * g);
            int blue = 255 - (int)((float)i / FADE_STEPS * b);
            gpioSetPWMrange(RED_PIN, 256);
            gpioSetPWMrange(GREEN_PIN, 256);
            gpioSetPWMrange(BLUE_PIN, 256);
            gpioSetPWMdutycycle(RED_PIN, red);
            gpioSetPWMdutycycle(GREEN_PIN, green);
            gpioSetPWMdutycycle(BLUE_PIN, blue);
            usleep(FADE_INTERVAL * 1000000 / FADE_STEPS);
        }
    }

    gpioSetPWMdutycycle(RED_PIN, 0);
    gpioSetPWMdutycycle(GREEN_PIN, 0);
    gpioSetPWMdutycycle(BLUE_PIN, 0);

    gpioTerminate();
    closelog();

    return 0;
}

