    uint8_t config[2] = {TCS34725_ATIME, TCS34725_CONTROL};
    if (write(i2c_fd, config, sizeof(config)) != sizeof(config)) {
        perror("Failed to set integration time and gain");
        cleanup();
        return EXIT_FAILURE;
    }

    // Verify sensor ID
    uint8_t id[1];
    if (read(i2c_fd, id, sizeof(id)) != sizeof(id)) {
        perror("Failed to read sensor ID");
        cleanup();
        return EXIT_FAILURE;
    }
    if (id[0] != 0x44) {
        fprintf(stderr, "Invalid sensor ID: 0x%02X\n", id[0]);
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        // Read sensor data
        uint16_t data[4];
        uint8_t buffer[8];
        if (read(i2c_fd, buffer, sizeof(buffer)) != sizeof(buffer)) {
            perror("Failed to read sensor data");
            // Attempt re-initialization
            if (write(i2c_fd, power_on, sizeof(power_on)) != sizeof(power_on)) {
                perror("Failed to power on sensor");
                cleanup();
                return EXIT_FAILURE;
            }
            if (write(i2c_fd, config, sizeof(config)) != sizeof(config)) {
                perror("Failed to set integration time and gain");
                cleanup();
                return EXIT_FAILURE;
            }
            continue;
        }
        data[0] = (buffer[1] << 8) | buffer[0];
        data[1] = (buffer[3] << 8) | buffer[2];
        data[2] = (buffer[5] << 8) | buffer[4];
        data[3] = (buffer[7] << 8) | buffer[6];

        // Apply calibration (example values, adjust as needed)
        uint16_t calibrate(uint16_t value) {
            return value * 1.1; // Example calibration factor
        }
        data[0] = calibrate(data[0]);
        data[1] = calibrate(data[1]);
        data[2] = calibrate(data[2]);
        data[3] = calibrate(data[3]);

        // Display calibrated values
        printf("C: %u, R: %u, G: %u, B: %u\n", data[0], data[1], data[2], data[3]);

        // Control LED
        if (data[1] > RED_THRESHOLD) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }

        // Poll every 200 ms
        usleep(200 * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

