#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define BH1750_I2C_ADDR 0x23
#define BH1750_CMD_ONE_TIME_HIGH_RES 0x20
#define BH1750_CONVERSION_TIME_MS 120
#define BH1750_LUX_RANGE_MIN 10
#define BH1750_LUX_RANGE_MAX 300
#define APA102_START_FRAME 0x00000000
#define APA102_END_FRAME 0xFFFFFFFF
#define APA102_BRIGHTNESS_MIN 0
#define APA102_BRIGHTNESS_MAX 31
#define SPI_CLOCK_FREQ 1000000

static int i2c_fd = -1;
static int spi_fd = -1;

void close_resources() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
}

void handle_sigint(int sig) {
    close_resources();
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open SPI device
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Set SPI mode and speed
    uint8_t mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    uint32_t speed = SPI_CLOCK_FREQ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize BH1750
    uint8_t cmd = BH1750_CMD_ONE_TIME_HIGH_RES;
    if (write(i2c_fd, &cmd, 1) != 1) {
        perror("Failed to write to BH1750");
        close(spi_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Wait for conversion to complete
    usleep(BH1750_CONVERSION_TIME_MS * 1000);

    // Read 2-byte lux value
    uint8_t lux_data[2];
    if (read(i2c_fd, lux_data, 2) != 2) {
        perror("Failed to read from BH1750");
        close(spi_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    uint16_t lux_raw = (lux_data[0] << 8) | lux_data[1];
    double lux = lux_raw / 1.2;

    // Map lux to APA102 brightness
    uint8_t brightness = (lux - BH1750_LUX_RANGE_MIN) * (APA102_BRIGHTNESS_MAX - APA102_BRIGHTNESS_MIN) / (BH1750_LUX_RANGE_MAX - BH1750_LUX_RANGE_MIN);
    if (brightness > APA102_BRIGHTNESS_MAX) {
        brightness = APA102_BRIGHTNESS_MAX;
    } else if (brightness < APA102_BRIGHTNESS_MIN) {
        brightness = APA102_BRIGHTNESS_MIN;
    }

    // Send APA102 frame
    uint32_t frame = APA102_START_FRAME;
    for (int i = 0; i < 16; i++) { // Assuming 16 LEDs
        frame |= (0xE0 | brightness) << (i * 8);
        frame |= 0x000000FF; // Blue, Green, Red
    }
    frame |= APA102_END_FRAME;

    uint8_t tx_buffer[4];
    for (int i = 0; i < 4; i++) {
        tx_buffer[i] = (frame >> (i * 8)) & 0xFF;
    }

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buffer,
        .rx_buf = 0,
        .len = 4,
        .speed_hz = SPI_CLOCK_FREQ,
        .delay_usecs = 0,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Failed to send APA102 frame");
        close(spi_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    close_resources();
    return EXIT_SUCCESS;
}

