#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define BH1750_ADDR_LOW 0x23
#define BH1750_ADDR_HIGH 0x5C
#define BH1750_CMD 0x21
#define BH1750_CONVERSION_TIME 180
#define APA102_MOSI 10
#define APA102_SCLK 11
#define APA102_BRIGHTNESS_MIN 0
#define APA102_BRIGHTNESS_MAX 31
#define FADE_TIME 500
#define LOOP_DELAY 100

volatile int running = 1;

void sigint_handler(int sig) {
    running = 0;
}

void set_apa102_brightness(int brightness) {
    uint8_t data[4];
    data[0] = 0x00; // Start frame
    data[1] = 0x00; // Global brightness
    data[2] = 0x00; // LED data
    data[3] = 0xFF; // End frame

    for (int i = 0; i < 4; i++) {
        data[1] = (data[1] & 0xF0) | (brightness & 0x0F);
        gpio_spi_write(0, data, 4);
        gpio_delay(100);
    }
}

int read_bh1750(int handle) {
    uint8_t data[2];
    if (gpio_i2c_read_device(handle, data, 2) != 2) {
        return -1;
    }
    return (data[0] << 8) | data[1];
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    int i2c_handles[2] = {-1, -1};
    int sensor_count = 0;

    for (int i = 0; i < 2; i++) {
        i2c_handles[i] = gpioI2COpen(I2C_BUS, BH1750_ADDR_LOW + i, 0);
        if (i2c_handles[i] < 0) {
            fprintf(stderr, "Failed to open BH1750 sensor at address 0x%02X\n", BH1750_ADDR_LOW + i);
        } else {
            gpioI2CWriteByte(i2c_handles[i], BH1750_CMD);
            gpioDelay(BH1750_CONVERSION_TIME * 1000);
            sensor_count++;
        }
    }

    if (sensor_count == 0) {
        fprintf(stderr, "No BH1750 sensors found\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);

    int spi_handle = gpioSpiOpen(0, APA102_MOSI, APA102_SCLK, 1000000);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI handle\n");
        for (int i = 0; i < 2; i++) {
            if (i2c_handles[i] >= 0) {
                gpioI2CClose(i2c_handles[i]);
            }
        }
        gpioTerminate();
        return 1;
    }

    int current_brightness = APA102_BRIGHTNESS_MAX;
    int target_brightness = APA102_BRIGHTNESS_MAX;

    while (running) {
        int lux_sum = 0;
        int lux_count = 0;

        for (int i = 0; i < sensor_count; i++) {
            int lux = read_bh1750(i2c_handles[i]);
            if (lux >= 0) {
                lux_sum += lux;
                lux_count++;
            }
        }

        if (lux_count > 0) {
            target_brightness = APA102_BRIGHTNESS_MAX - (lux_sum / lux_count) / 100;
            if (target_brightness < APA102_BRIGHTNESS_MIN) {
                target_brightness = APA102_BRIGHTNESS_MIN;
            }
        }

        if (target_brightness != current_brightness) {
            int steps = FADE_TIME / LOOP_DELAY;
            for (int i = 0; i <= steps; i++) {
                int new_brightness = current_brightness + (target_brightness - current_brightness) * i / steps;
                set_apa102_brightness(new_brightness);
                gpioDelay(LOOP_DELAY * 1000);
            }
            current_brightness = target_brightness;
        }

        gpioDelay(LOOP_DELAY * 1000);
    }

    set_apa102_brightness(APA102_BRIGHTNESS_MIN);
    for (int i = 0; i < 2; i++) {
        if (i2c_handles[i] >= 0) {
            gpioI2CClose(i2c_handles[i]);
        }
    }
    gpioSpiClose(spi_handle);
    gpioTerminate();

    return 0;
}

