#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define FLAME_SENSOR_CHIP "gpiochip0"
#define FLAME_SENSOR_LINE 4
#define BUZZER_LINE 17
#define LED_LINE 18

#define SELF_TEST_BLINK_COUNT 2
#define SELF_TEST_INTERVAL_MS 100
#define SELF_TEST_FAILURE_PATTERN_LED_ON_MS 100
#define SELF_TEST_FAILURE_PATTERN_LED_OFF_MS 100
#define SELF_TEST_FAILURE_PATTERN_BUZZER_SHORT_MS 200
#define SELF_TEST_FAILURE_PATTERN_BUZZER_LONG_MS 600
#define SELF_TEST_FAILURE_PATTERN_REPETITIONS 3

#define MAIN_LOOP_INTERVAL_MS 50

#define LOG_FILE "flame_sensor.log"

struct gpiod_chip *chip;
struct gpiod_line *flame_sensor_line, *buzzer_line, *led_line;
FILE *log_file;

void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d: %s\n",
            tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
            tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec, event);
    fflush(log_file);
}

void signal_handler(int sig) {
    if (sig == SIGINT) {
        log_event("SIGINT received, cleaning up and exiting...");
        gpiod_line_release(flame_sensor_line);
        gpiod_line_release(buzzer_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        fclose(log_file);
        exit(0);
    }
}

int self_test() {
    int result = 1;
    log_event("Running self-test...");

    // Blink LED twice
    for (int i = 0; i < SELF_TEST_BLINK_COUNT; i++) {
        gpiod_line_set_value(led_line, 1);
        usleep(SELF_TEST_INTERVAL_MS * 1000);
        gpiod_line_set_value(led_line, 0);
        usleep(SELF_TEST_INTERVAL_MS * 1000);
    }

    // Read flame sensor 5 times
    for (int i = 0; i < 5; i++) {
        int value = gpiod_line_get_value(flame_sensor_line);
        if (value == 1) {
            log_event("Self-test failed: flame sensor not consistently LOW");
            goto cleanup;
        }
        usleep(SELF_TEST_INTERVAL_MS * 1000);
    }

    result = 0;
    log_event("Self-test passed");

cleanup:
    gpiod_line_set_value(buzzer_line, 0);
    gpiod_line_set_value(led_line, 0);
    return result;
}

void handle_flame_detection() {
    log_event("Flame detected");
    gpiod_line_set_value(buzzer_line, 1);
    gpiod_line_set_value(led_line, 1);
}

void handle_flame_gone() {
    log_event("Flame gone");
    gpiod_line_set_value(buzzer_line, 0);
    gpiod_line_set_value(led_line, 0);
}

void handle_error() {
    log_event("Error detected");
    for (int i = 0; i < SELF_TEST_FAILURE_PATTERN_REPETITIONS; i++) {
        // LED blinking rapidly
        for (int j = 0; j < 5; j++) {
            gpiod_line_set_value(led_line, 1);
            usleep(SELF_TEST_FAILURE_PATTERN_LED_ON_MS * 1000);
            gpiod_line_set_value(led_line, 0);
            usleep(SELF_TEST_FAILURE_PATTERN_LED_OFF_MS * 1000);
        }

        // Buzzer pattern
        gpiod_line_set_value(buzzer_line, 1);
        usleep(SELF_TEST_FAILURE_PATTERN_BUZZER_SHORT_MS * 1000);
        gpiod_line_set_value(buzzer_line, 0);
        usleep(SELF_TEST_FAILURE_PATTERN_BUZZER_SHORT_MS * 1000);
        gpiod_line_set_value(buzzer_line, 1);
        usleep(SELF_TEST_FAILURE_PATTERN_BUZZER_LONG_MS * 1000);
        gpiod_line_set_value(buzzer_line, 0);
        usleep(SELF_TEST_FAILURE_PATTERN_BUZZER_SHORT_MS * 1000);
    }
}

int main() {
    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open_by_name(FLAME_SENSOR_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    flame_sensor_line = gpiod_chip_get_line(chip, FLAME_SENSOR_LINE);
    if (!flame_sensor_line) {
        perror("Failed to get flame sensor line");
        gpiod_chip_close(chip);
        return 1;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_LINE);
    if (!buzzer_line) {
        perror("Failed to get buzzer line");
        gpiod_line_release(flame_sensor_line);
        gpiod_chip_close(chip);
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, LED_LINE);
    if (!led_line) {
        perror("Failed to get LED line");
        gpiod_line_release(flame_sensor_line);
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(flame_sensor_line, "flame_sensor", 0) < 0) {
        perror("Failed to request flame sensor line as output");
        gpiod_line_release(flame_sensor_line);
        gpiod_line_release(buzzer_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        perror("Failed to request buzzer line as output");
        gpiod_line_release(flame_sensor_line);
        gpiod_line_release(buzzer_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        perror("Failed to request LED line as output");
        gpiod_line_release(flame_sensor_line);
        gpiod_line_release(buzzer_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(flame_sensor_line);
        gpiod_line_release(buzzer_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (self_test() != 0) {
        handle_error();
        gpiod_line_release(flame_sensor_line);
        gpiod_line_release(buzzer_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        fclose(log_file);
        return 1;
    }

    while (1) {
        int value = gpiod_line_get_value(flame_sensor_line);
        if (value == 0) {
            handle_flame_detection();
        } else {
            handle_flame_gone();
        }
        usleep(MAIN_LOOP_INTERVAL_MS * 1000);
    }

    gpiod_line_release(flame_sensor_line);
    gpiod_line_release(buzzer_line);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    fclose(log_file);
    return 0;
}

