        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open LED GPIO
    if ((gpio_fd = open(LED_GPIO, O_WRONLY)) < 0) {
        perror("Failed to open LED GPIO");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Set up signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    while (running) {
        // Read lux value from BH1750
        if (read(i2c_fd, buffer, 3) != 3) {
            perror("Failed to read from BH1750 sensor");
            continue;
        }

        // Convert raw value to lux
        uint16_t lux = (buffer[0] << 8) | buffer[1];
        lux = lux / 1.2;

        // Update circular buffer
        *buffer_ptr = lux;
        buffer_ptr = (buffer_ptr == lux_values + BUFFER_SIZE - 1) ? lux_values : buffer_ptr + 1;
        buffer_count = (buffer_count == BUFFER_SIZE) ? BUFFER_SIZE : buffer_count + 1;

        // Calculate average lux
        if (buffer_count > 0) {
            avg_lux = 0.0;
            for (int i = 0; i < buffer_count; i++) {
                avg_lux += lux_values[i];
            }
            avg_lux /= buffer_count;
        }

        // Calculate blink rate
        rate = 0.5 + (avg_lux / 1000) * 4.5;
        rate = (rate < 0.5) ? 0.5 : ((rate > 5.0) ? 5.0 : rate);

        // Blink LED
        for (int i = 0; i < rate * 2; i++) {
            if (write(gpio_fd, "1", 1) != 1) {
                perror("Failed to set LED GPIO high");
            }
            nanosleep(&sleep_time, NULL);
            if (write(gpio_fd, "0", 1) != 1) {
                perror("Failed to set LED GPIO low");
            }
            nanosleep(&sleep_time, NULL);
        }
    }

    // Clean up
    close(gpio_fd);
    close(i2c_fd);
    return EXIT_SUCCESS;
}
