void shift_out(struct gpiod_line *data_line, struct gpiod_line *clock_line, uint8_t byte) {
    for (int i = 7; i >= 0; i--) {
        gpiod_line_set_value(data_line, (byte >> i) & 1);
        gpiod_line_set_value(clock_line, 1);
        usleep(1);
        gpiod_line_set_value(clock_line, 0);
    }
}

