        gpiod_line_release(clock_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(data_line, "seven_segment_data", 0) < 0) {
        perror("Failed to request data line as output");
        gpiod_line_release(latch_line);
        gpiod_line_release(clock_line);
        gpiod_line_release(data_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(clock_line, "seven_segment_clock", 0) < 0) {
        perror("Failed to request clock line as output");
        gpiod_line_release(latch_line);
        gpiod_line_release(clock_line);
        gpiod_line_release(data_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(latch_line, "seven_segment_latch", 0) < 0) {
