#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <libgpiod.h>

#define LED_LINE "17"
#define BUTTON_LINE "18"
#define GPIO_CHIP "gpiochip0"
#define BLINK_PERIOD 2
#define TIMEOUT 1

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *led_line, *button_line;
    struct gpiod_line_request_config led_config, button_config;
    struct gpiod_line_event event;
    int ret;

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Configure LED line
    memset(&led_config, 0, sizeof(led_config));
    led_config.consumer = "LED";
    led_config.request_type = GPIOD_LINE_REQUEST_OUTPUT;
    led_config.default_val = 0;

    led_line = gpiod_chip_get_line(chip, atoi(LED_LINE));
    if (!led_line) {
        perror("Failed to get LED line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request(led_line, &led_config);
    if (ret < 0) {
        perror("Failed to request LED line");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure button line
    memset(&button_config, 0, sizeof(button_config));
    button_config.consumer = "Button";
    button_config.request_type = GPIOD_LINE_REQUEST_INPUT;
    button_config.flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP;
    button_config.event_types = GPIOD_LINE_EVENT_RISING_EDGE;

    button_line = gpiod_chip_get_line(chip, atoi(BUTTON_LINE));
    if (!button_line) {
        perror("Failed to get button line");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request(button_line, &button_config);
    if (ret < 0) {
        perror("Failed to request button line");
        gpiod_line_release(led_line);
        gpiod_line_release(button_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        // Blink LED
        ret = gpiod_line_set_value(led_line, 1);
        if (ret < 0) {
            perror("Failed to set LED line value");
            break;
        }
        sleep(BLINK_PERIOD / 2);

        ret = gpiod_line_set_value(led_line, 0);
        if (ret < 0) {
            perror("Failed to set LED line value");
            break;
        }
        sleep(BLINK_PERIOD / 2);

        // Check for button event
        ret = gpiod_line_event_wait(button_line, TIMEOUT);
        if (ret < 0) {
            perror("Failed to wait for button event");
            break;
        }

        ret = gpiod_line_event_read(button_line, &event);
        if (ret < 0) {
            perror("Failed to read button event");
            break;
        }

        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            printf("Button pressed, stopping blinking\n");
            break;
        }
    }

    // Clean up
    gpiod_line_release(led_line);
    gpiod_line_release(button_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

