#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define LED_PIN 5
#define DELAY_MS 750

volatile sig_atomic_t stop = 0;

void sigint_handler(int sig) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);

    signal(SIGINT, sigint_handler);

    while (!stop) {
        gpioWrite(LED_PIN, PI_HIGH);
        printf("LED ON\n");
        fflush(stdout);
        gpioDelay(DELAY_MS * 1000);
        gpioWrite(LED_PIN, PI_LOW);
        printf("LED OFF\n");
        fflush(stdout);
        gpioDelay(DELAY_MS * 1000);
    }

    gpioTerminate();
    return 0;
}

