#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define LED_LINE "24"
#define BUTTON_LINE "22"

static struct gpiod_chip *chip;
static struct gpiod_line *led_line;
static struct gpiod_line *button_line;

static void cleanup(int signum) {
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (button_line) {
        gpiod_line_release(button_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(signum);
}

int main() {
    int ret;

    // Register signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", gpiod_strerror(errno));
        return EXIT_FAILURE;
    }

    // Get the LED line
    led_line = gpiod_chip_get_line(chip, atoi(LED_LINE));
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line: %s\n", gpiod_strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request the LED line as output
    ret = gpiod_line_request_output(led_line, "LED", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request LED line as output: %s\n", gpiod_strerror(errno));
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Get the button line
    button_line = gpiod_chip_get_line(chip, atoi(BUTTON_LINE));
    if (!button_line) {
        fprintf(stderr, "Failed to get button line: %s\n", gpiod_strerror(errno));
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request the button line as input with internal pull-down
    ret = gpiod_line_request_input(led_line, "BUTTON", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN);
    if (ret < 0) {
        fprintf(stderr, "Failed to request button line as input: %s\n", gpiod_strerror(errno));
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        int button_value = gpiod_line_get_value(button_line);
        if (button_value < 0) {
            fprintf(stderr, "Failed to read button value: %s\n", gpiod_strerror(errno));
            continue;
        }

        if (button_value == 0) {
            // Button is pressed
            while (button_value == 0) {
                gpiod_line_set_value(led_line, 1);
                usleep(500 * 1000);
                gpiod_line_set_value(led_line, 0);
                usleep(500 * 1000);
                button_value = gpiod_line_get_value(button_line);
                if (button_value < 0) {
                    fprintf(stderr, "Failed to read button value: %s\n", gpiod_strerror(errno));
                    break;
                }
            }
        } else {
            // Button is released
            gpiod_line_set_value(led_line, 0);
        }
    }

    // Cleanup on normal exit
    cleanup(0);

    return EXIT_SUCCESS;
}

