#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP 0
#define GPIO_RED 24
#define GPIO_GREEN 23
#define GPIO_BLUE 18
#define PWM_PERIOD_NS 10000000  // 10 ms period
#define PWM_FREQ 100  // 100 Hz
#define PWM_DUTY_MIN 0
#define PWM_DUTY_MAX 100

static struct gpiod_chip *chip;
static struct gpiod_line *red_line, *green_line, *blue_line;
static volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

void set_pwm_duty_cycle(struct gpiod_line *line, int duty_cycle) {
    for (int i = 0; i < PWM_PERIOD_NS; i++) {
        if (i < (duty_cycle * PWM_PERIOD_NS / 100)) {
            gpiod_line_set_value(line, 1);
        } else {
            gpiod_line_set_value(line, 0);
        }
        struct timespec ts = {0, 1000};  // 1 us
        nanosleep(&ts, NULL);
    }
}

int main() {
    srand(time(NULL));
    signal(SIGINT, sigint_handler);

    chip = gpiod_chip_open_by_number(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    red_line = gpiod_chip_get_line(chip, GPIO_RED);
    if (!red_line) {
        perror("Failed to get GPIO line for Red");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    green_line = gpiod_chip_get_line(chip, GPIO_GREEN);
    if (!green_line) {
        perror("Failed to get GPIO line for Green");
        gpiod_line_release(red_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    blue_line = gpiod_chip_get_line(chip, GPIO_BLUE);
    if (!blue_line) {
        perror("Failed to get GPIO line for Blue");
        gpiod_line_release(red_line);
        gpiod_line_release(green_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(red_line, "RGB LED Red") < 0) {
        perror("Failed to request output for Red line");
        gpiod_line_release(blue_line);
        gpiod_line_release(green_line);
        gpiod_line_release(red_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(green_line, "RGB LED Green") < 0) {
        perror("Failed to request output for Green line");
        gpiod_line_release(blue_line);
        gpiod_line_release(green_line);
        gpiod_line_release(red_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(blue_line, "RGB LED Blue") < 0) {
        perror("Failed to request output for Blue line");
        gpiod_line_release(blue_line);
        gpiod_line_release(green_line);
        gpiod_line_release(red_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        int red_duty = rand() % (PWM_DUTY_MAX - PWM_DUTY_MIN + 1) + PWM_DUTY_MIN;
        int green_duty = rand() % (PWM_DUTY_MAX - PWM_DUTY_MIN + 1) + PWM_DUTY_MIN;
        int blue_duty = rand() % (PWM_DUTY_MAX - PWM_DUTY_MIN + 1) + PWM_DUTY_MIN;

        set_pwm_duty_cycle(red_line, red_duty);
        set_pwm_duty_cycle(green_line, green_duty);
        set_pwm_duty_cycle(blue_line, blue_duty);

        struct timespec ts = {0, 100000000};  // 100 ms
        nanosleep(&ts, NULL);
    }

    gpiod_line_release(blue_line);
    gpiod_line_release(green_line);
    gpiod_line_release(red_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

