#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x39
#define MODE_REG 0x0D
#define ALS_LSB_REG 0x64
#define ALS_MSB_REG 0x65
#define RED_REG 0x66
#define GREEN_REG 0x68
#define BLUE_REG 0x6A
#define LED_PIN 18
#define PWM_FREQ 1000
#define PWM_RANGE 255
#define SAMPLE_INTERVAL 500
#define RETRY_DELAY 100

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_PIN);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(LED_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO%d\n", LED_PIN);
        gpioSetMode(LED_PIN, PI_INPUT);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *csv_file = fopen("color_log.csv", "w");
    if (!csv_file) {
        fprintf(stderr, "Failed to open CSV file for writing\n");
        gpioSetMode(LED_PIN, PI_INPUT);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(csv_file, "Timestamp,ALS,R,G,B\n");

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        uint16_t als = 0, red = 0, green = 0, blue = 0;

        // Read ALS data
        uint8_t als_lsb = i2cReadByteData(i2c_handle, ALS_LSB_REG);
        uint8_t als_msb = i2cReadByteData(i2c_handle, ALS_MSB_REG);
        if (als_lsb < 0 || als_msb < 0) {
            fprintf(stderr, "Failed to read ALS data\n");
            usleep(RETRY_DELAY * 1000);
            continue;
        }
        als = (als_msb << 8) | als_lsb;

        // Read RGB data
        uint8_t red_lsb = i2cReadByteData(i2c_handle, RED_REG);
        uint8_t red_msb = i2cReadByteData(i2c_handle, RED_REG + 2);
        uint8_t green_lsb = i2cReadByteData(i2c_handle, GREEN_REG);
        uint8_t green_msb = i2cReadByteData(i2c_handle, GREEN_REG + 2);
        uint8_t blue_lsb = i2cReadByteData(i2c_handle, BLUE_REG);
        uint8_t blue_msb = i2cReadByteData(i2c_handle, BLUE_REG + 2);
        if (red_lsb < 0 || red_msb < 0 || green_lsb < 0 || green_msb < 0 || blue_lsb < 0 || blue_msb < 0) {
            fprintf(stderr, "Failed to read RGB data\n");
            usleep(RETRY_DELAY * 1000);
            continue;
        }
        red = (red_msb << 8) | red_lsb;
        green = (green_msb << 8) | green_lsb;
        blue = (blue_msb << 8) | blue_lsb;

        // Map ALS to PWM duty cycle
        uint8_t pwm_duty = (als * PWM_RANGE) / 65535;

        // Set LED brightness
        gpioSetPWMrange(LED_PIN, PWM_RANGE);
        gpioSetPWMdutycycle(LED_PIN, pwm_duty);

        // Log data
        fprintf(csv_file, "%lu,%u,%u,%u,%u\n", time(NULL), als, red, green, blue);
        fflush(csv_file);

        usleep(SAMPLE_INTERVAL * 1000);
    }

    gpioSetPWMdutycycle(LED_PIN, 0);
    gpioSetMode(LED_PIN, PI_INPUT);
    fclose(csv_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

