        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t config[2] = {XYZ_DATA_CFG, 0x00};
    if (gpioI2CWrite(i2c_handle, config, 2) < 0) {
        fprintf(stderr, "Failed to configure sensor\n");
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    config[0] = CTRL_REG1;
    config[1] = 0x01;
    if (gpioI2CWrite(i2c_handle, config, 2) < 0) {
        fprintf(stderr, "Failed to activate sensor\n");
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return 1;
