        if (magnitude > THRESHOLD) {
            log_impact(x_mps2, y_mps2, z_mps2, magnitude);
        }

        gpioDelay(SAMPLE_INTERVAL * 1000);
    }

    gpioI2CClose(i2c_handle);
    gpioTerminate();
    return 0;
}

