#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define GYRO_ADDR 0x69
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define WHO_AM_I 0x0F
#define SAMPLES 100
#define THRESHOLD 50.0
#define LOG_FILE "gyro_log.txt"

int i2c_fd = -1;
FILE *log_file = NULL;

void cleanup() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
}

void signal_handler(int sig) {
    cleanup();
    exit(0);
}

int read_register(int fd, uint8_t reg, uint8_t *value) {
    uint8_t buf[1] = {reg};
    if (write(fd, buf, 1) != 1) {
        perror("write");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("read");
        return -1;
    }
    return 0;
}

int read_multiple_registers(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    uint8_t read_reg[1] = {reg};
    if (write(fd, read_reg, 1) != 1) {
        perror("write");
        return -1;
    }
    if (read(fd, buf, len) != len) {
        perror("read");
        return -1;
    }
    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, GYRO_ADDR) < 0) {
        perror("ioctl");
        close(i2c_fd);
        return 1;
    }

    uint8_t who_am_i;
    if (read_register(i2c_fd, WHO_AM_I, &who_am_i) < 0) {
        close(i2c_fd);
        return 1;
    }
    if (who_am_i != 0xD3) {
        fprintf(stderr, "Sensor not found\n");
        close(i2c_fd);
        return 1;
    }

    uint8_t ctrl_reg1 = 0x0F;
    if (write(i2c_fd, &ctrl_reg1, 1) != 1) {
        perror("write");
        close(i2c_fd);
        return 1;
    }

    uint8_t ctrl_reg4 = 0x00;
    if (write(i2c_fd, &ctrl_reg4, 1) != 1) {
        perror("write");
        close(i2c_fd);
        return 1;
    }

    int16_t offsets[3] = {0};
    for (int i = 0; i < SAMPLES; i++) {
        uint8_t buf[6];
        if (read_multiple_registers(i2c_fd, OUT_X_L, buf, 6) < 0) {
            close(i2c_fd);
            return 1;
        }
        offsets[0] += (int16_t)((buf[1] << 8) | buf[0]);
        offsets[1] += (int16_t)((buf[3] << 8) | buf[2]);
        offsets[2] += (int16_t)((buf[5] << 8) | buf[4]);
        usleep(50000);
    }
    offsets[0] /= SAMPLES;
    offsets[1] /= SAMPLES;
    offsets[2] /= SAMPLES;

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        uint8_t buf[6];
        if (read_multiple_registers(i2c_fd, OUT_X_L, buf, 6) < 0) {
            close(i2c_fd);
            fclose(log_file);
            return 1;
        }

        int16_t x = (int16_t)((buf[1] << 8) | buf[0]);
        int16_t y = (int16_t)((buf[3] << 8) | buf[2]);
        int16_t z = (int16_t)((buf[5] << 8) | buf[4]);

        x -= offsets[0];
        y -= offsets[1];
        z -= offsets[2];

        double x_dps = x * 0.00875;
        double y_dps = y * 0.00875;
        double z_dps = z * 0.00875;

        if (fabs(x_dps) > THRESHOLD || fabs(y_dps) > THRESHOLD || fabs(z_dps) > THRESHOLD) {
            fprintf(stderr, "Warning: High angular velocity detected\n");
            fprintf(log_file, "Alert: High angular velocity detected\n");
        }

        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d %.2f %.2f %.2f\n",
                tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
                tm->tm_hour, tm->tm_min, tm->tm_sec,
                x_dps, y_dps, z_dps);

        usleep(50000);
    }

    cleanup();
    return 0;
}

