#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x53
#define DEVID_REG 0x00
#define DATA_REG 0x32
#define LED_PIN 17
#define SAMPLE_RATE 100
#define ACCEL_RANGE 2.0
#define ACCEL_SCALE 0.00390625

volatile FILE *log_file = NULL;

void log_acceleration(float x, float y, float z) {
    if (log_file) {
        time_t now = time(NULL);
        fprintf(log_file, "%ld,%0.3f,%0.3f,%0.3f\n", now, x, y, z);
        fflush(log_file);
    }
}

void handle_sigint(int sig) {
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d mode\n", LED_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(LED_PIN, PI_PUD_OFF) < 0) {
        fprintf(stderr, "Failed to set GPIO%d pull-up/down\n", LED_PIN);
        gpioTerminate();
        return 1;
    }

    int i2c_handle = gpioI2COpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return 1;
    }

    uint8_t devid;
    if (gpioI2CReadReg8(i2c_handle, DEVID_REG, &devid) < 0) {
        fprintf(stderr, "Failed to read DEVID register\n");
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (devid != 0xE5) {
        fprintf(stderr, "Incorrect DEVID: 0x%02X\n", devid);
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioI2CWriteReg8(i2c_handle, 0x2D, 0x08) < 0) { // Power control: measure mode
        fprintf(stderr, "Failed to set power control\n");
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioI2CWriteReg8(i2c_handle, 0x2C, 0x0B) < 0) { // Data format: full resolution, ±2g
        fprintf(stderr, "Failed to set data format\n");
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("accel_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    while (1) {
        uint8_t data[6];
        if (gpioI2CRead(i2c_handle, data, 6) < 0) {
            fprintf(stderr, "Failed to read accelerometer data\n");
            continue;
        }

        int16_t x = (data[1] << 8) | data[0];
        int16_t y = (data[3] << 8) | data[2];
        int16_t z = (data[5] << 8) | data[4];

        float x_g = x * ACCEL_SCALE;
        float y_g = y * ACCEL_SCALE;
        float z_g = z * ACCEL_SCALE;

        log_acceleration(x_g, y_g, z_g);

        if (fabs(x_g) > ACCEL_RANGE || fabs(y_g) > ACCEL_RANGE || fabs(z_g) > ACCEL_RANGE) {
            gpioWrite(LED_PIN, 1);
        } else {
            gpioWrite(LED_PIN, 0);
        }

        gpioDelay(SAMPLE_RATE * 1000);
