    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioI2CClose(i2c_handle);
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Heading,AccelX,AccelY,AccelZ,MagX,MagY,MagZ\n");
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

