        int16_t mag_y = (mag_data[3] << 8) | mag_data[2];
        int16_t mag_z = (mag_data[5] << 8) | mag_data[4];

        double accel_norm = sqrt(accel_x * accel_x + accel_y * accel_y + accel_z * accel_z);
        double accel_x_norm = accel_x / accel_norm;
        double accel_y_norm = accel_y / accel_norm;
        double accel_z_norm = accel_z / accel_norm;

        double mag_norm = sqrt(mag_x * mag_x + mag_y * mag_y + mag_z * mag_z);
