                timestamp, heading, accel_x_norm, accel_y_norm, accel_z_norm,
                mag_x_norm, mag_y_norm, mag_z_norm);

        fflush(log_file);

        gpioDelay(100000); // 100 ms
    }

    fclose(log_file);
    gpioI2CClose(i2c_handle);
    gpioI2CClose(i2c_handle);
    gpioTerminate();

    return 0;
}

