#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69
#define DATA_REG 0x01
#define CONTROL_REG 0x00
#define CONTROL_ENABLE 0x80
#define SAMPLE_INTERVAL 10000  // 10 ms in microseconds

FILE *log_file = NULL;
int i2c_handle1 = -1;
int i2c_handle2 = -1;

void signal_handler(int sig) {
    if (log_file) fclose(log_file);
    if (i2c_handle1 != -1) i2cClose(i2c_handle1);
    if (i2c_handle2 != -1) i2cClose(i2c_handle2);
    pigpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Failed to open I2C handle for sensor 1\n");
        signal_handler(0);
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Failed to open I2C handle for sensor 2\n");
        signal_handler(0);
    }

    if (i2cWriteByteData(i2c_handle1, CONTROL_REG, CONTROL_ENABLE) < 0) {
        fprintf(stderr, "Failed to enable sensor 1\n");
        signal_handler(0);
    }

    if (i2cWriteByteData(i2c_handle2, CONTROL_REG, CONTROL_ENABLE) < 0) {
        fprintf(stderr, "Failed to enable sensor 2\n");
        signal_handler(0);
    }

    log_file = fopen("audio_log.dat", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        signal_handler(0);
    }

    fprintf(log_file, "sec,nsec,sensor1,sensor2,tdoa\n");

    struct timespec start, end;
    while (1) {
        if (clock_gettime(CLOCK_REALTIME, &start) < 0) {
            fprintf(stderr, "Failed to get start time\n");
            signal_handler(0);
        }

        int16_t sensor1_data = i2cReadWordData(i2c_handle1, DATA_REG);
        int16_t sensor2_data = i2cReadWordData(i2c_handle2, DATA_REG);

        if (sensor1_data == -1 || sensor2_data == -1) {
            fprintf(stderr, "Failed to read sensor data\n");
            continue;
        }

        if (clock_gettime(CLOCK_REALTIME, &end) < 0) {
            fprintf(stderr, "Failed to get end time\n");
            signal_handler(0);
        }

        int64_t tdoa = (end.tv_sec - start.tv_sec) * 1000000000LL + (end.tv_nsec - start.tv_nsec);

        fprintf(log_file, "%ld,%ld,%d,%d,%lld\n", start.tv_sec, start.tv_nsec, sensor1_data, sensor2_data, tdoa);

        if (nanosleep(&(struct timespec){0, SAMPLE_INTERVAL}, NULL) < 0) {
            fprintf(stderr, "Failed to sleep\n");
            signal_handler(0);
        }
    }

    signal_handler(0);
    return 0;
}

