#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <libgpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 8
#define SPI_MODE SPI_MODE_3
#define SPI_SPEED 1000000
#define SPI_BITS_PER_WORD 8
#define REG_READ_MASK 0x80
#define REG_XGYRO_OUT 0x04
#define REG_YGYRO_OUT 0x06
#define REG_ZGYRO_OUT 0x08
#define REG_XACCL_OUT 0x0A
#define REG_YACCL_OUT 0x0C
#define REG_ZACCL_OUT 0x0E
#define GYRO_SCALE 0.02
#define ACCEL_SCALE 0.00025

static int spi_fd;
static struct gpiod_chip *gpio_chip;
static struct gpiod_line *gpio_line;

static void close_resources() {
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
}

static void handle_sigint(int signum) {
    close_resources();
    exit(signum);
}

static int read_spi_register(uint8_t reg, uint16_t *data) {
    uint8_t tx[2] = {reg | REG_READ_MASK, 0};
    uint8_t rx[2] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 2,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI_IOC_MESSAGE");
        return -1;
    }

    *data = (rx[0] << 8) | rx[1];
    return 0;
}

int main() {
    struct sigaction sa;

    // Initialize GPIO for chip-select
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_LINE);
    if (!gpio_line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(gpio_chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(gpio_line, "imu_cs", 0) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(gpio_chip);
        return EXIT_FAILURE;
    }

    // Initialize SPI
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open");
        close_resources();
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("SPI_IOC_WR_MODE");
        close_resources();
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("SPI_IOC_WR_BITS_PER_WORD");
        close_resources();
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        close_resources();
        return EXIT_FAILURE;
    }

    // Set up signal handler for clean exit
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        close_resources();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        close_resources();
        return EXIT_FAILURE;
    }

    while (1) {
        uint16_t gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;

        // Select the device
        gpiod_line_set_value(gpio_line, 0);

        // Read gyroscope data
        if (read_spi_register(REG_XGYRO_OUT, &gyro_x) < 0) {
            perror("read_spi_register XGYRO_OUT");
            close_resources();
            return EXIT_FAILURE;
        }
        if (read_spi_register(REG_YGYRO_OUT, &gyro_y) < 0) {
            perror("read_spi_register YGYRO_OUT");
            close_resources();
            return EXIT_FAILURE;
        }
        if (read_spi_register(REG_ZGYRO_OUT, &gyro_z) < 0) {
            perror("read_spi_register ZGYRO_OUT");
            close_resources();
            return EXIT_FAILURE;
        }

        // Read accelerometer data
        if (read_spi_register(REG_XACCL_OUT, &accel_x) < 0) {
            perror("read_spi_register XACCL_OUT");
            close_resources();
            return EXIT_FAILURE;
        }
        if (read_spi_register(REG_YACCL_OUT, &accel_y) < 0) {
            perror("read_spi_register YACCL_OUT");
            close_resources();
            return EXIT_FAILURE;
        }
        if (read_spi_register(REG_ZACCL_OUT, &accel_z) < 0) {
            perror("read_spi_register ZACCL_OUT");
            close_resources();
            return EXIT_FAILURE;
        }

        // Deselect the device
        gpiod_line_set_value(gpio_line, 1);

        // Convert and print data
        printf("Gyro: X=%.2f dps, Y=%.2f dps, Z=%.2f dps\n",
               gyro_x * GYRO_SCALE, gyro_y * GYRO_SCALE, gyro_z * GYRO_SCALE);
        printf("Accel: X=%.4f g, Y=%.4f g, Z=%.4f g\n",
               accel_x * ACCEL_SCALE, accel_y * ACCEL_SCALE, accel_z * ACCEL_SCALE);

        usleep(100000); // 100 ms delay
    }

    close_resources();
    return EXIT_SUCCESS;
}

