#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6886_ADDR 0x68
#define WHO_AM_I 0x75
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG 0x1B
#define ACCEL_DATA_START 0x3B
#define GYRO_DATA_START 0x43
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY 100000 // 100us

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t data[2] = {reg, value};
    for (int i = 0; i < I2C_RETRY_COUNT; i++) {
        if (write(fd, data, 2) == 2) {
            return 0;
        }
        usleep(I2C_RETRY_DELAY);
    }
    return -1;
}

int i2c_read(int fd, uint8_t reg, uint8_t *data, size_t len) {
    for (int i = 0; i < I2C_RETRY_COUNT; i++) {
        if (write(fd, &reg, 1) == 1 && read(fd, data, len) == len) {
            return 0;
        }
        usleep(I2C_RETRY_DELAY);
    }
    return -1;
}

int main() {
    int fd;
    uint8_t who_am_i, accel_data[6], gyro_data[6];

    if ((fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6886_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return EXIT_FAILURE;
    }

    if (i2c_read(fd, WHO_AM_I, &who_am_i, 1) < 0 || who_am_i != 0x86) {
        fprintf(stderr, "Sensor not found or communication error\n");
        close(fd);
        return EXIT_FAILURE;
    }

    if (i2c_write(fd, PWR_MGMT_1, 0x00) < 0) {
        perror("Failed to wake sensor");
        close(fd);
        return EXIT_FAILURE;
    }

    if (i2c_write(fd, ACCEL_CONFIG, 0x00) < 0 || i2c_write(fd, GYRO_CONFIG, 0x00) < 0) {
        perror("Failed to configure sensor");
        close(fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    while (running) {
        if (i2c_read(fd, ACCEL_DATA_START, accel_data, 6) < 0) {
            perror("Failed to read accelerometer data");
        } else {
            printf("Accel: X=%d, Y=%d, Z=%d\n", 
                   (int16_t)(accel_data[0] | (accel_data[1] << 8)),
                   (int16_t)(accel_data[2] | (accel_data[3] << 8)),
                   (int16_t)(accel_data[4] | (accel_data[5] << 8)));
        }

        if (i2c_read(fd, GYRO_DATA_START, gyro_data, 6) < 0) {
            perror("Failed to read gyroscope data");
        } else {
            printf("Gyro: X=%d, Y=%d, Z=%d\n", 
                   (int16_t)(gyro_data[0] | (gyro_data[1] << 8)),
                   (int16_t)(gyro_data[2] | (gyro_data[3] << 8)),
                   (int16_t)(gyro_data[4] | (gyro_data[5] << 8)));
        }

        usleep(50000); // 50ms
    }

    close(fd);
    return EXIT_SUCCESS;
}

