This C program interfaces with a TDK MPU-6886 6-axis IMU over the I2C bus 1 at address 0x68 on a Raspberry Pi 4 Model B. It verifies the sensor is present by reading the WHO_AM_I register and checking it returns 0x86. It then initializes the sensor by waking it and setting the accelerometer and gyroscope configurations. The program reads raw accelerometer and gyroscope data every 50 ms and prints the raw 16-bit signed values to the console. It handles sensor-absent and bus-error paths gracefully and ensures clean resource release by closing the I2C file descriptor on all exit paths, including when the program is terminated with Ctrl+C.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <signal.h>

#define I2C_BUS 1
#define I2C_ADDR 0x53
#define LED_PIN 17
#define LOG_FILE "impact_log.txt"
#define ACCEL_SCALE 256.0
#define THRESHOLD 2.5
#define POLL_INTERVAL 10

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2cReadByteData(i2c_handle, 0x00) != 0xE5) {
        fprintf(stderr, "Device ID mismatch\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        uint8_t data[6];
        if (i2cReadBlockData(i2c_handle, 0x32, data, 6) != 6) {
            fprintf(stderr, "Failed to read accelerometer data\n");
            continue;
        }

        int16_t x = (data[1] << 8) | data[0];
        int16_t y = (data[3] << 8) | data[2];
        int16_t z = (data[5] << 8) | data[4];

        double magnitude = sqrt(x * x + y * y + z * z) / ACCEL_SCALE;

        if (magnitude > THRESHOLD) {
            gpioWrite(LED_PIN, PI_HIGH);
            usleep(500 * 1000);
            gpioWrite(LED_PIN, PI_LOW);

            time_t now = time(NULL);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

            fprintf(log_file, "%s: Magnitude=%.2f, X=%d, Y=%d, Z=%d\n", timestamp, magnitude, x, y, z);
            fflush(log_file);
        }

        usleep(POLL_INTERVAL * 1000);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

