#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x1D
#define LED_LINE "gpiochip0:line17"
#define WHO_AM_I 0x0D
#define THRESHOLD 2048
#define IMPACT_LOG "impact_log.txt"
#define POLL_INTERVAL 100000 // 100 ms in microseconds

static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;
static FILE *log_file = NULL;

void cleanup() {
    if (log_file) {
        fclose(log_file);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

void handle_sigint(int sig) {
    cleanup();
    exit(0);
}

int read_i2c_reg(int fd, uint8_t reg, uint8_t *value) {
    uint8_t buf[1] = {reg};
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

int write_i2c_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize LED GPIO
    chip = gpiod_chip_open_by_name(LED_LINE);
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    led_line = gpiod_chip_get_line(chip, 17);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(led_line, "accel_impact", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Verify sensor identity
    uint8_t whoami;
    if (read_i2c_reg(i2c_fd, WHO_AM_I, &whoami) < 0) {
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (whoami != 0x1A) {
        fprintf(stderr, "Sensor identity verification failed\n");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(IMPACT_LOG, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        int16_t x, y, z;
        if (read_i2c_reg(i2c_fd, 0x01, (uint8_t *)&x) < 0 ||
            read_i2c_reg(i2c_fd, 0x03, (uint8_t *)&y) < 0 ||
            read_i2c_reg(i2c_fd, 0x05, (uint8_t *)&z) < 0) {
            fprintf(stderr, "Failed to read acceleration data\n");
            continue;
        }

        int16_t magnitude = x * x + y * y + z * z;
        if (magnitude > THRESHOLD * THRESHOLD) {
            gpiod_line_set_value(led_line, 1);
            usleep(500000); // 500 ms
            gpiod_line_set_value(led_line, 0);

            time_t now = time(NULL);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
            fprintf(log_file, "%s: Impact detected\n", timestamp);
            fflush(log_file);
        }

        usleep(POLL_INTERVAL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

