#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x35
#define X_REG 0x10
#define Y_REG 0x11
#define Z_REG 0x12
#define SAMPLE_RATE 1
#define CSV_HEADER "Timestamp,X,Y,Z\n"

int i2c_fd = -1;
FILE *csv_fd = NULL;

void signal_handler(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (csv_fd != NULL) {
        fclose(csv_fd);
    }
    exit(signum);
}

int main() {
    struct timespec ts;
    uint16_t x, y, z;
    uint8_t buffer[2];

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    if ((i2c_fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open CSV file
    csv_fd = fopen("magnetic_field_log.csv", "a");
    if (csv_fd == NULL) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Write CSV header if file is empty
    if (fseek(csv_fd, 0, SEEK_END) == 0 && ftell(csv_fd) == 0) {
        fputs(CSV_HEADER, csv_fd);
    }

    while (1) {
        // Read X, Y, Z registers
        if (read(i2c_fd, buffer, 2) != 2) {
            perror("Failed to read X register");
            continue;
        }
        x = (buffer[1] << 8) | buffer[0];

        if (read(i2c_fd, buffer, 2) != 2) {
            perror("Failed to read Y register");
            continue;
        }
        y = (buffer[1] << 8) | buffer[0];

        if (read(i2c_fd, buffer, 2) != 2) {
            perror("Failed to read Z register");
            continue;
        }
        z = (buffer[1] << 8) | buffer[0];

        // Get current timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("Failed to get timestamp");
            continue;
        }

        // Log data to CSV
        fprintf(csv_fd, "%ld.%09ld,%d,%d,%d\n", ts.tv_sec, ts.tv_nsec, x, y, z);
        fflush(csv_fd);

        // Sleep for 1 second
        sleep(SAMPLE_RATE);
    }

    // Clean up
    close(i2c_fd);
    fclose(csv_fd);
    return EXIT_SUCCESS;
}

