        y = (buffer[1] << 8) | buffer[0];

        if (read(i2c_fd, buffer, 2) != 2) {
            perror("Failed to read Z register");
            continue;
        }
        z = (buffer[1] << 8) | buffer[0];

        // Get current timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("Failed to get timestamp");
            continue;
        }

        // Log data to CSV
        fprintf(csv_fd, "%ld.%09ld,%d,%d,%d\n", ts.tv_sec, ts.tv_nsec, x, y, z);
        fflush(csv_fd);

        // Sleep for 1 second
        sleep(SAMPLE_RATE);
    }

    // Clean up
    close(i2c_fd);
    fclose(csv_fd);
    return EXIT_SUCCESS;
}
