This C program reads magnetic field data from a Texas Instruments TMAG5273 I2C 3D Hall-Effect sensor on a Raspberry Pi 3 Model B+ and logs the data with timestamps to a CSV file. It uses the Linux i2c-dev kernel interface directly and handles errors gracefully. The program also includes a signal handler for SIGINT and SIGTERM to cleanly close the I2C file descriptor and the CSV file.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <time.h>

#define I2C_DEVICE "/dev/i2c-1"
#define ADXL345_ADDRESS 0x53
#define ADXL345_DEVICE_ID 0xE5
#define ADXL345_THRESH_FF 0x0A
#define ADXL345_TIME_FF 0x20
#define ADXL345_INT_ENABLE 0x2E
#define ADXL345_INT_MAP 0x2F
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32
#define ADXL345_INT_SOURCE 0x30
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17

void log_freefall(const char *timestamp, int x, int y, int z) {
    FILE *log_file = fopen("freefall_log.csv", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }
    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(log_file);
    fclose(log_file);
}

void handle_interrupt(int fd, struct gpiod_chip *chip) {
    uint64_t timestamp_ns;
    if (gpiod_line_event_wait(chip->lines[0], 1000000) < 0) {
        perror("Failed to wait for event");
        return;
    }
    struct gpiod_line_event event;
    if (gpiod_line_event_read(chip->lines[0], &event) < 0) {
        perror("Failed to read event");
        return;
    }
    if (event.event_type != GPIOD_LINE_EVENT_RISING_EDGE) {
        return;
    }
    if (read(fd, &timestamp_ns, sizeof(timestamp_ns)) != sizeof(timestamp_ns)) {
        perror("Failed to read timestamp");
        return;
    }
    uint64_t timestamp_ms = timestamp_ns / 1000000;
    char timestamp_str[20];
    struct tm *tm = localtime(&timestamp_ms / 1000);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", tm);
    int x, y, z;
    if (read(fd, &x, sizeof(x)) != sizeof(x) ||
        read(fd, &y, sizeof(y)) != sizeof(y) ||
        read(fd, &z, sizeof(z)) != sizeof(z)) {
        perror("Failed to read acceleration data");
        return;
    }
    log_freefall(timestamp_str, x, y, z);
}

void cleanup(int fd, struct gpiod_chip *chip, struct gpiod_line *line) {
    if (line != NULL) {
        gpiod_line_release(line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    if (fd >= 0) {
        close(fd);
    }
}

int main() {
    int fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(fd);
        return EXIT_FAILURE;
    }

    uint8_t device_id;
    if (read(fd, &device_id, sizeof(device_id)) != sizeof(device_id)) {
        perror("Failed to read device ID");
        close(fd);
        return EXIT_FAILURE;
    }
    if (device_id != ADXL345_DEVICE_ID) {
        fprintf(stderr, "Incorrect device ID: 0x%02X\n", device_id);
        close(fd);
        return EXIT_FAILURE;
    }

    if (write(fd, "\x00", 1) != 1) {
        perror("Failed to put sensor in standby");
        close(fd);
        return EXIT_FAILURE;
    }

    uint8_t config[4] = {ADXL345_THRESH_FF, 0x00, ADXL345_TIME_FF, 0x00};
    if (write(fd, config, sizeof(config)) != sizeof(config)) {
        perror("Failed to configure sensor");
        close(fd);
        return EXIT_FAILURE;
    }

    if (write(fd, "\x04", 1) != 1) {
        perror("Failed to map interrupt to INT1");
        close(fd);
        return EXIT_FAILURE;
    }

    if (write(fd, "\x08", 1) != 1) {
        perror("Failed to enable freefall interrupt");
        close(fd);
        return EXIT_FAILURE;
    }

    if (write(fd, "\x08", 1) != 1) {
        perror("Failed to enter measurement mode");
        close(fd);
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open(GPIO_CHIP);
    if (chip == NULL) {
        perror("Failed to open GPIO chip");
        close(fd);
        return EXIT_FAILURE;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (line == NULL) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line, "adxl345_interrupt") < 0) {
        perror("Failed to request GPIO line as input");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(fd);
        return EXIT_FAILURE;
    }

    struct pollfd fds[1];
    fds[0].fd = gpiod_line_event_get_fd(line);
    fds[0].events = POLLIN;

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        if (poll(fds, 1, -1) < 0) {
            perror("Failed to poll for events");
            break;
        }
        if (fds[0].revents & POLLIN) {
            handle_interrupt(fd, chip);
        }
    }

    cleanup(fd, chip, line);
    return EXIT_SUCCESS;
}

