This code provides a complete solution for interfacing with the ADXL345 accelerometer on a Raspberry Pi 4 Model B using libgpiod and the Linux i2c-dev ioctl interface. It includes error handling, resource management, and logging of freefall events. The program uses a poll-based loop to handle GPIO events and logs acceleration data during freefall events to a CSV file.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x6A
#define LSM6DSR_WHO_AM_I 0x0F
#define LSM6DSR_CTRL1_XL 0x10
#define LSM6DSR_CTRL2_G 0x11
#define LSM6DSR_OUTX_L_G 0x22
#define LSM6DSR_OUTX_L_A 0x28
#define LSM6DSR_OUTX_H_G 0x23
#define LSM6DSR_OUTX_H_A 0x29
#define LSM6DSR_OUTX_L_XL 0x2C
#define LSM6DSR_OUTX_H_XL 0x2D
#define LSM6DSR_FIFO_CTRL5 0x3F
#define LSM6DSR_FIFO_CTRL6 0x40
#define LSM6DSR_FIFO_CTRL7 0x41
#define LSM6DSR_FIFO_STATUS1 0x4B
#define LSM6DSR_FIFO_DATA_OUT_L 0x4E
#define LSM6DSR_FIFO_DATA_OUT_H 0x4F

#define FREEFALL_THRESHOLD 0.2
#define IMPACT_THRESHOLD 2.5
#define WINDOW_SIZE 1000000 // 1 second in microseconds

typedef enum {
    IDLE,
    FREEFALL,
    IMPACT
} State;

State state = IDLE;
int fd;
FILE *log_file;
struct timespec start_time, current_time;
int freefall_count = 0, impact_count = 0;

void signal_handler(int signum) {
    gpioTerminate();
    fclose(log_file);
    exit(signum);
}

void init_i2c() {
    if ((fd = i2cOpen(I2C_BUS, I2C_ADDR, 0)) < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        exit(EXIT_FAILURE);
    }

    uint8_t who_am_i;
    if (i2cReadByteData(fd, LSM6DSR_WHO_AM_I, &who_am_i) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        exit(EXIT_FAILURE);
    }

    if (who_am_i != 0x6A) {
        fprintf(stderr, "Sensor not found at address 0x%02X\n", I2C_ADDR);
        exit(EXIT_FAILURE);
    }

    uint8_t ctrl1_xl = 0x50; // +-2g, 104 Hz ODR
    uint8_t ctrl2_g = 0x10;  // +-250 dps, 104 Hz ODR
    if (i2cWriteByteData(fd, LSM6DSR_CTRL1_XL, ctrl1_xl) < 0 ||
        i2cWriteByteData(fd, LSM6DSR_CTRL2_G, ctrl2_g) < 0) {
        fprintf(stderr, "Failed to configure sensor\n");
        exit(EXIT_FAILURE);
    }
}

void log_reading(float x, float y, float z) {
    clock_gettime(CLOCK_MONOTONIC, &current_time);
    fprintf(log_file, "%ld.%06ld,%f,%f,%f\n", current_time.tv_sec, current_time.tv_nsec / 1000, x, y, z);
}

void read_sensor_data() {
    uint8_t data[14];
    if (i2cReadBlockData(fd, LSM6DSR_OUTX_L_G, data, 14) < 0) {
        fprintf(stderr, "Failed to read sensor data\n");
        return;
    }

    int16_t x = (data[1] << 8) | data[0];
    int16_t y = (data[3] << 8) | data[2];
    int16_t z = (data[5] << 8) | data[4];
    int16_t x_g = (data[7] << 8) | data[6];
    int16_t y_g = (data[9] << 8) | data[8];
    int16_t z_g = (data[11] << 8) | data[10];

    float x_a = x * 0.000061; // 0.000061 g/LSB
    float y_a = y * 0.000061;
    float z_a = z * 0.000061;
    float x_gyro = x_g * 0.000070; // 0.000070 dps/LSB
    float y_gyro = y_g * 0.000070;
    float z_gyro = z_g * 0.000070;

    float magnitude = sqrt(x_a * x_a + y_a * y_a + z_a * z_a);

    if (state == IDLE) {
        if (magnitude < FREEFALL_THRESHOLD) {
            state = FREEFALL;
            clock_gettime(CLOCK_MONOTONIC, &start_time);
        }
    } else if (state == FREEFALL) {
        if (magnitude > IMPACT_THRESHOLD) {
            state = IMPACT;
            clock_gettime(CLOCK_MONOTONIC, &start_time);
        } else if (current_time.tv_sec - start_time.tv_sec > 1) {
            state = IDLE;
        }
    } else if (state == IMPACT) {
        if (current_time.tv_sec - start_time.tv_sec > 1) {
            state = IDLE;
        }
    }

    if (state != IDLE) {
        log_reading(x_a, y_a, z_a);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    init_i2c();

    log_file = fopen("motion_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(log_file, "Timestamp,AccelX,AccelY,AccelZ\n");

    while (1) {
        read_sensor_data();
        usleep(10000); // 10 ms delay
    }

    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

