#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x69
#define WHO_AM_I 0x0F
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define SAMPLE_INTERVAL 10000000  // 10 ms in nanoseconds

volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    int i2c_handle;
    FILE *log_file;
    struct timespec ts;
    uint8_t buffer[6];
    int16_t x, y, z;
    double x_dps, y_dps, z_dps;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return 1;
    }

    for (int i = 0; i < 3; i++) {
        uint8_t who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
        if (who_am_i == 0xD3) {
            break;
        }
        if (i == 2) {
            fprintf(stderr, "Gyroscope not found at address 0x%02X\n", I2C_ADDR);
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }
    }

    uint8_t ctrl_reg1 = 0x0F;
    uint8_t ctrl_reg4 = 0x00;
    i2cWriteByteData(i2c_handle, CTRL_REG1, ctrl_reg1);
    i2cWriteByteData(i2c_handle, CTRL_REG4, ctrl_reg4);

    log_file = fopen("gyro_log.csv", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fprintf(log_file, "Timestamp,X,Y,Z\n");

    signal(SIGINT, signal_handler);

    while (running) {
        if (i2cReadBlockData(i2c_handle, OUT_X_L, buffer, 6) != 6) {
            fprintf(stderr, "Failed to read data from gyroscope\n");
            continue;
        }

        x = (buffer[1] << 8) | buffer[0];
        y = (buffer[3] << 8) | buffer[2];
        z = (buffer[5] << 8) | buffer[4];

        x_dps = (double)x / 114.285;
        y_dps = (double)y / 114.285;
        z_dps = (double)z / 114.285;

        clock_gettime(CLOCK_MONOTONIC, &ts);
        fprintf(log_file, "%ld.%09ld,%f,%f,%f\n", ts.tv_sec, ts.tv_nsec, x_dps, y_dps, z_dps);

        gpioDelay(SAMPLE_INTERVAL);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

