#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define LOG_FILE "flame_events.log"

volatile sig_atomic_t stop_flag = 0;

void sigint_handler(int signum) {
    stop_flag = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up resistor on GPIO%d\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    time_t now;
    struct tm *tm_info;
    char timestamp[20];

    while (!stop_flag) {
        int flame_detected = gpioRead(GPIO_PIN);
        if (flame_detected == PI_BAD_GPIO) {
            fprintf(stderr, "Error reading GPIO%d\n", GPIO_PIN);
        } else {
            time(&now);
            tm_info = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
            fprintf(log_file, "%s - Flame detected: %s\n", timestamp, flame_detected ? "NO" : "YES");
            fflush(log_file);
            if (flame_detected) {
                printf("FLAME DETECTED!\n");
            }
        }

        gpioDelay(500 * 1000); // 500 ms delay
    }

    fclose(log_file);
    gpioTerminate();

    return EXIT_SUCCESS;
}

