#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_SLAVE_ADDR 0x53
#define REG_X_LSB 0x28
#define REG_Z_MSB 0x2D
#define SAMPLE_INTERVAL 100000  // 100 ms in microseconds

FILE *log_file = NULL;
int i2c_fd = -1;

void log_acceleration(int16_t x, int16_t y, int16_t z) {
    time_t now = time(NULL);
    struct tm *tm_info = gmtime(&now);
    fprintf(log_file, "%04d-%02d-%02dT%02d:%02d:%02d.%03d,%d,%d,%d\n",
            tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
            tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec, (int)(now % 1) * 1000,
            x, y, z);
}

void handle_sigint(int sig) {
    if (log_file) fclose(log_file);
    if (i2c_fd >= 0) close(i2c_fd);
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_SLAVE_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen("vibration_log.csv", "w");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    fprintf(log_file, "Timestamp,X,Y,Z\n");

    uint8_t reg = REG_X_LSB;
    while (1) {
        uint8_t data[6];
        if (read(i2c_fd, data, sizeof(data)) != sizeof(data)) {
            if (errno == EIO) {
                fprintf(stderr, "I2C read error, skipping sample\n");
            } else {
                perror("I2C read failed");
                break;
            }
        } else {
            int16_t x = (data[1] << 8) | data[0];
            int16_t y = (data[3] << 8) | data[2];
            int16_t z = (data[5] << 8) | data[4];
            log_acceleration(x, y, z);
        }
        usleep(SAMPLE_INTERVAL);
    }

    fclose(log_file);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

