#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define CONVEYOR_LOG "conveyor_log.txt"
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE1 17
#define GPIO_LINE2 27
#define SAMPLE_INTERVAL 50000  // 50 ms in microseconds

static struct gpiod_chip *chip;
static struct gpiod_line *line1, *line2;
static FILE *log_file;

void log_event(int sensor1, int sensor2) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    fprintf(log_file, "%ld.%03ld: Sensor1=%d, Sensor2=%d\n", ts.tv_sec, ts.tv_nsec / 1000000, sensor1, sensor2);
    fflush(log_file);
}

void halt_conveyor() {
    printf("Conveyor halted due to safety trigger.\n");
}

void handle_signal(int sig) {
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    struct gpiod_line_request req1 = { .consumer = "sensor1", .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT };
    struct gpiod_line_request req2 = { .consumer = "sensor2", .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT };

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, GPIO_LINE1);
    if (!line1) {
        perror("Failed to get GPIO line 1");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_LINE2);
    if (!line2) {
        perror("Failed to get GPIO line 2");
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(line1, &req1) < 0) {
        perror("Failed to request GPIO line 1");
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(line2, &req2) < 0) {
        perror("Failed to request GPIO line 2");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_file = fopen(CONVEYOR_LOG, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        int sensor1 = gpiod_line_get_value(line1);
        int sensor2 = gpiod_line_get_value(line2);

        if (sensor1 == 1 && sensor2 == 1) {
            halt_conveyor();
        }

        log_event(sensor1, sensor2);

        usleep(SAMPLE_INTERVAL);
    }

    // This point should never be reached
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);
    fclose(log_file);
    return EXIT_SUCCESS;
}

