#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>
#include <signal.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x1D
#define WHO_AM_I 0x0D
#define CTRL_REG1 0x2A
#define DATA_REGS 0x01
#define LOG_FILE "fall_log.txt"

int i2c_fd = -1;
FILE *log_file = NULL;

void close_resources() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
}

void signal_handler(int signum) {
    close_resources();
    exit(signum);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("ioctl");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t who_am_i;
    if (read(i2c_fd, &who_am_i, 1) != 1) {
        perror("read WHO_AM_I");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (who_am_i != 0x2A) {
        fprintf(stderr, "Sensor identity verification failed\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t ctrl_reg1;
    if (read(i2c_fd, &ctrl_reg1, 1) != 1) {
        perror("read CTRL_REG1");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    ctrl_reg1 &= ~(1 << 0); // Clear bit 0 to standby
    if (write(i2c_fd, &ctrl_reg1, 1) != 1) {
        perror("write CTRL_REG1");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    ctrl_reg1 |= (0x02 << 3); // Set data rate to 100 Hz
    if (write(i2c_fd, &ctrl_reg1, 1) != 1) {
        perror("write CTRL_REG1");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    ctrl_reg1 |= (1 << 0); // Set bit 0 to active
    if (write(i2c_fd, &ctrl_reg1, 1) != 1) {
        perror("write CTRL_REG1");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t data[7];
    while (1) {
        if (read(i2c_fd, data, 7) != 7) {
            perror("read data");
            continue;
        }

        int16_t x = (data[1] << 8) | data[0];
        int16_t y = (data[3] << 8) | data[2];
        int16_t z = (data[5] << 8) | data[4];

        x >>= 4;
        y >>= 4;
        z >>= 4;

        double tilt_angle = atan2(x, sqrt(y * y + z * z)) * 180 / M_PI;

        if (fabs(tilt_angle) > 45) {
            time_t now = time(NULL);
            char *timestamp = ctime(&now);
            timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

            fprintf(log_file, "%s X: %d Y: %d Z: %d\n", timestamp, x, y, z);
            fflush(log_file);
        }

        usleep(10000); // 10 ms loop interval
    }

    close_resources();
    return EXIT_SUCCESS;
}

