#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE "/dev/i2c-1"
#define LIS3MDL_ADDRESS 0x1E
#define WHO_AM_I 0x0F
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define CTRL_REG3 0x22
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define MAGNITUDE_THRESHOLD 800

#define RETRY_COUNT 3
#define SAMPLE_RATE 10
#define I2C_SPEED 100000

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buffer[2] = {reg, value};
    if (write(fd, buffer, 2) != 2) {
        perror("i2c_write");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t *buffer, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        perror("i2c_write");
        return -1;
    }
    if (read(fd, buffer, len) != len) {
        perror("i2c_read");
        return -1;
    }
    return 0;
}

int main() {
    int i2c_fd, log_fd;
    uint8_t buffer[6];
    double x, y, z, magnitude;
    double offset_x = 0.0, offset_y = 0.0, offset_z = 0.0;
    double scale_x = 1.0, scale_y = 1.0, scale_z = 1.0;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    for (int retry = 0; retry < RETRY_COUNT; retry++) {
        i2c_fd = open(I2C_DEVICE, O_RDWR);
        if (i2c_fd < 0) {
            perror("open");
            sleep(1);
            continue;
        }

        if (ioctl(i2c_fd, I2C_SLAVE, LIS3MDL_ADDRESS) < 0) {
            perror("ioctl");
            close(i2c_fd);
            sleep(1);
            continue;
        }

        uint8_t who_am_i;
        if (i2c_read(i2c_fd, WHO_AM_I, &who_am_i, 1) < 0) {
            close(i2c_fd);
            sleep(1);
            continue;
        }

        if (who_am_i != 0x3D) {
            fprintf(stderr, "LIS3MDL not found\n");
            close(i2c_fd);
            sleep(1);
            continue;
        }

        if (i2c_write(i2c_fd, CTRL_REG1, 0x70) < 0) {
            close(i2c_fd);
            sleep(1);
            continue;
        }

        if (i2c_write(i2c_fd, CTRL_REG4, 0x0C) < 0) {
            close(i2c_fd);
            sleep(1);
            continue;
        }

        if (i2c_write(i2c_fd, CTRL_REG3, 0x00) < 0) {
            close(i2c_fd);
            sleep(1);
            continue;
        }

        break;
    }

    if (retry == RETRY_COUNT) {
        fprintf(stderr, "Failed to initialize LIS3MDL after %d retries\n", RETRY_COUNT);
        return EXIT_FAILURE;
    }

    log_fd = open("magnetic_log.txt", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("open");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        if (i2c_read(i2c_fd, OUT_X_L, buffer, 6) < 0) {
            continue;
        }

        x = (buffer[1] << 8 | buffer[0]) * scale_x - offset_x;
        y = (buffer[3] << 8 | buffer[2]) * scale_y - offset_y;
        z = (buffer[5] << 8 | buffer[4]) * scale_z - offset_z;

        magnitude = sqrt(x * x + y * y + z * z);

        if (magnitude > MAGNITUDE_THRESHOLD) {
            fprintf(stderr, "Metal detected: %f mG\n", magnitude);
        }

        fprintf(log_fd, "%.2f,%.2f,%.2f\n", x, y, z);
        fflush(log_fd);

        usleep(1000000 / SAMPLE_RATE);
    }

    close(log_fd);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

