#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define ADXL354B_RESET 0x52
#define ADXL354B_PARTID 0x01
#define ADXL354B_XDATA 0x08
#define ADXL354B_YDATA 0x0B
#define ADXL354B_ZDATA 0x0E
#define ADXL354B_POWER_CTL 0x2D
#define ADXL354B_STATUS 0x04
#define ADXL354B_STABLE 0x01
#define ADXL354B_RUN 0x02
#define ADXL354B_READ_BIT 0x80
#define ADXL354B_MULTI_BYTE_BIT 0x40
#define ADXL354B_LSB_MASK 0xFF
#define ADXL354B_MSB_MASK 0x3F
#define ADXL354B_SIGN_BIT 0x80
#define ADXL354B_G_PER_LSB 0.0000039

volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
}

int read_spi(int handle, uint8_t reg, uint8_t *data, int length) {
    int retries = 3;
    while (retries--) {
        if (gpio_spi_xfer(handle, reg | ADXL354B_READ_BIT | ADXL354B_MULTI_BYTE_BIT, data, length) == length) {
            return 0;
        }
        usleep(1000);
    }
    return -1;
}

int main() {
    int handle, ret;
    FILE *log_file;
    uint8_t partid, reset, power_ctl, status;
    uint8_t xdata[3], ydata[3], zdata;
    int16_t x, y, z;
    struct timespec ts;

    if ((handle = gpioInitialise()) < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", handle);
        return 1;
    }

    if ((ret = gpioSetMode(8, PI_OUTPUT)) < 0) {
        fprintf(stderr, "Failed to set GPIO8 as output: %d\n", ret);
        gpioTerminate();
        return 1;
    }

    if ((ret = gpioSetPullUpDown(8, PI_PUD_UP)) < 0) {
        fprintf(stderr, "Failed to set GPIO8 pull-up: %d\n", ret);
        gpioTerminate();
        return 1;
    }

    if ((ret = gpioSetMode(9, PI_INPUT)) < 0) {
        fprintf(stderr, "Failed to set GPIO9 as input: %d\n", ret);
        gpioTerminate();
        return 1;
    }

    if ((ret = gpioSetPullUpDown(9, PI_PUD_DOWN)) < 0) {
        fprintf(stderr, "Failed to set GPIO9 pull-down: %d\n", ret);
        gpioTerminate();
