int read_spi(int handle, uint8_t reg, uint8_t *data, int length) {
    int retries = 3;
    while (retries--) {
        if (gpio_spi_xfer(handle, reg | ADXL354B_READ_BIT | ADXL354B_MULTI_BYTE_BIT, data, length) == length) {
            return 0;
        }
        usleep(1000);
    }
    return -1;
}

