#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 3
#define X_GYRO 0x04
#define Y_GYRO 0x06
#define Z_GYRO 0x08
#define X_ACCL 0x0A
#define Y_ACCL 0x0C
#define Z_ACCL 0x0E
#define GYRO_SCALE 0.05
#define ACCL_SCALE 0.0025
#define SAMPLE_INTERVAL 10000  // 10 ms

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

int main() {
    int spi_handle;
    FILE *log_file;
    struct timespec ts;
    uint8_t tx_buffer[2];
    uint8_t rx_buffer[2];
    double gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("imu_log.csv", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");

    signal(SIGINT, signal_handler);

    while (!stop_flag) {
        clock_gettime(CLOCK_REALTIME, &ts);

        // Read X_GYRO
        tx_buffer[0] = (X_GYRO | 0x80) << 1;
        tx_buffer[1] = 0x00;
        if (spiXfer(spi_handle, 2, tx_buffer, rx_buffer) < 0) {
            fprintf(stderr, "SPI transfer failed for X_GYRO\n");
            continue;
        }
        gyro_x = (rx_buffer[0] << 8 | rx_buffer[1]) * GYRO_SCALE;

        // Read Y_GYRO
        tx_buffer[0] = (Y_GYRO | 0x80) << 1;
        tx_buffer[1] = 0x00;
        if (spiXfer(spi_handle, 2, tx_buffer, rx_buffer) < 0) {
            fprintf(stderr, "SPI transfer failed for Y_GYRO\n");
            continue;
        }
        gyro_y = (rx_buffer[0] << 8 | rx_buffer[1]) * GYRO_SCALE;

        // Read Z_GYRO
        tx_buffer[0] = (Z_GYRO | 0x80) << 1;
        tx_buffer[1] = 0x00;
        if (spiXfer(spi_handle, 2, tx_buffer, rx_buffer) < 0) {
            fprintf(stderr, "SPI transfer failed for Z_GYRO\n");
            continue;
        }
        gyro_z = (rx_buffer[0] << 8 | rx_buffer[1]) * GYRO_SCALE;

        // Read X_ACCL
        tx_buffer[0] = (X_ACCL | 0x80) << 1;
        tx_buffer[1] = 0x00;
        if (spiXfer(spi_handle, 2, tx_buffer, rx_buffer) < 0) {
            fprintf(stderr, "SPI transfer failed for X_ACCL\n");
            continue;
        }
        accel_x = (rx_buffer[0] << 8 | rx_buffer[1]) * ACCL_SCALE;

        // Read Y_ACCL
        tx_buffer[0] = (Y_ACCL | 0x80) << 1;
        tx_buffer[1] = 0x00;
        if (spiXfer(spi_handle, 2, tx_buffer, rx_buffer) < 0) {
            fprintf(stderr, "SPI transfer failed for Y_ACCL\n");
            continue;
        }
        accel_y = (rx_buffer[0] << 8 | rx_buffer[1]) * ACCL_SCALE;

        // Read Z_ACCL
        tx_buffer[0] = (Z_ACCL | 0x80) << 1;
        tx_buffer[1] = 0x00;
        if (spiXfer(spi_handle, 2, tx_buffer, rx_buffer) < 0) {
            fprintf(stderr, "SPI transfer failed for Z_ACCL\n");
            continue;
        }
        accel_z = (rx_buffer[0] << 8 | rx_buffer[1]) * ACCL_SCALE;

        fprintf(log_file, "%ld.%09ld,%f,%f,%f,%f,%f,%f\n",
                ts.tv_sec, ts.tv_nsec, gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);

        nanosleep((struct timespec){0, SAMPLE_INTERVAL}, NULL);
    }

    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

