#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip4"
#define GPIO_LINE 17

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

void self_parking_sequence() {
    time_t now;
    struct tm *tm_info;
    char time_str[20];

    time(&now);
    tm_info = localtime(&now);
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
    printf("%s: Self-parking sequence started\n", time_str);

    // Simulate self-parking sequence
    sleep(2);

    time(&now);
    tm_info = localtime(&now);
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
    printf("%s: Self-parking sequence completed\n", time_str);
}

int main() {
    struct gpiod_line_request_config config = {
        .consumer = "ir_sensor",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
    };

    // Register signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request the GPIO line
    line = gpiod_line_open(chip, GPIO_LINE, GPIOD_LINE_REQUEST_DIRECTION_INPUT);
    if (!line) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("Failed to read GPIO line value");
            break;
        }

        if (value == 0) {
            self_parking_sequence();
        }

        sleep(1);
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

