#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define CS_PIN 8
#define SPI_MODE SPI_MODE_3
#define SPI_SPEED 1000000
#define SPI_BITS_PER_WORD 8
#define MSC_CTRL_REG 0x24
#define X_RATE_REG 0x04
#define Y_RATE_REG 0x06
#define Z_RATE_REG 0x08
#define REG_ADDR_MASK 0x80
#define REG_DATA_SIZE 2
#define SCALE_FACTOR 0.02

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *cs_line;
    int fd;
    uint8_t tx[2], rx[2];
    uint16_t x_rate, y_rate, z_rate;
    double x_rate_deg, y_rate_deg, z_rate_deg;

    // Initialize GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request CS line
    cs_line = gpiod_chip_get_line(chip, CS_PIN);
    if (!cs_line) {
        perror("Failed to get CS line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request CS line as output
    if (gpiod_line_request_output(cs_line, "adis16266_cs", 1)) {
        perror("Failed to request CS line as output");
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open SPI device
    fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set SPI mode
    if (ioctl(fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(fd);
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set SPI speed
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(fd);
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set SPI bits per word
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set SPI bits per word");
        close(fd);
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Enable data ready mode
    tx[0] = (MSC_CTRL_REG | REG_ADDR_MASK);
    tx[1] = 0x01;
    if (write(fd, tx, 2) != 2) {
        perror("Failed to write to MSC_CTRL register");
        close(fd);
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    while (running) {
        // Select CS line
        if (gpiod_line_set_value(cs_line, 0) < 0) {
            perror("Failed to select CS line");
            continue;
        }

        // Read X rate
        tx[0] = (X_RATE_REG | REG_ADDR_MASK);
        if (write(fd, tx, 1) != 1) {
            perror("Failed to write X rate address");
            gpiod_line_set_value(cs_line, 1);
            continue;
        }
        if (read(fd, rx, REG_DATA_SIZE) != REG_DATA_SIZE) {
            perror("Failed to read X rate data");
            gpiod_line_set_value(cs_line, 1);
            continue;
        }
        x_rate = (rx[0] << 8) | rx[1];
        x_rate_deg = x_rate * SCALE_FACTOR;

        // Read Y rate
        tx[0] = (Y_RATE_REG | REG_ADDR_MASK);
        if (write(fd, tx, 1) != 1) {
            perror("Failed to write Y rate address");
            gpiod_line_set_value(cs_line, 1);
            continue;
        }
        if (read(fd, rx, REG_DATA_SIZE) != REG_DATA_SIZE) {
            perror("Failed to read Y rate data");
            gpiod_line_set_value(cs_line, 1);
            continue;
        }
        y_rate = (rx[0] << 8) | rx[1];
        y_rate_deg = y_rate * SCALE_FACTOR;

        // Read Z rate
        tx[0] = (Z_RATE_REG | REG_ADDR_MASK);
        if (write(fd, tx, 1) != 1) {
            perror("Failed to write Z rate address");
            gpiod_line_set_value(cs_line, 1);
            continue;
        }
        if (read(fd, rx, REG_DATA_SIZE) != REG_DATA_SIZE) {
            perror("Failed to read Z rate data");
            gpiod_line_set_value(cs_line, 1);
            continue;
        }
        z_rate = (rx[0] << 8) | rx[1];
        z_rate_deg = z_rate * SCALE_FACTOR;

        // Deselect CS line
        gpiod_line_set_value(cs_line, 1);

        // Log results
        printf("X Rate: %.2f deg/sec, Y Rate: %.2f deg/sec, Z Rate: %.2f deg/sec\n",
               x_rate_deg, y_rate_deg, z_rate_deg);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up
    close(fd);
    gpiod_line_release(cs_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

