#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x6B
#define WHO_AM_I 0x0F
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22

volatile int running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    int i2c_handle = gpioI2COpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return 1;
    }

    uint8_t who_am_i = gpioI2CReadByte(i2c_handle, WHO_AM_I);
    if (who_am_i != 0x6B) {
        fprintf(stderr, "WHO_AM_I mismatch, expected 0x6B, got 0x%02X\n", who_am_i);
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t ctrl1_xl[2] = {CTRL1_XL, 0x42};
    if (gpioI2CWrite(i2c_handle, ctrl1_xl, 2) != 2) {
        fprintf(stderr, "Failed to write CTRL1_XL register\n");
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t ctrl2_g[2] = {CTRL2_G, 0x42};
    if (gpioI2CWrite(i2c_handle, ctrl2_g, 2) != 2) {
        fprintf(stderr, "Failed to write CTRL2_G register\n");
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (running) {
        uint8_t data[12];
        int bytes_read = gpioI2CRead(i2c_handle, OUTX_L_G, data, 12);
        if (bytes_read != 12) {
            fprintf(stderr, "Failed to read 12 bytes from sensor\n");
            break;
        }

        int16_t gyro_x = (data[0] | (data[1] << 8));
        int16_t gyro_y = (data[2] | (data[3] << 8));
        int16_t gyro_z = (data[4] | (data[5] << 8));
        int16_t accel_x = (data[6] | (data[7] << 8));
        int16_t accel_y = (data[8] | (data[9] << 8));
        int16_t accel_z = (data[10] | (data[11] << 8));

        double gyro_x_dps = gyro_x * 0.00875;
        double gyro_y_dps = gyro_y * 0.00875;
        double gyro_z_dps = gyro_z * 0.00875;
        double accel_x_g = accel_x * 0.000061;
        double accel_y_g = accel_y * 0.000061;
        double accel_z_g = accel_z * 0.000061;

        printf("Gyro: %.2f, %.2f, %.2f dps | Accel: %.4f, %.4f, %.4f g\n",
               gyro_x_dps, gyro_y_dps, gyro_z_dps,
               accel_x_g, accel_y_g, accel_z_g);

        gpioDelay(100000); // 100 ms
    }

    gpioI2CClose(i2c_handle);
    gpioTerminate();
    return 0;
}

