#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>

#define I2C_DEVICE "/dev/i2c-1"
#define ADXL345_ADDRESS 0x53
#define ADXL345_DATAX0 0x32
#define ADXL345_DATAY0 0x34
#define ADXL345_DATAZ0 0x36
#define TILT_THRESHOLD 30.0
#define LOG_FILE "/var/log/tilt_events.log"

int i2c_fd;
struct sigaction sa;

void i2c_init() {
    if ((i2c_fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void i2c_read(uint8_t reg, uint8_t *data, size_t len) {
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        exit(EXIT_FAILURE);
    }

    if (read(i2c_fd, data, len) != len) {
        perror("Failed to read data");
        exit(EXIT_FAILURE);
    }
}

void log_tilt_event(double x, double y, double z) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(log_file, "%s: X=%.2f, Y=%.2f, Z=%.2f\n", asctime(tm_info), x, y, z);
    fclose(log_file);
}

void handle_sigint(int sig) {
    close(i2c_fd);
    exit(EXIT_SUCCESS);
}

int main() {
    i2c_init();

    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to set signal handler");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    uint8_t data[6];
    while (1) {
        i2c_read(ADXL345_DATAX0, data, 6);

        int16_t x = (data[1] << 8) | data[0];
        int16_t y = (data[3] << 8) | data[2];
        int16_t z = (data[5] << 8) | data[4];

        double x_g = x / 256.0;
        double y_g = y / 256.0;
        double z_g = z / 256.0;

        double x_angle = atan2(x_g, sqrt(y_g * y_g + z_g * z_g)) * 180.0 / M_PI;
        double y_angle = atan2(y_g, sqrt(x_g * x_g + z_g * z_g)) * 180.0 / M_PI;

        if (fabs(x_angle) > TILT_THRESHOLD || fabs(y_angle) > TILT_THRESHOLD) {
            log_tilt_event(x_angle, y_angle, z_angle);
        }

        usleep(100000); // 100 ms
    }

    close(i2c_fd);
    return 0;
}

