#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define SAMPLE_INTERVAL 1
#define WINDOW_DURATION 5
#define MIN_THRESHOLD 1

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return 1;
    }

    int threshold;
    if (sscanf(argv[1], "%d", &threshold) != 1 || threshold <= 0) {
        fprintf(stderr, "Invalid threshold: %s\n", argv[1]);
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!stop_flag) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        int high_count = 0;
        for (int i = 0; i < WINDOW_DURATION * 1000 / SAMPLE_INTERVAL; i++) {
            if (gpioRead(GPIO_PIN) == PI_HIGH) {
                high_count++;
            }
            gpioDelay(SAMPLE_INTERVAL * 1000);
        }

        if (high_count > threshold) {
            printf("%s ALERT: High readings detected (%d)\n", timestamp, high_count);
        } else {
            printf("%s Status: %d high readings\n", timestamp, high_count);
        }

        sleep(1);
    }

    gpioTerminate();
    return 0;
}

