#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE_A 17
#define GPIO_LINE_B 27
#define CODE_LENGTH 6
#define ACCESS_LOG "access_log.txt"

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

void log_access(const char *code) {
    FILE *log_file = fopen(ACCESS_LOG, "a");
    if (!log_file) {
        perror("Failed to open access log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(log_file, "%s,%s\n", asctime(tm_info), code);
    fclose(log_file);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line_a, *line_b;
    char code[CODE_LENGTH + 1];
    char input[CODE_LENGTH + 1];
    int ret;

    // Initialize signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Get and request GPIO lines
    line_a = gpiod_chip_get_line(chip, GPIO_LINE_A);
    if (!line_a) {
        perror("Failed to get GPIO line A");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line_a, "door_access", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line A as output");
        gpiod_line_release(line_a);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line_b = gpiod_chip_get_line(chip, GPIO_LINE_B);
    if (!line_b) {
        perror("Failed to get GPIO line B");
        gpiod_line_release(line_a);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line_b, "door_access", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line B as output");
        gpiod_line_release(line_a);
        gpiod_line_release(line_b);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Generate and print random code
    srand(time(NULL));
    snprintf(code, sizeof(code), "%06d", rand() % 900000 + 100000);
    printf("Security code: %s\n", code);

    while (!stop_flag) {
        printf("Enter code: ");
        if (fgets(input, sizeof(input), stdin) == NULL) {
            perror("Failed to read input");
            continue;
        }

        // Remove newline character
        input[strcspn(input, "\n")] = 0;

        // Validate input
        if (strlen(input) != CODE_LENGTH || !strspn(input, "0123456789")) {
            printf("Invalid input. Please enter a 6-digit number.\n");
            continue;
        }

        // Check if code matches
        if (strcmp(input, code) == 0) {
            // Unlock Door A
            gpiod_line_set_value(line_a, 1);
            sleep(5);
            gpiod_line_set_value(line_a, 0);

            // Log access
            log_access(code);

            // Generate new random code
            snprintf(code, sizeof(code), "%06d", rand() % 900000 + 100000);
            printf("New security code: %s\n", code);
        } else {
            printf("Access denied\n");
        }
    }

    // Clean up
    gpiod_line_set_value(line_a, 0);
    gpiod_line_set_value(line_b, 0);
    gpiod_line_release(line_a);
    gpiod_line_release(line_b);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

