    // Generate and print random code
    srand(time(NULL));
    snprintf(code, sizeof(code), "%06d", rand() % 900000 + 100000);
    printf("Security code: %s\n", code);

    while (!stop_flag) {
        printf("Enter code: ");
        if (fgets(input, sizeof(input), stdin) == NULL) {
            perror("Failed to read input");
            continue;
        }

        // Remove newline character
        input[strcspn(input, "\n")] = 0;

        // Validate input
        if (strlen(input) != CODE_LENGTH || !strspn(input, "0123456789")) {
            printf("Invalid input. Please enter a 6-digit number.\n");
            continue;
        }

        // Check if code matches
        if (strcmp(input, code) == 0) {
            // Unlock Door A
            gpiod_line_set_value(line_a, 1);
            sleep(5);
            gpiod_line_set_value(line_a, 0);

            // Log access
            log_access(code);

            // Generate new random code
            snprintf(code, sizeof(code), "%06d", rand() % 900000 + 100000);
            printf("New security code: %s\n", code);
        } else {
            printf("Access denied\n");
        }
    }

    // Clean up
    gpiod_line_set_value(line_a, 0);
    gpiod_line_set_value(line_b, 0);
    gpiod_line_release(line_a);
    gpiod_line_release(line_b);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}
