#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDRESS 0x23
#define BH1750_COMMAND 0x21
#define CONVERSION_TIME 180000 // 180 ms in microseconds
#define LOG_FILE "light_log.txt"

int i2c_fd;
FILE *log_file;

void signal_handler(int sig) {
    if (log_file) fclose(log_file);
    if (i2c_fd) close(i2c_fd);
    exit(0);
}

int main() {
    struct timespec ts;
    uint16_t raw_value;
    double lux_value;
    char timestamp[20];
    char log_entry[100];

    // Open I2C bus
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    while (1) {
        // Send command to start measurement
        if (write(i2c_fd, &BH1750_COMMAND, 1) != 1) {
            perror("Failed to send command to BH1750");
            break;
        }

        // Wait for conversion to complete
        nanosleep(&ts, NULL);

        // Read 2 bytes of data
        if (read(i2c_fd, &raw_value, 2) != 2) {
            perror("Failed to read data from BH1750");
            break;
        }

        // Calculate lux value
        lux_value = (double)raw_value * 5 / 6;

        // Get current timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("Failed to get current time");
            break;
        }
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        // Log the reading
        snprintf(log_entry, sizeof(log_entry), "Timestamp: %s, Lux: %.2f\n", timestamp, lux_value);
        if (fputs(log_entry, log_file) == EOF) {
            perror("Failed to write to log file");
            break;
        }
        fflush(log_file);

        // Wait for 5 seconds before next reading
        ts.tv_sec = 5;
        ts.tv_nsec = 0;
    }

    // Clean up
    fclose(log_file);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

