#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x5A
#define PWM_PIN 18
#define PWM_FREQ 1000
#define PWM_RANGE 255
#define SOCKET_PORT 12345
#define SHARED_SECRET "MySecretKey"
#define LOG_FILE "frequency_log.txt"
#define PLAY_TIME 5000
#define SAMPLE_INTERVAL 20

volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_frequency(int frequency) {
    FILE *log = fopen(LOG_FILE, "a");
    if (log) {
        fprintf(log, "%d\n", frequency);
        fclose(log);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByteData(i2c_handle, 0x80, 0x00) < 0) {
        fprintf(stderr, "Failed to soft-reset MPR121\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByteData(i2c_handle, 0x5E, 0x00) < 0) {
        fprintf(stderr, "Failed to configure MPR121 electrodes\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", PWM_PIN);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioSetMode(PWM_PIN, PI_INPUT);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioSetMode(PWM_PIN, PI_INPUT);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    int server_fd, new_socket;
    struct sockaddr_in address;
    int addrlen = sizeof(address);
    char buffer[1024] = {0};

    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        gpioSetMode(PWM_PIN, PI_INPUT);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(SOCKET_PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(server_fd);
        gpioSetMode(PWM_PIN, PI_INPUT);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        perror("listen");
        close(server_fd);
        gpioSetMode(PWM_PIN, PI_INPUT);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("accept");
            continue;
        }

        int valread = read(new_socket, buffer, 1024);
        if (valread > 0) {
            buffer[valread] = '\0';
            if (strncmp(buffer, "MOTION_DETECTED:", 16) == 0 && strstr(buffer, SHARED_SECRET) != NULL) {
                int start_time = gpioTick();
                while (gpioTick() - start_time < PLAY_TIME && running) {
                    int touch_data = i2cReadByteData(i2c_handle, 0x00);
                    if (touch_data & 0x01) {
                        int frequency = 220 + (int)(log(touch_data) * 660);
                        if (frequency > 880) frequency = 880;
                        gpioSetPWMfrequency(PWM_PIN, frequency);
                        gpioSetPWMrange(PWM_PIN, frequency);
                        gpioSetPWMdutycycle(PWM_PIN, frequency);
                        log_frequency(frequency);
                    }
                    usleep(SAMPLE_INTERVAL * 1000);
                }
                gpioSetPWMdutycycle(PWM_PIN, 0);
            }
        }

        close(new_socket);
    }

    gpioSetMode(PWM_PIN, PI_INPUT);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

