#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>

#define I2C_DEVICE "/dev/i2c-1"
#define LSM303DLHC_ADDRESS 0x1E
#define CTRL_REG1_M 0x20
#define OUT_X_L_M 0x08
#define LED_PIN "gpiochip0/gpio17"
#define PWM_PERIOD 1000000 // 1 second period
#define SAMPLE_INTERVAL 100000 // 100 ms interval

static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;
static int pwm_fd = -1;

void cleanup() {
    if (led_line) {
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (pwm_fd >= 0) {
        close(pwm_fd);
    }
}

void signal_handler(int signum) {
    cleanup();
    exit(signum);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Initialize I2C
    if ((i2c_fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, LSM303DLHC_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize GPIO for LED
    chip = gpiod_chip_open_by_name(LED_PIN);
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    led_line = gpiod_chip_get_line(chip, 17);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize PWM
    if ((pwm_fd = open("/sys/class/pwm/pwmchip0/pwm0", O_WRONLY)) < 0) {
        perror("Failed to open PWM device");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (write(pwm_fd, "export", 6) < 0) {
        perror("Failed to export PWM");
        close(pwm_fd);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    usleep(100000); // Wait for export to complete
    if (write(pwm_fd, "period=1000000", 14) < 0) {
        perror("Failed to set PWM period");
        close(pwm_fd);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (write(pwm_fd, "duty_cycle=0", 12) < 0) {
        perror("Failed to set PWM duty cycle");
        close(pwm_fd);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (write(pwm_fd, "enable=1", 8) < 0) {
        perror("Failed to enable PWM");
        close(pwm_fd);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize magnetometer
    uint8_t ctrl_reg1_m = 0x18;
    if (write(i2c_fd, &ctrl_reg1_m, 1) != 1) {
        perror("Failed to write to magnetometer CTRL_REG1_M");
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        uint8_t buffer[6];
        if (read(i2c_fd, buffer, 6) != 6) {
            perror("Failed to read from magnetometer");
            continue;
        }

        int16_t x = (buffer[0] | (buffer[1] << 8));
        int16_t y = (buffer[2] | (buffer[3] << 8));
        int16_t z = (buffer[4] | (buffer[5] << 8));

        int16_t z_magnitude = abs(z);

        // Scale the LED brightness based on the Z-axis field magnitude
        int duty_cycle = (z_magnitude * PWM_PERIOD) / 32767;

        char duty_cycle_str[12];
        snprintf(duty_cycle_str, sizeof(duty_cycle_str), "%d", duty_cycle);
        if (write(pwm_fd, duty_cycle_str, strlen(duty_cycle_str)) != strlen(duty_cycle_str)) {
            perror("Failed to set PWM duty cycle");
        }

        usleep(SAMPLE_INTERVAL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

