#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1E
#define HMC5883L_CONFIG_A 0x70
#define HMC5883L_CONFIG_B 0x20
#define HMC5883L_MODE 0x00
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Y_MSB 0x05
#define HMC5883L_DATA_Y_LSB 0x06
#define HMC5883L_DATA_Z_MSB 0x07
#define HMC5883L_DATA_Z_LSB 0x08
#define SAMPLE_WINDOW 100
#define PRINT_INTERVAL 500

volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
}

int read_register(int handle, uint8_t reg, uint8_t *value) {
    if (i2c_write_byte_data(handle, reg, 0) < 0) {
        fprintf(stderr, "I2C write error\n");
        return -1;
    }
    if (i2c_read_byte_data(handle, reg, value) < 0) {
        fprintf(stderr, "I2C read error\n");
        return -1;
    }
    return 0;
}

int write_register(int handle, uint8_t reg, uint8_t value) {
    if (i2c_write_byte_data(handle, reg, value) < 0) {
        fprintf(stderr, "I2C write error\n");
        return -1;
    }
    return 0;
}

int main() {
    int handle;
    uint8_t data[6];
    int16_t x, y, z;
    int16_t offsets[3] = {0, 0, 0};
    int count = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "I2C open error\n");
        gpioTerminate();
        return 1;
    }

    if (write_register(handle, HMC5883L_CONFIG_A, 0x70) < 0 ||
        write_register(handle, HMC5883L_CONFIG_B, 0x20) < 0 ||
        write_register(handle, HMC5883L_MODE, 0x00) < 0) {
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        if (read_register(handle, HMC5883L_DATA_X_MSB, &data[0]) < 0 ||
            read_register(handle, HMC5883L_DATA_X_LSB, &data[1]) < 0 ||
            read_register(handle, HMC5883L_DATA_Y_MSB, &data[2]) < 0 ||
            read_register(handle, HMC5883L_DATA_Y_LSB, &data[3]) < 0 ||
            read_register(handle, HMC5883L_DATA_Z_MSB, &data[4]) < 0 ||
            read_register(handle, HMC5883L_DATA_Z_LSB, &data[5]) < 0) {
            continue;
        }

        x = (data[0] << 8) | data[1];
        y = (data[2] << 8) | data[3];
        z = (data[4] << 8) | data[5];

        offsets[0] += x;
        offsets[1] += y;
        offsets[2] += z;

        count++;
        if (count >= SAMPLE_WINDOW) {
            offsets[0] /= SAMPLE_WINDOW;
            offsets[1] /= SAMPLE_WINDOW;
            offsets[2] /= SAMPLE_WINDOW;

            printf("Offset-corrected: X=%d, Y=%d, Z=%d\n", x - offsets[0], y - offsets[1], z - offsets[2]);

            offsets[0] = 0;
            offsets[1] = 0;
            offsets[2] = 0;
            count = 0;
        }

        usleep(PRINT_INTERVAL * 1000);
    }

    i2cClose(handle);
    gpioTerminate();

    return 0;
}

