#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x1D
#define LSM303D_WHO_AM_I 0x0F
#define LSM303D_CTRL_REG1 0x20
#define LSM303D_CTRL_REG4 0x23
#define LSM303D_INT1_CFG 0x30
#define LSM303D_OUT_X_L_A 0x28
#define LSM303D_INT1_PIN 23
#define BUFFER_SIZE 64
#define SAMPLE_SIZE 6
#define THRESHOLD 125
#define DURATION 0

volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

int main() {
    int i2c_fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    uint8_t buffer[BUFFER_SIZE][SAMPLE_SIZE];
    int head = 0, tail = 0;
    struct timespec ts;

    // Open I2C device
    if ((i2c_fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    if ((chip = gpiod_chip_open_by_name("gpiochip0")) == NULL) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Request GPIO line
    if ((line = gpiod_chip_get_line(chip, LSM303D_INT1_PIN)) == NULL) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Configure GPIO line as input
    if (gpiod_line_request_input(line, "lsm303d_int1") < 0) {
        perror("Failed to request GPIO line as input");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Register signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    // Verify WHO_AM_I register
    uint8_t who_am_i;
    if (i2c_smbus_read_byte_data(i2c_fd, LSM303D_WHO_AM_I) != 0x49) {
        fprintf(stderr, "WHO_AM_I register does not match expected value\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Configure accelerometer
    if (i2c_smbus_write_byte_data(i2c_fd, LSM303D_CTRL_REG1, 0x57) < 0) {
        perror("Failed to write CTRL_REG1");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (i2c_smbus_write_byte_data(i2c_fd, LSM303D_CTRL_REG4, 0x00) < 0) {
        perror("Failed to write CTRL_REG4");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (i2c_smbus_write_byte_data(i2c_fd, LSM303D_INT1_CFG, 0x2A) < 0) {
        perror("Failed to write INT1_CFG");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        // Read acceleration data
        uint8_t data[SAMPLE_SIZE];
        if (i2c_smbus_read_i2c_block_data(i2c_fd, LSM303D_OUT_X_L_A | 0x80, SAMPLE_SIZE, data) < 0) {
            perror("Failed to read acceleration data");
            continue;
        }

        // Store sample in circular buffer
        memcpy(buffer[head], data, SAMPLE_SIZE);
        head = (head + 1) % BUFFER_SIZE;

        // Check for interrupt
        if (gpiod_line_get_value(line) == 1) {
            // Print timestamp
            clock_gettime(CLOCK_MONOTONIC, &ts);
            printf("Timestamp: %ld.%09ld\n", ts.tv_sec, ts.tv_nsec);

            // Dump last 10 buffered samples
            int count = (head - tail + BUFFER_SIZE) % BUFFER_SIZE;
            for (int i = 0; i < 10 && count > 0; i++) {
                printf("Sample %d: %02X %02X %02X %02X %02X %02X\n", i, buffer[tail][0], buffer[tail][1], buffer[tail][2], buffer[tail][3], buffer[tail][4], buffer[tail][5]);
                tail = (tail + 1) % BUFFER_SIZE;
                count--;
            }
        }

        // Sleep for 10 ms
        usleep(10000);
    }

    // Disable accelerometer
    if (i2c_smbus_write_byte_data(i2c_fd, LSM303D_CTRL_REG1, 0x00) < 0) {
        perror("Failed to disable accelerometer");
    }

    // Release resources
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

