#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_LOCK1 17
#define GPIO_LOCK2 27
#define UART_PRIMARY "/dev/serial0"
#define UART_SECONDARY "/dev/serial1"
#define CODE_LENGTH 6
#define TIMEOUT 5000000 // 5 seconds in microseconds
#define EXPECTED_CODE "123456"

volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_LOCK1, PI_OUTPUT);
    gpioSetMode(GPIO_LOCK2, PI_OUTPUT);
    gpioWrite(GPIO_LOCK1, 0); // Lock
    gpioWrite(GPIO_LOCK2, 0); // Lock

    int uart_primary = serialOpen(UART_PRIMARY, 9600);
    if (uart_primary < 0) {
        fprintf(stderr, "Failed to open %s\n", UART_PRIMARY);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int uart_secondary = serialOpen(UART_SECONDARY, 9600);
    if (uart_secondary < 0) {
        fprintf(stderr, "Failed to open %s\n", UART_SECONDARY);
        serialClose(uart_primary);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    char code_primary[CODE_LENGTH + 1] = {0};
    char code_secondary[CODE_LENGTH + 1] = {0};
    int code_length_primary = 0;
    int code_length_secondary = 0;

    while (running) {
        if (serialDataAvailable(uart_primary) > 0) {
            int c = serialGetChar(uart_primary);
            if (c >= '0' && c <= '9') {
                if (code_length_primary < CODE_LENGTH) {
                    code_primary[code_length_primary++] = c;
                }
            } else {
                code_length_primary = 0;
            }
        }

        if (serialDataAvailable(uart_secondary) > 0) {
            int c = serialGetChar(uart_secondary);
            if (c >= '0' && c <= '9') {
                if (code_length_secondary < CODE_LENGTH) {
                    code_secondary[code_length_secondary++] = c;
                }
            } else {
                code_length_secondary = 0;
            }
        }

        if (code_length_primary == CODE_LENGTH && code_length_secondary == CODE_LENGTH) {
            if (strcmp(code_primary, code_secondary) == 0 && strcmp(code_primary, EXPECTED_CODE) == 0) {
                gpioWrite(GPIO_LOCK1, 1); // Unlock
                gpioWrite(GPIO_LOCK2, 1); // Unlock
                usleep(2000000); // 2 seconds
                gpioWrite(GPIO_LOCK1, 0); // Lock
                gpioWrite(GPIO_LOCK2, 0); // Lock
            }
            code_length_primary = 0;
            code_length_secondary = 0;
        }

        usleep(10000); // 10 ms
    }

    serialClose(uart_primary);
    serialClose(uart_secondary);
    gpioTerminate();

    return EXIT_SUCCESS;
}

