#include <gpiod.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <stdlib.h>
#include <string.h>

#define PIR_PIN 4
#define RELAY_PIN 17
#define PIR_CHIP "gpiochip0"
#define RELAY_CHIP "gpiochip0"
#define PIR_LINE_NAME "pir_sensor"
#define RELAY_LINE_NAME "relay"
#define PIR_DEBOUNCE_TIME 50
#define RELAY_STRIKE_TIME 1000
#define FAILSAFE_TIME 10000

static struct gpiod_chip *pir_chip, *relay_chip;
static struct gpiod_line *pir_line, *relay_line;
static int running = 1;

void log_state(const char *message) {
    syslog(LOG_INFO, "%s", message);
}

void log_warning(const char *message) {
    syslog(LOG_WARNING, "%s", message);
}

void handle_signal(int sig) {
    running = 0;
}

void cleanup() {
    if (pir_line) {
        gpiod_line_release(pir_line);
    }
    if (relay_line) {
        gpiod_line_release(relay_line);
    }
    if (pir_chip) {
        gpiod_chip_close(pir_chip);
    }
    if (relay_chip) {
        gpiod_chip_close(relay_chip);
    }
    closelog();
}

int main() {
    struct gpiod_line_request_config config;
    int pir_value, relay_value, failsafe_timer = 0;

    openlog("motion_relay", LOG_PID, LOG_USER);

    // Open GPIO chips
    pir_chip = gpiod_chip_open_by_name(PIR_CHIP);
    if (!pir_chip) {
        log_state("Failed to open PIR GPIO chip");
        goto cleanup;
    }

    relay_chip = gpiod_chip_open_by_name(RELAY_CHIP);
    if (!relay_chip) {
        log_state("Failed to open Relay GPIO chip");
        goto cleanup;
    }

    // Request PIR line
    memset(&config, 0, sizeof(config));
    config.consumer = "motion_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    pir_line = gpiod_chip_get_line(pir_chip, PIR_PIN);
    if (!pir_line) {
        log_state("Failed to get PIR line");
        goto cleanup;
    }
    if (gpiod_line_request(pir_line, &config)) {
        log_state("Failed to request PIR line");
        goto cleanup;
    }

    // Request Relay line
    memset(&config, 0, sizeof(config));
    config.consumer = "relay";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    relay_line = gpiod_chip_get_line(relay_chip, RELAY_PIN);
    if (!relay_line) {
        log_state("Failed to get Relay line");
        goto cleanup;
    }
    if (gpiod_line_request(relay_line, &config)) {
        log_state("Failed to request Relay line");
        goto cleanup;
    }

    // Set initial state
    gpiod_line_set_value(relay_line, 0);

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (running) {
        // Read PIR sensor
        pir_value = gpiod_line_get_value(pir_line);
        if (pir_value < 0) {
            log_state("Failed to read PIR sensor");
            goto cleanup;
        }

        // Check for motion
        if (pir_value) {
            log_state("Motion detected");
            gpiod_line_set_value(relay_line, 1);
            log_state("Relay on");
            usleep(RELAY_STRIKE_TIME * 1000);
            gpiod_line_set_value(relay_line, 0);
            log_state("Relay off");
            failsafe_timer = 0;
        } else {
            failsafe_timer += PIR_DEBOUNCE_TIME;
            if (failsafe_timer > FAILSAFE_TIME) {
                log_warning("Potential malfunction: PIR sensor remains HIGH for too long");
                gpiod_line_set_value(relay_line, 0);
                log_state("Relay off due to failsafe");
                failsafe_timer = 0;
            }
        }

        // Poll PIR sensor
        usleep(PIR_DEBOUNCE_TIME * 1000);
    }

cleanup:
    cleanup();
    closelog();
    return 0;
}

