This C program uses the libgpiod library to control a 5V relay connected to GPIO17 based on motion detected by an HC-SR501 PIR sensor on GPIO4. It logs state transitions and potential malfunctions to the system journal. The program handles clean shutdown on SIGINT/SIGTERM.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <syslog.h>

#define RELAY_PINS (1 << 4 | 1 << 17 | 1 << 27 | 1 << 22)
#define RELAY_COUNT 4
#define RELAY_ON_TIME 300
#define RELAY_PAUSE_TIME 60
#define TIMER_INTERVAL 60

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

void log_state_change(int relay, int state) {
    char timestamp[20];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    syslog(LOG_INFO, "Relay %d: %s", relay, state ? "ON" : "OFF");
}

void timer_callback(int timer_id, void *user_data) {
    static int current_relay = 0;
    static int current_state = 0; // 0: pause, 1: on, 2: off

    if (current_state == 0) {
        gpioWrite(current_relay, 0); // Activate relay
        log_state_change(current_relay, 1);
        current_state = 1;
        gpioSetTimerFuncEx(timer_id, RELAY_ON_TIME * 1000, timer_callback, NULL);
    } else if (current_state == 1) {
        gpioWrite(current_relay, 1); // Deactivate relay
        log_state_change(current_relay, 0);
        current_state = 2;
        gpioSetTimerFuncEx(timer_id, RELAY_PAUSE_TIME * 1000, timer_callback, NULL);
    } else if (current_state == 2) {
        current_relay = (current_relay + 1) % RELAY_COUNT;
        current_state = 0;
        gpioSetTimerFuncEx(timer_id, TIMER_INTERVAL * 1000, timer_callback, NULL);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < RELAY_COUNT; i++) {
        int pin = 1 << (4 + i);
        gpioSetMode(pin, PI_OUTPUT);
        gpioWrite(pin, 1); // Initialize all relays to OFF (HIGH)
    }

    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);

    gpioSetTimerFuncEx(0, TIMER_INTERVAL * 1000, timer_callback, NULL);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!stop_flag) {
        sleep(1);
    }

    for (int i = 0; i < RELAY_COUNT; i++) {
        gpioWrite(1 << (4 + i), 1); // Deactivate all relays
        log_state_change(1 << (4 + i), 0);
    }

    gpioTerminate();
    closelog();

    return EXIT_SUCCESS;
}

