#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x68
#define ACCEL_XOUT_H 0x3B
#define ACCEL_CONFIG 0x1C
#define PWR_MGMT_1 0x6B
#define BUFFER_SIZE 1024
#define SAMPLE_RATE 100

typedef struct {
    int fd;
    int sysfs_fd;
    char buffer[BUFFER_SIZE];
    size_t head, tail;
    int running;
} Accelerometer;

void init_mpu6050(Accelerometer *acc) {
    uint8_t data[2];
    data[0] = PWR_MGMT_1;
    data[1] = 0x00;
    if (write(acc->fd, data, 2) != 2) {
        perror("Failed to wake MPU6050");
        exit(EXIT_FAILURE);
    }
    data[0] = ACCEL_CONFIG;
    data[1] = 0x00;
    if (write(acc->fd, data, 2) != 2) {
        perror("Failed to set accelerometer range");
        exit(EXIT_FAILURE);
    }
}

void read_acceleration(Accelerometer *acc) {
    uint8_t data[6];
    if (read(acc->fd, data, 6) != 6) {
        perror("Failed to read acceleration data");
        return;
    }
    int16_t x = (data[0] << 8) | data[1];
    int16_t y = (data[2] << 8) | data[3];
    int16_t z = (data[4] << 8) | data[5];
    float x_g = x / 16384.0;
    float y_g = y / 16384.0;
    float z_g = z / 16384.0;
    size_t next = (acc->head + 1) % BUFFER_SIZE;
    if (next != acc->tail) {
        acc->buffer[acc->head] = (char)x_g;
        acc->buffer[acc->head + 1] = (char)y_g;
        acc->buffer[acc->head + 2] = (char)z_g;
        acc->head = next;
    }
}

void write_sysfs(Accelerometer *acc) {
    if (acc->sysfs_fd != -1) {
        lseek(acc->sysfs_fd, 0, SEEK_SET);
        write(acc->sysfs_fd, &acc->buffer[acc->tail], 3);
        acc->tail = (acc->tail + 3) % BUFFER_SIZE;
    }
}

void signal_handler(int signum) {
    Accelerometer *acc = (Accelerometer *)signum;
    acc->running = 0;
}

int main() {
    Accelerometer acc = {0};
    acc.fd = open(I2C_BUS, O_RDWR);
    if (acc.fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }
    if (ioctl(acc.fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(acc.fd);
        exit(EXIT_FAILURE);
    }
    init_mpu6050(&acc);

    acc.sysfs_fd = open("/sys/kernel/mpu6050_accel/latest", O_WRONLY | O_CREAT, 0666);
    if (acc.sysfs_fd < 0) {
        perror("Failed to open sysfs file");
        close(acc.fd);
        exit(EXIT_FAILURE);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set signal handler");
        close(acc.fd);
        close(acc.sysfs_fd);
        exit(EXIT_FAILURE);
    }

    struct sigevent sev;
    memset(&sev, 0, sizeof(sev));
    sev.sigev_notify = SIGEV_SIGNAL;
    sev.sigev_signo = SIGRTMIN;
    sev.sigev_value.sival_ptr = &acc;
    timer_t timerid;
    struct itimerspec its;
    if (timer_create(CLOCK_REALTIME, &sev, &timerid) < 0) {
        perror("Failed to create timer");
        close(acc.fd);
        close(acc.sysfs_fd);
        exit(EXIT_FAILURE);
    }
    its.it_value.tv_sec = 0;
    its.it_value.tv_nsec = 10000000; // 100 Hz
    its.it_interval.tv_sec = 0;
    its.it_interval.tv_nsec = 10000000;
    if (timer_settime(timerid, 0, &its, NULL) < 0) {
        perror("Failed to set timer");
        close(acc.fd);
        close(acc.sysfs_fd);
        timer_delete(timerid);
        exit(EXIT_FAILURE);
    }

    acc.running = 1;
    while (acc.running) {
        read_acceleration(&acc);
        write_sysfs(&acc);
    }

    close(acc.fd);
    close(acc.sysfs_fd);
    timer_delete(timerid);
    return 0;
}

