#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINES {18, 23, 24, 25}
#define INTERVALS {2, 3, 5, 7}

volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[4];
    struct timespec now, last_times[4];
    int i, ret;

    // Register signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request GPIO lines
    for (i = 0; i < 4; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_LINES[i]);
        if (!lines[i]) {
            perror("Failed to get GPIO line");
            goto cleanup;
        }

        ret = gpiod_line_request_output(lines[i], "smart_lighting", 0);
        if (ret < 0) {
            perror("Failed to request GPIO line as output");
            goto cleanup;
        }
    }

    // Initialize last times
    for (i = 0; i < 4; i++) {
        last_times[i].tv_sec = 0;
        last_times[i].tv_nsec = 0;
    }

    // Main loop
    while (running) {
        clock_gettime(CLOCK_MONOTONIC, &now);

        for (i = 0; i < 4; i++) {
            if (now.tv_sec - last_times[i].tv_sec >= INTERVALS[i]) {
                ret = gpiod_line_set_value(lines[i], !gpiod_line_get_value(lines[i]));
                if (ret < 0) {
                    perror("Failed to set GPIO line value");
                } else {
                    last_times[i] = now;
                }
            }
        }

        // Sleep for a short period to reduce CPU usage
        usleep(100000);
    }

cleanup:
    // Release GPIO lines
    for (i = 0; i < 4; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

