#define SOUND_SENSOR_PIN 17
#define RELAY_PIN 27
#define THRESHOLD 1
#define ALARM_DURATION 3000000 // 3 seconds in microseconds
#define DEBOUNCE_TIME 500000 // 500 ms in microseconds

volatile int alarm_active = 0;

void log_alarm_time() {
    FILE *log_file = fopen("alarm_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    fprintf(log_file, "Alarm triggered at: %s", ctime(&now));
    fclose(log_file);
}

void gpio_callback(int gpio, int level, uint32_t tick) {
    if (level == PI_TIMEOUT) return;

    if (gpio == SOUND_SENSOR_PIN && level == 1) {
        if (!alarm_active) {
            alarm_active = 1;
            log_alarm_time();
            gpioWrite(RELAY_PIN, PI_HIGH);
            gpioSetTimerFunc(RELAY_PIN, ALARM_DURATION, 0, NULL);
        }
    }
}

void gpio_timer_callback(int gpio, int level, uint32_t tick) {
    gpioWrite(RELAY_PIN, PI_LOW);
    alarm_active = 0;
}

void signal_handler(int sig) {
    gpioWrite(RELAY_PIN, PI_LOW);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioSetPullUpDown(SOUND_SENSOR_PIN, PI_PUD_DOWN);

    gpioSetWatchdog(SOUND_SENSOR_PIN, DEBOUNCE_TIME);
    gpioSetAlertFunc(SOUND_SENSOR_PIN, gpio_callback);

    gpioSetTimerFunc(RELAY_PIN, ALARM_DURATION, 0, gpio_timer_callback);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        gpioDelay(100000); // 100 ms
    }

    gpioTerminate();
    return 0;
}

