#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define GYRO_XOUT_H 0x43
#define WHO_AM_I 0x75
#define PWR_MGMT_1 0x6B
#define GYRO_SENSITIVITY 131.0
#define BUFFER_SIZE 100

typedef struct {
    int fd;
    uint8_t buffer[BUFFER_SIZE][6];
    int head;
    int tail;
} GyroData;

GyroData gyro_data;

void init_gyro() {
    if ((gyro_data.fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(gyro_data.fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(gyro_data.fd);
        exit(EXIT_FAILURE);
    }

    uint8_t who_am_i;
    if (read(gyro_data.fd, &who_am_i, 1) != 1) {
        perror("Failed to read WHO_AM_I register");
        close(gyro_data.fd);
        exit(EXIT_FAILURE);
    }

    if (who_am_i != MPU6050_ADDR) {
        fprintf(stderr, "Incorrect device ID: 0x%02X\n", who_am_i);
        close(gyro_data.fd);
        exit(EXIT_FAILURE);
    }

    uint8_t pwr_mgmt_1 = 0;
    if (write(gyro_data.fd, &pwr_mgmt_1, 1) != 1) {
        perror("Failed to clear sleep bit in PWR_MGMT_1");
        close(gyro_data.fd);
        exit(EXIT_FAILURE);
    }
}

void read_gyro_data() {
    uint8_t buffer[6];
    if (read(gyro_data.fd, buffer, 6) != 6) {
        perror("Failed to read gyroscope data");
        return;
    }

    int16_t x = (buffer[0] << 8) | buffer[1];
    int16_t y = (buffer[2] << 8) | buffer[3];
    int16_t z = (buffer[4] << 8) | buffer[5];

    double angular_velocity = sqrt(x * x + y * y + z * z) / GYRO_SENSITIVITY;

    if (angular_velocity > 50.0) {
        // Trigger user-defined callback function here
        printf("Angular velocity exceeded threshold: %.2f deg/s\n", angular_velocity);
    }

    gyro_data.buffer[gyro_data.head][0] = x;
    gyro_data.buffer[gyro_data.head][1] = y;
    gyro_data.buffer[gyro_data.head][2] = z;
    gyro_data.buffer[gyro_data.head][3] = angular_velocity;
    gyro_data.head = (gyro_data.head + 1) % BUFFER_SIZE;

    if (gyro_data.head == gyro_data.tail) {
        gyro_data.tail = (gyro_data.tail + 1) % BUFFER_SIZE;
    }
}

void cleanup() {
    close(gyro_data.fd);
}

void signal_handler(int sig) {
    cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, signal_handler);

    init_gyro();

    while (1) {
        read_gyro_data();
        usleep(10000); // 10 ms delay
    }

    return 0;
}
```

This C program initializes the MPU-6050 gyroscope on the Raspberry Pi 3 Model B+ using the Linux I2C user-space API. It reads the gyroscope data, calculates the angular velocity, and logs it to a circular buffer. If the angular velocity exceeds a threshold of 50.0 degrees/second, it triggers a user-defined callback function (currently a print statement). The program handles errors, ensures clean resource release on all exit paths, and gracefully shuts down on SIGINT (Ctrl+C).

