#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/serial0"
#define UART_BAUD 9600
#define READ_COMMAND {0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79}
#define CHECKSUM_INDEX 7
#define RESPONSE_LENGTH 9
#define LOG_INTERVAL 5
#define ERROR_LOG "co2_error.log"
#define LOG_FILE "co2_log.json"

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

int main() {
    int uart_handle;
    FILE *log_file = fopen(LOG_FILE, "a");
    FILE *error_log = fopen(ERROR_LOG, "a");
    if (!log_file || !error_log) {
        perror("Failed to open log files");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(error_log, "%lu: Failed to initialise pigpio\n", time(NULL));
        fclose(log_file);
        fclose(error_log);
        return EXIT_FAILURE;
    }

    uart_handle = serOpen(UART_DEVICE, UART_BAUD, 0);
    if (uart_handle < 0) {
        fprintf(error_log, "%lu: Failed to open UART\n", time(NULL));
        gpioTerminate();
        fclose(log_file);
        fclose(error_log);
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!stop_flag) {
        if (serWrite(uart_handle, READ_COMMAND, sizeof(READ_COMMAND)) != sizeof(READ_COMMAND)) {
            fprintf(error_log, "%lu: Failed to write to UART\n", time(NULL));
            continue;
        }

        uint8_t response[RESPONSE_LENGTH];
        int bytes_read = 0;
        time_t start_time = time(NULL);
        while (bytes_read < RESPONSE_LENGTH && time(NULL) - start_time < 1) {
            if (serDataAvailable(uart_handle) > 0) {
                bytes_read += serRead(uart_handle, response + bytes_read, RESPONSE_LENGTH - bytes_read);
            }
        }

        if (bytes_read != RESPONSE_LENGTH) {
            fprintf(error_log, "%lu: Incomplete read from UART\n", time(NULL));
            continue;
        }

        uint8_t checksum = 0;
        for (int i = 1; i < CHECKSUM_INDEX; i++) {
            checksum += response[i];
        }
        checksum = ~checksum + 1;

        if (checksum != response[CHECKSUM_INDEX]) {
            fprintf(error_log, "%lu: Checksum mismatch\n", time(NULL));
            continue;
        }

        uint16_t co2_ppm = (response[2] << 8) | response[3];

        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        uint64_t timestamp = ts.tv_sec * 1000000 + ts.tv_nsec / 1000;

        fprintf(log_file, "{\"timestamp\": %llu, \"ppm\": %u, \"error\": false}\n", timestamp, co2_ppm);
        fflush(log_file);
        printf("{\"timestamp\": %llu, \"ppm\": %u, \"error\": false}\n", timestamp, co2_ppm);

        sleep(LOG_INTERVAL);
    }

    serClose(uart_handle);
    gpioTerminate();
    fclose(log_file);
    fclose(error_log);

    return EXIT_SUCCESS;
}

