#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1E
#define CONFIG_A 0x00
#define CONFIG_B 0x01
#define MODE 0x02
#define DATA_REG 0x03
#define X_OFFSET 100
#define Y_OFFSET -50
#define TARGET_HEADING 90.0
#define DEGREES_TO_RADIANS (M_PI / 180.0)
#define BUFFER_SIZE 100

volatile int running = 1;
volatile float heading_buffer[BUFFER_SIZE];
volatile int buffer_index = 0;

void signal_handler(int signum) {
    running = 0;
}

int read_heading() {
    uint8_t data[6];
    int rc = i2c_read_device(I2C_BUS, I2C_ADDR, DATA_REG, data, 6);
    if (rc != 6) {
        fprintf(stderr, "I2C read error: %d\n", rc);
        return -1;
    }
    int16_t x = (data[0] << 8) | data[1];
    int16_t z = (data[2] << 8) | data[3];
    int16_t y = (data[4] << 8) | data[5];
    float heading = atan2(y - Y_OFFSET, x - X_OFFSET) * DEGREES_TO_RADIANS;
    if (heading < 0) heading += 2 * M_PI;
    return (int)(heading * 180.0 / M_PI);
}

void log_heading(float heading) {
    heading_buffer[buffer_index] = heading;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (i2cOpen(I2C_BUS, I2C_ADDR, 0) < 0) {
        fprintf(stderr, "I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    uint8_t config_a = 0x70;
    uint8_t config_b = 0x20;
    uint8_t mode = 0x00;

    if (i2cWriteByteData(I2C_BUS, I2C_ADDR, CONFIG_A, config_a) < 0) {
        fprintf(stderr, "I2C write CONFIG_A failed\n");
        i2cClose(I2C_BUS);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByteData(I2C_BUS, I2C_ADDR, CONFIG_B, config_b) < 0) {
        fprintf(stderr, "I2C write CONFIG_B failed\n");
        i2cClose(I2C_BUS);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByteData(I2C_BUS, I2C_ADDR, MODE, mode) < 0) {
        fprintf(stderr, "I2C write MODE failed\n");
        i2cClose(I2C_BUS);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        int heading = read_heading();
        if (heading != -1) {
            log_heading(heading);
            if (abs(heading - TARGET_HEADING) > 10) {
                gpioWrite(17, PI_HIGH);
            } else {
                gpioWrite(17, PI_LOW);
            }
        }
        gpioDelay(100000); // 100 ms
    }

    i2cClose(I2C_BUS);
    gpioTerminate();
    return 0;
}

