#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define RED_RELAY_LINE "gpiochip0:line17"
#define GREEN_RELAY_LINE "gpiochip0:line27"
#define BLUE_RELAY_LINE "gpiochip0:line22"
#define LOG_FILE "lighting_log.txt"

int i2c_fd;
struct gpiod_chip *chip;
struct gpiod_line *red_line, *green_line, *blue_line;
FILE *log_file;

void init_i2c() {
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void init_relays() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }
    red_line = gpiod_chip_get_line(chip, 17);
    green_line = gpiod_chip_get_line(chip, 27);
    blue_line = gpiod_chip_get_line(chip, 22);
    if (!red_line || !green_line || !blue_line) {
        perror("Failed to get GPIO lines");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    gpiod_line_request_output(red_line, "red_relay", 0);
    gpiod_line_request_output(green_line, "green_relay", 0);
    gpiod_line_request_output(blue_line, "blue_relay", 0);
}

void init_log_file() {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

void read_bh1750() {
    uint8_t data[2];
    if (write(i2c_fd, "\x10", 1) != 1) {
        perror("Failed to write to BH1750");
        return;
    }
    usleep(120 * 1000);
    if (read(i2c_fd, data, 2) != 2) {
        perror("Failed to read from BH1750");
        return;
    }
    uint16_t lux_raw = (data[0] << 8) | data[1];
    double lux = lux_raw / 1.2;
    printf("Lux: %.2f\n", lux);

    int red_state = lux < 50;
    int green_state = lux >= 50 && lux < 150;
    int blue_state = lux >= 150 && lux < 300;
    int all_state = lux >= 300;

    gpiod_line_set_value(red_line, red_state);
    gpiod_line_set_value(green_line, green_state);
    gpiod_line_set_value(blue_line, blue_state);

    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, Lux: %.2f, Red: %d, Green: %d, Blue: %d, All: %d\n",
            tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
            tm->tm_hour, tm->tm_min, tm->tm_sec, lux, red_state, green_state, blue_state, all_state);
    fflush(log_file);
}

void cleanup() {
    if (log_file) fclose(log_file);
    if (red_line) gpiod_line_release(red_line);
    if (green_line) gpiod_line_release(green_line);
    if (blue_line) gpiod_line_release(blue_line);
    if (chip) gpiod_chip_close(chip);
    if (i2c_fd) close(i2c_fd);
}

void signal_handler(int sig) {
    cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    init_i2c();
    init_relays();
    init_log_file();

    while (1) {
        read_bh1750();
        sleep(1);
    }

    cleanup();
    return 0;
}

