    struct tm *tm = localtime(&now);
    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, Lux: %.2f, Red: %d, Green: %d, Blue: %d, All: %d\n",
            tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
            tm->tm_hour, tm->tm_min, tm->tm_sec, lux, red_state, green_state, blue_state, all_state);
    fflush(log_file);
}

void cleanup() {
    if (log_file) fclose(log_file);
    if (red_line) gpiod_line_release(red_line);
    if (green_line) gpiod_line_release(green_line);
    if (blue_line) gpiod_line_release(blue_line);
    if (chip) gpiod_chip_close(chip);
    if (i2c_fd) close(i2c_fd);
}

void signal_handler(int sig) {
    cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    init_i2c();
    init_relays();
    init_log_file();

    while (1) {
        read_bh1750();
        sleep(1);
    }

    cleanup();
    return 0;
}
