#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PINS {4, 17, 27, 22}
#define PWM_FREQ 100
#define TRANSITION_TIME 1800

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

void init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise GPIO\n");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < 4; i++) {
        gpioSetMode(GPIO_PINS[i], PI_OUTPUT);
        gpioSetPWMfrequency(GPIO_PINS[i], PWM_FREQ);
        gpioSetPWMrange(GPIO_PINS[i], 100);
        gpioWrite(GPIO_PINS[i], 0);
    }
}

void cleanup_gpio() {
    for (int i = 0; i < 4; i++) {
        gpioWrite(GPIO_PINS[i], 0);
        gpioSetMode(GPIO_PINS[i], PI_INPUT);
    }
    gpioTerminate();
}

void fade_lamp(int gpio, int on) {
    int start = gpioRead(gpio);
    int target = on ? 100 : 0;
    int step = (target - start) / (TRANSITION_TIME / 1000);
    for (int i = 0; i < TRANSITION_TIME / 1000; i++) {
        gpioSetPWMrange(gpio, 100);
        gpioSetPWMdutycycle(gpio, start + step * i);
        gpioDelay(1000);
    }
    gpioSetPWMdutycycle(gpio, target);
}

int parse_schedule_entry(char *line, int *hour, int *minute, int *second, int *relay, int *on) {
    char *token = strtok(line, ":");
    if (token == NULL || sscanf(token, "%d", hour) != 1) return -1;
    token = strtok(NULL, ":");
    if (token == NULL || sscanf(token, "%d", minute) != 1) return -1;
    token = strtok(NULL, ":");
    if (token == NULL || sscanf(token, "%d", second) != 1) return -1;
    token = strtok(NULL, ":");
    if (token == NULL || sscanf(token, "%d", relay) != 1) return -1;
    token = strtok(NULL, ":");
    if (token == NULL || sscanf(token, "%d", on) != 1) return -1;
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    init_gpio();

    FILE *file = fopen("lighting_schedule.txt", "r");
    if (file == NULL) {
        fprintf(stderr, "Failed to open lighting_schedule.txt\n");
        cleanup_gpio();
        exit(EXIT_FAILURE);
    }

    while (running) {
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        int current_hour = tm->tm_hour;
        int current_minute = tm->tm_min;
        int current_second = tm->tm_sec;

        char line[256];
        while (fgets(line, sizeof(line), file) != NULL) {
            int hour, minute, second, relay, on;
            if (parse_schedule_entry(line, &hour, &minute, &second, &relay, &on) == 0) {
                if (current_hour == hour && current_minute == minute && current_second == second) {
                    if (relay >= 0 && relay < 4) {
                        fade_lamp(GPIO_PINS[relay], on);
                    }
                }
            }
        }
        rewind(file);
        gpioDelay(1000000); // Check every second
    }

    fclose(file);
    cleanup_gpio();
    return 0;
}

