This C program uses the pigpio library to control four relay-controlled lamp actuators on GPIO4, GPIO17, GPIO27, and GPIO22. It reads a 24-hour schedule from `lighting_schedule.txt` and simulates a smart home lighting system with a sunrise/sunset effect. The program checks the schedule every second and, when the current time matches an entry, smoothly fades the lamp's brightness using PWM over a 30-minute transition. It handles file read errors, GPIO initialization failures, and invalid schedule entries gracefully. The program uses SIGINT/SIGTERM signal handling to turn off all relays and release GPIO resources cleanly on exit.

code:
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18
#define MIN_DISTANCE 2
#define MAX_DISTANCE 30
#define MIN_FREQ 200
#define MAX_FREQ 2000
#define MEASUREMENT_INTERVAL 60000
#define LOOP_INTERVAL 20000

volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    signal(SIGINT, signal_handler);

    while (running) {
        gpioWrite(TRIGGER_PIN, 0);
        gpioDelay(10);
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(10);
        gpioWrite(TRIGGER_PIN, 0);

        uint64_t start = gpioTick();
        while (gpioRead(ECHO_PIN) == 0 && gpioTick() - start < MEASUREMENT_INTERVAL) {
            // Wait for echo start
        }
        if (gpioTick() - start >= MEASUREMENT_INTERVAL) {
            fprintf(stderr, "Sensor timeout\n");
            continue;
        }

        uint64_t echo_start = gpioTick();
        while (gpioRead(ECHO_PIN) == 1 && gpioTick() - echo_start < MEASUREMENT_INTERVAL) {
            // Wait for echo end
        }
        if (gpioTick() - echo_start >= MEASUREMENT_INTERVAL) {
            fprintf(stderr, "Sensor timeout\n");
            continue;
        }

        uint64_t echo_duration = gpioTick() - echo_start;
        double distance = echo_duration * 0.034 / 2;

        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            fprintf(stderr, "Invalid distance: %f cm\n", distance);
            continue;
        }

        double frequency = MIN_FREQ + (distance - MIN_DISTANCE) * (MAX_FREQ - MIN_FREQ) / (MAX_DISTANCE - MIN_DISTANCE);
        frequency = frequency < MIN_FREQ ? MIN_FREQ : (frequency > MAX_FREQ ? MAX_FREQ : frequency);

        gpioSetPWMfrequency(BUZZER_PIN, (int)frequency);
        gpioSetPWMrange(BUZZER_PIN, 1000);
        gpioSetPWMdutycycle(BUZZER_PIN, 500);

        gpioDelay(LOOP_INTERVAL);
    }

    gpioSetPWMdutycycle(BUZZER_PIN, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

