        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(10);
        gpioWrite(TRIGGER_PIN, 0);

        uint64_t start = gpioTick();
        while (gpioRead(ECHO_PIN) == 0 && gpioTick() - start < MEASUREMENT_INTERVAL) {
            // Wait for echo start
        }
        if (gpioTick() - start >= MEASUREMENT_INTERVAL) {
            fprintf(stderr, "Sensor timeout\n");
            continue;
        }

        uint64_t echo_start = gpioTick();
        while (gpioRead(ECHO_PIN) == 1 && gpioTick() - echo_start < MEASUREMENT_INTERVAL) {
            // Wait for echo end
        }
        if (gpioTick() - echo_start >= MEASUREMENT_INTERVAL) {
            fprintf(stderr, "Sensor timeout\n");
            continue;
        }

        uint64_t echo_duration = gpioTick() - echo_start;
        double distance = echo_duration * 0.034 / 2;

        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            fprintf(stderr, "Invalid distance: %f cm\n", distance);
            continue;
        }

        double frequency = MIN_FREQ + (distance - MIN_DISTANCE) * (MAX_FREQ - MIN_FREQ) / (MAX_DISTANCE - MIN_DISTANCE);
        frequency = frequency < MIN_FREQ ? MIN_FREQ : (frequency > MAX_FREQ ? MAX_FREQ : frequency);

        gpioSetPWMfrequency(BUZZER_PIN, (int)frequency);
        gpioSetPWMrange(BUZZER_PIN, 1000);
        gpioSetPWMdutycycle(BUZZER_PIN, 500);

        gpioDelay(LOOP_INTERVAL);
    }

    gpioSetPWMdutycycle(BUZZER_PIN, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}
