    while (!stop) {
        for (double proximity = 0.0; proximity <= 1.0; proximity += 0.01) {
            double red = proximity * 255.0;
            double green = (1.0 - proximity) * 255.0;
            double blue = 0.0;

            gpioSetPWMrange(RED_PIN, 256);
            gpioSetPWMrange(GREEN_PIN, 256);
