#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define BUTTON_PIN 17
#define BUZZER_PIN 18
#define DEBOUNCE_TIME 50
#define PWM_FREQ 1000
#define PWM_RANGE 255

volatile int button_pressed = 0;
volatile int melody_playing = 0;
const unsigned char melody[] = {60, 62, 64, 65, 67, 69, 71, 72}; // C4 to C5 scale
const int melody_length = sizeof(melody) / sizeof(melody[0]);

void button_callback(int gpio, int level, uint32_t tick) {
    if (level == PI_LOW) {
        button_pressed = 1;
    }
}

void stop_melody() {
    gpioHardwarePWM(BUZZER_PIN, 0, 0);
    melody_playing = 0;
}

void signal_handler(int sig) {
    stop_melody();
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP);

    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    gpioSetISRFuncEx(BUTTON_PIN, RISING_EDGE, DEBOUNCE_TIME, button_callback, NULL);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        if (button_pressed) {
            button_pressed = 0;
            if (!melody_playing) {
                melody_playing = 1;
                for (int i = 0; i < melody_length; i++) {
                    gpioHardwarePWM(BUZZER_PIN, PWM_FREQ, (PWM_RANGE / 2));
                    gpioDelay(1000000 / melody[i]);
                    gpioHardwarePWM(BUZZER_PIN, 0, 0);
                    gpioDelay(1000000 / melody[i]);
                }
                melody_playing = 0;
            } else {
                stop_melody();
            }
        }
    }

    gpioTerminate();
    return 0;
}

