#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define WINDOW_SIZE 5
#define DEFAULT_TIMEOUT 1000

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

int main(int argc, char *argv[]) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_request_config config;
    struct gpiod_line_event event;
    struct timespec timeout;
    FILE *log_file = NULL;
    int event_count[WINDOW_SIZE] = {0};
    int window_index = 0;
    int timeout_ms = (argc > 1) ? atoi(argv[1]) : DEFAULT_TIMEOUT;

    if (timeout_ms <= 0) {
        fprintf(stderr, "Invalid timeout value: %d\n", timeout_ms);
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    memset(&config, 0, sizeof(config));
    config.consumer = "vibration_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(line, &config)) {
        perror("Failed to request GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_file = fopen("vibration_events.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!stop_flag) {
        timeout.tv_sec = timeout_ms / 1000;
        timeout.tv_nsec = (timeout_ms % 1000) * 1000000;

        if (gpiod_line_event_wait(line, &timeout)) {
            if (errno == EINTR) {
                continue;
            } else {
                perror("Failed to wait for GPIO line event");
                break;
            }
        }

        if (gpiod_line_event_read(line, &event)) {
            perror("Failed to read GPIO line event");
            break;
        }

        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            event_count[window_index] = 1;
        } else if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            event_count[window_index] = 0;
        }

        window_index = (window_index + 1) % WINDOW_SIZE;

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", tm_info);

        fprintf(log_file, "%s %d\n", timestamp, event_count[window_index]);
        fflush(log_file);

        if (window_index == 0) {
            int high_count = 0;
            for (int i = 0; i < WINDOW_SIZE; i++) {
                high_count += event_count[i];
            }
            if (high_count >= 3) {
                printf("EARTHQUAKE ALERT at %s\n", timestamp);
            }
        }
    }

    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

