        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", tm_info);

        fprintf(log_file, "%s %d\n", timestamp, event_count[window_index]);
        fflush(log_file);

        if (window_index == 0) {
            int high_count = 0;
            for (int i = 0; i < WINDOW_SIZE; i++) {
                high_count += event_count[i];
            }
            if (high_count >= 3) {
                printf("EARTHQUAKE ALERT at %s\n", timestamp);
            }
        }
    }

    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}
