        fprintf(csv_fd, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading,Direction\n");
    }

    fprintf(csv_fd, "%s,%.2f,%.2f,%.2f,%.2f,%s\n", timestamp, X_cal, Y_cal, Z_cal, heading, direction);
    fflush(csv_fd);
}

