#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <signal.h>

#define RELAY_PIN 17
#define TOUCH_PIN 4
#define DEBOUNCE_TIME 200

volatile int lastTouchTime = 0;
FILE *logFile = NULL;

void logRelayState(int relayState) {
    time_t now = time(NULL);
    char *isoTime = ctime(&now);
    isoTime[strlen(isoTime) - 1] = '\0'; // Remove newline

    fprintf(logFile, "{\"timestamp\":\"%s\",\"relay_state\":\"%s\"}\n", isoTime, relayState == 1 ? "ON" : "OFF");
    fflush(logFile);
}

void gpioISR(int gpio, int level, uint32_t tick) {
    if (level == PI_TIMEOUT) return;

    int currentTime = (int)tick;
    if (currentTime - lastTouchTime < DEBOUNCE_TIME) return;

    lastTouchTime = currentTime;

    int relayState = gpioRead(RELAY_PIN);
    gpioWrite(RELAY_PIN, !relayState);
    logRelayState(!relayState);
}

void cleanup(int signum) {
    gpioWrite(RELAY_PIN, 0);
    logRelayState(0);
    fclose(logFile);
    gpioTerminate();
    exit(signum);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set relay pin mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(TOUCH_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set touch pin mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(TOUCH_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set pull-down resistor on touch pin\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetISRFunc(TOUCH_PIN, RISING, DEBOUNCE_TIME, gpioISR) < 0) {
        fprintf(stderr, "Failed to set ISR for touch pin\n");
        gpioTerminate();
        return 1;
    }

    logFile = fopen("relay_log.json", "a");
    if (!logFile) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, cleanup);

    while (1) {
        gpioDelay(100000); // Sleep for 100ms
    }

    return 0;
}

