#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINES "17,23,24,25"
#define LOG_FILE "irrigation_log.txt"
#define CHECK(expr) if (!(expr)) { perror(#expr); exit(EXIT_FAILURE); }

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[4] = {NULL};
static FILE *log_file = NULL;

void handle_signal(int sig) {
    for (int i = 0; i < 4; i++) {
        CHECK(gpiod_line_set_value(lines[i], 1));
    }
    for (int i = 0; i < 4; i++) {
        CHECK(gpiod_line_release(lines[i]));
    }
    CHECK(gpiod_chip_close(chip));
    if (log_file) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    srand(time(NULL));
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    CHECK(chip = gpiod_chip_open_by_name(GPIO_CHIP));
    CHECK(log_file = fopen(LOG_FILE, "a"));

    for (int i = 0; i < 4; i++) {
        char line_name[10];
        snprintf(line_name, sizeof(line_name), "line%d", i);
        CHECK(lines[i] = gpiod_chip_get_line(chip, i));
        CHECK(gpiod_line_request_output(lines[i], "irrigation", 1));
    }

    while (1) {
        int moisture = rand() % 101;
        for (int i = 0; i < 4; i++) {
            if (moisture < 30) {
                CHECK(gpiod_line_set_value(lines[i], 0));
                time_t now = time(NULL);
                char timestamp[20];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
                fprintf(log_file, "%s, Relay %d, Moisture %d\n", timestamp, i + 1, moisture);
                fflush(log_file);
                sleep(5);
                CHECK(gpiod_line_set_value(lines[i], 1));
                sleep(1);
            }
        }
        sleep(10);
    }

    return 0;
}

