#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_VALVE 17
#define GPIO_NOZZLE 18
#define PULSE_WIDTH_MIN 500
#define PULSE_WIDTH_MAX 2500
#define PULSE_WIDTH_OPEN 1500
#define PULSE_WIDTH_CLOSE 500
#define PULSE_WIDTH_NOZZLE_STEPS 5
#define PULSE_WIDTH_NOZZLE_DELAY 2000000
#define PULSE_WIDTH_HOLD 5000000
#define SOIL_MOISTURE_VALUES 5
#define SOIL_MOISTURE_MIN 50
#define RETRY_COUNT 3
#define RETRY_DELAY 100000

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio library\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_VALVE, PI_OUTPUT);
    gpioSetMode(GPIO_NOZZLE, PI_OUTPUT);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int soil_moisture_values[] = {20, 40, 60, 80, 100};
    int current_value_index = 0;

    while (!stop_flag) {
        int moisture_reading = soil_moisture_values[current_value_index];
        printf("Soil moisture: %d\n", moisture_reading);

        if (moisture_reading < SOIL_MOISTURE_MIN) {
            int retry_count = 0;
            while (retry_count < RETRY_COUNT) {
                int result = gpioServo(GPIO_VALVE, PULSE_WIDTH_OPEN);
                if (result == PI_OK) {
                    break;
                }
                retry_count++;
                usleep(RETRY_DELAY);
            }

            if (result != PI_OK) {
                fprintf(stderr, "Failed to open valve servo\n");
                gpioTerminate();
                return EXIT_FAILURE;
            }

            for (int i = 0; i < PULSE_WIDTH_NOZZLE_STEPS; i++) {
                int result = gpioServo(GPIO_NOZZLE, PULSE_WIDTH_NOZZLE_STEPS * i * (PULSE_WIDTH_MAX - PULSE_WIDTH_MIN) / (PULSE_WIDTH_NOZZLE_STEPS - 1) + PULSE_WIDTH_MIN);
                if (result != PI_OK) {
                    fprintf(stderr, "Failed to set nozzle servo to angle %d\n", i * 45);
                }
                usleep(PULSE_WIDTH_NOZZLE_DELAY);
            }

            gpioServo(GPIO_NOZZLE, PULSE_WIDTH_CLOSE);
            usleep(PULSE_WIDTH_HOLD);

            retry_count = 0;
            while (retry_count < RETRY_COUNT) {
                int result = gpioServo(GPIO_VALVE, PULSE_WIDTH_CLOSE);
                if (result == PI_OK) {
                    break;
                }
                retry_count++;
                usleep(RETRY_DELAY);
            }

            if (result != PI_OK) {
                fprintf(stderr, "Failed to close valve servo\n");
            }
        }

        current_value_index = (current_value_index + 1) % SOIL_MOISTURE_VALUES;
        sleep(5);
    }

    gpioServo(GPIO_VALVE, 0);
    gpioServo(GPIO_NOZZLE, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

