            if (result != PI_OK) {
                fprintf(stderr, "Failed to open valve servo\n");
                gpioTerminate();
                return EXIT_FAILURE;
            }

            for (int i = 0; i < PULSE_WIDTH_NOZZLE_STEPS; i++) {
                int result = gpioServo(GPIO_NOZZLE, PULSE_WIDTH_NOZZLE_STEPS * i * (PULSE_WIDTH_MAX - PULSE_WIDTH_MIN) / (PULSE_WIDTH_NOZZLE_STEPS - 1) + PULSE_WIDTH_MIN);
                if (result != PI_OK) {
                    fprintf(stderr, "Failed to set nozzle servo to angle %d\n", i * 45);
                }
                usleep(PULSE_WIDTH_NOZZLE_DELAY);
            }

            gpioServo(GPIO_NOZZLE, PULSE_WIDTH_CLOSE);
            usleep(PULSE_WIDTH_HOLD);

            retry_count = 0;
            while (retry_count < RETRY_COUNT) {
                int result = gpioServo(GPIO_VALVE, PULSE_WIDTH_CLOSE);
                if (result == PI_OK) {
                    break;
                }
                retry_count++;
                usleep(RETRY_DELAY);
            }

            if (result != PI_OK) {
                fprintf(stderr, "Failed to close valve servo\n");
            }
        }

        current_value_index = (current_value_index + 1) % SOIL_MOISTURE_VALUES;
        sleep(5);
    }

    gpioServo(GPIO_VALVE, 0);
    gpioServo(GPIO_NOZZLE, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}
