#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define GYRO_SENSITIVITY 131.0

int i2c_fd;
FILE *log_file;

void close_resources() {
    if (log_file) fclose(log_file);
    if (i2c_fd >= 0) close(i2c_fd);
}

void signal_handler(int signum) {
    close_resources();
    exit(signum);
}

int main() {
    struct timespec ts;
    uint8_t buffer[7];
    int16_t gyro_x, gyro_y, gyro_z;
    double gyro_x_deg, gyro_y_deg, gyro_z_deg;

    // Open I2C bus
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Wake the sensor
    uint8_t wake_cmd = 0x00;
    if (write(i2c_fd, &wake_cmd, 1) != 1) {
        perror("Failed to wake MPU-6050");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    if ((log_file = fopen("gyro_log.txt", "w")) == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        // Read gyroscope data
        if (read(i2c_fd, buffer, 7) != 7) {
            perror("Failed to read gyroscope data");
            close_resources();
            return EXIT_FAILURE;
        }

        // Convert raw data to degrees/second
        gyro_x = (buffer[1] << 8) | buffer[0];
        gyro_y = (buffer[3] << 8) | buffer[2];
        gyro_z = (buffer[5] << 8) | buffer[4];
        gyro_x_deg = gyro_x / GYRO_SENSITIVITY;
        gyro_y_deg = gyro_y / GYRO_SENSITIVITY;
        gyro_z_deg = gyro_z / GYRO_SENSITIVITY;

        // Get current timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("Failed to get timestamp");
            close_resources();
            return EXIT_FAILURE;
        }

        // Log data
        fprintf(log_file, "%ld.%09ld,%f,%f,%f\n", ts.tv_sec, ts.tv_nsec, gyro_x_deg, gyro_y_deg, gyro_z_deg);
        fflush(log_file);

        // Sleep for 100ms (10 Hz)
        usleep(100000);
    }

    close_resources();
    return EXIT_SUCCESS;
}

