#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define STEPPER_PINS {4, 17, 27, 22}
#define LOCK_BUTTON 24
#define UNLOCK_BUTTON 23
#define STEPS_PER_REV 512
#define STEP_DELAY 3000

volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

void step_motor(int *pins, int steps, int direction) {
    for (int i = 0; i < steps; i++) {
        for (int j = 0; j < 4; j++) {
            gpioWrite(pins[j], (direction == 1) ? (1 << j) : (1 << (3 - j)));
            gpioDelay(STEP_DELAY);
        }
    }
    for (int j = 0; j < 4; j++) {
        gpioWrite(pins[j], 0);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio library\n");
        return EXIT_FAILURE;
    }

    int pins[4] = STEPPER_PINS;
    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set mode for pin %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPullUpDown(pins[i], PI_PUD_UP) < 0) {
            fprintf(stderr, "Failed to set pull-up for pin %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    if (gpioSetMode(LOCK_BUTTON, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set mode for LOCK button\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up for LOCK button\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(UNLOCK_BUTTON, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set mode for UNLOCK button\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up for UNLOCK button\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    while (running) {
        if (gpioRead(LOCK_BUTTON) == 0) {
            printf("Locking...\n");
            step_motor(pins, STEPS_PER_REV, 1);
            while (gpioRead(LOCK_BUTTON) == 0) {
                gpioDelay(100);
            }
        }
        if (gpioRead(UNLOCK_BUTTON) == 0) {
            printf("Unlocking...\n");
            step_motor(pins, STEPS_PER_REV, -1);
            while (gpioRead(UNLOCK_BUTTON) == 0) {
                gpioDelay(100);
            }
        }
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

