#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define TRIGGER_LINE "gpiochip0:line17"
#define ECHO_LINE "gpiochip0:line18"
#define LOG_FILE "distance_log.txt"
#define MIN_GUARD_TIME 60000
#define TIMEOUT_US 50000
#define PULSE_WIDTH_US 10

static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static FILE *log_file;

void handle_sigint(int sig) {
    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);
    fclose(log_file);
    exit(0);
}

int main() {
    struct timespec start, end;
    long long duration_us;
    int distance_cm;

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    // Register signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Request trigger line
    trigger_line = gpiod_chip_get_line(chip, 17);
    if (!trigger_line) {
        perror("Failed to get trigger line");
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Request echo line
    echo_line = gpiod_chip_get_line(chip, 18);
    if (!echo_line) {
        perror("Failed to get echo line");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Set trigger line as output
    if (gpiod_line_request_output(trigger_line, "trigger", 0) < 0) {
        perror("Failed to request trigger line as output");
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Set echo line as input
    if (gpiod_line_request_input(echo_line, "echo") < 0) {
        perror("Failed to request echo line as input");
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    while (1) {
        // Generate 10 microsecond high pulse on trigger line
        if (gpiod_line_set_value(trigger_line, 1) < 0) {
            perror("Failed to set trigger line high");
            fprintf(log_file, "-1\n");
            fflush(log_file);
        } else {
            usleep(PULSE_WIDTH_US);
            if (gpiod_line_set_value(trigger_line, 0) < 0) {
                perror("Failed to set trigger line low");
                fprintf(log_file, "-1\n");
                fflush(log_file);
            }
        }

        // Measure echo pulse width
        if (clock_gettime(CLOCK_MONOTONIC, &start) < 0) {
            perror("Failed to get start time");
            fprintf(log_file, "-1\n");
            fflush(log_file);
        } else {
            while (1) {
                if (gpiod_line_get_value(echo_line) == 1) {
                    if (clock_gettime(CLOCK_MONOTONIC, &end) < 0) {
                        perror("Failed to get end time");
                        fprintf(log_file, "-1\n");
                        fflush(log_file);
                        break;
                    }
                    duration_us = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
                    if (duration_us > TIMEOUT_US) {
                        fprintf(log_file, "-1\n");
                        fflush(log_file);
                        break;
                    }
                } else {
                    break;
                }
            }
        }

        // Convert pulse width to distance
        if (duration_us > 0) {
            distance_cm = (int)(duration_us * 0.01715);
        } else {
            distance_cm = -1;
        }

        // Log distance to file
        fprintf(log_file, "%d\n", distance_cm);
        fflush(log_file);

        // Wait for minimum guard time
        usleep(MIN_GUARD_TIME);
    }

    // Clean up
    gpiod_line_release(echo_line);
    gpiod_line_release(trigger_line);
    gpiod_chip_close(chip);
    fclose(log_file);

    return EXIT_SUCCESS;
}

