#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define RELAY_PIN 18
#define DISTANCE_THRESHOLD 50

volatile int running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set relay pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, PI_LOW) < 0) {
        fprintf(stderr, "Failed to set relay pin to LOW\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get relay line\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "relay", 0) < 0) {
        fprintf(stderr, "Failed to request relay line as output\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2cOpen(I2C_BUS, I2C_ADDR, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2cWriteByteData(I2C_BUS, 0x0000, 0x00) < 0) {
        fprintf(stderr, "Failed to perform software reset\n");
        i2cClose(I2C_BUS);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2cWriteByteData(I2C_BUS, 0x0080, 0x01) < 0) {
        fprintf(stderr, "Failed to set ranging mode\n");
        i2cClose(I2C_BUS);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    while (running) {
        uint8_t status;
        if (i2cReadByteData(I2C_BUS, 0x0044, &status) < 0) {
            fprintf(stderr, "Failed to read interrupt status\n");
            continue;
        }

        if (status & 0x01) {
            uint16_t distance;
            if (i2cReadByteData(I2C_BUS, 0x0096, (uint8_t *)&distance) < 0) {
                fprintf(stderr, "Failed to read distance MSB\n");
                continue;
            }
            if (i2cReadByteData(I2C_BUS, 0x0097, (uint8_t *)&distance) < 0) {
                fprintf(stderr, "Failed to read distance LSB\n");
                continue;
            }

            printf("Distance: %d cm\n", distance);

            if (distance <= DISTANCE_THRESHOLD) {
                if (gpiod_line_set_value(line, 1) < 0) {
                    fprintf(stderr, "Failed to set relay to HIGH\n");
                }
            } else {
                if (gpiod_line_set_value(line, 0) < 0) {
                    fprintf(stderr, "Failed to set relay to LOW\n");
                }
            }
        }

        gpioDelay(100000); // 100 ms
    }

    i2cClose(I2C_BUS);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    gpioTerminate();

    return EXIT_SUCCESS;
}

