#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDRESS 0x68
#define PWR_MGMT_1 0x6B
#define GYRO_CONFIG 0x1B
#define GYRO_XOUT_H 0x43
#define GYRO_SENSITIVITY 131.0

int fd;
volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int i2c_write_byte(int file, uint8_t address, uint8_t reg, uint8_t value) {
    uint8_t buffer[2] = {reg, value};
    if (write(file, buffer, 2) != 2) {
        perror("i2c_write_byte");
        return -1;
    }
    return 0;
}

int i2c_read_bytes(int file, uint8_t address, uint8_t reg, uint8_t *buffer, size_t length) {
    if (write(file, &reg, 1) != 1) {
        perror("i2c_read_bytes write");
        return -1;
    }
    if (read(file, buffer, length) != length) {
        perror("i2c_read_bytes read");
        return -1;
    }
    return 0;
}

int main() {
    if ((fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return EXIT_FAILURE;
    }

    if (i2c_write_byte(fd, MPU6050_ADDRESS, PWR_MGMT_1, 0) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    if (i2c_write_byte(fd, MPU6050_ADDRESS, GYRO_CONFIG, 0) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        uint8_t buffer[6];
        if (i2c_read_bytes(fd, MPU6050_ADDRESS, GYRO_XOUT_H, buffer, 6) < 0) {
            continue;
        }

        int16_t x = (buffer[0] << 8) | buffer[1];
        int16_t y = (buffer[2] << 8) | buffer[3];
        int16_t z = (buffer[4] << 8) | buffer[5];

        printf("X: %.2f, Y: %.2f, Z: %.2f\n", (float)x / GYRO_SENSITIVITY, (float)y / GYRO_SENSITIVITY, (float)z / GYRO_SENSITIVITY);
        usleep(100000); // 100ms delay
    }

    close(fd);
    return EXIT_SUCCESS;
}

