#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINES "17,18,27,22"
#define WATERING_INTERVAL 60
#define WATERING_DURATION 5
#define LOG_FILE "watering_log.txt"

static struct gpiod_chip *chip;
static struct gpiod_line *lines[4];
static int running = 1;

void log_watering_start() {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char buffer[80];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", tm_info);
    FILE *log = fopen(LOG_FILE, "a");
    if (log) {
        fprintf(log, "Watering started at %s\n", buffer);
        fclose(log);
    }
}

void signal_handler(int signum) {
    running = 0;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 4; i++) {
        lines[i] = gpiod_chip_get_line(chip, i);
        if (!lines[i]) {
            perror("Failed to get GPIO line");
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
        if (gpiod_line_request_output(lines[i], "watering", GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW, 1)) {
            perror("Failed to request GPIO line as output");
            for (int j = 0; j <= i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    while (running) {
        for (int i = 0; i < 4; i++) {
            log_watering_start();
            if (gpiod_line_set_value(lines[i], 0)) {
                perror("Failed to activate relay");
            }
            sleep(WATERING_DURATION);
            if (gpiod_line_set_value(lines[i], 1)) {
                perror("Failed to deactivate relay");
            }
            sleep(WATERING_INTERVAL - WATERING_DURATION);
        }
    }

    for (int i = 0; i < 4; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

