This program will control four relay modules connected to GPIO17, GPIO18, GPIO27, and GPIO22, simulating an automated plant watering system. It will log each watering cycle's start time to `watering_log.txt` and can be stopped gracefully with a SIGINT or SIGTERM signal.

code:
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PINS {17, 18, 27, 22}
#define PWM_FREQ 1000
#define PWM_RANGE 256
#define DURATION 1800 // 30 minutes in seconds
#define STEP_DURATION 1 // 1 second step

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio library\n");
        return EXIT_FAILURE;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    FILE *log_file = fopen("smart_lighting.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 4; i++) {
        int gpio = GPIO_PINS[i];
        if (gpioSetMode(gpio, PI_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO%d mode to output\n", gpio);
            goto cleanup;
        }
        if (gpioSetPWMfrequency(gpio, PWM_FREQ) < 0) {
            fprintf(stderr, "Failed to set GPIO%d PWM frequency to %d Hz\n", gpio, PWM_FREQ);
            goto cleanup;
        }
        if (gpioSetPWMrange(gpio, PWM_RANGE) < 0) {
            fprintf(stderr, "Failed to set GPIO%d PWM range to %d\n", gpio, PWM_RANGE);
            goto cleanup;
        }
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    for (int duty = 0; duty <= PWM_RANGE; duty++) {
        if (!running) {
            break;
        }
        for (int i = 0; i < 4; i++) {
            gpioSetPWMduty(GPIO_PINS[i], duty);
        }
        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld.%09ld: Duty cycle set to %d\n", ts.tv_sec, ts.tv_nsec, duty);
        fflush(log_file);
        sleep(STEP_DURATION);
    }

cleanup:
    for (int i = 0; i < 4; i++) {
        gpioSetPWMduty(GPIO_PINS[i], 0);
        gpioSetMode(GPIO_PINS[i], PI_INPUT);
    }
    gpioTerminate();
    fclose(log_file);
    return EXIT_SUCCESS;
}

