#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x68
#define LED_PIN 17
#define GYRO_XOUT_H 0x43
#define WHO_AM_I 0x75
#define PWR_MGMT_1 0x6B
#define SMPLRT_DIV 0x19
#define GYRO_CONFIG 0x1B
#define BUFFER_SIZE 100

typedef struct {
    time_t timestamp;
    int16_t x, y, z;
} GyroReading;

GyroReading buffer[BUFFER_SIZE];
int buffer_head = 0, buffer_tail = 0, buffer_count = 0;

void cleanup(int signum) {
    gpioTerminate();
    exit(signum);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(LED_PIN, PI_PUD_OFF) < 0) {
        fprintf(stderr, "Failed to set GPIO%d pull-up/down\n", LED_PIN);
        gpioTerminate();
        return 1;
    }

    int i2c_handle = -1;
    for (int i = 0; i < 3; i++) {
        i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
        if (i2c_handle >= 0) {
            break;
        }
        sleep(1);
    }

    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return 1;
    }

    uint8_t data[1] = {0};
    if (i2cWriteByteData(i2c_handle, WHO_AM_I, 0x68) < 0) {
        fprintf(stderr, "Failed to write to WHO_AM_I register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to write to PWR_MGMT_1 register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByteData(i2c_handle, SMPLRT_DIV, 0x07) < 0) {
        fprintf(stderr, "Failed to write to SMPLRT_DIV register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to write to GYRO_CONFIG register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        uint8_t buffer[6];
        if (i2cReadDevice(i2c_handle, GYRO_XOUT_H, buffer, 6) < 0) {
            fprintf(stderr, "Failed to read gyroscope data\n");
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }

        int16_t x = (buffer[0] << 8) | buffer[1];
        int16_t y = (buffer[2] << 8) | buffer[3];
        int16_t z = (buffer[4] << 8) | buffer[5];

        time_t timestamp = time(NULL);
        buffer[buffer_head] = (GyroReading){timestamp, x, y, z};
        buffer_head = (buffer_head + 1) % BUFFER_SIZE;
        if (buffer_count < BUFFER_SIZE) {
            buffer_count++;
        }

        int led_state = 0;
        for (int i = 0; i < buffer_count; i++) {
            int index = (buffer_head - i + BUFFER_SIZE) % BUFFER_SIZE;
            if (abs(buffer[index].x) > 250 || abs(buffer[index].y) > 250 || abs(buffer[index].z) > 250) {
                led_state = 1;
                break;
            }
        }

        gpioWrite(LED_PIN, led_state);

        sleep(50);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

