#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 8
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define GYRO_REG_START 0x43
#define GYRO_REG_COUNT 6
#define GYRO_SCALE 131.0
#define LOG_FILE "gyro_log.txt"
#define RETRY_COUNT 3

static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;

void cleanup() {
    if (gpio_line) {
        gpiod_line_release(gpio_line);
        gpio_line = NULL;
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
        gpio_chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

void signal_handler(int signum) {
    cleanup();
    exit(signum);
}

int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
    };
    for (int i = 0; i < RETRY_COUNT; i++) {
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) == len) {
            return 0;
        }
        perror("SPI transfer failed");
    }
    return -1;
}

int read_gyro_data(int16_t *data) {
    uint8_t tx[GYRO_REG_COUNT] = {GYRO_REG_START};
    uint8_t rx[GYRO_REG_COUNT];
    if (spi_transfer(tx, rx, GYRO_REG_COUNT) != 0) {
        return -1;
    }
    for (int i = 0; i < 3; i++) {
        data[i] = (rx[i * 2] << 8) | rx[i * 2 + 1];
    }
    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    gpio_chip = gpiod_chip_open_by_path(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_LINE);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(gpio_line, "gyro_cs", 0) < 0) {
        perror("Failed to request GPIO line for output");
        gpiod_chip_close(gpio_chip);
        return EXIT_FAILURE;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(spi_fd);
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        return EXIT_FAILURE;
    }

    while (1) {
        int16_t gyro_data[3];
        if (read_gyro_data(gyro_data) == 0) {
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            fprintf(log_file, "%ld.%09ld,%d,%d,%d\n", ts.tv_sec, ts.tv_nsec, 
                    gyro_data[0] / GYRO_SCALE, gyro_data[1] / GYRO_SCALE, 
                    gyro_data[2] / GYRO_SCALE);
            fflush(log_file);
        }
        usleep(10000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

