#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip0"
#define GPIO_CS 8
#define GPIO_LED 17
#define BUFFER_SIZE 64
#define SPI_SPEED 3900000
#define SPI_MODE 0
#define GYRO_SENSITIVITY 131.0
#define MAX_ANGULAR_VELOCITY 200.0

struct circular_buffer {
    int buffer[BUFFER_SIZE][4];
    int head;
    int count;
};

struct circular_buffer cb;

void init_spi() {
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, (unsigned char *)8) < 0) {
        perror("Failed to set bits per word");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set max speed HZ");
        close(fd);
        exit(EXIT_FAILURE);
    }

    cb.head = 0;
    cb.count = 0;

    printf("SPI initialized successfully\n");
}

void init_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line *cs_line, *led_line;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    cs_line = gpiod_chip_get_line(chip, GPIO_CS);
    if (!cs_line) {
        perror("Failed to get CS line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    led_line = gpiod_chip_get_line(chip, GPIO_LED);
    if (!led_line) {
        perror("Failed to get LED line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(cs_line, "mpu6050_cs", 0) < 0) {
        perror("Failed to request CS line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        perror("Failed to request LED line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    printf("GPIO initialized successfully\n");
}

void read_gyroscope(int *x, int *y, int *z) {
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    uint8_t tx[] = {0x43, 0x00, 0x00, 0x00, 0x00, 0x00};
    uint8_t rx[6];

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(rx),
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Failed to transfer data");
        close(fd);
        exit(EXIT_FAILURE);
    }

    *x = (rx[1] << 8) | rx[0];
    *y = (rx[3] << 8) | rx[2];
    *z = (rx[5] << 8) | rx[4];

    close(fd);
}

void add_to_buffer(int x, int y, int z) {
    if (cb.count < BUFFER_SIZE) {
        cb.count++;
    } else {
        cb.head = (cb.head + 1) % BUFFER_SIZE;
    }

    cb.buffer[cb.head][0] = time(NULL);
    cb.buffer[cb.head][1] = x;
    cb.buffer[cb.head][2] = y;
    cb.buffer[cb.head][3] = z;
}

void blink_led() {
    struct gpiod_chip *chip;
    struct gpiod_line *led_line;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    led_line = gpiod_chip_get_line(chip, GPIO_LED);
    if (!led_line) {
        perror("Failed to get LED line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_value(led_line, 1);
    usleep(500000);
    gpiod_line_set_value(led_line, 0);
    usleep(500000);

    gpiod_chip_close(chip);
}

void print_buffer() {
    for (int i = 0; i < cb.count; i++) {
        int index = (cb.head - i + BUFFER_SIZE) % BUFFER_SIZE;
        printf("%ld,%d,%d,%d\n", cb.buffer[index][0], cb.buffer[index][1], cb.buffer[index][2], cb.buffer[index][3]);
    }
}

void cleanup() {
    struct gpiod_chip *chip;
    struct gpiod_line *cs_line, *led_line;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    cs_line = gpiod_chip_get_line(chip, GPIO_CS);
    if (!cs_line) {
        perror("Failed to get CS line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
