        exit(EXIT_FAILURE);
    }

    gpiod_line_release(cs_line);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);

    printf("Resources released successfully\n");
}

void signal_handler(int sig) {
    print_buffer();
    cleanup();
    exit(EXIT_SUCCESS);
}

