#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x68
#define LED_PIN 21
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_ACCEL_CONFIG 0x1C
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_ACCEL_YOUT_H 0x3D
#define MPU6050_ACCEL_ZOUT_H 0x3F
#define PI 3.14159265358979323846

void log_tilt(double roll, double pitch) {
    FILE *log_file = fopen("tilt_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, roll, pitch);
    fclose(log_file);
}

void handle_sigint(int sig) {
    gpioWrite(LED_PIN, PI_OFF);
    i2cClose(I2C_BUS);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        gpioTerminate();
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByteData(i2c_handle, MPU6050_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to wake MPU-6050\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByteData(i2c_handle, MPU6050_ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to set accelerometer range\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        uint8_t data[6];
        if (i2cReadBytesData(i2c_handle, MPU6050_ACCEL_XOUT_H, data, 6) < 0) {
            fprintf(stderr, "Failed to read accelerometer data\n");
            continue;
        }

        int16_t x = (data[0] << 8) | data[1];
        int16_t y = (data[2] << 8) | data[3];
        int16_t z = (data[4] << 8) | data[5];

        double roll = atan2(y, z) * 180 / PI;
        double pitch = atan2(-x, sqrt(y * y + z * z)) * 180 / PI;

        printf("Roll: %.2f, Pitch: %.2f\n", roll, pitch);
        log_tilt(roll, pitch);

        if (fabs(roll) > 45 || fabs(pitch) > 45) {
            gpioWrite(LED_PIN, PI_ON);
        } else {
            gpioWrite(LED_PIN, PI_OFF);
        }

        gpioDelay(100000); // 100 ms
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

