#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x5A
#define I2C_REG_AMBIENT 0x20
#define I2C_REG_PROXIMITY 0x22
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define LED_ON 1
#define LED_OFF 0
#define RETRY_COUNT 3
#define RETRY_DELAY 10000
#define LOG_FILE "biometric_log.txt"

static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;

void log_reading(time_t timestamp, uint16_t ambient, uint16_t proximity) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }
    fprintf(log_file, "%s,AmbientLight:%04X,Proximity:%04X\n", ctime(&timestamp), ambient, proximity);
    fclose(log_file);
}

int i2c_read(uint8_t reg, uint16_t *value) {
    uint8_t buf[3];
    int retries = RETRY_COUNT;
    while (retries--) {
        if (write(i2c_fd, &reg, 1) != 1) {
            perror("I2C write failed");
            usleep(RETRY_DELAY);
            continue;
        }
        if (read(i2c_fd, buf, 2) != 2) {
            perror("I2C read failed");
            usleep(RETRY_DELAY);
            continue;
        }
        *value = (buf[1] << 8) | buf[0];
        return 0;
    }
    return -1;
}

void signal_handler(int signum) {
    if (gpio_line) {
        gpiod_line_set_value(gpio_line, LED_OFF);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(signum);
}

int main() {
    struct timespec ts;
    time_t timestamp;
    uint16_t ambient, proximity;

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Get GPIO line
    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_LINE);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Request GPIO line as output
    if (gpiod_line_request_output(gpio_line, "proximity_led", LED_OFF) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
            timestamp = ts.tv_sec;
        } else {
            perror("Failed to get current time");
            break;
        }

        if (i2c_read(I2C_REG_AMBIENT, &ambient) < 0) {
            perror("Failed to read ambient light value");
            break;
        }

        if (i2c_read(I2C_REG_PROXIMITY, &proximity) < 0) {
            perror("Failed to read proximity value");
            break;
        }

        log_reading(timestamp, ambient, proximity);

        if (proximity > 100) {
            gpiod_line_set_value(gpio_line, LED_ON);
        } else {
            gpiod_line_set_value(gpio_line, LED_OFF);
        }

        usleep(100000);
    }

    // Cleanup
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

