        perror("Failed to request GPIO line as output");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
            timestamp = ts.tv_sec;
        } else {
            perror("Failed to get current time");
            break;
        }

        if (i2c_read(I2C_REG_AMBIENT, &ambient) < 0) {
            perror("Failed to read ambient light value");
            break;
        }

        if (i2c_read(I2C_REG_PROXIMITY, &proximity) < 0) {
            perror("Failed to read proximity value");
            break;
        }

        log_reading(timestamp, ambient, proximity);

        if (proximity > 100) {
            gpiod_line_set_value(gpio_line, LED_ON);
        } else {
            gpiod_line_set_value(gpio_line, LED_OFF);
        }

        usleep(100000);
    }

    // Cleanup
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);
    close(i2c_fd);

    return EXIT_SUCCESS;
}
