#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_CE 8
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define X_RATE_REG 0x02
#define Y_RATE_REG 0x04
#define MAX_RETRIES 3

volatile int running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int read_register(int spi_handle, uint8_t reg_addr) {
    uint8_t tx[2] = {reg_addr | 0x80, 0x00};
    uint8_t rx[2];
    int status = spiXfer(spi_handle, tx, rx, 2);
    if (status < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", pigpio_error(status));
        return -1;
    }
    return (rx[0] << 8) | rx[1];
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel: %s\n", pigpio_error(spi_handle));
        gpioTerminate();
        return 1;
    }

    FILE *file = fopen("gyro_data.csv", "w");
    if (!file) {
        fprintf(stderr, "Failed to open gyro_data.csv for writing\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);

    uint64_t last_time = gpioTick();
    int retries = 0;

    while (running) {
        uint64_t now = gpioTick();
        if (now - last_time < 10000) {
            continue;
        }
        last_time = now;

        int x_rate = read_register(spi_handle, X_RATE_REG);
        int y_rate = read_register(spi_handle, Y_RATE_REG);

        if (x_rate == -1 || y_rate == -1) {
            retries++;
            if (retries >= MAX_RETRIES) {
                fprintf(stderr, "Too many read failures, exiting\n");
                break;
            }
            gpioDelay(100000); // Wait 100 ms before retrying
            continue;
        }

        retries = 0;

        time_t now_time;
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        now_time = ts.tv_sec;

        fprintf(file, "%ld.%06ld,%d,%d\n", now_time, ts.tv_nsec / 1000, x_rate, y_rate);
        fflush(file);
    }

    fclose(file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

