#define SENSOR1 23
#define SENSOR2 24
#define ALERT_PIN 17
#define MIN_DURATION 500
#define LOG_FILE "seismic_events.txt"

volatile int sensor1_state = 0;
volatile int sensor2_state = 0;
volatile int alert_active = 0;
FILE *log_file = NULL;

void log_event(const char *message) {
    if (log_file) {
        time_t now = time(NULL);
        char *iso_time = ctime(&now);
        iso_time[strlen(iso_time) - 1] = '\0'; // Remove newline
        fprintf(log_file, "%s - %s\n", iso_time, message);
        fflush(log_file);
    }
}

void alert_handler(int gpio, int level, uint32_t tick) {
    if (gpio == SENSOR1) {
        sensor1_state = level;
    } else if (gpio == SENSOR2) {
        sensor2_state = level;
    }

    if (sensor1_state == PIGPIO_FUNC_INPUT && sensor2_state == PIGPIO_FUNC_INPUT) {
        if (alert_active) {
            alert_active = 0;
            gpioWrite(ALERT_PIN, 0);
            log_event("Seismic alert ended");
        }
    } else if (sensor1_state == PIGPIO_FUNC_INPUT && sensor2_state == PIGPIO_FUNC_INPUT) {
        if (!alert_active) {
            alert_active = 1;
            gpioWrite(ALERT_PIN, 1);
            log_event("Seismic alert started");
        }
    }
}

void signal_handler(int sig) {
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(SENSOR1, PI_INPUT);
    gpioSetMode(SENSOR2, PI_INPUT);
    gpioSetMode(ALERT_PIN, PI_OUTPUT);
    gpioSetPullUpDown(SENSOR1, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR2, PI_PUD_DOWN);

    gpioSetAlertFunc(SENSOR1, alert_handler);
    gpioSetAlertFunc(SENSOR2, alert_handler);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        gpioDelay(100000); // Sleep for 100ms
    }

    return 0;
}

