#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_RANGE 255
#define PWM_FREQ 100
#define GPIO_PINS {17, 18, 27}
#define NUM_LAMPS sizeof(GPIO_PINS) / sizeof(GPIO_PINS[0])

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

void cleanup() {
    for (int i = 0; i < NUM_LAMPS; i++) {
        gpioSetMode(GPIO_PINS[i], PI_INPUT);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    exit(0);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <fade_duration>\n", argv[0]);
        return 1;
    }

    int fade_duration;
    if (sscanf(argv[1], "%d", &fade_duration) != 1 || fade_duration < 1 || fade_duration > 3600) {
        fprintf(stderr, "Invalid fade duration. Please provide an integer between 1 and 3600.\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio library.\n");
        return 1;
    }

    for (int i = 0; i < NUM_LAMPS; i++) {
        gpioSetMode(GPIO_PINS[i], PI_OUTPUT);
        gpioSetPWMfrequency(GPIO_PINS[i], PWM_FREQ);
        gpioSetPWMrange(GPIO_PINS[i], PWM_RANGE);
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Smart Sunset Simulator started. Fading duration: %d seconds.\n", fade_duration);

    for (int i = 0; i < NUM_LAMPS; i++) {
        while (!stop_flag) {
            for (int duty_cycle = PWM_RANGE; duty_cycle >= 0; duty_cycle--) {
                gpioSetPWMrange(GPIO_PINS[i], duty_cycle);
                gpioDelay(1000000 / (PWM_FREQ * PWM_RANGE)); // 1 second per PWM cycle
                if (stop_flag) break;
            }
            if (stop_flag) break;
            printf("Lamp %d faded out.\n", i + 1);
            gpioSetPWMrange(GPIO_PINS[i], 0);
            gpioDelay(1000000); // 1 second delay between lamps
        }
        if (stop_flag) break;
    }

    if (stop_flag) {
        printf("Fade interrupted by user.\n");
    } else {
        printf("All lamps faded out.\n");
    }

    cleanup();

    return 0;
}

