#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINES {17, 22, 23, 24}
#define RED 0
#define YELLOW 1
#define GREEN 2
#define CYCLE_TIME 25

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

void set_relay(int chip_fd, int line_num, int state) {
    struct gpiod_line *line = gpiod_chip_get_line(chip_fd, line_num);
    if (!line) {
        perror("Failed to get line");
        return;
    }

    if (gpiod_line_request_output(line, "traffic_light", state ? 0 : 1) < 0) {
        perror("Failed to request line as output");
        gpiod_line_release(line);
        return;
    }

    printf("Relay %d set to %s\n", line_num, state ? "OFF" : "ON");
}

int main() {
    struct gpiod_chip *chip;
    int chip_fd;
    int lines[] = GPIO_LINES;
    int i;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    chip_fd = gpiod_chip_get_fd(chip);

    for (i = 0; i < sizeof(lines) / sizeof(lines[0]); i++) {
        set_relay(chip_fd, lines[i], 1); // Initialize all relays to OFF
    }

    while (running) {
        for (i = 0; i < sizeof(lines) / sizeof(lines[0]); i++) {
            set_relay(chip_fd, lines[i], 0); // Turn on the current relay
            sleep(CYCLE_TIME / 4); // Each state is 25/4 = 6.25 seconds
            set_relay(chip_fd, lines[i], 1); // Turn off the current relay
        }
    }

    for (i = 0; i < sizeof(lines) / sizeof(lines[0]); i++) {
        set_relay(chip_fd, lines[i], 1); // Ensure all relays are OFF on exit
    }

    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

