#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define RELAY_PIN 17
#define MPR121_I2C_ADDRESS 0x5A
#define MPR121_I2C_BUS 1

#define MPR121_RESET 0x80
#define MPR121_STOP_MODE 0x5E
#define MPR121_ENABLE_ELECTRODE_0 0x5D
#define MPR121_TOUCH_THRESHOLD 0x41
#define MPR121_RELEASE_THRESHOLD 0x42
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CHARGE_TIME 0x5C
#define MPR121_RUN_MODE 0x5E

#define I2C_READ 0x00
#define I2C_WRITE 0x01

FILE *log_file;

void log_error(const char *message) {
    time_t now = time(NULL);
    fprintf(log_file, "%s: %s\n", ctime(&now), message);
    fflush(log_file);
}

void signal_handler(int signum) {
    log_error("Received signal, cleaning up...");
    gpioTerminate();
    if (log_file) {
        fclose(log_file);
    }
    exit(signum);
}

int main() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialise pigpio");
        return 1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        log_error("Failed to set GPIO17 as output");
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(RELAY_PIN, 0) < 0) {
        log_error("Failed to set GPIO17 to LOW");
        gpioTerminate();
        return 1;
    }

    int i2c_handle = i2cOpen(MPR121_I2C_BUS, MPR121_I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C device");
        gpioTerminate();
        return 1;
    }

    uint8_t reset_data[] = {MPR121_RESET, 0x63};
    if (i2cWriteDevice(i2c_handle, reset_data, sizeof(reset_data)) < 0) {
        log_error("Failed to reset MPR121");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t stop_mode_data[] = {MPR121_STOP_MODE, 0x00};
    if (i2cWriteDevice(i2c_handle, stop_mode_data, sizeof(stop_mode_data)) < 0) {
        log_error("Failed to set MPR121 to stop mode");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t enable_electrode_0_data[] = {MPR121_ENABLE_ELECTRODE_0, 0x01};
    if (i2cWriteDevice(i2c_handle, enable_electrode_0_data, sizeof(enable_electrode_0_data)) < 0) {
        log_error("Failed to enable electrode 0");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t touch_threshold_data[] = {MPR121_TOUCH_THRESHOLD, 0x0A};
    if (i2cWriteDevice(i2c_handle, touch_threshold_data, sizeof(touch_threshold_data)) < 0) {
        log_error("Failed to set touch threshold");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t release_threshold_data[] = {MPR121_RELEASE_THRESHOLD, 0x08};
    if (i2cWriteDevice(i2c_handle, release_threshold_data, sizeof(release_threshold_data)) < 0) {
        log_error("Failed to set release threshold");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t debounce_data[] = {MPR121_DEBOUNCE, 0x21};
    if (i2cWriteDevice(i2c_handle, debounce_data, sizeof(debounce_data)) < 0) {
        log_error("Failed to set debounce");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t charge_time_data[] = {MPR121_CHARGE_TIME, 0x0D};
    if (i2cWriteDevice(i2c_handle, charge_time_data, sizeof(charge_time_data)) < 0) {
        log_error("Failed to set charge time");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t run_mode_data[] = {MPR121_RUN_MODE, 0x0D};
    if (i2cWriteDevice(i2c_handle, run_mode_data, sizeof(run_mode_data)) < 0) {
        log_error("Failed to set MPR121 to run mode");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("touch_relay.log", "a");
    if (!log_file) {
        log_error("Failed to open log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int relay_state = 0;
    uint8_t touch_status[2];
    while (1) {
        if (i2cReadDevice(i2c_handle, touch_status, sizeof(touch_status)) < 0) {
            log_error("Failed to read touch status");
            continue;
        }

        if (touch_status[0] & 0x01) {
            if (!relay_state) {
                relay_state = 1;
                gpioWrite(RELAY_PIN, 1);
                log_error("Relay turned ON");
            }
        } else {
            if (relay_state) {
                relay_state = 0;
                gpioWrite(RELAY_PIN, 0);
                log_error("Relay turned OFF");
            }
        }

        usleep(10000); // 10 ms
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);
    return 0;
}

