    led_line = gpiod_chip_get_line(chip, 23);
    if (!led_line) {
        perror("Failed to get LED line");
        gpiod_line_release(sensor_line);
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Set sensor line as input
    if (gpiod_line_request_input(sensor_line, "flame_sensor")) {
        perror("Failed to request sensor line as input");
        gpiod_line_release(sensor_line);
        gpiod_line_release(buzzer_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Set buzzer and LED lines as output
    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) ||
        gpiod_line_request_output(led_line, "led", 0)) {
        perror("Failed to request buzzer and LED lines as output");
        gpiod_line_release(sensor_line);
        gpiod_line_release(buzzer_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Register signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        // Read sensor value
        sensor_value = gpiod_line_get_value(sensor_line);
        if (sensor_value < 0) {
            perror("Failed to read sensor value");
            cleanup(EXIT_FAILURE);
        }

        // Debounce sensor reading
        if (sensor_value != last_sensor_value) {
            consecutive_flame = 0;
        } else {
            consecutive_flame++;
        }

        if (consecutive_flame >= 3) {
            // Flame detected
            if (sensor_value == 0) {
                // Turn on buzzer and LED
                gpiod_line_set_value(buzzer_line, 1);
                gpiod_line_set_value(led_line, 1);

                // Log flame detection event
                clock_gettime(CLOCK_REALTIME, &ts);
                fprintf(log_file, "%ld.%09ld: Flame Detected\n", ts.tv_sec, ts.tv_nsec);
                fflush(log_file);
            } else {
                // Turn off buzzer and LED
                gpiod_line_set_value(buzzer_line, 0);
                gpiod_line_set_value(led_line, 0);
            }

            // Reset debounce counter
            consecutive_flame = 0;
        }

        last_sensor_value = sensor_value;
        usleep(50000); // 50 ms delay
    }

    return EXIT_SUCCESS;
}

