#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pigpio.h>
#include <signal.h>

#define GPIO17 17
#define GPIO27 27
#define DISPENSE_DURATION 1000
#define DISPENSE_INTERVAL 5000

void log_dispense_event(int solenoid1, int solenoid2, int duration) {
    FILE *log_file = fopen("dispense_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }
    time_t now = time(NULL);
    fprintf(log_file, "%s, Solenoid1: %d, Solenoid2: %d, Duration: %d ms\n", ctime(&now), solenoid1, solenoid2, duration);
    fclose(log_file);
}

void deactivate_solenoids() {
    gpioWrite(GPIO17, PI_LOW);
    gpioWrite(GPIO27, PI_LOW);
}

void sigint_handler(int sig) {
    deactivate_solenoids();
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    if (gpioSetMode(GPIO17, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO17 as output\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(GPIO27, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO27 as output\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        gpioWrite(GPIO17, PI_HIGH);
        gpioWrite(GPIO27, PI_LOW);
        gpioDelay(DISPENSE_DURATION / 2 * 1000);
        gpioWrite(GPIO17, PI_LOW);
        gpioWrite(GPIO27, PI_HIGH);
        gpioDelay(DISPENSE_DURATION / 2 * 1000);
        gpioWrite(GPIO17, PI_LOW);
        gpioWrite(GPIO27, PI_LOW);
        log_dispense_event(1, 0, DISPENSE_DURATION);
        gpioDelay(DISPENSE_INTERVAL * 1000);
    }

    gpioTerminate();
    return 0;
}

