#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23
#define ENA 24
#define ENB 25
#define PID_INTERVAL 50

typedef struct {
    double Kp, Ki, Kd;
    double setpoint, integral, prev_error;
} PIDController;

void signal_handler(int sig) {
    gpioWrite(MOTOR_A_FORWARD, 0);
    gpioWrite(MOTOR_A_BACKWARD, 0);
    gpioWrite(MOTOR_B_FORWARD, 0);
    gpioWrite(MOTOR_B_BACKWARD, 0);
    gpioTerminate();
    exit(0);
}

double simulate_tilt_error() {
    return (double)rand() / RAND_MAX * 20.0 - 10.0;
}

double simulate_distance() {
    return (double)rand() / RAND_MAX * 380.0 + 2.0;
}

void log_control_cycle(FILE *log_file, double tilt_error, double distance, int motor_a_speed, int motor_b_speed) {
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline character
    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);
    gpioSetMode(ENA, PI_OUTPUT);
    gpioSetMode(ENB, PI_OUTPUT);

    gpioWrite(ENA, 1);
    gpioWrite(ENB, 1);

    FILE *log_file = fopen("balance_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    PIDController pid = {1.0, 0.01, 0.1, 0.0, 0.0, 0.0};
    double prev_tilt_error = 0.0;
    double prev_distance = 0.0;

    while (1) {
        double tilt_error = simulate_tilt_error();
        double distance = simulate_distance();

        double error = pid.setpoint - tilt_error;
        pid.integral += error;
        double derivative = error - prev_tilt_error;
        double output = pid.Kp * error + pid.Ki * pid.integral + pid.Kd * derivative;

        int motor_a_speed = (int)output;
        int motor_b_speed = (int)output;

        if (distance < 20.0) {
            motor_a_speed = -128;
            motor_b_speed = -128;
        }

        motor_a_speed = motor_a_speed > 255 ? 255 : motor_a_speed;
        motor_a_speed = motor_a_speed < -255 ? -255 : motor_a_speed;
        motor_b_speed = motor_b_speed > 255 ? 255 : motor_b_speed;
        motor_b_speed = motor_b_speed < -255 ? -255 : motor_b_speed;

        gpioWrite(MOTOR_A_FORWARD, motor_a_speed > 0);
        gpioWrite(MOTOR_A_BACKWARD, motor_a_speed < 0);
        gpioWrite(MOTOR_B_FORWARD, motor_b_speed > 0);
        gpioWrite(MOTOR_B_BACKWARD, motor_b_speed < 0);

        log_control_cycle(log_file, tilt_error, distance, motor_a_speed, motor_b_speed);

        prev_tilt_error = error;
        prev_distance = distance;

        gpioDelay(PID_INTERVAL * 1000);
    }

    fclose(log_file);
    gpioTerminate();
    return 0;
}

