    }

    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioSetMode(TOUCH_PIN, PI_INPUT);
    gpioSetPullUpDown(TOUCH_PIN, PI_PUD_DOWN);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int relay_state = 0;
    int last_touch_state = 0;
    unsigned long last_touch_time = 0;

    while (running) {
        int current_touch_state = gpioRead(TOUCH_PIN);

        if (current_touch_state != last_touch_state) {
            last_touch_time = gpioTick();
        }

        if (gpioTick() - last_touch_time > DEBOUNCE_DELAY * 1000) {
            if (current_touch_state == 1 && current_touch_state != last_touch_state) {
                relay_state = !relay_state;
                gpioWrite(RELAY_PIN, relay_state);
                printf("Relay is now %s\n", relay_state ? "ON" : "OFF");
            }
            last_touch_state = current_touch_state;
        }

        gpioDelay(1000); // Sleep for 1 ms
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

