#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <alsa/asoundlib.h>
#include <pigpio.h>

#define GPIO_RED 17
#define GPIO_GREEN 18
#define GPIO_BLUE 27
#define SAMPLE_RATE 8000
#define FRAMES_PER_PERIOD 1024
#define BUFFER_SIZE (FRAMES_PER_PERIOD * 2)
#define SENSITIVITY_DEFAULT 1.0
#define SENSITIVITY_MIN 0.1
#define SENSITIVITY_MAX 10.0
#define DELAY_MS 10

static int running = 1;
static snd_pcm_t *capture_handle = NULL;
static float sensitivity = SENSITIVITY_DEFAULT;

static void cleanup() {
    if (capture_handle) {
        snd_pcm_drop(capture_handle);
        snd_pcm_close(capture_handle);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
}

static void signal_handler(int signum) {
    running = 0;
    cleanup();
    exit(signum);
}

static float compute_rms(const short *buffer, size_t length) {
    float sum = 0.0;
    for (size_t i = 0; i < length; ++i) {
        sum += buffer[i] * buffer[i];
    }
    return sqrt(sum / length);
}

static void set_rgb(float r, float g, float b) {
    gpioSetPWMRange(GPIO_RED, 255);
    gpioSetPWMRange(GPIO_GREEN, 255);
    gpioSetPWMRange(GPIO_BLUE, 255);
    gpioSetPWMFrequency(GPIO_RED, SAMPLE_RATE);
    gpioSetPWMFrequency(GPIO_GREEN, SAMPLE_RATE);
    gpioSetPWMFrequency(GPIO_BLUE, SAMPLE_RATE);
    gpioSetPWM(GPIO_RED, (int)(255 * r));
    gpioSetPWM(GPIO_GREEN, (int)(255 * g));
    gpioSetPWM(GPIO_BLUE, (int)(255 * b));
}

static void simulate_audio() {
    static float t = 0.0;
    float amplitude = 0.5 * sin(t);
    t += 0.01 * SAMPLE_RATE;
    set_rgb(amplitude, 0.5, 0.5);
}

int main(int argc, char *argv[]) {
    if (argc > 2) {
        fprintf(stderr, "Usage: %s [sensitivity]\n", argv[0]);
        return 1;
    }

    if (argc == 2) {
        sensitivity = atof(argv[1]);
        if (sensitivity < SENSITIVITY_MIN || sensitivity > SENSITIVITY_MAX) {
            fprintf(stderr, "Sensitivity must be between %f and %f\n", SENSITIVITY_MIN, SENSITIVITY_MAX);
            return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    gpioSetMode(GPIO_RED, PI_OUTPUT);
    gpioSetMode(GPIO_GREEN, PI_OUTPUT);
    gpioSetMode(GPIO_BLUE, PI_OUTPUT);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (snd_pcm_open(&capture_handle, "default", SND_PCM_STREAM_CAPTURE, 0) < 0) {
        fprintf(stderr, "Failed to open ALSA capture device\n");
        cleanup();
        return 1;
    }

    snd_pcm_hw_params_t *hw_params;
    snd_pcm_hw_params_alloca(&hw_params);
    snd_pcm_hw_params_any(capture_handle, hw_params);
    snd_pcm_hw_params_set_access(capture_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED);
    snd_pcm_hw_params_set_format(capture_handle, hw_params, SND_PCM_FORMAT_S16_LE);
    snd_pcm_hw_params_set_rate_near(capture_handle, hw_params, &SAMPLE_RATE, 0);
    snd_pcm_hw_params_set_channels(capture_handle, hw_params, 1);
    snd_pcm_hw_params_set_period_size_near(capture_handle, hw_params, &FRAMES_PER_PERIOD, 0);
    snd_pcm_hw_params(capture_handle, hw_params);

    short buffer[BUFFER_SIZE];
    while (running) {
        snd_pcm_sframes_t frames_read = snd_pcm_readi(capture_handle, buffer, FRAMES_PER_PERIOD);
        if (frames_read < 0) {
            if (frames_read == -EPIPE) {
                snd_pcm_prepare(capture_handle);
            } else if (frames_read == -ESTRPIPE) {
                snd_pcm_resume(capture_handle);
            } else {
                fprintf(stderr, "Failed to read ALSA audio: %s\n", snd_strerror(frames_read));
                running = 0;
            }
        } else {
            float rms = compute_rms(buffer, frames_read);
            float r, g, b;
            if (rms < 0.1) {
                r = 0.0;
                g = 0.0;
                b = 1.0; // Blue
            } else if (rms > 0.5) {
                r = 1.0;
                g = 0.0;
                b = 0.0; // Red
            } else {
                r = 0.0;
                g = 1.0;
                b = 0.0; // Green
            }
            set_rgb(r * sensitivity, g * sensitivity, b * sensitivity);
        }
        gpioDelay(DELAY_MS * 1000);
    }

    cleanup();
    return 0;
}

