#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define POWER_ON_REG 0x80
#define RGBC_ENABLE 0x03
#define INTEGRATION_TIME_REG 0x81
#define INTEGRATION_TIME 0xD5
#define DATA_START_REG 0x14
#define DATA_SIZE 8

void signal_handler(int signum) {
    printf("Signal %d received, exiting...\n", signum);
    gpioTerminate();
    exit(signum);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    int i2c_handle = gpioI2COpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return 1;
    }

    if (gpioI2CWriteByteData(i2c_handle, POWER_ON_REG, RGBC_ENABLE) < 0) {
        fprintf(stderr, "Failed to power on sensor\n");
    }

    if (gpioI2CWriteByteData(i2c_handle, INTEGRATION_TIME_REG, INTEGRATION_TIME) < 0) {
        fprintf(stderr, "Failed to set integration time\n");
    }

    FILE *file = fopen("color_data.csv", "w");
    if (!file) {
        fprintf(stderr, "Failed to open color_data.csv for writing\n");
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fprintf(file, "Timestamp,C,R,G,B\n");

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        uint8_t data[DATA_SIZE];
        if (gpioI2CRead(i2c_handle, data, DATA_SIZE) < 0) {
            fprintf(stderr, "Failed to read data from sensor\n");
            for (int i = 0; i < DATA_SIZE; i++) {
                data[i] = 0;
            }
        }

        time_t now = time(NULL);
        fprintf(file, "%ld,%d,%d,%d,%d\n", now, data[0] | (data[1] << 8), data[2] | (data[3] << 8), data[4] | (data[5] << 8), data[6] | (data[7] << 8));

        gpioDelay(500000);
    }

    fclose(file);
    gpioI2CClose(i2c_handle);
    gpioTerminate();

    return 0;
}

