#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PINS {17, 27, 22, 23}
#define PHASE_DURATION {3600, 3600, 3600, 518400} // sunrise, daytime, sunset, nighttime
#define PWM_STEPS 100

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void set_relay(int pin, int value) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(line, "relay");
    if (ret < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_value(line, value);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
}

void pwm_relay(int pin, int duty_cycle) {
    int step_time = 1000000 / PWM_STEPS;
    for (int i = 0; i < duty_cycle; i++) {
        set_relay(pin, 0);
        usleep(step_time);
    }
    for (int i = 0; i < (PWM_STEPS - duty_cycle); i++) {
        set_relay(pin, 1);
        usleep(step_time);
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int pins[] = GPIO_PINS;
    int durations[] = PHASE_DURATION;

    while (running) {
        for (int i = 0; i < 4; i++) {
            if (i == 0 || i == 2) { // Sunrise and sunset
                for (int j = 0; j <= PWM_STEPS; j++) {
                    pwm_relay(pins[i], j);
                    usleep(durations[i] / PWM_STEPS);
                }
            } else { // Daytime and nighttime
                set_relay(pins[i], i == 1); // Full brightness for daytime, off for nighttime
                usleep(durations[i]);
            }
        }
    }

    for (int i = 0; i < 4; i++) {
        set_relay(pins[i], 1); // Turn off all relays
    }

    return 0;
}

