volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_event(const char *event) {
    FILE *log = fopen(LOG_FILE, "a");
    if (log == NULL) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    char *iso_time = ctime(&now);
    iso_time[strlen(iso_time) - 1] = '\0'; // Remove newline
    fprintf(log, "%s: %s\n", iso_time, event);
    fclose(log);
}

void record_video(const char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "raspivid -t %d -o %s", VIDEO_DURATION * 1000, filename);
