    if (log == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    time_t last_event_time = 0;
    while (running) {
        if (gpioRead(GPIO_PIN) == 0) {
            time_t now = time(NULL);
