#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x68
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_CONFIG 0x19
#define MPU6050_GYRO_CONFIG 0x1B
#define MPU6050_GYRO_XOUT_H 0x43
#define MPU6050_GYRO_XOUT_L 0x44
#define MPU6050_GYRO_YOUT_H 0x45
#define MPU6050_GYRO_YOUT_L 0x46
#define MPU6050_GYRO_ZOUT_H 0x47
#define MPU6050_GYRO_ZOUT_L 0x48
#define GYRO_SENSITIVITY 131.0

FILE *log_file = NULL;

void signal_handler(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(signum);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return 1;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    log_file = fopen("gyro_log.csv", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fprintf(log_file, "timestamp,X_degps,Y_degps,Z_degps\n");

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        uint8_t data[6];
        int retries = 0;
        while (retries < 3) {
            int result = i2cReadI2CBlockData(i2c_handle, MPU6050_GYRO_XOUT_H, data, 6);
            if (result == 6) {
                int16_t x = (data[0] << 8) | data[1];
                int16_t y = (data[2] << 8) | data[3];
                int16_t z = (data[4] << 8) | data[5];
                double x_degps = x / GYRO_SENSITIVITY;
                double y_degps = y / GYRO_SENSITIVITY;
                double z_degps = z / GYRO_SENSITIVITY;

                clock_gettime(CLOCK_REALTIME, &ts);
                fprintf(log_file, "%ld.%03ld,%f,%f,%f\n", ts.tv_sec, ts.tv_nsec / 1000000, x_degps, y_degps, z_degps);
                fflush(log_file);
                break;
            } else {
                retries++;
                if (retries == 3) {
                    fprintf(stderr, "Failed to read from MPU-6050 after 3 retries\n");
                    break;
                }
                // Re-initialize sensor
                i2cWriteByteData(i2c_handle, MPU6050_PWR_MGMT_1, 0x00);
                i2cWriteByteData(i2c_handle, MPU6050_CONFIG, 0x07);
                i2cWriteByteData(i2c_handle, MPU6050_GYRO_CONFIG, 0x00);
                usleep(100000); // Wait 100 ms
            }
        }

        usleep(10000); // Wait 10 ms
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

