#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PINS {4, 17, 27, 22}
#define LOG_FILE "irrigation_log.txt"
#define THRESHOLD 30

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(GPIO_PINS[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO %d mode\n", GPIO_PINS[i]);
            fclose(log_file);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        gpioWrite(GPIO_PINS[i], PI_HIGH);
    }

    signal(SIGINT, signal_handler);

    while (running) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        for (int i = 0; i < 4; i++) {
            int moisture = rand() % 101;
            fprintf(log_file, "%s - Zone %d: Moisture %d%%, Relay %s\n", timestamp, i + 1, moisture, gpioRead(GPIO_PINS[i]) == PI_HIGH ? "OFF" : "ON");
            if (moisture < THRESHOLD) {
                gpioWrite(GPIO_PINS[i], PI_LOW);
            } else {
                gpioWrite(GPIO_PINS[i], PI_HIGH);
            }
        }

        fflush(log_file);
        sleep(5);
    }

    for (int i = 0; i < 4; i++) {
        gpioWrite(GPIO_PINS[i], PI_HIGH);
    }

    fclose(log_file);
    gpioTerminate();

    return EXIT_SUCCESS;
}

