#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x53
#define ADXL345_DATAX0 0x32
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_POWER_CTL 0x2D
#define GPIO_ALARM 27
#define FREEFALL_THRESHOLD 0.2
#define FREEFALL_DURATION 0.5
#define FREEFALL_CHECK_INTERVAL 0.5
#define FREEFALL_LOG "freefall.log"

void log_freefall_event(double x, double y, double z) {
    FILE *log_file = fopen(FREEFALL_LOG, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d,%.3f,%.3f,%.3f\n",
            tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
            tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec, x, y, z);
    fclose(log_file);
}

void freefall_detected() {
    gpioWrite(GPIO_ALARM, PI_HIGH);
    gpioDelay(5000000); // 5 seconds
    gpioWrite(GPIO_ALARM, PI_LOW);
}

void read_accelerometer_data(double *x, double *y, double *z) {
    uint8_t data[6];
    if (i2cReadDevice(I2C_BUS, I2C_ADDR, ADXL345_DATAX0, data, 6) != 6) {
        fprintf(stderr, "Failed to read accelerometer data\n");
        return;
    }
    *x = (int16_t)((data[1] << 8) | data[0]) / 256.0;
    *y = (int16_t)((data[3] << 8) | data[2]) / 256.0;
    *z = (int16_t)((data[5] << 8) | data[4]) / 256.0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    if (gpioSetMode(GPIO_ALARM, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    if (i2cOpen(I2C_BUS, I2C_ADDR, 0) < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByteData(I2C_BUS, I2C_ADDR, ADXL345_DATA_FORMAT, 0x0B) != 0) {
        fprintf(stderr, "Failed to set data format\n");
        i2cClose(I2C_BUS);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByteData(I2C_BUS, I2C_ADDR, ADXL345_POWER_CTL, 0x08) != 0) {
        fprintf(stderr, "Failed to enable measurement mode\n");
        i2cClose(I2C_BUS);
        gpioTerminate();
        return 1;
    }

    double x, y, z;
    int freefall_count = 0;
    clock_t start_time = clock();

    while (1) {
        read_accelerometer_data(&x, &y, &z);

        if (fabs(x) < FREEFALL_THRESHOLD && fabs(y) < FREEFALL_THRESHOLD && fabs(z) < FREEFALL_THRESHOLD) {
            freefall_count++;
            if (freefall_count >= FREEFALL_DURATION / FREEFALL_CHECK_INTERVAL) {
                freefall_detected();
                log_freefall_event(x, y, z);
                freefall_count = 0;
            }
        } else {
            freefall_count = 0;
        }

        clock_t current_time = clock();
        if (difftime(current_time, start_time) >= 100) {
            start_time = current_time;
        }

        gpioDelay(100000); // 100 ms
    }

    i2cClose(I2C_BUS);
    gpioTerminate();
    return 0;
}

void sigint_handler(int sig) {
    i2cClose(I2C_BUS);
    gpioWrite(GPIO_ALARM, PI_LOW);
    gpioTerminate();
    exit(0);
}

