    clock_t start_time = clock();

    while (1) {
        read_accelerometer_data(&x, &y, &z);

        if (fabs(x) < FREEFALL_THRESHOLD && fabs(y) < FREEFALL_THRESHOLD && fabs(z) < FREEFALL_THRESHOLD) {
            freefall_count++;
            if (freefall_count >= FREEFALL_DURATION / FREEFALL_CHECK_INTERVAL) {
                freefall_detected();
                log_freefall_event(x, y, z);
                freefall_count = 0;
            }
        } else {
            freefall_count = 0;
        }

        clock_t current_time = clock();
        if (difftime(current_time, start_time) >= 100) {
            start_time = current_time;
        }

        gpioDelay(100000); // 100 ms
    }

    i2cClose(I2C_BUS);
    gpioTerminate();
    return 0;
}

void sigint_handler(int sig) {
    i2cClose(I2C_BUS);
    gpioWrite(GPIO_ALARM, PI_LOW);
    gpioTerminate();
    exit(0);
}
