#define TIMEOUT_NS 100000000  // 100 ms in nanoseconds
#define TRIGGER_INTERVAL_MS 200  // 200 ms in milliseconds
#define TRIGGER_PULSE_US 10  // 10 microseconds trigger pulse

FILE *log_file;
pthread_mutex_t pulse_mutex;
volatile uint32_t echo_start = 0;
volatile uint32_t echo_end = 0;
volatile int measuring = 0;

void *measure_distance(void *arg) {
    while (measuring) {
        uint32_t trigger_time = gpioTick();
        gpioWrite(TRIG_PIN, PI_HIGH);
        gpioDelay(TRIGGER_PULSE_US);
        gpioWrite(TRIG_PIN, PI_LOW);

        uint32_t now = gpioTick();
        while (gpioRead(ECHO_PIN) == PI_LOW && now - trigger_time < TIMEOUT_NS / 1000) {
            now = gpioTick();
        }
        if (gpioRead(ECHO_PIN) == PI_LOW) {
            continue;  // Timeout
        }

        echo_start = now;
        while (gpioRead(ECHO_PIN) == PI_HIGH && now - trigger_time < TIMEOUT_NS / 1000) {
            now = gpioTick();
        }
        if (gpioRead(ECHO_PIN) == PI_HIGH) {
            continue;  // Timeout
        }

        echo_end = now;

        uint32_t pulse_width = echo_end - echo_start;
        if (pulse_width > MAX_DISTANCE) {
            continue;  // Invalid distance
        }

        double distance_cm = pulse_width * 0.034 / 2;  // Speed of sound is 340 m/s

        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        uint64_t timestamp_ns = ts.tv_sec * 1000000000 + ts.tv_nsec;

        pthread_mutex_lock(&pulse_mutex);
        fprintf(log_file, "%llu,%f\n", timestamp_ns, distance_cm);
        fflush(log_file);
        pthread_mutex_unlock(&pulse_mutex);
    }
    return NULL;
}

void gpio_callback(int gpio, int level, uint32_t tick) {
    if (gpio == ECHO_PIN) {
        if (level == PI_RISING) {
            echo_start = tick;
        } else if (level == PI_FALLING) {
            echo_end = tick;
        }
    }
}

void sigint_handler(int sig) {
    measuring = 0;
    gpioTerminate();
    fclose(log_file);
    pthread_mutex_destroy(&pulse_mutex);
    exit(0);
}

