    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) < 0 || gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    if ((log_file = fopen("distance_log.txt", "w")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    pthread_mutex_init(&pulse_mutex, NULL);

    gpioSetAlertFunc(ECHO_PIN, gpio_callback);

    measuring = 1;
    pthread_t thread;
    if (pthread_create(&thread, NULL, measure_distance, NULL) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        measuring = 0;
        gpioTerminate();
        fclose(log_file);
        pthread_mutex_destroy(&pulse_mutex);
        return 1;
    }

    signal(SIGINT, sigint_handler);

    pthread_join(thread, NULL);

    return 0;
}

