#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define I2C_BUS 1
#define I2C_ADDR 0x18
#define GPIO_Buzzer 17
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define LSB_PER_G 16384.0
#define DEFAULT_FREEFALL_THRESHOLD 0.2
#define DEFAULT_IMPACT_THRESHOLD 1.5
#define RETRY_COUNT 3

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

int read_i2c(int fd, uint8_t reg, uint8_t *data, size_t len) {
    for (int i = 0; i < RETRY_COUNT; i++) {
        if (i2c_write_byte_data(fd, reg) < 0) {
            continue;
        }
        if (i2c_read_i2c_block_data(fd, data, len) == len) {
            return 0;
        }
    }
    return -1;
}

int write_i2c(int fd, uint8_t reg, uint8_t data) {
    for (int i = 0; i < RETRY_COUNT; i++) {
        if (i2c_write_byte_data(fd, reg, data) >= 0) {
            return 0;
        }
    }
    return -1;
}

int main(int argc, char *argv[]) {
    int fd;
    uint8_t data[6];
    float freefall_threshold = DEFAULT_FREEFALL_THRESHOLD;
    float impact_threshold = DEFAULT_IMPACT_THRESHOLD;

    if (argc > 1) {
        freefall_threshold = atof(argv[1]);
    }
    if (argc > 2) {
        impact_threshold = atof(argv[2]);
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(GPIO_Buzzer, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_Buzzer);
        gpioTerminate();
        return 1;
    }

    if ((fd = i2cOpen(I2C_BUS, I2C_ADDR, 0)) < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return 1;
    }

    if (write_i2c(fd, CTRL_REG1, 0x77) < 0) {
        fprintf(stderr, "Failed to configure CTRL_REG1\n");
        i2cClose(fd);
        gpioTerminate();
        return 1;
    }

    if (write_i2c(fd, CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Failed to configure CTRL_REG4\n");
        i2cClose(fd);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (!stop_flag) {
        if (read_i2c(fd, OUT_X_L, data, 6) < 0) {
            fprintf(stderr, "Failed to read I2C data\n");
            continue;
        }

        int16_t x = (data[1] << 8) | data[0];
        int16_t y = (data[3] << 8) | data[2];
        int16_t z = (data[5] << 8) | data[4];

        float magnitude = sqrt(x * x + y * y + z * z) / LSB_PER_G;

        if (magnitude < freefall_threshold) {
            printf("Freefall detected\n");
        } else if (magnitude > impact_threshold) {
            printf("Impact detected\n");
            gpioWrite(GPIO_Buzzer, 1);
            sleep(1);
            gpioWrite(GPIO_Buzzer, 0);
        }
    }

    i2cClose(fd);
    gpioTerminate();
    return 0;
}

