#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define DEFAULT_I2C_ADDRESS 0x18
#define DEFAULT_THRESHOLD 2.0
#define I2C_DEVICE "/dev/i2c-1"
#define LOG_FILE "/var/log/high_acceleration.log"

volatile int i2cHandle = -1;

void cleanup() {
    if (i2cHandle >= 0) {
        i2cClose(i2cHandle);
    }
    pigpioTerminate();
    exit(0);
}

void sigintHandler(int sig) {
    cleanup();
}

int main(int argc, char *argv[]) {
    int i2cAddress = DEFAULT_I2C_ADDRESS;
    float threshold = DEFAULT_THRESHOLD;
    char *endptr;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-a") == 0 && i + 1 < argc) {
            i2cAddress = (int)strtol(argv[i + 1], &endptr, 16);
            if (*endptr != '\0' || i2cAddress < 0x08 || i2cAddress > 0x77) {
                fprintf(stderr, "Invalid I2C address: %s\n", argv[i + 1]);
                return 1;
            }
            i++;
        } else if (strcmp(argv[i], "-t") == 0 && i + 1 < argc) {
            threshold = strtof(argv[i + 1], &endptr);
            if (*endptr != '\0' || threshold <= 0) {
                fprintf(stderr, "Invalid threshold: %s\n", argv[i + 1]);
                return 1;
            }
            i++;
        }
    }

    if (pigpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    i2cHandle = i2cOpen(1, i2cAddress, 0);
    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        cleanup();
        return 1;
    }

    if (i2cWriteByteData(i2cHandle, 0x20, 0x57) < 0) {
        fprintf(stderr, "Failed to configure CTRL_REG1\n");
        cleanup();
        return 1;
    }

    if (i2cWriteByteData(i2cHandle, 0x23, 0x88) < 0) {
        fprintf(stderr, "Failed to configure CTRL_REG4\n");
        cleanup();
        return 1;
