    signal(SIGINT, sigintHandler);

    while (1) {
        uint8_t data[6];
        if (i2cReadI2CBlockData(i2cHandle, 0x28, data, 6) != 6) {
            fprintf(stderr, "Failed to read accelerometer data\n");
            continue;
        }

        int16_t x = (data[0] << 8) | data[1];
        int16_t y = (data[2] << 8) | data[3];
        int16_t z = (data[4] << 8) | data[5];

        float gx = (float)x / 16.0 * 0.0009765625;
        float gy = (float)y / 16.0 * 0.0009765625;
        float gz = (float)z / 16.0 * 0.0009765625;

        if (fabs(gx) > threshold || fabs(gy) > threshold || fabs(gz) > threshold) {
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

            FILE *logFile = fopen(LOG_FILE, "a");
            if (logFile) {
                fprintf(logFile, "%s: X=%.2f g, Y=%.2f g, Z=%.2f g\n", timestamp, gx, gy, gz);
                fclose(logFile);
            }

            system("sudo shutdown -h now");
        }

        gpioDelay(100000); // 100 ms
    }

    cleanup();
    return 0;
