#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define BUFFER_SIZE 5
#define SAMPLE_INTERVAL 10000  // 10 ms
#define ALERT_DURATION 2000000  // 2 seconds

struct sensor_data {
    int left;
    int center;
    int right;
};

struct circular_buffer {
    struct sensor_data buffer[BUFFER_SIZE];
    int head;
    int count;
};

struct gpiod_chip *chip;
struct gpiod_line *left_sensor, *center_sensor, *right_sensor, *alert_pin;
struct circular_buffer sensor_buffer;

void init_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    left_sensor = gpiod_chip_get_line(chip, 4);
    center_sensor = gpiod_chip_get_line(chip, 17);
    right_sensor = gpiod_chip_get_line(chip, 27);
    alert_pin = gpiod_chip_get_line(chip, 22);

    if (!left_sensor || !center_sensor || !right_sensor || !alert_pin) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(left_sensor, "line-following") < 0 ||
        gpiod_line_request_input(center_sensor, "line-following") < 0 ||
        gpiod_line_request_input(right_sensor, "line-following") < 0 ||
        gpiod_line_request_output(alert_pin, "line-following", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(left_sensor);
        gpiod_line_release(center_sensor);
        gpiod_line_release(right_sensor);
        gpiod_line_release(alert_pin);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
}

void cleanup() {
    gpiod_line_release(left_sensor);
    gpiod_line_release(center_sensor);
    gpiod_line_release(right_sensor);
    gpiod_line_release(alert_pin);
    gpiod_chip_close(chip);
}

void handle_signal(int signum) {
    cleanup();
    exit(EXIT_SUCCESS);
}

void add_to_buffer(struct sensor_data data) {
    if (sensor_buffer.count == BUFFER_SIZE) {
        sensor_buffer.head = (sensor_buffer.head + 1) % BUFFER_SIZE;
    } else {
        sensor_buffer.count++;
    }
    sensor_buffer.buffer[sensor_buffer.head] = data;
}

void log_sensor_data() {
    struct sensor_data data = {
        gpiod_line_get_value(left_sensor),
        gpiod_line_get_value(center_sensor),
        gpiod_line_get_value(right_sensor)
    };
    add_to_buffer(data);
    printf("Left: %d, Center: %d, Right: %d\n", data.left, data.center, data.right);
}

void check_alert() {
    int no_line_count = 0;
    for (int i = 0; i < sensor_buffer.count; i++) {
        if (sensor_buffer.buffer[(sensor_buffer.head - i + BUFFER_SIZE) % BUFFER_SIZE].center == 1) {
            no_line_count++;
        } else {
            no_line_count = 0;
        }
        if (no_line_count >= 5) {
            gpiod_line_set_value(alert_pin, 1);
            usleep(ALERT_DURATION);
            gpiod_line_set_value(alert_pin, 0);
            break;
        }
    }
}

void line_following() {
    while (1) {
        log_sensor_data();
        check_alert();
        usleep(SAMPLE_INTERVAL);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_gpio();
    sensor_buffer.head = 0;
    sensor_buffer.count = 0;

    line_following();

    cleanup();
    return 0;
}

