#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x30
#define RELAY_PIN 17
#define FIELD_THRESHOLD 5000
#define POLL_ATTEMPTS 50
#define SAMPLE_INTERVAL 100

void log_event(const char *event) {
    time_t now = time(NULL);
    char *iso_time = ctime(&now);
    iso_time[strlen(iso_time) - 1] = '\0'; // Remove newline
    printf("%s: %s\n", iso_time, event);
    FILE *log_file = fopen("magnetic_events.txt", "a");
    if (log_file) {
        fprintf(log_file, "%s: %s\n", iso_time, event);
        fclose(log_file);
    }
}

void handle_sigint(int sig) {
    log_event("Shutting down...");
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        log_event("Failed to initialize pigpio");
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        log_event("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0);

    signal(SIGINT, handle_sigint);

    while (1) {
        int attempts = 0;
        while (attempts < POLL_ATTEMPTS) {
            if (i2cWriteByteData(i2c_handle, 0xC1, 0x01) < 0) {
                log_event("Failed to start conversion");
                gpioWrite(RELAY_PIN, 0);
                break;
            }
            uint8_t status = i2cReadByteData(i2c_handle, 0xC1);
            if (status == 0x00) {
                break;
            }
            attempts++;
            gpioDelay(SAMPLE_INTERVAL * 1000);
        }

        if (attempts == POLL_ATTEMPTS) {
            log_event("Conversion timeout");
            continue;
        }

        uint8_t lsb = i2cReadByteData(i2c_handle, 0xC0);
        uint8_t msb = i2cReadByteData(i2c_handle, 0xC1);
        int16_t field_raw = (msb << 8) | lsb;
        int field_mT_x100 = field_raw * 25 / 1000;

        if (field_mT_x100 > FIELD_THRESHOLD) {
            gpioWrite(RELAY_PIN, 1);
            log_event("Relay activated");
        } else {
            gpioWrite(RELAY_PIN, 0);
            log_event("Relay deactivated");
        }

        log_event("Field strength: %d mT", field_mT_x100 / 100);

        gpioDelay(SAMPLE_INTERVAL * 1000);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

