#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define RELAY_PIN 18
#define PORT 5000
#define LOG_FILE "relay_log.txt"

volatile sig_atomic_t running = 1;

void log_event(const char *event) {
    FILE *log = fopen(LOG_FILE, "a");
    if (log == NULL) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    fprintf(log, "%s: %s\n", ctime(&now), event);
    fclose(log);
}

void handle_signal(int sig) {
    running = 0;
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, PI_OFF);
}

void cleanup_gpio() {
    gpioWrite(RELAY_PIN, PI_OFF);
    gpioTerminate();
}

void handle_client(int client_socket) {
    char buffer[1024];
    ssize_t bytes_read = read(client_socket, buffer, sizeof(buffer) - 1);
    if (bytes_read <= 0) {
        log_event("Client disconnected");
        close(client_socket);
        return;
    }
    buffer[bytes_read] = '\0';
    char *command = strtok(buffer, " \n");
    if (command == NULL) {
        log_event("Invalid command");
        return;
    }
    if (strcasecmp(command, "ON") == 0) {
        gpioWrite(RELAY_PIN, PI_ON);
        log_event("Relay ON");
    } else if (strcasecmp(command, "OFF") == 0) {
        gpioWrite(RELAY_PIN, PI_OFF);
        log_event("Relay OFF");
    } else {
        log_event("Invalid command");
    }
}

int main() {
    setup_gpio();

    int server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket < 0) {
        perror("Failed to create socket");
        cleanup_gpio();
        exit(EXIT_FAILURE);
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(PORT);

    if (bind(server_socket, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Failed to bind socket");
        close(server_socket);
        cleanup_gpio();
        exit(EXIT_FAILURE);
    }

    if (listen(server_socket, 5) < 0) {
        perror("Failed to listen on socket");
        close(server_socket);
        cleanup_gpio();
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    log_event("Server started");

    while (running) {
        int client_socket = accept(server_socket, NULL, NULL);
        if (client_socket < 0) {
            perror("Failed to accept connection");
            continue;
        }
        handle_client(client_socket);
        close(client_socket);
    }

    log_event("Server shutting down");
    close(server_socket);
    cleanup_gpio();

    return 0;
}

