#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR1_ADDR 0x08
#define SENSOR2_ADDR 0x09
#define START_MEAS_CMD 0x3608
#define RELAY_PIN 18
#define POLYNOMIAL 0x31
#define INIT_CRC 0xFF
#define CRC_LENGTH 1
#define DATA_LENGTH 2
#define SCALE_FACTOR 1.0 / 1500.0
#define POLL_INTERVAL 100000  // 100 ms in microseconds
#define LOG_FILE "flow_log.txt"

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

uint8_t calculate_crc8(const uint8_t *data, size_t length, uint8_t polynomial, uint8_t init_crc) {
    uint8_t crc = init_crc;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ polynomial;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    int i2c_handle1 = gpioI2COpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Failed to open I2C handle for sensor 1\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int i2c_handle2 = gpioI2COpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Failed to open I2C handle for sensor 2\n");
        gpioI2CClose(i2c_handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_PIN);
        gpioI2CClose(i2c_handle2);
        gpioI2CClose(i2c_handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(RELAY_PIN, 0);  // De-energize relay

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioI2CClose(i2c_handle2);
        gpioI2CClose(i2c_handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (!stop_flag) {
        uint8_t cmd[2] = {START_MEAS_CMD >> 8, START_MEAS_CMD & 0xFF};
        if (gpioI2CWrite(i2c_handle1, cmd, 2) != 2) {
            fprintf(stderr, "Failed to send start-measurement command to sensor 1\n");
            continue;
        }
        if (gpioI2CWrite(i2c_handle2, cmd, 2) != 2) {
            fprintf(stderr, "Failed to send start-measurement command to sensor 2\n");
            continue;
        }

        uint8_t data1[3], data2[3];
        if (gpioI2CRead(i2c_handle1, data1, 3) != 3) {
            fprintf(stderr, "Failed to read from sensor 1\n");
            continue;
        }
        if (gpioI2CRead(i2c_handle2, data2, 3) != 3) {
            fprintf(stderr, "Failed to read from sensor 2\n");
            continue;
        }

        uint8_t crc1 = calculate_crc8(data1, DATA_LENGTH, POLYNOMIAL, INIT_CRC);
        uint8_t crc2 = calculate_crc8(data2, DATA_LENGTH, POLYNOMIAL, INIT_CRC);

        if (crc1 != data1[DATA_LENGTH] || crc2 != data2[DATA_LENGTH]) {
            fprintf(stderr, "CRC mismatch\n");
            continue;
        }

        int16_t raw_value1 = (data1[0] << 8) | data1[1];
        int16_t raw_value2 = (data2[0] << 8) | data2[1];

        double flow_rate1 = raw_value1 * SCALE_FACTOR;
        double flow_rate2 = raw_value2 * SCALE_FACTOR;

        if (flow_rate1 < 5.0 || flow_rate2 < 5.0) {
            gpioWrite(RELAY_PIN, 1);  // Energize relay
        } else {
            gpioWrite(RELAY_PIN, 0);  // De-energize relay
        }

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        fprintf(log_file, "%s, Sensor 1: %.2f ml/min, Sensor 2: %.2f ml/min\n", asctime(tm_info), flow_rate1, flow_rate2);
        fflush(log_file);
    }

    gpioWrite(RELAY_PIN, 0);  // De-energize relay
    gpioI2CClose(i2c_handle2);
    gpioI2CClose(i2c_handle1);
    gpioTerminate();
    fclose(log_file);

    printf("Shutting down...\n");

    return EXIT_SUCCESS;
}

