#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24
#define POLL_INTERVAL 200000  // 200 ms in microseconds
#define MOTOR_RUN_TIME 5000000  // 5 seconds in microseconds
#define DRY_TO_WET_THRESHOLD 3

volatile int rain_detected = 0;
volatile int consecutive_dry = 0;

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        syslog(LOG_INFO, "Shutting down gracefully...");
        gpioWrite(MOTOR_ENA_PIN, PI_LOW);
        gpioWrite(MOTOR_IN1_PIN, PI_LOW);
        gpioWrite(MOTOR_IN2_PIN, PI_LOW);
        gpioTerminate();
        closelog();
        exit(EXIT_SUCCESS);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialise pigpio library");
        exit(EXIT_FAILURE);
    }

    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP);
    gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);

    gpioSetAlertFunc(RAIN_SENSOR_PIN, [](unsigned gpio, unsigned level, uint32_t tick) {
        if (level == PI_LOW) {
            rain_detected = 1;
        } else {
            rain_detected = 0;
            consecutive_dry++;
        }
    });

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    syslog(LOG_INFO, "Rain window controller started");

    while (1) {
        if (rain_detected && consecutive_dry >= DRY_TO_WET_THRESHOLD) {
            syslog(LOG_INFO, "Rain detected, closing window");
            gpioWrite(MOTOR_ENA_PIN, PI_HIGH);
            gpioWrite(MOTOR_IN1_PIN, PI_HIGH);
            gpioWrite(MOTOR_IN2_PIN, PI_LOW);
            gpioDelay(MOTOR_RUN_TIME);
            gpioWrite(MOTOR_ENA_PIN, PI_LOW);
            gpioWrite(MOTOR_IN1_PIN, PI_LOW);
            gpioWrite(MOTOR_IN2_PIN, PI_LOW);
            consecutive_dry = 0;
            syslog(LOG_INFO, "Window closed");
        }

        gpioDelay(POLL_INTERVAL);
    }

    gpioTerminate();
    closelog();
    return 0;
}

