#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define BUTTON1_PIN 21
#define BUTTON2_PIN 22
#define DEBOUNCE_DELAY 200

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio library\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(BUTTON1_PIN, PI_INPUT);
    gpioSetMode(BUTTON2_PIN, PI_INPUT);
    gpioSetPullUpDown(BUTTON1_PIN, PI_PUD_UP);
    gpioSetPullUpDown(BUTTON2_PIN, PI_PUD_UP);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int last_button1_state = 1;
    int last_button2_state = 1;

    while (running) {
        int button1_state = gpioRead(BUTTON1_PIN);
        int button2_state = gpioRead(BUTTON2_PIN);

        if (button1_state != last_button1_state) {
            if (button1_state == 0) {
                gpioDelay(DEBOUNCE_DELAY * 1000);
                if (gpioRead(BUTTON1_PIN) == 0) {
                    gpioServo(SERVO_PIN, 2000);
                    printf("Door locked\n");
                }
            }
            last_button1_state = button1_state;
        }

        if (button2_state != last_button2_state) {
            if (button2_state == 0) {
                gpioDelay(DEBOUNCE_DELAY * 1000);
                if (gpioRead(BUTTON2_PIN) == 0) {
                    gpioServo(SERVO_PIN, 1000);
                    printf("Door unlocked\n");
                }
            }
            last_button2_state = button2_state;
        }

        if (gpioServo(SERVO_PIN) < 0) {
            fprintf(stderr, "Failed to set servo pulse width\n");
            gpioTerminate();
            return EXIT_FAILURE;
        }

        gpioDelay(10000); // Sleep for 10ms
    }

    gpioServo(SERVO_PIN, 0);
    printf("Shutting down\n");
    gpioTerminate();
    return EXIT_SUCCESS;
}

