#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define PIR_PIN 4
#define LED_PIN 17
#define LOG_FILE "security_log.txt"
#define POLL_INTERVAL 100

volatile sig_atomic_t running = 1;

void log_event(const char *event, int duration) {
    FILE *log = fopen(LOG_FILE, "a");
    if (log == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(log, "%s: %s\n", asctime(tm_info), event);
    if (duration >= 0) {
        fprintf(log, "%s: Duration: %d seconds\n", asctime(tm_info), duration);
    }
    fclose(log);
}

void signal_handler(int sig) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    gpioSetMode(PIR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        if (gpioRead(PIR_PIN) == 1) {
            gpioWrite(LED_PIN, 1);
            log_event("Motion detected", -1);

            clock_t start = clock();
            while (gpioRead(PIR_PIN) == 1 && running) {
                gpioDelay(POLL_INTERVAL * 1000);
            }

            clock_t end = clock();
            int duration = (end - start) / (CLOCKS_PER_SEC / 1000);
            gpioWrite(LED_PIN, 0);
            log_event("Motion ended", duration);
        }

        gpioDelay(POLL_INTERVAL * 1000);
    }

    gpioTerminate();
    return 0;
}

