        fprintf(log, "%s: Duration: %d seconds\n", asctime(tm_info), duration);
    }
    fclose(log);
}

void signal_handler(int sig) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    gpioSetMode(PIR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        if (gpioRead(PIR_PIN) == 1) {
            gpioWrite(LED_PIN, 1);
            log_event("Motion detected", -1);

            clock_t start = clock();
            while (gpioRead(PIR_PIN) == 1 && running) {
                gpioDelay(POLL_INTERVAL * 1000);
            }

            clock_t end = clock();
            int duration = (end - start) / (CLOCKS_PER_SEC / 1000);
            gpioWrite(LED_PIN, 0);
            log_event("Motion ended", duration);
        }

        gpioDelay(POLL_INTERVAL * 1000);
    }

    gpioTerminate();
    return 0;
}
```

This C program uses the pigpio library to monitor a PIR motion sensor on GPIO 4 and control a relay-controlled 12V LED floodlight on GPIO 17. It logs every activation and deactivation event with timestamps and durations to `security_log.txt`. The program handles signals to ensure a clean exit and turns off the floodlight on every exit path. It polls at a 100 ms interval to avoid busy-waiting.

