static void handle_client(int client_fd) {
    char buffer[1024];
    int bytes_read;
    while ((bytes_read = read(client_fd, buffer, sizeof(buffer) - 1)) > 0) {
        buffer[bytes_read] = '\0';
        char *command = strtok(buffer, " ");
        if (command) {
            if (strcmp(command, "SERVO") == 0) {
                int angle = atoi(strtok(NULL, " "));
                set_servo_angle(angle);
                log_message("Command: SERVO %d\n", angle);
            } else if (strcmp(command, "PIR") == 0) {
                int pir_state = gpiod_line_get_value(line_pir);
                char response[32];
                snprintf(response, sizeof(response), "PIR:%d\n", pir_state);
                write(client_fd, response, strlen(response));
                log_message("Command: PIR, Response: %s", response);
            } else {
                log_message("Unknown command: %s\n", command);
            }
        }
    }
    close(client_fd);
}

int main() {
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    openlog("servo_control", LOG_PID, LOG_USER);
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        log_message("Failed to open log file: %s\n", strerror(errno));
        exit(1);
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        log_message("Failed to open GPIO chip: %s\n", strerror(errno));
        exit(1);
    }

    line_servo = gpiod_chip_get_line(chip, GPIO_SERVO);
    if (!line_servo) {
        log_message("Failed to get servo line: %s\n", strerror(errno));
        exit(1);
    }

    line_pir = gpiod_chip_get_line(chip, GPIO_PIR);
    if (!line_pir) {
        log_message("Failed to get PIR line: %s\n", strerror(errno));
        exit(1);
    }

    if (gpiod_line_request_output(line_servo, "servo_control", 0) < 0) {
        log_message("Failed to request servo line output: %s\n", strerror(errno));
        exit(1);
    }

    if (gpiod_line_request_input(line_pir, "pir_control") < 0) {
        log_message("Failed to request PIR line input: %s\n", strerror(errno));
        exit(1);
    }

    pthread_t servo_tid;
    if (pthread_create(&servo_tid, NULL, servo_thread, NULL) != 0) {
        log_message("Failed to create servo thread: %s\n", strerror(errno));
        exit(1);
    }

    int server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        log_message("Failed to create socket: %s\n", strerror(errno));
        exit(1);
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(SOCKET_PORT);

    if (bind(server_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        log_message("Failed to bind socket: %s\n", strerror(errno));
        exit(1);
    }

    if (listen(server_fd, 5) < 0) {
        log_message("Failed to listen on socket: %s\n", strerror(errno));
        exit(1);
    }

    log_message("Server started on port %d\n", SOCKET_PORT);

    while (1) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd < 0) {
            log_message("Failed to accept connection: %s\n", strerror(errno));
            continue;
        }
        log_message("Client connected: %s:%d\n", inet_ntoa(client_addr.sin_addr), ntohs(client_addr.sin_port));
        handle_client(client_fd);
    }

    pthread_join(servo_tid, NULL);
    cleanup();
    closelog();
    return 0;
}
