#define BH1750_I2C_ADDR 0x23
#define BH1750_CMD 0x20
#define RELAY_PIN 23
#define LOG_FILE "grow_log.txt"
#define SAMPLE_INTERVAL 2000000 // 2 seconds in microseconds
#define I2C_BUS 1
#define I2C_SDA 2
#define I2C_SCL 3

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    int i2c_handle, log_fd;
    uint16_t lux;
    char log_entry[100];
    struct timespec ts;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if ((i2c_handle = i2cOpen(I2C_BUS, I2C_SDA, I2C_SCL)) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set relay pin mode\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if ((log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644)) < 0) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        if (i2cWriteByte(i2c_handle, BH1750_CMD) < 0) {
            fprintf(stderr, "Failed to send command to BH1750\n");
            // Retry on next cycle
        } else {
            if (nanosleep(&ts, NULL) < 0) {
                fprintf(stderr, "Failed to sleep\n");
                // Retry on next cycle
            } else {
                uint8_t data[2];
                if (i2cReadDevice(i2c_handle, data, 2) < 0) {
                    fprintf(stderr, "Failed to read from BH1750\n");
                    // Retry on next cycle
                } else {
                    lux = (data[0] << 8) | data[1];
                    lux = lux / 1.2;

                    if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
                        fprintf(stderr, "Failed to get timestamp\n");
                    } else {
                        snprintf(log_entry, sizeof(log_entry), "%ld.%09ld, %u lux\n", ts.tv_sec, ts.tv_nsec, lux);
                        if (write(log_fd, log_entry, strlen(log_entry)) < 0) {
                            fprintf(stderr, "Failed to write to log file\n");
                        }
                    }

                    if (lux < 150) {
                        gpioWrite(RELAY_PIN, PI_HIGH);
                    } else {
                        gpioWrite(RELAY_PIN, PI_LOW);
                    }
                }
            }
        }

        if (nanosleep(&ts, NULL) < 0) {
            fprintf(stderr, "Failed to sleep\n");
        }
    }

    close(log_fd);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

