#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <libgpiod.h>

#define DOUT_PIN 23
#define SCK_PIN 24
#define LOCK_PIN 25
#define TARE_READINGS 10
#define MEASUREMENT_READINGS 5
#define DEFAULT_THRESHOLD 1000
#define DEFAULT_SCALE 1
#define DEFAULT_DURATION 60000
#define TIMEOUT 1000000 // 1 second in microseconds
#define RETRY_COUNT 3
#define CLOCK_PULSE_DELAY 10 // 10 microseconds

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int read_hx711(struct gpiod_chip *chip, int dout_pin, int sck_pin) {
    struct gpiod_line *dout_line = gpiod_chip_get_line(chip, dout_pin);
    struct gpiod_line *sck_line = gpiod_chip_get_line(chip, sck_pin);
    int value, result = 0;

    if (!dout_line || !sck_line) {
        syslog(LOG_ERR, "Failed to get GPIO line");
        return -1;
    }

    if (gpiod_line_request_input(dout_line, "hx711_dout")) {
        syslog(LOG_ERR, "Failed to request DOUT line");
        return -1;
    }

    if (gpiod_line_request_output(sck_line, "hx711_sck", 0)) {
        syslog(LOG_ERR, "Failed to request SCK line");
        gpiod_line_release(dout_line);
        return -1;
    }

    for (int i = 0; i < 24; i++) {
        gpiod_line_set_value(sck_line, 1);
        usleep(CLOCK_PULSE_DELAY);
        value = gpiod_line_get_value(dout_line);
        gpiod_line_set_value(sck_line, 0);
        usleep(CLOCK_PULSE_DELAY);
        result = (result << 1) | value;
    }

    gpiod_line_set_value(sck_line, 1);
    usleep(CLOCK_PULSE_DELAY);
    gpiod_line_set_value(sck_line, 0);
    usleep(CLOCK_PULSE_DELAY);

    gpiod_line_release(dout_line);
    gpiod_line_release(sck_line);

    return result;
}

int main(int argc, char *argv[]) {
    struct gpiod_chip *chip;
    int threshold = DEFAULT_THRESHOLD, scale = DEFAULT_SCALE, duration = DEFAULT_DURATION;
    int tare_offset = 0, weight = 0, raw_value = 0;
    int opt;
    struct timespec start, end;
    double elapsed_time;

    while ((opt = getopt(argc, argv, "t:s:d:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atoi(optarg);
                break;
            case 's':
                scale = atoi(optarg);
                break;
            case 'd':
                duration = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t <threshold>] [-s <scale>] [-d <duration>]\n", argv[0]);
                return 1;
        }
    }

    if (duration <= 0) {
        fprintf(stderr, "Duration must be greater than 0\n");
        return 1;
    }

    if (threshold <= 0) {
        fprintf(stderr, "Threshold must be greater than 0\n");
        return 1;
    }

    if (scale <= 0) {
        fprintf(stderr, "Scale must be greater than 0\n");
        return 1;
    }

    openlog("hx711_weight", LOG_PID, LOG_USER);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        closelog();
        return 1;
    }

    struct gpiod_line *lock_line = gpiod_chip_get_line(chip, LOCK_PIN);
    if (!lock_line) {
        syslog(LOG_ERR, "Failed to get GPIO line for lock");
        gpiod_chip_close(chip);
        closelog();
        return 1;
    }

    if (gpiod_line_request_output(lock_line, "hx711_lock", 0)) {
        syslog(LOG_ERR, "Failed to request lock line");
        gpiod_chip_close(chip);
        closelog();
        return 1;
    }

    for (int i = 0; i < TARE_READINGS; i++) {
        raw_value = read_hx711(chip, DOUT_PIN, SCK_PIN);
        if (raw_value < 0) {
            syslog(LOG_ERR, "Failed to read HX711");
            gpiod_line_release(lock_line);
            gpiod_chip_close(chip);
            closelog();
            return 1;
        }
        tare_offset += raw_value;
    }

    tare_offset /= TARE_READINGS;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    clock_gettime(CLOCK_MONOTONIC, &start);

    while (running) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        elapsed_time = (end.tv_sec - start.tv_sec) * 1000.0 + (end.tv_nsec - start.tv_nsec) / 1000000.0;

        if (elapsed_time >= duration) {
            break;
        }

        raw_value = 0;
        for (int i = 0; i < MEASUREMENT_READINGS; i++) {
            raw_value = read_hx711(chip, DOUT_PIN, SCK_PIN);
            if (raw_value < 0) {
                syslog(LOG_ERR, "Failed to read HX711");
                continue;
            }
            weight += raw_value;
        }

        weight /= MEASUREMENT_READINGS;

        if (weight > threshold) {
            gpiod_line_set_value(lock_line, 1);
            usleep(200000); // 200 ms
            gpiod_line_set_value(lock_line, 0);
        } else {
            gpiod_line_set_value(lock_line, 0);
        }

        weight = (weight - tare_offset) / scale;
        syslog(LOG_INFO, "Weight: %d grams", weight);

        usleep(500000); // 500 ms
    }

    gpiod_line_release(lock_line);
    gpiod_chip_close(chip);
    closelog();

    return 0;
}

