#include <mosquitto.h>

#define RELAY_PIN 17
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_TOPIC "home/lights/control"
#define KEEPALIVE 60
#define RETRY_DELAY 5

static struct mosquitto *mosq = NULL;
static int running = 1;

void signal_handler(int signum) {
    running = 0;
}

void log_event(const char *event, const char *message) {
    syslog(LOG_USER, "%s: %s", event, message);
}

void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *msg) {
    if (msg->payloadlen == 0 || (msg->payloadlen != 2 && (msg->payload[0] != 'O' || msg->payload[1] != 'N' || msg->payload[0] != 'F' || msg->payload[1] != 'F'))) {
        log_event("ERROR", "Invalid message payload");
        return;
    }

    int relay_state = (msg->payload[0] == 'O' && msg->payload[1] == 'N') ? PI_HIGH : PI_LOW;
    if (gpioWrite(RELAY_PIN, relay_state) != 0) {
        log_event("ERROR", "Failed to set relay state");
    } else {
        log_event("INFO", msg->payload);
    }
}

void connect_callback(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        log_event("INFO", "Connected to MQTT broker");
        if (mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0) != MOSQ_ERR_SUCCESS) {
            log_event("ERROR", "Failed to subscribe to topic");
        }
