#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <stdatomic.h>

#define MOTOR_A_PWM 17
#define MOTOR_A_DIR 18
#define MOTOR_B_PWM 22
#define MOTOR_B_DIR 23
#define ENCODER_A_A 4
#define ENCODER_A_B 5
#define ENCODER_B_A 6
#define ENCODER_B_B 12
#define PWM_FREQ 10000
#define CONTROL_PERIOD 100000  // 100 ms
#define TARGET_RPM 50
#define Kp 0.5
#define Ki 0.05
#define PWM_MAX 255
#define STALL_TIMEOUT 2000000  // 2 seconds

atomic_int encoder_A_count = 0;
atomic_int encoder_B_count = 0;
volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
}

void encoder_ISR(int gpio, int level, uint32_t tick) {
    if (gpio == ENCODER_A_A) {
        if (gpioRead(ENCODER_A_B) == level) {
            atomic_fetch_add(&encoder_A_count, 1);
        } else {
            atomic_fetch_sub(&encoder_A_count, 1);
        }
    } else if (gpio == ENCODER_B_A) {
        if (gpioRead(ENCODER_B_B) == level) {
            atomic_fetch_add(&encoder_B_count, 1);
        } else {
            atomic_fetch_sub(&encoder_B_count, 1);
        }
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    gpioSetMode(MOTOR_A_PWM, PI_OUTPUT);
    gpioSetMode(MOTOR_A_DIR, PI_OUTPUT);
    gpioSetMode(MOTOR_B_PWM, PI_OUTPUT);
    gpioSetMode(MOTOR_B_DIR, PI_OUTPUT);
    gpioSetMode(ENCODER_A_A, PI_INPUT);
    gpioSetMode(ENCODER_A_B, PI_INPUT);
    gpioSetMode(ENCODER_B_A, PI_INPUT);
    gpioSetMode(ENCODER_B_B, PI_INPUT);

    gpioSetPWMfrequency(MOTOR_A_PWM, PWM_FREQ);
    gpioSetPWMfrequency(MOTOR_B_PWM, PWM_FREQ);

    gpioSetPullUpDown(ENCODER_A_A, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER_A_B, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER_B_A, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER_B_B, PI_PUD_UP);

    gpioSetAlertFunc(ENCODER_A_A, encoder_ISR);
    gpioSetAlertFunc(ENCODER_A_B, encoder_ISR);
    gpioSetAlertFunc(ENCODER_B_A, encoder_ISR);
    gpioSetAlertFunc(ENCODER_B_B, encoder_ISR);

    signal(SIGINT, signal_handler);

    int64_t last_time = gpioTick();
    double integral_A = 0, integral_B = 0;
    int last_encoder_A_count = 0, last_encoder_B_count = 0;

    while (running) {
        int64_t current_time = gpioTick();
        int64_t dt = current_time - last_time;

        if (dt >= CONTROL_PERIOD) {
            int encoder_A_diff = atomic_load(&encoder_A_count) - last_encoder_A_count;
            int encoder_B_diff = atomic_load(&encoder_B_count) - last_encoder_B_count;

            double actual_rpm_A = (encoder_A_diff * 60.0) / (dt * 64.0);
            double actual_rpm_B = (encoder_B_diff * 60.0) / (dt * 64.0);

            double error_A = TARGET_RPM - actual_rpm_A;
            double error_B = TARGET_RPM - actual_rpm_B;

            integral_A += error_A * dt;
            integral_B += error_B * dt;

            double output_A = Kp * error_A + Ki * integral_A;
            double output_B = Kp * error_B + Ki * integral_B;

            if (output_A > PWM_MAX) output_A = PWM_MAX;
            if (output_A < 0) output_A = 0;
            if (output_B > PWM_MAX) output_B = PWM_MAX;
            if (output_B < 0) output_B = 0;

            gpioWrite(MOTOR_A_DIR, output_A > 0);
            gpioWrite(MOTOR_B_DIR, output_B > 0);
            gpioSetPWMrange(MOTOR_A_PWM, PWM_MAX);
            gpioSetPWMrange(MOTOR_B_PWM, PWM_MAX);
            gpioSetPWMdutycycle(MOTOR_A_PWM, (int)output_A);
            gpioSetPWMdutycycle(MOTOR_B_PWM, (int)output_B);

            printf("Motor A: RPM=%.2f, PWM=%.0f\n", actual_rpm_A, output_A);
            printf("Motor B: RPM=%.2f, PWM=%.0f\n", actual_rpm_B, output_B);

            last_encoder_A_count = atomic_load(&encoder_A_count);
            last_encoder_B_count = atomic_load(&encoder_B_count);
            last_time = current_time;
        }
    }

    gpioTerminate();
    return 0;
}

