#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pigpio.h>
#include <signal.h>

#define RELAY_PIN 17
#define BH1750_I2C_ADDRESS 0x23
#define BH1750_CMD 0x21
#define BH1750_DELAY 180
#define LUX_THRESHOLD_LOW 50
#define LUX_THRESHOLD_HIGH 200
#define LOG_FILE "chicken_coop_log.txt"

int i2c_handle;
FILE *log_file;

void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d: %s\n", tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday, tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec, message);
    fflush(log_file);
}

void cleanup() {
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

void signal_handler(int sig) {
    cleanup();
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if ((i2c_handle = i2cOpen(1, BH1750_I2C_ADDRESS, 0)) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int relay_state = 0;
    int last_relay_state = 0;
    int lux = 0;

    while (1) {
        if (i2cWriteByte(i2c_handle, BH1750_CMD) < 0) {
            fprintf(stderr, "Failed to send command to BH1750 sensor\n");
            gpioTerminate();
            fclose(log_file);
            i2cClose(i2c_handle);
            return 1;
        }

        gpioDelay(BH1750_DELAY);

        uint8_t data[2];
        if (i2cReadDevice(i2c_handle, data, 2) < 0) {
            fprintf(stderr, "Failed to read data from BH1750 sensor\n");
            gpioTerminate();
            fclose(log_file);
            i2cClose(i2c_handle);
            return 1;
        }

        lux = (data[0] << 8) | data[1];
        lux /= 1.2;

        if (lux < LUX_THRESHOLD_LOW && !relay_state) {
            relay_state = 1;
            gpioWrite(RELAY_PIN, 1);
            log_event("Relay ON");
        } else if (lux > LUX_THRESHOLD_HIGH && relay_state) {
            relay_state = 0;
            gpioWrite(RELAY_PIN, 0);
            log_event("Relay OFF");
        }

        if (relay_state != last_relay_state) {
            last_relay_state = relay_state;
        }

        gpioDelay(5000000); // 5 seconds
    }

    cleanup();
    return 0;
}

