#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pigpio.h>
#include <signal.h>

#define RELAY_PIN 17
#define TOUCH_PIN 4
#define DEBOUNCE_DELAY 50
#define MAIN_LOOP_DELAY 10

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioSetMode(TOUCH_PIN, PI_INPUT);

    if (gpioSetPullUpDown(TOUCH_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up on touch pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    int relay_state = 0;
    int last_touch_state = 0;
    int current_touch_state = 0;

    while (running) {
        current_touch_state = gpioRead(TOUCH_PIN);

        if (current_touch_state != last_touch_state) {
            gpioDelay(DEBOUNCE_DELAY * 1000); // 50 ms debounce delay

            if (gpioRead(TOUCH_PIN) == current_touch_state) {
                if (current_touch_state == 0) { // Touch released
                    relay_state = !relay_state;
                    gpioWrite(RELAY_PIN, relay_state);

                    time_t now = time(NULL);
                    struct tm *tm_info = localtime(&now);
                    char timestamp[20];
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

                    printf("%s - Relay state changed to %s\n", timestamp, relay_state ? "ON" : "OFF");
                }
            }
        }

        last_touch_state = current_touch_state;
        gpioDelay(MAIN_LOOP_DELAY * 1000); // 10 ms sleep
    }

    gpioWrite(RELAY_PIN, 0); // Ensure relay is off on exit
    gpioTerminate();

    printf("Program terminated gracefully\n");

    return EXIT_SUCCESS;
}

