#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <pthread.h>

#define FLOW_SENSOR_PIN 17
#define SOLENOID_PIN 27
#define PULSES_PER_LITRE 450.0
#define LPM_HIGH_THRESHOLD 5.0
#define LPM_LOW_THRESHOLD 4.5
#define DEBOUNCE_TIMEOUT 1000

volatile int pulse_count = 0;
pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
FILE *log_file = NULL;
int solenoid_state = 1; // 1 for open, 0 for closed

void log_event(const char *message) {
    if (log_file) {
        time_t now = time(NULL);
        fprintf(log_file, "%s: %s\n", ctime(&now), message);
        fflush(log_file);
    }
}

void solenoid_control(int state) {
    if (gpioWrite(SOLENOID_PIN, state) != PI_OK) {
        log_event("Failed to control solenoid");
    }
    solenoid_state = state;
}

void *flow_sensor_isr(void *arg) {
    int gpio = (int)arg;
    if (gpioRead(gpio) == 1) {
        pthread_mutex_lock(&pulse_mutex);
        pulse_count++;
        pthread_mutex_unlock(&pulse_mutex);
    }
    return NULL;
}

void handle_signal(int sig) {
    log_event("Received signal, shutting down");
    solenoid_control(1);
    if (log_file) {
        fclose(log_file);
    }
    pthread_mutex_destroy(&pulse_mutex);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        log_event("Failed to initialize pigpio");
        return 1;
    }

    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) != PI_OK) {
        log_event("Failed to set flow sensor pin mode");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) != PI_OK) {
        log_event("Failed to set solenoid pin mode");
        gpioTerminate();
        return 1;
    }

    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, DEBOUNCE_TIMEOUT, flow_sensor_isr, (void *)FLOW_SENSOR_PIN) != 0) {
        log_event("Failed to set flow sensor ISR");
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(SOLENOID_PIN, 1) != PI_OK) {
        log_event("Failed to initialize solenoid state");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    log_file = fopen("water_flow.log", "a");
    if (!log_file) {
        log_event("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    while (1) {
        sleep(1);

        pthread_mutex_lock(&pulse_mutex);
        int current_count = pulse_count;
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        double lpm = (current_count / PULSES_PER_LITRE) * 60.0;

        if (lpm > LPM_HIGH_THRESHOLD) {
            solenoid_control(0);
        } else if (lpm < LPM_LOW_THRESHOLD) {
            solenoid_control(1);
        }

        log_event(f"Flow rate: %.2f LPM, Solenoid: %s\n", lpm, solenoid_state ? "Open" : "Closed");
    }

    return 0;
}

