#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <json-c/json.h>

#define HX711_DATA 23
#define HX711_SCK 24
#define SERVO_PIN 18
#define DEFAULT_CALIBRATION_FACTOR 1.0
#define DEFAULT_SERVER_IP "127.0.0.1"
#define DEFAULT_SERVER_PORT 12345
#define MAX_LOG_SIZE 1024

typedef struct {
    double calibration_factor;
    char server_ip[16];
    int server_port;
} Config;

Config config = {
    .calibration_factor = DEFAULT_CALIBRATION_FACTOR,
    .server_ip = DEFAULT_SERVER_IP,
    .server_port = DEFAULT_SERVER_PORT
};

void load_config(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        return;
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "=");
        if (key && value) {
            if (strcmp(key, "calibration_factor") == 0) {
                config.calibration_factor = atof(value);
            } else if (strcmp(key, "server_ip") == 0) {
                strncpy(config.server_ip, value, sizeof(config.server_ip) - 1);
            } else if (strcmp(key, "server_port") == 0) {
                config.server_port = atoi(value);
            }
        }
    }

    fclose(file);
}

void log_event(const char *message) {
    FILE *file = fopen("dispensing_log.json", "a");
    if (!file) {
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    json_object *root = json_object_new_object();
    json_object_object_add(root, "timestamp", json_object_new_string(timestamp));
    json_object_object_add(root, "message", json_object_new_string(message));

    char *json_str = json_object_to_json_string(root);
    fprintf(file, "%s\n", json_str);
    json_object_put(root);
    fclose(file);
}

int read_hx711(double *value) {
    int data = 0;
    int count = 0;
    while (gpioRead(HX711_DATA) == 1) {
        if (count++ > 1000) {
            return -1;
        }
        gpioDelay(1);
    }

    gpioWrite(HX711_SCK, 0);
    for (int i = 0; i < 24; i++) {
        gpioDelay(1);
        gpioWrite(HX711_SCK, 1);
        gpioDelay(1);
        data = (data << 1) | gpioRead(HX711_DATA);
        gpioWrite(HX711_SCK, 0);
    }

    gpioWrite(HX711_SCK, 1);
    gpioDelay(1);
    gpioWrite(HX711_SCK, 0);

    *value = (data & 0x7fffff) * config.calibration_factor;
    return 0;
}

void control_servo(int angle) {
    int pulse_width = 1000 + (angle * 10);
    gpioSetServoPulsewidth(SERVO_PIN, pulse_width);
}

void signal_handler(int signum) {
    gpioTerminate();
    exit(signum);
}

int main() {
    if (pigpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    load_config("config.ini");

    gpioSetMode(HX711_DATA, PI_INPUT);
    gpioSetMode(HX711_SCK, PI_OUTPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    int server_fd, new_socket;
    struct sockaddr_in address;
    int addrlen = sizeof(address);

    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        gpioTerminate();
        return 1;
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(config.server_port);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(server_fd);
        gpioTerminate();
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        perror("listen");
        close(server_fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("accept");
            continue;
        }

        double target_weight;
        if (recv(new_socket, &target_weight, sizeof(target_weight), 0) <= 0) {
            close(new_socket);
            continue;
        }

        control_servo(100); // Open servo
        gpioDelay(1000000); // Wait 1 second

        double actual_weight;
        if (read_hx711(&actual_weight) < 0) {
            log_event("HX711 read timeout");
            close(new_socket);
            continue;
        }

        control_servo(0); // Close servo

        char response[256];
        snprintf(response, sizeof(response), "Actual weight: %.2f grams\n", actual_weight);
        send(new_socket, response, strlen(response), 0);

        char log_message[256];
        snprintf(log_message, sizeof(log_message), "Target weight: %.2f grams, Actual weight: %.2f grams", target_weight, actual_weight);
        log_event(log_message);

        close(new_socket);
    }

    close(server_fd);
    gpioTerminate();
    return 0;
}

