        gpioTerminate();
        return 1;
    }

    while (1) {
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("accept");
            continue;
        }

        double target_weight;
        if (recv(new_socket, &target_weight, sizeof(target_weight), 0) <= 0) {
            close(new_socket);
            continue;
        }

        control_servo(100); // Open servo
        gpioDelay(1000000); // Wait 1 second

        double actual_weight;
        if (read_hx711(&actual_weight) < 0) {
            log_event("HX711 read timeout");
            close(new_socket);
            continue;
        }

        control_servo(0); // Close servo

        char response[256];
        snprintf(response, sizeof(response), "Actual weight: %.2f grams\n", actual_weight);
        send(new_socket, response, strlen(response), 0);

        char log_message[256];
        snprintf(log_message, sizeof(log_message), "Target weight: %.2f grams, Actual weight: %.2f grams", target_weight, actual_weight);
        log_event(log_message);

        close(new_socket);
    }

    close(server_fd);
    gpioTerminate();
    return 0;
}
