#include <signal.h>
#include <pigpio.h>

#define RELAY_PIN 17
#define TOUCH_PIN 4
#define DEBOUNCE_TIME 50

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

void log_state(int state) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    printf("%04d-%02d-%02d %02d:%02d:%02d Relay: %s\n",
           tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
           tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec,
           state ? "ON" : "OFF");
}

int main(int argc, char *argv[]) {
    int debounce_time = DEBOUNCE_TIME;
    if (argc > 1 && strcmp(argv[1], "-d") == 0 && argc > 2) {
        debounce_time = atoi(argv[2]);
        if (debounce_time <= 0) {
            fprintf(stderr, "Invalid debounce time: %s\n", argv[2]);
            return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioSetMode(TOUCH_PIN, PI_INPUT);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int last_state = gpioRead(TOUCH_PIN);
    int current_state = last_state;
    int last_change_time = gpioTick();

    while (running) {
        current_state = gpioRead(TOUCH_PIN);
        int current_time = gpioTick();

        if (current_state != last_state) {
            if (current_time - last_change_time > debounce_time * 1000) {
                if (current_state == 1) {
                    gpioWrite(RELAY_PIN, !gpioRead(RELAY_PIN));
                    log_state(gpioRead(RELAY_PIN));
                }
                last_state = current_state;
                last_change_time = current_time;
            }
        }

        gpioDelay(1000);
    }

    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    return 0;
}

