#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <termios.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define PWM_FREQ 50
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define STEP_ANGLE 10
#define DEFAULT_ANGLE 90

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void restore_terminal_settings(struct termios *old_termios) {
    tcsetattr(STDIN_FILENO, TCSANOW, old_termios);
}

int main() {
    struct termios old_termios, new_termios;
    int angle = DEFAULT_ANGLE;
    int pulse_width = (angle - MIN_ANGLE) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) / (MAX_ANGLE - MIN_ANGLE) + MIN_PULSE_WIDTH;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio library\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(GPIO_PIN, PWM_FREQ);
    gpioServo(GPIO_PIN, pulse_width);

    if (tcgetattr(STDIN_FILENO, &old_termios) != 0) {
        fprintf(stderr, "Failed to get terminal attributes\n");
        gpioTerminate();
        return 1;
    }

    new_termios = old_termios;
    new_termios.c_lflag &= ~(ICANON | ECHO);
    if (tcsetattr(STDIN_FILENO, TCSANOW, &new_termios) != 0) {
        fprintf(stderr, "Failed to set terminal attributes\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (running) {
        if (kbhit()) {
            char ch = getchar();
            if (ch == '+') {
                angle += STEP_ANGLE;
                if (angle > MAX_ANGLE) angle = MAX_ANGLE;
            } else if (ch == '-') {
                angle -= STEP_ANGLE;
                if (angle < MIN_ANGLE) angle = MIN_ANGLE;
            } else if (ch == 'q') {
                running = 0;
            }
            pulse_width = (angle - MIN_ANGLE) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) / (MAX_ANGLE - MIN_ANGLE) + MIN_PULSE_WIDTH;
            gpioServo(GPIO_PIN, pulse_width);
            printf("Current angle: %d°\n", angle);
        }
    }

    gpioServo(GPIO_PIN, 0);
    gpioTerminate();
    restore_terminal_settings(&old_termios);

    return 0;
}

