#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define DEBOUNCE_US 2000
#define LOG_FILE "motor_rpm.log"
#define SAMPLE_INTERVAL_S 5

volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_request_config config;
    struct gpiod_line_event event;
    struct timespec start_time, current_time, elapsed_time;
    int pulse_count = 0;
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s\n", GPIO_CHIP);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d\n", GPIO_LINE);
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    memset(&config, 0, sizeof(config));
    config.consumer = "motor_rpm_monitor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    config.flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP;

    if (gpiod_line_request(line, &config)) {
        fprintf(stderr, "Failed to request GPIO line %d\n", GPIO_LINE);
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (running) {
        if (gpiod_line_event_wait(line, DEBOUNCE_US)) {
            if (gpiod_line_event_read(line, &event)) {
                if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
                    pulse_count++;
                }
            }
        }

        clock_gettime(CLOCK_MONOTONIC, &current_time);
        timersub(&current_time, &start_time, &elapsed_time);
        if (elapsed_time.tv_sec >= SAMPLE_INTERVAL_S) {
            double rpm = (pulse_count / elapsed_time.tv_sec) * 60.0;
            printf("Current RPM: %.2f\n", rpm);

            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

            fprintf(log_file, "%s,%.2f\n", timestamp, rpm);
            fflush(log_file);

            start_time = current_time;
            pulse_count = 0;
        }
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(log_file);

    return EXIT_SUCCESS;
}

