#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define RELAY_PIN 17
#define TOUCH_PIN 4
#define TOUCH_DEBOUNCE_TIME 50
#define TOUCH_TIMEOUT 10

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio library\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioSetMode(TOUCH_PIN, PI_INPUT);

    if (gpioRead(TOUCH_PIN) == PI_BAD_GPIO) {
        fprintf(stderr, "Invalid GPIO pin number for touch sensor\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetPullUpDown(TOUCH_PIN, PI_PUD_UP);

    time_t last_touch_time = 0;
    int relay_state = 0;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!stop_flag) {
        int touch_state = gpioRead(TOUCH_PIN);
        if (touch_state == PI_BAD_GPIO) {
            fprintf(stderr, "Error reading touch sensor GPIO\n");
            break;
        }

        if (touch_state == 0) {
            last_touch_time = time(NULL);
            relay_state = !relay_state;
            gpioWrite(RELAY_PIN, relay_state);
        } else {
            if (time(NULL) - last_touch_time > TOUCH_TIMEOUT) {
                relay_state = 0;
                gpioWrite(RELAY_PIN, relay_state);
            }
        }

        gpioDelay(TOUCH_DEBOUNCE_TIME * 1000);
    }

    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

