#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define LOCK1_PIN 17
#define LOCK2_PIN 27
#define BUTTON_PIN 22
#define RFID_SPI_CHANNEL 0
#define RFID_SPI_SPEED 100000
#define RFID_TAG_LENGTH 10
#define RFID_VALID_TAG {0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A}
#define DEBOUNCE_TIME 50000

FILE *log_file = NULL;

void log_access(const char *message) {
    if (log_file) {
        time_t now = time(NULL);
        char *timestamp = ctime(&now);
        timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file);
    }
}

void handle_signal(int sig) {
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int read_rfid_tag(uint8_t *tag) {
    int handle = spiOpen(RFID_SPI_CHANNEL, RFID_SPI_SPEED, 0);
    if (handle < 0) {
        log_access("Failed to open RFID SPI channel");
        return -1;
    }

    uint8_t tx[10] = {0};
    uint8_t rx[10];
    int status = spiXfer(handle, tx, rx, 10);
    spiClose(handle);

    if (status < 0) {
        log_access("RFID SPI read failed");
        return -1;
    }

    if (memcmp(rx, RFID_VALID_TAG, RFID_TAG_LENGTH) == 0) {
        memcpy(tag, rx, RFID_TAG_LENGTH);
        return 0;
    } else {
        return -1;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        log_access("Failed to initialise GPIO");
        return 1;
    }

    if (gpioSetMode(LOCK1_PIN, PI_OUTPUT) < 0 || gpioSetMode(LOCK2_PIN, PI_OUTPUT) < 0) {
        log_access("Failed to set GPIO mode for locks");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(BUTTON_PIN, PI_INPUT) < 0) {
        log_access("Failed to set GPIO mode for button");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP) < 0) {
        log_access("Failed to set pull-up for button");
        gpioTerminate();
        return 1;
    }

    log_file = fopen("/var/log/door_access.log", "a");
    if (!log_file) {
        log_access("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    uint8_t rfid_tag[RFID_TAG_LENGTH];
    int button_pressed = 0;

    while (1) {
        if (gpioRead(BUTTON_PIN) == 0) {
            gpioDelay(DEBOUNCE_TIME);
            if (gpioRead(BUTTON_PIN) == 0) {
                button_pressed = 1;
            }
        }

        if (button_pressed) {
            int rfid_status = read_rfid_tag(rfid_tag);
            if (rfid_status == 0) {
                log_access("Access granted");
                gpioWrite(LOCK1_PIN, 0);
                gpioWrite(LOCK2_PIN, 0);
                gpioDelay(5000000);
                gpioWrite(LOCK1_PIN, 1);
                gpioWrite(LOCK2_PIN, 1);
            } else if (rfid_status == -1) {
                log_access("Invalid RFID tag or read failure");
            } else {
                log_access("No RFID tag present");
            }
            button_pressed = 0;
        }

        gpioDelay(10000);
    }

    return 0;
}

