#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pthread.h>
#include <libgpiod.h>

#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20
#define ENCODER1_A 5
#define ENCODER1_B 6
#define ENCODER2_A 26
#define ENCODER2_B 19
#define PWM_FREQ 100
#define SAMPLE_TIME 100000  // 100 ms in microseconds
#define KP 1.0
#define KI 0.1
#define KD 0.01
#define TARGET_RPM 60
#define PULSES_PER_REV 600

struct Motor {
    struct gpiod_chip *chip;
    struct gpiod_line *ena;
    struct gpiod_line *in1;
    struct gpiod_line *in2;
    pthread_t thread;
    int direction;
    int count;
    int last_count;
    double integral;
    double last_error;
    double output;
};

struct Motor motor1, motor2;
FILE *log_file;
pthread_mutex_t encoder_mutex = PTHREAD_MUTEX_INITIALIZER;

void *encoder_thread(void *arg) {
    struct Motor *motor = (struct Motor *)arg;
    struct gpiod_line_event event;
    int ret;

    while (1) {
        ret = gpiod_line_event_wait(motor->chip, &event, SAMPLE_TIME);
        if (ret < 0) {
            perror("gpiod_line_event_wait");
            break;
        }

        ret = gpiod_line_event_read(motor->chip, &event);
        if (ret < 0) {
            perror("gpiod_line_event_read");
            break;
        }

        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            pthread_mutex_lock(&encoder_mutex);
            motor->count++;
            pthread_mutex_unlock(&encoder_mutex);
        } else if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            pthread_mutex_lock(&encoder_mutex);
            motor->count--;
            pthread_mutex_unlock(&encoder_mutex);
        }
    }

    return NULL;
}

void init_motor(struct Motor *motor, int ena, int in1, int in2) {
    motor->chip = gpiod_chip_open_by_name("gpiochip0");
    if (!motor->chip) {
        perror("gpiod_chip_open_by_name");
        exit(EXIT_FAILURE);
    }

    motor->ena = gpiod_chip_get_line(motor->chip, ena);
    if (!motor->ena) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(motor->chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(motor->ena, "motor_ena", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(motor->chip);
        exit(EXIT_FAILURE);
    }

    motor->in1 = gpiod_chip_get_line(motor->chip, in1);
    if (!motor->in1) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(motor->chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(motor->in1, "motor_in1", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(motor->chip);
        exit(EXIT_FAILURE);
    }

    motor->in2 = gpiod_chip_get_line(motor->chip, in2);
    if (!motor->in2) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(motor->chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(motor->in2, "motor_in2", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(motor->chip);
        exit(EXIT_FAILURE);
    }

    ret = pthread_create(&motor->thread, NULL, encoder_thread, motor);
    if (ret != 0) {
        perror("pthread_create");
        gpiod_chip_close(motor->chip);
        exit(EXIT_FAILURE);
    }
}

void set_motor_speed(struct Motor *motor, double speed) {
    int duty_cycle = (int)(speed * 100);
    if (duty_cycle > 100) {
        duty_cycle = 100;
    } else if (duty_cycle < 0) {
        duty_cycle = 0;
    }

    gpiod_line_set_value(motor->ena, duty_cycle);
}

void pid_control(struct Motor *motor) {
    double error = (TARGET_RPM * PULSES_PER_REV / 60) - motor->count;
    motor->integral += error;
    double derivative = error - motor->last_error;
    motor->output = KP * error + KI * motor->integral + KD * derivative;
    motor->last_error = error;

    if (motor->output > 100) {
        motor->output = 100;
    } else if (motor->output < -100) {
        motor->output = -100;
    }

    set_motor_speed(motor, motor->output);
}

void log_data(struct Motor *motor1, struct Motor *motor2) {
    static int header_written = 0;
    double rpm1 = (motor1->count * 60 * 1000) / (PULSES_PER_REV * SAMPLE_TIME);
    double rpm2 = (motor2->count * 60 * 1000) / (PULSES_PER_REV * SAMPLE_TIME);

    if (!header_written) {
        fprintf(log_file, "Time,RPM1,PID_P1,PID_I1,PID_D1,RPM2,PID_P2,PID_I2,PID_D2\n");
        header_written = 1;
    }

    fprintf(log_file, "%lu,%f,%f,%f,%f,%f,%f,%f,%f\n",
            time(NULL), rpm1, KP * (TARGET_RPM * PULSES_PER_REV / 60 - motor1->count),
            KI * motor1->integral, KD * (motor1->output - motor1->last_error),
            rpm2, KP * (TARGET_RPM * PULSES_PER_REV / 60 - motor2->count),
            KI * motor2->integral, KD * (motor2->output - motor2->last_error));
    fflush(log_file);
}

void signal_handler(int signum) {
    set_motor_speed(&motor1, 0);
    set_motor_speed(&motor2, 0);
    gpiod_line_release(motor1.ena);
    gpiod_line_release(motor1.in1);
    gpiod_line_release(motor1.in2);
    gpiod_chip_close(motor1.chip);
    gpiod_line_release(motor2.ena);
    gpiod_line_release(motor2.in3);
    gpiod_line_release(motor2.in4);
    gpiod_chip_close(motor2.chip);
    fclose(log_file);
    exit(signum);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    log_file = fopen("motor_log.csv", "w");
    if (!log_file) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    init_motor(&motor1, MOTOR1_ENA, MOTOR1_IN1, MOTOR1_IN2);
    init_motor(&motor2, MOTOR2_ENB, MOTOR2_IN3, MOTOR2_IN4);

    while (1) {
        pid_control(&motor1);
        pid_control(&motor2);
        log_data(&motor1, &motor2);
        usleep(SAMPLE_TIME);
    }

    return 0;
}

