#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x5A
#define RELAY_PIN 17
#define MPR121_SOFT_RESET 0x80
#define MPR121_FILTER_CONFIG 0x2B
#define MPR121_TOUCH_THRESHOLD 0x20
#define MPR121_RELEASE_THRESHOLD 0x21
#define MPR121_TOUCH_STATUS_0 0x00
#define MPR121_TOUCH_STATUS_1 0x01
#define MPR121_RUN_MODE 0x8C

void log_relay_state(int state) {
    FILE *log_file = fopen("relay_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    fprintf(log_file, "%s - Relay state: %s\n", ctime(&now), state ? "ON" : "OFF");
    fclose(log_file);
}

void handle_sigint(int sig) {
    gpioWrite(RELAY_PIN, PI_OFF);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int i2c_handle = gpioI2COpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Soft reset
    if (gpioI2CWriteByte(i2c_handle, MPR121_SOFT_RESET) < 0) {
        fprintf(stderr, "Failed to soft reset MPR121\n");
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Filter configuration
    uint8_t filter_config = 0x0B;
    if (gpioI2CWriteByteData(i2c_handle, MPR121_FILTER_CONFIG, filter_config) < 0) {
        fprintf(stderr, "Failed to set filter configuration\n");
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Touch and release thresholds
    for (int i = 0; i < 12; i++) {
        if (gpioI2CWriteByteData(i2c_handle, MPR121_TOUCH_THRESHOLD + i * 2, 0x00) < 0 ||
            gpioI2CWriteByteData(i2c_handle, MPR121_RELEASE_THRESHOLD + i * 2, 0x0B) < 0) {
            fprintf(stderr, "Failed to set touch/release thresholds\n");
            gpioI2CClose(i2c_handle);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    // Run mode
    if (gpioI2CWriteByte(i2c_handle, MPR121_RUN_MODE) < 0) {
        fprintf(stderr, "Failed to set run mode\n");
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    int last_relay_state = 0;
    while (1) {
        uint8_t touch_status[2];
        if (gpioI2CRead(i2c_handle, touch_status, 2) < 0) {
            fprintf(stderr, "Failed to read touch status\n");
            gpioI2CClose(i2c_handle);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        int current_relay_state = (touch_status[0] | touch_status[1]) != 0;
        if (current_relay_state != last_relay_state) {
            gpioWrite(RELAY_PIN, current_relay_state ? PI_ON : PI_OFF);
            log_relay_state(current_relay_state);
            last_relay_state = current_relay_state;
        }

        gpioDelay(50000); // 50 ms
    }

    gpioI2CClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

