#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define RELAY1_LINE 17
#define RELAY2_LINE 18
#define LOG_FILE "valve_log.txt"

static struct gpiod_chip *chip;
static struct gpiod_line *relay1, *relay2;
static FILE *log_file;

void log_event(const char *valve, const char *action) {
    time_t now = time(NULL);
    char *iso_time = ctime(&now);
    iso_time[strlen(iso_time) - 1] = '\0'; // Remove newline character

    fprintf(log_file, "%s: %s %s\n", iso_time, valve, action);
    fflush(log_file);
}

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        if (relay1) gpiod_line_release(relay1);
        if (relay2) gpiod_line_release(relay2);
        if (chip) gpiod_chip_close(chip);
        if (log_file) fclose(log_file);
        exit(0);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    relay1 = gpiod_chip_get_line(chip, RELAY1_LINE);
    if (!relay1) {
        perror("Failed to get relay1 line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    relay2 = gpiod_chip_get_line(chip, RELAY2_LINE);
    if (!relay2) {
        perror("Failed to get relay2 line");
        gpiod_line_release(relay1);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(relay1, "valve1", 0) < 0) {
        perror("Failed to request output for relay1");
        gpiod_line_release(relay1);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(relay2, "valve2", 0) < 0) {
        perror("Failed to request output for relay2");
        gpiod_line_release(relay1);
        gpiod_line_release(relay2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(relay1);
        gpiod_line_release(relay2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        // Activate Valve 1 for 500 ms
        gpiod_line_set_value(relay1, 1);
        log_event("Valve 1", "Opened");
        usleep(500 * 1000);
        gpiod_line_set_value(relay1, 0);
        log_event("Valve 1", "Closed");
        usleep(5 * 1000 * 1000);

        // Activate Valve 2 for 1000 ms
        gpiod_line_set_value(relay2, 1);
        log_event("Valve 2", "Opened");
        usleep(1000 * 1000);
        gpiod_line_set_value(relay2, 0);
        log_event("Valve 2", "Closed");
        usleep(10 * 1000 * 1000);
    }

    // This point should never be reached
    gpiod_line_release(relay1);
    gpiod_line_release(relay2);
    gpiod_chip_close(chip);
    fclose(log_file);
    return EXIT_SUCCESS;
}

