#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x5A
#define RELAY_PIN 17
#define TOUCH_THRESHOLD 0x10
#define RELEASE_THRESHOLD 0x0A
#define FILTER_CHARGE_TIME 0x20
#define ELECTRODE_CURRENT 0x01
#define ELE_EN 0x20
#define STABILIZATION_TIME 100
#define LOOP_DELAY 100

volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set relay pin as output\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Initialize MPR121 in stop mode
    if (i2cWriteByteData(i2c_handle, 0x80, 0x00) < 0) {
        fprintf(stderr, "Failed to initialize MPR121 in stop mode\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set touch threshold and release threshold for all 12 electrodes
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, 0x5A + i * 2, TOUCH_THRESHOLD) < 0 ||
            i2cWriteByteData(i2c_handle, 0x5B + i * 2, RELEASE_THRESHOLD) < 0) {
            fprintf(stderr, "Failed to set touch/release thresholds for electrode %d\n", i);
            i2cClose(i2c_handle);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    // Configure filter/charge time and electrode current
    if (i2cWriteByteData(i2c_handle, 0x20, FILTER_CHARGE_TIME) < 0 ||
        i2cWriteByteData(i2c_handle, 0x01, ELECTRODE_CURRENT) < 0) {
        fprintf(stderr, "Failed to configure filter/charge time and electrode current\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Enter run mode with ELE_EN=1
    if (i2cWriteByteData(i2c_handle, 0x20, ELE_EN) < 0) {
        fprintf(stderr, "Failed to enter run mode\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Wait for stabilization
    gpioDelay(STABILIZATION_TIME * 1000);

    // Set relay pin initially off
    gpioWrite(RELAY_PIN, 0);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        uint8_t touch_status;
        if (i2cReadByteData(i2c_handle, 0x00, &touch_status) < 0) {
            fprintf(stderr, "Failed to read touch status\n");
            break;
        }

        if (touch_status > 0) {
            gpioWrite(RELAY_PIN, !gpioRead(RELAY_PIN));
            printf("Relay toggled: %s\n", gpioRead(RELAY_PIN) ? "ON" : "OFF");
        }

        gpioDelay(LOOP_DELAY * 1000);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

