    // Set touch threshold and release threshold for all 12 electrodes
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, 0x5A + i * 2, TOUCH_THRESHOLD) < 0 ||
            i2cWriteByteData(i2c_handle, 0x5B + i * 2, RELEASE_THRESHOLD) < 0) {
            fprintf(stderr, "Failed to set touch/release thresholds for electrode %d\n", i);
            i2cClose(i2c_handle);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    // Configure filter/charge time and electrode current
    if (i2cWriteByteData(i2c_handle, 0x20, FILTER_CHARGE_TIME) < 0 ||
        i2cWriteByteData(i2c_handle, 0x01, ELECTRODE_CURRENT) < 0) {
        fprintf(stderr, "Failed to configure filter/charge time and electrode current\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Enter run mode with ELE_EN=1
    if (i2cWriteByteData(i2c_handle, 0x20, ELE_EN) < 0) {
        fprintf(stderr, "Failed to enter run mode\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Wait for stabilization
    gpioDelay(STABILIZATION_TIME * 1000);

    // Set relay pin initially off
    gpioWrite(RELAY_PIN, 0);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        uint8_t touch_status;
        if (i2cReadByteData(i2c_handle, 0x00, &touch_status) < 0) {
            fprintf(stderr, "Failed to read touch status\n");
            break;
        }

        if (touch_status > 0) {
            gpioWrite(RELAY_PIN, !gpioRead(RELAY_PIN));
            printf("Relay toggled: %s\n", gpioRead(RELAY_PIN) ? "ON" : "OFF");
        }

        gpioDelay(LOOP_DELAY * 1000);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}
