        fprintf(log_file, "%ld.%03ld %s\n", ts.tv_sec, ts.tv_nsec / 1000000, event);
        fflush(log_file);
    }
}

void gpio_callback(int gpio, int level, uint32_t tick) {
    if (gpio == PIR_PIN && level == PI_RISING_EDGE) {
        motion_detected = 1;
        log_event("Motion detected");
    }
}

void signal_handler(int sig) {
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
