        if (motion_detected) {
            int current_time = gpioTick();
            if (current_time - last_unlock_time > RATE_LIMIT) {
                gpioWrite(RELAY_PIN, 1);
                log_event("Door unlocked");
                gpioDelay(UNLOCK_DURATION * 1000);
                gpioWrite(RELAY_PIN, 0);
                last_unlock_time = current_time;
                motion_detected = 0;
