#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27
#define MIN_STEPS 5
#define MAX_STEPS 15
#define MIN_DUTY 0
#define MAX_DUTY 255
#define MIN_DURATION 50
#define MAX_DURATION 200

volatile sig_atomic_t shutdown = 0;

void signal_handler(int signum) {
    shutdown = 1;
}

void generate_pattern(int *duties1, int *duties2, int *durations, int *step_count) {
    *step_count = rand() % (MAX_STEPS - MIN_STEPS + 1) + MIN_STEPS;
    for (int i = 0; i < *step_count; i++) {
        duties1[i] = rand() % (MAX_DUTY - MIN_DUTY + 1) + MIN_DUTY;
        duties2[i] = rand() % (MAX_DUTY - MIN_DUTY + 1) + MIN_DUTY;
        durations[i] = rand() % (MAX_DURATION - MIN_DURATION + 1) + MIN_DURATION;
    }
}

void play_pattern(int *duties1, int *duties2, int *durations, int step_count) {
    for (int i = 0; i < step_count; i++) {
        gpioPWM(MOTOR1_PIN, duties1[i]);
        gpioPWM(MOTOR2_PIN, duties2[i]);
        gpioDelay(durations[i] * 1000);
    }
    gpioPWM(MOTOR1_PIN, 0);
    gpioPWM(MOTOR2_PIN, 0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    if (gpioSetMode(MOTOR1_PIN, PI_OUTPUT) != 0 || gpioSetMode(MOTOR2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    srand(time(NULL));
    signal(SIGINT, signal_handler);

    int *duties1 = malloc(MAX_STEPS * sizeof(int));
    int *duties2 = malloc(MAX_STEPS * sizeof(int));
    int *durations = malloc(MAX_STEPS * sizeof(int));

    if (!duties1 || !duties2 || !durations) {
        fprintf(stderr, "Memory allocation failed\n");
        gpioTerminate();
        free(duties1);
        free(duties2);
        free(durations);
        return 1;
    }

    while (!shutdown) {
        int step_count;
        generate_pattern(duties1, duties2, durations, &step_count);
        play_pattern(duties1, duties2, durations, step_count);
    }

    free(duties1);
    free(duties2);
    free(durations);
    gpioTerminate();

    return 0;
}

