#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define DATA_PIN 4
#define CLOCK_PIN 17
#define LOCK_PIN 27
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "weight_log.txt"
#define TIMEOUT 500000 // 0.5 seconds in microseconds
#define CALIBRATION_COUNT 100
#define THRESHOLD 10.0

void cleanup(int signum) {
    gpioTerminate();
    fclose(log_file);
    exit(signum);
}

int main() {
    FILE *calibration_file, *log_file;
    double scale_factor = 1.0, offset = 0.0;
    int i, raw_value, sum = 0;
    double weight;
    struct timespec ts;
    char buffer[256];

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    gpioSetMode(DATA_PIN, PI_INPUT);
    gpioSetMode(CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(LOCK_PIN, PI_OUTPUT);

    signal(SIGINT, cleanup);

    calibration_file = fopen(CALIBRATION_FILE, "r");
    if (calibration_file) {
        if (fscanf(calibration_file, "%lf %lf", &scale_factor, &offset) != 2) {
            fclose(calibration_file);
            calibration_file = NULL;
        } else {
            fclose(calibration_file);
        }
    }

    if (!calibration_file) {
        printf("Calibration file missing or invalid, using defaults\n");
    } else {
        printf("Loaded calibration: scale_factor=%f, offset=%f\n", scale_factor, offset);
    }

    for (i = 0; i < CALIBRATION_COUNT; i++) {
        if (gpioReadHX711(DATA_PIN, CLOCK_PIN, &raw_value, TIMEOUT) == 0) {
            sum += raw_value;
        } else {
            printf("HX711 read timeout, skipping calibration\n");
            break;
        }
    }

    if (i == CALIBRATION_COUNT) {
        offset = (double)sum / CALIBRATION_COUNT;
        printf("Calculated offset: %f\n", offset);
        calibration_file = fopen(CALIBRATION_FILE, "w");
        if (calibration_file) {
            fprintf(calibration_file, "%f %f\n", scale_factor, offset);
            fclose(calibration_file);
        }
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    while (1) {
        if (gpioReadHX711(DATA_PIN, CLOCK_PIN, &raw_value, TIMEOUT) == 0) {
            weight = (raw_value - offset) * scale_factor;
            if (weight > THRESHOLD) {
                gpioWrite(LOCK_PIN, 1);
            } else {
                gpioWrite(LOCK_PIN, 0);
            }
            clock_gettime(CLOCK_REALTIME, &ts);
            snprintf(buffer, sizeof(buffer), "%ld.%09ld %f\n", ts.tv_sec, ts.tv_nsec, weight);
            fputs(buffer, log_file);
            fflush(log_file);
        } else {
            printf("HX711 read timeout, skipping iteration\n");
        }
        usleep(500000); // 500 ms
    }

    cleanup(0);
    return 0;
}

