#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

#define RAIN_SENSOR_PIN 4
#define MOTOR_IN1_PIN 17
#define MOTOR_IN2_PIN 18
#define MOTOR_PWM_PIN 27
#define DEBOUNCE_INTERVAL 50
#define DEBOUNCE_COUNT 3
#define CHECK_INTERVAL 60
#define MOTOR_DURATION 5
#define LOG_FILE "/var/log/window_control.log"

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

int read_rain_sensor(int pin) {
    int count = 0;
    for (int i = 0; i < DEBOUNCE_COUNT; i++) {
        if (gpioRead(pin) == 0) {
            count++;
        }
        gpioDelay(DEBOUNCE_INTERVAL * 1000);
    }
    return count >= DEBOUNCE_COUNT;
}

void log_event(const char *event) {
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
    char log_message[256];
    snprintf(log_message, sizeof(log_message), "%s: %s", timestamp, event);
    syslog(LOG_INFO, "%s", log_message);
}

void close_window() {
    gpioWrite(MOTOR_IN1_PIN, 1);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioSetPWMFrequency(MOTOR_PWM_PIN, 1000);
    gpioSetPWMRange(MOTOR_PWM_PIN, 255);
    gpioSetPWM dutyCycle(MOTOR_PWM_PIN, 150);
    log_event("Window closing");
    gpioDelay(MOTOR_DURATION * 1000 * 1000);
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioSetPWMdutyCycle(MOTOR_PWM_PIN, 0);
    log_event("Window closed");
}

int main() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio library");
        return EXIT_FAILURE;
    }

    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT);

    if (gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP) != 0) {
        syslog(LOG_ERR, "Failed to set pull-up for rain sensor");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(MOTOR_IN1_PIN, PI_PUD_DOWN) != 0) {
        syslog(LOG_ERR, "Failed to set pull-down for motor IN1");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(MOTOR_IN2_PIN, PI_PUD_DOWN) != 0) {
        syslog(LOG_ERR, "Failed to set pull-down for motor IN2");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(MOTOR_PWM_PIN, PI_PUD_DOWN) != 0) {
        syslog(LOG_ERR, "Failed to set pull-down for motor PWM");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    openlog("window_control", LOG_PID | LOG_CONS, LOG_USER);

    while (!stop_flag) {
        if (read_rain_sensor(RAIN_SENSOR_PIN)) {
            close_window();
            gpioDelay(CHECK_INTERVAL * 1000 * 1000);
        } else {
            gpioDelay(CHECK_INTERVAL * 1000 * 1000);
        }
    }

    closelog();
    gpioTerminate();
    return EXIT_SUCCESS;
}

