#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27
#define CALIBRATION_FILE "calibration.txt"
#define SECURITY_LOG "security.log"
#define TIMEOUT_US 100000

volatile int running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int read_hx711() {
    int data = 0;
    int bit;
    gpioWrite(HX711_CLOCK_PIN, 1);
    for (bit = 0; bit < 24; bit++) {
        gpioDelay(1);
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1);
        data = (data << 1) | gpioRead(HX711_DATA_PIN);
        gpioWrite(HX711_CLOCK_PIN, 1);
    }
    return data;
}

double read_weight(double calibration_factor) {
    int raw_value = read_hx711();
    return (double)raw_value / calibration_factor;
}

void log_event(double weight) {
    FILE *log_file = fopen(SECURITY_LOG, "a");
    if (log_file == NULL) {
        perror("Failed to open security log file");
        return;
    }
    time_t now = time(NULL);
    fprintf(log_file, "%s: Weight exceeded 5.0 kg: %.2f kg\n", ctime(&now), weight);
    fclose(log_file);
}

void calibrate(double *calibration_factor) {
    FILE *cal_file = fopen(CALIBRATION_FILE, "r");
    if (cal_file != NULL) {
        fscanf(cal_file, "%lf", calibration_factor);
        fclose(cal_file);
        return;
    }
    double known_weight_kg;
    printf("Place a known weight on the load cell and press Enter: ");
    scanf("%lf", &known_weight_kg);
    int raw_value = read_hx711();
    *calibration_factor = (double)raw_value / known_weight_kg;
    cal_file = fopen(CALIBRATION_FILE, "w");
    if (cal_file == NULL) {
        perror("Failed to open calibration file");
        return;
    }
    fprintf(cal_file, "%.6f\n", *calibration_factor);
    fclose(cal_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }
    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);
    gpioWrite(SOLENOID_PIN, 0);

    signal(SIGINT, sigint_handler);

    double calibration_factor;
    calibrate(&calibration_factor);

    while (running) {
        double weight = read_weight(calibration_factor);
        if (weight > 5.0) {
            log_event(weight);
            gpioWrite(SOLENOID_PIN, 1);
            gpioDelay(5000000);
            gpioWrite(SOLENOID_PIN, 0);
        }
        gpioDelay(100000);
    }

    gpioTerminate();
    return 0;
}

