#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define SENSOR_CHIP "gpiochip0"
#define SENSOR_LINE 16
#define RELAY_CHIP "gpiochip0"
#define RELAY_LINE 20
#define LOG_FILE "relay_events.log"

static struct gpiod_chip *sensor_chip = NULL;
static struct gpiod_chip *relay_chip = NULL;
static struct gpiod_line *sensor_line = NULL;
static struct gpiod_line *relay_line = NULL;
static int relay_state = 0;

void log_event(const char *state) {
    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    char *iso_time = ctime(&now);
    iso_time[strlen(iso_time) - 1] = '\0'; // Remove newline
    fprintf(log, "%s: Relay state changed to %s\n", iso_time, state);
    fclose(log);
}

void handle_signal(int sig) {
    if (sensor_line) gpiod_line_release(sensor_line);
    if (relay_line) gpiod_line_release(relay_line);
    if (sensor_chip) gpiod_chip_close(sensor_chip);
    if (relay_chip) gpiod_chip_close(relay_chip);
    exit(0);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    sensor_chip = gpiod_chip_open_by_name(SENSOR_CHIP);
    if (!sensor_chip) {
        perror("Failed to open sensor chip");
        return EXIT_FAILURE;
    }

    relay_chip = gpiod_chip_open_by_name(RELAY_CHIP);
    if (!relay_chip) {
        perror("Failed to open relay chip");
        gpiod_chip_close(sensor_chip);
        return EXIT_FAILURE;
    }

    struct gpiod_line_request_bulk bulk;
    gpiod_line_request_bulk_init(&bulk);

    struct gpiod_line_request_config sensor_config = {
        .consumer = "ir_sensor",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
    };

    struct gpiod_line_request_config relay_config = {
        .consumer = "relay",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT,
        .default_val = relay_state,
    };

    gpiod_line_request_bulk_add_line(&bulk, sensor_chip, SENSOR_LINE, &sensor_config);
    gpiod_line_request_bulk_add_line(&bulk, relay_chip, RELAY_LINE, &relay_config);

    if (gpiod_line_request_bulk(&bulk) < 0) {
        perror("Failed to request lines");
        gpiod_chip_close(sensor_chip);
        gpiod_chip_close(relay_chip);
        return EXIT_FAILURE;
    }

    sensor_line = gpiod_line_bulk_get_line(&bulk, 0);
    relay_line = gpiod_line_bulk_get_line(&bulk, 1);

    while (1) {
        int sensor_value = gpiod_line_get_value(sensor_line);
        if (sensor_value < 0) {
            perror("Failed to read sensor value");
            break;
        }

        if (sensor_value == 0) { // Obstacle detected
            relay_state = !relay_state;
            gpiod_line_set_value(relay_line, relay_state);
            log_event(relay_state ? "ON" : "OFF");
        }

        sleep(1); // Check every second
    }

    gpiod_line_release(sensor_line);
    gpiod_line_release(relay_line);
    gpiod_chip_close(sensor_chip);
    gpiod_chip_close(relay_chip);

    return EXIT_SUCCESS;
}

