#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define PIR_LINE "17"
#define BUZZER_LINE "18"
#define LOG_FILE "motion_log.txt"

static struct gpiod_chip *chip;
static struct gpiod_line *pir_line, *buzzer_line;
static FILE *log_file;

void log_motion_event() {
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
    fprintf(log_file, "%s\n", timestamp);
    fflush(log_file);
}

void buzzer_on() {
    gpiod_line_set_value(buzzer_line, 1);
}

void buzzer_off() {
    gpiod_line_set_value(buzzer_line, 0);
}

void signal_handler(int sig) {
    buzzer_off();
    if (log_file) fclose(log_file);
    if (pir_line) gpiod_line_release(pir_line);
    if (buzzer_line) gpiod_line_release(buzzer_line);
    if (chip) gpiod_chip_close(chip);
    exit(0);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    pir_line = gpiod_chip_get_line(chip, atoi(PIR_LINE));
    if (!pir_line) {
        perror("Failed to get PIR line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    buzzer_line = gpiod_chip_get_line(chip, atoi(BUZZER_LINE));
    if (!buzzer_line) {
        perror("Failed to get Buzzer line");
        gpiod_line_release(pir_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(pir_line, "motion_sensor") < 0) {
        perror("Failed to request PIR line as input");
        gpiod_line_release(buzzer_line);
        gpiod_line_release(pir_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        perror("Failed to request Buzzer line as output");
        gpiod_line_release(pir_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(buzzer_line);
