#include <unistd.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 18
#define CONFIG_FILE "watering.conf"
#define MIN_DURATION 1
#define MAX_DURATION 3600

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

int read_config_duration(const char *filename, int *duration) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open configuration file");
        return -1;
    }

    char line[256];
    if (!fgets(line, sizeof(line), file)) {
        perror("Failed to read configuration file");
        fclose(file);
        return -1;
    }

    fclose(file);

    char *token = strtok(line, "=");
    if (!token || !strtok(NULL, "=")) {
        fprintf(stderr, "Malformed configuration file\n");
        return -1;
    }

    char *endptr;
    long val = strtol(token, &endptr, 10);
    if (*endptr != '\0' || val < MIN_DURATION || val > MAX_DURATION) {
        fprintf(stderr, "Invalid duration in configuration file\n");
        return -1;
    }

    *duration = (int)val;
    return 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int duration;

    if (read_config_duration(CONFIG_FILE, &duration) != 0) {
        return EXIT_FAILURE;
    }

    printf("Configured duration: %d seconds\n", duration);

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Failed to set SIGINT handler");
        return EXIT_FAILURE;
    }

    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("Failed to set SIGTERM handler");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "watering_valve", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Valve off\n");

    while (!stop_flag) {
        if (gpiod_line_set_value(line, 1) < 0) {
            perror("Failed to set GPIO line high");
            break;
        }
        printf("Valve on\n");

        if (usleep(duration * 1000000) < 0) {
            perror("Failed to sleep");
            break;
        }

        if (gpiod_line_set_value(line, 0) < 0) {
            perror("Failed to set GPIO line low");
            break;
        }
        printf("Valve off\n");
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

