#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pigpio.h>

#define LEFT_PWM 22
#define RIGHT_PWM 23
#define LEFT_DIR 24
#define RIGHT_DIR 25
#define LEFT_SENSOR 4
#define MIDDLE_SENSOR 17
#define RIGHT_SENSOR 27
#define PWM_FREQ 1000
#define BASE_SPEED 150

FILE *log_file;

void log_control_cycle(int left_sensor, int middle_sensor, int right_sensor, int left_speed, int right_speed) {
    time_t now = time(NULL);
    char *iso_time = ctime(&now);
    iso_time[strlen(iso_time) - 1] = '\0'; // Remove newline character
    fprintf(log_file, "%s, %d, %d, %d, %d, %d\n", iso_time, left_sensor, middle_sensor, right_sensor, left_speed, right_speed);
}

void stop_motors() {
    gpioWrite(LEFT_PWM, 0);
    gpioWrite(RIGHT_PWM, 0);
    gpioWrite(LEFT_DIR, 0);
    gpioWrite(RIGHT_DIR, 0);
}

void cleanup() {
    stop_motors();
    if (log_file) fclose(log_file);
    gpioTerminate();
}

void signal_handler(int sig) {
    cleanup();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    gpioSetMode(LEFT_PWM, PI_OUTPUT);
    gpioSetMode(RIGHT_PWM, PI_OUTPUT);
    gpioSetMode(LEFT_DIR, PI_OUTPUT);
    gpioSetMode(RIGHT_DIR, PI_OUTPUT);
    gpioSetMode(LEFT_SENSOR, PI_INPUT);
    gpioSetMode(MIDDLE_SENSOR, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR, PI_INPUT);

    gpioSetPWMfrequency(LEFT_PWM, PWM_FREQ);
    gpioSetPWMfrequency(RIGHT_PWM, PWM_FREQ);

    log_file = fopen("trace_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (1) {
        int left_sensor = gpioRead(LEFT_SENSOR);
        int middle_sensor = gpioRead(MIDDLE_SENSOR);
        int right_sensor = gpioRead(RIGHT_SENSOR);

        int left_speed = 0, right_speed = 0;

        if (middle_sensor == 0) {
            left_speed = BASE_SPEED;
            right_speed = BASE_SPEED;
        } else if (left_sensor == 0) {
            left_speed = BASE_SPEED / 2;
            right_speed = BASE_SPEED;
        } else if (right_sensor == 0) {
            left_speed = BASE_SPEED;
            right_speed = BASE_SPEED / 2;
        }

        gpioWrite(LEFT_PWM, left_speed);
        gpioWrite(RIGHT_PWM, right_speed);
        gpioWrite(LEFT_DIR, 1);
        gpioWrite(RIGHT_DIR, 1);

        log_control_cycle(left_sensor, middle_sensor, right_sensor, left_speed, right_speed);

        gpioDelay(10000); // 10 ms
    }

    cleanup();
    return 0;
}

