#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x23
#define RELAY_PIN 23
#define MIN_LUX 150
#define LOG_FILE "grow_log.txt"

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

uint16_t read_bh1750(int i2c_handle) {
    uint8_t data[2];
    if (i2cReadDevice(i2c_handle, 0x10, data, 2) != 2) {
        fprintf(stderr, "Failed to read from BH1750\n");
        return 0;
    }
    return (data[0] << 8) | data[1];
}

void log_event(const char *event) {
    FILE *log = fopen(LOG_FILE, "a");
    if (log == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    fprintf(log, "%ld.%03ld %s\n", ts.tv_sec, ts.tv_nsec / 1000000, event);
    fclose(log);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (running) {
        uint16_t lux = read_bh1750(i2c_handle);
        if (lux == 0) {
            continue;
        }

        if (lux < MIN_LUX) {
            gpioWrite(RELAY_PIN, PI_HIGH);
            log_event("Relay ON");
        } else {
            gpioWrite(RELAY_PIN, PI_LOW);
            log_event("Relay OFF");
        }

        log_event("Lux: ");
        printf("Lux: %d\n", lux);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

