#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22
#define DEBOUNCE_TIME 100
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define LOCKED_PULSE_WIDTH 1000
#define UNLOCKED_PULSE_WIDTH 2000

volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

