#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define MOTOR1_LINE "gpiochip0:line17"
#define MOTOR2_LINE "gpiochip0:line27"
#define PULSE_DURATION_MOTOR1 200
#define PULSE_DURATION_MOTOR2 300
#define MOTOR_CURRENT_MA 60
#define MOTOR_VOLTAGE_V 3.0

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *motor1_line, *motor2_line;
    int ret;

    // Register signal handlers
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    // Request GPIO lines for motor control
    motor1_line = gpiod_chip_get_line(chip, 17);
    if (!motor1_line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    motor2_line = gpiod_chip_get_line(chip, 27);
    if (!motor2_line) {
        perror("gpiod_chip_get_line");
        gpiod_line_release(motor1_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request lines as output
    ret = gpiod_line_request_output(motor1_line, "motor1", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_line_release(motor2_line);
        gpiod_line_release(motor1_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(motor2_line, "motor2", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_line_release(motor1_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (running) {
        // Pulse motor 1
        ret = gpiod_line_set_value(motor1_line, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break;
        }
        usleep(PULSE_DURATION_MOTOR1 * 1000);

        ret = gpiod_line_set_value(motor1_line, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break;
        }
        usleep(PULSE_DURATION_MOTOR1 * 1000);

        // Pulse motor 2
        ret = gpiod_line_set_value(motor2_line, 1);
