            perror("gpiod_line_set_value");
            break;
        }
        usleep(PULSE_DURATION_MOTOR2 * 1000);

        ret = gpiod_line_set_value(motor2_line, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break;
        }
        usleep(PULSE_DURATION_MOTOR2 * 1000);
    }

    // Cleanup
    gpiod_line_release(motor2_line);
    gpiod_line_release(motor1_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

