#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>
#include <zmq.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_SOUND_SENSOR 17
#define GPIO_ALARM_LED 27
#define ZMQ_ADDRESS "tcp://*:5555"
#define ZMQ_TOPIC "SOUND_ALERTS"
#define POLL_INTERVAL 10  // 10 ms

volatile sig_atomic_t running = 1;

void sig_handler(int signum) {
    running = 0;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <mode> (sound_sensor|alarm_node)\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *mode = argv[1];
    struct gpiod_chip *chip;
    struct gpiod_line *sound_sensor_line, *alarm_led_line;
    int ret;
    zmq_context_t *context = NULL;
    zmq_socket_t *socket = NULL;

    // Initialize GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request GPIO lines
    sound_sensor_line = gpiod_chip_get_line(chip, GPIO_SOUND_SENSOR);
    if (!sound_sensor_line) {
        perror("Failed to get sound sensor line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    alarm_led_line = gpiod_chip_get_line(chip, GPIO_ALARM_LED);
    if (!alarm_led_line) {
        perror("Failed to get alarm LED line");
        gpiod_line_release(sound_sensor_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure GPIO lines
    ret = gpiod_line_request_input(sound_sensor_line, "sound_sensor");
    if (ret < 0) {
        perror("Failed to request input for sound sensor line");
        gpiod_line_release(sound_sensor_line);
        gpiod_line_release(alarm_led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(alarm_led_line, "alarm_led", 0);
    if (ret < 0) {
        perror("Failed to request output for alarm LED line");
        gpiod_line_release(sound_sensor_line);
        gpiod_line_release(alarm_led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initialize ZeroMQ
    context = zmq_ctx_new();
    if (!context) {
        perror("Failed to create ZeroMQ context");
        gpiod_line_release(sound_sensor_line);
        gpiod_line_release(alarm_led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (strcmp(mode, "sound_sensor") == 0) {
        // Sound sensor mode
        socket = zmq_socket(context, ZMQ_PUB);
        if (!socket) {
            perror("Failed to create ZeroMQ socket");
            zmq_ctx_destroy(context);
            gpiod_line_release(sound_sensor_line);
            gpiod_line_release(alarm_led_line);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        ret = zmq_bind(socket, ZMQ_ADDRESS);
        if (ret < 0) {
            perror("Failed to bind ZeroMQ socket");
            zmq_close(socket);
            zmq_ctx_destroy(context);
            gpiod_line_release(sound_sensor_line);
            gpiod_line_release(alarm_led_line);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        signal(SIGINT, sig_handler);
        signal(SIGTERM, sig_handler);

        while (running) {
            int sound_detected = gpiod_line_get_value(sound_sensor_line);
            if (sound_detected == 0) {
                zmq_msg_t msg;
                zmq_msg_init(&msg);
                zmq_msg_set_str(&msg, ZMQ_TOPIC, strlen(ZMQ_TOPIC));
                zmq_send(socket, &msg, 0);
                zmq_msg_close(&msg);
            }
            usleep(POLL_INTERVAL * 1000);
        }
    } else if (strcmp(mode, "alarm_node") == 0) {
        // Alarm node mode
        socket = zmq_socket(context, ZMQ_SUB);
        if (!socket) {
            perror("Failed to create ZeroMQ socket");
            zmq_ctx_destroy(context);
            gpiod_line_release(sound_sensor_line);
            gpiod_line_release(alarm_led_line);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        ret = zmq_connect(socket, "tcp://localhost:5555");
        if (ret < 0) {
            perror("Failed to connect ZeroMQ socket");
            zmq_close(socket);
            zmq_ctx_destroy(context);
            gpiod_line_release(sound_sensor_line);
            gpiod_line_release(alarm_led_line);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        ret = zmq_setsockopt(socket, ZMQ_SUBSCRIBE, ZMQ_TOPIC, strlen(ZMQ_TOPIC));
        if (ret < 0) {
            perror("Failed to subscribe to topic");
            zmq_close(socket);
            zmq_ctx_destroy(context);
            gpiod_line_release(sound_sensor_line);
            gpiod_line_release(alarm_led_line);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        signal(SIGINT, sig_handler);
        signal(SIGTERM, sig_handler);

        while (running) {
            zmq_msg_t msg;
            zmq_msg_init(&msg);
            ret = zmq_recv(socket, &msg, 0);
            if (ret >= 0) {
                gpiod_line_set_value(alarm_led_line, 1);
                usleep(1000000);  // 1 second
                gpiod_line_set_value(alarm_led_line, 0);
            }
            zmq_msg_close(&msg);
        }
    } else {
        fprintf(stderr, "Invalid mode: %s\n", mode);
        return EXIT_FAILURE;
    }

    // Cleanup
    if (socket) {
        zmq_close(socket);
    }
    zmq_ctx_destroy(context);
    gpiod_line_release(sound_sensor_line);
    gpiod_line_release(alarm_led_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

