#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <paho-mqtt.h>

#define IR_PIN 17
#define PULSE_BUF_SIZE 1000
#define MQTT_BROKER "tcp://localhost:1883"
#define MQTT_TOPIC "ir/decoded"

volatile int running = 1;
volatile int pulse_count = 0;
volatile int pulse_buf[PULSE_BUF_SIZE];
volatile int pulse_widths[PULSE_BUF_SIZE];
volatile int pulse_times[PULSE_BUF_SIZE];
volatile int pulse_index = 0;

MQTTClient client;

void pulse_callback(int gpio, int level, uint32_t tick) {
    if (level == PI_TIMEOUT) {
        if (pulse_count > 0) {
            pulse_buf[pulse_index++] = pulse_count;
            pulse_count = 0;
        }
    } else {
        pulse_count++;
    }
}

void signal_handler(int signum) {
    running = 0;
}

void log_decoded_command(uint32_t address, uint32_t command) {
    char log_message[256];
    snprintf(log_message, sizeof(log_message), "Decoded NEC command: Address=0x%08X, Command=0x%08X", address, command);
    syslog(LOG_INFO, "%s", log_message);
}

void publish_mqtt_command(uint32_t address, uint32_t command) {
    char json_message[256];
    snprintf(json_message, sizeof(json_message), "{\"address\": \"%08X\", \"command\": \"%08X\"}", address, command);
    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    pubmsg.payload = json_message;
    pubmsg.payloadlen = strlen(json_message);
    pubmsg.qos = 1;
    pubmsg.retained = 0;
    MQTTClient_publishMessage(client, MQTT_TOPIC, &pubmsg, NULL);
}

void decode_nec_command(uint32_t *address, uint32_t *command) {
    if (pulse_index < 36) {
        return;
    }

    uint32_t header_mark = pulse_widths[0];
    uint32_t header_space = pulse_widths[1];
    uint32_t bit_mark = pulse_widths[2];
    uint32_t one_space = pulse_widths[3];
    uint32_t zero_space = pulse_widths[4];

    if (header_mark != 9000 || header_space != 4500 || bit_mark != 560 || one_space != 1690 || zero_space != 560) {
        return;
    }

    *address = 0;
    *command = 0;

    for (int i = 5; i < 21; i++) {
        *address = (*address << 1) | (pulse_widths[i] == one_space);
    }

    for (int i = 21; i < 37; i++) {
        *command = (*command << 1) | (pulse_widths[i] == one_space);
    }

    uint32_t checksum = (*address ^ *command) & 0xFF;
    if (checksum != pulse_widths[37]) {
        return;
    }

    log_decoded_command(*address, *command);
    publish_mqtt_command(*address, *command);
}

int main() {
    if (pigpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

