        syslog(LOG_ERR, "Failed to set GPIO%d mode to input", IR_PIN);
        pigpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(IR_PIN, pulse_callback, 0) < 0) {
        syslog(LOG_ERR, "Failed to set alert function for GPIO%d", IR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

