#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESSES {0x23, 0x24, 0x25, 0x26}
#define I2C_COMMAND 0x20
#define I2C_DELAY 180000
#define UDP_PORT 5005
#define UDP_MULTICAST "239.255.255.250"

volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

int main() {
    int i2c_fd, udp_fd;
    uint8_t data[2];
    struct sockaddr_in udp_addr;
    char buffer[256];
    sigset_t sigset;

    // Set up signal handler
    sigemptyset(&sigset);
    sigaddset(&sigset, SIGINT);
    sigaddset(&sigset, SIGTERM);
    if (sigprocmask(SIG_BLOCK, &sigset, NULL) == -1) {
        perror("sigprocmask");
        return EXIT_FAILURE;
    }
    struct sigaction sa = {0};
    sa.sa_handler = handle_sigint;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    // Open I2C bus
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) == -1) {
        perror("open");
        return EXIT_FAILURE;
    }

    // Create UDP socket
    if ((udp_fd = socket(AF_INET, SOCK_DGRAM, 0)) == -1) {
        perror("socket");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Set up UDP address
    memset(&udp_addr, 0, sizeof(udp_addr));
    udp_addr.sin_family = AF_INET;
    udp_addr.sin_port = htons(UDP_PORT);
    if (inet_pton(AF_INET, UDP_MULTICAST, &udp_addr.sin_addr) <= 0) {
        perror("inet_pton");
        close(udp_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        for (int i = 0; i < 4; i++) {
            uint16_t lux = 0;

            // Set I2C slave address
            if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESSES[i]) == -1) {
                fprintf(stderr, "Failed to set I2C address 0x%02X: %s\n", I2C_ADDRESSES[i], strerror(errno));
                lux = NAN;
            } else {
                // Write command
                if (write(i2c_fd, &I2C_COMMAND, 1) != 1) {
                    fprintf(stderr, "Failed to write command to sensor %d: %s\n", i + 1, strerror(errno));
                    lux = NAN;
                } else {
                    // Wait for conversion
                    usleep(I2C_DELAY);

                    // Read data
                    if (read(i2c_fd, data, 2) != 2) {
                        fprintf(stderr, "Failed to read data from sensor %d: %s\n", i + 1, strerror(errno));
                        lux = NAN;
                    } else {
                        // Convert to lux
                        lux = ((data[0] << 8) | data[1]) / 1.2;
                    }
                }
            }

            // Format and send UDP packet
            snprintf(buffer, sizeof(buffer), "%d,%.1f;", i + 1, lux);
            if (sendto(udp_fd, buffer, strlen(buffer), 0, (struct sockaddr *)&udp_addr, sizeof(udp_addr)) == -1) {
                perror("sendto");
            }
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    close(udp_fd);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

