#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <time.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x28
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY 100000 // 100 ms
#define LOG_FILE "airflow_log.txt"

int i2c_fd;
FILE *log_file;

void close_i2c_and_log() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }
    exit(0);
}

void sigint_handler(int signum) {
    close_i2c_and_log();
}

int read_sensor_data() {
    uint8_t write_buf[1] = {0};
    uint8_t read_buf[2];
    int retries = 0;

    while (retries < I2C_RETRY_COUNT) {
        if (write(i2c_fd, write_buf, 1) != 1) {
            if (errno == EAGAIN || errno == EBUSY) {
                usleep(I2C_RETRY_DELAY);
                retries++;
                continue;
            }
            perror("I2C write failed");
            return -1;
        }

        if (read(i2c_fd, read_buf, 2) != 2) {
            if (errno == EAGAIN || errno == EBUSY) {
                usleep(I2C_RETRY_DELAY);
                retries++;
                continue;
            }
            perror("I2C read failed");
            return -1;
        }

        uint16_t raw_value = (read_buf[0] << 8) | read_buf[1];
        if (raw_value == 0xFFFF) {
            continue; // Sensor not present
        }

        uint16_t flow = (raw_value - 3277) * 0.1;
        time_t now = time(NULL);
        fprintf(log_file, "%ld,%f\n", now, flow);
        fflush(log_file);
        return 0;
    }

    perror("I2C read retries exceeded");
    return -1;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to set SIGINT handler");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        if (read_sensor_data() == 0) {
            sleep(1);
        }
    }

    close_i2c_and_log();
    return EXIT_SUCCESS;
}

