#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x39
#define WHO_AM_I 0x24
#define ENABLE 0x80
#define CFG6 0xAF
#define SP_EN 0x01
#define F1 0x60
#define F8 0x67
#define CLEAR 0x68
#define NIR 0x69

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    int fd, log_fd;
    char buffer[10];
    struct sigaction sa;

    // Open I2C device
    if ((fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return EXIT_FAILURE;
    }

    // Open log file
    if ((log_fd = open("spectral_log.csv", O_WRONLY | O_CREAT | O_APPEND, 0644)) < 0) {
        perror("Failed to open log file");
        close(fd);
        return EXIT_FAILURE;
    }

    // Signal handler for SIGINT
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set signal handler");
        close(fd);
        close(log_fd);
        return EXIT_FAILURE;
    }

    // Initialize sensor
    if (read(fd, buffer, 1) != 1 || buffer[0] != 0x19) {
        fprintf(stderr, "Sensor WHO_AM_I mismatch\n");
        close(fd);
        close(log_fd);
        return EXIT_FAILURE;
    }

    if (write(fd, &ENABLE, 1) != 1) {
        perror("Failed to power on sensor");
        close(fd);
        close(log_fd);
        return EXIT_FAILURE;
    }

    uint8_t cfg6 = 0x00; // Configure SMUX for spectral readings
    if (write(fd, &cfg6, 1) != 1) {
        perror("Failed to configure SMUX");
        close(fd);
        close(log_fd);
        return EXIT_FAILURE;
    }

    uint8_t enable = SP_EN;
    if (write(fd, &enable, 1) != 1) {
        perror("Failed to enable spectral measurement");
        close(fd);
        close(log_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        uint16_t spectral_data[10];
        for (int i = 0; i < 10; i++) {
            if (read(fd, buffer, 2) != 2) {
                perror("Failed to read spectral data");
                close(fd);
                close(log_fd);
                return EXIT_FAILURE;
            }
            spectral_data[i] = (buffer[0] << 8) | buffer[1];
        }

        // Simplified lux approximation (example formula)
        double lux = (spectral_data[0] * 0.362) + (spectral_data[1] * 0.357) + (spectral_data[2] * 0.193) + (spectral_data[3] * 0.072) + (spectral_data[4] * 0.025) + (spectral_data[5] * 0.012) + (spectral_data[6] * 0.006) + (spectral_data[7] * 0.003) + (spectral_data[8] * 0.001) + (spectral_data[9] * 0.0005);

        // Log results with timestamp
