#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define DEFAULT_I2C_ADDRESS 0x37
#define DEFAULT_INTERVAL 1
#define DEFAULT_FILENAME "seismic_data.csv"
#define I2C_DEVICE "/dev/i2c-1"
#define MAX_RETRIES 3
#define BACKOFF_MS 10

typedef struct {
    int fd;
    FILE *csv_file;
    FILE *error_file;
    int i2c_address;
    int interval;
    char *filename;
} SeismicData;

void log_error(SeismicData *data, const char *message) {
    time_t now = time(NULL);
    fprintf(data->error_file, "%s: %s\n", ctime(&now), message);
    fflush(data->error_file);
}

int i2c_write(SeismicData *data, uint8_t reg, uint8_t *buf, size_t len) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (write(data->fd, buf, len) == len) {
            return 0;
        }
        retries++;
        usleep(BACKOFF_MS * 1000);
    }
    return -1;
}

int i2c_read(SeismicData *data, uint8_t reg, uint8_t *buf, size_t len) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (write(data->fd, &reg, 1) == 1 && read(data->fd, buf, len) == len) {
            return 0;
        }
        retries++;
        usleep(BACKOFF_MS * 1000);
    }
    return -1;
}

void handle_sigint(int sig) {
    exit(0);
}

void handle_sigterm(int sig) {
    exit(0);
}

int main(int argc, char *argv[]) {
    SeismicData data = {
        .fd = -1,
        .csv_file = NULL,
        .error_file = NULL,
        .i2c_address = DEFAULT_I2C_ADDRESS,
        .interval = DEFAULT_INTERVAL,
        .filename = DEFAULT_FILENAME
    };

    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    sa.sa_handler = handle_sigterm;
    sigaction(SIGTERM, &sa, NULL);

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-a") == 0 && i + 1 < argc) {
            data.i2c_address = strtol(argv[i + 1], NULL, 16);
            i++;
        } else if (strcmp(argv[i], "-i") == 0 && i + 1 < argc) {
            data.interval = atoi(argv[i + 1]);
            i++;
        } else if (strcmp(argv[i], "-f") == 0 && i + 1 < argc) {
            data.filename = argv[i + 1];
            i++;
        }
    }

    data.csv_file = fopen(data.filename, "a");
    if (!data.csv_file) {
        log_error(&data, "Failed to open CSV file");
        return 1;
    }

    data.error_file = fopen("seismic_error.log", "a");
    if (!data.error_file) {
        log_error(&data, "Failed to open error log file");
        fclose(data.csv_file);
        return 1;
    }

    if ((data.fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        log_error(&data, "Failed to open I2C device");
        fclose(data.csv_file);
        fclose(data.error_file);
        return 1;
    }

    if (ioctl(data.fd, I2C_SLAVE, data.i2c_address) < 0) {
        log_error(&data, "Failed to set I2C address");
        close(data.fd);
        fclose(data.csv_file);
        fclose(data.error_file);
        return 1;
    }

    fprintf(data.csv_file, "timestamp,x_g,y_g,z_g\n");
    fflush(data.csv_file);

    while (1) {
        uint8_t buf[6];
        if (i2c_read(&data, 0x28, buf, sizeof(buf)) < 0) {
            log_error(&data, "Failed to read from sensor");
            continue;
        }

        int16_t x = (buf[1] << 8) | buf[0];
        int16_t y = (buf[3] << 8) | buf[2];
        int16_t z = (buf[5] << 8) | buf[4];

        double x_g = x * 0.000244;
        double y_g = y * 0.000244;
        double z_g = z * 0.000244;

        time_t now = time(NULL);
        fprintf(data.csv_file, "%s,%.4f,%.4f,%.4f\n", ctime(&now), x_g, y_g, z_g);
        fflush(data.csv_file);

        sleep(data.interval);
    }

    close(data.fd);
    fclose(data.csv_file);
    fclose(data.error_file);
    return 0;
}

