#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>

#define I2C_DEVICE "/dev/i2c-1"
#define BH1750_ADDRESS 0x23
#define BH1750_POWER_ON 0x01
#define BH1750_CONT_HIGH_RES_MODE 0x10
#define I2C_READ_LEN 2
#define UDP_MULTICAST_PORT 5000
#define UDP_MULTICAST_GROUP "239.255.255.250"
#define UDP_TTL 1

int i2c_fd;
int udp_fd;
struct sockaddr_in udp_addr;

void signal_handler(int signum) {
    close(i2c_fd);
    close(udp_fd);
    exit(signum);
}

int main() {
    // Initialize I2C
    if ((i2c_fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize UDP
    if ((udp_fd = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        perror("Failed to create UDP socket");
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    memset(&udp_addr, 0, sizeof(udp_addr));
    udp_addr.sin_family = AF_INET;
    udp_addr.sin_port = htons(UDP_MULTICAST_PORT);
    if (inet_pton(AF_INET, UDP_MULTICAST_GROUP, &udp_addr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(i2c_fd);
        close(udp_fd);
        return EXIT_FAILURE;
    }
    if (setsockopt(udp_fd, IPPROTO_IP, IP_MULTICAST_TTL, &UDP_TTL, sizeof(UDP_TTL)) < 0) {
        perror("Failed to set UDP TTL");
        close(i2c_fd);
        close(udp_fd);
        return EXIT_FAILURE;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize BH1750 sensor
    uint8_t init_commands[] = {BH1750_POWER_ON, BH1750_CONT_HIGH_RES_MODE};
    if (write(i2c_fd, init_commands, sizeof(init_commands)) != sizeof(init_commands)) {
        perror("Failed to initialize BH1750 sensor");
        close(i2c_fd);
        close(udp_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        uint8_t raw_data[I2C_READ_LEN];
        if (read(i2c_fd, raw_data, sizeof(raw_data)) != sizeof(raw_data)) {
            perror("Failed to read from BH1750 sensor");
            sleep(1);
            continue;
        }

        uint16_t raw_value = (raw_data[0] << 8) | raw_data[1];
        float lux = raw_value / 1.2;

        char buffer[32];
        snprintf(buffer, sizeof(buffer), "%.2f\n", lux);

        if (sendto(udp_fd, buffer, strlen(buffer), 0, (struct sockaddr *)&udp_addr, sizeof(udp_addr)) < 0) {
            perror("Failed to send UDP packet");
        }

        sleep(1);
    }

    // Clean up
    close(i2c_fd);
    close(udp_fd);
    return EXIT_SUCCESS;
}

