#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/ttyS0"
#define BAUD_RATE 921600
#define MAGIC_WORD "\x02\x04\x03\x06\x08\x05\x07\x09"
#define MAGIC_WORD_LEN 8
#define TLV_HEADER_LEN 4
#define CSV_FILE "radar_data.csv"

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    int uart_handle;
    FILE *csv_file;
    char buffer[1024];
    char *magic_ptr;
    uint32_t timestamp;
    uint16_t object_index, range_m, velocity_mps;
    struct timespec ts;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    if ((uart_handle = gpioSerialOpen(UART_DEVICE, BAUD_RATE, 0)) < 0) {
        fprintf(stderr, "Failed to open UART device %s\n", UART_DEVICE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if ((csv_file = fopen(CSV_FILE, "w")) == NULL) {
        fprintf(stderr, "Failed to open CSV file %s\n", CSV_FILE);
        gpioSerialClose(uart_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(csv_file, "timestamp,object_index,range_m,velocity_mps\n");

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        int bytes_read = gpioSerialRead(uart_handle, buffer, sizeof(buffer));
        if (bytes_read < 0) {
            fprintf(stderr, "Failed to read from UART\n");
            break;
        }

        magic_ptr = buffer;
        while (magic_ptr < buffer + bytes_read - MAGIC_WORD_LEN) {
            if (memcmp(magic_ptr, MAGIC_WORD, MAGIC_WORD_LEN) == 0) {
                if (magic_ptr + TLV_HEADER_LEN + 2 * sizeof(uint16_t) > buffer + bytes_read) {
                    break;
                }

                timestamp = *(uint32_t *)(magic_ptr + TLV_HEADER_LEN);
                object_index = ntohs(*(uint16_t *)(magic_ptr + TLV_HEADER_LEN + 4));
