#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <errno.h>
#include <sys/select.h>
#include <signal.h>
#include <time.h>

#define UART_PATH "/dev/serial0"
#define BAUDRATE B115200
#define TIMEOUT 2
#define IBT 500000 // 0.5s in microseconds

volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

void handle_sigterm(int sig) {
    running = 0;
}

int open_uart(const char *path, speed_t baudrate) {
    int fd = open(path, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        perror("Failed to open UART");
        return -1;
    }

    struct termios options;
    if (tcgetattr(fd, &options) == -1) {
        perror("Failed to get UART attributes");
        close(fd);
        return -1;
    }

    cfsetispeed(&options, baudrate);
    cfsetospeed(&options, baudrate);

    options.c_cflag &= ~PARENB;
    options.c_cflag &= ~CSTOPB;
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8;
    options.c_cflag &= ~CRTSCTS;
    options.c_cflag |= CREAD | CLOCAL;

    options.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    options.c_iflag &= ~(IXON | IXOFF | IXANY);
    options.c_oflag &= ~OPOST;

    options.c_cc[VMIN] = 0;
    options.c_cc[VTIME] = IBT / 100000;

    if (tcsetattr(fd, TCSANOW, &options) == -1) {
        perror("Failed to set UART attributes");
        close(fd);
        return -1;
    }

    return fd;
}

void close_uart(int fd) {
    close(fd);
}

void log_detection(const char *timestamp, float range) {
    printf("Timestamp: %s, Range: %.2f meters\n", timestamp, range);
}

int main() {
    int uart_fd = open_uart(UART_PATH, BAUDRATE);
    if (uart_fd == -1) {
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_sigint;
    sigaction(SIGINT, &sa, NULL);

    sa.sa_handler = handle_sigterm;
    sigaction(SIGTERM, &sa, NULL);

    char buffer[256];
    char *line = NULL;
    size_t line_len = 0;
    ssize_t bytes_read;

    while (running) {
        fd_set read_fds;
        FD_ZERO(&read_fds);
        FD_SET(uart_fd, &read_fds);

        struct timeval timeout;
        timeout.tv_sec = TIMEOUT;
        timeout.tv_usec = 0;

        int ret = select(uart_fd + 1, &read_fds, NULL, NULL, &timeout);
        if (ret == -1) {
            perror("Failed to select");
            break;
        } else if (ret == 0) {
            printf("No data received for %d seconds\n", TIMEOUT);
            continue;
        }

        if (FD_ISSET(uart_fd, &read_fds)) {
            bytes_read = read(uart_fd, buffer, sizeof(buffer) - 1);
            if (bytes_read == -1) {
                perror("Failed to read from UART");
                break;
            }

            buffer[bytes_read] = '\0';

            for (size_t i = 0; i < bytes_read; i++) {
                if (buffer[i] == '\n') {
                    buffer[i] = '\0';
                    if (line != NULL) {
                        char *timestamp_end = strchr(line, ',');
                        if (timestamp_end != NULL) {
                            *timestamp_end = '\0';
                            char *range_start = timestamp_end + 1;
                            char *range_end = strchr(range_start, '\0');
                            if (range_end != NULL) {
                                *range_end = '\0';
                                char *timestamp = strdup(line);
                                char *range_str = strdup(range_start);
                                if (timestamp != NULL && range_str != NULL) {
                                    float range = atof(range_str);
                                    log_detection(timestamp, range);
                                    free(timestamp);
                                    free(range_str);
                                }
                            }
                        }
                        free(line);
                    }
                    line = NULL;
                    line_len = 0;
                } else {
                    if (line_len < sizeof(buffer) - 1) {
                        line[line_len++] = buffer[i];
                    }
                }
            }
        }
    }

    close_uart(uart_fd);
    return EXIT_SUCCESS;
}

