#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_LEFT 4
#define GPIO_MIDDLE 17
#define GPIO_RIGHT 27
#define SERIAL_PORT "/dev/ttyAMA0"
#define BAUD_RATE 115200

int serial_fd = -1;

void cleanup() {
    if (serial_fd != -1) {
        close(serial_fd);
    }
    gpioTerminate();
}

void signal_handler(int signum) {
    cleanup();
    exit(signum);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    gpioSetMode(GPIO_LEFT, PI_INPUT);
    gpioSetMode(GPIO_MIDDLE, PI_INPUT);
    gpioSetMode(GPIO_RIGHT, PI_INPUT);
    gpioSetPullUpDown(GPIO_LEFT, PI_PUD_UP);
    gpioSetPullUpDown(GPIO_MIDDLE, PI_PUD_UP);
    gpioSetPullUpDown(GPIO_RIGHT, PI_PUD_UP);

    serial_fd = serialOpen(SERIAL_PORT, BAUD_RATE);
    if (serial_fd < 0) {
        fprintf(stderr, "Failed to open serial port\n");
        cleanup();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = 100 * 1000 * 1000; // 100 ms

    while (1) {
        int left = gpioRead(GPIO_LEFT);
        int middle = gpioRead(GPIO_MIDDLE);
        int right = gpioRead(GPIO_RIGHT);

        if (left == -1 || middle == -1 || right == -1) {
            fprintf(stderr, "Failed to read sensor\n");
            continue;
        }

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

        printf("%s Left: %d, Middle: %d, Right: %d\n", time_str, left, middle, right);

        if (left == 0 && middle == 0 && right == 0) {
            char *message = "EMERGENCY STOP!\n";
            if (serialWrite(serial_fd, message, strlen(message)) < 0) {
                fprintf(stderr, "Failed to write to serial port\n");
            }
        }

        nanosleep(&ts, NULL);
    }

    cleanup();
    return 0;
}

